def _apply_owner_gear_warnings_and_quality(
    run: dict[str, Any], warnings: list[Any], candidate: Mapping[str, Any],
) -> dict[str, Any]:
    """Add gear warnings and non-blocking quantity advice before quality review."""
    warnings.extend(
        {"code": "CG1_OWNER_NAMED_GEAR_UNAVAILABLE", "message": message}
        for message in dict.fromkeys(run.pop("_derived_owner_gear_warnings", []))
        if isinstance(message, str) and message.strip()
    )
    needs_review = bool(warnings)
    warnings.extend(
        {"code": "CG1_OWNER_GEAR_QUANTITY_ADVISORY", "message": message}
        for message in (run.get("request") or {}).get("owner_gear_advisories") or []
        if isinstance(message, str) and message.strip()
    )
    return {
        "schema": QUALITY_SCHEMA,
        "status": "NEEDS_REVIEW" if needs_review else "CLEAN",
        "required_receipts": sorted(candidate["preview"]["readiness"]),
        "candidate_identity": candidate["candidate_identity"],
    }
