def _authenticated_immortal_feature_action(
    feature_id: str,
    published_text: str,
    factory_root: Path,
    exact_source: Mapping[str, Any],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Derive the complete feature adapter, including authenticated dependencies."""
    from character_creation.constructed_arts.sources import published_section

    adapter = _IMMORTAL_FEATURE_SOURCE_ADAPTERS[feature_id]
    source_dependencies: list[dict[str, Any]] = []
    if adapter.get("mark_source_id"):
        mark_path = exact_source.get("factory_source_path")
        mark_source = {
            "source_id": adapter["mark_source_id"],
            "path": mark_path,
            "anchor": f"line:{adapter['mark_line_start']}",
            "source_hash": adapter["source_file_sha256"],
            "factory_source_path": mark_path,
            "source_file_sha256": adapter["source_file_sha256"],
            "line_start": adapter["mark_line_start"],
            "line_end": adapter["mark_line_end"],
            "section_sha256": adapter["mark_section_sha256"],
        }
        mark_text = published_section(factory_root, mark_source)
        if not mark_text:
            raise FoundryError(
                "CG1_IMMORTAL_ART_SOURCE_DEPENDENCY_UNAVAILABLE",
                "The common Severance Mark definition for Divide cannot be authenticated from the installed source pack.",
                details={"feature_id": feature_id, "source": mark_source},
                status_code=409,
            )
        source_dependencies.append({"purpose": "severance_mark_definition", **mark_source, "published_text": mark_text})
    if feature_id == "tianxia.tradition.spirit.dreamweaver.feature.unreality_bites_back":
        for purpose, start, end, section_hash in (
            ("dream_thread_definition", 91, 103, "2f9b49b3f50383614904b3a682c1b29f0f1dd46b6aa9382b8eb3993e62caf613"),
            ("dreamweaver_cultivation_boundary", 85, 85, "47fb0ea7bd720bc8f4f8499197655de222a099d85608c8d3b7df5f05574aff75"),
        ):
            dependency = {**exact_source, "source_id": "source.tianxia.tradition.spirit.dreamweaver." + purpose, "anchor": f"line:{start}-{end}", "line_start": start, "line_end": end, "section_sha256": section_hash}
            dependency_text = published_section(factory_root, dependency)
            if not dependency_text:
                raise FoundryError("CG1_IMMORTAL_ART_SOURCE_DEPENDENCY_UNAVAILABLE", "The selected Dreamweaver action requires its authenticated Thread definition and cultivation boundary.", details={"feature_id": feature_id, "source": dependency}, status_code=409)
            source_dependencies.append({"purpose": purpose, **dependency, "published_text": dependency_text})
    action = _immortal_feature_action(feature_id, published_text)
    if feature_id == "tianxia.tradition.spirit.dreamweaver.feature.unreality_bites_back":
        action["source_mechanics"]["dependencies"] = deepcopy(source_dependencies)
        action["limits"].extend([
            "Maintain at most PB Dream Threads, with only one of your Threads per creature; end one existing Thread when exceeding the maximum.",
            "A Thread is a spiritual state and does not reveal a hidden creature's exact location.",
            "Dreamweaver does not rewrite actual history, steal Fate's authority, permanently replace memory without explicit higher authority, or automatically affect mindless or dreamless entities.",
        ])
        action["cleanup"] += " A Dream Thread lasts for the scene, until dismissed, or until its attached Source is destroyed or leaves the plane. Dream-Confrontation during a Short or Long Rest requires at least 10 uninterrupted minutes of sleep, meditation, lucid-dream treatment, or spiritual care: the affected creature chooses a Wisdom or Charisma save against your Cultivation Save DC, once per rest unless a separate Source Rule grants another attempt. Ordinary sleep alone does not remove a Thread."
    return action, source_dependencies


def _verified_starting_proficiency_language_inputs(
    authority_service: Any,
) -> tuple[str, dict[str, str]]:
    """Read the already-declared Background source section without fallback."""
    authority_root = getattr(authority_service, "authority_root", None)
    authority_root = Path(authority_root) if isinstance(authority_root, (str, Path)) else None
    identity = getattr(authority_service, "identity", {})
    metadata = (identity.get("files") or {}).get(_CAMPAIGN_LANGUAGE_SECTION_FILE) if isinstance(identity, dict) else None
    if authority_root is None or not isinstance(metadata, dict):
        return "", {}
    source_file = authority_root / _CAMPAIGN_LANGUAGE_SECTION_FILE
    try:
        if (
            source_file.is_symlink()
            or not source_file.is_file()
            or source_file.resolve().parent != authority_root.resolve()
        ):
            return "", {}
        expected_hash = metadata.get("sha256")
        if not isinstance(expected_hash, str) or sha256_file(source_file) != expected_hash:
            return "", {}
        source_text = source_file.read_text(encoding="utf-8")
        source_path = source_file.relative_to(Path(getattr(authority_service, "root", authority_root))).as_posix()
    except (OSError, UnicodeError, ValueError):
        return "", {}
    return source_text, {"path": source_path, "source_hash": expected_hash}
