def _safe_timing_number(value: Any) -> int | float | None:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    if isinstance(value, int):
        return value if 0 <= value <= 1_000_000_000_000 else None
    number = float(value)
    if not math.isfinite(number) or number < 0 or number > 1_000_000_000_000:
        return None
    if isinstance(value, int) or number.is_integer():
        return int(number)
    return round(number, 6)


def _elapsed_ms(start: float, end: float) -> int:
    if not isinstance(start, (int, float)) or not isinstance(end, (int, float)):
        return 0
    elapsed = (float(end) - float(start)) * 1000
    if not math.isfinite(elapsed) or elapsed <= 0:
        return 0
    return round(elapsed)


_PRODUCTION_RELEASE_COMBAT_EVIDENCE_SCHEMA = (
    "TianxiaFoundry.CharacterProductionCombatEvidence.v2"
)
_PRODUCTION_RELEASE_COMBAT_RECEIPT_SECTIONS = (
    "raw_evidence_hashes",
    "semantic_projections",
    "layer_status",
    "schema_presence",
    "equalities",
)


def _production_release_combat_receipt(release: Any) -> dict[str, Any]:
    """Return the audited combat proof emitted by a production release.

    ``CharacterProductionReleaseAdapter`` owns the expensive cross-surface
    combat checks.  The creation compiler must still bind the value it records
    to that exact completed receipt, rather than invoking a second optional
    collaborator or accepting a receipt-shaped placeholder.
    """

    receipt = release.get("combat_readiness") if isinstance(release, dict) else None
    completion_proof = release.get("completion_proof") if isinstance(release, dict) else None
    proof_combat = (
        completion_proof.get("combat")
        if isinstance(completion_proof, dict)
        else None
    )
    valid = (
        isinstance(receipt, dict)
        and bool(receipt)
        and isinstance(proof_combat, dict)
        and bool(proof_combat)
        and receipt == proof_combat
        and receipt.get("schema_version") == _PRODUCTION_RELEASE_COMBAT_EVIDENCE_SCHEMA
        and receipt.get("equality") is True
        and all(
            isinstance(receipt.get(section), dict)
            for section in _PRODUCTION_RELEASE_COMBAT_RECEIPT_SECTIONS
        )
    )
    if not valid:
        raise FoundryError(
            "CG1_PRODUCTION_RELEASE_COMBAT_RECEIPT_INVALID",
            "The production release did not provide an exact audited combat receipt.",
            details={
                "release_present": isinstance(release, dict),
                "receipt_present": isinstance(receipt, dict),
                "completion_proof_present": isinstance(completion_proof, dict),
                "proof_combat_present": isinstance(proof_combat, dict),
                "receipt_equals_proof": isinstance(receipt, dict)
                and isinstance(proof_combat, dict)
                and receipt == proof_combat,
                "schema_version": receipt.get("schema_version") if isinstance(receipt, dict) else None,
                "equality": receipt.get("equality") if isinstance(receipt, dict) else None,
                "missing_sections": [
                    section
                    for section in _PRODUCTION_RELEASE_COMBAT_RECEIPT_SECTIONS
                    if not isinstance(receipt.get(section), dict)
                ]
                if isinstance(receipt, dict)
                else list(_PRODUCTION_RELEASE_COMBAT_RECEIPT_SECTIONS),
            },
            status_code=409,
        )
    return deepcopy(receipt)


def _timing_receipt(
    *,
    phases_ms: dict[str, Any] | None = None,
    provider_reported: dict[str, Any] | None = None,
) -> dict[str, Any]:
    phases: dict[str, int | float] = {}
    for key, value in (phases_ms or {}).items():
        if key not in _TIMING_PHASE_ALLOWLIST:
            continue
        safe_value = _safe_timing_number(value)
        if safe_value is not None:
            phases[key] = safe_value
    provider: dict[str, int | float] = {}
    for key in sorted(_PROVIDER_TIMING_ALLOWLIST):
        safe_value = _safe_timing_number((provider_reported or {}).get(key))
        if safe_value is not None:
            provider[key] = safe_value
    return {
        "schema": CHARACTER_CREATION_TIMING_SCHEMA,
        "phases_ms": phases,
        "provider_reported": provider,
    }


def _compile_timing_receipt(phases_ms: dict[str, Any] | None = None) -> dict[str, Any]:
    """Build the private per-compilation timing handoff.

    This is intentionally separate from ``_timing_receipt`` because the
    unprefixed phase names exist only inside one isolated compile.  The
    caller prefixes them with ``factory_compile_1.``/``factory_compile_2.``
    before merging into the persisted diagnostic receipt.
    """

    phases: dict[str, int | float] = {}
    for key, value in (phases_ms or {}).items():
        if key not in _COMPILE_TIMING_PHASE_ALLOWLIST:
            continue
        safe_value = _safe_timing_number(value)
        if safe_value is not None:
            phases[key] = safe_value
    return {
        "schema": CHARACTER_CREATION_TIMING_SCHEMA,
        "phases_ms": phases,
        "provider_reported": {},
    }


def _merge_timing_receipts(*receipts: Any) -> dict[str, Any]:
    phases: dict[str, Any] = {}
    provider_reported: dict[str, Any] = {}
    for receipt in receipts:
        if not isinstance(receipt, dict):
            continue
        source_phases = receipt.get("phases_ms")
        if isinstance(source_phases, dict):
            phases.update(source_phases)
        source_provider = receipt.get("provider_reported")
        if isinstance(source_provider, dict):
            provider_reported.update(source_provider)
    return _timing_receipt(phases_ms=phases, provider_reported=provider_reported)


def _provider_short_text(value: Any, limit: int, fallback: str = "") -> str:
    if not isinstance(value, str):
        return fallback
    text = " ".join(value.split())
    return text[:limit] if text else fallback


def _provider_choice_projection(
    row: dict[str, Any],
    *,
    cue_limit: int,
    display_limit: int,
    include_owner: bool = True,
) -> dict[str, Any]:
    """Project one compact-choice row without exposing source/mechanical data."""

    choice_id = row.get("id") if isinstance(row.get("id"), str) else ""
    category = row.get("category") if isinstance(row.get("category"), str) else "choice"
    projected = {
        "id": choice_id,
        "name": _provider_short_text(row.get("display_name"), display_limit, choice_id),
        "cue": _provider_short_text(
            row.get("semantic_cue"),
            cue_limit,
            f"{category} choice {choice_id}.",
        ),
    }
    owner = row.get("owner") if isinstance(row.get("owner"), str) else None
    if include_owner and owner:
        projected["owner"] = owner
    prerequisites = sorted({
        value for value in row.get("hard_prerequisite_ids") or [] if isinstance(value, str)
    })
    if prerequisites:
        projected["requires"] = prerequisites
    return projected


def _provider_selection_limits(envelope: dict[str, Any], slot_ids: Collection[str]) -> dict[str, dict[str, Any]]:
    raw_limits = envelope.get("selection_limits_by_slot") or {}
    if not isinstance(raw_limits, dict):
        return {}
    projected: dict[str, dict[str, Any]] = {}
    for slot_id in sorted(slot_ids):
        raw = raw_limits.get(slot_id)
        if not isinstance(raw, dict):
            continue
        projected[slot_id] = {
            key: raw.get(key)
            for key in ("owner_lock_min", "owner_lock_max", "final_min", "final_max", "allow_none")
            if key in raw
        }
    return projected


def _provider_subpath_required(
    request: dict[str, Any],
    envelope: dict[str, Any],
    target_cl: int | None,
) -> bool:
    """Read the frozen Stage 1 Subpath cardinality for the model projection.

    The complete request retains the archival Stage 1 envelope, whose slot
    cardinality is authoritative.  The delegated compatibility projection can
    only expose ``allow_none`` and therefore is used as a fallback when an old
    request has no Stage 1 slot copy.  This helper returns a boolean only; no
    choice IDs or mechanical authority are inferred here.
    """

    stage1_prompt = request.get("stage1_prompt") if isinstance(request, dict) else None
    stage1_envelope = stage1_prompt.get("envelope") if isinstance(stage1_prompt, dict) else None
    sources = (
        stage1_envelope if isinstance(stage1_envelope, dict) else None,
        envelope if isinstance(envelope, dict) else None,
    )
    for source in sources:
        slots = source.get("decision_slots") if isinstance(source, dict) else None
        if not isinstance(slots, list):
            continue
        slot = next(
            (
                row for row in slots
                if isinstance(row, dict) and row.get("slot_id") == "subpath_choice"
            ),
            None,
        )
        if isinstance(slot, dict) and type(slot.get("min_selections")) is int:
            return slot["min_selections"] > 0
    limits = envelope.get("selection_limits_by_slot") if isinstance(envelope, dict) else None
    subpath_limits = limits.get("subpath_choice") if isinstance(limits, dict) else None
    if isinstance(subpath_limits, dict) and type(subpath_limits.get("final_min")) is int:
        return subpath_limits["final_min"] > 0
    # Missing frozen metadata is an old-request compatibility case.  Preserve
    # the required behavior for unknown target levels while matching the
    # authenticated compiler's first possible Subpath selection for known ones.
    return target_cl is None or target_cl >= FIRST_PATH_SUBPATH_SELECTION_CL


def _provider_descriptive_context(envelope: dict[str, Any]) -> dict[str, dict[str, Any]]:
    delegated_fields = envelope.get("delegated_fields") or {}
    if not isinstance(delegated_fields, dict):
        delegated_fields = {}
    context: dict[str, dict[str, Any]] = {}
    active_fields = ["identity.name", "concept"]
    if isinstance(delegated_fields.get("identity.title"), dict):
        active_fields.append("identity.title")
    for field in active_fields:
        authority = delegated_fields.get(field) or {}
        authority = authority if isinstance(authority, dict) else {}
        state = "owner_locked" if authority.get("state") == "owner_locked" else "delegated"
        owner_value = authority.get("owner_value")
        if state == "owner_locked" and not isinstance(owner_value, str):
            contract_key = (
                "delegated_title_contract"
                if field == "identity.title"
                else "delegated_name_contract"
            )
            owner_value = (envelope.get(contract_key) or {}).get("owner_locked_value")
        owner_value = owner_value.strip() if isinstance(owner_value, str) and owner_value.strip() else None
        if state == "owner_locked":
            action = "Repeat the exact owner-locked value unchanged."
        elif field == "identity.name":
            action = "Assign a nonblank character name in owner_descriptive_fields.identity.name for owner review."
        elif field == "identity.title":
            action = "Assign a concise nonblank character title in owner_descriptive_fields.identity.title for owner review; do not infer it from name or concept."
        else:
            action = "Assign a concise character concept in owner_descriptive_fields.concept for owner review."
        context[field] = {
            "state": state,
            "owner_locked_value": owner_value if state == "owner_locked" else None,
            "provider_action": action,
        }
    return context


def _provider_background_ability_candidates(
    envelope: dict[str, Any],
    allowed_by_slot: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    allowed_background_ids = sorted({
        value for value in allowed_by_slot.get("background_choice") or [] if isinstance(value, str)
    })
    typed = envelope.get("typed_choice_authority_by_slot") or {}
    typed = typed if isinstance(typed, dict) else {}
    background_contract = typed.get("background_choice") or {}
    background_contract = background_contract if isinstance(background_contract, dict) else {}
    adjustments = background_contract.get("ability_adjustment_by_choice") or {}
    adjustments = adjustments if isinstance(adjustments, dict) else {}
    result: dict[str, dict[str, Any]] = {}
    for choice_id in allowed_background_ids:
        row = ((envelope.get("choices_by_slot") or {}).get("background_choice") or {}).get(choice_id) or {}
        row = row if isinstance(row, dict) else {}
        authority = choice_authority(envelope, "background_choice", choice_id, row)
        raw = adjustments.get(choice_id) or authority or {}
        raw = raw if isinstance(raw, dict) else {}
        adjustment = raw.get("ability_adjustment") if isinstance(raw.get("ability_adjustment"), dict) else raw
        if not isinstance(adjustment, dict):
            continue
        abilities = sorted({
            value for value in adjustment.get("allowed_abilities") or []
            if isinstance(value, str) and value in _PROVIDER_POINT_BUY_ABILITIES
        })
        amounts = sorted({
            value for value in (adjustment.get("allowed_amounts") or adjustment.get("amount_choices") or [])
            if type(value) is int
        })
        if abilities or amounts:
            result[choice_id] = {
                "allowed_abilities": abilities,
                "allowed_amounts": amounts,
            }
    return result


def _starting_proficiency_schema_properties(
    contract: dict[str, Any] | None,
) -> tuple[dict[str, Any], list[str]]:
    """Build exact map schemas from a frozen starting-proficiency contract."""
    if not isinstance(contract, dict) or contract.get("schema") != _STARTING_PROFICIENCY_CONTRACT_SCHEMA:
        return {}, []
    fields = contract.get("fields")
    if not isinstance(fields, dict):
        return {}, []
    properties: dict[str, Any] = {}
    required: list[str] = []
    for field in _STARTING_PROFICIENCY_FIELD_KEYS:
        spec = fields.get(field)
        # The reviewed pure authority returns the choice entries directly
        # under each field.  Accept the older service-local wrapper too so
        # retained fixtures remain readable, but never merge the two shapes.
        entries = None
        if isinstance(spec, dict):
            entries = spec.get("entries") if isinstance(spec.get("entries"), dict) else spec
        if not isinstance(entries, dict) or not entries:
            continue
        map_properties: dict[str, Any] = {}
        valid = True
        for choice_id, entry in entries.items():
            allowed_values = entry.get("allowed_values") if isinstance(entry, dict) else None
            count = entry.get("required_count") if isinstance(entry, dict) else None
            if field == "background_language_choices_by_background_id" and isinstance(entry, dict):
                count = entry.get("language_choice_count")
            # A Background can have fixed grants with no language choice.  It
            # is still part of the frozen authority, but has no response map
            # property.  A positive entry elsewhere keeps the outer map
            # advertised and independently bounded.
            if field == "background_language_choices_by_background_id" and count == 0:
                continue
            if (
                not isinstance(choice_id, str)
                or not isinstance(allowed_values, list)
                or not allowed_values
                or any(not isinstance(value, str) or not value for value in allowed_values)
                or len(set(allowed_values)) != len(allowed_values)
                or type(count) is not int
                or count < 1
                or count > len(allowed_values)
            ):
                valid = False
                break
            map_properties[choice_id] = {
                "type": "array",
                "items": {"type": "string", "enum": list(allowed_values)},
                "minItems": count,
                "maxItems": count,
                "uniqueItems": True,
            }
        if not valid or not map_properties:
            continue
        properties[field] = {
            "type": "object",
            "additionalProperties": False,
            "properties": map_properties,
        }
        required.append(field)
    return properties, required


def _provider_comparability_tags(text: str) -> list[str]:
    folded = text.casefold()
    return [
        tag
        for tag, keywords in _PROVIDER_COMPARABILITY_TAG_LEXICON
        if any(keyword.casefold() in folded for keyword in keywords)
    ][: _PROVIDER_COMPARABILITY_MAX_TAGS]


def _provider_comparability_source_text(row: dict[str, Any]) -> str:
    values = (
        row.get("display_name"),
        row.get("name"),
        row.get("canonical_name"),
        row.get("semantic_cue"),
        row.get("short_description"),
        row.get("summary"),
        row.get("description"),
    )
    return " ".join(
        " ".join(value.split())[:_PROVIDER_COMPARABILITY_MAX_PROFILE_TEXT]
        for value in values
        if isinstance(value, str) and value.strip()
    )


def _provider_comparability_owner(
    row: Any,
    *,
    include_plain_owner: bool = False,
) -> tuple[str | None, bool]:
    """Resolve one unambiguous canonical Sphere owner from frozen aliases."""

    if not isinstance(row, dict):
        return None, False
    keys = [
        "owning_canonical_sphere_id",
        "owning_sphere_id",
        "sphere_id",
    ]
    if include_plain_owner:
        keys.append("owner")
    owners = [
        value.strip()
        for key in keys
        for value in (row.get(key),)
        if isinstance(value, str) and value.strip()
    ]
    if not owners:
        return None, False
    if len(set(owners)) != 1:
        return None, True
    return owners[0], False


def _provider_comparability_sparse_cue(
    cue: str,
    sphere_name: str,
    signatures: list[dict[str, str]],
) -> bool:
    """Identify display-only cues that carry no useful comparison context."""

    normalized_cue = " ".join(cue.split()).casefold()
    normalized_name = " ".join(sphere_name.split()).casefold()
    if not normalized_cue or normalized_cue == normalized_name:
        sphere_sparse = True
    else:
        sphere_sparse = normalized_cue.startswith((
            "prerequisite:",
            "cost:",
            "action type:",
        ))
    if not sphere_sparse or not signatures:
        return False
    generic_prefixes = ("prerequisite:", "cost:", "action type:")
    return all(
        not isinstance(signature.get("cue"), str)
        or not signature["cue"].strip()
        or " ".join(signature["cue"].split()).casefold().startswith(generic_prefixes)
        for signature in signatures
    )


def _provider_comparability_display_text(
    value: Any,
    display_limit: int,
    fallback: str,
) -> str:
    """Keep compact profile names useful even when optional text contracts."""

    effective_limit = max(
        _PROVIDER_COMPARABILITY_MIN_DISPLAY_TEXT,
        min(max(display_limit, 0), 96),
    )
    return _provider_short_text(value, effective_limit, fallback)


def _provider_comparability_profile(
    envelope: dict[str, Any],
    compact_model: dict[str, Any],
    allowed_high_level: dict[str, list[dict[str, Any]]],
    *,
    target_cl: int | None,
    cue_limit: int,
    display_limit: int,
) -> dict[str, Any]:
    """Project bounded, planning-only Sphere comparison context.

    Every output ID is first selected from the current frozen allowed
    projection and every signature Talent is independently checked against its
    frozen owner and active ordinary-Talent slot.  This helper never emits
    mechanical authority and its optional row override accepts only the three
    documented planning fields.
    """

    choices_by_slot = envelope.get("choices_by_slot")
    choices_by_slot = choices_by_slot if isinstance(choices_by_slot, dict) else {}
    allowed_by_slot = envelope.get("allowed_choice_ids_by_slot")
    allowed_by_slot = allowed_by_slot if isinstance(allowed_by_slot, dict) else {}
    frozen_spheres = choices_by_slot.get("sphere_priorities")
    frozen_spheres = frozen_spheres if isinstance(frozen_spheres, dict) else {}
    frozen_talents = choices_by_slot.get("advancement_skeleton")
    frozen_talents = frozen_talents if isinstance(frozen_talents, dict) else {}
    frozen_allowed_sphere_ids = {
        value
        for value in allowed_by_slot.get("sphere_priorities") or []
        if isinstance(value, str) and value.strip()
    }
    # ``allowed_by_slot`` is the sealed closed-world set, while the compact
    # high-level projection additionally removes unavailable, above-target,
    # prerequisite-bearing, and incompatible planning rows.  Comparison
    # context must use that currently-presented intersection, never merely a
    # frozen row that happens to be allowed in another request state.
    currently_allowed_sphere_ids = {
        row.get("id")
        for row in allowed_high_level.get("sphere_priorities") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str) and row.get("id").strip()
    }
    allowed_sphere_ids = frozen_allowed_sphere_ids & currently_allowed_sphere_ids
    compact_by_slot = compact_model.get("choices_by_slot")
    compact_by_slot = compact_by_slot if isinstance(compact_by_slot, dict) else {}
    compact_sphere_rows = {
        row.get("id"): row
        for row in compact_by_slot.get("sphere_priorities") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    compact_talent_rows = {
        row.get("id"): row
        for row in compact_by_slot.get("advancement_skeleton") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    allowed_talent_ids = {
        value
        for value in allowed_by_slot.get("advancement_skeleton") or []
        if isinstance(value, str) and value.strip()
    }
    active_by_talent: dict[str, set[int]] = {}
    if type(target_cl) is int:
        for slot in compact_model.get("ordinary_talent_slots") or []:
            if not isinstance(slot, dict) or slot.get("active_for_request") is not True:
                continue
            cl = slot.get("cl")
            if type(cl) is not int or cl < 1 or cl > target_cl:
                continue
            for talent_id in slot.get("eligible_choice_ids") or []:
                if isinstance(talent_id, str) and talent_id in allowed_talent_ids:
                    active_by_talent.setdefault(talent_id, set()).add(cl)

    profiles: list[dict[str, Any]] = []
    for sphere_id in sorted(allowed_sphere_ids):
        frozen_sphere = frozen_spheres.get(sphere_id)
        compact_sphere = compact_sphere_rows.get(sphere_id)
        if not isinstance(frozen_sphere, dict) or not isinstance(compact_sphere, dict):
            continue
        authority_talents: list[dict[str, Any]] = []
        for talent_id in sorted(frozen_talents):
            if talent_id not in allowed_talent_ids:
                continue
            source_talent = frozen_talents.get(talent_id)
            compact_talent = compact_talent_rows.get(talent_id)
            if not isinstance(source_talent, dict) or not isinstance(compact_talent, dict):
                continue
            if not active_by_talent.get(talent_id):
                continue
            authority = choice_authority(
                envelope,
                "advancement_skeleton",
                talent_id,
                source_talent,
            )
            if authority.get("authority_complete") is not True:
                continue
            authoritative_owner, authority_conflict = _provider_comparability_owner(
                authority,
                include_plain_owner=True,
            )
            source_owner, source_conflict = _provider_comparability_owner(
                source_talent,
                include_plain_owner=True,
            )
            if authority_conflict or source_conflict:
                continue
            if authoritative_owner is None:
                # A direct source-row owner is accepted only after the same
                # existing frozen-authority completeness proof used by the
                # provider projection has authenticated that row.  A bare
                # display owner never creates planning authority.
                if not _provider_source_authority_complete(authority, source_talent):
                    continue
            owners = [
                owner
                for owner in (authoritative_owner, source_owner)
                if isinstance(owner, str) and owner
            ]
            if not owners or len(set(owners)) != 1:
                # A matching typed owner cannot override a conflicting frozen
                # source alias.  Keep the full alias set fail-closed.
                continue
            authoritative_owner = owners[0]
            compact_owner, compact_conflict = _provider_comparability_owner(
                compact_talent,
                include_plain_owner=True,
            )
            if (
                compact_conflict
                or authoritative_owner is None
                or compact_owner is None
                or authoritative_owner != sphere_id
                or compact_owner != sphere_id
            ):
                continue
            authority_talents.append({
                "id": talent_id,
                "name": _provider_comparability_display_text(
                    compact_talent.get("display_name"),
                    display_limit,
                    talent_id,
                ),
                "cue": _provider_short_text(
                    compact_talent.get("semantic_cue"),
                    min(max(cue_limit, 0), _PROVIDER_COMPARABILITY_MAX_PROFILE_TEXT),
                    f"Talent choice {talent_id}.",
                ),
                "active_cls": tuple(sorted(active_by_talent[talent_id])),
                "source_text": _provider_comparability_source_text(source_talent),
            })

        authority_talents.sort(key=lambda row: (
            row["active_cls"][0],
            row["active_cls"][-1],
            row["id"],
        ))
        auto_indexes = (
            0,
            (len(authority_talents) - 1) // 2,
            len(authority_talents) - 1,
        )
        auto_ids = [
            authority_talents[index]["id"]
            for index in auto_indexes
            if 0 <= index < len(authority_talents)
        ]
        raw_profile = frozen_sphere.get("ai_comparability_profile")
        raw_profile = raw_profile if isinstance(raw_profile, dict) else {}
        preferred_raw = raw_profile.get("preferred_signature_talent_ids")
        preferred_ids = sorted({
            value
            for value in preferred_raw[:_PROVIDER_COMPARABILITY_MAX_PREFERRED_IDS]
            if isinstance(value, str) and value.strip()
        }) if isinstance(preferred_raw, list) else []
        candidate_ids = {row["id"] for row in authority_talents}
        # The final hard-cap fallback strips all optional cues and display
        # names; retain one stable signature there so large legacy catalogues
        # still fit the exact byte envelope without losing every comparison
        # cue.  Normal projections retain both signatures.
        signature_limit = (
            1
            if cue_limit <= 0 and display_limit <= 0
            else _PROVIDER_COMPARABILITY_MAX_SIGNATURES
        )
        selected_ids: list[str] = [
            talent_id for talent_id in preferred_ids if talent_id in candidate_ids
        ][: signature_limit]
        for talent_id in auto_ids:
            if talent_id not in selected_ids:
                selected_ids.append(talent_id)
            if len(selected_ids) >= signature_limit:
                break
        selected_talent_rows = [
            row for row in authority_talents if row["id"] in selected_ids
        ]
        selected_talents = []
        for row in selected_talent_rows:
            projected_talent = {
                "id": row["id"],
                "name": row["name"],
            }
            if cue_limit >= _PROVIDER_COMPARABILITY_MIN_CUE_LIMIT and row["cue"]:
                projected_talent["cue"] = row["cue"]
            selected_talents.append(projected_talent)
        source_text = " ".join(
            [_provider_comparability_source_text(frozen_sphere)]
            + [row["source_text"] for row in authority_talents]
        )
        inferred_tags = _provider_comparability_tags(source_text)
        raw_tags = raw_profile.get("capability_tags")
        if isinstance(raw_tags, list):
            explicit_tags = {
                value.strip().casefold()
                for value in raw_tags
                if isinstance(value, str) and value.strip()
            }
            tags = [
                tag for tag, _keywords in _PROVIDER_COMPARABILITY_TAG_LEXICON
                if tag in explicit_tags
            ][: _PROVIDER_COMPARABILITY_MAX_TAGS]
        else:
            tags = inferred_tags
        sphere_name = _provider_comparability_display_text(
            compact_sphere.get("display_name"),
            display_limit,
            sphere_id,
        )
        default_cue_source = _provider_short_text(
            compact_sphere.get("semantic_cue"),
            _PROVIDER_COMPARABILITY_MAX_PROFILE_TEXT,
            f"Sphere {sphere_id}.",
        )
        override_cue = raw_profile.get("flavor_cue")
        if not isinstance(override_cue, str):
            override_cue = raw_profile.get("flavor")
        has_override_cue = isinstance(override_cue, str) and bool(override_cue.strip())
        flavor_source = override_cue if has_override_cue else default_cue_source
        if not has_override_cue and _provider_comparability_sparse_cue(
            default_cue_source,
            sphere_name,
            selected_talent_rows,
        ):
            representative_names = [
                signature["name"]
                for signature in selected_talent_rows
                if isinstance(signature.get("name"), str) and signature["name"].strip()
            ]
            if representative_names:
                flavor_source = "Representative arts: " + "; ".join(representative_names) + "."
        flavor_cue = (
            _provider_short_text(
                flavor_source,
                min(max(cue_limit, 0), _PROVIDER_COMPARABILITY_MAX_PROFILE_TEXT),
                "",
            )
            if cue_limit >= _PROVIDER_COMPARABILITY_MIN_CUE_LIMIT
            else ""
        )
        profile = {
            "sphere_id": sphere_id,
            "name": sphere_name,
            "capability_tags": tags,
            "signature_talents": selected_talents,
        }
        if flavor_cue:
            profile["flavor_cue"] = flavor_cue
        profiles.append(profile)
    return {
        "schema": "TianxiaFoundry.SphereComparabilityIndex.v1",
        "version": 1,
        "origin": "frozen_delegated_choice_envelope",
        "mechanical_authority": False,
        "target_cl": target_cl,
        "profiles": profiles,
    }


def _provider_progression_cues(envelope: dict[str, Any], target_cl: int | None, cue_limit: int) -> dict[str, list[dict[str, Any]]]:
    milestones: list[dict[str, Any]] = []
    for row in envelope.get("advancement_choice_milestones") or []:
        if not isinstance(row, dict) or not isinstance(row.get("milestone_id"), str):
            continue
        cl = row.get("cl")
        if type(cl) is int and target_cl is not None and cl > target_cl:
            continue
        projected = {
            "milestone_id": row["milestone_id"],
            "path_id": row.get("path_id") if isinstance(row.get("path_id"), str) else None,
            "feature_record_id": row.get("feature_record_id") if isinstance(row.get("feature_record_id"), str) else None,
            "cl": cl if type(cl) is int else None,
            "allowed_kinds": sorted({value for value in row.get("allowed_kinds") or [] if isinstance(value, str)}),
        }
        milestones.append(projected)
    progression: list[dict[str, Any]] = []
    for row in envelope.get("path_progression_choices") or []:
        if not isinstance(row, dict):
            continue
        cl = row.get("cl")
        if type(cl) is not int or (target_cl is not None and cl > target_cl):
            continue
        path_ids = sorted({value for value in row.get("path_ids") or [] if isinstance(value, str)})
        if not path_ids:
            continue
        progression.append({
            "cl": cl,
            "path_ids": path_ids,
            "semantic_cue": _provider_short_text(
                row.get("semantic_cue") or row.get("description"),
                cue_limit,
                "Choose a presented Path ID when more than one Path can progress at this CL.",
            ),
        })
    return {
        "advancement_choice_milestones": sorted(milestones, key=lambda row: (row.get("cl") is None, row.get("cl") or 0, row["milestone_id"])),
        "path_progression_choices": sorted(progression, key=lambda row: (row["cl"], tuple(row["path_ids"]))),
    }


def _bind_path_feature_ability_change_rules(
    envelope: dict[str, Any],
    authority: NonSphereAuthorityService,
) -> None:
    """Bind each real Advancement Choice row to its authenticated Path rule.

    Stage 1's compact milestone rows intentionally carry identifiers and
    applicability only.  Before the request is sealed, resolve each
    ability-score row through the authenticated Non-Sphere Path projection and
    copy the exact typed rule plus minimal source evidence into that row.  A
    missing or malformed projection is a request-construction failure; the
    provider projection must never fill it with a generic ASI policy.
    """

    rows = envelope.get("advancement_choice_milestones")
    if not isinstance(rows, list):
        return
    feature_cache: dict[tuple[str, str], dict[str, Any]] = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        allowed_kinds = row.get("allowed_kinds")
        if not isinstance(allowed_kinds, list) or "ability_score_change" not in allowed_kinds:
            continue
        path_id = row.get("path_id")
        feature_id = row.get("feature_record_id")
        milestone_id = row.get("milestone_id")
        cl = row.get("cl")
        if not all(isinstance(value, str) and value.strip() for value in (path_id, feature_id, milestone_id)):
            raise FoundryError(
                "CG1_ADVANCEMENT_CHOICE_AUTHORITY_MISSING",
                "An Advancement Choice milestone is missing its authenticated Path feature binding.",
                details={"milestone_id": milestone_id, "path_id": path_id, "feature_record_id": feature_id},
                status_code=503,
            )
        cache_key = (path_id, feature_id)
        if cache_key not in feature_cache:
            try:
                feature_cache[cache_key] = authority.project_locked_path_feature_catalog_record(
                    path_id,
                    feature_id,
                )
            except FoundryError as exc:
                raise FoundryError(
                    "CG1_ADVANCEMENT_CHOICE_AUTHORITY_MISSING",
                    "The Advancement Choice milestone is not backed by an authenticated Path feature rule.",
                    details={
                        "milestone_id": milestone_id,
                        "path_id": path_id,
                        "feature_record_id": feature_id,
                        "source_error": exc.code,
                    },
                    status_code=503,
                ) from exc
        feature = feature_cache[cache_key]
        stage2_authority = (
            (feature.get("compatibility") or {})
            .get("factory", {})
            .get("stage2_authority")
            or {}
        )
        rule = stage2_authority.get("ability_change")
        granted_cls = rule.get("allowed_cls") if isinstance(rule, dict) else None
        granted_deltas = rule.get("allowed_deltas") if isinstance(rule, dict) else None
        rule_budget = rule.get("budget") if isinstance(rule, dict) else None
        rule_cap = rule.get("cap") if isinstance(rule, dict) else None
        authority_channels = stage2_authority.get("allowed_channels")
        source = feature.get("source")
        if (
            stage2_authority.get("authority_complete") is not True
            or stage2_authority.get("feature_kind") != "advancement_choice"
            or "ability_score_change" not in (stage2_authority.get("allowed_kinds") or [])
            or not isinstance(authority_channels, list)
            or "level-choice" not in authority_channels
            or not isinstance(rule, dict)
            or not isinstance(granted_cls, list)
            or any(type(value) is not int for value in granted_cls)
            or not granted_cls
            or not isinstance(granted_deltas, list)
            or any(type(value) is not int or value <= 0 for value in granted_deltas)
            or not granted_deltas
            or type(rule_budget) is not int
            or rule_budget <= 0
            or type(rule_cap) is not int
            or rule_cap <= 0
            or type(cl) is not int
            or cl not in granted_cls
            or not isinstance(source, dict)
            or not isinstance(source.get("path"), str)
            or not isinstance(source.get("source_hash"), str)
            or len(source.get("source_hash")) != 64
            or not isinstance(stage2_authority.get("rule_id"), str)
        ):
            raise FoundryError(
                "CG1_ADVANCEMENT_CHOICE_AUTHORITY_INVALID",
                "The authenticated Path feature does not expose an exact legal Advancement Choice rule for this milestone.",
                details={
                    "milestone_id": milestone_id,
                    "path_id": path_id,
                    "feature_record_id": feature_id,
                    "cl": cl,
                    "allowed_cls": granted_cls,
                },
                status_code=503,
            )
        row["ability_change"] = deepcopy(rule)
        row["ability_change_source"] = {
            "authority": "authenticated_non_sphere_path_feature",
            "rule_id": stage2_authority.get("rule_id"),
            "source": deepcopy(source),
        }


def _provider_milestone_resolution_contract(
    envelope: dict[str, Any],
    milestones: Collection[dict[str, Any]],
    *,
    presented_insight_ids: Collection[str],
) -> dict[str, dict[str, Any]]:
    """Project the complete, typed milestone decision map for the provider.

    The delegated envelope is authoritative, but its milestone rows are kept
    deliberately small because they are also used by the response validator.
    The model-facing projection therefore publishes the missing *decision
    shape* here: which path makes a milestone applicable, which destination
    resolves it, and the source-backed constraints for each destination.  No
    choice is preselected.  In particular, an Insight is offered only when its
    frozen typed authority is legal at that milestone's CL; an omitted/empty
    resolution still fails at the normal materialization boundary.

    The request builder binds each real ASI row to the exact
    ``ability_change`` mapping returned by the authenticated Non-Sphere Path
    projection.  This helper only projects that frozen mapping; it never fills
    missing fields from a generic point-buy policy, live catalog, or prose.
    """

    typed_authority = envelope.get("typed_choice_authority_by_slot")
    typed_authority = typed_authority if isinstance(typed_authority, dict) else {}
    insight_authority_section = typed_authority.get("insight_priorities")
    insight_authority_section = (
        insight_authority_section if isinstance(insight_authority_section, dict) else {}
    )
    insight_authority_by_id = insight_authority_section.get("stage2_authority_by_choice")
    insight_authority_by_id = (
        insight_authority_by_id if isinstance(insight_authority_by_id, dict) else {}
    )
    choices_by_slot = envelope.get("choices_by_slot")
    choices_by_slot = choices_by_slot if isinstance(choices_by_slot, dict) else {}
    insight_rows = choices_by_slot.get("insight_priorities")
    insight_rows = insight_rows if isinstance(insight_rows, dict) else {}
    candidate_insight_ids = sorted({
        value for value in presented_insight_ids
        if isinstance(value, str) and value.strip()
    })

    def typed_insight_authority(insight_id: str) -> dict[str, Any] | None:
        authority = insight_authority_by_id.get(insight_id)
        if not isinstance(authority, dict):
            row = insight_rows.get(insight_id)
            authority = row.get("stage2_authority") if isinstance(row, dict) else None
        if not isinstance(authority, dict):
            row = insight_rows.get(insight_id)
            authority = (
                (row.get("compatibility") or {}).get("factory", {}).get("stage2_authority")
                if isinstance(row, dict)
                else None
            )
        return authority if isinstance(authority, dict) else None

    def positive_ints(value: Any) -> list[int]:
        return sorted({item for item in value or [] if type(item) is int and item > 0}) if isinstance(value, list) else []

    def projected_ability_change(milestone: dict[str, Any]) -> dict[str, Any] | None:
        raw = milestone.get("ability_change") or milestone.get("ability_score_change")
        if not isinstance(raw, dict):
            return None
        allowed_abilities = sorted({
            value for value in raw.get("allowed_abilities") or []
            if isinstance(value, str) and value.strip()
        })
        allowed_deltas = positive_ints(raw.get("allowed_deltas"))
        budget = raw.get("budget") if type(raw.get("budget")) is int else None
        cap = raw.get("cap") if type(raw.get("cap")) is int else None
        allowed_cls = positive_ints(raw.get("allowed_cls"))
        source = milestone.get("ability_change_source")
        raw_source = source.get("source") if isinstance(source, dict) else None
        if (
            not allowed_deltas
            or budget is None
            or budget <= 0
            or cap is None
            or cap <= 0
            or not isinstance(source, dict)
            or source.get("authority") != "authenticated_non_sphere_path_feature"
            or not isinstance(source.get("rule_id"), str)
            or not isinstance(raw_source, dict)
            or not isinstance(raw_source.get("path"), str)
            or not isinstance(raw_source.get("source_hash"), str)
            or len(raw_source.get("source_hash")) != 64
        ):
            return None
        constraints: dict[str, Any] = {
            "allowed_deltas": allowed_deltas,
            "budget": budget,
            "cap": cap,
        }
        if allowed_cls:
            constraints["allowed_cls"] = allowed_cls
        if allowed_abilities:
            constraints["allowed_abilities"] = allowed_abilities
        source_projection = {
            key: deepcopy(source[key])
            for key in ("authority", "rule_id")
            if key in source
        }
        source_projection["source"] = {
            key: deepcopy(raw_source[key])
            for key in ("source_id", "path", "anchor", "source_hash")
            if key in raw_source
        }
        constraints["source"] = source_projection
        return constraints

    result: dict[str, dict[str, Any]] = {}
    for raw_milestone in milestones:
        if not isinstance(raw_milestone, dict):
            continue
        milestone_id = raw_milestone.get("milestone_id")
        path_id = raw_milestone.get("path_id")
        if not isinstance(milestone_id, str) or not milestone_id.strip():
            continue
        if not isinstance(path_id, str) or not path_id.strip():
            continue
        cl = raw_milestone.get("cl")
        milestone_allowed_kinds = sorted({
            value for value in raw_milestone.get("allowed_kinds") or []
            if isinstance(value, str) and value.strip()
        })
        options: dict[str, Any] = {}
        if "ability_score_change" in milestone_allowed_kinds:
            constraints = projected_ability_change(raw_milestone)
            if constraints is not None:
                options["ability_score_change"] = {
                    "destination": (
                        "bounded_choices.ability_score_changes_by_milestone_id." + milestone_id
                    ),
                    "constraints": constraints,
                }
        if "cultivation_insight_acquisition" in milestone_allowed_kinds:
            allowed_insights: list[str] = []
            parameters_by_insight: dict[str, dict[str, Any]] = {}
            for insight_id in candidate_insight_ids:
                authority = typed_insight_authority(insight_id)
                if not isinstance(authority, dict):
                    continue
                if authority.get("authority_complete") is not True:
                    continue
                authority_allowed_kinds = authority.get("allowed_kinds")
                if (
                    not isinstance(authority_allowed_kinds, list)
                    or "cultivation_insight_acquisition" not in authority_allowed_kinds
                ):
                    continue
                allowed_channels = authority.get("allowed_channels")
                if (
                    not isinstance(allowed_channels, list)
                    or "cultivation-insight-selection" not in allowed_channels
                ):
                    continue
                allowed_cls = authority.get("allowed_cls") or authority.get("allowed_effective_cls")
                if (
                    not isinstance(allowed_cls, list)
                    or any(type(value) is not int or value < 1 for value in allowed_cls)
                    or type(cl) is not int
                    or cl not in allowed_cls
                ):
                    continue
                rule = authority.get("ability_change") or authority.get("insight_ability_change")
                rule_abilities = rule.get("allowed_abilities") if isinstance(rule, dict) else None
                rule_amount = rule.get("amount") if isinstance(rule, dict) else None
                if (
                    not isinstance(rule, dict)
                    or not isinstance(rule_abilities, list)
                    or not rule_abilities
                    or any(not isinstance(value, str) or not value.strip() for value in rule_abilities)
                    or type(rule_amount) is not int
                    or rule_amount <= 0
                ):
                    continue
                allowed_insights.append(insight_id)
                parameters: dict[str, Any] = {
                    "allowed_abilities": sorted({
                        value for value in rule.get("allowed_abilities") or []
                        if isinstance(value, str) and value.strip()
                    }),
                }
                amount = rule.get("amount")
                if type(amount) is int:
                    parameters["amount"] = amount
                parameters_by_insight[insight_id] = parameters
            # An empty Insight enum is not a legal provider option.  Omitting
            # it makes a source-backed ASI the sole visible destination (or
            # leaves the row explicitly blocked when no destination exists),
            # instead of asking the model to choose an impossible kind.
            if allowed_insights:
                options["cultivation_insight_acquisition"] = {
                    "destination": "acquisition_intent.insight_occurrences[]",
                    "allowed_insight_ids": allowed_insights,
                    "parameters_by_insight_id": parameters_by_insight,
                }
        if not options:
            # Retain an explicit impossible/blocked entry rather than letting
            # a missing map entry look like an unadvertised free choice.
            options = {"blocked": {"reason": "NO_SOURCE_BACKED_RESOLUTION"}}
        result[milestone_id] = {
            "milestone_id": milestone_id,
            "path_id": path_id,
            "cl": cl if type(cl) is int else None,
            "feature_record_id": (
                raw_milestone.get("feature_record_id")
                if isinstance(raw_milestone.get("feature_record_id"), str)
                else None
            ),
            "applicable_when": {
                "selection_intent.by_slot.path_choice_contains": path_id,
            },
            "allowed_kinds": milestone_allowed_kinds,
            "resolution_options": options,
            "resolution_cardinality": "exactly_one",
        }
    return dict(sorted(result.items()))


def _provider_ordinary_shortlist(
    compact_model: dict[str, Any],
    *,
    target_cl: int | None,
    cue_limit: int,
    display_limit: int,
    required_ids: Collection[str] | None = None,
) -> dict[str, list[dict[str, Any]]]:
    ordinary_rows = ((compact_model.get("choices_by_slot") or {}).get("advancement_skeleton") or [])
    ordinary_rows = ordinary_rows if isinstance(ordinary_rows, list) else []
    rows_by_id = {
        row.get("id"): row
        for row in ordinary_rows
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    active_positions: dict[str, list[int]] = {}
    for row in compact_model.get("ordinary_talent_slots") or []:
        if not isinstance(row, dict) or not row.get("active_for_request"):
            continue
        cl = row.get("cl")
        if type(cl) is not int or (target_cl is not None and cl > target_cl):
            continue
        for choice_id in row.get("eligible_choice_ids") or []:
            if isinstance(choice_id, str):
                active_positions.setdefault(choice_id, []).append(cl)
    grouped: dict[str, list[str]] = {}
    for choice_id, positions in active_positions.items():
        row = rows_by_id.get(choice_id)
        if not isinstance(row, dict):
            continue
        owner = row.get("owner") if isinstance(row.get("owner"), str) and row.get("owner") else "unassigned"
        grouped.setdefault(owner, []).append(choice_id)

    shortlist: dict[str, list[dict[str, Any]]] = {}
    required_ids = {value for value in (required_ids or ()) if isinstance(value, str)}
    for owner in sorted(grouped):
        choice_ids = sorted(
            grouped[owner],
            key=lambda choice_id: (
                bool(rows_by_id[choice_id].get("hard_prerequisite_ids")),
                rows_by_id[choice_id].get("minimum_cl") if type(rows_by_id[choice_id].get("minimum_cl")) is int else 999,
                -len(active_positions.get(choice_id) or []),
                choice_id,
            ),
        )
        # Preserve a source-locked first-cycle free-Talent candidate in the
        # compact presentation even when its stable ID would otherwise fall
        # below the ordinary balanced shortlist.  This does not broaden the
        # frozen envelope; it only makes the legal illustrative pair visible.
        required_for_owner = [choice_id for choice_id in choice_ids if choice_id in required_ids]
        ordinary_for_owner = [choice_id for choice_id in choice_ids if choice_id not in required_ids]
        # A selected first-cycle free Talent is not also an ordinary per-CL
        # Talent.  Keep the required free row in addition to (rather than in
        # place of) the balanced ordinary shortlist, or a copied provider
        # template can become one ordinary choice short for every acquired
        # Sphere.
        choice_ids = required_for_owner + ordinary_for_owner[:_PROVIDER_SHORTLIST_PER_SPHERE]
        shortlisted: list[dict[str, Any]] = []
        for choice_id in choice_ids:
            projected = _provider_choice_projection(
                rows_by_id[choice_id],
                cue_limit=cue_limit,
                display_limit=display_limit,
                include_owner=False,
            )
            projected["eligible_cl"] = sorted(set(active_positions.get(choice_id) or []))
            shortlisted.append(projected)
        if shortlisted:
            shortlist[owner] = shortlisted
    return shortlist


def _provider_locked_grant_accounting(request: dict[str, Any]) -> dict[str, Any]:
    """Project only the frozen initial grant accounting needed by the prompt.

    The complete request remains the authority.  The typed choice snapshot is
    the frozen route binding; its semantic catalog-grant lock takes precedence
    over older compatibility locks.  The Stage 1 envelope is retained as a
    compatibility source for older requests.  We resolve by lock field rather
    than list position because a snapshot can contain an unrelated empty grant
    accounting before the first-cycle plan.  Only the accounting projection is
    returned; the lock itself never enters the model-facing payload.
    """

    prompt = request.get("stage1_prompt") if isinstance(request, dict) else None
    envelope = prompt.get("envelope") if isinstance(prompt, dict) else None
    stage1_locks = envelope.get("user_locks") if isinstance(envelope, dict) else None
    if not isinstance(stage1_locks, list):
        stage1_locks = []
    snapshot = request.get("typed_choice_snapshot") if isinstance(request, dict) else None
    typed_locks = snapshot.get("typed_locks") if isinstance(snapshot, dict) else None
    if not isinstance(typed_locks, list):
        typed_locks = []
    fields = (
        DELEGATED_FINAL_CATALOG_GRANT_FIELD,
        COMMITTED_CATALOG_CHOICE_FIELD,
        "character_sheet.canonical_grant_plan",
    )
    for field in fields:
        # The snapshot is the actual frozen authority.  Reverse iteration
        # mirrors the project lock map's last-value-wins compatibility rule
        # when malformed/legacy requests contain duplicate fields.
        for locks in (typed_locks, stage1_locks):
            for lock in reversed(locks):
                if not isinstance(lock, dict) or lock.get("field") != field:
                    continue
                value = lock.get("value")
                if not isinstance(value, dict):
                    continue
                accounting = value.get("grant_accounting")
                if isinstance(accounting, dict):
                    return deepcopy(accounting)
    return {}


def _provider_catalog_grant_origin(request: dict[str, Any]) -> str | None:
    """Return a positively marked creator projection origin, if frozen.

    Historical requests do not carry this marker and therefore remain
    fail-closed.  In particular, an unmarked empty zero grant plan is never
    reinterpreted as an AI-bootstrap compatibility placeholder.
    """

    prompt = request.get("stage1_prompt") if isinstance(request, dict) else None
    envelope = prompt.get("envelope") if isinstance(prompt, dict) else None
    stage1_locks = envelope.get("user_locks") if isinstance(envelope, dict) else None
    if not isinstance(stage1_locks, list):
        stage1_locks = []
    snapshot = request.get("typed_choice_snapshot") if isinstance(request, dict) else None
    typed_locks = snapshot.get("typed_locks") if isinstance(snapshot, dict) else None
    if not isinstance(typed_locks, list):
        typed_locks = []
    for locks in (typed_locks, stage1_locks):
        for lock in reversed(locks):
            if not isinstance(lock, dict) or lock.get("field") != CATALOG_GRANT_ORIGIN_FIELD:
                continue
            value = lock.get("value")
            return value if isinstance(value, str) else None
    return None


def _provider_free_talent_kind(request: dict[str, Any]) -> str:
    prompt = request.get("stage1_prompt") if isinstance(request, dict) else None
    envelope = prompt.get("envelope") if isinstance(prompt, dict) else None
    locks = envelope.get("user_locks") if isinstance(envelope, dict) else None
    if isinstance(locks, list):
        for lock in locks:
            if isinstance(lock, dict) and lock.get("field") == "character_sheet.generation_route":
                return (
                    "ai_bootstrap_talent_acquisition"
                    if lock.get("value") == "ai_bootstrap"
                    else "sect_trial_talent_acquisition"
                )
    return "sect_trial_talent_acquisition"


def _provider_free_sphere_kind(request: dict[str, Any]) -> str:
    """Return the frozen route-specific Sphere kind paired with free Talent."""

    return (
        "ai_bootstrap_sphere_acquisition"
        if _provider_free_talent_kind(request) == "ai_bootstrap_talent_acquisition"
        else "sect_trial_sphere_acquisition"
    )


def _provider_stage2_allowed_kinds(
    authority: dict[str, Any],
    source_row: dict[str, Any],
) -> set[str]:
    """Project route kinds from sealed typed authority or its source channels.

    Older frozen Stage 1 envelopes retain canonical Sphere rows and their
    acquisition channels but omit the later typed ``allowed_kinds`` block.
    Preserve the same bounded source-backed authority for those rows; a
    background-only channel never becomes a route grant.
    """

    direct = {
        value
        for value in (
            list(authority.get("allowed_kinds") or [])
            + list(source_row.get("allowed_kinds") or [])
        )
        if isinstance(value, str) and value.strip()
    }
    if direct:
        return direct
    channels = {
        value
        for value in (
            list(authority.get("allowed_channels") or [])
            + list(source_row.get("acquisition_channels") or [])
        )
        if isinstance(value, str) and value.strip()
    }
    channel_kinds = {
        "ai-bootstrap-free-cl1-sphere": "ai_bootstrap_sphere_acquisition",
        "sect-trial-cl1-sphere": "sect_trial_sphere_acquisition",
        "ai-bootstrap-free-cl1-talent": "ai_bootstrap_talent_acquisition",
        "sect-trial-cl1-level-talent": "sect_trial_talent_acquisition",
    }
    inferred = {
        channel_kinds[channel]
        for channel in channels
        if channel in channel_kinds
    }
    # The generic canonical Sphere acquisition channel is the source-backed
    # selectable Sphere surface in older envelopes.  Route selection still
    # chooses the concrete kind; a background-grant row has no such fallback.
    if "sphere-acquisition" in channels:
        inferred.update({
            "ai_bootstrap_sphere_acquisition",
            "sect_trial_sphere_acquisition",
        })
    if "sect-trial" in channels:
        inferred.add("sect_trial_sphere_acquisition")
    return inferred


def _provider_source_authority_complete(
    authority: dict[str, Any],
    source_row: dict[str, Any],
) -> bool:
    return authority.get("authority_complete") is True or (
        isinstance(source_row.get("content_binding"), dict)
        and source_row.get("authority") == "canonical"
        and source_row.get("publication_state") == "published"
    )


def _provider_combat_ready_requested(request: dict[str, Any]) -> bool:
    """Return the server-owned combat presentation target, when present.

    This is intentionally a presentation-only read.  Complete-request
    validation authenticates the full target before provider work starts; the
    strict identity/schema check here keeps malformed test/legacy inputs from
    accidentally opting into the combat route policy while still preserving
    the historical absent-target behavior.
    """

    authority = request.get("server_owned_authority") if isinstance(request, dict) else None
    target = authority.get("output_profile") if isinstance(authority, dict) else None
    return isinstance(target, dict) and target.get("combat_ready") is True


# The provider step key for one creation run.  It is scoped to the run, so two
# distinct runs whose complete-request bytes happen to be identical never share
# a provider run, an agent mailbox request, or a receipt.  The request bytes are
# included so changed bytes for the same run fail closed instead of reusing a
# recorded receipt.
CREATION_PROVIDER_STEP_PURPOSE = "character_creation_complete_plan"


def _creation_provider_step_key(run_id: str, request_sha256: Any) -> str:
    return "prp." + sha256_json(
        {
            "purpose": CREATION_PROVIDER_STEP_PURPOSE,
            "run_id": str(run_id),
            "request_sha256": str(request_sha256 or ""),
        }
    )


# A mailbox row in one of these states still belongs to unfinished provider
# work: PENDING/CLAIMED mean the agent has not answered yet, and ANSWERED means
# the answer landed after the caller stopped waiting and is waiting to be
# consumed by the resumed step.
RESUMABLE_AGENT_REQUEST_STATES = {"PENDING", "CLAIMED", "ANSWERED"}


def settings_provider_id(run: Mapping[str, Any]) -> str | None:
    """The provider profile recorded on the run's persisted selection, if any."""

    for key in ("provider_id",):
        value = run.get(key)
        if isinstance(value, str) and value:
            return value
    transport = run.get("transport")
    if isinstance(transport, Mapping):
        for key in ("provider_id", "selected_provider_id"):
            value = transport.get(key)
            if isinstance(value, str) and value:
                return value
    return None


def _open_agent_step_request(provider: Any, *, step_key: str) -> dict[str, Any] | None:
    """Return the resumable agent bridge request for one creation step, if any.

    ``None`` whenever the selected provider is not the agent bridge or the
    mailbox holds no resumable row for this exact step key.
    """

    bridge = getattr(provider, "agent_bridge", None)
    find_latest = getattr(bridge, "find_latest", None)
    if not callable(find_latest):
        return None
    try:
        latest = find_latest(
            provider_id="agent",
            prompt_id=CREATION_PROVIDER_STEP_PURPOSE,
            idempotency_key=step_key,
        )
    except FoundryError:
        return None
    if not isinstance(latest, dict):
        return None
    if latest.get("state") not in RESUMABLE_AGENT_REQUEST_STATES:
        return None
    return latest


def _provider_frozen_talent_dispositions(request: dict[str, Any]) -> dict[str, dict[str, Any] | None]:
    """Index full Talent descriptions from the sealed typed snapshot.

    The compact envelope deliberately carries only a short presentation cue.
    A combat-ready eligibility decision must therefore use the frozen typed
    grant projection.  Duplicate canonical IDs are represented by ``None`` so
    callers fail closed instead of selecting one by list order.
    """

    snapshot = request.get("typed_choice_snapshot") if isinstance(request, dict) else None
    locks = snapshot.get("typed_locks") if isinstance(snapshot, dict) else None
    if not isinstance(locks, list):
        return {}
    indexed: dict[str, dict[str, Any] | None] = {}
    for lock in locks:
        value = lock.get("value") if isinstance(lock, dict) else None
        rows = value.get("talent_dispositions") if isinstance(value, dict) else None
        if not isinstance(rows, list):
            continue
        for disposition in rows:
            if not isinstance(disposition, dict):
                continue
            talent_id = disposition.get("canonical_talent_id")
            if not isinstance(talent_id, str) or not talent_id.strip():
                continue
            if talent_id in indexed:
                indexed[talent_id] = None
            else:
                indexed[talent_id] = disposition
    return indexed


def _provider_bound_talent_disposition(
    choice_id: str,
    compact_row: dict[str, Any],
    source_row: dict[str, Any],
    authority: dict[str, Any],
    dispositions: dict[str, dict[str, Any] | None],
) -> dict[str, Any] | None:
    """Return one disposition only when its source identity binds exactly."""

    disposition = dispositions.get(choice_id)
    if not isinstance(disposition, dict):
        return None
    if disposition.get("canonical_talent_id") != choice_id:
        return None
    for row in (compact_row, source_row):
        row_id = row.get("id") or row.get("choice_id")
        if row_id is not None and row_id != choice_id:
            return None

    explicit_owners = [
        value
        for value in (
            compact_row.get("owner"),
            authority.get("owning_canonical_sphere_id"),
            authority.get("owning_sphere_id"),
            authority.get("sphere_id"),
            source_row.get("owner"),
        )
        if isinstance(value, str) and value.strip()
    ]
    if not explicit_owners or len(set(explicit_owners)) != 1:
        return None
    if disposition.get("owning_canonical_sphere_id") != explicit_owners[0]:
        return None

    source = source_row.get("source")
    source_reference = disposition.get("source_reference")
    if not isinstance(source, dict) or not isinstance(source_reference, dict):
        return None
    source_anchor = source.get("anchor")
    source_path = source.get("path")
    source_hash = source.get("source_hash")
    if (
        not isinstance(source_anchor, str)
        or not source_anchor.strip()
        or not isinstance(source_path, str)
        or not source_path.strip()
        or not isinstance(source_hash, str)
        or len(source_hash) != 64
        or any(character not in "0123456789abcdef" for character in source_hash)
        or source_reference.get("source_anchor") != source_anchor
        or source_reference.get("source_path") != source_path
        or source_reference.get("source_file_sha256") != source_hash
    ):
        return None

    source_name = source_row.get("name") or source_row.get("display_name")
    frozen_name = disposition.get("display_name")
    if (
        not isinstance(source_name, str)
        or not source_name.strip()
        or not isinstance(frozen_name, str)
        or " ".join(source_name.split()).casefold() != " ".join(frozen_name.split()).casefold()
    ):
        return None
    return disposition


def _provider_combat_action_type(value: Any) -> tuple[bool, str | None]:
    """Return whether text has one unambiguous supported action label.

    The label is intentionally line-anchored.  A prose mention of an Action
    must not turn a non-action Talent into a combat route, while conflicting
    Action/Reaction labels fail closed rather than selecting one by order.
    """

    if not isinstance(value, str):
        return False, None
    normalized_types: list[str] = []
    for line in value.splitlines():
        match = _PROVIDER_COMBAT_ACTION_LABEL_RE.fullmatch(line.strip())
        if match is None:
            continue
        normalized = " ".join(match.group("action_type").split()).casefold()
        normalized_types.append(normalized)
    if not normalized_types:
        return False, None
    if len(set(normalized_types)) != 1:
        return True, None
    return True, {
        "action": "Action",
        "bonus action": "Bonus Action",
        "reaction": "Reaction",
    }.get(normalized_types[0])


def _provider_explicit_combat_action_text(value: Any) -> bool:
    return _provider_combat_action_type(value)[0]


def _provider_complete_action_resource_projection(
    description: Any,
    *,
    expected_action_type: str,
    record_id: str,
    display_name: Any,
) -> bool:
    """Recognize only the strict standalone-cost Command 4 grammar.

    This intentionally remains a local pure predicate.  Importing the
    ``factory_authoring`` package here initializes its service facade and
    creates a character-sheet/projector import cycle.  The grammar mirrors
    Command 4's source projection: one non-contextual Cost line, explicit
    ``None``, or one/two distinct positive typed resource clauses.  The
    returned transaction shape is server-owned and therefore includes the
    same timing/condition commitments as the executable projection.
    """

    del record_id, display_name
    if not isinstance(description, str) or not description.strip():
        return False
    action_label_present, parsed_action_type = _provider_combat_action_type(description)
    if not action_label_present or parsed_action_type != expected_action_type:
        return False

    action_cost_values: list[str] = []
    context: str | None = None
    for raw_line in description.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        inline_context = _PROVIDER_INLINE_COST_CONTEXT_RE.fullmatch(line)
        if inline_context is not None:
            context = None
            continue
        context_match = _PROVIDER_COST_CONTEXT_LABEL_RE.fullmatch(line)
        if context_match is not None:
            context = line.casefold()
            continue
        cost_match = _PROVIDER_COST_LABEL_RE.fullmatch(line)
        if cost_match is not None:
            value = cost_match.group("value").strip()
            if context is None:
                action_cost_values.append(value)
            context = None
            continue
        # Ingredient/Refinement context applies only to the immediately next
        # labelled Cost line; prose cannot inherit recipe cost authority.
        context = None

    if len(action_cost_values) != 1:
        return False
    value = action_cost_values[0].strip().casefold().rstrip(".")
    if not value:
        return False
    if value in _PROVIDER_NONE_COST_VALUES:
        return True

    clauses = [part.strip() for part in re.split(r"\s+and\s+", value, flags=re.IGNORECASE)]
    if not 1 <= len(clauses) <= 2:
        return False
    parsed_ids: list[str] = []
    for clause in clauses:
        match = _PROVIDER_RESOURCE_CLAUSE_RE.fullmatch(clause.rstrip("."))
        if match is None:
            return False
        amount_text = match.group("amount").casefold()
        amount = int(amount_text) if amount_text.isdigit() else 1
        if amount <= 0:
            return False
        resource = match.group("resource").strip()
        normalized = " ".join(resource.casefold().replace("_", " ").replace("-", " ").split())
        resource_id = _PROVIDER_RESOURCE_ID_ALIASES.get(normalized)
        if resource_id is None:
            slug = re.sub(r"[^A-Z0-9]+", "_", normalized.upper()).strip("_")
            resource_id = f"RES_{slug}"
        parsed_ids.append(resource_id)

    if len(set(parsed_ids)) != len(parsed_ids):
        return False
    # Keep these explicit so a future caller cannot accidentally treat the
    # source amount/resource grammar as executable without its transaction
    # timing and condition semantics.
    return bool(_PROVIDER_RESOURCE_COST_TIMING and _PROVIDER_RESOURCE_COST_CONDITION)


def _provider_combat_ready_free_talent_allowed(
    request: dict[str, Any],
    compact_row: dict[str, Any],
    source_row: dict[str, Any],
    authority: dict[str, Any],
    *,
    dispositions: dict[str, dict[str, Any] | None] | None = None,
) -> bool:
    """Gate only ambiguous action-declared free Talents for combat targets."""

    if not _provider_combat_ready_requested(request):
        return True
    choice_id = compact_row.get("id")
    if not isinstance(choice_id, str) or not choice_id.strip():
        return False
    dispositions = (
        dispositions
        if isinstance(dispositions, dict)
        else _provider_frozen_talent_dispositions(request)
    )
    disposition = _provider_bound_talent_disposition(
        choice_id,
        compact_row,
        source_row,
        authority,
        dispositions,
    )
    if disposition is None:
        # If the compact/frozen row itself declares a supported combat action,
        # missing or mismatched full source authority cannot be treated as a
        # harmless non-action.  Non-action legacy rows retain their old path.
        raw_disposition = dispositions.get(choice_id)
        return not any(
            _provider_explicit_combat_action_text(value)
            for value in (
                compact_row.get("semantic_cue"),
                compact_row.get("description"),
                source_row.get("description"),
                source_row.get("full_description"),
                raw_disposition.get("full_description")
                if isinstance(raw_disposition, dict)
                else None,
            )
        )
    action_label_present, expected_action_type = _provider_combat_action_type(
        disposition.get("full_description")
    )
    if not action_label_present:
        return True
    if expected_action_type is None:
        return False
    return _provider_complete_action_resource_projection(
        disposition.get("full_description"),
        expected_action_type=expected_action_type,
        record_id=choice_id,
        display_name=disposition.get("display_name"),
    )


def _provider_free_talent_candidate_is_eligible(
    compact_row: dict[str, Any],
    source_row: dict[str, Any],
    authority: dict[str, Any],
    *,
    free_kind: str,
    target_cl: int | None,
    request: dict[str, Any] | None = None,
    combat_ready: bool = False,
    dispositions: dict[str, dict[str, Any] | None] | None = None,
) -> bool:
    """Apply the shared sealed Talent predicate before/after presentation caps."""

    allowed_kinds = _provider_stage2_allowed_kinds(authority, source_row)
    if free_kind not in allowed_kinds:
        return False
    free_eligible = (
        authority.get("free_sphere_talent_eligible")
        if "free_sphere_talent_eligible" in authority
        else source_row.get("free_sphere_talent_eligible")
    )
    # The canonical delegated-authority validator treats an omitted flag as
    # unknown/legacy-compatible; only an explicit False disqualifies the
    # candidate.  Keep this predicate aligned with that authority contract.
    if free_eligible is False:
        return False
    minimum_cl = compact_row.get("minimum_cl")
    if type(minimum_cl) is not int:
        minimum_cl = authority.get("minimum_cl")
    if type(minimum_cl) is not int:
        availability = source_row.get("availability")
        minimum_cl = availability.get("minimum_cl") if isinstance(availability, dict) else None
    if type(minimum_cl) is int and (
        minimum_cl < 0 or (target_cl is not None and minimum_cl > target_cl)
    ):
        return False
    if (
        compact_row.get("hard_prerequisite_ids")
        or compact_row.get("incompatibility_ids")
        or authority.get("hard_prerequisite_ids")
        or authority.get("prerequisite_ids")
        or authority.get("prerequisites")
        or authority.get("incompatibility_ids")
        or authority.get("incompatibilities")
        or source_row.get("hard_prerequisite_ids")
        or source_row.get("prerequisite_ids")
        or source_row.get("prerequisites")
        or source_row.get("incompatibility_ids")
        or source_row.get("incompatibilities")
    ):
        return False
    if combat_ready and isinstance(request, dict) and not _provider_combat_ready_free_talent_allowed(
        request,
        compact_row,
        source_row,
        authority,
        dispositions=dispositions,
    ):
        return False
    return True


def _provider_free_talent_pairs(
    request: dict[str, Any],
    compact_model: dict[str, Any],
    ordinary_shortlist: dict[str, list[dict[str, Any]]],
) -> list[dict[str, str]]:
    """Return only legal, presented Sphere/free-Talent pairs.

    Pair legality is projected from the same frozen choice rows and typed
    authority used by the local validator.  A talent must be in the compact
    ordinary shortlist, belong to a presented Sphere, be active at CL1, and
    explicitly allow the frozen generation route's acquisition kind.  The
    presented Sphere must independently advertise the matching route-specific
    Sphere kind in the sealed envelope; a background-only Sphere is never a
    legal free-Talent pair merely because its Talent advertises the route.
    """

    envelope = request.get("delegated_choice_envelope") or {}
    if not isinstance(envelope, dict):
        return []
    choices_by_slot = envelope.get("choices_by_slot") or {}
    if not isinstance(choices_by_slot, dict):
        return []
    sphere_rows = (compact_model.get("choices_by_slot") or {}).get("sphere_priorities") or []
    sphere_ids = {
        row.get("id")
        for row in sphere_rows
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    presented_talents = {
        row.get("id")
        for rows in ordinary_shortlist.values()
        for row in rows
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    frozen_sphere_rows = choices_by_slot.get("sphere_priorities") or {}
    if not isinstance(frozen_sphere_rows, dict):
        return []
    talent_rows = (choices_by_slot.get("advancement_skeleton") or {})
    if not isinstance(talent_rows, dict):
        return []
    compact_talents = {
        row.get("id"): row
        for row in ((compact_model.get("choices_by_slot") or {}).get("advancement_skeleton") or [])
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    free_kind = _provider_free_talent_kind(request)
    free_sphere_kind = _provider_free_sphere_kind(request)
    combat_ready = _provider_combat_ready_requested(request)
    dispositions = _provider_frozen_talent_dispositions(request) if combat_ready else None
    pairs: list[dict[str, str]] = []
    for talent_id in sorted(presented_talents):
        compact_row = compact_talents.get(talent_id)
        source_row = talent_rows.get(talent_id)
        if not isinstance(compact_row, dict) or not isinstance(source_row, dict):
            continue
        authority = choice_authority(envelope, "advancement_skeleton", talent_id, source_row)
        owner = compact_row.get("owner")
        if not isinstance(owner, str) or owner not in sphere_ids:
            owner = (
                authority.get("owning_canonical_sphere_id")
                or authority.get("owning_sphere_id")
                or authority.get("sphere_id")
            )
        if not isinstance(owner, str) or owner not in sphere_ids:
            continue
        sphere_source_row = frozen_sphere_rows.get(owner)
        if not isinstance(sphere_source_row, dict):
            continue
        sphere_authority = choice_authority(
            envelope,
            "sphere_priorities",
            owner,
            sphere_source_row,
        )
        sphere_allowed_kinds = _provider_stage2_allowed_kinds(sphere_authority, sphere_source_row)
        if free_sphere_kind not in sphere_allowed_kinds:
            continue
        if not _provider_free_talent_candidate_is_eligible(
            compact_row,
            source_row,
            authority,
            free_kind=free_kind,
            target_cl=1,
            request=request,
            combat_ready=combat_ready,
            dispositions=dispositions,
        ):
            continue
        pairs.append({"sphere_id": owner, "talent_id": talent_id})
    return pairs


def _provider_free_talent_pair_shortlist(
    request: dict[str, Any],
    compact_model: dict[str, Any],
    *,
    target_cl: int | None,
) -> dict[str, list[dict[str, Any]]]:
    """Project at most the balanced two-per-Sphere free-Talent shortlist.

    Route-specific free-Talent rows are not necessarily ordinary level-talent
    rows, so ``_provider_ordinary_shortlist`` cannot be used directly for this
    correction.  This keeps its deterministic ordering/cap policy while
    deriving ownership and eligibility from the same sealed choice authority.
    Rows with explicit prerequisite or incompatibility projections are omitted
    because this target has no authority to satisfy those conditions.
    """

    envelope = request.get("delegated_choice_envelope") or {}
    if not isinstance(envelope, dict):
        return {}
    frozen_rows = (envelope.get("choices_by_slot") or {}).get("advancement_skeleton")
    if not isinstance(frozen_rows, dict):
        return {}
    compact_rows = (compact_model.get("choices_by_slot") or {}).get("advancement_skeleton")
    if not isinstance(compact_rows, list):
        return {}

    # Filter against the sealed route authority before applying the balanced
    # two-per-Sphere presentation cap.  Ordinary/non-route rows can sort ahead
    # of a legal free-Talent row in a large Sphere; capping first would hide
    # the only choices this scoped correction is allowed to offer.
    free_kind = _provider_free_talent_kind(request)
    combat_ready = _provider_combat_ready_requested(request)
    dispositions = _provider_frozen_talent_dispositions(request) if combat_ready else None
    sphere_rows = (compact_model.get("choices_by_slot") or {}).get("sphere_priorities")
    sphere_ids = {
        row.get("id")
        for row in sphere_rows
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    } if isinstance(sphere_rows, list) else set()

    grouped: dict[str, list[dict[str, Any]]] = {}
    for compact_row in compact_rows:
        if not isinstance(compact_row, dict):
            continue
        choice_id = compact_row.get("id")
        if not isinstance(choice_id, str) or not choice_id.strip():
            continue
        source_row = frozen_rows.get(choice_id)
        if not isinstance(source_row, dict):
            continue
        authority = choice_authority(envelope, "advancement_skeleton", choice_id, source_row)
        owner = compact_row.get("owner")
        if not isinstance(owner, str) or not owner.strip():
            owner = (
                authority.get("owning_canonical_sphere_id")
                or authority.get("owning_sphere_id")
                or authority.get("sphere_id")
                or source_row.get("owner")
            )
        if not isinstance(owner, str) or not owner.strip():
            continue
        if owner not in sphere_ids:
            continue
        authoritative_owner = (
            authority.get("owning_canonical_sphere_id")
            or authority.get("owning_sphere_id")
            or authority.get("sphere_id")
            or source_row.get("owner")
        )
        if isinstance(authoritative_owner, str) and authoritative_owner.strip() and authoritative_owner != owner:
            continue
        if not _provider_free_talent_candidate_is_eligible(
            compact_row,
            source_row,
            authority,
            free_kind=free_kind,
            target_cl=target_cl,
            request=request,
            combat_ready=combat_ready,
            dispositions=dispositions,
        ):
            continue
        minimum_cl = compact_row.get("minimum_cl")
        if type(minimum_cl) is not int:
            minimum_cl = authority.get("minimum_cl")
        if type(minimum_cl) is not int:
            availability = source_row.get("availability")
            minimum_cl = availability.get("minimum_cl") if isinstance(availability, dict) else None
        projected = deepcopy(compact_row)
        projected["id"] = choice_id
        projected["owner"] = owner
        projected["minimum_cl"] = minimum_cl if type(minimum_cl) is int else 0
        grouped.setdefault(owner, []).append(projected)

    shortlist: dict[str, list[dict[str, Any]]] = {}
    for owner in sorted(grouped):
        rows = sorted(
            grouped[owner],
            key=lambda row: (
                bool(row.get("hard_prerequisite_ids")),
                row.get("minimum_cl") if type(row.get("minimum_cl")) is int else 999,
                -len(row.get("eligible_cl") or []),
                row["id"],
            ),
        )
        shortlist[owner] = rows[:_PROVIDER_SHORTLIST_PER_SPHERE]
    return shortlist


def _provider_acquisition_contract(
    request: dict[str, Any],
    compact_model: dict[str, Any],
    ordinary_shortlist: dict[str, list[dict[str, Any]]],
    target_cl: int | None,
) -> dict[str, Any]:
    """Expose exact frozen acquisition capacity without copying authority rows."""

    envelope = request.get("delegated_choice_envelope") or {}
    envelope = envelope if isinstance(envelope, dict) else {}
    accounting = _provider_locked_grant_accounting(request)
    free_rows = accounting.get("free_sphere_talent_grants")
    if isinstance(free_rows, dict):
        free_rows = [
            {"sphere_id": sphere_id, "talent_id": talent_id}
            for sphere_id, talent_id in sorted(free_rows.items())
            if isinstance(sphere_id, str) and isinstance(talent_id, str)
        ]
    elif not isinstance(free_rows, list):
        free_rows = []
    explicit_pair_count: int | None = None
    for source in (accounting, envelope):
        if not isinstance(source, dict):
            continue
        for key in (
            "free_sphere_talent_grant_count",
            "sphere_free_talent_pair_count",
            "first_cycle_sphere_free_talent_count",
            "first_cycle_free_sphere_talent_count",
        ):
            value = source.get(key)
            if type(value) is int and value >= 0:
                explicit_pair_count = value
                break
        if explicit_pair_count is not None:
            break
    if explicit_pair_count is None and "free_sphere_talent_grants" in accounting:
        explicit_pair_count = len(free_rows)
    if explicit_pair_count is None:
        nested_counts = envelope.get("acquisition_counts")
        if isinstance(nested_counts, dict):
            value = nested_counts.get("sphere_free_talent_pairs")
            if type(value) is int and value >= 0:
                explicit_pair_count = value

    ordinary_count = envelope.get("ordinary_talent_count")
    if type(ordinary_count) is not int:
        ordinary_count = target_cl if type(target_cl) is int else None

    insight_count: int | None = None
    for source in (accounting, envelope):
        if not isinstance(source, dict):
            continue
        for key in (
            "insight_occurrence_count",
            "required_insight_occurrence_count",
            "first_cycle_insight_occurrence_count",
        ):
            value = source.get(key)
            if type(value) is int and value >= 0:
                insight_count = value
                break
        if insight_count is not None:
            break
    if insight_count is None:
        milestones = [
            row for row in envelope.get("advancement_choice_milestones") or []
            if isinstance(row, dict)
            and (target_cl is None or type(row.get("cl")) is not int or row.get("cl") <= target_cl)
        ]
        insight_only = [
            row for row in milestones
            if set(row.get("allowed_kinds") or []) == {"cultivation_insight_acquisition"}
        ]
        if insight_only:
            insight_count = len(insight_only)

    free_talent_shortlist = _provider_free_talent_pair_shortlist(
        request,
        compact_model,
        target_cl=1,
    )
    legal_pairs = _provider_free_talent_pairs(request, compact_model, free_talent_shortlist)
    legal_by_key = {(row["sphere_id"], row["talent_id"]): row for row in legal_pairs}
    selected_pairs: list[dict[str, str]] = []
    selected_keys: set[tuple[str, str]] = set()
    selected_spheres: set[str] = set()
    # Before a delegated response exists, the compatibility grant lock can
    # contain an empty zero placeholder even though the frozen request still
    # requires ordinary Talents.  Treating that placeholder as final creates
    # an impossible prompt: every ordinary Talent then fails Sphere ownership.
    # Derive the one route-legal pair required by the bootstrap contract from
    # sealed authority.
    # A contradictory non-empty zero remains authoritative for retained legacy
    # data and is intentionally not rewritten here.
    empty_pre_response_placeholder = (
        explicit_pair_count == 0
        and not free_rows
        and type(target_cl) is int
        and target_cl >= 1
        and type(ordinary_count) is int
        and ordinary_count > 0
        and _provider_free_talent_kind(request) == "ai_bootstrap_talent_acquisition"
        and _provider_catalog_grant_origin(request) == CATALOG_GRANT_ORIGIN_PROJECTION
    )
    if empty_pre_response_placeholder:
        # The bootstrap contract grants exactly one CL1 Sphere and its one
        # paired free Talent.  Ordinary per-CL Talent presentation is a
        # separate route concern and must never inflate this acquisition
        # count to cover shortlist capacity.
        required_owner_count = 1
        for row in legal_pairs:
            sphere_id = row.get("sphere_id")
            talent_id = row.get("talent_id")
            key = (sphere_id, talent_id)
            if (
                not isinstance(sphere_id, str)
                or not isinstance(talent_id, str)
                or sphere_id in selected_spheres
                or key not in legal_by_key
            ):
                continue
            selected_pairs.append(deepcopy(legal_by_key[key]))
            selected_keys.add(key)
            selected_spheres.add(sphere_id)
            if len(selected_spheres) >= required_owner_count:
                break
        # Keep the frozen required count at one even when no complete route
        # could be selected; the caller then fails closed with the bounded
        # unsatisfiable-contract diagnostic rather than presenting a zero
        # pair response that Stage 2 can never complete.
        explicit_pair_count = required_owner_count
    # An explicit zero is authoritative: do not let a legal illustrative row
    # leak into the prompt and contradict the frozen acquisition capacity.
    # Grant rows establish the frozen capacity, not an owner-forced provider
    # selection.  Choose a deterministic legal presented example instead of
    # promoting the committed plan's exact pair into the response contract.
    if explicit_pair_count != 0 and not selected_pairs:
        for row in legal_pairs:
            key = (row.get("sphere_id"), row.get("talent_id"))
            sphere_id = row.get("sphere_id")
            if key not in legal_by_key or key in selected_keys or sphere_id in selected_spheres:
                continue
            selected_pairs.append(deepcopy(legal_by_key[key]))
            selected_keys.add(key)
            if isinstance(sphere_id, str):
                selected_spheres.add(sphere_id)
            if explicit_pair_count is not None and len(selected_pairs) >= explicit_pair_count:
                break
    return {
        "expected_counts": {
            "sphere_free_talent_pairs": explicit_pair_count,
            "ordinary_talent_ids": ordinary_count,
            "insight_occurrences": insight_count,
        },
        "presented_legal_pairs": selected_pairs,
    }


def _provider_route_modules(
    request: dict[str, Any],
    compact_model: dict[str, Any],
    legal_pairs: Collection[dict[str, Any]],
    comparability_index: dict[str, Any],
    *,
    target_cl: int | None,
    required_route_count: int | None = None,
) -> list[dict[str, Any]]:
    """Project a few complete, coherent Sphere routes for the provider.

    A route is a whole frozen free-Sphere/free-Talent pair plus a deterministic
    one-to-one assignment of ordinary Talents to every active CL.  This is a
    presentation projection only: the response validator still consults the
    complete sealed envelope.  The matching step is intentionally performed
    before any presentation cap so a route cannot look legal while relying on
    server-side duplicate repair.
    """
    if type(target_cl) is not int or target_cl < 1:
        return []
    envelope = request.get("delegated_choice_envelope")
    if not isinstance(envelope, dict):
        return []
    choices_by_slot = envelope.get("choices_by_slot")
    choices_by_slot = choices_by_slot if isinstance(choices_by_slot, dict) else {}
    frozen_talents = choices_by_slot.get("advancement_skeleton")
    frozen_talents = frozen_talents if isinstance(frozen_talents, dict) else {}
    compact_talents = (compact_model.get("choices_by_slot") or {}).get("advancement_skeleton")
    compact_talents = compact_talents if isinstance(compact_talents, list) else []
    compact_by_id = {
        row.get("id"): row
        for row in compact_talents
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    active_by_cl: dict[int, list[str]] = {}
    for slot in compact_model.get("ordinary_talent_slots") or []:
        if not isinstance(slot, dict) or slot.get("active_for_request") is not True:
            continue
        cl = slot.get("cl")
        if type(cl) is not int or cl < 1 or cl > target_cl:
            continue
        active_by_cl[cl] = sorted({
            choice_id
            for choice_id in slot.get("eligible_choice_ids") or []
            if isinstance(choice_id, str) and choice_id in compact_by_id
        })
    if any(not active_by_cl.get(cl) for cl in range(1, target_cl + 1)):
        return []

    profile_by_sphere = {
        row.get("sphere_id"): row
        for row in comparability_index.get("profiles") or []
        if isinstance(row, dict) and isinstance(row.get("sphere_id"), str)
    }
    # Each active choice's owner and level-talent eligibility depend only on
    # the frozen envelope, not on the pair being projected.  Derive them once
    # per CL and owner so the pair loop below is a lookup instead of a full
    # re-derivation per pair (the same rows, the same checks, the same order).
    eligible_by_cl_owner: dict[int, dict[Any, list[str]]] = {}
    for cl in range(1, target_cl + 1):
        owners: dict[Any, list[str]] = {}
        for choice_id in active_by_cl[cl]:
            compact_row = compact_by_id.get(choice_id)
            source_row = frozen_talents.get(choice_id)
            if not isinstance(compact_row, dict) or not isinstance(source_row, dict):
                continue
            authority = choice_authority(envelope, "advancement_skeleton", choice_id, source_row)
            owner = (
                compact_row.get("owner")
                or authority.get("owning_canonical_sphere_id")
                or authority.get("owning_sphere_id")
                or authority.get("sphere_id")
                or source_row.get("owner")
            )
            if authority.get("authority_complete") is not True:
                continue
            if "level_talent_acquisition" not in (authority.get("allowed_kinds") or []):
                continue
            owners.setdefault(owner, []).append(choice_id)
        eligible_by_cl_owner[cl] = owners
    # Talent and record prerequisites a route must schedule before the Talent.
    # A Path prerequisite cannot be planned before the Path is chosen, so such
    # Talents stay out of routes (training can still offer them).
    availability = (envelope.get("prerequisites_and_availability") or {}).get("advancement_skeleton")
    availability = availability if isinstance(availability, dict) else {}
    # Each prerequisite is a clause of alternatives (any one alternative whose
    # Talents are all scheduled earlier satisfies it).
    route_prerequisites: dict[str, list[list[list[str]]]] = {}
    path_gated: set[str] = set()
    for choice_id, row in availability.items():
        relations = row.get("prerequisites") if isinstance(row, dict) else None
        for relation in relations if isinstance(relations, list) else []:
            if not isinstance(relation, dict) or relation.get("operator") != "requires":
                continue
            if relation.get("kind") in {"talent", "record"} and isinstance(relation.get("target_id"), str):
                route_prerequisites.setdefault(choice_id, []).append([[relation["target_id"]]])
            elif relation.get("kind") == "path":
                path_gated.add(choice_id)
    canonical_gates = request.get("talent_prerequisite_gates")
    for choice_id, clauses in (canonical_gates.items() if isinstance(canonical_gates, dict) else []):
        for clause in clauses if isinstance(clauses, list) else []:
            if isinstance(clause, list):
                route_prerequisites.setdefault(choice_id, []).append(
                    [list(alternative) for alternative in clause if isinstance(alternative, list)]
                )
    # A Background Talent is the canonical Talent it links to; a route that
    # schedules it as an ordinary Talent dead-ends when the Background took it
    # (build 30: Lookout at CL1).  Routes are built before the Background is
    # chosen, so keep every Background-linked Talent out of them.
    linkage = (((envelope.get("typed_choice_authority_by_slot") or {}).get("background_choice") or {})
               .get("background_package_linkage"))
    background_linked = {
        entry.get("canonical_talent_id")
        for entries in (linkage.values() if isinstance(linkage, dict) else [])
        for entry in (entries if isinstance(entries, list) else [])
        if isinstance(entry, dict) and isinstance(entry.get("canonical_talent_id"), str)
    }
    for owners in eligible_by_cl_owner.values():
        for owner, ids in owners.items():
            owners[owner] = [value for value in ids if value not in path_gated and value not in background_linked]
    candidate_routes: list[dict[str, Any]] = []
    seen_pairs: set[tuple[str, str]] = set()
    for raw_pair in sorted(
        (row for row in legal_pairs if isinstance(row, dict)),
        key=lambda row: (row.get("sphere_id") or "", row.get("talent_id") or ""),
    ):
        sphere_id = raw_pair.get("sphere_id")
        free_talent_id = raw_pair.get("talent_id")
        pair_key = (sphere_id, free_talent_id)
        if (
            not isinstance(sphere_id, str)
            or not isinstance(free_talent_id, str)
            or pair_key in seen_pairs
        ):
            continue
        seen_pairs.add(pair_key)
        candidate_ids_by_cl: dict[int, list[str]] = {}
        for cl in range(1, target_cl + 1):
            candidate_ids_by_cl[cl] = sorted({
                choice_id
                for choice_id in eligible_by_cl_owner[cl].get(sphere_id, [])
                if choice_id != free_talent_id
            })
        if any(not candidate_ids_by_cl[cl] for cl in range(1, target_cl + 1)):
            continue

        # Deterministic bipartite matching: CL positions are visited from the
        # most constrained to the least constrained, while the augmenting
        # search always visits stable IDs in lexical order.
        matched_talent_to_cl: dict[str, int] = {}

        def assign(cl: int, visited: set[str]) -> bool:
            for talent_id in candidate_ids_by_cl[cl]:
                if talent_id in visited:
                    continue
                visited.add(talent_id)
                prior_cl = matched_talent_to_cl.get(talent_id)
                if prior_cl is None or assign(prior_cl, visited):
                    matched_talent_to_cl[talent_id] = cl
                    return True
            return False

        # A route must be walkable in order: every Talent's Talent
        # prerequisites come from the free Talent or an earlier CL (a route
        # scheduled Enduring Control at CL8 with no Beast Tamer and dead-ended
        # the walk).  Drop the first out-of-order (Talent, CL) and re-match.
        while True:
            matched_talent_to_cl = {}
            for cl in sorted(range(1, target_cl + 1), key=lambda value: (len(candidate_ids_by_cl[value]), value)):
                if not assign(cl, set()):
                    matched_talent_to_cl = {}
                    break
            if len(matched_talent_to_cl) != target_cl:
                break
            violation = next((
                (talent_id, assigned_cl)
                for talent_id, assigned_cl in sorted(matched_talent_to_cl.items(), key=lambda item: (item[1], item[0]))
                if not all(
                    any(
                        all(
                            required == free_talent_id
                            or matched_talent_to_cl.get(required, target_cl + 1) < assigned_cl
                            for required in alternative
                        )
                        for alternative in clause
                    )
                    for clause in route_prerequisites.get(talent_id, ())
                )
            ), None)
            if violation is None:
                break
            candidate_ids_by_cl[violation[1]] = [value for value in candidate_ids_by_cl[violation[1]] if value != violation[0]]
            if not candidate_ids_by_cl[violation[1]]:
                matched_talent_to_cl = {}
                break
        if len(matched_talent_to_cl) != target_cl:
            continue
        ordinary_by_cl = {
            str(cl): next(
                talent_id for talent_id, assigned_cl in matched_talent_to_cl.items()
                if assigned_cl == cl
            )
            for cl in range(1, target_cl + 1)
        }
        ordinary_ids = [ordinary_by_cl[str(cl)] for cl in range(1, target_cl + 1)]
        profile = profile_by_sphere.get(sphere_id) or {}
        route = {
            "route_id": f"sphere-route:{sphere_id}:{free_talent_id}",
            "sphere_id": sphere_id,
            "free_talent_pair": {"sphere_id": sphere_id, "talent_id": free_talent_id},
            "ordinary_talent_ids_by_cl": ordinary_by_cl,
            "ordinary_talent_ids": ordinary_ids,
            "cross_route_mixing_forbidden": True,
            "comparability_profile_sphere_id": sphere_id,
            "capability_tags": [
                value for value in profile.get("capability_tags") or []
                if isinstance(value, str)
            ],
        }
        if isinstance(profile.get("flavor_cue"), str) and profile["flavor_cue"].strip():
            route["flavor_cue"] = profile["flavor_cue"]
        candidate_routes.append(route)

    # Favor distinct comparison profiles first, then distinct Spheres, while
    # retaining lexical ordering as the final deterministic tie breaker.  The
    # normal presentation cap is intentionally raised when the sealed
    # acquisition contract requires more complete alternatives; otherwise a
    # valid request could publish fewer unique pairs than its frozen count.
    route_limit = _PROVIDER_ROUTE_MAX_MODULES
    if type(required_route_count) is int and required_route_count > route_limit:
        route_limit = required_route_count
    selected: list[dict[str, Any]] = []
    remaining = list(candidate_routes)
    while remaining and len(selected) < route_limit:
        prior_spheres = {row["sphere_id"] for row in selected}
        prior_tags = {
            tag for row in selected for tag in row.get("capability_tags") or []
        }
        remaining.sort(key=lambda row: (
            row["sphere_id"] in prior_spheres,
            -len(set(row.get("capability_tags") or []) - prior_tags),
            -len(set(row.get("capability_tags") or [])),
            row["sphere_id"],
            row["free_talent_pair"]["talent_id"],
        ))
        selected.append(remaining.pop(0))
    return selected


def _provider_route_ordinary_shortlist(
    compact_model: dict[str, Any],
    route_modules: Collection[dict[str, Any]],
    *,
    cue_limit: int,
    display_limit: int,
) -> dict[str, list[dict[str, Any]]]:
    """Return only the route rows needed for the active CL positions."""
    compact_rows = (compact_model.get("choices_by_slot") or {}).get("advancement_skeleton")
    compact_rows = compact_rows if isinstance(compact_rows, list) else []
    rows_by_id = {
        row.get("id"): row
        for row in compact_rows
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    by_owner: dict[str, set[str]] = {}
    assigned_cl_by_choice: dict[tuple[str, str], set[int]] = {}
    for route in route_modules:
        if not isinstance(route, dict) or not isinstance(route.get("sphere_id"), str):
            continue
        owner = route["sphere_id"]
        route_assignments = route.get("ordinary_talent_ids_by_cl")
        if isinstance(route_assignments, dict):
            for raw_cl, value in route_assignments.items():
                if type(raw_cl) is not str or not raw_cl.isdigit() or not isinstance(value, str):
                    continue
                by_owner.setdefault(owner, set()).add(value)
                assigned_cl_by_choice.setdefault((owner, value), set()).add(int(raw_cl))
        else:
            by_owner.setdefault(owner, set()).update(
                value for value in route.get("ordinary_talent_ids") or []
                if isinstance(value, str)
            )
        pair = route.get("free_talent_pair")
        if isinstance(pair, dict) and isinstance(pair.get("talent_id"), str):
            by_owner[owner].add(pair["talent_id"])
            assigned_cl_by_choice.setdefault((owner, pair["talent_id"]), set()).add(1)
    result: dict[str, list[dict[str, Any]]] = {}
    for owner in sorted(by_owner):
        rows: list[dict[str, Any]] = []
        for choice_id in sorted(by_owner[owner]):
            row = rows_by_id.get(choice_id)
            if not isinstance(row, dict):
                continue
            projected = _provider_choice_projection(
                row,
                cue_limit=cue_limit,
                display_limit=display_limit,
                include_owner=False,
            )
            # Route assignments already prove the exact CL positions offered
            # by this projection.  Do not repeat every sealed catalogue
            # eligibility position here: that turns a compact whole-route
            # shortlist back into a mix-and-match catalogue.  The sealed
            # envelope remains authoritative for final validation.
            projected["eligible_cl"] = sorted(assigned_cl_by_choice.get((owner, choice_id), set()))
            rows.append(projected)
        if rows:
            result[owner] = rows
    return result


def _provider_compact_high_level_choices(
    allowed_high_level: dict[str, list[dict[str, Any]]],
    *,
    route_sphere_ids: Collection[str],
    background_package_linkage: dict[str, list[dict[str, Any]]],
    owner_locks: dict[str, Any] | None = None,
) -> dict[str, list[dict[str, Any]]]:
    """Keep the model-facing high-level choice lists bounded and coherent."""
    owner_locks = owner_locks if isinstance(owner_locks, dict) else {}
    route_sphere_ids = {value for value in route_sphere_ids if isinstance(value, str)}
    linked_ids = {
        key: {
            value
            for package in packages
            if isinstance(package, dict)
            for value in (
                package.get("background_sphere_choice_id"),
                package.get("background_talent_choice_id"),
            )
            if isinstance(value, str)
        }
        for key, packages in (background_package_linkage or {}).items()
        if isinstance(key, str) and isinstance(packages, list)
    }
    result: dict[str, list[dict[str, Any]]] = {}
    for slot_id, rows in allowed_high_level.items():
        if not isinstance(rows, list):
            continue
        locked = {
            value for value in owner_locks.get(slot_id) or []
            if isinstance(value, str)
        }
        filtered = rows
        if slot_id == "sphere_priorities" and route_sphere_ids:
            filtered = [row for row in rows if row.get("id") in route_sphere_ids]
        elif slot_id in {"background_sphere_choice", "background_talent_choice"} and linked_ids:
            package_ids = set().union(*linked_ids.values()) if linked_ids else set()
            filtered = [row for row in rows if row.get("id") in package_ids]
        elif slot_id == "subpath_choice":
            # Preserve up to two presented options per owning Path so every
            # presented Path can resolve its required Subpath without a dump.
            counts: dict[str, int] = {}
            bounded: list[dict[str, Any]] = []
            for row in rows:
                owner = row.get("owner") or ""
                if counts.get(owner, 0) >= 2 and row.get("id") not in locked:
                    continue
                bounded.append(row)
                counts[owner] = counts.get(owner, 0) + 1
            filtered = bounded
        elif slot_id in {
            "insight_priorities",
            "item_priorities",
            "origin_insight_choice",
            "foundation_choice",
        }:
            filtered = rows[:_PROVIDER_HIGH_LEVEL_MAX_ROWS]
        filtered_ids = {row.get("id") for row in filtered if isinstance(row, dict)}
        for row in rows:
            if row.get("id") in locked and row.get("id") not in filtered_ids:
                filtered.append(row)
        result[slot_id] = filtered
    return result


def _provider_response_template(
    *,
    request_sha256: str,
    descriptive_context: dict[str, dict[str, Any]],
    presented_choices_by_slot: dict[str, list[dict[str, Any]]],
    ordinary_shortlist: dict[str, list[dict[str, Any]]],
    target_cl: int | None,
    subpath_required: bool = False,
    acquisition_contract: dict[str, Any] | None = None,
    background_package_linkage: dict[str, list[dict[str, Any]]] | None = None,
    background_ability_candidates: dict[str, dict[str, Any]] | None = None,
    selection_limits: dict[str, dict[str, Any]] | None = None,
    legal_method_path_pairs: list[dict[str, str]] | None = None,
    bounded_choice_fields: Collection[str] | None = None,
    milestone_resolution_placeholders: Collection[str] | None = None,
    owner_locks: dict[str, Any] | None = None,
) -> dict[str, Any]:
    acquisition_contract = acquisition_contract if isinstance(acquisition_contract, dict) else {}
    selection_limits = selection_limits if isinstance(selection_limits, dict) else {}
    if bounded_choice_fields is None:
        bounded_choice_fields = _PROVIDER_LEGACY_BOUNDED_CHOICE_KEYS
    requested_bounded_choice_fields = {
        value
        for value in bounded_choice_fields
        if isinstance(value, str) and value.strip() and value == value.strip()
    }
    unsupported_bounded_choice_fields = sorted(
        requested_bounded_choice_fields - _PROVIDER_SUPPORTED_BOUNDED_CHOICE_KEYS
    )
    if unsupported_bounded_choice_fields:
        raise FoundryError(
            "CG1_PROVIDER_BOUNDED_FIELD_UNSUPPORTED",
            "The sealed request advertises a bounded field without a supported model and validator representation.",
            details={"fields": unsupported_bounded_choice_fields},
            status_code=422,
        )
    allowed_bounded_choice_fields = requested_bounded_choice_fields
    shape_only = owner_locks is not None
    owner_locks = owner_locks if isinstance(owner_locks, dict) else {}
    expected_counts = acquisition_contract.get("expected_counts") or {}
    expected_ordinary_count = expected_counts.get("ordinary_talent_ids")
    if type(expected_ordinary_count) is not int:
        expected_ordinary_count = target_cl if type(target_cl) is int else 0
    pair_rows = [
        row for row in acquisition_contract.get("presented_legal_pairs") or []
        if isinstance(row, dict)
        and isinstance(row.get("sphere_id"), str)
        and isinstance(row.get("talent_id"), str)
    ]
    free_talent_ids = {row["talent_id"] for row in pair_rows}
    presented_ordinary = [
        row
        for owner in sorted(ordinary_shortlist)
        for row in ordinary_shortlist[owner]
    ]
    ordinary_by_cl: dict[int, list[str]] = {}
    for row in presented_ordinary:
        for cl in row.get("eligible_cl") or []:
            ordinary_by_cl.setdefault(cl, []).append(row["id"])
    # Keep the illustrative response legal with respect to unique ordinary
    # talent IDs.  Pick the first unused eligible presented ID at each active
    # CL; the Factory remains responsible for the final coherent choice.
    ordinary_ids: list[str] = []
    used_ordinary_ids: set[str] = set()
    for cl in range(1, expected_ordinary_count + 1):
        candidates = sorted({
            value
            for value in ordinary_by_cl.get(cl) or []
            if value not in used_ordinary_ids and value not in free_talent_ids
        })
        if not candidates:
            continue
        ordinary_ids.append(candidates[0])
        used_ordinary_ids.add(candidates[0])
    presented_path_ids = [
        row.get("id")
        for row in presented_choices_by_slot.get("path_choice") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    ]
    presented_method_ids = [
        row["id"]
        for row in presented_choices_by_slot.get("method_choice") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    ]
    legal_pair_rows = sorted(
        (
            {"method_id": row["method_id"], "path_id": row["path_id"]}
            for row in (legal_method_path_pairs or [])
            if isinstance(row, dict)
            and isinstance(row.get("method_id"), str)
            and isinstance(row.get("path_id"), str)
            and row["method_id"] in set(presented_method_ids)
            and row["path_id"] in set(presented_path_ids)
        ),
        key=lambda row: (row["path_id"], row["method_id"]),
    )
    selected_pair = legal_pair_rows[0] if legal_pair_rows else None
    selected_path_id = (
        selected_pair["path_id"]
        if selected_pair is not None
        else (presented_path_ids[0] if presented_path_ids else None)
    )
    selected_method_id = (
        selected_pair["method_id"]
        if selected_pair is not None
        else (presented_method_ids[0] if presented_method_ids else None)
    )
    presented_foundation_ids = [
        row.get("id")
        for row in presented_choices_by_slot.get("foundation_choice") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    ]
    selected_foundation_id = presented_foundation_ids[0] if presented_foundation_ids else None
    presented_ids_by_slot: dict[str, set[str]] = {}
    for slot_id, rows in presented_choices_by_slot.items():
        if not isinstance(rows, list):
            continue
        presented_ids_by_slot[slot_id] = {
            row["id"]
            for row in rows
            if isinstance(row, dict) and isinstance(row.get("id"), str)
        }
    selected_background: list[str] = []
    selected_background_sphere: list[str] = []
    selected_background_talent: list[str] = []
    linkage = background_package_linkage if isinstance(background_package_linkage, dict) else {}
    for background_id in sorted(linkage):
        if background_id not in presented_ids_by_slot.get("background_choice", set()):
            continue
        packages = linkage.get(background_id)
        if not isinstance(packages, list):
            continue
        ordered_packages = sorted(
            (package for package in packages if isinstance(package, dict)),
            key=lambda package: (
                package.get("package_index") if type(package.get("package_index")) is int else 2**31,
                package.get("background_sphere_choice_id") or "",
                package.get("background_talent_choice_id") or "",
            ),
        )
        for package in ordered_packages:
            sphere_id = package.get("background_sphere_choice_id")
            talent_id = package.get("background_talent_choice_id")
            if (
                isinstance(sphere_id, str)
                and isinstance(talent_id, str)
                and sphere_id in presented_ids_by_slot.get("background_sphere_choice", set())
                and talent_id in presented_ids_by_slot.get("background_talent_choice", set())
            ):
                selected_background = [background_id]
                selected_background_sphere = [sphere_id]
                selected_background_talent = [talent_id]
                break
        if selected_background:
            break
    presented_origin_ids = [
        row.get("id")
        for row in presented_choices_by_slot.get("origin_insight_choice") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    ]
    selected_subpath: list[str] = []
    presented_subpaths = presented_choices_by_slot.get("subpath_choice") or []
    if subpath_required and selected_path_id and isinstance(presented_subpaths, list):
        for row in sorted(
            (row for row in presented_subpaths if isinstance(row, dict)),
            key=lambda row: row.get("id") if isinstance(row.get("id"), str) else "",
        ):
            owning_path_id = row.get("owner") or row.get("owning_path_id")
            if isinstance(row.get("id"), str) and owning_path_id == selected_path_id:
                selected_subpath = [row["id"]]
                break
    ability_candidates = background_ability_candidates if isinstance(background_ability_candidates, dict) else {}
    selected_background_abilities = (
        (ability_candidates.get(selected_background[0]) or {}).get("allowed_abilities")
        if selected_background
        else []
    )
    selected_background_abilities = [
        value for value in selected_background_abilities or []
        if isinstance(value, str) and value in _PROVIDER_POINT_BUY_ABILITIES
    ]
    background_ability_example = selected_background_abilities[0] if selected_background_abilities else None
    selected_background_amounts = (
        (ability_candidates.get(selected_background[0]) or {}).get("allowed_amounts")
        if selected_background
        else []
    )
    selected_background_amounts = [
        value for value in selected_background_amounts or []
        if type(value) is int
    ]
    background_ability_amount_example = (
        selected_background_amounts[0]
        if selected_background_amounts
        else None
    )

    def planning_priority_example(slot_id: str, preferred_ids: list[str] | None = None) -> list[str]:
        rows = presented_choices_by_slot.get(slot_id) or []
        presented_ids = [
            row["id"] for row in rows
            if isinstance(row, dict) and isinstance(row.get("id"), str)
        ]
        minimum = (selection_limits.get(slot_id) or {}).get("final_min")
        minimum = minimum if type(minimum) is int and minimum > 0 else 0
        # Auto-finalization needs a concrete delegated recommendation even when
        # the underlying planning-only slot permits an owner to choose none.
        # Requiring one proposal does not grant or acquire the choice.
        if presented_ids:
            minimum = max(minimum, 1)
        ordered = [
            choice_id for choice_id in (preferred_ids or [])
            if choice_id in set(presented_ids)
        ]
        ordered.extend(choice_id for choice_id in presented_ids if choice_id not in set(ordered))
        return ordered[:minimum]

    pair_sphere_ids = [row["sphere_id"] for row in pair_rows]

    def owner_locked_values(slot_id: str) -> list[str]:
        values = owner_locks.get(slot_id)
        if not isinstance(values, list):
            return []
        return [value for value in values if isinstance(value, str) and value.strip()]

    def shape_slot(slot_id: str, suggested: list[str] | None = None) -> list[str]:
        # Delegated slots intentionally have no copyable first choice.  A
        # positively owner-locked slot remains exact, as required by the
        # delegated authority contract.
        locked = owner_locked_values(slot_id)
        # Direct callers of this private helper may still request the
        # historical illustrative projection by omitting ``owner_locks``;
        # model-facing payload construction always passes a dictionary and
        # therefore remains shape-only.
        return locked if locked else (list(suggested or []) if not shape_only else [])

    selection_by_slot = {
        "path_choice": shape_slot("path_choice", presented_path_ids[:1]),
        "method_choice": shape_slot("method_choice", [selected_method_id] if selected_method_id else []),
        "foundation_choice": shape_slot("foundation_choice", [selected_foundation_id] if selected_foundation_id else []),
        "subpath_choice": shape_slot("subpath_choice", selected_subpath),
        "background_choice": shape_slot("background_choice", selected_background),
        "background_sphere_choice": shape_slot("background_sphere_choice", selected_background_sphere),
        "background_talent_choice": shape_slot("background_talent_choice", selected_background_talent),
        "origin_insight_choice": shape_slot("origin_insight_choice", presented_origin_ids[:1]),
        "sphere_priorities": shape_slot("sphere_priorities", planning_priority_example("sphere_priorities", pair_sphere_ids)),
        "insight_priorities": shape_slot("insight_priorities", planning_priority_example("insight_priorities")),
        "item_priorities": shape_slot("item_priorities", planning_priority_example("item_priorities")),
        "advancement_skeleton": shape_slot("advancement_skeleton", ordinary_ids),
    }
    name_context = descriptive_context.get("identity.name") or {}
    title_context = descriptive_context.get("identity.title") or {}
    concept_context = descriptive_context.get("concept") or {}
    name_value = name_context.get("owner_locked_value")
    title_value = title_context.get("owner_locked_value")
    concept_value = concept_context.get("owner_locked_value")
    if not isinstance(name_value, str) or not name_value.strip():
        name_value = None
    if not isinstance(title_value, str) or not title_value.strip():
        title_value = None
    if not isinstance(concept_value, str) or not concept_value.strip():
        concept_value = None
    bounded_choices: dict[str, Any] = {}
    if "foundation_initial_stage" in allowed_bounded_choice_fields:
        bounded_choices["foundation_initial_stage"] = None
    if "ability_scores" in allowed_bounded_choice_fields:
        bounded_choices["ability_scores"] = {}
    if "background_ability" in allowed_bounded_choice_fields:
        bounded_choices["background_ability"] = None
    if (
        "background_ability_amount" in allowed_bounded_choice_fields
    ):
        bounded_choices["background_ability_amount"] = None
    if "ability_score_changes_by_milestone_id" in allowed_bounded_choice_fields:
        # Keep one explicit null placeholder per advertised milestone.  The
        # placeholder is not a selected ASI; it makes the required response
        # destinations visible in the shape-only example so a provider cannot
        # mistake an empty map for a complete resolution.  The validator still
        # requires a typed delta or a matching Insight occurrence.
        milestone_ids = sorted({
            value for value in milestone_resolution_placeholders or []
            if isinstance(value, str) and value.strip()
        })
        bounded_choices["ability_score_changes_by_milestone_id"] = {
            milestone_id: None for milestone_id in milestone_ids
        }
    if "path_progression_by_cl" in allowed_bounded_choice_fields:
        bounded_choices["path_progression_by_cl"] = {}
    # Starting-proficiency maps are sealed separately from this shape-only
    # template.  Their concrete per-ID enums are injected by the generated
    # request schema; the provider response template must nevertheless expose
    # an exact destination for every advertised map.
    for field in (
        "path_skill_choices_by_path_id",
        "origin_skill_choices_by_origin_id",
        "background_language_choices_by_background_id",
    ):
        if field in allowed_bounded_choice_fields:
            bounded_choices[field] = {}

    # Keep this a shape-only contract.  The closed-world candidate rows and
    # route modules above are the provider's legal option set; putting the
    # first pair or first ordinary Talent into the template turns the schema
    # into a copyable answer and biases selection toward lexical order.
    return {
        "schema": DELEGATED_RESPONSE_SCHEMA,
        "request_sha256": request_sha256,
        "selection_intent": {
            "by_slot": selection_by_slot,
        },
        "acquisition_intent": {
            "sphere_free_talent_pairs": [],
            "ordinary_talent_ids": [],
            "insight_occurrences": [],
        },
        "bounded_choices": bounded_choices,
        "owner_descriptive_fields": {
            "identity": {
                "name": name_value,
                **(
                    {"title": title_value}
                    if "identity.title" in descriptive_context
                    else {}
                ),
            },
            "concept": concept_value,
        },
    }



class _DeferSecondCompilation(Exception):
    """Internal control flow: the walk-completion build stops after compile 1."""


def _is_plain_json(value: Any) -> bool:
    """True when ``value`` round-trips through JSON unchanged (no tuples, sets, non-str keys)."""
    stack = [value]
    while stack:
        item = stack.pop()
        kind = type(item)
        if kind is dict:
            for key, child in item.items():
                if type(key) is not str:
                    return False
                stack.append(child)
        elif kind is list:
            stack.extend(item)
        elif kind not in (str, int, float, bool) and item is not None:
            return False
    return True

def _provider_payload(
    run: dict[str, Any],
    *,
    cue_limit: int,
    display_limit: int,
) -> dict[str, Any]:
    request = run.get("request") or {}
    compact_model = build_compact_choice_model(request)
    envelope = request.get("delegated_choice_envelope") or {}
    envelope = envelope if isinstance(envelope, dict) else {}
    target_cl = compact_model.get("target_cl")
    target_cl = target_cl if type(target_cl) is int else None
    subpath_required = _provider_subpath_required(request, envelope, target_cl)
    choices_by_slot = compact_model.get("choices_by_slot") or {}
    choices_by_slot = choices_by_slot if isinstance(choices_by_slot, dict) else {}
    allowed_high_level: dict[str, list[dict[str, Any]]] = {}
    for slot_id in sorted(choices_by_slot):
        # Advancement is represented separately as a bounded active-CL
        # shortlist.  The other planning slots still need compact presented
        # IDs so the provider can make coherent priority choices.
        if slot_id == "advancement_skeleton":
            continue
        rows = choices_by_slot.get(slot_id)
        if not isinstance(rows, list):
            continue
        unavailable_by_slot = envelope.get("unavailable_or_rejected_choice_ids_by_slot")
        unavailable_by_slot = unavailable_by_slot if isinstance(unavailable_by_slot, dict) else {}
        unavailable_ids = {
            value
            for value in unavailable_by_slot.get(slot_id) or []
            if isinstance(value, str)
        }

        def planning_choice_is_available(row: dict[str, Any]) -> bool:
            if slot_id not in {"sphere_priorities", "insight_priorities", "item_priorities"}:
                return True
            choice_id = row.get("id")
            minimum_cl = row.get("minimum_cl")
            if choice_id in unavailable_ids:
                return False
            if type(minimum_cl) is int and (
                minimum_cl < 0 or (target_cl is not None and minimum_cl > target_cl)
            ):
                return False
            # Planning priorities are not acquisitions, but the delegated
            # validator still requires each presented priority itself to be
            # legal without letting another planning preference satisfy its
            # prerequisites.  Until the provider has selected the mechanical
            # route, only prerequisite-free, incompatibility-free rows are a
            # closed-world safe presentation.
            if row.get("hard_prerequisite_ids") or row.get("incompatibility_ids"):
                return False
            return True

        allowed_high_level[slot_id] = [
            _provider_choice_projection(row, cue_limit=cue_limit, display_limit=display_limit)
            for row in rows
            if isinstance(row, dict)
            and isinstance(row.get("id"), str)
            and planning_choice_is_available(row)
        ]
    slot_ids = set(choices_by_slot) | {"advancement_skeleton"}
    locked_accounting = _provider_locked_grant_accounting(request)
    locked_free_rows = locked_accounting.get("free_sphere_talent_grants")
    if isinstance(locked_free_rows, dict):
        locked_free_rows = [
            {"talent_id": talent_id}
            for talent_id in locked_free_rows.values()
            if isinstance(talent_id, str)
        ]
    required_free_ids = {
        row.get("talent_id")
        for row in (locked_free_rows or [])
        if isinstance(row, dict) and isinstance(row.get("talent_id"), str)
    }
    base_ordinary_shortlist = _provider_ordinary_shortlist(
        compact_model,
        target_cl=target_cl,
        cue_limit=cue_limit,
        display_limit=display_limit,
        required_ids=required_free_ids,
    )
    acquisition_contract = _provider_acquisition_contract(
        request,
        compact_model,
        base_ordinary_shortlist,
        target_cl,
    )
    preliminary_free_shortlist = _provider_free_talent_pair_shortlist(
        request,
        compact_model,
        target_cl=1,
    )
    preliminary_legal_pairs = _provider_free_talent_pairs(
        request,
        compact_model,
        preliminary_free_shortlist,
    )
    presented_sphere_ids = {
        row.get("id")
        for row in allowed_high_level.get("sphere_priorities") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    if presented_sphere_ids:
        preliminary_legal_pairs = [
            row for row in preliminary_legal_pairs
            if row.get("sphere_id") in presented_sphere_ids
        ]
    # Once the frozen contract presents exact first-cycle Sphere/free-Talent
    # pairs, ordinary Talents must stay inside those acquired Spheres.  Do not
    # leave unrelated Sphere groups in the provider prompt: a model can copy a
    # valid standalone Talent ID while still producing an illegal grant plan.
    # An absent presented pair preserves the older unfiltered projection for
    # routes whose Sphere ownership is established elsewhere.
    background_ability_candidates = _provider_background_ability_candidates(
        envelope,
        envelope.get("allowed_choice_ids_by_slot") or {},
    )
    request_sha256 = request.get("request_sha256") if isinstance(request.get("request_sha256"), str) else ""
    descriptive_context = _provider_descriptive_context(envelope)
    selection_limits = _provider_selection_limits(envelope, slot_ids)
    if "subpath_choice" in selection_limits:
        # ``build_delegated_choice_envelope`` historically flattened
        # allow_none into final_min.  Preserve the exact Stage 1 cardinality
        # in this model-facing projection without changing validator authority.
        selection_limits["subpath_choice"]["final_min"] = 1 if subpath_required else 0
    raw_owner_locks = envelope.get("owner_locks")
    raw_owner_locks = raw_owner_locks if isinstance(raw_owner_locks, dict) else {}
    owner_locks = raw_owner_locks.get("by_slot") or {}
    owner_locks = owner_locks if isinstance(owner_locks, dict) else {}
    sphere_comparability_index = _provider_comparability_profile(
        envelope,
        compact_model,
        allowed_high_level,
        target_cl=target_cl,
        cue_limit=cue_limit,
        display_limit=display_limit,
    )
    expected_pair_count = (acquisition_contract.get("expected_counts") or {}).get(
        "sphere_free_talent_pairs"
    )
    route_modules = (
        _provider_route_modules(
            request,
            compact_model,
            preliminary_legal_pairs,
            sphere_comparability_index,
            target_cl=target_cl,
            required_route_count=expected_pair_count,
        )
        if type(expected_pair_count) is int and expected_pair_count > 0
        else []
    )
    if type(expected_pair_count) is int and expected_pair_count > 0:
        presented_pair_keys = {
            (pair.get("sphere_id"), pair.get("talent_id"))
            for route in route_modules
            if isinstance(route, dict)
            and isinstance(route.get("route_id"), str)
            and isinstance(route.get("free_talent_pair"), dict)
            and isinstance(route["free_talent_pair"].get("sphere_id"), str)
            and isinstance(route["free_talent_pair"].get("talent_id"), str)
            for pair in (route["free_talent_pair"],)
        }
        presented_route_ids = {
            route.get("route_id")
            for route in route_modules
            if isinstance(route, dict) and isinstance(route.get("route_id"), str)
        }
        presented_pair_count = len(presented_pair_keys)
        if (
            len(route_modules) < expected_pair_count
            or presented_pair_count < expected_pair_count
            or len(route_modules) != presented_pair_count
            or len(route_modules) != len(presented_route_ids)
        ):
            request_binding = {
                key: request.get(key)
                for key in ("request_sha256", "content_lock_hash")
                if isinstance(request.get(key), str)
            }
            raise FoundryError(
                "CG1_PROVIDER_ACQUISITION_CONTRACT_UNSATISFIABLE",
                "The sealed acquisition count cannot be represented by complete distinct provider routes.",
                details={
                    "expected_pair_count": expected_pair_count,
                    "presented_pair_count": presented_pair_count,
                    "request_binding": request_binding,
                },
                status_code=422,
            )
    if route_modules:
        route_sphere_ids = [row["sphere_id"] for row in route_modules]
        # The full comparability catalogue is useful while selecting routes,
        # but once complete routes are chosen it would only repeat unrelated
        # Spheres in the provider request.  Retain the route-level contrast
        # (one profile per presented route) and drop unselected catalogue
        # profiles from the model-facing projection.
        route_sphere_id_set = set(route_sphere_ids)
        sphere_comparability_index = {
            **sphere_comparability_index,
            "profiles": [
                profile
                for profile in sphere_comparability_index.get("profiles") or []
                if isinstance(profile, dict)
                and profile.get("sphere_id") in route_sphere_id_set
            ],
        }
        allowed_high_level = _provider_compact_high_level_choices(
            allowed_high_level,
            route_sphere_ids=route_sphere_ids,
            background_package_linkage=compact_model.get("background_package_linkage") or {},
            owner_locks=owner_locks,
        )
        ordinary_shortlist = _provider_route_ordinary_shortlist(
            compact_model,
            route_modules,
            cue_limit=cue_limit,
            display_limit=display_limit,
        )
        acquisition_contract = _provider_acquisition_contract(
            request,
            compact_model,
            ordinary_shortlist,
            target_cl,
        )
        # The count remains frozen authority; all complete route alternatives
        # are presented as legal whole-pair options for the provider to choose.
        acquisition_contract["presented_legal_pairs"] = [
            deepcopy(route["free_talent_pair"])
            for route in route_modules
        ]
    else:
        allowed_high_level = _provider_compact_high_level_choices(
            allowed_high_level,
            route_sphere_ids=(),
            background_package_linkage=compact_model.get("background_package_linkage") or {},
            owner_locks=owner_locks,
        )
        ordinary_shortlist = base_ordinary_shortlist
        selected_free_ids = {
            row.get("talent_id")
            for row in acquisition_contract.get("presented_legal_pairs") or []
            if isinstance(row, dict) and isinstance(row.get("talent_id"), str)
        }
        if selected_free_ids:
            ordinary_shortlist = _provider_ordinary_shortlist(
                compact_model,
                target_cl=target_cl,
                cue_limit=cue_limit,
                display_limit=display_limit,
                required_ids=required_free_ids | selected_free_ids,
            )
    # Once the frozen contract presents exact first-cycle Sphere/free-Talent
    # pairs, ordinary Talents must stay inside those acquired Spheres.  The
    # route projection above intentionally presents several whole alternatives;
    # the response validator binds the final ordinary array to the selected
    # alternative rather than permitting cross-route mixing.
    presented_pair_sphere_ids = {
        row.get("sphere_id")
        for row in acquisition_contract.get("presented_legal_pairs") or []
        if isinstance(row, dict) and isinstance(row.get("sphere_id"), str)
    }
    if presented_pair_sphere_ids:
        ordinary_shortlist = {
            owner: rows
            for owner, rows in ordinary_shortlist.items()
            if owner in presented_pair_sphere_ids
        }
    presented_path_ids = {
        row["id"]
        for row in allowed_high_level.get("path_choice") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    presented_method_ids = {
        row["id"]
        for row in allowed_high_level.get("method_choice") or []
        if isinstance(row, dict) and isinstance(row.get("id"), str)
    }
    path_method_authority = envelope.get("path_method_authority")
    path_method_authority = path_method_authority if isinstance(path_method_authority, dict) else {}
    raw_method_grants = path_method_authority.get("method_granted_path_ids")
    raw_method_grants = raw_method_grants if isinstance(raw_method_grants, dict) else {}
    legal_method_path_pairs = sorted(
        {
            (method_id, path_id)
            for method_id, path_ids in raw_method_grants.items()
            if method_id in presented_method_ids and isinstance(path_ids, list)
            for path_id in path_ids
            if isinstance(path_id, str) and path_id in presented_path_ids
        }
    )
    if not legal_method_path_pairs:
        # Compatibility fixtures and older complete requests may encode the
        # same frozen relation as Path prerequisite IDs.  This is a fallback
        # projection only; it never invents compatibility.
        legal_method_path_pairs = sorted({
            (method_id, row["id"])
            for row in allowed_high_level.get("path_choice") or []
            if isinstance(row, dict) and row.get("id") in presented_path_ids
            for method_id in row.get("requires") or []
            if isinstance(method_id, str) and method_id in presented_method_ids
        })
    presented_legal_method_path_pairs = [
        {"method_id": method_id, "path_id": path_id}
        for method_id, path_id in legal_method_path_pairs
    ]
    raw_method_allocations = path_method_authority.get("method_allocation_by_id")
    raw_method_allocations = raw_method_allocations if isinstance(raw_method_allocations, dict) else {}
    presented_method_allocations = {
        method_id: deepcopy(raw_method_allocations[method_id])
        for method_id in sorted(presented_method_ids)
        if isinstance(raw_method_allocations.get(method_id), dict)
    }
    bounded_choice_contract = request.get("bounded_choice_contract")
    bounded_choice_contract = (
        bounded_choice_contract
        if isinstance(bounded_choice_contract, dict)
        else {}
    )
    bounded_choice_fields = bounded_choice_contract.get("fields")
    bounded_choice_fields = (
        bounded_choice_fields
        if isinstance(bounded_choice_fields, dict)
        else {}
    )
    advertised_bounded_choice_keys = sorted(
        key
        for key in bounded_choice_fields
        if isinstance(key, str) and key.strip() and key == key.strip()
    )
    unsupported_bounded_choice_keys = sorted(
        set(advertised_bounded_choice_keys) - _PROVIDER_SUPPORTED_BOUNDED_CHOICE_KEYS
    )
    if unsupported_bounded_choice_keys:
        raise FoundryError(
            "CG1_PROVIDER_BOUNDED_FIELD_UNSUPPORTED",
            "The sealed request advertises a bounded field without a supported model and validator representation.",
            details={"fields": unsupported_bounded_choice_keys},
            status_code=422,
        )
    starting_proficiency_contract = bounded_choice_contract.get(
        "starting_proficiency_choice_contract"
    )
    starting_proficiency_contract_ref: dict[str, Any] = {}
    if (
        isinstance(starting_proficiency_contract, dict)
        and starting_proficiency_contract.get("schema") == STARTING_PROFICIENCY_CONTRACT_SCHEMA
        and isinstance(starting_proficiency_contract.get("contract_sha256"), str)
        and re.fullmatch(r"[0-9a-f]{64}", starting_proficiency_contract["contract_sha256"])
    ):
        starting_proficiency_contract_ref = {
            "schema": STARTING_PROFICIENCY_CONTRACT_SCHEMA,
            "contract_sha256": starting_proficiency_contract["contract_sha256"],
            "advertised_fields": sorted(
                field
                for field in (
                    "path_skill_choices_by_path_id",
                    "origin_skill_choices_by_origin_id",
                    "background_language_choices_by_background_id",
                )
                if field in advertised_bounded_choice_keys
            ),
        }
    template = _provider_response_template(
        request_sha256=request_sha256,
        descriptive_context=descriptive_context,
        presented_choices_by_slot=allowed_high_level,
        ordinary_shortlist=ordinary_shortlist,
        target_cl=target_cl,
        subpath_required=subpath_required,
        acquisition_contract=acquisition_contract,
        background_package_linkage=compact_model.get("background_package_linkage") or {},
        background_ability_candidates=background_ability_candidates,
        selection_limits=selection_limits,
        legal_method_path_pairs=presented_legal_method_path_pairs,
        bounded_choice_fields=advertised_bounded_choice_keys,
        owner_locks=owner_locks,
    )
    represented_bounded_choice_keys = set(
        (template.get("bounded_choices") or {})
        if isinstance(template, dict)
        else {}
    )
    missing_bounded_choice_keys = sorted(
        set(advertised_bounded_choice_keys) - represented_bounded_choice_keys
    )
    if missing_bounded_choice_keys:
        raise FoundryError(
            "CG1_PROVIDER_BOUNDED_FIELD_AUTHORITY_INCOMPLETE",
            "The sealed request advertises a bounded field that cannot be represented by the current legal response template.",
            details={"fields": missing_bounded_choice_keys},
            status_code=422,
        )
    free_talent_ids = {
        row.get("talent_id")
        for row in acquisition_contract.get("presented_legal_pairs") or []
        if isinstance(row, dict) and isinstance(row.get("talent_id"), str)
    }
    # With complete route modules, the ordinary legality contract must not
    # re-expand each projected row to every CL at which the frozen catalogue
    # happens to mark it eligible.  That would expose a large mix-and-match
    # catalogue even though the model is required to choose one whole route.
    # Publish the exact per-route assignment first, then its small CL-wise
    # union for the existing validator.  The sealed envelope remains the
    # authority for the validator's final mechanical checks.
    presented_ordinary_ids_by_route_and_cl: dict[str, dict[str, list[str]]] = {}
    presented_ordinary_ids_by_cl: dict[str, list[str]] = {}
    if route_modules:
        for route in route_modules:
            route_id = route.get("route_id") if isinstance(route, dict) else None
            route_assignments = route.get("ordinary_talent_ids_by_cl") if isinstance(route, dict) else None
            if not isinstance(route_id, str) or not isinstance(route_assignments, dict):
                continue
            route_contract: dict[str, list[str]] = {}
            for cl in range(1, (target_cl or 0) + 1):
                talent_id = route_assignments.get(str(cl))
                if not isinstance(talent_id, str) or talent_id in free_talent_ids:
                    continue
                route_contract[str(cl)] = [talent_id]
                presented_ordinary_ids_by_cl.setdefault(str(cl), []).append(talent_id)
            if route_contract:
                presented_ordinary_ids_by_route_and_cl[route_id] = route_contract
        presented_ordinary_ids_by_cl = {
            cl: sorted(set(ids))
            for cl, ids in sorted(presented_ordinary_ids_by_cl.items())
        }
    elif type(target_cl) is int:
        # Compatibility fallback for requests which cannot publish a complete
        # route.  This path preserves the older shortlist-based legality
        # projection; route-bearing requests never take it.
        for cl in range(1, target_cl + 1):
            ids = sorted({
                row.get("id")
                for rows in ordinary_shortlist.values()
                for row in rows
                if isinstance(row, dict)
                and isinstance(row.get("id"), str)
                and cl in (row.get("eligible_cl") or [])
                and row.get("id") not in free_talent_ids
            })
            presented_ordinary_ids_by_cl[str(cl)] = ids
    revision_request = request.get("revision_request")
    revision_context: dict[str, Any] | None = None
    if isinstance(revision_request, dict):
        owner_notes = _provider_short_text(revision_request.get("owner_notes"), 2_000)
        blocker_codes = sorted({
            blocker.get("code")
            for blocker in revision_request.get("blockers") or []
            if isinstance(blocker, dict) and isinstance(blocker.get("code"), str)
        })
        revision_context = {
            "owner_notes": owner_notes,
            "blocker_codes": blocker_codes,
            "instruction": "Apply these owner revision notes while remaining inside the newly frozen choices and locks.",
        }
    point_buy_summary = {
        "rule": "27-point buy; each ability score is independently chosen from 8 through 15.",
        "abilities": list(_PROVIDER_POINT_BUY_ABILITIES),
        "allowed_values": list(_PROVIDER_POINT_BUY_COSTS),
        "cost_by_value": {str(key): value for key, value in sorted(_PROVIDER_POINT_BUY_COSTS.items())},
        "budget": 27,
        "exact_budget": 27,
        "cost_by_score": {str(key): value for key, value in sorted(_PROVIDER_POINT_BUY_COSTS.items())},
        "legal_score_presets": [
            {
                "scores": list(values),
                "cost": sum(_PROVIDER_POINT_BUY_COSTS[value] for value in values),
                "permutable_across_abilities": True,
            }
            for values in _PROVIDER_POINT_BUY_LEGAL_PRESETS
        ],
    }
    subpath_representation = (
        "selection_intent.by_slot.subpath_choice must contain one exact presented Subpath owned by the selected Path because the frozen Stage 1 slot requires one; choose from the presented Path-owned options."
        if subpath_required
        else
        "selection_intent.by_slot.subpath_choice must be an explicit empty array because the frozen Stage 1 slot is not due at this target CL; do not invent or select an unavailable Subpath."
    )
    presented_path_progression_ids_by_cl = {
        str(row["cl"]): sorted({
            path_id
            for path_id in row.get("path_ids") or []
            if isinstance(path_id, str)
        })
        for row in envelope.get("path_progression_choices") or []
        if isinstance(row, dict)
        and type(row.get("cl")) is int
        and (target_cl is None or row["cl"] <= target_cl)
        and any(isinstance(path_id, str) for path_id in row.get("path_ids") or [])
    }
    progression_cues = _provider_progression_cues(envelope, target_cl, cue_limit)
    # Keep the richer frozen milestone rows for the typed resolution map.  The
    # compact progression cue intentionally strips mechanics for its display
    # use, but doing so here would erase source-backed ASI constraints before
    # they reach the provider contract.
    milestone_rows_for_provider = [
        row
        for row in envelope.get("advancement_choice_milestones") or []
        if isinstance(row, dict)
        and isinstance(row.get("milestone_id"), str)
        and (
            target_cl is None
            or type(row.get("cl")) is not int
            or row["cl"] <= target_cl
        )
    ]
    milestone_resolution_contract = _provider_milestone_resolution_contract(
        envelope,
        milestone_rows_for_provider,
        presented_insight_ids=[
            row.get("id")
            for row in allowed_high_level.get("insight_priorities") or []
            if isinstance(row, dict) and isinstance(row.get("id"), str)
        ],
    )
    for milestone in milestone_resolution_contract.values():
        options = milestone.get("resolution_options") or {}
        destinations = {
            kind: option.get("destination")
            for kind, option in options.items()
            if kind in {"ability_score_change", "cultivation_insight_acquisition"}
            and isinstance(option, dict)
            and isinstance(option.get("destination"), str)
        }
        milestone["response_destinations"] = destinations
        # Keep this compatibility field adjacent to the richer constraints;
        # existing clients use it as a quick display filter.
        milestone["allowed_kinds"] = sorted(destinations)
    template_bounded_choices = template.get("bounded_choices") if isinstance(template, dict) else None
    if (
        isinstance(template_bounded_choices, dict)
        and "ability_score_changes_by_milestone_id" in template_bounded_choices
    ):
        template_bounded_choices["ability_score_changes_by_milestone_id"] = {
            milestone_id: None for milestone_id in sorted(milestone_resolution_contract)
        }
    required_selection_slots = [
        "path_choice",
        *(["method_choice"] if allowed_high_level.get("method_choice") else []),
        *(["foundation_choice"] if allowed_high_level.get("foundation_choice") else []),
        "background_choice",
        "background_sphere_choice",
        "background_talent_choice",
        "origin_insight_choice",
        *[
            slot_id
            for slot_id in ("sphere_priorities", "insight_priorities", "item_priorities")
            if allowed_high_level.get(slot_id)
        ],
        "advancement_skeleton",
    ]
    if subpath_required:
        required_selection_slots.insert(1, "subpath_choice")
    ordinary_talent_position_map: dict[str, dict[str, Any]] = {}
    if type(target_cl) is int and target_cl > 0:
        for effective_cl in range(1, target_cl + 1):
            row: dict[str, Any] = {
                "effective_cl": effective_cl,
                "array_index": effective_cl - 1,
                "destination": "acquisition_intent.ordinary_talent_ids",
                "mirror_destination": "selection_intent.by_slot.advancement_skeleton",
            }
            if route_modules:
                row["route_bound_ids"] = {
                    route.get("route_id"): route.get("ordinary_talent_ids_by_cl", {}).get(str(effective_cl))
                    for route in route_modules
                    if isinstance(route, dict)
                    and isinstance(route.get("route_id"), str)
                    and isinstance(route.get("ordinary_talent_ids_by_cl"), dict)
                    and isinstance(route.get("ordinary_talent_ids_by_cl", {}).get(str(effective_cl)), str)
                }
            else:
                # The full no-route CL allowlists already live once in the
                # response contract.  Reference that frozen map here rather
                # than copying a potentially catalogue-sized list into every
                # structural row; route-bearing production requests retain
                # their exact route-bound IDs above.
                row["allowed_ids_ref"] = (
                    "response_contract.presented_legal_ordinary_talent_ids_by_cl."
                    f"{effective_cl}"
                )
            ordinary_talent_position_map[str(effective_cl)] = row
    return {
        "schema": "TianxiaFoundry.CharacterCreationProviderPrompt.v2",
        "purpose": "bounded_character_creation_provider_adapter",
        "binding": {
            "project_id": request.get("project_id"),
            "project_revision": request.get("project_revision"),
            "target_cl": target_cl,
            "request_sha256": request_sha256,
        },
        "descriptive_context": descriptive_context,
        **(
            {"owner_gear_requirements": deepcopy(request["owner_gear_requirements"])}
            if isinstance(request.get("owner_gear_requirements"), list)
            and request["owner_gear_requirements"]
            else {}
        ),
        **({"most_relevant_to_owner_concept": deepcopy(request["concept_guidance"])}
           if request.get("concept_guidance") else {}),
        "sphere_comparability_index": sphere_comparability_index,
        **({"revision_context": revision_context} if revision_context is not None else {}),
        "response_contract": {
            "schema": DELEGATED_RESPONSE_SCHEMA,
            "required_fields": sorted(PREFERRED_RESPONSE_KEYS),
            "shape_only_template": True,
            "input_only_fields": ["project_id", "project_revision", "target_cl", "content_lock_hash"],
            "forbidden_top_level_response_keys": sorted({
                "project_id", "project_revision", "target_cl", "content_lock_hash", "advancement_skeleton",
            }),
            "ordinary_talent_field": "acquisition_intent.ordinary_talent_ids",
            "ordinary_talent_source": "At array index N, use only IDs from the exact CL assignment of one whole route in sphere_route_modules; mirror that ordered array into selection_intent.by_slot.advancement_skeleton. The route list is the sole ordinary-legality source when routes are present, and cross-route mixing is forbidden. For legacy no-route projections, use the fallback presented_legal_ordinary_talent_ids_by_cl map. This source is never a source for sphere_free_talent_pairs. The shape-only template intentionally contains no selected IDs.",
            "first_cycle_pair_source": "Copy each whole {sphere_id, talent_id} object exactly from presented_legal_first_cycle_pairs. Never compose a pair from background choices, allowed_choices_by_slot, or ordinary_talent_shortlist_by_sphere; the shape-only template intentionally contains no pair.",
            "advancement_skeleton_representation": "selection_intent.by_slot.advancement_skeleton must mirror that exact ordered array.",
            "path_choice_representation": "selection_intent.by_slot.path_choice must contain at least one exact presented Path ID; the shape-only template is not a selection example.",
            "path_progression_representation": "When path_choice contains more than one ID, bounded_choices.path_progression_by_cl must map every ambiguous CL through target_cl to exactly one selected Path ID from presented_legal_path_progression_ids_by_cl. With exactly one selected Path, keep path_progression_by_cl empty.",
            "presented_legal_path_progression_ids_by_cl": presented_path_progression_ids_by_cl,
            "method_choice_representation": "When presented, selection_intent.by_slot.method_choice must contain one exact Method ID that appears with every selected Path in presented_legal_method_path_pairs. For a one-Path response, copy one whole presented pair.",
            "presented_legal_method_path_pairs": deepcopy(presented_legal_method_path_pairs),
            "presented_method_allocation_by_id": presented_method_allocations,
            "foundation_choice_representation": "When presented, selection_intent.by_slot.foundation_choice must contain one exact presented Foundation ID. The Factory validates route compatibility.",
            "subpath_choice_representation": subpath_representation,
            "background_package_representation": "selection_intent.by_slot.background_choice, background_sphere_choice, and background_talent_choice must contain one exact, linkage-coherent presented package.",
            "origin_insight_representation": "selection_intent.by_slot.origin_insight_choice must contain an exact presented Origin Insight ID.",
            "planning_priority_representation": "Every required sphere_priorities, insight_priorities, and item_priorities slot must contain exact IDs from allowed_choices_by_slot. These are planning-only preferences: they never grant a Sphere, Talent, Insight, or Item and never authorize a free Talent pair.",
            "sphere_comparability_representation": "sphere_comparability_index is comparative flavor and planning context only; it cannot create mechanics or authorize choices.",
            "background_ability_representation": "bounded_choices.background_ability must contain one exact allowed ability for the selected Background.",
            "bounded_choice_representation": (
                "bounded_choices may contain only these exact keys from the sealed request: "
                f"{advertised_bounded_choice_keys!r}. Omit every other key; never rename "
                "keys or invent new ones."
            ),
            **(
                {
                    "starting_proficiency_choice_representation": (
                        "For each advertised starting-proficiency map, use exactly its "
                        "frozen choice-ID properties and select the exact required "
                        "number of distinct values from that property's enum. Path and "
                        "Background language arrays are exact-count selections; the "
                        "Origin map uses the same one-item array representation. Fixed "
                        "Background skills/tools remain server-owned metadata."
                    ),
                    "starting_proficiency_choice_contract_ref": starting_proficiency_contract_ref,
                }
                if starting_proficiency_contract_ref
                else {}
            ),
            "allowed_bounded_choice_keys": advertised_bounded_choice_keys,
            **({"foundation_initial_stage_contract": deepcopy(bounded_choice_fields["foundation_initial_stage"])} if "foundation_initial_stage" in bounded_choice_fields else {}),
            "required_selection_slots": required_selection_slots,
            "subpath_choice_required": subpath_required,
            "subpath_choice_minimum": 1 if subpath_required else 0,
            "ordinary_talent_array_length": target_cl,
            "array_position_semantics": "array index N is the ordinary Talent acquired at character level N+1",
            "ordinary_talent_position_map": ordinary_talent_position_map,
            "acquisition_intent_required_keys": sorted(
                set(PREFERRED_ACQUISITION_KEYS)
                | ({"trained_choices"} if isinstance(envelope.get("creation_training_contract"), dict) else set())
                | ({"forged_technique_concepts"} if isinstance(envelope.get("explicit_forging_contract"), dict) else set())
            ),
            "expected_acquisition_counts": deepcopy(acquisition_contract.get("expected_counts") or {}),
            "presented_legal_first_cycle_pairs": deepcopy(acquisition_contract.get("presented_legal_pairs") or []),
            **(
                {"presented_legal_ordinary_talent_ids_by_cl": presented_ordinary_ids_by_cl}
                if not route_modules
                else {
                    "presented_legal_ordinary_talent_ids_by_cl_ref": (
                        "sphere_route_modules[].ordinary_talent_ids_by_cl"
                    ),
                }
            ),
            "required_milestone_resolutions": milestone_resolution_contract,
            "milestone_resolution_rule": (
                "First choose one or more exact Path IDs and path_progression_by_cl. "
                "Advancement milestones are character-level: at each CL resolve exactly "
                "one advertised milestone, the one whose path_id is the Path you named "
                "for that CL in path_progression_by_cl. Milestones of other selected "
                "Paths at the same CL, and of unselected Paths, are not applicable: "
                "leave their placeholders null and never resolve them."
            ),
            "sphere_route_modules_ref": "sphere_route_modules",
            "cross_route_mixing_forbidden": bool(route_modules),
            "response_template": template,
            "return_exactly_one_json_object": True,
        },
        "selection_limits_by_slot": selection_limits,
        "bounded_choice_summary": {
            "ability_scores": point_buy_summary,
            "background_ability_candidates": background_ability_candidates,
            "milestone_and_path_progression_cues": {
                # Keep the applicability rule beside the progression cue.  The
                # complete typed map lives once in the response contract (to
                # stay inside the wire cap) and is referenced here so a model
                # still sees that a selected Path's CL4/CL8/etc. choice is
                # mandatory.
                "advancement_choice_milestones_ref": (
                    "response_contract.required_milestone_resolutions"
                ),
                "resolution_rule": (
                    "Resolve exactly one listed ASI or Insight option for each "
                    "milestone whose path_id appears in the selected Path IDs; "
                    "unselected Path milestones are not applicable."
                ),
                "path_progression_choices": progression_cues.get(
                    "path_progression_choices"
                ) or [],
            },
            "background_package_linkage": compact_model.get("background_package_linkage") or {},
        },
        "choice_row_contract": {
            "fields": {
                "id": "stable frozen allowed choice ID",
                "name": "human-readable display name",
                "cue": "short semantic decision cue",
                "owner": "owning sphere or path when supplied; ordinary rows use their enclosing sphere key",
                "requires": "nonempty frozen prerequisite IDs, when present",
                "eligible_cl": "ordinary shortlist CL positions where the ID is active",
            },
            "ordinary_shortlist_per_sphere": _PROVIDER_SHORTLIST_PER_SPHERE,
            "ordinary_shortlist_per_route": target_cl if route_modules and type(target_cl) is int else None,
        },
        "allowed_choices_by_slot": allowed_high_level,
        "ordinary_talent_shortlist_by_sphere": ordinary_shortlist,
        "sphere_route_modules": deepcopy(route_modules),
        "background_package_linkage": compact_model.get("background_package_linkage") or {},
        "instructions": [
            "Return exactly one JSON object, with no markdown, commentary, or second object.",
            f"Copy request_sha256 exactly as {request_sha256!r}; keep the project binding unchanged.",
            "Return only these six top-level keys: schema, request_sha256, selection_intent, acquisition_intent, bounded_choices, owner_descriptive_fields. project_id, project_revision, target_cl, content_lock_hash, and top-level advancement_skeleton are input-only and forbidden.",
            "The response_template is shape-only, not an answer. Select delegated IDs only from exact closed-world lists; delegated name/concept values must be distinct nonblank proposals, never labels or placeholders.",
            *(
                [
                    "The sealed title contract is also closed-world descriptive authority: when delegated, provide exactly one concise nonblank owner_descriptive_fields.identity.title; when owner-locked, copy it exactly. Never infer a title from the name, concept, catalog, or prose, and never provide conflicting title representations."
                ]
                if "identity.title" in descriptive_context
                else []
            ),
            *(
                [
                    "Owner-named catalog gear is required equipment when the legal kit choices and guaranteed coin cover it. Include each affordable owner_gear_requirements item_id through a kit choice, an Option B purchase, or a matching treasure chassis. Guaranteed coin means Path coin plus fixed or already chosen Background coin, counting each die at its minimum roll. Gear needing a lucky roll is optional and leaves both kit choices open. Owner-written alternatives are optional suggestions and never lock kit choices. Preserve other valid kit choices. The Factory will reject a requirement affordable with guaranteed coin that the plan omits."
                ]
                if request.get("owner_gear_requirements")
                else []
            ),
            "Method and Foundation IDs are a closed world backed by the exact pinned compiler corpus; choose only IDs in the presented allowed lists. Nonselectable IDs and response prose cannot grant mechanics or authority.",
            "Use allowed_choices_by_slot only for its matching selection_intent slot. For ordinary Talents, use one exact sphere_route_modules assignment at each CL and mirror that array into advancement_skeleton; never compose a free Sphere/Talent pair from these lists.",
            "For sphere_free_talent_pairs, copy whole pair objects exactly from response_contract.presented_legal_first_cycle_pairs. Never substitute a background Sphere, an ordinary Talent, or a mixed pair.",
            "When sphere_route_modules are presented, choose one complete module (or the exact required number), copy its whole free pair, and use only its ordinary_talent_ids_by_cl. These are closed-world legal choices; cross-route mixing is forbidden and every active CL must be distinct without server duplicate repair.",
            "Choose coherent Path, Method, Foundation, Background, Sphere, and Talent IDs; preserve owner locks; select a Subpath only when the frozen Stage 1 slot requires it.",
            f"Provide exactly {target_cl} ordinary talent IDs when target_cl is an integer (array index N is character level N+1), and copy that exact array into selection_intent.by_slot.advancement_skeleton.",
            "Follow response_contract.ordinary_talent_position_map: each effective CL fixes the zero-based array index, its destination, and the route-bound allowed ID(s); the mirror destination must be byte-for-byte the same ordered array.",
            "Include at least one exact presented Path ID. For multiple Paths, bounded_choices.path_progression_by_cl must choose one selected Path at each ambiguous CL using response_contract.presented_legal_path_progression_ids_by_cl; for one Path keep it empty.",
            "When method_choice is presented, include one Method ID forming a whole pair with every selected Path in response_contract.presented_legal_method_path_pairs; obey response_contract.presented_method_allocation_by_id for path_progression_by_cl and never infer Method rules from its name.",
            "When presented, include one coherent Foundation, one Path-owned Subpath when required, and one linkage-coherent Background/Sphere/Talent package; include an exact presented Origin Insight and every required planning-priority slot.",
            (
            "The required Subpath must be Path-owned and exact; the Factory remains final authority."
                if subpath_required
                else
                "Keep subpath_choice explicitly empty because the frozen Stage 1 slot is not due; do not invent one."
            ),
            "Planning Sphere, Insight, and Item priorities are exact matching IDs only; they do not grant/acquire content or authorize a free pair. Use sphere_comparability_index only for flavor/comparison, never mechanics.",
            "Include bounded_choices.background_ability as one exact allowed ability for the selected Background.",
            *(
                [
                    "For every advertised starting-proficiency map, include only its exact frozen choice-ID keys and choose the required distinct enum values; Path and Background language values are exact-count arrays, while Origin uses a one-item array. Fixed Background grants are server-owned and must not be authored in the response."
                ]
                if starting_proficiency_contract_ref
                else []
            ),
            (
                "bounded_choices may contain only these exact sealed-request keys: "
                f"{advertised_bounded_choice_keys!r}; omit every other key; never rename "
                "keys or invent new ones."
            ),
            "acquisition_intent must contain exactly sphere_free_talent_pairs, ordinary_talent_ids, and insight_occurrences, with explicit empty arrays when needed.",
            AUTOMATIC_INSIGHT_ADVICE,
            f"Return exactly {acquisition_contract.get('expected_counts', {}).get('sphere_free_talent_pairs')} Sphere/free-Talent pair object(s) when counted; copy each unchanged from response_contract.presented_legal_first_cycle_pairs, and no other pair is legal for this frozen route.",
            f"Return exactly {acquisition_contract.get('expected_counts', {}).get('ordinary_talent_ids')} distinct ordinary acquisition(s), distinct from free-Talent pair IDs.",
            "After selecting Path IDs and path_progression_by_cl, resolve exactly one advancement milestone per CL: the required_milestone_resolutions entry whose path_id is the Path named for that CL (milestones of other Paths at that CL stay null). For that entry choose one of its listed resolution_options. Put an ASI at bounded_choices.ability_score_changes_by_milestone_id.<milestone_id> using the shown constraints, or put one exact allowed Insight occurrence in acquisition_intent.insight_occurrences with that milestone_id. Unselected Path milestones are not applicable; an empty/null placeholder is not a resolution. Never invent milestones or use a top-level advancement array.",
            "Keep 27-point-buy scores legal; provide distinct nonblank name/concept proposals (never placeholders) and repeat owner-locked values exactly. Do not return target_cl, events, grants, or hashes other than request_sha256; the local Factory remains sole mechanical authority.",
        ],
        "authority": {
            "provider_mechanical_authority": False,
            "provider_direct_commit_allowed": False,
            "automatic_retries": 0,
            "local_two_isolated_compilations_required": True,
        },
    }




def _provider_wire_compact_payload(payload: dict[str, Any]) -> dict[str, Any]:
    """Deduplicate repeated, source-backed resolution data for the wire.

    The complete delegated envelope remains persisted and authoritative.  A
    large real request can nevertheless repeat the same Path rule and Insight
    profile once per milestone.  Keep every milestone, destination, and
    opaque ID in the provider projection, but move repeated typed records to a
    single bound table and replace them with deterministic references.  This
    is a transport projection only: no legal option is added or removed and no
    provider-facing text is interpreted as authority.
    """

    if not isinstance(payload, dict):
        return payload
    try:
        raw_size = len(canonical_json(payload).encode("utf-8"))
    except (TypeError, ValueError):
        # _provider_payload normally produces canonical JSON.  Preserve the
        # existing fail-closed serialization path if a malformed test/legacy
        # payload reaches this private projection helper.
        return payload
    if raw_size <= PROVIDER_PROMPT_TARGET_BYTES:
        return payload

    raw_contract = payload.get("response_contract")
    raw_milestones = raw_contract.get("required_milestone_resolutions") if isinstance(raw_contract, dict) else None
    if not isinstance(raw_contract, dict) or not isinstance(raw_milestones, dict) or not raw_milestones:
        # Some legacy large projections have no milestone map.  They retain
        # their existing cue/display degradation and hard-cap behavior; never
        # apply an unrelated lossy transform to them here.
        return payload

    # Keep the complete shortlist for the elision proof.  The later compact
    # projection intentionally removes display-only fields (including an
    # optional row owner); validating that reduced shape would allow a
    # malformed row to disappear merely because its evidence was stripped.
    original_shortlist = payload.get("ordinary_talent_shortlist_by_sphere")
    original_shortlist = deepcopy(original_shortlist) if isinstance(original_shortlist, dict) else original_shortlist
    compacted = deepcopy(payload)
    contract = compacted["response_contract"]
    milestones = contract["required_milestone_resolutions"]

    def valid_background_package_linkage(value: Any) -> bool:
        """Recognise only the complete provider linkage table shape.

        The top-level table is the one retained authority copy.  A malformed
        or partial nested table must stay present so a transport compaction
        cannot hide an invalid choice projection.
        """
        if not isinstance(value, dict):
            return False
        return all(
            isinstance(background_id, str)
            and bool(background_id.strip())
            and isinstance(packages, list)
            and all(isinstance(package, dict) for package in packages)
            for background_id, packages in value.items()
        )

    linkage_deduplicated = False
    bounded_summary = compacted.get("bounded_choice_summary")
    nested_linkage = (
        bounded_summary.get("background_package_linkage")
        if isinstance(bounded_summary, dict)
        else None
    )
    top_level_linkage = compacted.get("background_package_linkage")
    if (
        valid_background_package_linkage(nested_linkage)
        and valid_background_package_linkage(top_level_linkage)
    ):
        try:
            linkage_matches = (
                canonical_json(nested_linkage).encode("utf-8")
                == canonical_json(top_level_linkage).encode("utf-8")
            )
        except (TypeError, ValueError):
            linkage_matches = False
        if linkage_matches:
            bounded_summary.pop("background_package_linkage")
            bounded_summary["background_package_linkage_ref"] = "background_package_linkage"
            instructions = compacted.get("instructions")
            if isinstance(instructions, list):
                instructions.append(
                    "When bounded_choice_summary.background_package_linkage_ref is present, "
                    "resolve it to the complete top-level background_package_linkage table; "
                    "every background ID, package, source, eligibility, and order-bearing "
                    "list in that table remains authoritative and unchanged."
                )
            linkage_deduplicated = True

    ability_rules: dict[str, dict[str, Any]] = {}
    insight_profiles: dict[str, dict[str, Any]] = {}

    def stable_record_key(record: dict[str, Any]) -> str:
        # The digest is only a local reference key.  The complete record,
        # including its source path/hash or exact Insight parameters, remains
        # in the bound authority table.
        return sha256_json(record)[:24]

    for milestone_id in sorted(milestones):
        milestone = milestones[milestone_id]
        if not isinstance(milestone, dict):
            continue
        options = milestone.get("resolution_options")
        if not isinstance(options, dict):
            continue
        asi = options.get("ability_score_change")
        if isinstance(asi, dict) and isinstance(asi.get("constraints"), dict):
            constraints = asi["constraints"]
            key = stable_record_key(constraints)
            existing = ability_rules.get(key)
            if existing is not None and existing != constraints:
                # A cryptographic collision is not expected, but do not let
                # one turn into an accidental cross-milestone authority
                # alias if a malformed fixture supplies one.
                key = f"{key}-{sha256_json(constraints)[24:48]}"
            ability_rules[key] = deepcopy(constraints)
            asi["constraints_ref"] = (
                "milestone_resolution_authority.ability_score_change_rules." + key
            )
            del asi["constraints"]
        insight = options.get("cultivation_insight_acquisition")
        if isinstance(insight, dict):
            allowed_ids = insight.get("allowed_insight_ids")
            parameters = insight.get("parameters_by_insight_id")
            if isinstance(allowed_ids, list) and isinstance(parameters, dict):
                profile = {
                    "allowed_insight_ids": deepcopy(allowed_ids),
                    "parameters_by_insight_id": deepcopy(parameters),
                }
                key = stable_record_key(profile)
                existing = insight_profiles.get(key)
                if existing is not None and existing != profile:
                    key = f"{key}-{sha256_json(profile)[24:48]}"
                insight_profiles[key] = profile
                insight["authority_ref"] = (
                    "milestone_resolution_authority.cultivation_insight_profiles." + key
                )
                del insight["allowed_insight_ids"]
                del insight["parameters_by_insight_id"]

    if not ability_rules and not insight_profiles:
        return compacted if linkage_deduplicated else payload

    binding = compacted.get("binding")
    binding = binding if isinstance(binding, dict) else {}
    compacted["milestone_resolution_authority"] = {
        "schema": "TianxiaFoundry.ProviderMilestoneResolutionAuthority.v1",
        "origin": "frozen_delegated_choice_envelope",
        "request_sha256": binding.get("request_sha256"),
        "ability_score_change_rules": ability_rules,
        "cultivation_insight_profiles": insight_profiles,
    }
    contract["milestone_resolution_authority_ref"] = "milestone_resolution_authority"

    # If repeated typed records alone do not reach the wire target, remove
    # display-only name/cue text from ordinary shortlist rows.  Their stable
    # IDs and exact eligible CL assignments remain, and the complete route
    # modules still carry the ordered assignment the response must mirror.
    try:
        compact_size = len(canonical_json(compacted).encode("utf-8"))
    except (TypeError, ValueError):
        return payload
    if compact_size > _PROVIDER_WIRE_COMPACT_TARGET_BYTES:
        shortlist = compacted.get("ordinary_talent_shortlist_by_sphere")
        if isinstance(shortlist, dict):
            compact_shortlist: dict[str, list[dict[str, Any]]] = {}
            for owner in sorted(shortlist):
                rows = shortlist[owner]
                if not isinstance(rows, list):
                    continue
                projected_rows: list[dict[str, Any]] = []
                for row in rows:
                    if not isinstance(row, dict) or not isinstance(row.get("id"), str):
                        # Generated projections are well-formed.  Retaining an
                        # unexpected row unchanged avoids silently dropping a
                        # provider option if a legacy fixture is malformed.
                        projected_rows.append(deepcopy(row))
                        continue
                    eligible_cl = row.get("eligible_cl")
                    if not isinstance(eligible_cl, list):
                        eligible_cl = []
                    projected_rows.append({
                        "id": row["id"],
                        "eligible_cl": deepcopy(eligible_cl),
                    })
                if projected_rows:
                    compact_shortlist[owner] = projected_rows
            compacted["ordinary_talent_shortlist_by_sphere"] = compact_shortlist
            compacted["choice_row_contract"]["ordinary_shortlist_compact_fields"] = [
                "id", "eligible_cl",
            ]

    # Complete route modules are a closed-world source for ordinary IDs only
    # when the row can be reconstructed without guessing.  In particular,
    # merely finding an ID somewhere in any route is insufficient: owner and
    # every eligible CL must bind to one unique, well-formed route.
    route_modules = compacted.get("sphere_route_modules")
    route_modules = route_modules if isinstance(route_modules, list) else []
    routes_by_owner: dict[str, list[tuple[dict[str, Any], dict[int, str]]]] = {}
    routes_valid = bool(route_modules)
    seen_route_ids: set[str] = set()
    for route in route_modules:
        if not isinstance(route, dict):
            routes_valid = False
            continue
        owner = route.get("sphere_id")
        assignments = route.get("ordinary_talent_ids_by_cl")
        if not isinstance(owner, str) or not owner.strip() or not isinstance(assignments, dict) or not assignments:
            routes_valid = False
            continue
        normalized_assignments: dict[int, str] = {}
        for raw_cl, talent_id in assignments.items():
            if (
                not isinstance(raw_cl, str)
                or not raw_cl.isdigit()
                or int(raw_cl) <= 0
                or not isinstance(talent_id, str)
                or not talent_id.strip()
                or int(raw_cl) in normalized_assignments
            ):
                routes_valid = False
                break
            normalized_assignments[int(raw_cl)] = talent_id
        if not normalized_assignments:
            routes_valid = False
            continue
        route_id = route.get("route_id")
        if (
            not isinstance(route_id, str)
            or not route_id.strip()
            or route_id != route_id.strip()
            or route_id in seen_route_ids
        ):
            routes_valid = False
        else:
            seen_route_ids.add(route_id)
        free_pair = route.get("free_talent_pair")
        if free_pair is not None and (
            not isinstance(free_pair, dict)
            or free_pair.get("sphere_id") != owner
            or not isinstance(free_pair.get("talent_id"), str)
            or not free_pair.get("talent_id", "").strip()
        ):
            routes_valid = False
        ordered = [normalized_assignments[cl] for cl in sorted(normalized_assignments)]
        ordinary_ids = route.get("ordinary_talent_ids")
        if "ordinary_talent_ids" in route and (
            not isinstance(ordinary_ids, list) or ordinary_ids != ordered
        ):
            routes_valid = False
        routes_by_owner.setdefault(owner, []).append((route, normalized_assignments))
    if any(len(routes) != 1 for routes in routes_by_owner.values()):
        routes_valid = False

    # The route modules already carry the complete per-CL assignment.  The
    # position map repeats that same assignment once per route and CL, so it
    # can be reduced to a structural map plus a bound reference only after a
    # strict equality proof.  This is deliberately a wire-only transform:
    # the copied route modules remain the source of every exact Talent ID.
    position_map = contract.get("ordinary_talent_position_map")
    position_map_is_losslessly_routed = (
        routes_valid
        and isinstance(position_map, dict)
        and bool(position_map)
        and compact_size > _PROVIDER_WIRE_COMPACT_TARGET_BYTES
        and isinstance(binding.get("target_cl"), int)
        and type(binding.get("target_cl")) is int
        and binding["target_cl"] > 0
    )
    if position_map_is_losslessly_routed:
        target_cl = binding["target_cl"]
        expected_cl_keys = {str(effective_cl) for effective_cl in range(1, target_cl + 1)}
        if set(position_map) != expected_cl_keys:
            position_map_is_losslessly_routed = False
        else:
            for route in route_modules:
                assignments = route.get("ordinary_talent_ids_by_cl")
                if not isinstance(assignments, dict) or set(assignments) != expected_cl_keys:
                    position_map_is_losslessly_routed = False
                    break
            if position_map_is_losslessly_routed:
                for effective_cl in range(1, target_cl + 1):
                    key = str(effective_cl)
                    row = position_map.get(key)
                    expected_route_bound_ids = {
                        route["route_id"]: route["ordinary_talent_ids_by_cl"][key]
                        for route in route_modules
                    }
                    if (
                        not isinstance(row, dict)
                        or set(row) != {
                            "effective_cl",
                            "array_index",
                            "destination",
                            "mirror_destination",
                            "route_bound_ids",
                        }
                        or row.get("effective_cl") != effective_cl
                        or row.get("array_index") != effective_cl - 1
                        or row.get("destination") != "acquisition_intent.ordinary_talent_ids"
                        or row.get("mirror_destination") != "selection_intent.by_slot.advancement_skeleton"
                        or row.get("route_bound_ids") != expected_route_bound_ids
                    ):
                        position_map_is_losslessly_routed = False
                        break
    if position_map_is_losslessly_routed:
        compact_position_map: dict[str, dict[str, Any]] = {}
        for key in sorted(position_map, key=lambda value: int(value)):
            row = position_map[key]
            compact_position_map[key] = {
                "effective_cl": row["effective_cl"],
                "array_index": row["array_index"],
                "destination": row["destination"],
                "mirror_destination": row["mirror_destination"],
                "route_bound_ids_ref": "sphere_route_modules[].ordinary_talent_ids_by_cl",
            }
        contract["ordinary_talent_position_map"] = compact_position_map
        contract["ordinary_talent_position_map_route_bound_ids_ref"] = (
            "sphere_route_modules[].ordinary_talent_ids_by_cl"
        )
        compacted["instructions"].append(
            "The ordinary_talent_position_map rows retain exact CL/index and destination semantics; "
            "each route_bound_ids_ref resolves by route_id and effective_cl in "
            "sphere_route_modules[].ordinary_talent_ids_by_cl."
        )

    shortlist = original_shortlist
    shortlist_is_losslessly_routed = routes_valid and isinstance(shortlist, dict) and bool(shortlist)
    if shortlist_is_losslessly_routed:
        seen_shortlist_ids: set[str] = set()
        for owner, rows in shortlist.items():
            candidates = routes_by_owner.get(owner) if isinstance(owner, str) else None
            if not isinstance(owner, str) or not owner.strip() or not isinstance(rows, list) or not rows or len(candidates or []) != 1:
                shortlist_is_losslessly_routed = False
                break
            _route, assignments = candidates[0]
            for row in rows:
                if not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"].strip():
                    shortlist_is_losslessly_routed = False
                    break
                if "owner" in row and row.get("owner") != owner:
                    shortlist_is_losslessly_routed = False
                    break
                talent_id = row["id"]
                eligible_cl = row.get("eligible_cl")
                if (
                    not isinstance(eligible_cl, list)
                    or not eligible_cl
                    or any(type(cl) is not int or cl <= 0 for cl in eligible_cl)
                    or len(set(eligible_cl)) != len(eligible_cl)
                ):
                    shortlist_is_losslessly_routed = False
                    break
                if talent_id in seen_shortlist_ids:
                    shortlist_is_losslessly_routed = False
                    break
                seen_shortlist_ids.add(talent_id)
                eligible_set = set(eligible_cl)
                if any(assignments.get(cl) != talent_id for cl in eligible_set):
                    shortlist_is_losslessly_routed = False
                    break
                assigned_cl = {
                    cl for cl, assigned_id in assignments.items() if assigned_id == talent_id
                }
                if assigned_cl != eligible_set:
                    shortlist_is_losslessly_routed = False
                    break
            if not shortlist_is_losslessly_routed:
                break
    if shortlist_is_losslessly_routed:
        compacted["ordinary_talent_shortlist_by_sphere"] = {}
        compacted["ordinary_talent_shortlist_by_sphere_ref"] = (
            "sphere_route_modules[].ordinary_talent_ids_by_cl"
        )
        compacted["choice_row_contract"]["ordinary_shortlist_source"] = (
            "When route modules are present, their by-CL assignments are the "
            "complete ordinary Talent closed world."
        )

    # Each route's ordered list is derivable from its by-CL mapping.  Keep the
    # mapping (the validator-facing position authority) and remove only an
    # exact duplicate list after the complete route tree passed validation.
    if routes_valid:
        for route in route_modules:
            assignments = route.get("ordinary_talent_ids_by_cl")
            ordered = [
                assignments[str(cl)] for cl in sorted(
                    int(raw_cl) for raw_cl in assignments
                    if isinstance(raw_cl, str) and raw_cl.isdigit()
                )
            ] if isinstance(assignments, dict) else None
            if (
                isinstance(ordered, list)
                and ordered
                and route.get("ordinary_talent_ids") == ordered
            ):
                del route["ordinary_talent_ids"]

    compacted["instructions"].append(
        "For required_milestone_resolutions, resolve each constraints_ref or authority_ref "
        "through milestone_resolution_authority; these references carry the exact frozen "
        "source-backed rule and are the only legal resolution constraints."
    )
    compacted["instructions"].append(
        "When ordinary_talent_shortlist_by_sphere_ref is present, use the referenced "
        "sphere_route_modules by-CL assignments as the complete ordinary Talent source; "
        "if shortlist rows remain, their stable id and eligible_cl values remain "
        "closed-world and unchanged (display-only name/cue fields may also be present)."
    )
    return compacted



_FICLONE = 0x40049409


def _reflink_copy2(source: Any, target: Any) -> Any:
    """``shutil.copy2`` that clones the bytes when the filesystem can (byte-identical either way)."""

    source_path = Path(source)
    target_path = Path(target)
    if source_path.is_file() and not source_path.is_symlink() and _reflink_file(source_path, target_path):
        shutil.copystat(source_path, target_path)
        return target
    return shutil.copy2(source, target)


def _reflink_file(source: Path, target: Path) -> bool:
    """Clone ``source`` into ``target`` with FICLONE; False when unsupported."""

    import fcntl

    try:
        with open(source, "rb") as src_fh:
            with open(target, "wb") as dst_fh:
                fcntl.ioctl(dst_fh.fileno(), _FICLONE, src_fh.fileno())
    except (OSError, AttributeError):
        try:
            target.unlink()
        except OSError:
            pass
        return False
    return True

# Owner decisions a still-active run may carry into a scratch compilation.
_ACTIVE_RUN_OWNER_DECISIONS = frozenset({None, "ACCEPT_DESCRIPTIVE_FIELDS", "REPLACE_RESPONSE", "APPLY_DECISION"})

class CharacterCreationExecutionService:
    """Three transport policies over one locally authoritative character pipeline."""

    def __init__(
        self,
        db: Database,
        *,
        stage1: Any,
        provider: Any,
        project_store: Any,
        stage2: Any | None = None,
        character_sheets: Any | None = None,
        gm_exports: Any | None = None,
        portable_characters: Any | None = None,
        factory_authoring: Any | None = None,
        projections: Any | None = None,
        gm_consumer: Any | None = None,
        combat_readiness: Any | None = None,
        pipeline_factory: Callable[[Database], dict[str, Any]] | None = None,
        production_release: Any | None = None,
        owner_principal: str = "local-owner",
        timing_logger: Any | None = None,
    ):
        self.db = db
        self.stage1 = stage1
        self.provider = provider
        self.projects = project_store
        self.stage2 = stage2
        self.character_sheets = character_sheets
        self.gm_exports = gm_exports
        self.portable_characters = portable_characters
        self.factory_authoring = factory_authoring
        self.projections = projections
        self.gm_consumer = gm_consumer
        self.combat_readiness = combat_readiness
        self.pipeline_factory = pipeline_factory
        self.production_release = production_release
        self.owner_principal = owner_principal
        self.timing_logger = timing_logger or configure_timing_logger(db.settings.logs_dir)
        self.candidate_gm = CandidateGMCapsuleStore(db)
        # Candidate GM authoring has its own run-keyed namespace and consumes
        # the capsule store as its sole context authority.  It is deliberately
        # separate from the live project's Factory GM workspace.
        from character_creation.candidate_gm_authoring import CandidateGMAuthoringService

        self.candidate_gm_authoring = CandidateGMAuthoringService(
            db,
            provider=provider,
            capsule_store=self.candidate_gm,
        )
        # The route repository is a persistence seam only.  It never invokes
        # the provider or the Stage A shadow controller; legacy rows simply do
        # not have a corresponding binding.
        self.controller_routes = ControllerRoutePersistence(db)
        self.linear_walk = LinearWalkPersistence(db, self.controller_routes)
        # Finalization snapshots/restores the complete desktop data directory;
        # serialize the whole operation within this service instance so a
        # second request cannot interleave with that restore boundary.
        self._finalize_lock = threading.Lock()
        # The run whose finalize holds the lock, so the page can show
        # "Finalizing…" after a reload or in a second tab.
        self._finalizing_run_id: str | None = None
        self._manual_correction_summaries = ValidationResultCache(limit=16)
        self._route_request_hashes = ValidationResultCache(limit=16)

    def _project(self, project_id: str) -> dict[str, Any]:
        result = self.projects.get_project(project_id)
        # ``get_project`` parses ``project_json`` afresh on every call, so the
        # structure it hands back is already private to this caller and is
        # discarded when this function returns.  The defensive deepcopy that
        # used to wrap it duplicated the entire multi-megabyte project
        # document -- the dominant cost of every recovery projection -- while
        # isolating it from nothing that the parse had not already isolated.
        project = result.get("project") or result
        if isinstance(result.get("project"), dict):
            # These server-owned columns are the authoritative project envelope.
            # working_name is copied only as display content; it never replaces project_id.
            for key in ("project_id", "revision", "working_name"):
                if key in result:
                    project[key] = result[key]
        return project

    def _revision(self, project_id: str) -> int:
        return int(self._project(project_id).get("revision") or 0)

    def _content_lock_hash(self, project_id: str) -> str:
        project = self._project(project_id)
        lock = project.get("content_lock") or {}
        return str(lock.get("lock_hash") or project.get("content_lock_hash") or "")

    def _materialize_initial_path_progression(
        self,
        run: dict[str, Any],
        plan: dict[str, Any] | None,
        authority_db: Database,
        *,
        method_id: str,
        phase: str,
    ) -> dict[str, Any] | None:
        """Rebind the pristine native ledger to the exact server Path route."""
        if not isinstance(plan, dict):
            return None
        intent = plan.get("canonical_selection_intent")
        if not isinstance(intent, dict):
            return None
        selected_by_slot = intent.get("selected_by_slot")
        selected_path_ids = selected_by_slot.get("path_choice") if isinstance(selected_by_slot, dict) else None
        if isinstance(selected_path_ids, str):
            selected_path_ids = [selected_path_ids]
        if not isinstance(selected_path_ids, list) or not selected_path_ids:
            return None
        selected_path_ids = [path_id for path_id in selected_path_ids if isinstance(path_id, str)]
        bounded = intent.get("bounded_choices")
        bounded = bounded if isinstance(bounded, dict) else {}
        raw_progression = bounded.get("path_progression_by_cl")
        target_cl = intent.get("target_cl")
        if not isinstance(target_cl, int) or isinstance(target_cl, bool):
            target_cl = plan.get("target_cl")
        if not isinstance(target_cl, int) or isinstance(target_cl, bool):
            raise FoundryError(
                "CG1_METHOD_PATH_PROGRESSION_TARGET_INVALID",
                "Exact Path progression materialization requires the server-bound target CL.",
                details={"method_id": method_id, "phase": phase},
                status_code=409,
            )
        if not isinstance(raw_progression, dict):
            if len(selected_path_ids) <= 1:
                return None
            raise FoundryError(
                "CG1_METHOD_PATH_PROGRESSION_REQUIRED",
                "Exact multi-Path Method materialization requires the server-bound Path progression map.",
                details={"method_id": method_id, "selected_path_ids": selected_path_ids, "phase": phase},
                status_code=409,
            )
        if not raw_progression:
            if len(selected_path_ids) > 1:
                raise FoundryError(
                    "CG1_METHOD_PATH_PROGRESSION_REQUIRED",
                    "Exact multi-Path Method materialization requires the server-bound Path progression map.",
                    details={"method_id": method_id, "selected_path_ids": selected_path_ids, "phase": phase},
                    status_code=409,
                )
            # The provider contract deliberately represents a sole selected
            # Path with an empty map.  Native NS1R still needs one exact route
            # entry per CL, so expand only that authenticated singleton here.
            raw_progression = {
                str(effective_cl): selected_path_ids[0]
                for effective_cl in range(1, target_cl + 1)
            }
        progression: dict[int, str] = {}
        for raw_cl, path_id in raw_progression.items():
            if isinstance(raw_cl, bool):
                raise FoundryError(
                    "CG1_METHOD_PATH_PROGRESSION_INVALID",
                    "The server-bound Path progression map contains an invalid CL key.",
                    details={"cl": raw_cl, "phase": phase},
                    status_code=409,
                )
            if isinstance(raw_cl, int):
                effective_cl = raw_cl
            elif isinstance(raw_cl, str) and raw_cl.isdigit() and str(int(raw_cl)) == raw_cl:
                effective_cl = int(raw_cl)
            else:
                raise FoundryError(
                    "CG1_METHOD_PATH_PROGRESSION_INVALID",
                    "The server-bound Path progression map contains an invalid CL key.",
                    details={"cl": raw_cl, "phase": phase},
                    status_code=409,
                )
            if effective_cl in progression:
                raise FoundryError(
                    "CG1_METHOD_PATH_PROGRESSION_INVALID",
                    "The server-bound Path progression map contains duplicate CL entries.",
                    details={"cl": effective_cl, "phase": phase},
                    status_code=409,
                )
            progression[effective_cl] = path_id
        # The proposal is already server-derived from this intent. Cross-check
        # its level rows so the native ledger cannot drift from the Stage 2 route
        # that will be committed immediately afterward.
        stage2_choices = (plan.get("stage2_proposal") or {}).get("choices")
        stage2_progression: dict[int, str] = {}
        if isinstance(stage2_choices, list):
            for row in stage2_choices:
                if not isinstance(row, dict) or row.get("kind") != "level_advance":
                    continue
                effective_cl = row.get("effective_cl")
                record_id = row.get("record_id")
                if not isinstance(effective_cl, int) or not isinstance(record_id, str) or ".feature." not in record_id:
                    continue
                path_id = record_id.split(".feature.", 1)[0]
                if effective_cl in stage2_progression and stage2_progression[effective_cl] != path_id:
                    raise FoundryError(
                        "CG1_METHOD_PATH_PROGRESSION_STAGE2_MISMATCH",
                        "The server-derived Stage 2 proposal contains conflicting Path routes for one CL.",
                        details={"cl": effective_cl, "phase": phase},
                        status_code=409,
                    )
                stage2_progression[effective_cl] = path_id
        if len(selected_path_ids) > 1 and stage2_progression != progression:
            raise FoundryError(
                "CG1_METHOD_PATH_PROGRESSION_STAGE2_MISMATCH",
                "The exact native Path rebind does not match the server-derived Stage 2 progression route.",
                details={
                    "method_id": method_id,
                    "bounded_progression": progression,
                    "stage2_progression": stage2_progression,
                    "phase": phase,
                },
                status_code=409,
            )
        authority = NonSphereAuthorityService(authority_db)
        return authority.rebind_initial_path_progression(
            run["project_id"],
            method_id=method_id,
            selected_path_ids=selected_path_ids,
            progression_by_cl=progression,
            target_cl=target_cl,
            _creation_authority=_TRUSTED_CHARACTER_CREATION_PROGRESS_REBIND,
            _equal_initial_attainment=equal_initial_path_attainment(run.get("request") or {}),
        )

    def _choice_snapshot(self, project_id: str) -> dict[str, Any]:
        return materialize_choice_snapshot(self._project(project_id))

    def _materialize_method_exact_choice(
        self,
        run: dict[str, Any],
        authority_db: Database,
        *,
        phase: str,
        plan: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Materialize a server-derived exact Method route during local compilation."""
        if authority_db is self.db:
            project = self.projects.get_project(run["project_id"])
        else:
            from project_store.service import ProjectStore
            project = ProjectStore(authority_db).get_project(run["project_id"])
        envelope = deepcopy(project.get("project") or project)
        locks = {
            row.get("field"): row.get("value")
            for row in envelope.get("user_locks", []) if isinstance(row, dict)
        }
        mode = locks.get("character_sheet.method_planning_mode")
        access_plan = deepcopy(locks.get("character_sheet.method_access_plan") or {})
        authority = NonSphereAuthorityService(authority_db)
        route_origin = "owner_plan"
        if mode not in {"EXACT", "HARD_LOCK"} or not access_plan:
            if mode == "HARD_LOCK" and not access_plan:
                # Accepted pre-WIN1-P1R2 project compatibility: those projects put
                # the Method directly in the locked state and never authored a route.
                return None
            # AUTO planning, or an owner who authored no route: the accepted
            # plan's Method is the Factory's choice, and its learning route is
            # constructed from the frozen request (owner ruling 2026-09-06).
            method_id = self._accepted_method_id(plan)
            if not method_id:
                return None
            access_plan = self._constructed_method_access_plan(run, authority, method_id)
            route_origin = "factory_constructed"
        method_id = access_plan.get("method_id")
        required = (
            "schema", "method_id", "access_tier", "route_type", "route_label",
            "source_reference", "source_route_sha256", "route_commitment_sha256",
            "method_registry_commitment_sha256", "status",
        )
        missing = [field for field in required if access_plan.get(field) in (None, "", {})]
        if access_plan.get("schema") != "TianxiaFoundry.MethodAccessPlan.v2" or missing:
            raise FoundryError(
                "CG1_METHOD_ACCESS_PLAN_INCOMPLETE",
                "The selected Method has no complete legal learning route; return to Describe and choose another Method or learning route.",
                details={"method_id": method_id, "missing_fields": missing},
            )
        method = authority.methods.get(method_id)
        evidence_targets = {
            key: deepcopy(access_plan[key])
            for key in (
                "method_id", "access_tier", "route_type", "route_label",
                "owner_annotation", "source_reference", "source_route_sha256", "route_commitment_sha256",
                "method_registry_commitment_sha256",
            )
        }
        if method is None:
            raise FoundryError("CG1_METHOD_ACCESS_PLAN_STALE", "The selected Method is no longer installed.", details={"method_id": method_id})
        authority._validate_authority_targets("method_access", evidence_targets)
        receipt = {
            "schema": "TianxiaFoundry.MethodAccessCompilationReceipt.v2",
            "method_id": method_id,
            "route_origin": route_origin,
            "access_plan": access_plan,
            "evidence_required": True,
            "evidence_authority_type": "method_access",
            "primary_method_id": method_id,
            "canonical_mutation_boundary": "VALIDATED_LOCAL_COMPILATION",
        }
        evidence = authority.commit_authority_event(
            run["project_id"], "method_access", evidence_targets,
            creation_authority="PROJECT_AUTHORITY_SERVICE",
            idempotency_key=f"cg1.method-access:{run['run_id']}:{method_id}",
        )
        receipt["evidence_id"] = evidence["evidence_id"]
        if plan is not None:
            self._materialize_initial_path_progression(
                run,
                plan,
                authority_db,
                method_id=method_id,
                phase=phase,
            )
        state = authority.get_state(run["project_id"])
        if state.get("primary_method_id") == method_id:
            return receipt
        updated = authority.set_primary_method(
            run["project_id"], method_id,
            access_source_records=([evidence["evidence_id"]] if evidence else None),
        )
        if updated.get("primary_method_id") != method_id:
            raise FoundryError("CG1_METHOD_ACCESS_COMMIT_FAILED", "The validated Method access route did not materialize its Primary Method.", details={"method_id": method_id})
        return receipt

    @staticmethod
    def _accepted_method_id(plan: dict[str, Any] | None) -> str | None:
        """The Method the accepted plan selected, if any."""

        if not isinstance(plan, dict):
            return None
        resolution = plan.get("resolution")
        method_id = resolution.get("method_id") if isinstance(resolution, dict) else None
        if not method_id:
            intent = plan.get("canonical_selection_intent")
            selected = (intent.get("selected_by_slot") or {}).get("method_choice") if isinstance(intent, dict) else None
            method_id = selected[0] if isinstance(selected, list) and selected else None
        return method_id if isinstance(method_id, str) and method_id else None

    @staticmethod
    def _constructed_method_access_plan(run: dict[str, Any], authority: Any, method_id: str) -> dict[str, Any]:
        """Build the exact access plan for a Factory-chosen Method.

        An open-tier Method resolves through its published open route.  A
        restricted Method uses the constructed route the frozen request
        advertised for it; without one the compile fails closed rather than
        inventing access.
        """

        method = authority.methods.get(method_id)
        if method is None:
            raise FoundryError("CG1_METHOD_ACCESS_PLAN_STALE", "The selected Method is no longer installed.", details={"method_id": method_id})
        if authority.method_initial_creation_satisfied(method):
            return authority.resolve_initial_method_access(method_id, route_choice=None, owner_annotation=None)
        envelope = ((run.get("request") or {}).get("delegated_choice_envelope") or {})
        access = ((envelope.get("path_method_authority") or {}).get("method_access_by_id") or {}).get(method_id) or {}
        route = access.get("constructed_access_route") if isinstance(access, dict) else None
        if not isinstance(route, dict) or not isinstance(route.get("choice_id"), str):
            raise FoundryError(
                "CG1_METHOD_ACCESS_ROUTE_MISSING",
                "The accepted Method needs a learning route and the frozen request advertised none the Factory may construct.",
                details={"method_id": method_id, "access_tier": access.get("access_tier") if isinstance(access, dict) else None},
            )
        return authority.resolve_initial_method_access(
            method_id,
            route_choice=route["choice_id"],
            owner_annotation=f"Factory-constructed learning route: {route.get('label') or route.get('typed_route')}",
        )

    # Compatibility for focused callers created during WIN1-P1R2.
    def _materialize_method_hard_lock(
        self,
        run: dict[str, Any],
        authority_db: Database,
        *,
        phase: str,
        plan: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        receipt = self._materialize_method_exact_choice(run, authority_db, phase=phase, plan=plan)
        self._sync_accepted_foundation(run, NonSphereAuthorityService(authority_db), plan)
        return receipt

    @staticmethod
    def _accepted_foundation_id(plan: dict[str, Any] | None) -> str | None:
        """The Foundation the accepted plan selected, if any."""

        if not isinstance(plan, dict):
            return None
        resolution = plan.get("resolution")
        foundation_id = resolution.get("foundation_id") if isinstance(resolution, dict) else None
        if not foundation_id:
            intent = plan.get("canonical_selection_intent")
            selected = (intent.get("selected_by_slot") or {}).get("foundation_choice") if isinstance(intent, dict) else None
            foundation_id = selected[0] if isinstance(selected, list) and selected else None
        return foundation_id if isinstance(foundation_id, str) and foundation_id else None

    def _sync_accepted_foundation(self, run: dict[str, Any], authority: Any, plan: dict[str, Any] | None) -> str | None:
        """Mirror the accepted plan's Foundation into the builder state.

        The Primary Method already reaches the non-sphere builder state during
        compilation; without the same for the Foundation the builder panel
        shows "No Foundation selected" under a sheet whose Foundation is active.
        """
        foundation_id = self._accepted_foundation_id(plan)
        if not foundation_id:
            return None
        state = authority.get_state(run["project_id"])
        if state.get("foundation_id") == foundation_id:
            return foundation_id
        updated = authority.select_foundation(run["project_id"], foundation_id)
        if updated.get("foundation_id") != foundation_id:
            raise FoundryError(
                "CG1_FOUNDATION_COMMIT_FAILED",
                "The accepted Foundation did not materialize in the builder state.",
                details={"foundation_id": foundation_id},
            )
        return foundation_id

    def _require_frozen_choice_snapshot(self, run: dict[str, Any]) -> dict[str, Any]:
        expected = run.get("request", {}).get("typed_choice_snapshot") or {}
        actual = self._choice_snapshot(run["project_id"])
        if not valid_choice_snapshot(expected) or actual != expected:
            raise FoundryError(
                "CG1_TYPED_CHOICE_SNAPSHOT_STALE",
                "Committed project choices changed after the build request was frozen.",
                details={
                    "expected_snapshot_sha256": expected.get("snapshot_sha256"),
                    "actual_snapshot_sha256": actual.get("snapshot_sha256"),
                    "project_id": run["project_id"],
                    "project_revision": actual.get("project_revision"),
                },
                status_code=409,
            )
        return expected

    @property
    def owner_principal_hash(self) -> str:
        return sha256_bytes(self.owner_principal.encode("utf-8"))

    def preference(self, project_id: str) -> dict[str, Any]:
        self._project(project_id)
        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT execution_mode,updated_at FROM character_creation_preferences "
                "WHERE project_id=? AND owner_principal_hash=?",
                (project_id, self.owner_principal_hash),
            ).fetchone()
        return {
            "schema": "TianxiaFoundry.CharacterCreationExecutionPreference.v1",
            "project_id": project_id,
            "owner_principal_hash": self.owner_principal_hash,
            "execution_mode": row["execution_mode"] if row else "MANUAL_CHAT",
            "explicit": bool(row),
            "updated_at": row["updated_at"] if row else None,
        }

    def set_preference(self, project_id: str, execution_mode: str) -> dict[str, Any]:
        mode = str(execution_mode or "").strip().upper()
        if mode not in MODES:
            raise FoundryError("CG1_EXECUTION_MODE_INVALID", "Choose Manual Chat, Standard API, or Auto-Finalize When Clean.")
        self._project(project_id)
        with self.db.transaction() as conn:
            conn.execute(
                "INSERT INTO character_creation_preferences(project_id,owner_principal_hash,execution_mode,updated_at) "
                "VALUES(?,?,?,?) ON CONFLICT(project_id,owner_principal_hash) DO UPDATE SET "
                "execution_mode=excluded.execution_mode,updated_at=excluded.updated_at",
                (project_id, self.owner_principal_hash, mode, utcnow()),
            )
        return self.preference(project_id)

    @staticmethod
    def _loads(row: Any, key: str, default: Any) -> Any:
        value = row[key]
        return json.loads(value) if value else deepcopy(default)

    def _attempt_history(self, run_id: str) -> list[dict[str, Any]]:
        """Read the append-only response/build-attempt ledger for one run."""
        with self.db.connection() as conn:
            rows = conn.execute(
                "SELECT * FROM character_creation_attempt_history WHERE run_id=? ORDER BY ordinal",
                (run_id,),
            ).fetchall()
        result: list[dict[str, Any]] = []
        for row in rows:
            item = dict(row)
            for key, default in (
                ("canonical_intent_json", {}),
                ("materialization_receipt_json", {}),
                ("validation_json", {}),
                ("quality_json", {}),
                ("binding_json", {}),
                ("links_json", {}),
                ("blockers_json", []),
                ("error_json", {}),
            ):
                raw = item.get(key)
                try:
                    item[key.removesuffix("_json")] = json.loads(raw) if raw else deepcopy(default)
                except (TypeError, json.JSONDecodeError):
                    item[key.removesuffix("_json")] = deepcopy(default)
                item.pop(key, None)
            # Keep the exact bounded response available to the owner while
            # also exposing its digest in the compact projection.
            response_bytes = item.pop("response_bytes", None)
            if response_bytes is not None:
                if isinstance(response_bytes, memoryview):
                    response_bytes = response_bytes.tobytes()
                item["response_byte_count"] = len(response_bytes) if isinstance(response_bytes, (bytes, bytearray)) else None
                item["response_bytes_sha256"] = sha256_bytes(bytes(response_bytes)) if isinstance(response_bytes, (bytes, bytearray)) else None
            result.append(item)
        return result

    def _append_attempt(
        self,
        run: dict[str, Any] | str,
        *,
        action_type: str,
        status: str,
        response_text: str | None = None,
        canonical_intent: dict[str, Any] | None = None,
        materialization_receipt: dict[str, Any] | None = None,
        validation: dict[str, Any] | None = None,
        quality: dict[str, Any] | None = None,
        candidate_identity: str | None = None,
        materialized_plan_sha256: str | None = None,
        submitted_plan_sha256: str | None = None,
        prior_attempt_id: str | None = None,
        binding: dict[str, Any] | None = None,
        blockers: list[dict[str, Any]] | None = None,
        error: dict[str, Any] | None = None,
        links: dict[str, Any] | None = None,
        completed: bool = True,
        _transaction_conn: sqlite3.Connection | None = None,
    ) -> str:
        """Append one immutable attempt row; never update a prior attempt."""
        current = self.get(run) if isinstance(run, str) else run
        transaction_context = self.db.transaction() if _transaction_conn is None else nullcontext(_transaction_conn)
        with transaction_context as conn:
            ordinal = int(
                conn.execute(
                    "SELECT COALESCE(MAX(ordinal),0)+1 FROM character_creation_attempt_history WHERE run_id=?",
                    (current["run_id"],),
                ).fetchone()[0]
            )
            digest_material = {
                "run_id": current["run_id"],
                "ordinal": ordinal,
                "action_type": action_type,
                "status": status,
                "response_sha256": sha256_bytes(response_text.encode("utf-8")) if isinstance(response_text, str) else None,
                "prior_attempt_id": prior_attempt_id,
            }
            attempt_id = "cg1.attempt." + sha256_json(digest_material)[:40]
            request = current.get("request") or {}
            response = current.get("response") or {}
            exact_response = response_text if response_text is not None else response.get("exact_response_text")
            response_sha = (
                sha256_bytes(exact_response.encode("utf-8"))
                if isinstance(exact_response, str)
                else response.get("response_sha256")
            )
            now = utcnow()
            conn.execute(
                """INSERT INTO character_creation_attempt_history(
                   attempt_id,run_id,project_id,ordinal,action_type,status,
                   request_sha256,response_sha256,response_bytes,response_text,canonical_intent_json,
                   materialization_receipt_json,validation_json,quality_json,candidate_identity,
                   materialized_plan_sha256,submitted_plan_sha256,prior_attempt_id,binding_json,links_json,
                   blockers_json,error_json,created_at,completed_at)
                   VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    attempt_id,
                    current["run_id"],
                    current["project_id"],
                    ordinal,
                    action_type,
                    status,
                    request.get("request_sha256"),
                    response_sha,
                    exact_response.encode("utf-8") if isinstance(exact_response, str) else None,
                    exact_response,
                    canonical_json(canonical_intent or {}),
                    canonical_json(materialization_receipt or {}),
                    canonical_json(validation or {}),
                    canonical_json(quality or {}),
                    candidate_identity or (current.get("dry_run") or {}).get("candidate_identity"),
                    materialized_plan_sha256,
                    submitted_plan_sha256,
                    prior_attempt_id,
                    canonical_json(binding or {}),
                    canonical_json(links or {}),
                    canonical_json(blockers or []),
                    canonical_json(error or {}),
                    now,
                    now if completed else None,
                ),
            )
        return attempt_id

    def _latest_attempt_id(self, run_id: str) -> str | None:
        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT attempt_id FROM character_creation_attempt_history WHERE run_id=? ORDER BY ordinal DESC LIMIT 1",
                (run_id,),
            ).fetchone()
        return row["attempt_id"] if row else None

    @staticmethod
    def _stage1_prior_attempt_id(db: Database, prompt_id: str | None, attempt_id: str | None) -> str | None:
        """Return an attempt ID only when it belongs to Stage 1's ledger.

        Character-creation history and Stage 1 validation intentionally have
        separate append-only ledgers.  Their IDs currently share a readable
        prefix, but Stage 1's ``prior_attempt_id`` is a foreign key to
        ``stage1_response_attempts``; passing a creation-history ID here makes
        a valid owner retry fail with a database foreign-key error when the
        first response was blocked before Stage 1 validation ran.
        """
        if not isinstance(prompt_id, str) or not prompt_id or not isinstance(attempt_id, str) or not attempt_id:
            return None
        with db.connection() as conn:
            row = conn.execute(
                "SELECT attempt_id FROM stage1_response_attempts WHERE attempt_id=? AND prompt_id=?",
                (attempt_id, prompt_id),
            ).fetchone()
        return row["attempt_id"] if row else None

    @staticmethod
    def _descriptive_fields(value: Any) -> dict[str, Any]:
        raw = value if isinstance(value, dict) else {}
        identity = raw.get("identity") if isinstance(raw.get("identity"), dict) else {}
        name = str(identity.get("name") or raw.get("name") or "").strip() or None
        concept = str(raw.get("concept") or raw.get("character_concept") or "").strip() or None
        result = {"identity": {"name": name}, "concept": concept}
        if "title" in identity or "title" in raw:
            title_value = identity.get("title") if "title" in identity else raw.get("title")
            result["identity"]["title"] = (
                title_value.strip()
                if isinstance(title_value, str) and title_value.strip()
                else None
            )
        return result

    @staticmethod
    def _has_canonical_descriptive_fields(value: Any) -> bool:
        if not isinstance(value, dict) or not isinstance(value.get("identity"), dict):
            return False
        name = value["identity"].get("name")
        concept = value.get("concept")
        title = value["identity"].get("title") if "title" in value["identity"] else None
        return (
            isinstance(name, str)
            and bool(name.strip())
            and isinstance(concept, str)
            and bool(concept.strip())
            and (
                "title" not in value["identity"]
                or (isinstance(title, str) and bool(title.strip()))
            )
        )

    @classmethod
    def _descriptive_from_response_text(cls, response_text: str) -> dict[str, Any]:
        try:
            value = json.loads(response_text)
        except (TypeError, json.JSONDecodeError):
            return cls._descriptive_fields({})
        if isinstance(value, dict) and isinstance(value.get("owner_descriptive_fields"), dict):
            value = value["owner_descriptive_fields"]
        return cls._descriptive_fields(value)

    @staticmethod
    def _proposal_projection(value: Any) -> dict[str, Any]:
        """Project parsed planner intent without promoting it to mechanics.

        This bounded projection is retained even when a later request-binding,
        semantic, legality, or compilation boundary rejects the response.  It
        is deliberately separate from ``response_json``: the exact response
        bytes remain immutable evidence, while this view is an owner-readable
        planning receipt and never a replacement response.
        """
        if not isinstance(value, dict):
            return {}
        selection = value.get("selection_intent")
        selected_by_slot = selection.get("by_slot") if isinstance(selection, dict) else {}
        selected_by_slot = selected_by_slot if isinstance(selected_by_slot, dict) else {}

        def bounded_ids(rows: Any, limit: int = 512) -> list[str]:
            if not isinstance(rows, list):
                return []
            return [row for row in rows[:limit] if isinstance(row, str) and row.strip()]

        selected = {
            str(slot): bounded_ids(rows)
            for slot, rows in selected_by_slot.items()
            if isinstance(slot, str) and isinstance(rows, list)
        }
        acquisition = value.get("acquisition_intent")
        acquisition = acquisition if isinstance(acquisition, dict) else {}
        pairs = []
        for row in acquisition.get("sphere_free_talent_pairs") or []:
            if isinstance(row, dict) and isinstance(row.get("sphere_id"), str) and isinstance(row.get("talent_id"), str):
                pairs.append({"sphere_id": row["sphere_id"], "talent_id": row["talent_id"]})
                if len(pairs) >= 512:
                    break
        occurrences = []
        for row in acquisition.get("insight_occurrences") or []:
            if not isinstance(row, dict) or not isinstance(row.get("insight_id"), str) or not isinstance(row.get("milestone_id"), str):
                continue
            item = {"insight_id": row["insight_id"], "milestone_id": row["milestone_id"]}
            if isinstance(row.get("parameters"), dict):
                item["parameters"] = deepcopy(row["parameters"])
            occurrences.append(item)
            if len(occurrences) >= 512:
                break
        bounded = value.get("bounded_choices") if isinstance(value.get("bounded_choices"), dict) else {}
        identity = value.get("owner_descriptive_fields") if isinstance(value.get("owner_descriptive_fields"), dict) else {}
        identity_row = identity.get("identity") if isinstance(identity.get("identity"), dict) else {}
        projected_identity = {
            "name": str(identity_row.get("name") or "").strip() or None,
            "concept": str(identity.get("concept") or "").strip() or None,
        }
        if "title" in identity_row or "title" in identity:
            title_value = identity_row.get("title") if "title" in identity_row else identity.get("title")
            projected_identity["title"] = (
                title_value.strip()
                if isinstance(title_value, str) and title_value.strip()
                else None
            )
        projected_acquisition = {
            "sphere_free_talent_pairs": pairs,
            "ordinary_talent_ids": bounded_ids(acquisition.get("ordinary_talent_ids")),
            "insight_occurrences": occurrences,
        }
        if "trained_choices" in acquisition:
            raw_trained_choices = acquisition.get("trained_choices")
            if not isinstance(raw_trained_choices, list):
                raw_trained_choices = []
            projected_acquisition["trained_choices"] = [
                canonical_trained_choice(row)
                for row in raw_trained_choices[:512]
                if isinstance(row, Mapping)
            ]

        return {
            "schema": "TianxiaFoundry.CharacterCreationProposalProjection.v1",
            "source": "parsed_response",
            "identity": projected_identity,
            "selected_by_slot": selected,
            "planning_preferences_by_slot": {
                slot: deepcopy(selected.get(slot) or [])
                for slot in ("sphere_priorities", "advancement_skeleton", "insight_priorities", "item_priorities")
                if selected.get(slot)
            },
            "acquisition_intent": projected_acquisition,
            "bounded_choices": deepcopy(bounded),
        }

    @classmethod
    def _proposal_projection_from_response_text(cls, response_text: str) -> dict[str, Any]:
        try:
            value = json.loads(response_text)
        except (TypeError, json.JSONDecodeError):
            return {}
        return cls._proposal_projection(value)

    @staticmethod
    def _diagnostic_boundary(code: str) -> str:
        """Name the observable failed boundary without changing legacy stage."""
        normalized = str(code or "").strip().upper()
        if normalized == "CG1_MANUAL_AI_CORRECTION_REQUIRED":
            return "AI_CORRECTION"
        if normalized == "CG1_PLAN_JSON_INVALID":
            return "JSON_PARSING"
        if normalized in {"CG1_PLAN_SCHEMA_INVALID", "CG1_PREFERRED_RESPONSE_SHAPE_INVALID"}:
            return "RESPONSE_SHAPE"
        if normalized in {
            "CG1_PREFERRED_RESPONSE_SELECTION_INVALID",
            "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID",
            "CG1_PREFERRED_RESPONSE_BOUNDED_FIELD_INVALID",
        }:
            return "RESPONSE_SCHEMA"
        if normalized in {"CG1_PLAN_BLOCKED", "CG1_TARGET_CL_INVALID"}:
            return "LEGALITY"
        if normalized in {"CG1_RESPONSE_SCHEMA_INVALID", "CG1_RESPONSE_SCHEMA_EMPTY_COMBINATOR", "CG1_RESPONSE_SCHEMA_REPRESENTATIVE_INVALID"}:
            return "COMPILATION"
        return CharacterCreationExecutionService._diagnostic_stage(normalized)

    @classmethod
    def _descriptive_projection(cls, row: Any) -> dict[str, Any]:
        proposed = cls._descriptive_fields(cls._loads(row, "owner_descriptive_fields_json", {}))
        final_plan = cls._loads(row, "final_plan_json", {})
        accepted = cls._descriptive_fields(cls._loads(row, "accepted_descriptive_fields_json", {}))
        return cls._descriptive_projection_from_values(
            proposed,
            accepted,
            (final_plan or {}).get("descriptive_fields"),
        )

    @classmethod
    def _descriptive_projection_from_values(
        cls,
        proposed: Any,
        accepted: Any,
        final_plan_descriptive_fields: Any,
    ) -> dict[str, Any]:
        proposed = cls._descriptive_fields(proposed)
        if not (
            (proposed.get("identity") or {}).get("name")
            or (proposed.get("identity") or {}).get("title")
            or proposed.get("concept")
        ):
            proposed = cls._descriptive_fields(final_plan_descriptive_fields)
        accepted = cls._descriptive_fields(accepted)
        accepted_name = (accepted.get("identity") or {}).get("name")
        accepted_title = (accepted.get("identity") or {}).get("title")
        accepted_concept = accepted.get("concept")
        proposed_name = (proposed.get("identity") or {}).get("name")
        proposed_title = (proposed.get("identity") or {}).get("title")
        proposed_concept = proposed.get("concept")
        resolved = {
            "identity": {"name": accepted_name or proposed_name},
            "concept": accepted_concept or proposed_concept,
        }
        if accepted_title or proposed_title:
            resolved["identity"]["title"] = accepted_title or proposed_title
        if accepted_name or accepted_concept or accepted_title:
            state = "OWNER_ACCEPTED"
        elif proposed_name or proposed_concept or proposed_title:
            state = "AI_PROPOSED"
        else:
            state = "UNRESOLVED"
        return {
            "schema": "TianxiaFoundry.OwnerDescriptiveFieldsProjection.v1",
            "proposed": proposed,
            "accepted": accepted,
            "resolved": resolved,
            "state": state,
            "label": "Owner accepted" if state == "OWNER_ACCEPTED" else "AI proposed" if state == "AI_PROPOSED" else "Owner decision needed",
        }

    @staticmethod
    def _recovery_json_extract(row: Any, value_key: str, type_key: str, default: Any) -> Any:
        value = row[value_key]
        if value is None:
            return deepcopy(default)
        if row[type_key] in {"object", "array"}:
            return json.loads(value)
        if row[type_key] == "true":
            return True
        if row[type_key] == "false":
            return False
        return deepcopy(value)

    def _compact_recovery_run(self, row: Any) -> dict[str, Any]:
        owner_descriptive_fields = self._loads(row, "owner_descriptive_fields_json", {})
        accepted_descriptive_fields = self._loads(row, "accepted_descriptive_fields_json", {})
        attempt_history = self._attempt_history(row["run_id"])

        def nonblank_string(value: Any) -> str | None:
            return value.strip() if isinstance(value, str) and value.strip() else None

        request_sha256 = next(
            (
                value
                for attempt in attempt_history
                if isinstance(attempt, dict)
                for value in (nonblank_string(attempt.get("request_sha256")),)
                if value is not None
            ),
            None,
        ) or nonblank_string(row["final_plan_request_sha256"])
        content_lock_hash = next(
            (
                value
                for attempt in attempt_history
                if isinstance(attempt, dict)
                for binding in (attempt.get("binding"),)
                if isinstance(binding, dict)
                for value in (nonblank_string(binding.get("content_lock_hash")),)
                if value is not None
            ),
            None,
        ) or nonblank_string(row["final_plan_content_lock_hash"])
        final_plan_descriptive_fields = self._recovery_json_extract(
            row,
            "final_plan_descriptive_fields_json",
            "final_plan_descriptive_fields_type",
            {},
        )
        return {
            "run_id": row["run_id"],
            "project_id": row["project_id"],
            "starting_revision": row["starting_revision"],
            "execution_mode": row["execution_mode"],
            "status": row["status"],
            "updated_at": row["updated_at"],
            "request": {
                "request_sha256": request_sha256,
                "content_lock_hash": content_lock_hash,
            },
            "response": {"response_sha256": row["response_sha256"]},
            "blockers": self._loads(row, "blockers_json", []),
            "warnings": self._loads(row, "warnings_json", []),
            "submission_error": self._recovery_json_extract(
                row,
                "submission_error_json",
                "submission_error_type",
                None,
            ),
            "owner_descriptive_fields": self._descriptive_projection_from_values(
                owner_descriptive_fields,
                accepted_descriptive_fields,
                final_plan_descriptive_fields,
            ),
            "attempt_history": attempt_history,
        }

    def _compact_recovery_runs(self, project_id: str) -> list[dict[str, Any]]:
        with self.db.connection() as conn:
            rows = conn.execute(
                """
                SELECT
                    run_id,
                    project_id,
                    starting_revision,
                    execution_mode,
                    status,
                    updated_at,
                    created_at,
                    json_extract(response_json, '$.response_sha256') AS response_sha256,
                    json_extract(validation_json, '$.last_submission_error') AS submission_error_json,
                    json_type(validation_json, '$.last_submission_error') AS submission_error_type,
                    json_extract(final_plan_json, '$.request_sha256') AS final_plan_request_sha256,
                    json_extract(final_plan_json, '$.content_lock_hash') AS final_plan_content_lock_hash,
                    json_extract(final_plan_json, '$.descriptive_fields') AS final_plan_descriptive_fields_json,
                    json_type(final_plan_json, '$.descriptive_fields') AS final_plan_descriptive_fields_type,
                    owner_descriptive_fields_json,
                    accepted_descriptive_fields_json,
                    blockers_json,
                    warnings_json
                FROM character_creation_runs
                WHERE project_id=?
                ORDER BY created_at DESC
                """,
                (project_id,),
            ).fetchall()
        return [self._compact_recovery_run(row) for row in rows]

    def _public(self, row: Any) -> dict[str, Any]:
        ui_ready_started = time.perf_counter()
        validation = self._loads(row, "validation_json", {})
        response = self._loads(row, "response_json", {})
        final_plan = self._loads(row, "final_plan_json", {})
        transport = self._loads(row, "transport_json", {})
        commit = self._loads(row, "commit_json", {})
        request = self._loads(row, "request_json", {})
        if not isinstance(request, dict):
            raise FoundryError(
                "DCC_ROUTE_BINDING_TAMPERED",
                "The persisted character-creation request is not an object.",
                status_code=409,
            )
        result = {
            "schema": RUN_SCHEMA, "run_id": row["run_id"], "project_id": row["project_id"],
            "starting_revision": row["starting_revision"], "execution_mode": row["execution_mode"],
            "idempotency_key": row["idempotency_key"], "request": request,
            "transport": transport, "response": response,
            "validation": validation, "dry_run": self._loads(row, "dry_run_json", {}),
            "final_plan": final_plan,
            "quality": self._loads(row, "quality_json", {}), "owner_decision": row["owner_decision"],
            "commit": commit, "final_revision": row["final_revision"],
            "outputs": self._loads(row, "output_json", {}), "blockers": self._loads(row, "blockers_json", []),
            "warnings": self._loads(row, "warnings_json", []), "status": row["status"],
            "created_at": row["created_at"], "updated_at": row["updated_at"], "completed_at": row["completed_at"],
            "owner_descriptive_fields": self._descriptive_projection(row),
            "submission_error": deepcopy(validation.get("last_submission_error")) if isinstance(validation, dict) else None,
            "secret_persisted": False,
            "attempt_history": self._attempt_history(row["run_id"]),
            "canonical_intent_hash": validation.get("canonical_intent_hash") or final_plan.get("canonical_intent_hash"),
            "materialized_plan_sha256": validation.get("materialized_stage2_hash") or final_plan.get("materialized_stage2_sha256"),
            "submitted_plan_sha256": final_plan.get("submitted_plan_sha256"),
        }
        # A DCC route is the only route with a persisted controller seam.  The
        # request binding and the durable row must agree exactly on reload;
        # legacy requests (including all pre-route historical rows) remain
        # projection-free and are never retrofitted here.
        route_binding = request.get("controller_route_binding")
        request_route = request.get("controller_route")
        if route_binding is None:
            if request_route == DETERMINISTIC_CREATIVE_CONTROLLER:
                raise FoundryError(
                    "DCC_ROUTE_BINDING_NOT_FOUND",
                    "The active DCC request has no durable authority-bound route binding.",
                    status_code=409,
                )
        else:
            route_binding = validate_controller_route_binding(route_binding)
            if request_route is not None and request_route != route_binding["route_mode"]:
                raise FoundryError(
                    "DCC_ROUTE_BINDING_TAMPERED",
                    "The request route and its sealed route binding disagree.",
                    status_code=409,
                )
            if route_binding["route_mode"] == DETERMINISTIC_CREATIVE_CONTROLLER:
                if (
                    not self._dcc_request_hash_matches(row["request_json"], request)
                ):
                    raise FoundryError(
                        "DCC_ROUTE_REQUEST_HASH_INVALID",
                        "The DCC route binding is not covered by the persisted request hash.",
                        status_code=409,
                    )
                projection = self.controller_routes.projection(row["run_id"])
                if projection is None:
                    raise FoundryError(
                        "DCC_ROUTE_BINDING_NOT_FOUND",
                        "The DCC run has no durable controller route binding.",
                        status_code=409,
                    )
                if (
                    projection["project_id"] != row["project_id"]
                    or projection["request_sha256"] != request.get("request_sha256")
                    or projection["binding_sha256"] != route_binding["binding_sha256"]
                ):
                    raise FoundryError(
                        "DCC_ROUTE_BINDING_TAMPERED",
                        "The durable DCC route binding does not match the immutable request.",
                        status_code=409,
                    )
                result["controller_route_status"] = self.controller_route_status(row["run_id"])
        result["owner_decision_authority"] = self._owner_decision_authority(result)
        result["manual_ai_correction"] = self._manual_ai_correction_summary(result)
        result["action_availability"] = self._action_availability(result)
        result["timings"] = _merge_timing_receipts(
            transport.get("timings") if isinstance(transport, dict) else None,
            validation.get("timings") if isinstance(validation, dict) else None,
            commit.get("timings") if isinstance(commit, dict) else None,
        )
        result["timings"]["phases_ms"]["factory_ui_ready_response"] = _elapsed_ms(
            ui_ready_started,
            time.perf_counter(),
        )
        return result

    def _dcc_request_hash_matches(self, raw: str | bytes, request: dict[str, Any]) -> bool:
        """Validate a parsed persisted request once per actual JSON content."""
        key = sha256_bytes(raw.encode("utf-8") if isinstance(raw, str) else raw)
        return self._route_request_hashes.get_or_compute(
            key, lambda: isinstance(request.get("request_sha256"), str)
            and self.request_payload_sha256(request) == request.get("request_sha256"),
        )

    @staticmethod
    def _historical_advancement_choice_diagnostics(
        run: dict[str, Any],
        *,
        authority_by_milestone: dict[str, Any] | None = None,
    ) -> list[dict[str, Any]]:
        """Recover an ordered chain of exact historical Advancement Choices.

        A later provider-free retry can leave the public blocker at the
        response-shape boundary even though one or more ancestor provider
        corrections selected bounded Advancement Choices.  The historical
        markers are useful only when they are the exact ancestors of the
        current leaf, in root-to-leaf order, with only immutable no-op retries
        between them.  This helper does not approve a correction; the
        ordinary provenance walk still verifies every target-only merge and
        response hash.
        """
        if not isinstance(run, dict):
            return []
        request = run.get("request") if isinstance(run.get("request"), dict) else None
        request_sha256 = request.get("request_sha256") if isinstance(request, dict) else None
        history = run.get("attempt_history")
        if (
            not isinstance(request, dict)
            or not isinstance(request_sha256, str)
            or len(request_sha256) != 64
            or not isinstance(history, list)
            or not history
        ):
            return []

        ordinals: list[int] = []
        for item in history:
            if not isinstance(item, dict) or type(item.get("ordinal")) is not int or item["ordinal"] < 1:
                return []
            ordinals.append(item["ordinal"])
        if ordinals != list(range(ordinals[0], ordinals[0] + len(ordinals))):
            return []

        records: dict[str, dict[str, Any]] = {}
        for item in history:
            if not isinstance(item, dict):
                return []
            attempt_id = item.get("attempt_id")
            if not isinstance(attempt_id, str) or not attempt_id.strip() or attempt_id in records:
                return []
            if (
                item.get("run_id") != run.get("run_id")
                or item.get("project_id") != run.get("project_id")
                or item.get("request_sha256") != request_sha256
            ):
                return []
            response_text = item.get("response_text")
            response_sha256 = item.get("response_sha256")
            if response_text is None:
                if response_sha256 not in (None, ""):
                    return []
            elif (
                not isinstance(response_text, str)
                or not response_text.strip()
                or not isinstance(response_sha256, str)
                or response_sha256 != sha256_bytes(response_text.encode("utf-8"))
            ):
                return []
            parent_id = item.get("prior_attempt_id")
            if parent_id in (None, ""):
                parent_id = None
            elif not isinstance(parent_id, str) or not parent_id.strip():
                return []
            records[attempt_id] = {
                **item,
                "_parent_id": parent_id,
                "_response_text": response_text,
                "_response_sha256": response_sha256,
                "_transport": (
                    (item.get("binding") or {}).get("transport")
                    if isinstance(item.get("binding"), dict)
                    and isinstance((item.get("binding") or {}).get("transport"), dict)
                    else None
                ),
            }

        ordered_records = [records.get(item.get("attempt_id")) for item in history]
        if (
            not ordered_records
            or any(not isinstance(item, dict) for item in ordered_records)
            or ordered_records[0].get("_parent_id") is not None
            or any(
                child.get("_parent_id") != parent.get("attempt_id")
                for parent, child in zip(ordered_records, ordered_records[1:])
            )
        ):
            return []

        latest = ordered_records[-1]
        if not isinstance(latest, dict):
            return []
        current_response = run.get("response") if isinstance(run.get("response"), dict) else None
        if (
            isinstance(current_response, dict)
            and current_response.get("exact_response_text") != latest.get("_response_text")
        ):
            return []
        if (
            isinstance(current_response, dict)
            and current_response.get("response_sha256") not in (None, latest.get("_response_sha256"))
        ):
            return []

        # Follow the actual latest-to-root chain so a marker in a disconnected
        # branch cannot supply authority for this response.
        chain: list[dict[str, Any]] = []
        seen: set[str] = set()
        node = latest
        while isinstance(node, dict):
            node_id = node.get("attempt_id")
            if not isinstance(node_id, str) or node_id in seen:
                return []
            seen.add(node_id)
            chain.append(node)
            parent_id = node.get("_parent_id")
            if parent_id is None:
                break
            node = records.get(parent_id)
            if not isinstance(node, dict):
                return []

        # A historical marker is usable only when the entire retained ledger
        # is one connected, single-child chain to the current leaf.  A sibling
        # or disconnected row must not be able to donate an authority hint.
        children: dict[str, list[str]] = {}
        for item in records.values():
            parent_id = item.get("_parent_id")
            if parent_id is None:
                continue
            if parent_id not in records:
                return []
            children.setdefault(parent_id, []).append(item["attempt_id"])
        if any(len(child_ids) > 1 for child_ids in children.values()) or len(seen) != len(records):
            return []

        def exact_retry_descendant(item: dict[str, Any], parent: dict[str, Any]) -> bool:
            binding = item.get("binding") if isinstance(item.get("binding"), dict) else None
            transport = binding.get("transport") if isinstance(binding, dict) else None
            response_text = item.get("_response_text")
            parent_text = parent.get("_response_text")
            if (
                item.get("action_type") != "RETRY_LOCAL_BUILD"
                or item.get("status") != "BLOCKED"
                or item.get("_parent_id") != parent.get("attempt_id")
                or not isinstance(response_text, str)
                or response_text != parent_text
                or item.get("_response_sha256") != parent.get("_response_sha256")
                or not isinstance(binding, dict)
                or binding.get("active_request_sha256") != request_sha256
                or binding.get("submitted_request_sha256") != request_sha256
                or not isinstance(transport, dict)
                or transport.get("provider_called") is not False
                or type(transport.get("automatic_retries")) is not int
                or transport.get("automatic_retries") != 0
                or transport.get("transfer") != "retry_local_build"
                or transport.get("submitted_request_sha256") != request_sha256
                or transport.get("prior_attempt_id") != parent.get("attempt_id")
                or "local_correction" in transport
                or "local_recovery" in transport
            ):
                return False
            if "mode" in transport and transport.get("mode") != run.get("execution_mode"):
                return False
            return True

        candidates: list[tuple[int, dict[str, Any], dict[str, Any], dict[str, Any]]] = []
        for index, marker_row in enumerate(chain):
            transport_binding = marker_row.get("binding") if isinstance(marker_row.get("binding"), dict) else None
            transport = transport_binding.get("transport") if isinstance(transport_binding, dict) else None
            marker = transport.get("local_correction") if isinstance(transport, dict) else None
            if not isinstance(marker, dict) or marker.get("target_kind") != "advancement_choice":
                continue
            parent = records.get(marker_row.get("_parent_id"))
            if (
                not isinstance(parent, dict)
                or marker_row.get("action_type") != "LOCAL_PROVIDER_CORRECTION"
                or marker_row.get("status") not in {"BLOCKED", "READY_FOR_REVIEW"}
                or not isinstance(transport_binding, dict)
                or transport_binding.get("active_request_sha256") != request_sha256
                or transport_binding.get("submitted_request_sha256") is not None
                or not isinstance(transport, dict)
                or transport.get("provider_called") is not True
                or type(transport.get("automatic_retries")) is not int
                or transport.get("automatic_retries") != 0
                or transport.get("complete_request_sha256") != request_sha256
                or transport.get("prior_attempt_id") != parent.get("attempt_id")
                or transport.get("provider_id") not in _LOCAL_PROVIDER_IDS
                or "local_recovery" in transport
            ):
                return []
            if "mode" in transport and transport.get("mode") != run.get("execution_mode"):
                return []
            if (
                marker.get("attempted") is not True
                or marker.get("explicit") is not True
                or marker.get("status") != "RETAINED_FOR_VALIDATION"
                or marker.get("provider_id") != transport.get("provider_id")
                or ("provider_called" in marker and marker.get("provider_called") is not True)
                or marker.get("request_sha256") != request_sha256
                or marker.get("prior_attempt_id") != parent.get("attempt_id")
                or marker.get("prior_response_sha256") != parent.get("_response_sha256")
                or marker.get("applied_response_sha256") != marker_row.get("_response_sha256")
                or not isinstance(marker.get("selected_option_id"), str)
                or not isinstance(marker.get("selected_kind"), str)
            ):
                return []
            diagnostic = marker.get("validator_diagnostic")
            details = diagnostic.get("details") if isinstance(diagnostic, dict) else None
            milestone_id = details.get("milestone_id") if isinstance(details, dict) else None
            expected_field = (
                "bounded_choices.ability_score_changes_by_milestone_id." + milestone_id
                if isinstance(milestone_id, str)
                else None
            )
            if (
                not isinstance(diagnostic, dict)
                or diagnostic.get("code") != "CG1_BOUNDED_DECISION_REQUIRED"
                or not isinstance(details, dict)
                or not isinstance(milestone_id, str)
                or details.get("field") != expected_field
                or marker.get("field") != expected_field
                or marker.get("milestone_id") != milestone_id
                or type(details.get("effective_cl", details.get("cl"))) is not int
                or marker.get("selected_kind") not in {
                    "ability_score_change",
                    "cultivation_insight_acquisition",
                }
                or marker.get("target_scoped_merge") is not True
            ):
                return []
            raw_completion = marker.get("raw_provider_completion_sha256")
            raw_response = marker.get("raw_provider_response_sha256")
            if (
                not isinstance(raw_completion, str)
                or not raw_completion.strip()
                or raw_response != raw_completion
                or marker.get("provider_completion_sha256") != transport.get("provider_completion_sha256")
                or marker.get("provider_response_sha256") != transport.get("provider_response_sha256")
                or transport.get("provider_completion_sha256") != raw_completion
                or not isinstance(transport.get("provider_response_sha256"), str)
                or not transport.get("provider_response_sha256").strip()
            ):
                return []
            candidates.append((index, marker_row, parent, deepcopy(diagnostic)))

        if not candidates:
            return []
        milestone_ids = [
            candidate[3].get("details", {}).get("milestone_id")
            for candidate in candidates
        ]
        if (
            any(not isinstance(milestone_id, str) for milestone_id in milestone_ids)
            or len(set(milestone_ids)) != len(milestone_ids)
        ):
            return []
        effective_cls = [
            candidate[3].get("details", {}).get("effective_cl", candidate[3].get("details", {}).get("cl"))
            for candidate in reversed(candidates)
        ]
        if (
            any(type(effective_cl) is not int for effective_cl in effective_cls)
            or any(left >= right for left, right in zip(effective_cls, effective_cls[1:]))
        ):
            return []

        # ``chain`` is latest-to-root.  The root-most marker bounds the
        # historical suffix that can donate authority.  Every edge from the
        # leaf through that marker is either one validated Advancement Choice
        # marker or an exact provider-free retry; arbitrary interleaving is
        # never skipped.
        marker_indexes = {candidate[0] for candidate in candidates}
        rootmost_marker_index = max(marker_indexes)
        for child_index in range(rootmost_marker_index):
            if child_index in marker_indexes:
                continue
            if not exact_retry_descendant(chain[child_index], chain[child_index + 1]):
                return []

        proof_authority = authority_by_milestone
        if proof_authority is None:
            candidate_authority = run.get("owner_decision_authority")
            proof_authority = candidate_authority if isinstance(candidate_authority, dict) else None
        if proof_authority is not None:
            proof_run = dict(run)
            proof_run["owner_decision_authority"] = proof_authority
            for _index, marker_row, parent, _diagnostic in candidates:
                item_projection = CharacterCreationExecutionService._ordinary_response_array_projection(
                    marker_row.get("_response_text")
                )
                parent_projection = CharacterCreationExecutionService._ordinary_response_array_projection(
                    parent.get("_response_text")
                )
                if (
                    item_projection is None
                    or parent_projection is None
                    or not CharacterCreationExecutionService._ordinary_repair_advancement_choice_intermediary_valid(
                        proof_run,
                        marker_row,
                        parent,
                        request_sha256=request_sha256,
                        item_projection=item_projection,
                        parent_projection=parent_projection,
                    )
                ):
                    return []
        # Return root-to-leaf order, while the singular compatibility wrapper
        # below continues to expose the latest marker.
        return [deepcopy(candidate[3]) for candidate in reversed(candidates)]

    @staticmethod
    def _historical_advancement_choice_diagnostic(
        run: dict[str, Any],
        *,
        authority_by_milestone: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        diagnostics = CharacterCreationExecutionService._historical_advancement_choice_diagnostics(
            run,
            authority_by_milestone=authority_by_milestone,
        )
        return deepcopy(diagnostics[-1]) if diagnostics else None

    def _owner_decision_authority(self, run: dict[str, Any]) -> dict[str, Any]:
        """Attach source-backed rules needed by the shared owner resolver.

        The response request deliberately remains immutable and request-bound;
        this derived view is not part of its hash.  It gives the owner API and
        the retry path the same authenticated Path-feature rule, including for
        a historical request whose milestone rows predate typed ASI metadata.
        """
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        envelope = request.get("delegated_choice_envelope") if isinstance(request, dict) else {}
        if not isinstance(envelope, dict):
            return {}
        blockers = run.get("blockers") if isinstance(run.get("blockers"), list) else []
        historical_advancements = self._historical_advancement_choice_diagnostics(run)
        if historical_advancements:
            blockers = [*blockers, *historical_advancements]
        if not blockers:
            return {}
        advertised = {
            row.get("milestone_id"): row
            for row in envelope.get("advancement_choice_milestones") or []
            if isinstance(row, dict) and isinstance(row.get("milestone_id"), str)
        }
        authority = NonSphereAuthorityService(self.db)
        result: dict[str, Any] = {}
        for blocker in blockers:
            if not isinstance(blocker, dict):
                continue
            details = blocker.get("details") if isinstance(blocker.get("details"), dict) else {}
            nested = details.get("milestone") if isinstance(details.get("milestone"), dict) else {}
            milestone_id = details.get("milestone_id") or nested.get("milestone_id")
            if not isinstance(milestone_id, str):
                continue
            source_milestone = advertised.get(milestone_id) or {}
            milestone = {**source_milestone, **nested, **details}
            path_id = milestone.get("path_id")
            feature_id = milestone.get("feature_record_id")
            if not isinstance(path_id, str) or not isinstance(feature_id, str):
                continue
            try:
                feature = authority.project_locked_path_feature_catalog_record(path_id, feature_id)
            except FoundryError:
                continue
            stage2_authority = (feature.get("compatibility") or {}).get("factory", {}).get("stage2_authority") or {}
            if not isinstance(stage2_authority, dict):
                continue
            result[milestone_id] = {
                "ability_change": deepcopy(stage2_authority.get("ability_change") or {}),
                "allowed_kinds": deepcopy(stage2_authority.get("allowed_kinds") or []),
                "source": deepcopy(stage2_authority.get("path_index_source") or {}),
            }
        if historical_advancements:
            historical_milestone_ids = {
                details.get("milestone_id")
                for diagnostic in historical_advancements
                for details in [diagnostic.get("details")]
                if isinstance(details, dict) and isinstance(details.get("milestone_id"), str)
            }
            strict_historical = self._historical_advancement_choice_diagnostics(
                {**run, "owner_decision_authority": result},
                authority_by_milestone=result,
            )
            strict_milestone_ids = {
                details.get("milestone_id")
                for diagnostic in strict_historical
                for details in [diagnostic.get("details")]
                if isinstance(details, dict) and isinstance(details.get("milestone_id"), str)
            }
            for milestone_id in historical_milestone_ids - strict_milestone_ids:
                result.pop(milestone_id, None)
        return result

    def get(self, run_id: str) -> dict[str, Any]:
        with self.db.connection() as conn:
            row = conn.execute("SELECT * FROM character_creation_runs WHERE run_id=?", (run_id,)).fetchone()
        if not row:
            raise FoundryError("CG1_RUN_NOT_FOUND", "No character build run has that ID.", status_code=404)
        public = self._public(row)
        # The owner page follows a finalize started elsewhere (auto-finalize, another tab) by
        # polling this view; without the flag it concluded "ended without saving" on its first
        # poll while the finalize was still running (owner report 2026-09-25).
        public["finalize_in_progress"] = getattr(self, "_finalizing_run_id", None) == run_id
        if public.get("status") == "CLEAN_AND_FINALIZED":
            try:
                from .auto_token import add_notes

                add_notes(self.db.settings.data_dir, public)
            except Exception:
                import logging

                logging.getLogger(__name__).exception("Could not read automatic token note; finalized run is unchanged")
        return public

    def training_authority_supplement(self, run_id: str, digest: str) -> dict[str, Any]:
        """Return the run's declared frozen training authority supplement.

        Only a digest that is published and bound to this run's own frozen
        request is served; the prompt cannot reference an unpublished authority,
        and the caller cannot substitute another run's digest.
        """

        run = self.get(run_id)
        request_sha256 = (run.get("request") or {}).get("request_sha256")
        from character_creation.training_authority_supplement import load_supplement

        return load_supplement(
            self.db,
            run_id,
            digest,
            expected_request_sha256=request_sha256 if isinstance(request_sha256, str) else None,
        )

    def candidate_gm_summary(self, run_id: str) -> dict[str, Any]:
        """Return the authenticated staged GM context identity without a provider call."""
        return self.candidate_gm.summary(run_id)

    def load_candidate_gm_context(self, run_id: str) -> dict[str, Any]:
        """Load a previously captured staged GM context without rebuilding it."""
        return self.candidate_gm.load(run_id)

    def candidate_gm_author(self, run_id: str) -> dict[str, Any]:
        """Explicitly invoke the local provider for one captured candidate."""
        from .candidate_action_authoring import prepare_candidate_actions

        started = time.perf_counter()
        with self._finalize_lock:
            prepare_candidate_actions(self, run_id)
        prepared = time.perf_counter()
        try:
            return self.candidate_gm_authoring.author(run_id)
        finally:
            self._record_stage_timings(run_id, "gm_author", {
                "prepare_candidate_actions": _elapsed_ms(started, prepared),
                "composite_author": _elapsed_ms(prepared, time.perf_counter()),
            })

    def candidate_gm_author_status(self, run_id: str) -> dict[str, Any]:
        """Return candidate GM authoring state without invoking a provider."""
        return self.candidate_gm_authoring.status(run_id)

    def load_candidate_gm_authoring(self, run_id: str) -> dict[str, Any]:
        """Load the authenticated candidate GM artifact without rebuilding it."""
        return self.candidate_gm_authoring.load(run_id)

    def build_candidate_gm_authoring(self, run_id: str) -> dict[str, Any]:
        """Provider-free candidate GM review/build from the stored receipt."""
        return self.candidate_gm_authoring.build(run_id)

    def issue_candidate_gm_approval_challenge(
        self,
        run_id: str,
        ttl_seconds: int = 300,
    ) -> dict[str, Any]:
        """Issue an exact-byte owner challenge for a captured GM candidate."""
        return self.candidate_gm_authoring.issue_candidate_approval_challenge(
            run_id,
            ttl_seconds=ttl_seconds,
        )

    def approve_candidate_gm(
        self,
        run_id: str,
        challenge_id: str,
        nonce: str,
    ) -> dict[str, Any]:
        """Consume the owner challenge and persist candidate approval."""
        return self.candidate_gm_authoring.approve_candidate_gm(
            run_id,
            challenge_id,
            nonce,
        )

    def list(self, project_id: str) -> list[dict[str, Any]]:
        with self.db.connection() as conn:
            rows = conn.execute("SELECT * FROM character_creation_runs WHERE project_id=? ORDER BY created_at DESC", (project_id,)).fetchall()
        return [self._public(row) for row in rows]

    def controller_route_projection(self, run_id: str) -> dict[str, Any] | None:
        """Return the private route/event projection for reload and recovery.

        The projection is intentionally separate from the public API view.  It
        contains the exact sealed binding and event chain needed by the next
        DCC slice, while ``controller_route_status`` below exposes only safe
        route state and hashes.
        """

        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT project_id,request_json FROM character_creation_runs WHERE run_id=?",
                (run_id,),
            ).fetchone()
        if row is None:
            raise FoundryError("CG1_RUN_NOT_FOUND", "No character build run has that ID.", status_code=404)
        request = json.loads(row["request_json"]) if row["request_json"] else {}
        if not isinstance(request, dict):
            raise FoundryError("DCC_ROUTE_BINDING_TAMPERED", "The persisted character-creation request is not an object.", status_code=409)
        binding = request.get("controller_route_binding")
        if binding is not None:
            binding = validate_controller_route_binding(binding)
        if binding is None and request.get("controller_route") == DETERMINISTIC_CREATIVE_CONTROLLER:
            raise FoundryError(
                "DCC_ROUTE_BINDING_NOT_FOUND",
                "The active DCC request has no durable authority-bound route binding.",
                status_code=409,
            )
        projection = self.controller_routes.projection(run_id)
        if binding is None or binding.get("route_mode") == LEGACY_FULL_PLAN:
            if projection is not None:
                raise FoundryError(
                    "DCC_ROUTE_BINDING_TAMPERED",
                    "A legacy request unexpectedly has a persisted DCC route.",
                    status_code=409,
                )
            return None
        if binding.get("route_mode") != DETERMINISTIC_CREATIVE_CONTROLLER or projection is None:
            raise FoundryError("DCC_ROUTE_BINDING_NOT_FOUND", "The DCC route binding is missing.", status_code=409)
        if (
            projection["project_id"] != row["project_id"]
            or projection["request_sha256"] != request.get("request_sha256")
            or projection["binding_sha256"] != binding["binding_sha256"]
            or not self._dcc_request_hash_matches(row["request_json"], request)
        ):
            raise FoundryError(
                "DCC_ROUTE_BINDING_TAMPERED",
                "The durable DCC route binding does not match the immutable request.",
                status_code=409,
            )
        return projection

    # Recovery-oriented aliases keep the internal seam discoverable without
    # introducing another public endpoint.
    controller_route_recovery = controller_route_projection
    get_controller_route_projection = controller_route_projection

    def controller_route_status(self, run_id: str) -> dict[str, Any] | None:
        projection = self.controller_route_projection(run_id)
        if projection is None:
            return None
        status = self.controller_routes.status(run_id)
        if status is not None:
            walk = self.linear_walk.status(run_id)
            if walk is not None:
                status["walk"] = walk
        return status

    def append_controller_event(self, run_id: str, **kwargs: Any) -> dict[str, Any]:
        """Append a future DCC event through the strict persistence seam."""

        return self.controller_routes.append_event(run_id, **kwargs)

    @staticmethod
    def _dcc_step_events(events: Collection[dict[str, Any]]) -> list[dict[str, Any]]:
        return [
            event
            for event in events
            if isinstance(event, dict)
            and event.get("event_type") in {STEP_COMMITTED, STEP_AUTOCOMMITTED}
        ]

    @staticmethod
    def _dcc_metric(receipt: Mapping[str, Any], *keys: str) -> int | None:
        """Extract one bounded provider metric without retaining prompt data."""

        sources: list[Mapping[str, Any]] = []
        timings = receipt.get("timings")
        if isinstance(timings, Mapping):
            reported = timings.get("provider_reported")
            if isinstance(reported, Mapping):
                sources.append(reported)
            sources.append(timings)
        for field in ("usage", "performance"):
            value = receipt.get(field)
            if isinstance(value, Mapping):
                sources.append(value)
        for source in sources:
            for key in keys:
                value = source.get(key)
                if type(value) is int and value >= 0:
                    return value
        return None

    @staticmethod
    def _dcc_diagnostic(
        exc: Exception,
        *,
        step_id: str,
        menu_sha256: str | None = None,
        code: str | None = None,
    ) -> dict[str, Any]:
        if isinstance(exc, FoundryError):
            error_code = code or exc.code
            message = exc.message
        else:
            error_code = code or "DCC_LINEAR_PROVIDER_ERROR"
            message = "The DCC linear step did not complete."
        diagnostic: dict[str, Any] = {
            "schema": "TianxiaFoundry.DccLinearWalkDiagnostic.v1",
            "code": str(error_code)[:120],
            "message": str(message)[:300],
            "step_id": step_id[:160],
            "menu_sha256": menu_sha256,
        }
        # Typed walk errors carry the actionable detail (the exact missing
        # step, counts, and known holdings).  Keep it bounded and pass it to
        # the owner instead of collapsing it into the generic message.
        details = exc.details if isinstance(exc, FoundryError) else None
        if isinstance(details, Mapping) and details and len(canonical_json(details)) <= 6000:
            diagnostic["details"] = deepcopy(dict(details))
        return diagnostic

    def _dcc_append_walk_event(
        self,
        run_id: str,
        *,
        event_type: str,
        subject_sha256: str,
        state_sha256_before: str,
        state_sha256_after: str,
        payload: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        projection = self.controller_routes.projection(run_id)
        if projection is None:
            raise FoundryError(
                "DCC_ROUTE_BINDING_NOT_FOUND",
                "No DCC controller route is bound to this run.",
                status_code=404,
            )
        return self.linear_walk.append_event(
            run_id,
            event_type=event_type,
            subject_sha256=subject_sha256,
            state_sha256_before=state_sha256_before,
            state_sha256_after=state_sha256_after,
            payload=payload,
            expected_event_head_sha256=projection["event_head_sha256"],
            expected_ordinal=projection["event_count"] + 1,
            expected_binding_sha256=projection["binding_sha256"],
        )

    def _dcc_save_walk_snapshot(
        self,
        run_id: str,
        *,
        step_ordinal: int,
        committed: CommittedState,
        event: Mapping[str, Any],
    ) -> dict[str, Any]:
        return self.linear_walk.save_snapshot(
            run_id,
            step_ordinal,
            committed,
            str(event["event_sha256"]),
        )

    def _dcc_transport_receipt(self, run: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "mode": run.get("execution_mode"),
            "provider_called": False,
            "purpose": DCC_LINEAR_STEP_PURPOSE,
            "automatic_retries": 0,
            "linear_walk": {
                "schema": "TianxiaFoundry.DccLinearWalkTransportReceipt.v1",
                "provider_called": False,
                "step_count": 0,
                "steps": [],
                "menu_sha256_chain": [],
                "menu_sha256_chain_digest": sha256_json([]),
            },
        }

    def _dcc_provider_step(
        self,
        *,
        prompt_text: str,
        response_schema: dict[str, Any],
    ) -> dict[str, Any]:
        """Invoke exactly one bounded local step request.

        Signature inspection keeps the provider-free test doubles small while
        the real AIProviderService receives every S0 bound explicitly.
        """

        # Identity authors three bounded strings, including a 240-character
        # concept. A one-option selection budget truncates valid identity JSON.
        # Stay inside the existing DCC ceiling; all response gates still apply.
        identity_response = set(response_schema.get("properties", {})) == {"name", "title", "concept"}
        provider_call: dict[str, Any] = {
            "prompt_text": prompt_text,
            "system_message": CHARACTER_CREATION_PROVIDER_SYSTEM_MESSAGE,
            "purpose": DCC_LINEAR_STEP_PURPOSE,
            "substantive": identity_response,
            "response_schema": deepcopy(response_schema),
            "response_schema_max_output_tokens": 256 if identity_response else 64,
            "timeout_seconds": 180,
        }
        try:
            parameters = inspect.signature(self.provider.complete_json).parameters
        except (TypeError, ValueError):
            parameters = {}
        accepts_kwargs = any(
            parameter.kind is inspect.Parameter.VAR_KEYWORD
            for parameter in parameters.values()
        )
        if not accepts_kwargs and parameters:
            provider_call = {
                key: value
                for key, value in provider_call.items()
                if key in parameters
            }
        receipt = self.provider.complete_json(**provider_call)
        if not isinstance(receipt, dict):
            raise FoundryError(
                "DCC_LINEAR_PROVIDER_RECEIPT_INVALID",
                "The DCC step provider returned invalid transport evidence.",
                status_code=502,
            )
        return receipt

    @staticmethod
    def _dcc_response_value(receipt: Mapping[str, Any]) -> Mapping[str, Any]:
        value = receipt.get("value")
        if isinstance(value, Mapping):
            return value
        response_text = receipt.get("response_text")
        if isinstance(response_text, str):
            try:
                parsed = json.loads(response_text)
            except (TypeError, json.JSONDecodeError) as exc:
                raise FoundryError(
                    "DCC_LINEAR_PROVIDER_RESPONSE_INVALID",
                    "The DCC step provider returned invalid JSON.",
                    status_code=502,
                ) from exc
            if isinstance(parsed, Mapping):
                return parsed
        raise FoundryError(
            "DCC_LINEAR_PROVIDER_RESPONSE_INVALID",
            "The DCC step provider returned no JSON object.",
            status_code=502,
        )

    @staticmethod
    def _dcc_receipt_digest(receipt: Mapping[str, Any]) -> str:
        for key in ("response_sha256", "completion_sha256", "request_sha256"):
            value = receipt.get(key)
            if isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value):
                return value
        return sha256_json({
            "provider_id": receipt.get("provider_id"),
            "model": receipt.get("model"),
            "purpose": receipt.get("purpose"),
            "timings": receipt.get("timings"),
        })

    def _dcc_update_run(
        self,
        run_id: str,
        *,
        status: str,
        transport: Mapping[str, Any] | None = None,
        diagnostic: Mapping[str, Any] | None = None,
    ) -> None:
        with self.db.transaction() as conn:
            row = conn.execute(
                "SELECT transport_json,validation_json FROM character_creation_runs WHERE run_id=?",
                (run_id,),
            ).fetchone()
            if row is None:
                raise FoundryError("CG1_RUN_NOT_FOUND", "No character build run has that ID.", status_code=404)
            try:
                current_transport = json.loads(row["transport_json"] or "{}")
            except (TypeError, json.JSONDecodeError):
                current_transport = {}
            try:
                validation = json.loads(row["validation_json"] or "{}")
            except (TypeError, json.JSONDecodeError):
                validation = {}
            if not isinstance(current_transport, dict):
                current_transport = {}
            if not isinstance(validation, dict):
                validation = {}
            if isinstance(transport, Mapping):
                current_transport = deepcopy(dict(transport))
            if isinstance(diagnostic, Mapping):
                validation["last_submission_error"] = deepcopy(dict(diagnostic))
                validation["response_state"] = {
                    "exact_response_retained": False,
                    "compiled": False,
                }
            conn.execute(
                "UPDATE character_creation_runs SET transport_json=?,validation_json=?,blockers_json=?,status=?,updated_at=? WHERE run_id=?",
                (
                    canonical_json(current_transport),
                    canonical_json(validation),
                    canonical_json([dict(diagnostic)] if isinstance(diagnostic, Mapping) else []),
                    status,
                    utcnow(),
                    run_id,
                ),
            )

    def _dcc_start_walk(
        self,
        run_id: str,
        request: Mapping[str, Any],
        envelope: Mapping[str, Any],
    ) -> dict[str, Any]:
        existing = self.linear_walk.events(run_id)
        if any(event.get("event_type") == WALK_STARTED for event in existing):
            return self.linear_walk.verified_replay(request, envelope, run_id)
        first = next_linear_step(request, envelope, CommittedState.empty(), [], page=1)
        projection = self.controller_routes.projection(run_id)
        if projection is None:
            raise FoundryError(
                "DCC_ROUTE_BINDING_NOT_FOUND",
                "No DCC controller route is bound to this run.",
                status_code=404,
            )
        event = self._dcc_append_walk_event(
            run_id,
            event_type=WALK_STARTED,
            subject_sha256=str(request.get("request_sha256")),
            state_sha256_before=projection["state_sha256"],
            state_sha256_after=first.committed.committed_sha256,
            payload={
                "steps_estimate": walk_steps_estimate(request),
                "ceilings": deepcopy(WALK_CEILINGS),
            },
        )
        if first.action == ACTION_AUTOCOMMITTED:
            # A single-option first menu is already committed in
            # first.committed.  Persist its STEP_AUTOCOMMITTED event exactly
            # like the main loop does; otherwise the snapshot would hold a
            # step the verified replay cannot reconstruct.
            autocommit = first.event if isinstance(first.event, dict) else {}
            projection = self.controller_routes.projection(run_id)
            if projection is None:
                raise FoundryError(
                    "DCC_ROUTE_BINDING_NOT_FOUND",
                    "No DCC controller route is bound to this run.",
                    status_code=404,
                )
            commit_event = self._dcc_append_walk_event(
                run_id,
                event_type=STEP_AUTOCOMMITTED,
                subject_sha256=first.committed.committed_sha256,
                state_sha256_before=projection["state_sha256"],
                state_sha256_after=first.committed.committed_sha256,
                payload={
                    "step_id": first.step_id,
                    "choice_ids": list(autocommit.get("choice_ids") or []),
                    "reason": "single_option",
                },
            )
            self._dcc_save_walk_snapshot(
                run_id,
                step_ordinal=first.ordinal,
                committed=first.committed,
                event=commit_event,
            )
        else:
            self._dcc_save_walk_snapshot(
                run_id,
                step_ordinal=0,
                committed=first.committed,
                event=event,
            )
        return self.linear_walk.verified_replay(request, envelope, run_id)

    def _dcc_fail_walk(
        self,
        run_id: str,
        *,
        state: CommittedState,
        step_id: str,
        menu_sha256: str | None,
        diagnostic: Mapping[str, Any],
        transport: Mapping[str, Any],
        step_ordinal: int | None = None,
    ) -> dict[str, Any]:
        projection = self.controller_routes.projection(run_id)
        if projection is not None:
            subject = menu_sha256 if isinstance(menu_sha256, str) and len(menu_sha256) == 64 else sha256_json({"step_id": step_id})
            event = self._dcc_append_walk_event(
                run_id,
                event_type=WALK_FAILED,
                subject_sha256=subject,
                state_sha256_before=projection["state_sha256"],
                state_sha256_after=state.committed_sha256,
                payload={
                    "step_id": step_id,
                    "diagnostic": deepcopy(dict(diagnostic)),
                },
            )
            self._dcc_save_walk_snapshot(
                run_id,
                step_ordinal=(
                    step_ordinal
                    if type(step_ordinal) is int and step_ordinal >= 0
                    else (self.linear_walk.load_snapshot(run_id) or {}).get("step_ordinal", 0)
                ),
                committed=state,
                event=event,
            )
        self._dcc_update_run(
            run_id,
            status="NEEDS_REVIEW",
            transport=transport,
            diagnostic=diagnostic,
        )
        return self.get(run_id)

    def _run_dcc_linear_walk(self, run_id: str, *, resume: bool = False) -> dict[str, Any]:
        run = self.get(run_id)
        request = run.get("request") if isinstance(run.get("request"), Mapping) else {}
        envelope = request.get("delegated_choice_envelope") if isinstance(request, Mapping) else None
        if not isinstance(envelope, Mapping):
            # Stage B compatibility runs deliberately remain a route seam and
            # do not enter the active walk until a frozen envelope exists.
            return run
        transport = self._dcc_transport_receipt(run)
        started = time.perf_counter()
        page_for_step = 1
        try:
            # The sealed request carries the compact choice envelope, while
            # the provider projection is the authority for the legal first
            # cycle pair rows and route modules.  Keep the projection in the
            # walk's in-memory envelope so pure menu builders can consume the
            # exact typed fields without composing legality from display data.
            projection = _provider_payload(run, cue_limit=0, display_limit=0)
            if isinstance(projection, Mapping) and projection:
                envelope = {
                    **dict(envelope),
                    "linear_provider_payload": deepcopy(dict(projection)),
                }
            replay = self._dcc_start_walk(run_id, request, envelope)
            state = replay["state"]
        except FoundryError as exc:
            diagnostic = self._dcc_diagnostic(exc, step_id="")
            return self._dcc_fail_walk(
                run_id,
                state=CommittedState.empty(),
                step_id="",
                menu_sha256=None,
                diagnostic=diagnostic,
                transport=transport,
            )
        menu_chain: list[str] = []
        retry_menu_sha256: str | None = None
        retry_count = 0
        while True:
            if time.perf_counter() - started > WALK_CEILINGS["max_walk_seconds"]:
                diagnostic = self._dcc_diagnostic(
                    FoundryError("DCC_LINEAR_WALK_TIME_LIMIT", "The DCC walk exceeded its forty-five-minute ceiling."),
                    step_id="",
                )
                return self._dcc_fail_walk(
                    run_id,
                    state=state,
                    step_id="",
                    menu_sha256=retry_menu_sha256,
                    diagnostic=diagnostic,
                    transport=transport,
                    step_ordinal=(self.linear_walk.load_snapshot(run_id) or {}).get("step_ordinal", 0),
                )
            replay = self.linear_walk.verified_replay(request, envelope, run_id)
            state = replay["state"]
            step_events = self._dcc_step_events(replay["step_events"])
            if len(step_events) >= MAX_WALK_STEPS:
                diagnostic = self._dcc_diagnostic(
                    FoundryError("DCC_LINEAR_STEP_LIMIT", "The DCC walk exceeded its step ceiling."),
                    step_id="",
                )
                return self._dcc_fail_walk(
                    run_id,
                    state=state,
                    step_id="",
                    menu_sha256=retry_menu_sha256,
                    diagnostic=diagnostic,
                    transport=transport,
                    step_ordinal=(self.linear_walk.load_snapshot(run_id) or {}).get("step_ordinal", 0),
                )
            try:
                step = next_linear_step(
                    request,
                    envelope,
                    state,
                    step_events,
                    page=page_for_step,
                )
            except FoundryError as exc:
                diagnostic = self._dcc_diagnostic(exc, step_id="")
                return self._dcc_fail_walk(
                    run_id,
                    state=state,
                    step_id="",
                    menu_sha256=retry_menu_sha256,
                    diagnostic=diagnostic,
                    transport=transport,
                    step_ordinal=(self.linear_walk.load_snapshot(run_id) or {}).get("step_ordinal", 0),
                )
            if step.action == ACTION_COMPLETE:
                try:
                    response_text = build_linear_response(request, state)
                    transport["provider_called"] = bool(transport["linear_walk"]["provider_called"])
                    transport["linear_walk"]["step_count"] = len(step_events)
                    transport["linear_walk"]["menu_sha256_chain"] = list(menu_chain)
                    transport["linear_walk"]["menu_sha256_chain_digest"] = sha256_json(menu_chain)
                    result = self._apply_response(
                        run_id,
                        response_text,
                        transport,
                        action_type="DCC_LINEAR_WALK",
                    )
                except FoundryError as exc:
                    diagnostic = self._dcc_diagnostic(exc, step_id="")
                    return self._dcc_fail_walk(
                        run_id,
                        state=state,
                        step_id="",
                        menu_sha256=retry_menu_sha256,
                        diagnostic=diagnostic,
                        transport=transport,
                    )
                projection = self.controller_routes.projection(run_id)
                if projection is not None:
                    event = self._dcc_append_walk_event(
                        run_id,
                        event_type=WALK_COMPLETED,
                        subject_sha256=sha256_bytes(response_text.encode("utf-8")),
                        state_sha256_before=projection["state_sha256"],
                        state_sha256_after=state.committed_sha256,
                        payload={
                            "step_count": len(step_events),
                            "total_ms": max(1, round((time.perf_counter() - started) * 1000)),
                        },
                    )
                    self._dcc_save_walk_snapshot(
                        run_id,
                        step_ordinal=len(step_events),
                        committed=state,
                        event=event,
                    )
                return self.get(run_id) if not isinstance(result, dict) else self.get(run_id)
            if step.action == ACTION_AUTOCOMMITTED:
                projection = self.controller_routes.projection(run_id)
                if projection is None:
                    raise FoundryError("DCC_ROUTE_BINDING_NOT_FOUND", "No DCC controller route is bound to this run.", status_code=404)
                payload = {
                    "step_id": step.step_id,
                    "choice_ids": list(step.event.get("choice_ids") or []) if isinstance(step.event, Mapping) else [],
                    "reason": "single_option",
                }
                event = self._dcc_append_walk_event(
                    run_id,
                    event_type=STEP_AUTOCOMMITTED,
                    subject_sha256=step.committed.committed_sha256,
                    state_sha256_before=projection["state_sha256"],
                    state_sha256_after=step.committed.committed_sha256,
                    payload=payload,
                )
                self._dcc_save_walk_snapshot(
                    run_id,
                    step_ordinal=step.ordinal,
                    committed=step.committed,
                    event=event,
                )
                retry_menu_sha256 = None
                retry_count = 0
                continue
            if step.action != ACTION_MENU or step.menu is None:
                diagnostic = self._dcc_diagnostic(
                    FoundryError("DCC_LINEAR_STEP_INVALID", "The DCC walk produced an unsupported step action."),
                    step_id=step.step_id,
                )
                return self._dcc_fail_walk(
                    run_id,
                    state=state,
                    step_id=step.step_id,
                    menu_sha256=None,
                    diagnostic=diagnostic,
                    transport=transport,
                )
            menu = step.menu
            page = page_for_step
            menu_chain.append(menu.menu_sha256)
            retry_menu_sha256 = menu.menu_sha256
            retry_count = 0
            projection = self.controller_routes.projection(run_id)
            if projection is None:
                raise FoundryError("DCC_ROUTE_BINDING_NOT_FOUND", "No DCC controller route is bound to this run.", status_code=404)
            menu_event = self._dcc_append_walk_event(
                run_id,
                event_type=MENU_PUBLISHED,
                subject_sha256=menu.menu_sha256,
                state_sha256_before=projection["state_sha256"],
                state_sha256_after=projection["state_sha256"],
                payload={
                    "step_id": menu.step_id,
                    "ordinal": menu.ordinal,
                    "page": page,
                    "option_count": len(menu.options),
                    "option_ids": list(menu.option_ids),
                },
            )
            self._dcc_save_walk_snapshot(
                run_id,
                step_ordinal=step.ordinal,
                committed=state,
                event=menu_event,
            )
            while True:
                provider_call_done = False
                validated_identity: dict[str, str] | None = None
                try:
                    # Seeded autogeneration answers every step from the seed, no AI.
                    autogen_seed = seeded_picker.request_seed(request)
                    if autogen_seed:
                        receipt = seeded_picker.step_receipt(autogen_seed, menu, request, envelope)
                    else:
                        prompt = build_linear_step_prompt(
                            request,
                            envelope,
                            state,
                            menu,
                            steps_estimate=walk_steps_estimate(request),
                        )
                        schema = build_linear_response_schema(menu, request, envelope)
                        receipt = self._dcc_provider_step(
                            prompt_text=prompt,
                            response_schema=schema,
                        )
                    provider_call_done = True
                    linear_transport = transport["linear_walk"]
                    if autogen_seed:
                        linear_transport["autogen_seed"] = autogen_seed
                    else:
                        transport["provider_called"] = True
                        linear_transport["provider_called"] = True
                    linear_transport["steps"].append(
                        {
                            "step_id": menu.step_id,
                            "ordinal": menu.ordinal,
                            "menu_sha256": menu.menu_sha256,
                            "prompt_n": self._dcc_metric(receipt, "prompt_n", "prompt_tokens"),
                            "predicted_n": self._dcc_metric(receipt, "predicted_n", "completion_tokens", "completion_n"),
                            "ms": self._dcc_metric(receipt, "duration_ms", "ms", "total_ms"),
                        }
                    )
                    selected = self._dcc_response_value(receipt)
                    if menu.step_kind == "identity":
                        validated_identity = validate_linear_identity_owner_lock(selected, request, envelope)
                        option_id = None
                    else:
                        option_id = parse_linear_step_response(selected, menu)
                        from character_creation.insight_build_policy import recommended_build_option
                        preferred = recommended_build_option(menu, model_choice=True)
                        if preferred is not None:
                            # Membership validation comes first; automatic
                            # routes share the same mechanical quality policy.
                            # Explicit owner choices were applied before this menu.
                            option_id = preferred.option_id
                except Exception as exc:
                    if not provider_call_done:
                        diagnostic = self._dcc_diagnostic(exc, step_id=menu.step_id, menu_sha256=menu.menu_sha256)
                        return self._dcc_fail_walk(
                            run_id,
                            state=state,
                            step_id=menu.step_id,
                            menu_sha256=menu.menu_sha256,
                            diagnostic=diagnostic,
                            transport=transport,
                            step_ordinal=step.ordinal,
                        )
                    diagnostic = self._dcc_diagnostic(exc, step_id=menu.step_id, menu_sha256=menu.menu_sha256)
                    if retry_count == 0:
                        retry_count = 1
                        projection = self.controller_routes.projection(run_id)
                        if projection is None:
                            raise FoundryError("DCC_ROUTE_BINDING_NOT_FOUND", "No DCC controller route is bound to this run.", status_code=404)
                        retry_event = self._dcc_append_walk_event(
                            run_id,
                            event_type=STEP_RETRIED,
                            subject_sha256=menu.menu_sha256,
                            state_sha256_before=projection["state_sha256"],
                            state_sha256_after=projection["state_sha256"],
                            payload={"step_id": menu.step_id, "diagnostic_code": diagnostic["code"]},
                        )
                        self._dcc_save_walk_snapshot(
                            run_id,
                            step_ordinal=step.ordinal,
                            committed=state,
                            event=retry_event,
                        )
                        continue
                    return self._dcc_fail_walk(
                        run_id,
                        state=state,
                        step_id=menu.step_id,
                            menu_sha256=menu.menu_sha256,
                            diagnostic=diagnostic,
                            transport=transport,
                            step_ordinal=step.ordinal,
                        )
                projection = self.controller_routes.projection(run_id)
                if projection is None:
                    raise FoundryError("DCC_ROUTE_BINDING_NOT_FOUND", "No DCC controller route is bound to this run.", status_code=404)
                selected_subject = (
                    sha256_bytes(option_id.encode("utf-8"))
                    if isinstance(option_id, str)
                    else sha256_json(selected)
                )
                option_event = self._dcc_append_walk_event(
                    run_id,
                    event_type=OPTION_SELECTED,
                    subject_sha256=selected_subject,
                    state_sha256_before=projection["state_sha256"],
                    state_sha256_after=projection["state_sha256"],
                    payload={
                        "step_id": menu.step_id,
                        **({"option_id": option_id} if isinstance(option_id, str) else {}),
                        "provider_receipt_sha256": self._dcc_receipt_digest(receipt),
                        "prompt_n": self._dcc_metric(receipt, "prompt_n", "prompt_tokens"),
                        "predicted_n": self._dcc_metric(receipt, "predicted_n", "completion_tokens", "completion_n"),
                        "ms": self._dcc_metric(receipt, "duration_ms", "ms", "total_ms"),
                    },
                )
                self._dcc_save_walk_snapshot(
                    run_id,
                    step_ordinal=step.ordinal,
                    committed=state,
                    event=option_event,
                )
                selected_option = next(
                    option for option in menu.options if option.option_id == option_id
                ) if isinstance(option_id, str) else None
                if selected_option is not None and selected_option.is_continuation:
                    # A slot that froze a chain of option windows may serve
                    # more pages than the ordinary three, so a later window is
                    # reachable instead of failing the run. Score assignments
                    # likewise use the menu builder's bounded permutation count.
                    # Other slots keep the ordinary ceiling.
                    page_ceiling = paged_max_pages(
                        request, envelope, menu.step_id.split(":", 1)[0], MAX_PAGES_PER_STEP)
                    if menu.step_kind == "point_buy_assignment":
                        from character_creation.creative_controller.linear_menus import point_buy_assignment_page_limit
                        page_ceiling = point_buy_assignment_page_limit(request, envelope, state)
                    if page_for_step >= page_ceiling:
                        diagnostic = self._dcc_diagnostic(
                            FoundryError(
                                "DCC_LINEAR_PAGE_LIMIT",
                                "This list of options ran out of pages before every option was shown.",
                            ),
                            step_id=menu.step_id,
                            menu_sha256=menu.menu_sha256,
                        )
                        return self._dcc_fail_walk(
                            run_id,
                            state=state,
                            step_id=menu.step_id,
                            menu_sha256=menu.menu_sha256,
                            diagnostic=diagnostic,
                            transport=transport,
                            step_ordinal=step.ordinal,
                        )
                    page_for_step += 1
                    retry_menu_sha256 = None
                    retry_count = 0
                    break
                try:
                    if menu.step_kind == "identity":
                        if validated_identity is None:
                            raise FoundryError(
                                "DCC_LINEAR_IDENTITY_VALIDATION_MISSING",
                                "The identity response was not validated before commit.",
                                status_code=409,
                            )
                        committed_state = state.with_identity(
                            validated_identity["name"],
                            validated_identity["title"],
                            validated_identity.get("concept"),
                        )
                        committed_ids: list[str] = []
                        identity = validated_identity
                    else:
                        committed_state = commit_linear_option(menu, option_id, state)
                        committed_ids = list(next(option for option in menu.options if option.option_id == option_id).choice_ids)
                        identity = None
                except Exception as exc:
                    diagnostic = self._dcc_diagnostic(exc, step_id=menu.step_id, menu_sha256=menu.menu_sha256)
                    return self._dcc_fail_walk(
                        run_id,
                        state=state,
                        step_id=menu.step_id,
                        menu_sha256=menu.menu_sha256,
                        diagnostic=diagnostic,
                        transport=transport,
                        step_ordinal=step.ordinal,
                    )
                projection = self.controller_routes.projection(run_id)
                if projection is None:
                    raise FoundryError("DCC_ROUTE_BINDING_NOT_FOUND", "No DCC controller route is bound to this run.", status_code=404)
                commit_payload: dict[str, Any] = {
                    "step_id": menu.step_id,
                    "choice_ids": committed_ids,
                }
                if menu.step_kind in {"point_buy_preset", "point_buy_assignment", "background_ability",
                                      "asi_or_insight", "asi_milestone", "insight_occurrence"}:
                    option = next((option for option in menu.options if option.option_id == option_id), None)
                    if option is not None:
                        from character_creation.insight_build_policy import build_choice_reason
                        from character_creation.creative_controller.linear_menus import mechanical_choice_detail
                        commit_payload["build_choice_reason"] = build_choice_reason(
                            menu, option, mechanical_choice_detail(request, envelope, state, menu, option))
                        proposed = selected.get("option_id") if isinstance(selected, Mapping) else None
                        if isinstance(proposed, str) and proposed != option_id:
                            commit_payload["provider_proposed_option_id"] = proposed
                if isinstance(identity, Mapping):
                    commit_payload["identity"] = deepcopy(dict(identity))
                commit_event = self._dcc_append_walk_event(
                    run_id,
                    event_type=STEP_COMMITTED,
                    subject_sha256=committed_state.committed_sha256,
                    state_sha256_before=projection["state_sha256"],
                    state_sha256_after=committed_state.committed_sha256,
                    payload=commit_payload,
                )
                self._dcc_save_walk_snapshot(
                    run_id,
                    step_ordinal=step.ordinal,
                    committed=committed_state,
                    event=commit_event,
                )
                state = committed_state
                retry_menu_sha256 = None
                retry_count = 0
                page_for_step = 1
                break
            # The next outer iteration rebuilds the menu from the committed
            # typed state; continuation pages never mutate that state.
            continue

    def continue_controller_walk(self, run_id: str) -> dict[str, Any]:
        """Resume a DCC walk after a bounded failure or process restart."""

        run = self.get(run_id)
        route = (run.get("request") or {}).get("controller_route")
        if route != DETERMINISTIC_CREATIVE_CONTROLLER:
            raise FoundryError("DCC_LINEAR_ROUTE_REQUIRED", "Only DCC linear runs can be continued.", status_code=409)
        if run.get("status") in {"CLEAN_AND_FINALIZED", "CANCELLED", "REVISED"}:
            return run
        return self._run_dcc_linear_walk(run_id, resume=True)

    @staticmethod
    def _dcc_step_title(step_id: Any) -> str | None:
        if not isinstance(step_id, str) or not step_id:
            return None
        kind = step_id.split(":", 1)[0]
        return STEP_TITLES.get(kind, kind.replace("_", " ").title())

    _DCC_PROGRESS_NAME_CACHE_LIMIT = 16

    def _dcc_progress_names(self, run_id: str) -> dict[str, str]:
        """Frozen choice-ID -> name map for one run, parsed once and cached."""

        cache = getattr(self, "_dcc_progress_name_cache", None)
        if cache is None:
            cache = {}
            self._dcc_progress_name_cache = cache
        if run_id in cache:
            return cache[run_id]
        with self.db.connection() as conn:
            row = conn.execute("SELECT request_json FROM character_creation_runs WHERE run_id=?", (run_id,)).fetchone()
        try:
            request = json.loads(row["request_json"]) if row is not None and row["request_json"] else {}
        except (TypeError, ValueError):
            request = {}
        names = self._dcc_choice_names({"request": request})
        if len(cache) >= self._DCC_PROGRESS_NAME_CACHE_LIMIT:
            cache.pop(next(iter(cache)))
        cache[run_id] = names
        return names

    @staticmethod
    def _dcc_choice_names(run: Mapping[str, Any]) -> dict[str, str]:
        """Map frozen choice IDs to their catalogue names, nothing else."""

        request = run.get("request") if isinstance(run.get("request"), Mapping) else {}
        envelope = request.get("delegated_choice_envelope") if isinstance(request.get("delegated_choice_envelope"), Mapping) else {}
        names: dict[str, str] = {}
        slots = envelope.get("choices_by_slot")
        if not isinstance(slots, Mapping):
            return names
        for rows in slots.values():
            items = rows.values() if isinstance(rows, Mapping) else rows if isinstance(rows, (list, tuple)) else []
            for row in items:
                if not isinstance(row, Mapping):
                    continue
                choice_id = row.get("choice_id") or row.get("id")
                name = row.get("name") or row.get("display_name") or row.get("title")
                if isinstance(choice_id, str) and choice_id and isinstance(name, str) and name:
                    names.setdefault(choice_id, name)
        return names

    def controller_active_run(self, project_id: str) -> dict[str, Any]:
        """Cheapest possible lookup of the newest DCC run for a project.

        The guided page polls this while its synchronous start call is
        pending.  It is one indexed row scan with no run reconstruction, so
        polling it every two seconds cannot compete with the walk itself.
        """

        with self.db.connection() as conn:
            rows = conn.execute(
                "SELECT run_id, status, json_extract(request_json, '$.controller_route') AS route, created_at FROM character_creation_runs WHERE project_id=? ORDER BY created_at DESC LIMIT 8",
                (project_id,),
            ).fetchall()
        for row in rows:
            # Route via SQLite JSON extraction: parsing the multi-megabyte
            # request JSON in Python for every poll held the interpreter.
            if row["route"] == DETERMINISTIC_CREATIVE_CONTROLLER:
                return {
                    "schema": "TianxiaFoundry.DccActiveRun.v1",
                    "project_id": project_id,
                    "run_id": row["run_id"],
                    "status": row["status"],
                    "created_at": row["created_at"],
                }
        return {"schema": "TianxiaFoundry.DccActiveRun.v1", "project_id": project_id, "run_id": None, "status": None, "created_at": None}

    def controller_walk_progress(self, run_id: str) -> dict[str, Any]:
        """Owner-facing progress of a DCC linear walk: step position and catalogue names only.

        No option cues, choice IDs, menus, hashes, or prompt text leave this
        view.  The bounded status comes from the persisted walk events and
        the committed snapshot; names come from the frozen envelope rows.
        """

        # Polled every few seconds by the guided page: never rebuild the run
        # (multi-megabyte request JSON) or verify the event chain here.  The
        # frozen choice names are immutable per run and cached; the route is
        # read with SQLite's JSON extraction; the full run is loaded only when
        # a NEEDS_REVIEW diagnostic has to be shown.
        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT status, json_extract(request_json, '$.controller_route') AS route, project_id FROM character_creation_runs WHERE run_id=?",
                (run_id,),
            ).fetchone()
        if row is None:
            raise FoundryError("RUN_NOT_FOUND", "No character creation run has that ID.", status_code=404)
        if row["route"] != DETERMINISTIC_CREATIVE_CONTROLLER:
            raise FoundryError("DCC_LINEAR_ROUTE_REQUIRED", "Only DCC linear runs report walk progress.", status_code=409)
        run: dict[str, Any] = {"run_id": run_id, "status": row["status"], "project_id": row["project_id"]}
        if row["status"] == "NEEDS_REVIEW":
            run = self.get(run_id)
        names = self._dcc_progress_names(run_id)
        walk = self.linear_walk.status_light(run_id)
        snapshot = self.linear_walk.load_snapshot(run_id)
        committed: list[dict[str, Any]] = []
        state = snapshot.get("committed") if isinstance(snapshot, Mapping) else None
        state_map = state.to_dict() if isinstance(state, CommittedState) else state if isinstance(state, Mapping) else {}

        def named(values: Any) -> list[str]:
            result: list[str] = []
            for value in values if isinstance(values, (list, tuple)) else []:
                if isinstance(value, str) and value in names and names[value] not in result:
                    result.append(names[value])
            return result[:24]

        by_slot = state_map.get("by_slot") if isinstance(state_map.get("by_slot"), Mapping) else {}
        for slot_id, values in by_slot.items():
            labels = named(values)
            count = len(values) if isinstance(values, (list, tuple)) else 0
            if count:
                committed.append({"step_kind": slot_id, "title": self._dcc_step_title(slot_id) or slot_id, "names": labels, "count": count})
        pairs = state_map.get("pairs") if isinstance(state_map.get("pairs"), (list, tuple)) else []
        pair_labels = [
            " + ".join(label for label in (names.get(row.get("sphere_id")), names.get(row.get("talent_id"))) if label)
            for row in pairs if isinstance(row, Mapping)
        ]
        if pairs:
            committed.append({"step_kind": "sphere_free_talent_pair", "title": STEP_TITLES["sphere_free_talent_pair"], "names": [label for label in pair_labels if label][:24], "count": len(pairs)})
        ordinary = state_map.get("ordinary_by_cl") if isinstance(state_map.get("ordinary_by_cl"), Mapping) else {}
        if ordinary:
            ordered = [ordinary[key] for key in sorted(ordinary, key=lambda value: (len(str(value)), str(value)))]
            committed.append({"step_kind": "ordinary_talent", "title": STEP_TITLES["ordinary_talent"], "names": named(ordered), "count": len(ordered)})
        occurrences = state_map.get("insight_occurrences") if isinstance(state_map.get("insight_occurrences"), (list, tuple)) else []
        if occurrences:
            committed.append({"step_kind": "insight_occurrence", "title": STEP_TITLES["insight_occurrence"], "names": named([row.get("insight_id") for row in occurrences if isinstance(row, Mapping)]), "count": len(occurrences)})
        bounded = state_map.get("bounded") if isinstance(state_map.get("bounded"), Mapping) else {}
        bounded_titles = {
            "point_buy_preset": "point_buy_preset", "ability_scores": "point_buy_assignment", "background_ability": "background_ability",
            "ability_score_changes_by_milestone_id": "asi_milestone", "path_progression_by_cl": "path_progression",
            "path_skill_choices_by_path_id": "path_skill", "origin_skill_choices_by_origin_id": "origin_skill",
            "background_language_choices_by_background_id": "background_language",
            "foundation_initial_stage": "foundation_initial_stage",
        }
        for key, kind in bounded_titles.items():
            value = bounded.get(key)
            if value:
                count = len(value) if isinstance(value, (Mapping, list, tuple)) else 1
                committed.append({"step_kind": kind, "title": STEP_TITLES[kind], "names": [], "count": count})
        identity = state_map.get("identity") if isinstance(state_map.get("identity"), Mapping) else None
        if identity and isinstance(identity.get("name"), str) and identity["name"]:
            committed.append({"step_kind": "identity", "title": STEP_TITLES["identity"], "names": [identity["name"]], "count": 1})
        diagnostic_source = (run.get("validation") or {}).get("last_submission_error") if isinstance(run.get("validation"), Mapping) else None
        diagnostic = None
        if run.get("status") == "NEEDS_REVIEW" and isinstance(diagnostic_source, Mapping):
            step_id = (diagnostic_source.get("details") or {}).get("step_id") if isinstance(diagnostic_source.get("details"), Mapping) else None
            step_id = step_id if isinstance(step_id, str) else (walk or {}).get("step_id")
            diagnostic = {
                "code": diagnostic_source.get("code"),
                "message": diagnostic_source.get("message"),
                "step_title": self._dcc_step_title(step_id),
            }
        return {
            "schema": "TianxiaFoundry.DccLinearWalkProgress.v1",
            "run_id": run_id,
            "project_id": run.get("project_id"),
            "status": run.get("status"),
            "walk": {
                "state": walk.get("state"),
                "step_ordinal": walk.get("step_ordinal"),
                "step_title": self._dcc_step_title(walk.get("step_id")),
                "steps_estimate": walk.get("steps_estimate"),
            } if isinstance(walk, Mapping) else None,
            "committed_choices": committed[:64],
            "diagnostic": diagnostic,
            "can_continue": run.get("status") == "NEEDS_REVIEW",
        }

    def cancel_controller_walk(self, run_id: str) -> dict[str, Any]:
        """Cancel a DCC walk without invoking provider transport."""

        run = self.get(run_id)
        route = (run.get("request") or {}).get("controller_route")
        if route != DETERMINISTIC_CREATIVE_CONTROLLER:
            raise FoundryError("DCC_LINEAR_ROUTE_REQUIRED", "Only DCC linear runs can be cancelled.", status_code=409)
        if run.get("status") in TERMINAL_RUN_STATUSES:
            return run
        with self.db.transaction() as conn:
            conn.execute(
                "UPDATE character_creation_runs SET status='CANCELLED',updated_at=? WHERE run_id=?",
                (utcnow(), run_id),
            )
        return self.get(run_id)

    @staticmethod
    def _stage_for_status(status: str) -> int:
        return {
            "PREPARING_REQUEST": 2,
            "WAITING_FOR_RESPONSE": 2,
            "NEEDS_REVIEW": 3,
            "READY_FOR_REVIEW": 3,
            "CLEAN_AND_FINALIZED": 4,
            "CANCELLED": 2,
            "REVISED": 2,
        }.get(status, 2)

    @staticmethod
    def _owner_stage_for_status(status: str) -> int:
        """Map persisted lifecycle states to the four-screen owner flow.

        ``stage`` remains the legacy four-stage recovery/evidence contract.  The
        owner workspace uses this separate field so a waiting response is not
        presented as the Path/Method screen and a finalized run opens its saved
        sheet on the same review page rather than the legacy Finalize panel.
        Owner request 2026-09-13 (one page after the AI build): the review page
        is step 4 and every post-build state stays on it.
        """
        return {
            "PREPARING_REQUEST": 3,
            "WAITING_FOR_RESPONSE": 3,
            "READY_FOR_REVIEW": 4,
            "NEEDS_REVIEW": 4,
            "CLEAN_AND_FINALIZED": 4,
            "CANCELLED": 4,
            "REVISED": 3,
        }.get(status, 1)

    def _next_action_for_status(self, run: dict[str, Any], *, audit_provider: bool = True) -> str:
        status = run.get("status")
        if status == "WAITING_FOR_RESPONSE":
            return "Load one response file or paste the complete response."
        if status == "PREPARING_REQUEST":
            return "Resume the build and inspect the request status."
        if status == "NEEDS_REVIEW":
            if gm_candidate_authoring_gate(run):
                return GM_CANDIDATE_AUTHORING_NEXT_ACTION
            validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
            diagnostic = validation.get("last_submission_error") if isinstance(validation, dict) else None
            diagnostic = diagnostic if isinstance(diagnostic, dict) else run.get("submission_error")
            if (
                isinstance(diagnostic, dict)
                and diagnostic.get("code") in _LOCAL_PROVIDER_CORRECTION_CODES
                and audit_provider
                and self._explicit_provider_correction_context(run) is not None
            ):
                return "Ask Local AI to Fix This, or choose Replace Response, Retry Local Build (no provider), Edit Brief / Create New Request, or Cancel Build."
            return "Inspect the blocker, then choose Replace Response, Retry Local Build (no provider), Edit Brief / Create New Request, or Cancel Build."
        if status == "READY_FOR_REVIEW":
            return "Review the proposal and choose Finalize, Edit Brief / Create New Request, or Cancel Build."
        if status == "CLEAN_AND_FINALIZED":
            return "Open the completed Character Sheet."
        if status == "CANCELLED":
            return "Start a deliberate new build when you are ready."
        if status == "REVISED":
            return "Resume the replacement build."
        return "Inspect the current build state."

    def _recovery_summary(self, run: dict[str, Any], *, audit_provider: bool = True) -> dict[str, Any]:
        request = run.get("request") or {}
        response = run.get("response") or {}
        summary = {
            "run_id": run.get("run_id"),
            "project_id": run.get("project_id"),
            "starting_revision": run.get("starting_revision"),
            "execution_mode": run.get("execution_mode"),
            "status": run.get("status"),
            "stage": self._stage_for_status(str(run.get("status") or "")),
            "owner_stage": self._owner_stage_for_status(str(run.get("status") or "")),
            "next_legal_action": self._next_action_for_status(run, audit_provider=audit_provider),
            "request_sha256": request.get("request_sha256"),
            "content_lock_hash": request.get("content_lock_hash"),
            "response_sha256": response.get("response_sha256"),
            "response_binding": {
                "request_sha256": request.get("request_sha256"),
                "response_sha256": response.get("response_sha256"),
                "binding_status": "BOUND" if response.get("response_sha256") and not run.get("submission_error") else "WAITING_FOR_RESPONSE" if not response.get("response_sha256") else "REVIEW_REQUIRED",
            },
            "blockers": deepcopy(run.get("blockers") or []),
            "warnings": deepcopy(run.get("warnings") or []),
            "submission_error": deepcopy(run.get("submission_error")),
            "owner_descriptive_fields": deepcopy(run.get("owner_descriptive_fields") or {}),
            "attempt_history": deepcopy(run.get("attempt_history") or []),
            "action_availability": self._action_availability(run, audit_provider=audit_provider),
            "updated_at": run.get("updated_at"),
        }
        route_status = run.get("controller_route_status")
        if isinstance(route_status, dict):
            # Recovery is a public summary surface; carry only the safe route
            # state and hashes, never the sealed binding or event bodies.
            summary["controller_route_status"] = {
                key: route_status.get(key)
                for key in (
                    "schema", "run_id", "project_id", "mode", "route_mode", "state",
                    "activation_policy", "request_sha256", "binding_sha256",
                    "event_count", "event_head_sha256", "controller_version_sha256",
                    "operator_contract_sha256", "publication_receipt_sha256",
                    "content_snapshot_sha256", "semantic_authority_bundle_sha256",
                    "source_rights_authority_sha256", "selected_ai_identity_sha256",
                    "selected_ai_identity_state",
                )
                if key in route_status
            }
        return summary

    @staticmethod
    def _is_dcc_route_run(run: dict[str, Any]) -> bool:
        """Identify the immutable DCC route without consulting the provider."""

        if not isinstance(run, dict):
            return False
        request = run.get("request")
        if not isinstance(request, dict):
            return False
        if request.get("controller_route") == DETERMINISTIC_CREATIVE_CONTROLLER:
            return True
        binding = request.get("controller_route_binding")
        return isinstance(binding, dict) and binding.get("route_mode") == DETERMINISTIC_CREATIVE_CONTROLLER

    @staticmethod
    def _dcc_provider_execution_error() -> FoundryError:
        return FoundryError(
            DCC_PROVIDER_EXECUTION_NOT_ACTIVATED,
            DCC_PROVIDER_EXECUTION_NOT_ACTIVATED_MESSAGE,
            status_code=409,
        )

    def _reject_dcc_provider_execution(self, run_id: str) -> None:
        """Reject provider entry points before loading a provider-audited run."""

        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT request_json FROM character_creation_runs WHERE run_id=?",
                (run_id,),
            ).fetchone()
        if row is None:
            return
        try:
            request = json.loads(row["request_json"]) if row["request_json"] else {}
        except (TypeError, ValueError, json.JSONDecodeError):
            # The normal reload path will fail closed on malformed request JSON;
            # do not attempt any provider work while its route is unknowable.
            return
        if self._is_dcc_route_run({"request": request}):
            raise self._dcc_provider_execution_error()

    def _action_availability(self, run: dict[str, Any], *, audit_provider: bool = True) -> dict[str, dict[str, Any]]:
        status = str(run.get("status") or "")
        terminal = status in TERMINAL_RUN_STATUSES
        response = run.get("response") or {}
        response_present = bool(response.get("response_sha256"))
        # Compact global recovery rows deliberately omit the frozen request and
        # exact response text.  They are chooser projections only, so a local
        # correction action must stay unavailable until the direct run endpoint
        # performs the complete evidence audit.
        dcc_route = self._is_dcc_route_run(run)
        support_blocked = factory_support_blocker(run)
        local_correction_available = (
            not dcc_route
            and not support_blocked
            and audit_provider
            and self._explicit_provider_correction_context(run) is not None
        )
        local_correction_reason = (
            DCC_PROVIDER_EXECUTION_NOT_ACTIVATED_MESSAGE
            if dcc_route
            else "Ask Local AI to Fix This requires a non-terminal provider or Local-AI auto-build review run, a retained allowlisted provider diagnostic, and the same selected local provider."
        )
        return {
            "replace_response": {
                "available": not support_blocked and not terminal and run.get("execution_mode") == "MANUAL_CHAT",
                "reason": "This source-authority gap needs a Factory update; replacing the response cannot supply the missing rules." if support_blocked else "Import one corrected response for this same frozen request." if not terminal and run.get("execution_mode") == "MANUAL_CHAT" else "Replace Response is unavailable after finalization/cancellation or for a provider-only run.",
            },
            "retry_local_build": {
                "available": not terminal and response_present and status in {"READY_FOR_REVIEW", "NEEDS_REVIEW"},
                "reason": "Retry the persisted response without contacting an external provider." if not terminal and response_present and status in {"READY_FOR_REVIEW", "NEEDS_REVIEW"} else "Retry requires a persisted response and a non-terminal review/build state.",
            },
            "retry_local_ai_correction": {
                "available": local_correction_available,
                "reason": "This source-authority gap needs a Factory update; Local AI cannot supply missing rules authority." if support_blocked else "Send the exact retained response and validator issue to the selected Local AI while keeping this request frozen." if local_correction_available else local_correction_reason,
            },
            "edit_brief_create_new_request": {
                "available": not terminal,
                "reason": "Create a linked request with a deliberate brief or lock change; prior history remains inspectable." if not terminal else "A terminal run cannot be edited; start a deliberate new request.",
            },
            "cancel_build": {
                "available": not terminal,
                "reason": "Cancel this build explicitly and retain its attempt history." if not terminal else "This build is already terminal.",
            },
        }

    @staticmethod
    def _run_matches_project_revision(run: dict[str, Any], project_revision: int) -> bool:
        """Only a run frozen at the current project revision can be active."""
        try:
            starting_revision = (
                run.get("starting_revision")
                if isinstance(run, dict)
                else run["starting_revision"]
            )
            if isinstance(starting_revision, bool):
                return False
            return int(starting_revision) == int(project_revision)
        except (TypeError, ValueError):
            return False

    def _run_is_recovery_candidate(self, run: dict[str, Any], project_revision: int) -> bool:
        """Exclude only revision-stale active rows from recovery selection."""
        return (
            run.get("status") not in ACTIVE_RUN_STATUSES
            if isinstance(run, dict)
            else run["status"] not in ACTIVE_RUN_STATUSES
        ) or self._run_matches_project_revision(run, project_revision)

    def recovery(self, project_id: str, *, audit_provider: bool = True) -> dict[str, Any]:
        project = self._project(project_id)
        runs = self._compact_recovery_runs(project_id)
        project_revision = int(project.get("revision") or 0)
        active = next(
            (
                run
                for run in runs
                if run.get("status") in ACTIVE_RUN_STATUSES
                and self._run_matches_project_revision(run, project_revision)
            ),
            None,
        )
        latest = next(
            (run for run in runs if self._run_is_recovery_candidate(run, project_revision)),
            None,
        )
        # The compact query intentionally omits retained response text.  Load
        # the selected run only for the server-side eligibility audit so the
        # Local-AI recovery action can be truthful without exposing that text
        # through the recovery projection.
        active_full = self.get(active["run_id"]) if active and audit_provider else None
        latest_full = (
            self.get(latest["run_id"])
            if latest and latest is not active and audit_provider
            else active_full
        )
        active_summary = (
            self._recovery_summary(active_full or active, audit_provider=audit_provider)
            if active
            else None
        )
        latest_summary = (
            deepcopy(active_summary)
            if latest is active
            else self._recovery_summary(latest_full or latest, audit_provider=audit_provider)
            if latest
            else None
        )
        summary = active_summary or latest_summary
        content_lock = project.get("content_lock") if isinstance(project, dict) else None
        content_lock_hash = (
            content_lock.get("lock_hash")
            if isinstance(content_lock, dict)
            else None
        ) or (project.get("content_lock_hash") if isinstance(project, dict) else None) or ""
        return {
            "schema": "TianxiaFoundry.CharacterCreationRecovery.v1",
            "project_id": project_id,
            "project_revision": int(project.get("revision") or 0),
            "content_lock_hash": str(content_lock_hash),
            "project_name": project.get("name"),
            "active": active is not None,
            "active_run": active_summary,
            "latest_run": latest_summary,
            "attempt_history": deepcopy((active or latest or {}).get("attempt_history") or []),
            "next_legal_action": summary.get("next_legal_action") if summary else "Start a complete-character build when the owner is ready.",
            "action_availability": self._action_availability(
                active_full or latest_full or active or latest or {},
                audit_provider=audit_provider,
            ),
        }

    def _chooser_recoverable(self) -> list[dict[str, Any]]:
        """Return the startup chooser projection without opening payload blobs.

        The global chooser only needs enough identity and lifecycle data to let
        the owner select a project/run.  It immediately fetches the selected
        run through the direct run endpoint, so reading request/response,
        validation, final-plan, attempt, or full project JSON here would add
        avoidable latency (and can block on retained multi-megabyte requests).
        The direct ``recovery(project_id)`` path remains the audited, detailed
        recovery surface.
        """
        with self.db.connection() as conn:
            project_rows = conn.execute(
                """
                SELECT project_id, working_name, revision
                FROM projects
                ORDER BY updated_at DESC
                """
            ).fetchall()
            run_rows = conn.execute(
                """
                SELECT
                    run_id,
                    project_id,
                    starting_revision,
                    execution_mode,
                    status,
                    updated_at,
                    created_at
                FROM character_creation_runs
                ORDER BY project_id, created_at DESC
            """
            ).fetchall()

        runs_by_project: dict[str, list[Any]] = {}
        for row in run_rows:
            project_id = row["project_id"]
            if isinstance(project_id, str):
                runs_by_project.setdefault(project_id, []).append(row)

        result: list[dict[str, Any]] = []
        for project_row in project_rows:
            project_id = project_row["project_id"]
            if not isinstance(project_id, str):
                continue
            runs = runs_by_project.get(project_id) or []
            if not runs:
                continue
            active_row = next(
                (
                    row
                    for row in runs
                    if row["status"] in ACTIVE_RUN_STATUSES
                    and self._run_matches_project_revision(
                        row,
                        int(project_row["revision"] or 0),
                    )
                ),
                None,
            )
            project_revision = int(project_row["revision"] or 0)
            latest_row = next(
                (row for row in runs if self._run_is_recovery_candidate(row, project_revision)),
                None,
            )
            if latest_row is None:
                continue

            def compact_run(row: Any) -> dict[str, Any]:
                return {
                    "run_id": row["run_id"],
                    "project_id": project_id,
                    "starting_revision": row["starting_revision"],
                    "execution_mode": row["execution_mode"],
                    "status": row["status"],
                    "updated_at": row["updated_at"],
                    "request": {},
                    "response": {},
                    "blockers": [],
                    "warnings": [],
                    "submission_error": None,
                    "owner_descriptive_fields": {},
                    "attempt_history": [],
                }

            active = compact_run(active_row) if active_row else None
            latest = compact_run(latest_row) if latest_row else None
            active_summary = self._recovery_summary(active, audit_provider=False) if active else None
            latest_summary = (
                deepcopy(active_summary)
                if active_row is latest_row
                else self._recovery_summary(latest, audit_provider=False)
                if latest
                else None
            )
            summary = active_summary or latest_summary
            chooser = {
                "schema": "TianxiaFoundry.CharacterCreationRecovery.v1",
                "project_id": project_id,
                "project_revision": int(project_row["revision"] or 0),
                "content_lock_hash": None,
                "project_name": project_row["working_name"],
                "active": active is not None,
                "active_run": active_summary,
                "latest_run": latest_summary,
                "attempt_history": [],
                "next_legal_action": (
                    summary.get("next_legal_action")
                    if summary
                    else "Start a complete-character build when the owner is ready."
                ),
                "action_availability": self._action_availability(
                    active or latest,
                    audit_provider=False,
                ),
            }
            result.append(chooser)
        return result

    def recoverable(self) -> list[dict[str, Any]]:
        return self._chooser_recoverable()

    def evidence(self, run_id: str) -> dict[str, Any]:
        run = self.get(run_id)
        request = run.get("request") or {}
        response = run.get("response") or {}
        validation = run.get("validation") or {}
        return {
            "schema": "TianxiaFoundry.CharacterCreationBuildEvidence.v1",
            "run_id": run.get("run_id"),
            "project_id": run.get("project_id"),
            "stage": self._stage_for_status(str(run.get("status") or "")),
            "status": run.get("status"),
            "execution_mode": run.get("execution_mode"),
            "starting_revision": run.get("starting_revision"),
            "request_binding": {
                "request_sha256": request.get("request_sha256"),
                "content_lock_hash": request.get("content_lock_hash"),
                "project_id": request.get("project_id"),
                "project_revision": request.get("project_revision"),
                "typed_choice_snapshot_sha256": (request.get("typed_choice_snapshot") or {}).get("snapshot_sha256"),
                "idempotency_binding_sha256": request.get("idempotency_binding_sha256"),
            },
            "response_binding": {
                "response_sha256": response.get("response_sha256"),
                "submitted_request_sha256": (run.get("transport") or {}).get("submitted_request_sha256"),
                "binding_status": "BOUND" if response.get("response_sha256") and not run.get("submission_error") else "NOT_BOUND_OR_REQUIRES_REVIEW",
            },
            "source_provenance": deepcopy((run.get("transport") or {}).get("source_provenance") or {}),
            "response_view": {
                "exact_response_present": bool(response.get("exact_response_text")),
                "response_sha256": response.get("response_sha256"),
                "parsed_plan": deepcopy(response.get("parsed_plan")) if isinstance(response.get("parsed_plan"), dict) else None,
                "owner_descriptive_fields": deepcopy(run.get("owner_descriptive_fields")),
            },
            "canonical_intent": {
                "schema": "TianxiaFoundry.DelegatedSelectionIntent.v1" if run.get("canonical_intent_hash") else None,
                "intent_sha256": run.get("canonical_intent_hash"),
                "materialized_plan_sha256": run.get("materialized_plan_sha256"),
                "submitted_plan_sha256": run.get("submitted_plan_sha256"),
                "receipt": deepcopy((run.get("validation") or {}).get("materialization_receipt") or {}),
            },
            "owner_descriptive_fields": deepcopy(run.get("owner_descriptive_fields")),
            "blockers": deepcopy(run.get("blockers") or []),
            "warnings": deepcopy(run.get("warnings") or []),
            "submission_error": deepcopy(run.get("submission_error")),
            "validation": {
                key: deepcopy(value)
                for key, value in validation.items()
                if key != "last_submission_error"
            },
            "last_submission_error": deepcopy(validation.get("last_submission_error")),
            "quality": deepcopy(run.get("quality") or {}),
            "dry_run": {
                key: deepcopy((run.get("dry_run") or {}).get(key))
                for key in ("schema", "candidate_identity", "identities", "deterministic", "independent_compilations", "artifacts", "preview")
                if key in (run.get("dry_run") or {})
            },
            "next_legal_action": self._next_action_for_status(run),
            "finalize_in_progress": getattr(self, "_finalizing_run_id", None) == run.get("run_id"),
            "action_availability": deepcopy((self.recovery(run["project_id"]).get("active_run") or self.recovery(run["project_id"]).get("latest_run") or {}).get("action_availability") or {}),
            "attempt_history": deepcopy(run.get("attempt_history") or []),
        }

    @staticmethod
    def _server_owned_output_profile_target(
        *,
        project_id: str,
        project_revision: int,
        content_lock_hash: str,
        combat_ready: bool,
        request_sha256: str = "",
    ) -> dict[str, Any]:
        """Build the immutable owner-selected output-profile target.

        The request hash is filled after the complete request payload is
        assembled.  ``canonical_request_payload`` excludes only that one
        nested binding value, making the final request hash stable while the
        target still carries an exact request binding for every consumer.
        """
        if (
            not isinstance(project_id, str)
            or not project_id.strip()
            or type(project_revision) is not int
            or not isinstance(content_lock_hash, str)
            or type(combat_ready) is not bool
            or not isinstance(request_sha256, str)
        ):
            raise FoundryError(
                "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                "The owner output-profile target has an invalid binding or readiness value.",
                status_code=409,
            )
        return {
            "schema": SERVER_OUTPUT_PROFILE_SCHEMA,
            "profile": SERVER_OUTPUT_PROFILE_NAME,
            "combat_ready": combat_ready,
            "binding": {
                "project_id": project_id,
                "project_revision": project_revision,
                "content_lock_hash": content_lock_hash,
                "request_sha256": request_sha256,
            },
        }

    @classmethod
    def _validated_server_owned_output_profile_target(
        cls,
        run: dict[str, Any],
        *,
        allow_legacy_missing: bool = True,
    ) -> dict[str, Any] | None:
        """Validate the exact request-bound owner target for delegated runs."""
        request = run.get("request") if isinstance(run, dict) else None
        if not isinstance(request, dict):
            if allow_legacy_missing:
                return None
            raise FoundryError(
                "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                "The run has no complete server-owned output-profile request authority.",
                status_code=409,
            )
        server_authority = request.get("server_owned_authority")
        server_authority = server_authority if isinstance(server_authority, dict) else {}
        target_marker_present = "output_profile_target_required" in server_authority
        if target_marker_present and server_authority.get("output_profile_target_required") is not True:
            raise FoundryError(
                "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                "The server-owned output-profile target requirement marker is malformed.",
                status_code=409,
            )
        if "output_profile" not in server_authority:
            if target_marker_present:
                raise FoundryError(
                    "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                    "The run is marked as requiring a server-owned output-profile target, but the target is absent.",
                    status_code=409,
                )
            if allow_legacy_missing:
                return None
            raise FoundryError(
                "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                "The run has no complete server-owned output-profile request authority.",
                status_code=409,
            )
        target = server_authority.get("output_profile")
        expected_keys = {"schema", "profile", "combat_ready", "binding"}
        binding_keys = {"project_id", "project_revision", "content_lock_hash", "request_sha256"}
        request_sha256 = request.get("request_sha256")
        project_id = run.get("project_id")
        project_revision = run.get("starting_revision")
        content_lock_hash = request.get("content_lock_hash")
        binding = target.get("binding") if isinstance(target, dict) else None
        if (
            not isinstance(target, dict)
            or set(target) != expected_keys
            or target.get("schema") != SERVER_OUTPUT_PROFILE_SCHEMA
            or target.get("profile") != SERVER_OUTPUT_PROFILE_NAME
            or type(target.get("combat_ready")) is not bool
            or not isinstance(binding, dict)
            or set(binding) != binding_keys
            or not isinstance(project_id, str)
            or not project_id.strip()
            or not isinstance(request.get("project_id"), str)
            or request.get("project_id") != project_id
            or type(project_revision) is not int
            or type(request.get("project_revision")) is not int
            or request.get("project_revision") != project_revision
            or not isinstance(content_lock_hash, str)
            or not isinstance(binding.get("project_id"), str)
            or not binding.get("project_id").strip()
            or type(binding.get("project_revision")) is not int
            or not isinstance(binding.get("content_lock_hash"), str)
            or not isinstance(binding.get("request_sha256"), str)
            or binding.get("project_id") != project_id
            or binding.get("project_revision") != project_revision
            or binding.get("content_lock_hash") != content_lock_hash
            or not isinstance(request_sha256, str)
            or len(request_sha256) != 64
            or any(character not in "0123456789abcdef" for character in request_sha256)
            or binding.get("request_sha256") != request_sha256
            or cls.request_payload_sha256(request) != request_sha256
        ):
            raise FoundryError(
                "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                "The server-owned output-profile target is malformed or no longer bound to this request.",
                details={"field": "server_owned_authority.output_profile"},
                status_code=409,
            )
        return deepcopy(target)

    def _complete_request(
        self,
        project_id: str,
        revision_request: dict[str, Any] | None = None,
        *,
        execution_mode: str = "MANUAL_CHAT",
        idempotency_key: str = "",
        combat_ready: bool = False,
        controller_route: str = LEGACY_FULL_PLAN,
        manual_collection_nonce: str | None = None,
        required_forged_design_ids: list[str] | None = None,
    ) -> dict[str, Any]:
        from character_creation.constructed_arts.explicit_forging import normalize_required_design_ids
        required_designs = normalize_required_design_ids(required_forged_design_ids, revision_request)
        if required_designs and normalize_controller_route(controller_route) != DETERMINISTIC_CREATIVE_CONTROLLER:
            raise FoundryError("CG1_REQUIRED_FORGED_DESIGNS_ROUTE_UNSUPPORTED", "Required Forge designs need the deterministic creative controller.", status_code=422)
        if type(combat_ready) is not bool:
            raise FoundryError(
                "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                "combat_ready must be an explicit boolean owner target.",
                status_code=422,
            )
        controller_route = normalize_controller_route(controller_route)
        project = self._project(project_id)
        # A seeded Quick Build answers every controller step locally. Read its
        # owner-locked seed before deciding whether an AI route identity exists.
        autogen_seed = seeded_picker.valid_seed(next(
            (row.get("value") for row in (project.get("user_locks") or []) if isinstance(row, dict) and row.get("field") == seeded_picker.SEED_LOCK_FIELD),
            None,
        ))
        route_binding = (
            build_active_controller_route_binding(provider=getattr(self, "provider", None), seeded=bool(autogen_seed))
            if controller_route == DETERMINISTIC_CREATIVE_CONTROLLER
            else build_controller_route_binding(
                controller_route,
                provider=getattr(self, "provider", None),
            )
        )
        project_revision = self._revision(project_id)
        content_lock_hash = self._content_lock_hash(project_id)
        # New creation requests receive a server-owned Manual collection roll
        # before any provider/DCC response exists. Seeded requests use a
        # versioned deterministic nonce; persisted nonces remain unchanged.
        # Caller-controlled idempotency keys never supply randomness. The request hash
        # never enters its own pre-hash authority and the provider never has
        # to calculate dice or printed-content commitments.
        from character_creation.constructed_arts.manual import (
            MANUAL_COLLECTION_POLICY_ID,
            MANUAL_COLLECTION_SCHEMA,
            roll_manual_collection_count,
        )
        if manual_collection_nonce is None:
            # Select fresh nonce authority separately: recipe reconstruction
            # may only opt in after this version has been persisted.
            autogen_seed = self._autogeneration_seed(project)
            seed = f"{autogen_seed}::manual_authority:0" if autogen_seed else ""
            manual_collection_nonce = (
                "cg1.autogen.v1." + sha256_json({"seed": seed})
                if seed else secrets.token_urlsafe(32)
            )
        if (
            not isinstance(manual_collection_nonce, str)
            or len(manual_collection_nonce) < 32
            or not manual_collection_nonce.strip()
        ):
            raise FoundryError(
                "CG1_MANUAL_COLLECTION_AUTHORITY_INVALID",
                "The server-owned Manual collection nonce is malformed.",
                status_code=500,
            )
        manual_collection_seed = "cg1.manual.collection." + sha256_json({
            "policy_id": MANUAL_COLLECTION_POLICY_ID,
            "nonce": manual_collection_nonce,
        })
        manual_collection_roll = roll_manual_collection_count(
            frozen_owner_target_cl(project),
            seed=manual_collection_seed,
        )
        # Freeze the compiler-backed Method/Foundation intersection before
        # Stage 1 is generated.  The authority is built from server settings
        # and the exact project lock; no request field can select its corpus.
        compiler_authority_service = NonSphereAuthorityService(self.db)
        compiler_selection_authority = build_compiler_selection_authority(
            self.db.settings.vendor_dir,
            content_lock=project.get("content_lock") or {},
            method_records=compiler_authority_service.method_catalog(initial_creation=True)["records"],
            foundation_records=compiler_authority_service.foundation_catalog()["orthodox"],
        )
        prompt = self.stage1.generate_prompt(project_id)
        request = {
            "schema": "TianxiaFoundry.CharacterCreationPlanRequest.v3",
            "project_id": project_id,
            "project_revision": project_revision,
            "content_lock_hash": content_lock_hash,
            # This route request is frozen before the complete request hash is
            # computed.  The binding itself is self-hashed and contains no
            # request hash, avoiding a circular identity.
            "controller_route": controller_route,
            "controller_route_binding": route_binding,
            "typed_choice_snapshot": self._choice_snapshot(project_id),
            "stage1_prompt": deepcopy(prompt),
            "required_plan_schema": DELEGATED_RESPONSE_SCHEMA,
            "required_components": sorted(PREFERRED_RESPONSE_KEYS),
            "forbidden_planner_fields": sorted(FORBIDDEN_PLANNER_FIELDS),
            "server_owned_authority": {
                "initial_path_attainment_policy": deepcopy(INITIAL_PATH_ATTAINMENT_POLICY),
                "initial_method_mechanics_policy": deepcopy(INITIAL_METHOD_MECHANICS_POLICY),
                "initial_foundation_mechanics_policy": deepcopy(INITIAL_FOUNDATION_MECHANICS_POLICY),
                "target_cl": "frozen from project.user_locks[field=target_cl]",
                "stage1_response": True,
                "stage2_proposal": True,
                "event_kinds_channels_effective_cl": True,
                "automatic_components": True,
                "hashes_and_receipts": True,
                "manual_collection": {
                    "schema": MANUAL_COLLECTION_SCHEMA,
                    "policy_id": MANUAL_COLLECTION_POLICY_ID,
                    "authority_version": "server_owned_pre_provider.v2",
                    "nonce": manual_collection_nonce,
                    "seed": manual_collection_seed,
                    "roll": manual_collection_roll,
                },
                "method_foundation_choices": "Closed-world IDs are selectable only when the exact pinned compiler corpus provides tianxia_rules evidence; response prose never grants authority.",
                "output_profile_target_required": True,
                "output_profile": self._server_owned_output_profile_target(
                    project_id=project_id,
                    project_revision=project_revision,
                    content_lock_hash=content_lock_hash,
                    combat_ready=combat_ready,
                ),
            },
            "bounded_choice_contract": {
                "schema": "TianxiaFoundry.BoundedChoiceContract.v1",
                "purpose": "Only genuinely non-derivable typed choices may appear here.",
                "fields": {
                    "foundation_initial_stage": foundation_initial_stage_contract(),
                    "ability_scores": {
                        "type": "point_buy_scores",
                        "abilities": ["STR", "DEX", "CON", "INT", "WIS", "CHA"],
                        "allowed_values": [8, 9, 10, 11, 12, 13, 14, 15],
                        "budget": 27,
                    },
                    "background_ability": "only when the frozen Background authority publishes an allowed ability choice",
                    "background_ability_amount": "server-derived amount unless the frozen Background authority exposes a bounded amount",
                    "ability_score_changes_by_milestone_id": "typed ASI deltas keyed by advertised source milestone ID",
                    "path_progression_by_cl": "exact representative Path ID for shared global milestone choices; every selected Path independently attains each CL through target_cl",
                },
            },
            "policy": {
                "planner_prose_is_mechanical_authority": False,
                "priorities_are_non_acquisitive": True,
                "automatic_retries": False,
            },
        }
        delegated = build_delegated_choice_envelope(
            project,
            prompt,
            execution_mode=execution_mode,
            idempotency_key=idempotency_key,
            compiler_selection_authority=compiler_selection_authority,
        )
        if delegated is not None:
            _bind_path_feature_ability_change_rules(delegated, compiler_authority_service)
            language_source_text, language_source = _verified_starting_proficiency_language_inputs(
                compiler_authority_service
            )
            starting_contract = build_starting_proficiency_choice_contract(
                path_profiles=compiler_authority_service.path_profiles,
                backgrounds=compiler_authority_service.backgrounds,
                choices_by_slot=delegated.get("choices_by_slot") or {},
                allowed_choice_ids_by_slot=delegated.get("allowed_choice_ids_by_slot") or {},
                campaign_language_source_text=language_source_text,
                campaign_language_source=language_source,
            )
            starting_unresolved = [
                row for row in starting_contract.get("unresolved") or []
                if isinstance(row, dict)
                and row.get("field") in {
                    "path_skill_choices_by_path_id",
                    "background_language_choices_by_background_id",
                }
            ]
            if starting_unresolved:
                raise FoundryError(
                    "CG1_STARTING_PROFICIENCY_AUTHORITY_UNRESOLVED",
                    "A presented Path or Background has no complete frozen starting-proficiency authority.",
                    details={
                        "contract_schema": STARTING_PROFICIENCY_CONTRACT_SCHEMA,
                        "unresolved": deepcopy(starting_unresolved[:32]),
                    },
                    status_code=422,
                )
            bounded_contract = request["bounded_choice_contract"]
            bounded_contract["starting_proficiency_choice_contract"] = deepcopy(starting_contract)
            for field in (
                "path_skill_choices_by_path_id",
                "origin_skill_choices_by_origin_id",
                "background_language_choices_by_background_id",
            ):
                entries = (starting_contract.get("fields") or {}).get(field)
                if not isinstance(entries, dict) or not entries:
                    continue
                if field == "background_language_choices_by_background_id" and not any(
                    isinstance(entry, dict)
                    and type(entry.get("language_choice_count")) is int
                    and entry.get("language_choice_count") > 0
                    and isinstance(entry.get("allowed_values"), list)
                    and entry.get("allowed_values")
                    for entry in entries.values()
                ):
                    continue
                bounded_contract["fields"][field] = {
                    "type": "starting_proficiency_choice_map",
                    "contract_sha256": starting_contract.get("contract_sha256"),
                    "selection_map": field,
                }
            # The binding above adds server-owned typed mechanics to the
            # otherwise compact envelope.  Re-seal that envelope before it is
            # copied into the request; otherwise the persisted request would
            # fail the delegated validator's tamper check on its first use.
            delegated.pop("envelope_sha256", None)
            if required_designs:
                delegated["required_forged_design_ids"] = required_designs
            delegated["envelope_sha256"] = sha256_json(delegated)
            # Initial Methods are authenticated by the non-Sphere registry,
            # not always by the ordinary HF2 pack.  Freeze every Method that
            # this sealed envelope offers before any response can name one;
            # compilation may then use the project snapshot without consulting
            # a live catalog or asking the owner to repeat a valid AI choice.
            method_ids = [
                value
                for value in (delegated.get("allowed_choice_ids_by_slot") or {}).get("method_choice", [])
                if isinstance(value, str)
            ]
            if method_ids:
                authority = NonSphereAuthorityService(self.db)
                # Freeze missing source rows only. Revisions may select a new
                # derived version, but packed and extra snapshots are immutable.
                with self.db.connection() as conn:
                    self.projects.project_lock_proof(conn, project_id)
                    frozen_ids = {row[0] for row in conn.execute(
                        "SELECT record_id FROM project_locked_records WHERE project_id=?",
                        (project_id,),
                    )}
                    for method_id in method_ids:
                        if method_id in frozen_ids:
                            self.projects._resolve_project_locked_method_after_proof(
                                conn, project_id, method_id, authority_service=authority,
                            )
                missing_sources = [authority.project_locked_method_catalog_record(method_id)
                                   for method_id in method_ids if method_id not in frozen_ids]
                if missing_sources:
                    self.projects.add_server_locked_records(project_id, missing_sources)
            request["delegated_choice_envelope"] = delegated
            request["delegated_name_contract"] = deepcopy(
                delegated.get("delegated_name_contract") or {}
            )
            if isinstance(delegated.get("delegated_title_contract"), dict):
                request["delegated_title_contract"] = deepcopy(
                    delegated.get("delegated_title_contract") or {}
                )
            request["bounded_choice_contract"]["advertised_advancement_choice_milestones"] = deepcopy(
                delegated.get("advancement_choice_milestones") or []
            )
            fields = request["bounded_choice_contract"]["fields"]
            prompt_locks = (request.get("stage1_prompt") or {}).get("envelope", {}).get("user_locks") or []
            point_buy_lock = next(
                (
                    row.get("value")
                    for row in prompt_locks
                    if isinstance(row, dict) and row.get("field") == "character_sheet.ability_point_buy"
                ),
                {},
            )
            fixed_scores = point_buy_lock.get("fixed_scores") if isinstance(point_buy_lock, dict) else None
            if isinstance(fixed_scores, dict) and set(fixed_scores) == {"STR", "DEX", "CON", "INT", "WIS", "CHA"} and not point_buy_lock.get("auto_abilities"):
                fields.pop("ability_scores", None)
            background_contract = delegated.get("typed_choice_authority_by_slot", {}).get("background_choice", {})
            if not (background_contract.get("ability_adjustment_by_choice") or {}):
                fields.pop("background_ability", None)
                fields.pop("background_ability_amount", None)
            else:
                background_amount_choices = {
                    amount
                    for adjustment in (background_contract.get("ability_adjustment_by_choice") or {}).values()
                    if isinstance(adjustment, dict)
                    for amount in (
                        adjustment.get("allowed_amounts")
                        or adjustment.get("amount_choices")
                        or []
                    )
                    if type(amount) is int
                }
                if not background_amount_choices:
                    fields.pop("background_ability_amount", None)
            if not delegated.get("advancement_choice_milestones"):
                fields.pop("ability_score_changes_by_milestone_id", None)
            if not any(
                isinstance(row, dict) and len(row.get("path_ids") or []) > 1
                for row in delegated.get("path_progression_choices") or []
            ):
                fields.pop("path_progression_by_cl", None)
        if revision_request:
            request["revision_request"] = deepcopy(revision_request)
        if required_designs:
            if not request.get("delegated_choice_envelope"):
                raise FoundryError("CG1_REQUIRED_FORGED_DESIGNS_ROUTE_UNSUPPORTED", "Required Forge designs need a delegated Forge envelope.", status_code=422)
            request["required_forged_design_ids"] = required_designs
        # Owner-preferred weapons and armour steer the starting-kit steps.
        gear_preferences = next(
            (row.get("value") for row in (project.get("user_locks") or []) if isinstance(row, dict) and row.get("field") == "character_sheet.gear_preferences"),
            None,
        )
        from factory_authoring.starting_kits import owner_named_gear

        from character_creation.creative_controller.linear_prompt import owner_locked_descriptive_fields

        sealed_text = {"stage1_prompt": {"envelope": {"user_locks": project.get("user_locks") or []}}}
        owner_text = owner_locked_descriptive_fields(sealed_text, {})
        named_gear = owner_named_gear(
            owner_text.get("concept"), owner_text.get("owner_descriptive_fields.identity.title"),
        )
        explicit_gear_preferences = [
            item for item in gear_preferences if isinstance(item, str) and item
        ] if isinstance(gear_preferences, list) else []
        combined_gear_preferences = list(dict.fromkeys([
            *explicit_gear_preferences,
            *named_gear["item_ids"],
        ]))
        if combined_gear_preferences:
            request["owner_gear_preferences"] = combined_gear_preferences
        if named_gear["items"]:
            request["owner_gear_requirements"] = named_gear["items"]
        if named_gear["warnings"]:
            request["owner_gear_warnings"] = named_gear["warnings"]
        if named_gear.get("advisories"):
            request["owner_gear_advisories"] = named_gear["advisories"]
        # Optional advice is frozen before hashing; legal choices stay intact.
        from character_creation.concept_index import freeze_concept_guidance

        concept_advice = freeze_concept_guidance(
            request, cache_path=self.db.settings.data_dir / "cache/concept_embeddings.json",
        )
        if concept_advice:
            request["concept_guidance"] = concept_advice
            # Advice cannot create owner gear locks or automatic purchases.
            # Explicit gear authority is assembled independently of advice.
        # A seeded autogeneration project: the walk answers every step from the seed.
        if autogen_seed:
            request["autogen_seed"] = autogen_seed
        # Talents gated by a structure the walk cannot model ("Spear-Heart",
        # "Tamer Package"); the canonical grant validator enforces them.
        from canonical_catalog.service import structural_talent_gates, talent_prerequisite_gates

        request["structural_talent_gates"] = structural_talent_gates()
        # Talent prerequisites the envelope does not carry but the canonical
        # grant validator enforces (clauses of alternatives; build 38).
        request["talent_prerequisite_gates"] = talent_prerequisite_gates()
        request["request_sha256"] = self.request_payload_sha256(request)
        output_profile_target = request["server_owned_authority"]["output_profile"]
        output_profile_target["binding"]["request_sha256"] = request["request_sha256"]
        # The nested request binding is intentionally the sole excluded
        # transport identity field; assert the final value remains stable.
        if self.request_payload_sha256(request) != request["request_sha256"]:
            raise FoundryError(
                "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                "The server-owned output-profile target could not be bound to the complete request.",
                status_code=500,
            )
        return request

    @staticmethod
    def canonical_request_payload(request: dict[str, Any]) -> dict[str, Any]:
        """Return the non-circular payload covered by request_sha256.

        Transport/run commitments are deliberately external to this payload.  In
        particular, start() adds the idempotency binding only after the canonical
        request identity exists; validators must therefore exclude it too.  The
        owner output-profile target carries the resulting request hash inside
        its binding, so that one nested value is also excluded to avoid a hash
        cycle; all other target fields remain covered by this digest.
        """
        # Copy only the path that changes (the request is ~60 MB; a full
        # deepcopy cost 2.5 s per call and ran 11 times per retry).  Callers
        # serialize the result; untouched values are shared, never mutated.
        payload = dict(request)
        payload.pop("request_sha256", None)
        payload.pop("idempotency_binding_sha256", None)
        server_authority = payload.get("server_owned_authority")
        output_profile = (
            server_authority.get("output_profile")
            if isinstance(server_authority, dict)
            else None
        )
        if (
            isinstance(output_profile, dict)
            and output_profile.get("schema") == SERVER_OUTPUT_PROFILE_SCHEMA
        ):
            binding = output_profile.get("binding")
            if isinstance(binding, dict) and "request_sha256" in binding:
                binding = {key: value for key, value in binding.items() if key != "request_sha256"}
                output_profile = {**output_profile, "binding": binding}
                payload["server_owned_authority"] = {**server_authority, "output_profile": output_profile}
        return payload

    @classmethod
    def request_payload_bytes(cls, request: dict[str, Any]) -> bytes:
        return canonical_json(cls.canonical_request_payload(request)).encode("utf-8")

    @classmethod
    def request_payload_sha256(cls, request: dict[str, Any]) -> str:
        return sha256_bytes(cls.request_payload_bytes(request))

    @staticmethod
    def _deterministic_zip(entries: dict[str, bytes]) -> bytes:
        output = io.BytesIO()
        with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
            for name in sorted(entries):
                info = zipfile.ZipInfo(name, (1980, 1, 1, 0, 0, 0))
                info.compress_type = zipfile.ZIP_DEFLATED
                info.external_attr = 0o100644 << 16
                archive.writestr(info, entries[name])
        return output.getvalue()

    @staticmethod
    def _impossible_schema() -> dict[str, Any]:
        """Return a valid, non-combinator schema for an unavailable branch."""
        return {"type": "string", "enum": []}

    @staticmethod
    def _empty_schema_combinators(value: Any, path: tuple[str, ...] = ()) -> list[str]:
        """Return paths to empty JSON-Schema combinators.

        An empty ``oneOf`` is easy to emit when a source authority was only
        consulted for owner-selected records.  It is not a usable response
        contract, so request-package generation fails closed before the
        malformed schema can reach an owner or an external response model.
        """
        found: list[str] = []
        if isinstance(value, dict):
            for key in ("oneOf", "anyOf", "allOf"):
                branch = value.get(key)
                if isinstance(branch, list) and not branch:
                    found.append("/" + "/".join((*path, key)))
            if isinstance(value.get("not"), dict) and not value["not"]:
                found.append("/" + "/".join((*path, "not")))
            for key, child in value.items():
                found.extend(CharacterCreationExecutionService._empty_schema_combinators(child, (*path, str(key))))
        elif isinstance(value, list):
            for index, child in enumerate(value):
                found.extend(CharacterCreationExecutionService._empty_schema_combinators(child, (*path, str(index))))
        return found

    @staticmethod
    def _schema_representative_value(schema: Any, *, include_optional: bool = False) -> Any:
        """Build a small representative instance for a generated schema.

        This is intentionally a schema smoke value, not a mechanical plan.
        It exercises the required response envelope and each optional bounded
        field without inventing authority or persisting the value anywhere.
        """
        if not isinstance(schema, dict):
            return _SCHEMA_MISSING
        if "const" in schema:
            return deepcopy(schema["const"])
        enum = schema.get("enum")
        if isinstance(enum, list):
            return deepcopy(enum[0]) if enum else _SCHEMA_MISSING
        for combinator in ("oneOf", "anyOf", "allOf"):
            branches = schema.get(combinator)
            if isinstance(branches, list):
                for branch in branches:
                    candidate = CharacterCreationExecutionService._schema_representative_value(
                        branch,
                        include_optional=include_optional,
                    )
                    if candidate is not _SCHEMA_MISSING:
                        return candidate
                return _SCHEMA_MISSING
        if "not" in schema:
            return _SCHEMA_MISSING
        schema_type = schema.get("type")
        if schema_type == "object" or "properties" in schema:
            properties = schema.get("properties") if isinstance(schema.get("properties"), dict) else {}
            required = set(schema.get("required") or [])
            keys = list(properties) if include_optional else list(required)
            result: dict[str, Any] = {}
            for key in keys:
                candidate = CharacterCreationExecutionService._schema_representative_value(
                    properties.get(key),
                    include_optional=include_optional,
                )
                if candidate is _SCHEMA_MISSING:
                    if key in required:
                        return _SCHEMA_MISSING
                    continue
                result[str(key)] = candidate
            return result
        if schema_type == "array":
            item_schema = schema.get("items")
            count = schema.get("minItems") if type(schema.get("minItems")) is int else 0
            result: list[Any] = []
            for index in range(max(0, count)):
                candidate = CharacterCreationExecutionService._schema_representative_value(
                    item_schema,
                    include_optional=include_optional,
                )
                if candidate is _SCHEMA_MISSING:
                    return _SCHEMA_MISSING
                if schema.get("uniqueItems") and candidate in result:
                    # A bounded enum-backed array (ordinary Talents and
                    # required multi-Path selections are the common cases)
                    # needs distinct representative values.  Reusing the
                    # first enum member would make the generated smoke value
                    # fail its own uniqueItems contract.
                    enum = item_schema.get("enum") if isinstance(item_schema, dict) else None
                    if isinstance(enum, list):
                        candidate = next((value for value in enum if value not in result), _SCHEMA_MISSING)
                    else:
                        branches = item_schema.get("oneOf") if isinstance(item_schema, dict) else None
                        if isinstance(branches, list):
                            candidate = _SCHEMA_MISSING
                            for branch in branches[index % max(1, len(branches)):] + branches[:index % max(1, len(branches))]:
                                trial = CharacterCreationExecutionService._schema_representative_value(
                                    branch,
                                    include_optional=include_optional,
                                )
                                if trial is not _SCHEMA_MISSING and trial not in result:
                                    candidate = trial
                                    break
                if candidate is _SCHEMA_MISSING:
                    return _SCHEMA_MISSING
                result.append(candidate)
            return result
        if schema_type == "string":
            return "Representative response"
        if schema_type == "integer":
            return schema.get("minimum", 0)
        if schema_type == "number":
            return schema.get("minimum", 0)
        if schema_type == "boolean":
            return True
        return _SCHEMA_MISSING

    @classmethod
    def _validate_generated_response_schema(cls, schema: dict[str, Any]) -> None:
        empty = cls._empty_schema_combinators(schema)
        if empty:
            raise FoundryError(
                "CG1_RESPONSE_SCHEMA_EMPTY_COMBINATOR",
                "The generated response schema contains an empty JSON-Schema combinator.",
                details={"paths": empty},
                status_code=500,
            )
        try:
            Draft202012Validator.check_schema(schema)
        except Exception as exc:
            raise FoundryError(
                "CG1_RESPONSE_SCHEMA_INVALID",
                "The generated response schema failed Draft 2020-12 metaschema validation.",
                details={"error": str(exc)},
                status_code=500,
            ) from exc
        representative = cls._schema_representative_value(schema)
        if not isinstance(representative, dict):
            raise FoundryError(
                "CG1_RESPONSE_SCHEMA_REPRESENTATIVE_INVALID",
                "The generated response schema could not produce a representative response object.",
                status_code=500,
            )
        # Exercise optional bounded contracts too.  The response envelope
        # keeps them optional because some routes do not expose a bounded
        # choice, but every generated property still needs a valid instance.
        bounded = (schema.get("properties") or {}).get("bounded_choices") or {}
        bounded_properties = bounded.get("properties") if isinstance(bounded, dict) else {}
        if isinstance(bounded_properties, dict):
            bounded_value: dict[str, Any] = {}
            for key, child in bounded_properties.items():
                candidate = cls._schema_representative_value(child, include_optional=True)
                if candidate is not _SCHEMA_MISSING:
                    bounded_value[key] = candidate
            representative.setdefault("bounded_choices", {}).update(bounded_value)
        errors = list(Draft202012Validator(schema).iter_errors(representative))
        if errors:
            raise FoundryError(
                "CG1_RESPONSE_SCHEMA_REPRESENTATIVE_INVALID",
                "The generated response schema rejected its representative response.",
                details={"errors": [error.message for error in errors[:10]]},
                status_code=500,
            )

    @staticmethod
    def _manual_ai_instructions(request: dict[str, Any], model: dict[str, Any]) -> bytes:
        target_cl = model.get("target_cl")
        return (
            "# Manual Chat AI Instructions\n\n"
            "This is the compact choice context for one Factory MANUAL_CHAT request. "
            "The local Factory remains the mechanical authority and accepts only the "
            "response schema in RESPONSE_SCHEMA.json.\n\n"
            f"Request SHA-256: {request.get('request_sha256')}\n"
            f"Target CL: {target_cl if target_cl is not None else 'Factory-bound'}\n\n"
            "Use stable IDs from AI_CHOICE_MODEL.json only. Do not invent mechanics, "
            "copy source payloads, or return Factory-owned target CL, event rows, "
            "channels, grants, hashes, receipts, or readiness claims.\n\n"
            "Method and Foundation selections are closed-world compiler-backed legal "
            "choices from the exact pinned compiler corpus; use only presented allowed "
            "IDs. Nonselectable IDs and response prose never grant mechanics or authority.\n\n"
            "## Ordinary Talent positions\n\n"
            "The response fields acquisition_intent.ordinary_talent_ids and, where present, "
            "selection_intent.by_slot.advancement_skeleton use the same zero-based "
            "array: array index 0 is the ordinary Talent acquired at CL1, and the "
            "final active position is determined by the frozen request target CL. "
            "Supply exactly one distinct stable Talent ID for every active CL slot and "
            "choose only an ID listed as eligible for that CL. Sphere ownership and hard "
            "prerequisites still apply. If a compact shortlist repeats legal same-sphere "
            "anchors, the Factory may expand them deterministically only through its "
            "frozen server-owned legal plan authority; do not invent IDs or rely on an "
            "unlisted expansion.\n\n"
            "If a correction packet is provided, fix every listed array index using its "
            "legal candidate IDs. Return the complete corrected response to this same "
            "chat, preserving the exact request_sha256; the owner will then use Replace "
            "Response in the Factory. Do not ask the owner to choose an illegal "
            "progression replacement.\n\n"
            "## Bounded mechanical corrections\n\n"
            "For each bounded error, use the exact response field and slot named in "
            "AI_CORRECTION_REQUEST.json. A null proposal means that the response omitted "
            "the required value. Use only the listed legal candidate IDs, labels, semantic "
            "cues, and parameters when reconstructing the complete response value; the "
            "candidate list is compact context, not permission to invent another value. "
            "These response-authored mechanical corrections belong to the same AI. Do not "
            "ask the owner to select one, and do not return an owner-decision placeholder.\n"
        ).encode("utf-8")

    @staticmethod
    def _manual_ai_correction_from_run(run: dict[str, Any]) -> dict[str, Any] | None:
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        last_error = validation.get("last_submission_error") if isinstance(validation, dict) else {}
        last_error = last_error if isinstance(last_error, dict) else {}
        details = last_error.get("details") if isinstance(last_error.get("details"), dict) else {}
        correction = details.get("ai_correction_required")
        if isinstance(correction, dict) and correction.get("classification") == "AI_CORRECTION_REQUIRED":
            return correction
        for blocker in run.get("blockers") or []:
            if not isinstance(blocker, dict):
                continue
            blocker_details = blocker.get("details") if isinstance(blocker.get("details"), dict) else {}
            correction = blocker_details.get("ai_correction_required")
            if isinstance(correction, dict) and correction.get("classification") == "AI_CORRECTION_REQUIRED":
                return correction
        return None

    def _manual_ai_correction_summary(self, run: dict[str, Any]) -> dict[str, Any]:
        if run.get("execution_mode") != "MANUAL_CHAT" or self._manual_ai_correction_from_run(run) is None:
            return self._manual_ai_correction_summary_uncached(run)
        # These are the complete inputs to the pure summary/model validation;
        # use actual content, not the request's claimed self-hash or updated_at.
        key = sha256_json({name: run.get(name) for name in (
            "execution_mode", "request", "response", "validation", "blockers",
        )})
        return self._manual_correction_summaries.get_or_compute(
            key, lambda: self._manual_ai_correction_summary_uncached(run),
        )

    def _manual_ai_correction_summary_uncached(self, run: dict[str, Any]) -> dict[str, Any]:
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        response = run.get("response") if isinstance(run.get("response"), dict) else {}
        correction = self._manual_ai_correction_from_run(run) if run.get("execution_mode") == "MANUAL_CHAT" else None
        if correction is None:
            return {
                "schema": MANUAL_AI_CORRECTION_SCHEMA,
                "required": False,
                "download_available": False,
            }
        model = build_compact_choice_model(request)
        return {
            "schema": MANUAL_AI_CORRECTION_SCHEMA,
            "required": True,
            "download_available": True,
            "request_sha256": request.get("request_sha256"),
            "response_sha256": response.get("response_sha256"),
            "model_sha256": sha256_json(model),
            "error_count": len(correction.get("errors") or []),
            "errors": deepcopy(correction.get("errors") or []),
            "prior_response_retained": bool(response.get("response_sha256")),
            "return_instruction": "Return the corrected complete response to the same chat, then use Replace Response.",
        }

    def _manual_ai_correction_for_response(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        project: dict[str, Any],
    ) -> dict[str, Any] | None:
        if run.get("execution_mode") != "MANUAL_CHAT" or not self._has_delegated_envelope(run):
            return None
        return classify_ordinary_talent_corrections(
            run.get("request") or {},
            plan,
            project,
            self._resolve_event_authority,
        )

    @staticmethod
    def _manual_bounded_response_value(plan: dict[str, Any], field: str | None) -> Any:
        """Read one response proposal without interpreting its mechanics."""

        if not isinstance(field, str) or not field:
            return None
        path = field
        for prefix in ("bounded_choices.", "acquisition_intent.", "selection_intent."):
            if path.startswith(prefix):
                path = path[len(prefix):]
                break
        else:
            return None
        current: Any = plan
        root = field.split(".", 1)[0]
        current = plan.get(root) if isinstance(plan, dict) else None
        for part in path.split("."):
            if not isinstance(current, dict) or part not in current:
                return None
            current = current[part]
        return deepcopy(current)

    @staticmethod
    def _manual_bounded_field(details: dict[str, Any]) -> str | None:
        field = details.get("field")
        if isinstance(field, str) and field.strip():
            return field.strip()
        milestone_id = details.get("milestone_id")
        if isinstance(milestone_id, str) and milestone_id:
            return f"bounded_choices.ability_score_changes_by_milestone_id.{milestone_id}"
        return None

    @staticmethod
    def _manual_bounded_response_authored(
        run: dict[str, Any],
        plan: dict[str, Any],
        details: dict[str, Any],
    ) -> bool:
        """Keep genuine owner locks/descriptive authority out of AI recovery."""

        field = CharacterCreationExecutionService._manual_bounded_field(details)
        if not field or field in {"identity.name", "concept"} or field.startswith("owner_descriptive_fields."):
            return False
        if field.startswith(("bounded_choices.", "acquisition_intent.")):
            return True
        if details.get("milestone_id") is not None or details.get("ordinary_talent_index") is not None:
            return True

        mechanical_slots = {
            "path_choice", "subpath_choice", "method_choice", "foundation_choice",
            "background_choice", "background_sphere_choice", "background_talent_choice",
            "stage2_record", "stage2_record_id", "acquisition_intent",
        }
        slot_id = details.get("slot_id") if isinstance(details.get("slot_id"), str) else field
        if slot_id not in mechanical_slots:
            return False
        envelope = ((run.get("request") or {}).get("delegated_choice_envelope") or {})
        owner_by_slot = ((envelope.get("owner_locks") or {}).get("by_slot") or {})
        # The materializer falls back to these locks when the response omits a
        # slot.  If one exists, a remaining failure belongs to the owner/project
        # authority boundary rather than to an AI-authored proposal.
        return not bool(owner_by_slot.get(slot_id))

    @staticmethod
    def _manual_bounded_candidate(
        candidate: Any,
        *,
        field: str,
        milestone_id: str | None = None,
    ) -> dict[str, Any]:
        """Project one legal bounded alternative into a compact AI context."""

        raw = candidate if isinstance(candidate, dict) else {"value": candidate}
        value = deepcopy(raw.get("value")) if "value" in raw else None
        if value is None and isinstance(raw.get("kind"), str):
            value = {
                key: deepcopy(raw[key])
                for key in ("kind", "milestone_id", "insight_id", "deltas", "parameters")
                if key in raw
            }
        candidate_id = next(
            (
                raw.get(key)
                for key in ("choice_id", "candidate_id", "stable_id", "id")
                if isinstance(raw.get(key), str) and raw.get(key)
            ),
            None,
        )
        if not isinstance(candidate_id, str):
            candidate_identity = {"field": field, "value": value}
            candidate_id = f"bounded.{sha256_json(candidate_identity)[:24]}"
        kind = raw.get("kind")
        if not isinstance(kind, str) and isinstance(value, dict):
            kind = value.get("kind")
        kind = kind if isinstance(kind, str) else None
        candidate_milestone_id = raw.get("milestone_id")
        if not isinstance(candidate_milestone_id, str) and isinstance(value, dict):
            candidate_milestone_id = value.get("milestone_id")
        if not isinstance(candidate_milestone_id, str):
            candidate_milestone_id = milestone_id

        parameters = deepcopy(raw.get("parameters")) if isinstance(raw.get("parameters"), dict) else {}
        if isinstance(value, dict):
            if kind == "ability_score_change" and isinstance(value.get("deltas"), dict):
                parameters.setdefault("deltas", deepcopy(value["deltas"]))
            if kind == "cultivation_insight_acquisition":
                if isinstance(value.get("insight_id"), str):
                    parameters.setdefault("insight_id", value["insight_id"])
                if isinstance(value.get("parameters"), dict):
                    parameters.setdefault("choice_parameters", deepcopy(value["parameters"]))
        label = next(
            (
                raw.get(key)
                for key in ("display_name", "name", "label", "title")
                if isinstance(raw.get(key), str) and raw.get(key).strip()
            ),
            None,
        )
        if not label and kind == "ability_score_change" and isinstance(parameters.get("deltas"), dict):
            label = "Ability-score improvement: " + ", ".join(
                f"{ability} {delta:+d}"
                for ability, delta in sorted(parameters["deltas"].items())
                if type(delta) is int
            )
        if not label and kind == "cultivation_insight_acquisition":
            label = f"Cultivation Insight: {parameters.get('insight_id') or 'source-backed insight'}"
        if not label:
            label = candidate_id
        cue = next(
            (
                raw.get(key)
                for key in ("semantic_cue", "short_description", "summary", "description")
                if isinstance(raw.get(key), str) and raw.get(key).strip()
            ),
            None,
        )
        if not cue:
            cue = (
                f"Legal {kind.replace('_', ' ') if kind else 'bounded'} candidate for "
                f"{candidate_milestone_id or field}; use the listed parameters."
            )
        return {
            "id": candidate_id,
            "display_name": " ".join(str(label).split())[:240],
            "semantic_cue": " ".join(str(cue).split())[:240],
            "kind": kind,
            "milestone_id": candidate_milestone_id,
            "parameters": parameters,
        }

    def _manual_bounded_legal_candidates(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        details: dict[str, Any],
        field: str,
    ) -> list[dict[str, Any]]:
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        envelope = request.get("delegated_choice_envelope") if isinstance(request, dict) else {}
        envelope = envelope if isinstance(envelope, dict) else {}
        bounded = plan.get("bounded_choices") if isinstance(plan.get("bounded_choices"), dict) else {}
        acquisition = plan.get("acquisition_intent") if isinstance(plan.get("acquisition_intent"), dict) else {}
        selection = plan.get("selection_intent") if isinstance(plan.get("selection_intent"), dict) else {}
        selected_by_slot = selection.get("by_slot") if isinstance(selection.get("by_slot"), dict) else {}
        milestone_id = details.get("milestone_id") if isinstance(details.get("milestone_id"), str) else None
        raw_candidates: list[Any] = []

        if milestone_id:
            authority_by_milestone = run.get("owner_decision_authority")
            if not isinstance(authority_by_milestone, dict):
                authority_run = dict(run)
                authority_run["blockers"] = [{"details": deepcopy(details)}]
                try:
                    authority_by_milestone = self._owner_decision_authority(authority_run)
                except (FoundryError, KeyError, TypeError, AttributeError):
                    authority_by_milestone = {}
            try:
                enriched = enrich_milestone_details(
                    details,
                    envelope=envelope,
                    proposal_bounded=bounded,
                    proposal_acquisition=acquisition,
                    proposal_selected_by_slot=selected_by_slot,
                    authority_by_milestone=authority_by_milestone,
                )
            except (KeyError, TypeError, ValueError):
                enriched = {}
            raw_candidates = list(enriched.get("legal_choices") or []) if isinstance(enriched, dict) else []

        if not raw_candidates:
            for key in (
                "legal_candidates", "allowed_candidates", "allowed_milestone_choices",
                "allowed_choice_ids", "available_choice_ids", "available_path_ids",
                "allowed_resolutions",
            ):
                values = details.get(key)
                if isinstance(values, list):
                    raw_candidates = values
                    if raw_candidates:
                        break

        if not raw_candidates:
            slot_id = details.get("slot_id") if isinstance(details.get("slot_id"), str) else None
            if slot_id is None and field == "path_progression_by_cl":
                slot_id = "path_choice"
            choices = (envelope.get("choices_by_slot") or {}).get(slot_id) if slot_id else {}
            candidate_ids = details.get("allowed_choice_ids") or details.get("available_choice_ids") or []
            if isinstance(choices, dict):
                raw_candidates = [
                    {**deepcopy(choices.get(choice_id) or {}), "choice_id": choice_id}
                    for choice_id in candidate_ids
                    if isinstance(choice_id, str) and isinstance(choices.get(choice_id), dict)
                ]

        candidates = [
            self._manual_bounded_candidate(value, field=field, milestone_id=milestone_id)
            for value in raw_candidates
        ]
        unique = {row["id"]: row for row in candidates if isinstance(row.get("id"), str)}
        return [unique[key] for key in sorted(unique)]

    def _manual_ai_correction_for_bounded_failure(
        self,
        run: dict[str, Any],
        response_text: str,
        error: FoundryError,
    ) -> dict[str, Any] | None:
        if (
            run.get("execution_mode") != "MANUAL_CHAT"
            or not self._has_delegated_envelope(run)
            or error.code not in {"CG1_BOUNDED_DECISION_REQUIRED", "CG1_PLAN_BLOCKED"}
        ):
            return None
        sources: list[FoundryError] = []
        if error.code == "CG1_BOUNDED_DECISION_REQUIRED":
            sources = [error]
        else:
            nested = error.details.get("blockers") if isinstance(error.details, dict) else None
            sources = [
                FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    str(row.get("message") or "A bounded mechanical decision is required."),
                    details=deepcopy(row.get("details") or {}),
                    status_code=409,
                )
                for row in nested or []
                if isinstance(row, dict)
                and row.get("code") == "CG1_BOUNDED_DECISION_REQUIRED"
                and isinstance(row.get("details"), dict)
            ]
        if not any(
            self._manual_bounded_response_authored(
                run,
                {},
                source.details if isinstance(source.details, dict) else {},
            )
            for source in sources
        ):
            return None
        try:
            plan, _raw = self._parse_plan(
                response_text,
                expected_request_sha256=(run.get("request") or {}).get("request_sha256"),
                creation_training_active=self._creation_training_contract_active(run),
                explicit_forging_active=self._explicit_forging_contract_active(run),
            )
        except (FoundryError, KeyError, TypeError, ValueError):
            return None
        error_rows: list[dict[str, Any]] = []
        for source in sources:
            details = source.details if isinstance(source.details, dict) else {}
            if not self._manual_bounded_response_authored(run, plan, details):
                continue
            field = self._manual_bounded_field(details)
            if not field:
                continue
            proposal = self._manual_bounded_response_value(plan, field)
            milestone_id = details.get("milestone_id") if isinstance(details.get("milestone_id"), str) else None
            candidates = self._manual_bounded_legal_candidates(run, plan, details, field)
            candidate_ids = [row["id"] for row in candidates]
            error_rows.append({
                "slot": details.get("slot") if isinstance(details.get("slot"), str) else field,
                "field": field,
                "slot_id": details.get("slot_id") if isinstance(details.get("slot_id"), str) else field,
                "milestone_id": milestone_id,
                "effective_cl": details.get("effective_cl"),
                "proposal": deepcopy(proposal),
                "current_proposal": deepcopy(proposal),
                "proposal_state": "missing" if proposal is None else "present",
                "proposed": deepcopy(proposal),
                "reason_code": source.code,
                "reason_codes": [source.code],
                "reason_message": source.message,
                "reasons": [source.message],
                "reason": source.message,
                "legal_candidate_ids": candidate_ids,
                "legal_choice_ids": candidate_ids,
                "legal_candidates": candidates,
            })
        if not error_rows:
            return None
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        envelope = request.get("delegated_choice_envelope") if isinstance(request, dict) else {}
        frozen_target = envelope.get("frozen_owner_target_cl") if isinstance(envelope, dict) else {}
        target_cl = next(
            (row.get("effective_cl") for row in error_rows if type(row.get("effective_cl")) is int),
            None,
        )
        if type(target_cl) is not int:
            target_cl = plan.get("target_cl") if type(plan.get("target_cl")) is int else None
        if type(target_cl) is not int and isinstance(frozen_target, dict) and type(frozen_target.get("value")) is int:
            target_cl = frozen_target["value"]
        return {
            "schema": MANUAL_AI_CORRECTION_SCHEMA,
            "classification": "AI_CORRECTION_REQUIRED",
            "request_sha256": request.get("request_sha256"),
            "response_sha256": sha256_bytes(response_text.encode("utf-8")),
            "response_field": error_rows[0]["field"] if len(error_rows) == 1 else "bounded_choices",
            "slot_id": error_rows[0]["slot_id"] if len(error_rows) == 1 else None,
            "target_cl": target_cl,
            "expected_count": None,
            "actual_count": None,
            "error_count": len(error_rows),
            "source_error": {
                "code": error.code,
                "message": error.message,
                "details": deepcopy(error.details),
                "nested_errors": [
                    {
                        "code": source.code,
                        "message": source.message,
                        "details": deepcopy(source.details),
                    }
                    for source in sources
                    if source is not error
                ],
            },
            "errors": error_rows,
        }

    def _manual_ai_correction_package(self, run: dict[str, Any]) -> dict[str, Any]:
        if run.get("execution_mode") != "MANUAL_CHAT":
            raise FoundryError(
                "CG1_MANUAL_CORRECTION_MODE_MISMATCH",
                "Manual AI correction packets are available only for MANUAL_CHAT runs.",
                status_code=409,
            )
        correction = self._manual_ai_correction_from_run(run)
        if correction is None:
            raise FoundryError(
                "CG1_MANUAL_CORRECTION_NOT_REQUIRED",
                "This Manual Chat run has no persisted AI correction requirement.",
                status_code=409,
            )
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        response = run.get("response") if isinstance(run.get("response"), dict) else {}
        exact_response = response.get("exact_response_text")
        if not isinstance(exact_response, str):
            raise FoundryError(
                "CG1_MANUAL_CORRECTION_RESPONSE_MISSING",
                "The AI correction packet cannot preserve a missing prior response.",
                status_code=409,
            )
        model = build_compact_choice_model(request)
        model_choices = {
            row.get("id"): row
            for row in (model.get("choices_by_slot") or {}).get("advancement_skeleton", [])
            if isinstance(row, dict) and isinstance(row.get("id"), str)
        }
        errors: list[dict[str, Any]] = []
        for row in correction.get("errors") or []:
            if not isinstance(row, dict):
                continue
            item = deepcopy(row)
            if not isinstance(item.get("legal_candidates"), list):
                item["legal_candidates"] = [
                    deepcopy(model_choices[choice_id])
                    for choice_id in row.get("legal_choice_ids") or []
                    if choice_id in model_choices
                ]
            errors.append(item)
        response_sha256 = response.get("response_sha256") or sha256_bytes(exact_response.encode("utf-8"))
        correction_request = {
            "schema": MANUAL_AI_CORRECTION_SCHEMA,
            "classification": "AI_CORRECTION_REQUIRED",
            "request_binding": {
                "run_id": run.get("run_id"),
                "project_id": run.get("project_id"),
                "project_revision": run.get("starting_revision"),
                "request_sha256": request.get("request_sha256"),
                "content_lock_hash": request.get("content_lock_hash"),
                "typed_choice_snapshot_sha256": (request.get("typed_choice_snapshot") or {}).get("snapshot_sha256"),
                "prior_response_sha256": response_sha256,
            },
            "response_field": correction.get("response_field"),
            "slot_id": correction.get("slot_id"),
            "target_cl": correction.get("target_cl"),
            "expected_count": correction.get("expected_count"),
            "actual_count": correction.get("actual_count"),
            "error_count": len(errors),
            "errors": errors,
            "return_contract": {
                "same_chat": True,
                "preserve_request_sha256": request.get("request_sha256"),
                "next_factory_action": "Replace Response",
            },
        }
        if isinstance(correction.get("source_error"), dict):
            correction_request["source_error"] = deepcopy(correction["source_error"])
        binding = {
            "schema": "TianxiaFoundry.ManualAICorrectionBinding.v1",
            "run_id": run.get("run_id"),
            "project_id": run.get("project_id"),
            "project_revision": run.get("starting_revision"),
            "request_sha256": request.get("request_sha256"),
            "content_lock_hash": request.get("content_lock_hash"),
            "prior_response_sha256": response_sha256,
            "correction_request_sha256": sha256_json(correction_request),
        }
        attempts = [row for row in run.get("attempt_history") or [] if isinstance(row, dict)]
        latest_attempt = attempts[-1] if attempts else {}
        prior_evidence = {
            "schema": "TianxiaFoundry.ManualAICorrectionPriorEvidence.v1",
            "run_id": run.get("run_id"),
            "request_sha256": request.get("request_sha256"),
            "response_sha256": response_sha256,
            "attempt_id": latest_attempt.get("attempt_id"),
            "attempt_ordinal": latest_attempt.get("ordinal"),
            "attempt_status": latest_attempt.get("status"),
            "blocker_sha256": sha256_json(run.get("blockers") or []),
        }
        entries = {
            "AI_CHOICE_MODEL.json": canonical_json(model).encode("utf-8") + b"\n",
            "AI_CORRECTION_INSTRUCTIONS.md": self._manual_ai_instructions(request, model),
            "AI_CORRECTION_REQUEST.json": canonical_json(correction_request).encode("utf-8") + b"\n",
            "BINDING.json": canonical_json(binding).encode("utf-8") + b"\n",
            "PRIOR_RESPONSE.json": exact_response.encode("utf-8"),
            "PRIOR_RESPONSE_EVIDENCE.json": canonical_json(prior_evidence).encode("utf-8") + b"\n",
        }
        entries["SHA256SUMS.txt"] = "".join(
            f"{sha256_bytes(entries[name])}  {name}\n" for name in sorted(entries)
        ).encode("ascii")
        filename = (
            f"CG1_MANUAL_AI_CORRECTION_{run.get('project_id')}_"
            f"{request.get('request_sha256', '')[:12]}_{response_sha256[:12]}.zip"
        )
        member_inventory = [
            {"name": name, "bytes": len(entries[name]), "sha256": sha256_bytes(entries[name])}
            for name in sorted(entries)
        ]
        payload = self._deterministic_zip(entries)
        return {
            "filename": filename,
            "payload": payload,
            "member_inventory": member_inventory,
            "content_set_sha256": sha256_json(member_inventory),
            "final_zip_sha256": sha256_bytes(payload),
            "request_sha256": request.get("request_sha256"),
            "response_sha256": response_sha256,
        }

    def manual_ai_correction_zip(self, run_id: str) -> tuple[str, bytes]:
        package = self._manual_ai_correction_package(self.get(run_id))
        return package["filename"], package["payload"]

    def _complete_request_package(self, run_id: str) -> dict[str, Any]:
        run = self.get(run_id)
        request = deepcopy(run["request"])
        envelope = request.get("delegated_choice_envelope") or {}
        allowed_by_slot = envelope.get("allowed_choice_ids_by_slot") or {}
        choices_by_slot = envelope.get("choices_by_slot") or {}
        typed_choice_authority = envelope.get("typed_choice_authority_by_slot") or {}
        selection_properties: dict[str, Any] = {}
        for slot_id in sorted(allowed_by_slot):
            limits = (envelope.get("selection_limits_by_slot") or {}).get(slot_id) or {}
            slot_schema: dict[str, Any] = {
                "type": "array",
                "items": {
                    "type": "string",
                    "enum": list(allowed_by_slot.get(slot_id) or []),
                },
                "uniqueItems": True,
            }
            if isinstance(limits.get("final_min"), int):
                slot_schema["minItems"] = limits["final_min"]
            if isinstance(limits.get("final_max"), int):
                slot_schema["maxItems"] = limits["final_max"]
            selection_properties[slot_id] = slot_schema

        target_cl = (envelope.get("frozen_owner_target_cl") or {}).get("value")
        target_cl = target_cl if type(target_cl) is int else None
        subpath_required = _provider_subpath_required(request, envelope, target_cl)
        if "subpath_choice" in selection_properties:
            selection_properties["subpath_choice"]["minItems"] = 1 if subpath_required else 0
        for slot_id in ("sphere_priorities", "insight_priorities", "item_priorities"):
            if allowed_by_slot.get(slot_id) and slot_id in selection_properties:
                # The mechanical slot may permit none, but a delegated provider
                # must make one planning-only recommendation so finalization
                # does not silently transfer the choice back to the owner.
                selection_properties[slot_id]["minItems"] = max(
                    1, selection_properties[slot_id].get("minItems") or 0
                )
        required_candidates = [
            "path_choice",
            *(["subpath_choice"] if subpath_required else []),
            "method_choice",
            "foundation_choice",
            "background_choice",
            "background_sphere_choice",
            "background_talent_choice",
            "origin_insight_choice",
            "sphere_priorities",
            "insight_priorities",
            "item_priorities",
            "advancement_skeleton",
        ]
        required_selection_slots = sorted({
            slot_id for slot_id in required_candidates
            if allowed_by_slot.get(slot_id) and slot_id in selection_properties
        })

        sphere_ids = [value for value in allowed_by_slot.get("sphere_priorities") or [] if isinstance(value, str)]
        talent_ids = [value for value in allowed_by_slot.get("advancement_skeleton") or [] if isinstance(value, str)]
        insight_ids = [value for value in allowed_by_slot.get("insight_priorities") or [] if isinstance(value, str)]
        milestone_rows = [
            row for row in envelope.get("advancement_choice_milestones") or []
            if isinstance(row, dict) and isinstance(row.get("milestone_id"), str)
        ]
        milestone_feature_ids = {
            row["feature_record_id"]
            for row in milestone_rows
            if isinstance(row.get("feature_record_id"), str)
        }
        # RESPONSE_SCHEMA only consults locked records for advertised Path
        # milestone features. Reconstructing every locked catalog row here
        # repeated schema validation and audit writes for records that never
        # enter the package, making one browser download take minutes. Keep the
        # complete project-lock proof, then resolve only the consumed features.
        locked_records = self._locked_records_for_project_ids(
            run["project_id"],
            milestone_feature_ids,
        )
        milestone_ids = [row["milestone_id"] for row in milestone_rows]
        omitted_milestones: list[dict[str, Any]] = []

        def authority_for_choice(slot_id: str, choice_id: str) -> dict[str, Any]:
            choice = (choices_by_slot.get(slot_id) or {}).get(choice_id) or {}
            authority = (typed_choice_authority.get(slot_id) or {}).get("stage2_authority_by_choice", {}).get(choice_id)
            if not isinstance(authority, dict):
                authority = choice.get("stage2_authority")
            if not isinstance(authority, dict):
                authority = (choice.get("compatibility") or {}).get("factory", {}).get("stage2_authority") or {}
            return authority if isinstance(authority, dict) else {}

        generation_route = next(
            (
                row.get("value")
                for row in (request.get("stage1_prompt") or {}).get("envelope", {}).get("user_locks") or []
                if isinstance(row, dict) and row.get("field") == "character_sheet.generation_route"
            ),
            "player",
        )
        free_talent_kind = (
            "ai_bootstrap_talent_acquisition"
            if generation_route == "ai_bootstrap"
            else "sect_trial_talent_acquisition"
        )

        def insight_parameter_schema(authority: dict[str, Any]) -> tuple[dict[str, Any], bool]:
            ability_change = authority.get("ability_change") or authority.get("insight_ability_change") or {}
            properties: dict[str, Any] = {}
            required = False
            if isinstance(ability_change, dict) and ability_change.get("allowed_abilities"):
                properties["ability"] = {
                    "type": "string",
                    "enum": sorted({value for value in ability_change["allowed_abilities"] if isinstance(value, str)}),
                }
                required = True
            return {
                "type": "object",
                "additionalProperties": False,
                "properties": properties,
                **({"required": ["ability"]} if required else {}),
            }, required

        insight_occurrence_alternatives: list[dict[str, Any]] = []
        for insight_id in insight_ids:
            authority = authority_for_choice("insight_priorities", insight_id)
            allowed_cls = authority.get("allowed_cls") or authority.get("allowed_effective_cls") or []
            parameter_schema, parameters_required = insight_parameter_schema(authority)
            for milestone in milestone_rows:
                milestone_cl = milestone.get("cl", milestone.get("effective_cl"))
                if isinstance(allowed_cls, list) and milestone_cl not in allowed_cls:
                    continue
                insight_occurrence_alternatives.append({
                    "type": "object",
                    "additionalProperties": False,
                    "required": [
                        "insight_id",
                        "milestone_id",
                        *(["parameters"] if parameters_required else []),
                    ],
                    "properties": {
                        "insight_id": {"const": insight_id},
                        "milestone_id": {"const": milestone["milestone_id"]},
                        "parameters": parameter_schema,
                    },
                })

        pair_alternatives: list[dict[str, Any]] = []
        free_talents_by_sphere: dict[str, list[str]] = {}
        for talent_id in talent_ids:
            authority = authority_for_choice("advancement_skeleton", talent_id)
            sphere_id = (
                authority.get("owning_canonical_sphere_id")
                or authority.get("owning_sphere_id")
                or authority.get("sphere_id")
            )
            minimum_cl = authority.get("minimum_cl") or 1
            if (
                isinstance(sphere_id, str)
                and sphere_id in sphere_ids
                and free_talent_kind in (authority.get("allowed_kinds") or [])
                and type(minimum_cl) is int
                and minimum_cl <= 1
                and authority.get("free_sphere_talent_eligible") is not False
            ):
                free_talents_by_sphere.setdefault(sphere_id, []).append(talent_id)
        for sphere_id in sorted(free_talents_by_sphere):
            pair_alternatives.append({
                "type": "object",
                "additionalProperties": False,
                "required": ["sphere_id", "talent_id"],
                "properties": {
                    "sphere_id": {"const": sphere_id},
                    "talent_id": {"type": "string", "enum": sorted(set(free_talents_by_sphere[sphere_id]))},
                },
            })
        pair_schema: dict[str, Any] = (
            {"oneOf": pair_alternatives}
            if pair_alternatives
            else self._impossible_schema()
        )
        ordinary_schema: dict[str, Any] = {
            "type": "array",
            "items": {"type": "string", "enum": talent_ids},
            "uniqueItems": True,
        }
        target_cl = (envelope.get("frozen_owner_target_cl") or {}).get("value")
        expected_ordinary_count = envelope.get("ordinary_talent_count")
        if isinstance(expected_ordinary_count, int):
            ordinary_schema["minItems"] = expected_ordinary_count
            ordinary_schema["maxItems"] = expected_ordinary_count

        acquisition_properties: dict[str, Any] = {
            "sphere_free_talent_pairs": {
                "type": "array",
                "items": pair_schema,
                "uniqueItems": True,
            },
            "ordinary_talent_ids": ordinary_schema,
            "insight_occurrences": {
                "type": "array",
                "uniqueItems": True,
                "items": (
                    {"oneOf": insight_occurrence_alternatives}
                    if insight_occurrence_alternatives
                    else self._impossible_schema()
                ),
            },
        }
        acquisition_properties["manual_collection"] = {
            "type": "object",
            "additionalProperties": False,
            "required": ["schema", "policy_id", "roll", "manuals"],
            "properties": {
                "schema": {"const": "TianxiaFoundry.LineageManualCollection.v1"},
                "policy_id": {"const": "TIANXIA.FACTORY.MARTIAL_MANUAL_COLLECTION.D6_BANDS.v1"},
                "roll": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["policy_id", "schema", "band", "cl", "dice_count", "die_sides", "faces", "total"],
                    "properties": {
                        "policy_id": {"const": "TIANXIA.FACTORY.MARTIAL_MANUAL_COLLECTION.D6_BANDS.v1"},
                        "schema": {"const": "TianxiaFoundry.LineageManualCollection.v1"},
                        "band": {"type": "string"},
                        "cl": {"type": "integer", "minimum": 1, "maximum": 20},
                        "dice_count": {"type": "integer", "minimum": 1, "maximum": 4},
                        "die_sides": {"const": 6},
                        "faces": {"type": "array", "minItems": 1, "maxItems": 4, "items": {"type": "integer", "minimum": 1, "maximum": 6}},
                        "total": {"type": "integer", "minimum": 1, "maximum": 24},
                    },
                },
                "manuals": {
                    "type": "array",
                    "minItems": 1,
                    "items": {
                        "type": "object",
                        "additionalProperties": False,
                        "required": ["collection_id", "content_record_ids", "content_record_bindings"],
                        "properties": {
                            "collection_id": {"type": "string", "minLength": 1},
                            "content_record_ids": {"type": "array", "minItems": 3, "maxItems": 3, "uniqueItems": True, "items": {"type": "string", "minLength": 1}},
                            "content_record_bindings": {
                                "type": "array",
                                "minItems": 3,
                                "maxItems": 3,
                                "items": {
                                    "type": "object",
                                    "additionalProperties": False,
                                    "required": ["record_id", "record_hash", "source"],
                                    "properties": {
                                        "record_id": {"type": "string", "minLength": 1},
                                        "record_hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
                                        "source": {
                                            "type": "object",
                                            "additionalProperties": False,
                                            "required": ["source_id", "path", "anchor", "source_hash"],
                                            "properties": {
                                                "source_id": {"type": "string", "minLength": 1},
                                                "path": {"type": "string", "minLength": 1},
                                                "anchor": {"type": "string", "minLength": 1},
                                                "source_hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
                                            },
                                        },
                                    },
                                },
                            },
                        },
                    },
                },
            },
        }
        creation_training_contract = envelope.get("creation_training_contract")
        preferred_acquisition_required_keys = set(PREFERRED_ACQUISITION_KEYS)
        from character_creation.constructed_arts.explicit_forging import DESIGNS, has_explicit_forging_contract
        if has_explicit_forging_contract(envelope):
            acquisition_properties["forged_technique_concepts"] = {"type": "array", "maxItems": 2, "uniqueItems": True, "items": {"enum": [deepcopy(row["concept"]) for row in DESIGNS.values()]}}
            preferred_acquisition_required_keys.add("forged_technique_concepts")
        if isinstance(creation_training_contract, dict):
            trained_choice_schema: dict[str, Any] = {
                "type": "object",
                "additionalProperties": False,
                "required": ["cl", "slot", "choice_type", "record_id", "source", "outcome"],
                "properties": {
                    "cl": {"type": "integer", "minimum": 1, "maximum": target_cl or 20},
                    "slot": {"type": "integer", "minimum": 1, "maximum": 3},
                    "choice_type": {"type": "string", "enum": ["new_sphere", "known_sphere_talent"]},
                    "record_id": {"type": "string", "minLength": 1},
                    "source": {"type": "object"},
                    "outcome": {"type": "object"},
                    "bonus_talent_id": {"type": "string", "minLength": 1},
                },
            }
            acquisition_properties["trained_choices"] = {
                "type": "array",
                "items": trained_choice_schema,
                "maxItems": (target_cl or 20) * 3,
                **(
                    {"minItems": (target_cl or 20) * 3}
                    if creation_training_contract.get("required_choices_per_cl") == 3
                    else {}
                ),
            }
            preferred_acquisition_required_keys.add("trained_choices")

        bounded_properties: dict[str, Any] = {}
        foundation_stage_contract = ((request.get("bounded_choice_contract") or {}).get("fields") or {}).get("foundation_initial_stage")
        if isinstance(foundation_stage_contract, dict):
            bounded_properties["foundation_initial_stage"] = {
                "enum": [None, *sorted({stage for stages in foundation_stage_contract.get("options_by_foundation_id", {}).values() for stage in stages})],
                "description": "Exact initial stage for the selected Foundation; null only when its published stage is unique or no Foundation is selected.",
            }
        prompt_locks = (request.get("stage1_prompt") or {}).get("envelope", {}).get("user_locks") or []
        point_buy_lock = next(
            (
                row.get("value")
                for row in prompt_locks
                if isinstance(row, dict) and row.get("field") == "character_sheet.ability_point_buy"
            ),
            {},
        )
        fixed_scores = point_buy_lock.get("fixed_scores") if isinstance(point_buy_lock, dict) else None
        ability_scores_are_nonderivable = not (
            isinstance(fixed_scores, dict)
            and set(fixed_scores) == {"STR", "DEX", "CON", "INT", "WIS", "CHA"}
            and not point_buy_lock.get("auto_abilities")
        )
        if ability_scores_are_nonderivable:
            point_buy_costs = {8: 0, 9: 1, 10: 2, 11: 3, 12: 4, 13: 5, 14: 7, 15: 9}
            point_buy_alternatives = []
            for values in itertools.product(sorted(point_buy_costs), repeat=6):
                if sum(point_buy_costs[value] for value in values) != 27:
                    continue
                point_buy_alternatives.append({
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["STR", "DEX", "CON", "INT", "WIS", "CHA"],
                    "properties": {
                        ability: {"const": values[index]}
                        for index, ability in enumerate(("STR", "DEX", "CON", "INT", "WIS", "CHA"))
                    },
                })
            bounded_properties["ability_scores"] = {
                "oneOf": point_buy_alternatives,
                "x-point-buy-budget": 27,
            }
        background_contract = typed_choice_authority.get("background_choice") or {}
        background_adjustments = background_contract.get("ability_adjustment_by_choice") or {}
        background_choices = (choices_by_slot.get("background_choice") or {}).values()
        background_adjustment_rows = [
            authority
            for choice in background_choices
            if isinstance(choice, dict)
            for authority in [
                background_adjustments.get(choice.get("choice_id"))
                or choice.get("stage2_authority")
                or (choice.get("compatibility") or {}).get("factory", {}).get("stage2_authority")
                or {}
            ]
        ]
        background_abilities = sorted({
            ability
            for authority in background_adjustment_rows
            # Stage 1 publishes the typed contract as the adjustment itself,
            # while older choice projections wrapped it under
            # ``ability_adjustment``.  Accept both frozen representations;
            # neither path interprets planner prose.
            for adjustment in [
                authority.get("ability_adjustment")
                if isinstance(authority, dict) and isinstance(authority.get("ability_adjustment"), dict)
                else authority
            ]
            if isinstance(adjustment, dict)
            for ability in adjustment.get("allowed_abilities") or []
            if isinstance(ability, str)
        })
        if background_abilities:
            bounded_properties["background_ability"] = {"type": "string", "enum": background_abilities}
            background_amount_choices = sorted({
                amount
                for authority in background_adjustment_rows
                for adjustment in [
                    authority.get("ability_adjustment")
                    if isinstance(authority, dict) and isinstance(authority.get("ability_adjustment"), dict)
                    else authority
                ]
                if isinstance(adjustment, dict)
                for amount in (
                    adjustment.get("allowed_amounts")
                    or adjustment.get("amount_choices")
                    or []
                )
                if type(amount) is int
            })
            if background_amount_choices:
                bounded_properties["background_ability_amount"] = {
                    "type": "integer",
                    "enum": background_amount_choices,
                }

        if milestone_rows:
            asi_alternatives_by_milestone: dict[str, list[dict[str, Any]]] = {}
            # The delegated envelope advertises all three Path progression
            # tracks, while the project lock normally contains only the
            # owner-selected tracks.  Schema generation must still publish
            # the typed ASI contract for every offered Path.  Resolve the
            # remaining Path feature authority from the authenticated
            # non-Sphere registry; this is the same source-backed projection
            # used by Stage 2 materialization, never planner prose.
            path_authority = NonSphereAuthorityService(self.db)
            for milestone in milestone_rows:
                feature = locked_records.get(milestone.get("feature_record_id")) or {}
                if not feature:
                    path_id = milestone.get("path_id")
                    feature_id = milestone.get("feature_record_id")
                    if isinstance(path_id, str) and isinstance(feature_id, str):
                        feature = path_authority.project_locked_path_feature_catalog_record(path_id, feature_id)
                authority = (feature.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {})
                rule = authority.get("ability_change") or {}
                allowed_deltas = [value for value in rule.get("allowed_deltas") or [] if type(value) is int]
                budget = rule.get("budget")
                alternatives: list[dict[str, Any]] = []
                if allowed_deltas and type(budget) is int:
                    for count in range(1, 7):
                        for abilities in itertools.combinations(("STR", "DEX", "CON", "INT", "WIS", "CHA"), count):
                            for deltas in itertools.product(allowed_deltas, repeat=count):
                                if sum(deltas) != budget:
                                    continue
                                alternatives.append({
                                    "type": "object",
                                    "additionalProperties": False,
                                    "required": list(abilities),
                                    "properties": {
                                        ability: {"const": delta}
                                        for ability, delta in zip(abilities, deltas)
                                    },
                                })
                if "ability_score_change" in (milestone.get("allowed_kinds") or []) and not alternatives:
                    # A milestone with no source-backed ASI rule must not be
                    # represented by an empty oneOf or an invented generic
                    # delta shape.  Omit it from the response contract and
                    # publish the omission as review metadata; if a response
                    # supplies that field, the ordinary bounded-field /
                    # materialization boundary rejects it explicitly.
                    omitted_milestones.append({
                        "milestone_id": milestone.get("milestone_id"),
                        "path_id": milestone.get("path_id"),
                        "feature_record_id": milestone.get("feature_record_id"),
                        "reason": "NO_SOURCE_BACKED_ABILITY_SCORE_CHANGE_AUTHORITY",
                    })
                    continue
                if alternatives:
                    asi_alternatives_by_milestone[milestone["milestone_id"]] = alternatives
            milestone_properties = {
                milestone_id: {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["deltas"],
                    "properties": {"deltas": {"oneOf": alternatives}},
                }
                for milestone_id, alternatives in asi_alternatives_by_milestone.items()
            }
            if milestone_properties:
                bounded_properties["ability_score_changes_by_milestone_id"] = {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": milestone_properties,
                }

        ambiguous_progressions = {
            str(row.get("cl")): [value for value in row.get("path_ids") or [] if isinstance(value, str)]
            for row in envelope.get("path_progression_choices") or []
            if isinstance(row, dict) and isinstance(row.get("cl"), int) and len(row.get("path_ids") or []) > 1
        }
        if ambiguous_progressions:
            bounded_properties["path_progression_by_cl"] = {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    cl: {"type": "string", "enum": path_ids}
                    for cl, path_ids in ambiguous_progressions.items()
                },
            }

        # Starting proficiencies are a single frozen authority contract.  The
        # response schema exposes only the advertised maps and their exact
        # per-record enums; fixed Background grants remain metadata in the
        # contract and are never response-authored.
        starting_proficiency_contract = (
            (request.get("bounded_choice_contract") or {}).get(
                "starting_proficiency_choice_contract"
            )
            if isinstance(request.get("bounded_choice_contract"), dict)
            else None
        )
        starting_proficiency_properties, starting_proficiency_required = (
            _starting_proficiency_schema_properties(starting_proficiency_contract)
        )
        advertised_starting_fields = (
            (request.get("bounded_choice_contract") or {}).get("fields") or {}
            if isinstance(request.get("bounded_choice_contract"), dict)
            else {}
        )
        advertised_starting_fields = (
            set(advertised_starting_fields)
            if isinstance(advertised_starting_fields, dict)
            else set()
        )
        starting_proficiency_required = [
            field
            for field in starting_proficiency_required
            if field in advertised_starting_fields
        ]
        for field, field_schema in starting_proficiency_properties.items():
            if field in advertised_starting_fields:
                bounded_properties[field] = field_schema

        delegated_name_contract = envelope.get("delegated_name_contract") or {}
        delegated_name_state = str(delegated_name_contract.get("state") or "delegated")
        name_schema: dict[str, Any] = {
            "type": "string",
            "minLength": 1,
            # minLength alone accepts whitespace-only values; the delegated
            # semantic contract requires one non-whitespace character.
            "pattern": r".*\S.*",
        }
        if delegated_name_state == "owner_locked" and isinstance(
            delegated_name_contract.get("owner_locked_value"), str
        ):
            name_schema = {"const": delegated_name_contract["owner_locked_value"]}

        delegated_title_contract = envelope.get("delegated_title_contract") or {}
        title_contract_active = (
            isinstance(delegated_title_contract, dict)
            and delegated_title_contract.get("schema") == "TianxiaFoundry.DelegatedTitleRequirement.v1"
            and delegated_title_contract.get("field") == "owner_descriptive_fields.identity.title"
            and delegated_title_contract.get("required") is True
            and delegated_title_contract.get("nonblank") is True
        )
        delegated_title_state = str(delegated_title_contract.get("state") or "delegated")
        title_schema: dict[str, Any] = {
            "type": "string",
            "minLength": 1,
            "maxLength": 120,
            "pattern": r".*\S.*",
        }
        if title_contract_active and delegated_title_state == "owner_locked" and isinstance(
            delegated_title_contract.get("owner_locked_value"), str
        ):
            title_schema = {"const": delegated_title_contract["owner_locked_value"]}
        identity_required = ["name"]
        identity_properties: dict[str, Any] = {"name": name_schema}
        if title_contract_active:
            identity_required.append("title")
            identity_properties["title"] = title_schema

        preferred_response_schema = {
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "title": "TianxiaFoundry delegated selection-intent response",
            "type": "object",
            "additionalProperties": False,
            "required": sorted(PREFERRED_RESPONSE_KEYS),
            "properties": {
                "schema": {"const": DELEGATED_RESPONSE_SCHEMA},
                "request_sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$", "const": request["request_sha256"]},
                "selection_intent": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["by_slot"],
                    "properties": {
                        "by_slot": {
                            "type": "object",
                            "additionalProperties": False,
                            "required": required_selection_slots,
                            "properties": selection_properties,
                        },
                    },
                },
                "acquisition_intent": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": sorted(preferred_acquisition_required_keys),
                    "properties": acquisition_properties,
                },
                "bounded_choices": {
                    "type": "object",
                    "additionalProperties": False,
                    "properties": bounded_properties,
                    **(
                        {"required": sorted(starting_proficiency_required)}
                        if starting_proficiency_required
                        else {}
                    ),
                },
                "owner_descriptive_fields": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["identity"],
                    "properties": {
                        "identity": {
                            "type": "object",
                            "additionalProperties": False,
                            "required": identity_required,
                            "properties": identity_properties,
                        },
                        "concept": {"type": "string"},
                    },
                },
            },
            "x-delegated-name-contract": deepcopy(delegated_name_contract),
            **(
                {"x-delegated-title-contract": deepcopy(delegated_title_contract)}
                if title_contract_active
                else {}
            ),
            "x-frozen-offered-choice-ids-by-slot": deepcopy(allowed_by_slot),
            "x-choice-records-by-slot": deepcopy(choices_by_slot),
            "x-advertised-advancement-choice-milestones": deepcopy(milestone_rows),
            "x-omitted-advancement-choice-milestones": deepcopy(omitted_milestones),
            "x-server-owned-fields": [
                "target_cl",
                "stage1_response",
                "stage2_proposal",
                "event_kinds",
                "acquisition_channels",
                "effective_cl_rows",
                "automatic_grants",
                "hashes",
                "receipts",
            ],
        }
        self._validate_generated_response_schema(preferred_response_schema)
        response_schema = {
            "schema": DELEGATED_RESPONSE_SCHEMA,
            "preferred_required": list(request["required_components"]),
            "preferred_response": preferred_response_schema,
            "historical_compatibility": [PLAN_SCHEMA, LEGACY_PLAN_SCHEMA],
            "request_sha256": request["request_sha256"],
            "forbidden_planner_fields": request["forbidden_planner_fields"],
            # The complete request remains the private authority used by the
            # compiler.  Manual Chat receives only the transfer-safe portion;
            # the collection nonce/seed is internal replay authority and must
            # never cross this boundary.
            "server_owned": deepcopy(request.get("server_owned_authority", {})),
            "bounded_choice_contract": request.get("bounded_choice_contract", {}),
            "authority": "Planner prose, Stage 1 bindings, Stage 2 rows, and asserted compiled surfaces are not mechanical authority.",
        }
        transfer_server_owned = response_schema["server_owned"]
        if isinstance(transfer_server_owned, dict):
            transfer_server_owned.pop("manual_collection", None)
        binding = {
            "schema": "TianxiaFoundry.CharacterCreationRequestBinding.v1",
            "project_id": run["project_id"],
            "project_revision": run["starting_revision"],
            "content_lock_hash": request["content_lock_hash"],
            "typed_choice_snapshot_sha256": request["typed_choice_snapshot"]["snapshot_sha256"],
            "request_sha256": request["request_sha256"],
            "owner_principal_hash": self.owner_principal_hash,
        }
        delegated_title_contract_for_package = (
            request.get("delegated_title_contract")
            if isinstance(request.get("delegated_title_contract"), dict)
            else {}
        )
        title_package_instruction = (
            b" If delegated, owner_descriptive_fields.identity.title is required and must be concise and nonblank; "
            b"if owner-locked, copy it exactly. Never infer a title from name, concept, catalog, or prose."
            if delegated_title_contract_for_package.get("required") is True
            else b""
        )
        transfer_request = deepcopy(request)
        transfer_request_authority = transfer_request.get("server_owned_authority")
        if isinstance(transfer_request_authority, dict):
            transfer_request_authority.pop("manual_collection", None)
        entries = {
            "BINDING.json": canonical_json(binding).encode("utf-8") + b"\n",
            "COMPLETE_REQUEST.json": canonical_json(transfer_request).encode("utf-8") + b"\n",
            "README_START_HERE.md": (
                b"# Start Here: Complete Character Response\n\n"
                b"This package is an owner-mediated Manual Chat transfer for automatic character creation only. "
                b"A compatible receiving chat may be ChatGPT, ChatGPT Work, Codex, or another compatible chat. "
                b"It is not a combat or game-session control package.\n\n"
                b"Read COMPLETE_REQUEST.json, PROMPT_INSTRUCTIONS.md, and RESPONSE_SCHEMA.json. Return one "
                b"response file for this exact request. Do not edit the request, invent mechanics, call APIs, "
                b"control combat, or claim mechanical authority. Return stable offered IDs, descriptive fields, "
                b"and semantic acquisition intent/bounded choices only. Use Sphere/free-Talent pairs, ordinary "
                b"Talent IDs, and source-backed Insight occurrences; the local Factory owns target CL, "
                b"Stage 1/Stage 2 materialization, validation, compilation, and receipts. Any plan allowance "
                b"described in the request is not direct API credit. If the delegated name contract is positive "
                b"delegation, owner_descriptive_fields.identity.name is required and must contain a nonblank "
                b"proposed name; if it is owner-locked, copy that exact name unchanged."
                + title_package_instruction
                + b"\n"
            ),
            "PROMPT_INSTRUCTIONS.md": (
                b"# Complete Character Creation Request\n\nReturn exactly one JSON object conforming "
                b"to the preferred delegated selection-intent response in RESPONSE_SCHEMA.json. Copy the exact "
                b"request_sha256 into the response. Do not choose or copy target CL, Stage 1 bindings, Stage 2 "
                b"event kinds/channels/effective CL rows, automatic grants, hashes, readiness, or artifact "
                b"identities. Select offered stable IDs only. Keep ordered priorities separate from an explicit "
                b"acquisition_intent semantic object (never backend rows) and provide only exact bounded choices advertised by the request. "
                b"The delegated name contract is positive delegation: owner_descriptive_fields.identity.name "
                b"must be present and nonblank when delegated, while an owner-locked name must be copied exactly. Owner "
                b"descriptions are allowed; prose never creates mechanics."
                + title_package_instruction
                + b" The local Factory validates and "
                b"materializes every mechanical choice. Historical full-row responses remain compatibility input "
                b"only and must equal the server materialization.\n"
            ),
            "RESPONSE_SCHEMA.json": canonical_json(response_schema).encode("utf-8") + b"\n",
        }
        if run.get("execution_mode") == "MANUAL_CHAT":
            compact_model = build_compact_choice_model(request)
            entries["AI_CHOICE_MODEL.json"] = canonical_json(compact_model).encode("utf-8") + b"\n"
            entries["AI_INSTRUCTIONS.md"] = self._manual_ai_instructions(request, compact_model)
            entries["README_START_HERE.md"] += (
                b"\nFor Manual Chat, also read AI_INSTRUCTIONS.md and AI_CHOICE_MODEL.json. "
                b"The ordinary_talent_ids array is positional: index 0 is CL1 and the "
                b"final active position is the frozen request target CL. Each ordinary "
                b"Talent must be distinct. If a compact model repeats legal same-sphere "
                b"anchors, the Factory may expand them deterministically only through "
                b"frozen server-owned legal plan authority. The compact model is choice "
                b"context only; the Factory remains the legality and compilation authority.\n"
            )
        entries["SHA256SUMS.txt"] = "".join(
            f"{sha256_bytes(entries[name])}  {name}\n" for name in sorted(entries)
        ).encode("ascii")
        filename = f"CG1_COMPLETE_REQUEST_{run['project_id']}_{request['request_sha256'][:12]}.zip"
        member_inventory = [
            {"name": name, "bytes": len(entries[name]), "sha256": sha256_bytes(entries[name])}
            for name in sorted(entries)
        ]
        content_set_sha256 = sha256_json(member_inventory)
        payload = self._deterministic_zip(entries)
        return {
            "filename": filename,
            "payload": payload,
            "request_payload_sha256": self.request_payload_sha256(request),
            "member_inventory": member_inventory,
            "content_set_sha256": content_set_sha256,
            "final_zip_sha256": sha256_bytes(payload),
        }

    def complete_request_zip(self, run_id: str) -> tuple[str, bytes]:
        package = self._complete_request_package(run_id)
        return package["filename"], package["payload"]

    def _complete_request_receipt_from_package(
        self,
        run: dict[str, Any],
        package: dict[str, Any],
    ) -> dict[str, Any]:
        request = run["request"]
        return {
            "schema": "TianxiaFoundry.CompleteRequestSaveReceipt.v2",
            "run_id": run["run_id"],
            "project_id": run["project_id"],
            "starting_revision": run["starting_revision"],
            "filename": package["filename"],
            "request_payload_sha256": package["request_payload_sha256"],
            "content_set_sha256": package["content_set_sha256"],
            "final_zip_sha256": package["final_zip_sha256"],
            "final_zip_bytes": len(package["payload"]),
            "member_inventory": package["member_inventory"],
            "request": {
                "request_sha256": request["request_sha256"],
                "content_lock_hash": request["content_lock_hash"],
                "typed_choice_snapshot": {
                    "snapshot_sha256": request["typed_choice_snapshot"]["snapshot_sha256"],
                },
            },
        }

    def complete_request_download(self, run_id: str) -> dict[str, Any]:
        """Build one package for both the response body and its receipt headers."""
        run = self.get(run_id)
        package = self._complete_request_package(run_id)
        return {
            "filename": package["filename"],
            "payload": package["payload"],
            "receipt": self._complete_request_receipt_from_package(run, package),
        }

    def complete_request_save_receipt(self, run_id: str) -> dict[str, Any]:
        """Return the bounded server-owned identity needed by native Save As."""
        run = self.get(run_id)
        package = self._complete_request_package(run_id)
        return self._complete_request_receipt_from_package(run, package)

    def _resumable_awaiting_agent_run(
        self,
        old: Any,
        *,
        project_id: str,
        mode: str,
        controller_route: str,
        combat_ready: bool,
        revision_request: Any,
        required_designs: Any,
    ) -> dict[str, Any] | None:
        """Return the resumable agent-awaiting run, or ``None``.

        The stored run must still match every guard a same-key replay already
        enforces — execution mode, project revision, content lock, controller
        route, combat target, the requested ``revision_request``, required
        designs, and the server-owned idempotency binding — and its mailbox
        must still hold a resumable row for the run-scoped step key.  ``None`` therefore means
        "not resumable": the caller keeps whatever replay or conflict decision
        it would otherwise make.  This helper never raises for a malformed or
        foreign run; the guards simply fail closed.
        """

        try:
            if str(old["status"] or "") != AGENT_AWAITING_RUN_STATUS:
                return None
            if mode not in {"STANDARD_API", "AUTO_FINALIZE_WHEN_CLEAN"}:
                return None
            if str(old["execution_mode"] or "") != mode:
                return None
            try:
                request = json.loads(old["request_json"] or "{}")
            except (TypeError, ValueError, json.JSONDecodeError):
                return None
            if not isinstance(request, dict):
                return None
            if request.get("project_id") != project_id:
                return None
            if request.get("project_revision") != self._revision(project_id):
                return None
            if request.get("content_lock_hash") != self._content_lock_hash(project_id):
                return None
            if request.get("controller_route") != controller_route:
                return None
            if _provider_combat_ready_requested(request) is not combat_ready:
                return None
            # The requested revision/brief must be the one this run was created
            # with: a same-key call for a different revision is a conflict, not
            # a resume, and must never consume the parked answer.
            if request.get("revision_request") != revision_request:
                return None
            from character_creation.constructed_arts.explicit_forging import (
                normalize_required_design_ids as _normalize_design_ids,
            )

            if _normalize_design_ids(request.get("required_forged_design_ids"), request.get("revision_request")) != required_designs:
                return None
            if request.get("idempotency_binding_sha256") != sha256_json({
                "project_id": project_id,
                "starting_revision": request.get("project_revision"),
                "content_lock_hash": request.get("content_lock_hash"),
                "execution_mode": str(old["execution_mode"]),
                "request_sha256": request.get("request_sha256"),
                "idempotency_key": str(old["idempotency_key"] or ""),
                "owner_principal": self.owner_principal,
            }):
                return None
        except (KeyError, TypeError, ValueError):
            return None
        step_key = _creation_provider_step_key(old["run_id"], request.get("request_sha256"))
        if _open_agent_step_request(self.provider, step_key=step_key) is None:
            return None
        return self.get(old["run_id"])

    def start(
        self,
        project_id: str,
        *,
        execution_mode: str,
        idempotency_key: str,
        revision_request: dict[str, Any] | None = None,
        combat_ready: bool = False,
        controller_route: str | None = None,
        required_forged_design_ids: list[str] | None = None,
    ) -> dict[str, Any]:
        from character_creation.constructed_arts.explicit_forging import normalize_required_design_ids
        required_designs = normalize_required_design_ids(required_forged_design_ids, revision_request)
        if required_designs and normalize_controller_route(controller_route) != DETERMINISTIC_CREATIVE_CONTROLLER:
            raise FoundryError("CG1_REQUIRED_FORGED_DESIGNS_ROUTE_UNSUPPORTED", "Required Forge designs need the deterministic creative controller.", status_code=422)
        mode = str(execution_mode or "").strip().upper()
        if mode not in MODES:
            raise FoundryError("CG1_EXECUTION_MODE_INVALID", "Choose Manual Chat, Standard API, or Auto-Finalize When Clean.")
        if type(combat_ready) is not bool:
            raise FoundryError(
                "CG1_OUTPUT_PROFILE_AUTHORITY_INVALID",
                "combat_ready must be an explicit boolean owner target.",
                status_code=422,
            )
        controller_route = normalize_controller_route(controller_route)
        key = str(idempotency_key or "").strip()
        if len(key) < 8:
            raise FoundryError("CG1_IDEMPOTENCY_KEY_INVALID", "The build request key must be at least 8 characters.")
        old = None
        persisted_manual_collection_nonce = None
        with self.db.connection() as conn:
            old = conn.execute(
                "SELECT * FROM character_creation_runs WHERE project_id=? AND idempotency_key=?",
                (project_id, key),
            ).fetchone()
        if old is not None:
            try:
                persisted_request = json.loads(old["request_json"] or "{}")
            except (TypeError, ValueError, json.JSONDecodeError):
                persisted_request = {}
            marker = (
                ((persisted_request.get("server_owned_authority") or {}).get("manual_collection"))
                if isinstance(persisted_request, dict)
                else None
            )
            persisted_nonce = marker.get("nonce") if isinstance(marker, dict) else None
            if (
                isinstance(persisted_nonce, str)
                and len(persisted_nonce) >= 32
                and persisted_nonce.strip()
                and marker.get("authority_version") == "server_owned_pre_provider.v2"
            ):
                persisted_manual_collection_nonce = persisted_nonce
                # A run parked on an unanswered agent request is still this
                # step's active work: resume it here instead of replaying the
                # parked view, so the early nonce path cannot strand it.
                resumable = self._resumable_awaiting_agent_run(
                    old,
                    project_id=project_id,
                    mode=mode,
                    controller_route=controller_route,
                    combat_ready=combat_ready,
                    revision_request=revision_request,
                    required_designs=required_designs,
                )
                if resumable is not None:
                    return self._run_provider(resumable["run_id"])
            elif (
                old["execution_mode"] == mode
                and isinstance(persisted_request, dict)
                and persisted_request.get("project_id") == project_id
                and persisted_request.get("project_revision") == self._revision(project_id)
                and persisted_request.get("content_lock_hash") == self._content_lock_hash(project_id)
                and persisted_request.get("controller_route") == controller_route
                and _provider_combat_ready_requested(persisted_request) is combat_ready
                and persisted_request.get("revision_request") == revision_request
                and normalize_required_design_ids(persisted_request.get("required_forged_design_ids"), persisted_request.get("revision_request")) == required_designs
                and persisted_request.get("idempotency_binding_sha256") == sha256_json({
                    "project_id": project_id,
                    "starting_revision": persisted_request.get("project_revision"),
                    "content_lock_hash": persisted_request.get("content_lock_hash"),
                    "execution_mode": mode,
                    "request_sha256": persisted_request.get("request_sha256"),
                    "idempotency_key": key,
                    "owner_principal": self.owner_principal,
                })
            ):
                prior = self._public(old)
                resumable = self._resumable_awaiting_agent_run(
                    old,
                    project_id=project_id,
                    mode=mode,
                    controller_route=controller_route,
                    combat_ready=combat_ready,
                    revision_request=revision_request,
                    required_designs=required_designs,
                )
                if resumable is not None:
                    return self._run_provider(resumable["run_id"])
                prior["idempotent"] = True
                return prior
        request = self._complete_request(
            project_id,
            revision_request,
            execution_mode=mode,
            idempotency_key=key,
            combat_ready=combat_ready,
            controller_route=controller_route,
            manual_collection_nonce=persisted_manual_collection_nonce,
            required_forged_design_ids=required_designs or None,
        )
        # Resolve the route authority before recording any run.  In particular,
        # an unavailable active DCC publication or selected AI must not leave a
        # preference/run side effect behind.
        self.set_preference(project_id, mode)
        binding = sha256_json({"project_id": project_id, "starting_revision": request["project_revision"], "content_lock_hash": request["content_lock_hash"], "execution_mode": mode, "request_sha256": request["request_sha256"], "idempotency_key": key, "owner_principal": self.owner_principal})
        request["idempotency_binding_sha256"] = binding
        if old:
            prior = self._public(old)
            if prior["execution_mode"] != mode or prior["request"].get("idempotency_binding_sha256") != binding:
                raise FoundryError("CG1_IDEMPOTENCY_CONFLICT", "That request key is bound to a different project revision, content lock, mode, request, or owner.", status_code=409)
            # A run parked on an unanswered agent-bridge request is resumable
            # "not yet" work, not a finished run.  Re-entering provider
            # execution with the same run-scoped step key waits on the same
            # mailbox row and consumes the eventual answer, so an agent that
            # answers after the first wait still completes this exact run.
            resumable = self._resumable_awaiting_agent_run(
                old,
                project_id=project_id,
                mode=mode,
                controller_route=controller_route,
                combat_ready=combat_ready,
                revision_request=revision_request,
                required_designs=required_designs,
            )
            if resumable is not None:
                return self._run_provider(resumable["run_id"])
            prior["idempotent"] = True
            return prior
        now = utcnow(); run_id = "cg1.run." + uuid.uuid4().hex
        status = "WAITING_FOR_RESPONSE" if mode == "MANUAL_CHAT" else "PREPARING_REQUEST"
        with self.db.transaction() as conn:
            conn.execute("""INSERT INTO character_creation_runs(run_id,project_id,starting_revision,execution_mode,idempotency_key,request_json,status,created_at,updated_at)
                         VALUES(?,?,?,?,?,?,?,?,?)""", (run_id, project_id, request["project_revision"], mode, key, canonical_json(request), status, now, now))
            # Bind and seed the DCC event stream in the same transaction as
            # initial run creation.  A legacy route intentionally has no row.
            route_binding = request.get("controller_route_binding")
            if route_binding is not None:
                controller_routes = getattr(self, "controller_routes", None)
                if controller_routes is None:
                    controller_routes = ControllerRoutePersistence(self.db)
                controller_routes.bind_new_run(
                    conn,
                    run_id=run_id,
                    project_id=project_id,
                    request_sha256=request["request_sha256"],
                    binding=route_binding,
                    created_at=now,
                )
        self._append_attempt(
            run_id,
            action_type="REQUEST_CREATED",
            status=status,
            binding={
                "request_sha256": request.get("request_sha256"),
                "project_revision": request.get("project_revision"),
                "content_lock_hash": request.get("content_lock_hash"),
                "execution_mode": mode,
                "idempotency_key": key,
            },
        )
        if mode == "MANUAL_CHAT":
            result = self.get(run_id); result["idempotent"] = False; return result
        if controller_route == DETERMINISTIC_CREATIVE_CONTROLLER:
            # Compatibility requests built by the inactive Stage B seam may
            # still lack a delegated envelope.  They remain provider-free;
            # complete, frozen requests enter the bounded linear walk here.
            result = self.get(run_id)
            if self._has_delegated_envelope(result):
                return self._run_dcc_linear_walk(run_id)
            result["idempotent"] = False
            return result
        provider_status = self.provider.status() or {}
        if not bool(provider_status.get("ready")):
            warning = {
                "code": "CG1_PROVIDER_NOT_READY_FALLBACK_MANUAL",
                "message": "The configured provider is unavailable; no request was transmitted and the run returned to Manual Chat.",
                "provider": provider_status,
            }
            transport = {
                "mode": mode,
                "provider_called": False,
                "provider_status": provider_status,
                "fallback_mode": "MANUAL_CHAT",
            }
            with self.db.transaction() as conn:
                conn.execute(
                    "UPDATE character_creation_runs SET execution_mode='MANUAL_CHAT',transport_json=?,status='WAITING_FOR_RESPONSE',warnings_json=?,updated_at=? WHERE run_id=?",
                    (canonical_json(transport), canonical_json([warning]), utcnow(), run_id),
                )
            return self.get(run_id)
        return self._run_provider(run_id)

    @staticmethod
    def _infer_missing_preferred_response_schema(
        plan: Any,
        *,
        expected_request_sha256: str | None,
        creation_training_active: bool = False,
        explicit_forging_active: bool = False,
    ) -> dict[str, Any] | None:
        """Project one exact schema-less preferred response in memory.

        A provider response is retained as exact text/bytes by the caller.  A
        missing schema member is the only compatibility defect that can be
        repaired here, and only when the complete preferred top-level object
        and its active request binding are already present.  Historical plans,
        diagnostics, and partial objects deliberately return ``None`` so the
        normal schema gate rejects them.
        """
        if not isinstance(plan, dict) or "schema" in plan:
            return None
        if not isinstance(expected_request_sha256, str) or not expected_request_sha256:
            return None
        required_without_schema = PREFERRED_RESPONSE_KEYS - {"schema"}
        if set(plan) != required_without_schema:
            return None
        if plan.get("request_sha256") != expected_request_sha256:
            return None

        selection = plan.get("selection_intent")
        by_slot = selection.get("by_slot") if isinstance(selection, dict) else None
        if (
            not isinstance(selection, dict)
            or set(selection) != {"by_slot"}
            or not isinstance(by_slot, dict)
        ):
            return None
        if any(
            not isinstance(slot_id, str)
            or not slot_id
            or not isinstance(values, list)
            or any(not isinstance(value, str) or not value for value in values)
            for slot_id, values in by_slot.items()
        ):
            return None

        acquisition = plan.get("acquisition_intent")
        preferred_acquisition_keys = PREFERRED_ACQUISITION_KEYS | (
            {"trained_choices"} if creation_training_active else set()
        ) | ({"forged_technique_concepts"} if explicit_forging_active else set())
        allowed_acquisition_keys = preferred_acquisition_keys | OPTIONAL_PREFERRED_ACQUISITION_KEYS
        if (
            not isinstance(acquisition, dict)
            or not preferred_acquisition_keys.issubset(acquisition)
            or bool(set(acquisition) - allowed_acquisition_keys)
            or any(not isinstance(acquisition.get(key), list) for key in preferred_acquisition_keys)
        ):
            return None
        if not isinstance(plan.get("bounded_choices"), dict) or not isinstance(plan.get("owner_descriptive_fields"), dict):
            return None

        projected = deepcopy(plan)
        projected["schema"] = DELEGATED_RESPONSE_SCHEMA
        return projected

    @staticmethod
    def _parse_plan(
        response_text: str,
        *,
        expected_project_id: str | None = None,
        expected_project_revision: int | None = None,
        expected_request_sha256: str | None = None,
        compatibility_receipt: dict[str, Any] | None = None,
        allow_proven_stale_advancement_echo: bool = False,
        creation_training_active: bool = False,
        explicit_forging_active: bool = False,
    ) -> tuple[dict[str, Any], bytes]:
        raw = response_text.encode("utf-8")
        try:
            plan = json.loads(response_text)
        except json.JSONDecodeError as exc:
            raise FoundryError("CG1_PLAN_JSON_INVALID", "The complete character plan response is not valid JSON.", details={"line": exc.lineno, "column": exc.colno}) from exc
        inferred_preferred = CharacterCreationExecutionService._infer_missing_preferred_response_schema(
            plan,
            expected_request_sha256=expected_request_sha256,
            creation_training_active=creation_training_active,
            explicit_forging_active=explicit_forging_active,
        )
        if inferred_preferred is not None:
            # The exact response bytes remain the ``raw`` value returned to
            # the caller.  Only this parsed in-memory projection gains the
            # constant schema member, and the existing preferred validator
            # below is still authoritative for every nested field.
            plan = inferred_preferred
            if compatibility_receipt is not None:
                compatibility_receipt.update({
                    "schema": "TianxiaFoundry.MissingSchemaCompatibilityProjection.v1",
                    "inferred_schema": DELEGATED_RESPONSE_SCHEMA,
                    "source_schema_member": "absent",
                    "top_level_shape_exact": True,
                    "request_binding_exact": True,
                    "exact_response_bytes_preserved": True,
                })
        if (
            isinstance(plan, dict)
            and plan.get("schema") in {PLAN_SCHEMA, LEGACY_PLAN_SCHEMA}
            and set(plan) == PREFERRED_RESPONSE_KEYS
        ):
            raise FoundryError(
                "CG1_PLAN_SCHEMA_INVALID",
                "A preferred delegated response cannot be relabeled as a historical plan schema.",
                details={"schema": plan.get("schema"), "preferred_shape": True},
            )
        if not isinstance(plan, dict) or plan.get("schema") not in {
            PLAN_SCHEMA,
            LEGACY_PLAN_SCHEMA,
            DELEGATED_RESPONSE_SCHEMA,
        }:
            raise FoundryError(
                "CG1_PLAN_SCHEMA_INVALID",
                f"The response must use {DELEGATED_RESPONSE_SCHEMA} (preferred) or a supported historical plan schema such as TianxiaFoundry.CharacterCreationPlan.v2.",
            )
        if plan.get("schema") == DELEGATED_RESPONSE_SCHEMA:
            selection = plan.get("selection_intent")
            # Preserve exact submitted bytes while accepting one uniquely
            # reversible Qwen shape slip: advancement_skeleton was moved one
            # object level up from its advertised by_slot location. Never
            # overwrite a destination or repair any other sibling/slot shape.
            if (
                isinstance(selection, dict)
                and set(selection) == {"by_slot", "advancement_skeleton"}
                and isinstance(selection.get("by_slot"), dict)
                and "advancement_skeleton" not in selection["by_slot"]
            ):
                selection["by_slot"]["advancement_skeleton"] = selection.pop("advancement_skeleton")
            # A local model can echo immutable request binding fields even
            # though the preferred response surface is closed. Accept only
            # the uniquely reversible form: both binding values must exactly
            # equal the active frozen run, and a top-level advancement copy
            # must exactly mirror both canonical advertised locations. The
            # submitted bytes remain retained unchanged; only this in-memory
            # semantic projection drops the redundant copies.
            echoed_fields: list[str] = []
            stale_advancement_echo_recovered = False
            if "project_id" in plan:
                if (
                    not isinstance(expected_project_id, str)
                    or not expected_project_id
                    or plan.get("project_id") != expected_project_id
                ):
                    raise FoundryError(
                        "CG1_PREFERRED_RESPONSE_SHAPE_INVALID",
                        "A returned project_id is allowed only as an exact copy of the active frozen binding.",
                        details={"field": "project_id", "binding_match": False},
                    )
                plan.pop("project_id")
                echoed_fields.append("project_id")
            if "project_revision" in plan:
                if (
                    type(expected_project_revision) is not int
                    or type(plan.get("project_revision")) is not int
                    or plan.get("project_revision") != expected_project_revision
                ):
                    raise FoundryError(
                        "CG1_PREFERRED_RESPONSE_SHAPE_INVALID",
                        "A returned project_revision is allowed only as an exact copy of the active frozen binding.",
                        details={"field": "project_revision", "binding_match": False},
                    )
                plan.pop("project_revision")
                echoed_fields.append("project_revision")
            if "advancement_skeleton" in plan:
                top_level_skeleton = plan.get("advancement_skeleton")
                selection_skeleton = (
                    (selection.get("by_slot") or {}).get("advancement_skeleton")
                    if isinstance(selection, dict) and isinstance(selection.get("by_slot"), dict)
                    else None
                )
                acquisition = plan.get("acquisition_intent")
                acquisition_skeleton = (
                    acquisition.get("ordinary_talent_ids")
                    if isinstance(acquisition, dict)
                    else None
                )
                advancement_mirror_exact = (
                    isinstance(top_level_skeleton, list)
                    and top_level_skeleton == selection_skeleton
                    and top_level_skeleton == acquisition_skeleton
                )
                if (
                    not advancement_mirror_exact
                    and not allow_proven_stale_advancement_echo
                ):
                    raise FoundryError(
                        "CG1_PREFERRED_RESPONSE_SHAPE_INVALID",
                        "A top-level advancement_skeleton is allowed only as an exact redundant mirror of both canonical arrays.",
                        details={"field": "advancement_skeleton", "canonical_mirror": False},
                    )
                stale_advancement_echo_recovered = not advancement_mirror_exact
                plan.pop("advancement_skeleton")
                echoed_fields.append("advancement_skeleton")
            if echoed_fields and compatibility_receipt is not None:
                compatibility_receipt.update({
                    "schema": "TianxiaFoundry.ExactEchoCompatibilityProjection.v1",
                    "accepted_redundant_fields": sorted(echoed_fields),
                    "binding_exact": True,
                    "advancement_mirror_exact": (
                        "advancement_skeleton" in echoed_fields
                        and not stale_advancement_echo_recovered
                    ),
                    "stale_server_repair_echo_recovered": stale_advancement_echo_recovered,
                    "exact_response_bytes_preserved": True,
                })
            missing = sorted(PREFERRED_RESPONSE_KEYS - set(plan))
            extra = sorted(set(plan) - PREFERRED_RESPONSE_KEYS)
            if missing or extra:
                raise FoundryError(
                    "CG1_PREFERRED_RESPONSE_SHAPE_INVALID",
                    "The preferred delegated response must contain only selection intent, explicit acquisition intent, bounded choices, and owner descriptive fields.",
                    details={"missing": missing, "unexpected": extra},
                )
            selection = plan.get("selection_intent")
            if (
                not isinstance(selection, dict)
                or set(selection) != {"by_slot"}
                or not isinstance(selection.get("by_slot"), dict)
            ):
                raise FoundryError(
                    "CG1_PREFERRED_RESPONSE_SHAPE_INVALID",
                    "selection_intent.by_slot is required and is the only preferred selection surface.",
                )
            allowed_slots = {
                "path_choice", "method_choice", "foundation_choice", "subpath_choice",
                "background_choice", "background_sphere_choice", "background_talent_choice",
                "origin_insight_choice", "sphere_priorities", "advancement_skeleton",
                "insight_priorities", "item_priorities",
            }
            unknown_slots = sorted(set(selection["by_slot"]) - allowed_slots)
            if unknown_slots:
                raise FoundryError(
                    "CG1_PREFERRED_RESPONSE_SELECTION_INVALID",
                    "selection_intent.by_slot contains an unknown or aliased slot.",
                    details={"slots": unknown_slots},
                    status_code=422,
                )
            for slot_id, values in selection["by_slot"].items():
                if not isinstance(values, list) or any(not isinstance(value, str) or not value for value in values):
                    raise FoundryError(
                        "CG1_PREFERRED_RESPONSE_SELECTION_INVALID",
                        "Every preferred selection slot must contain an array of non-empty stable IDs.",
                        details={"slot_id": slot_id},
                        status_code=422,
                    )
                if len(values) != len(set(values)):
                    raise FoundryError(
                        "CG1_DELEGATED_DUPLICATE_CHOICE",
                        "Preferred selection IDs may not be silently deduplicated.",
                        details={"slot_id": slot_id, "choice_ids": values},
                        status_code=409,
                    )
            acquisition = plan.get("acquisition_intent")
            preferred_acquisition_keys = PREFERRED_ACQUISITION_KEYS | (
                {"trained_choices"} if creation_training_active else set()
            ) | ({"forged_technique_concepts"} if explicit_forging_active else set())
            allowed_acquisition_keys = preferred_acquisition_keys | OPTIONAL_PREFERRED_ACQUISITION_KEYS
            if (
                not isinstance(acquisition, dict)
                or not preferred_acquisition_keys.issubset(acquisition)
                or bool(set(acquisition) - allowed_acquisition_keys)
            ):
                raise FoundryError(
                    "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID",
                    "Preferred acquisition_intent must be the exact semantic object with Sphere pairs, ordinary Talent IDs, and Insight occurrences.",
                    details={
                        "required": sorted(preferred_acquisition_keys),
                        "actual": sorted(acquisition) if isinstance(acquisition, dict) else None,
                    },
                    status_code=422,
                )
            if explicit_forging_active:
                from character_creation.constructed_arts.explicit_forging import validate_explicit_concepts
                validate_explicit_concepts(acquisition.get("forged_technique_concepts"))
            if creation_training_active and not isinstance(acquisition.get("trained_choices"), list):
                raise FoundryError(
                    "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID",
                    "A sealed creation-training contract requires trained_choices as an array.",
                    status_code=422,
                )
            pairs = acquisition.get("sphere_free_talent_pairs")
            if not isinstance(pairs, list):
                raise FoundryError("CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID", "sphere_free_talent_pairs must be an array.", status_code=422)
            pair_spheres: list[str] = []
            pair_talents: list[str] = []
            for index, pair in enumerate(pairs):
                if not isinstance(pair, dict) or set(pair) != {"sphere_id", "talent_id"}:
                    raise FoundryError(
                        "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID",
                        "Sphere/free-Talent pairs may contain only sphere_id and talent_id.",
                        details={"index": index},
                        status_code=422,
                    )
                if not isinstance(pair.get("sphere_id"), str) or not isinstance(pair.get("talent_id"), str):
                    raise FoundryError("CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID", "Sphere/free-Talent IDs must be strings.", details={"index": index}, status_code=422)
                pair_spheres.append(pair["sphere_id"]); pair_talents.append(pair["talent_id"])
            if len(pair_spheres) != len(set(pair_spheres)) or len(pair_talents) != len(set(pair_talents)):
                raise FoundryError("CG1_DELEGATED_DUPLICATE_CHOICE", "Sphere/free-Talent pairs must be unique.", status_code=409)
            ordinary = acquisition.get("ordinary_talent_ids")
            if not isinstance(ordinary, list) or any(not isinstance(value, str) or not value for value in ordinary):
                raise FoundryError("CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID", "ordinary_talent_ids must be an array of stable IDs.", status_code=422)
            if len(ordinary) != len(set(ordinary)):
                raise FoundryError("CG1_DELEGATED_DUPLICATE_CHOICE", "ordinary_talent_ids must be unique.", status_code=409)
            occurrences = acquisition.get("insight_occurrences")
            if not isinstance(occurrences, list):
                raise FoundryError("CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID", "insight_occurrences must be an array.", status_code=422)
            occurrence_keys: set[tuple[str, str]] = set()
            for index, occurrence in enumerate(occurrences):
                if not isinstance(occurrence, dict):
                    raise FoundryError("CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID", "Each Insight occurrence must be an object.", details={"index": index}, status_code=422)
                if set(occurrence) - {"insight_id", "milestone_id", "parameters"}:
                    raise FoundryError("CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID", "Insight occurrences contain an unsupported field.", details={"index": index}, status_code=422)
                if not isinstance(occurrence.get("insight_id"), str) or not isinstance(occurrence.get("milestone_id"), str):
                    raise FoundryError("CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID", "Insight occurrences require stable insight_id and milestone_id.", details={"index": index}, status_code=422)
                key = (occurrence["insight_id"], occurrence["milestone_id"])
                if key in occurrence_keys:
                    raise FoundryError("CG1_DELEGATED_DUPLICATE_CHOICE", "An Insight occurrence is repeated for one milestone.", details={"index": index}, status_code=409)
                occurrence_keys.add(key)
                if "parameters" in occurrence and not isinstance(occurrence["parameters"], dict):
                    raise FoundryError("CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID", "Insight parameters must be an object.", details={"index": index}, status_code=422)
                if "parameters" in occurrence:
                    unsupported_parameters = sorted(set(occurrence["parameters"]) - {"ability"})
                    if unsupported_parameters:
                        raise FoundryError(
                            "CG1_INSIGHT_PARAMETER_OUT_OF_AUTHORITY",
                            "Preferred Insight parameters may contain only source-advertised typed ability choices; event metadata is forbidden.",
                            details={"index": index, "unsupported_parameters": unsupported_parameters},
                            status_code=422,
                        )
            if not isinstance(plan.get("bounded_choices"), dict) or not isinstance(plan.get("owner_descriptive_fields"), dict):
                raise FoundryError("CG1_PREFERRED_RESPONSE_SHAPE_INVALID", "The preferred delegated response has an invalid typed component.")
            unknown_bounded = sorted(set(plan["bounded_choices"]) - PREFERRED_BOUNDED_CHOICE_KEYS)
            if unknown_bounded:
                raise FoundryError("CG1_PREFERRED_RESPONSE_BOUNDED_FIELD_INVALID", "The preferred response supplied a bounded field not advertised by the request.", details={"fields": unknown_bounded})
        forbidden = sorted(k for k in plan if k in FORBIDDEN_PLANNER_FIELDS)
        if forbidden:
            raise FoundryError("CG1_PLANNER_AUTHORITY_FIELDS_FORBIDDEN", "Planner responses may not assert compiled surfaces, readiness, or artifact identities.", details={"fields": forbidden})
        return plan, raw

    @staticmethod
    def _proven_stale_server_repair_advancement_echo(
        run: dict[str, Any],
        response_text: str,
    ) -> bool:
        """Recognize only the pre-fix duplicate-repair mirror omission.

        One released deterministic repair updated both canonical ordinary
        arrays but left a redundant top-level model echo unchanged. Recovery
        is allowed only when the append-only ordinary-repair chain proves the
        exact original and corrected response bytes and the stale echo is the
        rejected array reported by that retained diagnostic.
        """
        try:
            payload = json.loads(response_text)
        except (TypeError, ValueError):
            return False
        if not isinstance(payload, dict) or "advancement_skeleton" not in payload:
            return False
        acquisition = payload.get("acquisition_intent")
        selection = payload.get("selection_intent")
        by_slot = selection.get("by_slot") if isinstance(selection, dict) else None
        current_ordinary = acquisition.get("ordinary_talent_ids") if isinstance(acquisition, dict) else None
        current_mirror = by_slot.get("advancement_skeleton") if isinstance(by_slot, dict) else None
        stale_echo = payload.get("advancement_skeleton")
        if (
            not isinstance(current_ordinary, list)
            or not current_ordinary
            or current_ordinary != current_mirror
            or stale_echo == current_ordinary
        ):
            return False
        transport = run.get("transport") if isinstance(run.get("transport"), dict) else {}
        direct_marker = transport.get("local_correction")
        direct_marker = direct_marker if isinstance(direct_marker, dict) else None
        provenance = CharacterCreationExecutionService._ordinary_repair_provenance_chain(
            run,
            response_text,
            direct_marker=direct_marker,
        )
        if not isinstance(provenance, dict):
            return False
        marker = provenance.get("marker")
        prior_response_text = provenance.get("prior_response_text")
        if not isinstance(marker, dict) or not isinstance(prior_response_text, str):
            return False
        diagnostic = marker.get("validator_diagnostic")
        details = diagnostic.get("details") if isinstance(diagnostic, dict) else None
        reported = details.get("choice_ids") if isinstance(details, dict) else None
        if not isinstance(reported, list):
            reported = details.get("ordinary_talent_ids") if isinstance(details, dict) else None
        try:
            prior_payload = json.loads(prior_response_text)
        except (TypeError, ValueError):
            return False
        prior_acquisition = prior_payload.get("acquisition_intent") if isinstance(prior_payload, dict) else None
        prior_ordinary = prior_acquisition.get("ordinary_talent_ids") if isinstance(prior_acquisition, dict) else None
        advancement_markers = provenance.get("advancement_choice_markers")
        if not isinstance(advancement_markers, list):
            advancement_markers = []
        advancement_marker = (
            advancement_markers[-1]
            if advancement_markers and isinstance(advancement_markers[-1], dict)
            else provenance.get("advancement_choice_marker")
        )
        current_hash = sha256_bytes(response_text.encode("utf-8"))
        ordinary_response_text = provenance.get("ordinary_response_text")
        ordinary_response_hash = (
            sha256_bytes(ordinary_response_text.encode("utf-8"))
            if isinstance(ordinary_response_text, str)
            else None
        )
        exact_current_or_target_intermediate = marker.get("applied_response_sha256") == current_hash
        if not exact_current_or_target_intermediate:
            exact_current_or_target_intermediate = (
                isinstance(advancement_marker, dict)
                and advancement_marker.get("target_kind") == "advancement_choice"
                and advancement_marker.get("applied_response_sha256") == current_hash
                and marker.get("applied_response_sha256") == ordinary_response_hash
            )
        return (
            marker.get("target_kind") == "ordinary_duplicate"
            and marker.get("deterministic_server_repair") is True
            and marker.get("provider_called") is False
            and marker.get("selected_ordinary_talent_ids") == current_ordinary
            and exact_current_or_target_intermediate
            and stale_echo == reported
            and stale_echo == prior_ordinary
        )

    @staticmethod
    def _server_materialized_stage1_response(
        run: dict[str, Any], intent: CanonicalSelectionIntent
    ) -> dict[str, Any]:
        """Build the closed Stage 1 response from the normalized intent.

        This is intentionally a small projection of the existing Stage 1
        contract.  It copies no planner-authored binding or hash and it never
        exposes target CL as a response choice.
        """
        request = run.get("request") or {}
        prompt = request.get("stage1_prompt") or {}
        envelope = prompt.get("envelope") or {}
        intent_doc = intent.as_dict()
        selected = intent_doc.get("selected_by_slot") or {}
        planning = intent_doc.get("planning_preferences_by_slot") or {}
        # Stage 1 records planning preferences as planning intent only.  They
        # are included in the server-owned blueprint response for transparency,
        # but the later materializer reads acquisition_intent rather than these
        # rows when creating mechanics.
        stage1_selected = {**deepcopy(planning), **deepcopy(selected)}
        owner_locks = ((request.get("delegated_choice_envelope") or {}).get("owner_locks") or {}).get("by_slot") or {}
        decisions: list[dict[str, Any]] = []
        for slot in envelope.get("decision_slots") or []:
            slot_id = slot.get("slot_id")
            if not isinstance(slot_id, str):
                continue
            values = list(stage1_selected.get(slot_id) or [])
            if not values:
                values = list(owner_locks.get(slot_id) or [])
            if values:
                decisions.append({
                    "slot_id": slot_id,
                    "state": "selected",
                    "choice_ids": values,
                })
            elif slot.get("coverage_state") == "blocked_missing_authority":
                decisions.append({
                    "slot_id": slot_id,
                    "state": "blocked_missing_authority",
                    "choice_ids": [],
                    "reason_code": slot.get("blocked_reason_code"),
                    "reason": slot.get("blocked_reason"),
                })
            elif slot.get("allow_none"):
                decisions.append({
                    "slot_id": slot_id,
                    "state": "deferred_with_reason",
                    "choice_ids": [],
                    "reason_code": "deferred_future_decision",
                    "reason": "No explicit selection was supplied; the Factory will not infer one from prose or priority order.",
                })
            else:
                decisions.append({
                    "slot_id": slot_id,
                    "state": "deferred_with_reason",
                    "choice_ids": [],
                    "reason_code": "deferred_future_decision",
                    "reason": "An exact selection is required before the Factory can compile this character.",
                })
        return {
            "protocol_version": "TianxiaFoundry.AIClipboard.Stage1.v2",
            "response_id": "cg1.materialized.stage1." + intent.intent_hash[:32],
            "prompt_id": prompt.get("prompt_id"),
            "prompt_sha256": prompt.get("prompt_sha256"),
            "project_id": envelope.get("project_id") or run.get("project_id"),
            "expected_project_revision": envelope.get("project_revision"),
            "catalog_build_id": envelope.get("catalog_build_id"),
            "content_lock_hash": envelope.get("content_lock_hash"),
            "stage_id": envelope.get("stage_id"),
            "response_payload": {
                "decisions": decisions,
                "authored_notes": [],
                "planner_rationale": "Server-materialized from validated stable-ID selection intent.",
            },
        }

    @staticmethod
    def _project_generation_route(project: dict[str, Any]) -> str:
        return next(
            (
                row.get("value")
                for row in project.get("user_locks") or []
                if isinstance(row, dict) and row.get("field") == "character_sheet.generation_route"
            ),
            "player",
        )

    @classmethod
    def _resolve_event_authority(
        cls,
        record: dict[str, Any],
        project: dict[str, Any],
        *,
        requested_kind: str | None = None,
        requested_channel: str | None = None,
        effective_cl: int | None = None,
        field: str = "stage2_record",
    ) -> tuple[str, str, dict[str, Any]]:
        """Resolve one exact kind/channel pair from the record authority.

        The project route is used only to disambiguate the established
        AI-bootstrap versus sect-trial pair when the record publishes both.
        Every selected result is still checked against the record's own
        ``allowed_kinds`` and ``allowed_channels``; no transport map grants
        authority.
        """
        auth = deepcopy(record.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {})
        allowed_kinds = [value for value in auth.get("allowed_kinds") or [] if isinstance(value, str)]
        allowed_channels = [value for value in auth.get("allowed_channels") or record.get("legality", {}).get("acquisition_channels", []) if isinstance(value, str)]
        if not allowed_kinds or not allowed_channels or auth.get("authority_complete") is not True:
            raise FoundryError(
                "CG1_AUTHORITY_SHAPE_UNRESOLVED",
                "The selected authority record does not publish a complete Stage 2 kind/channel contract.",
                details={"field": field, "record_id": record.get("record_id"), "allowed_kinds": allowed_kinds, "allowed_channels": allowed_channels},
                status_code=409,
            )
        kind = "cultivation_insight_acquisition" if requested_kind == "insight_acquisition" else requested_kind
        if kind is None:
            candidates = list(allowed_kinds)
            route = cls._project_generation_route(project)
            if route == "ai_bootstrap":
                candidates = [value for value in candidates if "ai_bootstrap" in value] or candidates
            elif route != "ai_bootstrap":
                candidates = [value for value in candidates if "sect_trial" in value] or candidates
            if len(candidates) != 1:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The installed authority permits multiple Stage 2 event kinds; choose one exact bounded kind.",
                    details={"field": field, "record_id": record.get("record_id"), "allowed_kinds": allowed_kinds, "candidates": candidates},
                    status_code=409,
                )
            kind = candidates[0]
        if kind not in allowed_kinds:
            raise FoundryError(
                "CG1_AUTHORITY_KIND_NOT_ALLOWED",
                "The requested Stage 2 kind is not advertised by the selected authority record.",
                details={"field": field, "record_id": record.get("record_id"), "requested_kind": kind, "allowed_kinds": allowed_kinds},
                status_code=409,
            )
        channel = requested_channel
        if channel is None:
            candidates = list(allowed_channels)
            preferred_tokens = {
                "ai_bootstrap": ("ai-bootstrap", "ai_bootstrap"),
                "sect_trial": ("sect-trial", "sect_trial"),
                "level_advance": ("level-advance",),
                "ability_score_change": ("level-choice",),
                "cultivation_insight_acquisition": ("cultivation-insight",),
                "typed_none": ("typed-none",),
                "creation_recorded_art_acquisition": ("factory-constructed-recorded-art",),
                "background_acquisition": ("background-selection",),
                "background_sphere_acquisition": ("background-grant",),
                "background_talent_acquisition": ("background-grant",),
                "origin_insight_acquisition": ("origin-selection",),
                "new_sphere_bonus_talent_acquisition": ("new-sphere-bonus",),
                "method_acquisition": ("method-acquisition",),
                "method_activation": ("method-activation",),
            }
            tokens = preferred_tokens.get(kind)
            if kind == "level_talent_acquisition":
                if effective_cl == 1:
                    tokens = ("ai-bootstrap-free-cl1-talent",) if cls._project_generation_route(project) == "ai_bootstrap" else ("sect-trial-cl1-level-talent",)
                else:
                    tokens = ("level-choice",)
            if tokens is None and isinstance(kind, str):
                if "ai_bootstrap" in kind:
                    tokens = preferred_tokens["ai_bootstrap"]
                elif "sect_trial" in kind:
                    tokens = preferred_tokens["sect_trial"]
            if tokens:
                matching = [value for value in candidates if any(token in value for token in tokens)]
                if matching:
                    candidates = matching
            if len(candidates) != 1:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The installed authority permits multiple Stage 2 channels; choose one exact bounded channel.",
                    details={"field": field, "record_id": record.get("record_id"), "kind": kind, "allowed_channels": allowed_channels, "candidates": candidates},
                    status_code=409,
                )
            channel = candidates[0]
        if channel not in allowed_channels:
            raise FoundryError(
                "CG1_AUTHORITY_CHANNEL_NOT_ALLOWED",
                "The requested Stage 2 channel is not advertised by the selected authority record.",
                details={"field": field, "record_id": record.get("record_id"), "kind": kind, "requested_channel": channel, "allowed_channels": allowed_channels},
                status_code=409,
            )
        return kind, channel, auth

    def _locked_records_for_project(
        self,
        project_id: str,
        *,
        authority_db: Database | None = None,
        method_version: str | None = None,
        foundation_version: str | None = None,
    ) -> dict[str, dict[str, Any]]:
        """Return the project-locked records, once per project identity per operation scope.

        One compile asks for the whole locked set many times.  Inside an
        operation scope the reconstructed set is reused while the project's
        revision, canonical hash and locked record identities are unchanged;
        every caller receives its own deep copy.  Outside a scope nothing is
        reused.
        """
        from project_store.service import _PROJECT_LOCK_SCOPE_MEMO

        memo = _PROJECT_LOCK_SCOPE_MEMO.get()
        memo_key = None
        if memo is not None:
            selected_db = authority_db if authority_db is not None else self.db
            with selected_db.connection() as conn:
                # The reconstruction depends on the owner locks and the locked
                # rows only; a Stage 2 commit bumps the revision without
                # touching either, so neither the revision nor the whole
                # document is part of the identity.
                project_row = conn.execute(
                    "SELECT json_extract(project_json, '$.user_locks') AS user_locks FROM projects WHERE project_id=?",
                    (project_id,),
                ).fetchone()
                identities = tuple(
                    (row["record_id"], row["record_hash"])
                    for row in conn.execute(
                        "SELECT record_id, record_hash FROM project_locked_records WHERE project_id=? ORDER BY record_id",
                        (project_id,),
                    )
                )
            if project_row:
                memo_key = (
                    "locked_records_for_project",
                    id(selected_db),
                    str(project_id),
                    method_version,
                    foundation_version,
                    sha256_bytes((project_row["user_locks"] or "").encode("utf-8")),
                    identities,
                )
                cached = memo.get(memo_key)
                if cached is not None:
                    # Plain-JSON sets are kept as text: parsing a fresh copy
                    # is ~4x faster than deepcopy for ~6.5k records.
                    return json.loads(cached) if isinstance(cached, str) else deepcopy(cached)
        result = self._locked_records_for_project_uncached(
            project_id,
            authority_db=authority_db,
            method_version=method_version,
            foundation_version=foundation_version,
        )
        if memo_key is not None:
            memo[memo_key] = json.dumps(result, ensure_ascii=False) if _is_plain_json(result) else deepcopy(result)
        return result

    def _locked_records_for_project_uncached(
        self,
        project_id: str,
        *,
        authority_db: Database | None = None,
        method_version: str | None = None,
        foundation_version: str | None = None,
    ) -> dict[str, dict[str, Any]]:
        """Return the exact project-locked records used by server materialization.

        The response transport is not allowed to resolve a display name or to
        consult the live catalog.  Materialization therefore reads the same
        immutable snapshot that Stage 2 will later validate.  The proof is
        performed once for this read, then every record is reconstructed through
        ProjectStore's proof-bound resolver (including authenticated Path and
        Background projections).
        An explicit authority database is used for scratch compilation so
        this proof and every subsequent lookup share one immutable local
        authority context.
        """
        selected_db = authority_db if authority_db is not None else self.db
        if selected_db is self.db:
            selected_projects = self.projects
        else:
            from project_store.service import ProjectStore
            selected_projects = ProjectStore(selected_db)
        with selected_db.connection() as conn:
            selected_projects.project_lock_proof(conn, project_id)
            project_row = conn.execute(
                "SELECT project_json FROM projects WHERE project_id=?",
                (project_id,),
            ).fetchone()
            rows = conn.execute(
                "SELECT record_id, record_hash, record_json FROM project_locked_records WHERE project_id=? ORDER BY record_id",
                (project_id,),
            ).fetchall()
            project_doc = json.loads(project_row["project_json"] or "{}") if project_row else {}
            lock_values = {
                item.get("field"): item.get("value")
                for item in project_doc.get("user_locks") or []
                if isinstance(item, dict) and isinstance(item.get("field"), str)
            }
            selected_paths = (lock_values.get("character_sheet.locked_choices") or {}).get("path_choice") or []
            selected_subpaths = (lock_values.get("character_sheet.locked_choices") or {}).get("subpath_choice") or []
            selected_foundations = (lock_values.get("character_sheet.locked_choices") or {}).get("foundation_choice") or []
            authority = NonSphereAuthorityService(selected_db)
            selected_feature_ids = {
                feature.get("canonical_id")
                for path_id in selected_paths
                for feature in (authority.path_profiles.get(path_id) or {}).get("features") or []
                if isinstance(feature, dict) and isinstance(feature.get("canonical_id"), str)
            }
            access_plan = lock_values.get("character_sheet.method_access_plan")
            access_method_id = access_plan.get("method_id") if isinstance(access_plan, dict) else None
            result: dict[str, dict[str, Any]] = {}
            # All project-specific non-Sphere records below are resolved through
            # the proved immutable snapshot.  In particular, do not rebuild a
            # selected Subpath directly from the live registry: its ownership
            # and feature progression are part of the project's frozen
            # authority boundary.
            # Exact initial Methods are a separate authenticated authority
            # surface rather than HF2 pack members.  Resolve only the Method
            # named by the server-created access plan; the proof-bound resolver
            # checks that plan's registry and record commitments before exposing
            # the typed Stage 2 projection.
            if isinstance(access_method_id, str):
                method_record = selected_projects._resolve_locked_record_after_proof(
                    conn,
                    project_id,
                    access_method_id,
                    authority_service=authority,
                    method_version=method_version,
                )
                if method_record is not None:
                    result[access_method_id] = method_record
            # Selected Subpaths are explicit owner choices.  They are resolved
            # through the proved project snapshot below, even when a historical
            # project did not persist the ordinary catalog row in the current
            # executable set.  A missing row remains fail-closed.
            for row in rows:
                record_id = row["record_id"]
                if record_id.startswith("tianxia.path.") and ".feature." in record_id:
                    # Component IDs in the source index are evidence, not
                    # executable catalog records.  Only selected top-level
                    # feature authorities enter the materialization map.
                    if record_id not in selected_feature_ids:
                        continue
                    path_id = record_id.split(".feature.", 1)[0]
                    record = authority.project_locked_path_feature_catalog_record(path_id, record_id)
                elif record_id.startswith("tianxia.path."):
                    if record_id not in selected_paths:
                        continue
                    record = authority.project_locked_path_catalog_record(record_id)
                else:
                    try:
                        record = selected_projects._resolve_locked_record_after_proof(
                            conn,
                            project_id,
                            record_id,
                            authority_service=authority,
                            method_version=method_version,
                            foundation_version=foundation_version,
                            prefetched_row=row,
                        )
                    except FoundryError as exc:
                        # P2A progression may name source-text component IDs
                        # that are evidence inside a feature, not executable
                        # Stage 2 records.  They remain in the immutable
                        # snapshot but are intentionally absent from the
                        # materialization map.
                        if exc.code != "NS1R_PATH_FEATURE_ID_UNKNOWN":
                            raise
                        record = None
                if record is not None:
                    result[record_id] = record
                    continue
                # No live-catalog fallback is permitted for a missing locked
                # record.  The caller will receive the normal bounded,
                # fail-closed missing-authority diagnostic.
            # Path features may not be persisted as ordinary catalog rows. Add
            # the complete selected top-level feature set from the authenticated
            # P2A source once, after the immutable project proof above.
            for path_id in selected_paths:
                profile = authority.path_profiles.get(path_id) or {}
                for feature in profile.get("features") or []:
                    feature_id = feature.get("canonical_id") if isinstance(feature, dict) else None
                    if not isinstance(feature_id, str):
                        continue
                    record = authority.project_locked_path_feature_catalog_record(path_id, feature_id)
                    if isinstance(record, dict):
                        result[feature_id] = record
            # Exact selected Subpaths/Traditions are owner-bound records.  The
            # resolver must have obtained each one from this project's proved
            # snapshot; if a legacy row is absent it remains unresolved rather
            # than being rebuilt from the live registry.
            for subpath_id in selected_subpaths:
                record = selected_projects._resolve_locked_record_after_proof(
                    conn,
                    project_id,
                    subpath_id,
                    authority_service=authority,
                )
                if record is not None:
                    result[subpath_id] = record
            return result

    def _locked_records_for_project_ids(
        self,
        project_id: str,
        record_ids: Collection[str],
    ) -> dict[str, dict[str, Any]]:
        """Resolve a bounded subset after proving the complete project lock once."""
        requested = sorted({
            record_id
            for record_id in record_ids
            if isinstance(record_id, str) and record_id
        })
        with self.db.connection() as conn:
            self.projects.project_lock_proof(conn, project_id)
            if not requested:
                return {}
            authority = NonSphereAuthorityService(self.db)
            result: dict[str, dict[str, Any]] = {}
            for record_id in requested:
                try:
                    record = self.projects._resolve_locked_record_after_proof(
                        conn,
                        project_id,
                        record_id,
                        authority_service=authority,
                    )
                except FoundryError as exc:
                    if exc.code != "NS1R_PATH_FEATURE_ID_UNKNOWN":
                        raise
                    record = None
                if record is not None:
                    result[record_id] = record
            return result

    @staticmethod
    def _materialization_bounded_choices(plan: dict[str, Any]) -> dict[str, Any]:
        bounded: dict[str, Any] = {}
        for key in ("bounded_choices", "bounded_choice", "choice_parameters"):
            value = plan.get(key)
            if isinstance(value, dict):
                bounded.update(deepcopy(value))
        selection = plan.get("selection_intent")
        if isinstance(selection, dict) and isinstance(selection.get("bounded_choices"), dict):
            bounded.update(deepcopy(selection["bounded_choices"]))
        return bounded

    @staticmethod
    def _selection_values(intent: CanonicalSelectionIntent, slot_id: str, owner_locks: dict[str, Any]) -> list[str]:
        selected = intent.as_dict().get("selected_by_slot") or {}
        values = selected.get(slot_id)
        if not values:
            values = owner_locks.get(slot_id)
        if isinstance(values, str):
            return [values]
        return [value for value in values or [] if isinstance(value, str) and value]

    @staticmethod
    def _frozen_background_package_linkage(
        delegated_envelope: dict[str, Any],
    ) -> dict[str, list[dict[str, Any]]]:
        """Return only the package linkage sealed by the delegated envelope.

        Background choice rows carry this contract in their typed authority.
        A top-level copy is accepted solely for small compatibility fixtures;
        neither form is resolved through the live catalog.
        """
        if not isinstance(delegated_envelope, dict):
            return {}
        typed = delegated_envelope.get("typed_choice_authority_by_slot")
        if isinstance(typed, dict):
            background_authority = typed.get("background_choice")
            if isinstance(background_authority, dict):
                linkage = background_authority.get("background_package_linkage")
                if isinstance(linkage, dict):
                    return linkage
                contract = background_authority.get("authority_contract")
                if isinstance(contract, dict):
                    linkage = contract.get("background_package_linkage")
                    if isinstance(linkage, dict):
                        return linkage
        linkage = delegated_envelope.get("background_package_linkage")
        return linkage if isinstance(linkage, dict) else {}

    @staticmethod
    def _require_frozen_background_package_triplet(
        delegated_envelope: dict[str, Any],
        *,
        background_id: str,
        sphere_choice_id: str,
        talent_choice_id: str,
    ) -> None:
        """Require both selected Background dependent choices from one package."""

        linkage = CharacterCreationExecutionService._frozen_background_package_linkage(
            delegated_envelope
        )
        packages = linkage.get(background_id)
        if not isinstance(packages, list):
            packages = []
        matching = [
            package
            for package in packages
            if isinstance(package, dict)
            and package.get("background_sphere_choice_id") == sphere_choice_id
            and package.get("background_talent_choice_id") == talent_choice_id
        ]
        if len(matching) != 1:
            raise FoundryError(
                "CG1_DELEGATED_BACKGROUND_PACKAGE_MISMATCH",
                "The selected Background Sphere and Talent must come from one exact sealed package.",
                details={
                    "background_id": background_id,
                    "background_sphere_choice_id": sphere_choice_id,
                    "background_talent_choice_id": talent_choice_id,
                },
                status_code=409,
            )

    @staticmethod
    def _canonicalize_frozen_background_choice_id(
        delegated_envelope: dict[str, Any],
        slot_id: str,
        choice_id: str,
        *,
        background_id: str | None = None,
    ) -> str:
        """Canonicalize one legacy Background ID using frozen proof only.

        The historical provider response used ``background.sphere`` and
        ``background.talent`` separators while the current frozen envelope
        uses ``background_sphere`` and ``background_talent``.  The separator
        migration is safe only when the resulting ID is simultaneously an
        allowed frozen choice, an exact frozen choice row, and the uniquely
        linked choice for the selected frozen Background package.  No catalog
        lookup or display-name matching is permitted here.
        """
        background_slots = {
            "background_sphere_choice": (
                "tianxia.background_sphere.",
                "tianxia.background.sphere.",
                "background_sphere_choice_id",
            ),
            "background_talent_choice": (
                "tianxia.background_talent.",
                "tianxia.background.talent.",
                "background_talent_choice_id",
            ),
        }
        if slot_id not in background_slots or not isinstance(choice_id, str) or not choice_id:
            return choice_id
        canonical_prefix, legacy_prefix, package_key = background_slots[slot_id]

        allowed_by_slot = delegated_envelope.get("allowed_choice_ids_by_slot")
        choices_by_slot = delegated_envelope.get("choices_by_slot")
        allowed = {
            value
            for value in (allowed_by_slot.get(slot_id) if isinstance(allowed_by_slot, dict) else []) or []
            if isinstance(value, str) and value
        }
        choices = choices_by_slot.get(slot_id) if isinstance(choices_by_slot, dict) else None
        choices = choices if isinstance(choices, dict) else {}

        def exact_choice_row(candidate_id: str) -> dict[str, Any] | None:
            row = choices.get(candidate_id)
            if not isinstance(row, dict) or candidate_id not in allowed:
                return None
            for identity_key in ("choice_id", "id"):
                identity = row.get(identity_key)
                if identity is not None and identity != candidate_id:
                    return None
            return row

        # An exact frozen ID needs no migration proof.  It is still required
        # to have both halves of the frozen closed-world projection.
        if exact_choice_row(choice_id) is not None:
            return choice_id
        # Do not reinterpret an ID that the frozen projection explicitly
        # carries but does not allow (or carries without a matching row).  Such
        # a value is an unavailable/provenance entry, not a legacy alias.
        if choice_id in allowed or isinstance(choices.get(choice_id), dict):
            raise FoundryError(
                "CG1_DELEGATED_BACKGROUND_ALIAS_UNPROVEN",
                "The Background choice ID is present but not an allowed exact frozen choice.",
                details={
                    "slot_id": slot_id,
                    "choice_id": choice_id,
                    "background_id": background_id,
                    "candidates": [],
                    "offered_choice_ids": sorted(allowed),
                },
                status_code=409,
            )

        linkage = CharacterCreationExecutionService._frozen_background_package_linkage(
            delegated_envelope
        )
        if not linkage:
            raise FoundryError(
                "CG1_DELEGATED_BACKGROUND_ALIAS_UNPROVEN",
                "The Background choice ID is not an exact frozen choice and has no sealed package-alias proof.",
                details={"slot_id": slot_id, "choice_id": choice_id, "background_id": background_id, "candidates": []},
                status_code=409,
            )

        package_rows: list[dict[str, Any]] = []
        if isinstance(background_id, str) and background_id:
            selected_packages = linkage.get(background_id)
            if isinstance(selected_packages, list):
                package_rows = [row for row in selected_packages if isinstance(row, dict)]
        elif background_id is None:
            # This path is useful only for owner-lock compatibility where the
            # selected Background is not in the canonical intent.  A candidate
            # still has to occur in exactly one complete frozen package.
            for packages in linkage.values():
                if isinstance(packages, list):
                    package_rows.extend(row for row in packages if isinstance(row, dict))

        occurrences: dict[str, int] = {}
        for package in package_rows:
            if (
                type(package.get("package_index")) is not int
                or not isinstance(package.get("sphere_record_id"), str)
                or not isinstance(package.get("talent_record_id"), str)
            ):
                continue
            candidate = package.get(package_key)
            if not isinstance(candidate, str) or exact_choice_row(candidate) is None:
                continue
            occurrences[candidate] = occurrences.get(candidate, 0) + 1

        def aliases_for(candidate_id: str, row: dict[str, Any]) -> set[str]:
            aliases: set[str] = set()
            if candidate_id.startswith(canonical_prefix):
                aliases.add(legacy_prefix + candidate_id[len(canonical_prefix):])
            # A future frozen envelope may publish an explicit migration alias;
            # accept it only as data in the sealed row, never from a catalog.
            for alias_key in ("aliases", "legacy_aliases", "legacy_ids", "source_aliases", "alias_ids"):
                raw_aliases = row.get(alias_key)
                if isinstance(raw_aliases, str):
                    raw_aliases = [raw_aliases]
                if isinstance(raw_aliases, list):
                    aliases.update(value for value in raw_aliases if isinstance(value, str) and value)
            return aliases

        candidates = {
            candidate
            for candidate, occurrence_count in occurrences.items()
            if occurrence_count == 1
            and choice_id in aliases_for(candidate, exact_choice_row(candidate) or {})
        }
        if len(candidates) != 1:
            code = (
                "CG1_DELEGATED_BACKGROUND_ALIAS_AMBIGUOUS"
                if len(candidates) > 1
                else "CG1_DELEGATED_BACKGROUND_ALIAS_UNPROVEN"
            )
            raise FoundryError(
                code,
                "The Background choice alias does not resolve to exactly one offered frozen package choice.",
                details={
                    "slot_id": slot_id,
                    "choice_id": choice_id,
                    "background_id": background_id,
                    "candidates": sorted(candidates),
                    "offered_choice_ids": sorted(allowed),
                },
                status_code=409,
            )
        return next(iter(candidates))

    @staticmethod
    def _canonicalize_frozen_background_intent(
        intent: CanonicalSelectionIntent,
        delegated_envelope: dict[str, Any],
    ) -> CanonicalSelectionIntent:
        """Return a rehashed intent with only proven Background aliases fixed."""
        document = intent.as_dict()
        selected = document.get("selected_by_slot")
        if not isinstance(selected, dict):
            return intent
        background_values = selected.get("background_choice")
        if isinstance(background_values, str):
            background_values = [background_values]
        background_values = [
            value for value in background_values or [] if isinstance(value, str) and value
        ]
        background_id = background_values[0] if len(background_values) == 1 else None
        changed = False
        canonical_selected = deepcopy(selected)
        for slot_id in ("background_sphere_choice", "background_talent_choice"):
            raw_values = selected.get(slot_id)
            if isinstance(raw_values, str):
                raw_values = [raw_values]
            if not isinstance(raw_values, list):
                continue
            canonical_values = [
                CharacterCreationExecutionService._canonicalize_frozen_background_choice_id(
                    delegated_envelope,
                    slot_id,
                    value,
                    background_id=background_id,
                )
                for value in raw_values
                if isinstance(value, str) and value
            ]
            if canonical_values != raw_values:
                changed = True
                canonical_selected[slot_id] = canonical_values
        if not changed:
            return intent
        unsigned = deepcopy(document)
        unsigned["selected_by_slot"] = canonical_selected
        unsigned.pop("intent_sha256", None)
        return CanonicalSelectionIntent.from_document(
            {**unsigned, "intent_sha256": sha256_json(unsigned)}
        )

    @staticmethod
    def _manual_collection_authority_from_bundles(
        bundles: list[dict[str, Any]],
    ) -> dict[str, Any]:
        """Project server-built Manual bundles into canonical possession authority."""
        from character_creation.response_materialization import canonical_semantic_acquisition
        from character_creation.constructed_arts.manual import (
            MANUAL_COLLECTION_POLICY_ID,
            MANUAL_COLLECTION_SCHEMA,
        )

        manuals: list[dict[str, Any]] = []
        for index, bundle in enumerate(bundles):
            manual = bundle.get("manual") if isinstance(bundle, Mapping) else None
            collection = manual.get("collection") if isinstance(manual, Mapping) else None
            if not isinstance(collection, Mapping):
                raise FoundryError(
                    "CG1_MANUAL_COLLECTION_AUTHORITY_INVALID",
                    "A server-built Manual is missing its persisted possession binding.",
                    details={"index": index},
                    status_code=409,
                )
            manuals.append({
                "collection_id": collection.get("collection_id"),
                "content_record_ids": list(collection.get("content_record_ids") or []),
                "content_record_bindings": deepcopy(collection.get("content_record_bindings") or []),
            })
        authority = {
            "schema": MANUAL_COLLECTION_SCHEMA,
            "policy_id": MANUAL_COLLECTION_POLICY_ID,
            "roll": deepcopy((bundles[0].get("manual") or {}).get("collection", {}).get("roll") if bundles else None),
            "manuals": manuals,
        }
        return canonical_semantic_acquisition({"manual_collection": authority})["manual_collection"]

    def _server_manual_collection_intent(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        intent: CanonicalSelectionIntent,
        *,
        target_cl: int,
    ) -> CanonicalSelectionIntent:
        """Inject the server-owned new-request Manual collection before acceptance."""
        from character_creation.response_materialization import canonical_semantic_acquisition
        from character_creation.constructed_arts.manual import (
            MANUAL_COLLECTION_POLICY_ID,
            MANUAL_COLLECTION_SCHEMA,
            roll_manual_collection_count,
            validate_manual_collection_roll,
        )

        request = run.get("request") if isinstance(run, dict) else None
        server_authority = request.get("server_owned_authority") if isinstance(request, Mapping) else None
        marker = server_authority.get("manual_collection") if isinstance(server_authority, Mapping) else None
        if not isinstance(marker, Mapping):
            # Requests created before the versioned server policy retain their
            # sealed one-Manual behavior and are never silently migrated.
            return intent
        authority_version = marker.get("authority_version")
        nonce = marker.get("nonce")
        if (
            marker.get("schema") != MANUAL_COLLECTION_SCHEMA
            or marker.get("policy_id") != MANUAL_COLLECTION_POLICY_ID
            or authority_version not in {"server_owned_pre_provider.v1", "server_owned_pre_provider.v2"}
            or not isinstance(marker.get("seed"), str)
            or not marker.get("seed")
            or (
                authority_version == "server_owned_pre_provider.v2"
                and (
                    not isinstance(nonce, str)
                    or len(nonce) < 32
                    or not nonce.strip()
                )
            )
        ):
            raise FoundryError(
                "CG1_MANUAL_COLLECTION_AUTHORITY_INVALID",
                "The new-request Manual collection authority is not the exact server-owned versioned policy.",
                status_code=409,
            )
        if authority_version == "server_owned_pre_provider.v2":
            expected_seed = "cg1.manual.collection." + sha256_json({
                "policy_id": MANUAL_COLLECTION_POLICY_ID,
                "nonce": nonce,
            })
            if marker.get("seed") != expected_seed:
                raise FoundryError(
                    "CG1_MANUAL_COLLECTION_NONCE_MISMATCH",
                    "The server-owned Manual collection seed no longer derives from its persisted nonce.",
                    status_code=409,
                )
        expected_roll = roll_manual_collection_count(target_cl, seed=marker["seed"])
        try:
            stored_roll = validate_manual_collection_roll(marker.get("roll"), cl=target_cl)
        except FoundryError as exc:
            raise FoundryError(
                "CG1_MANUAL_COLLECTION_AUTHORITY_INVALID",
                "The new-request Manual collection roll is malformed.",
                details={"cause": exc.code},
                status_code=409,
            ) from exc
        if stored_roll != expected_roll:
            raise FoundryError(
                "CG1_MANUAL_COLLECTION_ROLL_MISMATCH",
                "The server-owned Manual collection roll no longer rederives from its bound seed.",
                details={"expected": expected_roll, "actual": stored_roll},
                status_code=409,
            )

        # First derive the legal base rows without constructing any Manual.
        # This gives the server the selected/locked source context after the
        # provider has made its ordinary legal choices, without exposing the
        # internal collection manifest to the provider.
        base_rows = self._derive_stage2_rows_from_frozen_authority(
            run,
            project,
            intent,
            include_manual_collection=False,
        )
        records = self._locked_records_for_run(run)
        # Derive the server-owned collection independently of any provider
        # supplied manifest.  Otherwise the explicit branch would reuse a
        # forged collection_id as the construction input and the subsequent
        # equality check could only compare the forged value with itself.
        construction_intent_doc = intent.as_dict()
        construction_acquisition = construction_intent_doc.get("acquisition_intent")
        if isinstance(construction_acquisition, Mapping):
            construction_acquisition = deepcopy(construction_acquisition)
            construction_acquisition.pop("manual_collection", None)
            construction_intent_doc["acquisition_intent"] = construction_acquisition
        bundles, _records, _roll = self._manual_collection_constructions(
            run,
            project,
            construction_intent_doc,
            base_rows,
            records,
            target_cl,
            intent_hash=intent.intent_hash,
            persisted_roll=stored_roll,
        )
        generated = self._manual_collection_authority_from_bundles(bundles)

        document = intent.as_dict()
        acquisition = document.get("acquisition_intent")
        acquisition = deepcopy(acquisition) if isinstance(acquisition, Mapping) else {}
        supplied = acquisition.get("manual_collection")
        if supplied is not None:
            try:
                supplied_canonical = canonical_semantic_acquisition({"manual_collection": supplied})["manual_collection"]
            except FoundryError as exc:
                raise FoundryError(
                    "CG1_MANUAL_COLLECTION_AUTHORITY_TAMPERED",
                    "The provider supplied a malformed Manual collection authority where the server must derive it.",
                    details={"cause": exc.code},
                    status_code=409,
                ) from exc
            if canonical_json(supplied_canonical) != canonical_json(generated):
                raise FoundryError(
                    "CG1_MANUAL_COLLECTION_AUTHORITY_TAMPERED",
                    "The provider-supplied Manual collection differs from the server-derived source bindings.",
                    status_code=409,
                )
        acquisition["manual_collection"] = generated
        document["acquisition_intent"] = acquisition
        document.pop("intent_sha256", None)
        return CanonicalSelectionIntent.from_document(
            {**document, "intent_sha256": sha256_json(document)}
        )

    @staticmethod
    def _delegated_path_ids_from_canonical_intent(
        intent: CanonicalSelectionIntent | dict[str, Any] | None,
    ) -> tuple[str, ...]:
        """Project only normalized Path IDs into the private Stage 2 scope."""
        if isinstance(intent, CanonicalSelectionIntent):
            document = intent.as_dict()
        elif isinstance(intent, dict):
            document = intent
        else:
            return ()
        selected = document.get("selected_by_slot") or {}
        values = selected.get("path_choice") if isinstance(selected, dict) else None
        if isinstance(values, str):
            values = [values]
        return tuple(
            value
            for value in values or []
            if isinstance(value, str) and value.startswith("tianxia.path.") and ".feature." not in value
        )

    @staticmethod
    def _insert_stage2_row_at_effective_cl(
        rows: list[dict[str, Any]],
        entry: dict[str, Any],
    ) -> None:
        """Insert one constructed event at its causal effective CL.

        Existing Stage 2 rows are already in source/causal order.  A
        constructed event is inserted after every existing row at the same
        CL and before the first later effective-CL row, preserving the order
        of all pre-existing rows and of constructed rows sharing a CL.
        """
        effective_cl = entry.get("effective_cl")
        if type(effective_cl) is not int:
            raise FoundryError(
                "CG1_STAGE2_DERIVATION_INVALID",
                "A constructed Stage 2 row must carry an integer effective CL.",
                details={"row": entry},
                status_code=409,
            )
        boundary = next(
            (
                index
                for index, existing in enumerate(rows)
                if type(existing.get("effective_cl")) is int
                and existing["effective_cl"] > effective_cl
            ),
            len(rows),
        )
        rows.insert(boundary, entry)

    @staticmethod
    def _unique_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        seen: set[tuple[Any, ...]] = set()
        result: list[dict[str, Any]] = []
        for row in rows:
            key = (
                row.get("kind"),
                row.get("record_id"),
                row.get("effective_cl"),
                row.get("acquisition_channel"),
                sha256_json(row.get("parameters") or {}),
            )
            if key in seen:
                raise FoundryError(
                    "CG1_STAGE2_DERIVATION_DUPLICATE",
                    "The frozen authority produced a duplicate Stage 2 row; compilation is not allowed to silently deduplicate it.",
                    details={"row": row},
                    status_code=409,
                )
            seen.add(key)
            result.append(row)
        return result

    def _add_delegated_path_records(
        self,
        run: dict[str, Any],
        records: dict[str, dict[str, Any]],
        path_ids: list[str],
        *,
        db: Database,
        store: Any,
    ) -> None:
        """Add the exact authority records of delegated Paths and their features."""
        authorized = frozenset(path_ids)
        path_authority = NonSphereAuthorityService(db)
        for path_id in path_ids:
            with db.connection() as conn:
                store.project_lock_proof(conn, run["project_id"])
                path_record = store._resolve_locked_record_after_proof(
                    conn,
                    run["project_id"],
                    path_id,
                    authority_service=path_authority,
                    authorized_delegated_path_ids=authorized,
                )
            if path_record is None:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The frozen project does not contain the exact authority needed to materialize this Path.",
                    details={"field": "path_choice", "record_id": path_id},
                    status_code=409,
                )
            if isinstance(path_record, dict):
                records[path_id] = path_record
            profile = path_authority.path_profiles.get(path_id) or {}
            for feature in profile.get("features") or []:
                feature_id = feature.get("canonical_id") if isinstance(feature, dict) else None
                if isinstance(feature_id, str):
                    feature_record = path_authority.project_locked_path_feature_catalog_record(path_id, feature_id)
                    if isinstance(feature_record, dict):
                        records[feature_id] = feature_record

    def _locked_records_for_run(self, run: dict[str, Any], *, authority_db: Database | None = None) -> dict[str, dict[str, Any]]:
        """Select only explicit frozen versions; retain historical call semantics."""
        request = run.get("request") or {}
        kwargs: dict[str, Any] = {}
        for key, version in (
            ("method_version", initial_method_record_version(request)),
            ("foundation_version", initial_foundation_record_version(request)),
        ):
            if version is not None:
                kwargs[key] = version
        if authority_db is not None:
            kwargs["authority_db"] = authority_db
        return self._locked_records_for_project(run["project_id"], **kwargs)

    def _derive_stage2_rows_from_frozen_authority(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        intent: CanonicalSelectionIntent,
        *,
        include_manual_collection: bool = True,
    ) -> list[dict[str, Any]]:
        """Build the closed Stage 2 event request from stable-ID intent.

        This is the preferred REC1-P1CR3 path.  The external response supplies
        stable selections and genuinely bounded values; all event kinds,
        channels, level timing, automatic grants, and bookkeeping are selected
        here from the frozen project snapshot.  A missing non-derivable value is
        reported as an owner decision rather than guessed.
        """
        records = self._locked_records_for_run(run)
        intent_doc = intent.as_dict()
        # A delegated Path is selected in the frozen Stage 1 envelope rather
        # than necessarily being an owner lock on the project.  Reconstruct its
        # exact P2A source-bound authority here; never resolve a display label
        # through the live catalog or promote a planning priority into a Path.
        selected_path_ids = list(self._delegated_path_ids_from_canonical_intent(intent))
        delegated_envelope = ((run.get("request") or {}).get("delegated_choice_envelope") or {})
        allowed_paths = (
            (delegated_envelope.get("allowed_choice_ids_by_slot") or {}).get("path_choice")
            if isinstance(delegated_envelope, dict)
            else None
        )
        path_choices = (
            (delegated_envelope.get("choices_by_slot") or {}).get("path_choice")
            if isinstance(delegated_envelope, dict)
            else None
        )
        allowed_paths = allowed_paths if isinstance(allowed_paths, list) else []
        path_choices = path_choices if isinstance(path_choices, dict) else {}
        out_of_envelope = [
            path_id
            for path_id in selected_path_ids
            if path_id not in allowed_paths or path_id not in path_choices
        ]
        if out_of_envelope:
            raise FoundryError(
                "CG1_DELEGATED_CHOICE_OUT_OF_ENVELOPE",
                "The selected Path is not present in the frozen delegated Path envelope.",
                details={
                    "field": "path_choice",
                    "choice_ids": out_of_envelope,
                    "allowed_choice_ids": list(allowed_paths),
                },
                status_code=409,
            )
        authorized_delegated_path_ids = frozenset(selected_path_ids)
        path_authority = NonSphereAuthorityService(self.db)
        for path_id in selected_path_ids:
            with self.db.connection() as conn:
                self.projects.project_lock_proof(conn, run["project_id"])
                path_record = self.projects._resolve_locked_record_after_proof(
                    conn,
                    run["project_id"],
                    path_id,
                    authority_service=path_authority,
                    authorized_delegated_path_ids=authorized_delegated_path_ids,
                )
            if path_record is None:
                # A delegated Path is not necessarily an owner lock, but it is
                # still required to be authenticated by the exact project lock
                # boundary before it can enter materialization.
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The frozen project does not contain the exact authority needed to materialize this Path.",
                    details={"field": "path_choice", "record_id": path_id},
                    status_code=409,
                )
            if isinstance(path_record, dict):
                records[path_id] = path_record
            profile = path_authority.path_profiles.get(path_id) or {}
            for feature in profile.get("features") or []:
                feature_id = feature.get("canonical_id") if isinstance(feature, dict) else None
                if isinstance(feature_id, str):
                    feature_record = path_authority.project_locked_path_feature_catalog_record(path_id, feature_id)
                    if isinstance(feature_record, dict):
                        records[feature_id] = feature_record
        locks = {
            row.get("field"): row.get("value")
            for row in project.get("user_locks") or []
            if isinstance(row, dict) and isinstance(row.get("field"), str)
        }
        locked_choices = locks.get("character_sheet.locked_choices") or {}
        bounded = deepcopy(intent_doc.get("bounded_choices") or {})
        owner_locks = ((run.get("request") or {}).get("delegated_choice_envelope") or {}).get("owner_locks") or {}
        owner_by_slot = owner_locks.get("by_slot") or {}

        def values(slot_id: str, *, background_id: str | None = None) -> list[str]:
            selected = self._selection_values(intent, slot_id, locked_choices)
            if not selected:
                selected = [value for value in owner_by_slot.get(slot_id) or [] if isinstance(value, str)]
            if slot_id in {"background_sphere_choice", "background_talent_choice"}:
                if background_id is None:
                    background_values = self._selection_values(
                        intent,
                        "background_choice",
                        locked_choices,
                    )
                    if not background_values:
                        background_values = [
                            value
                            for value in owner_by_slot.get("background_choice") or []
                            if isinstance(value, str)
                        ]
                    background_id = background_values[0] if len(background_values) == 1 else None
                selected = [
                    self._canonicalize_frozen_background_choice_id(
                        delegated_envelope,
                        slot_id,
                        value,
                        background_id=background_id,
                    )
                    for value in selected
                ]
            return selected

        def require_record(record_id: str, field: str) -> dict[str, Any]:
            record = records.get(record_id)
            if record is None:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The frozen project does not contain the exact authority needed to materialize this choice.",
                    details={"field": field, "record_id": record_id},
                    status_code=409,
                )
            return record

        def path_feature_kind(record: dict[str, Any]) -> str:
            return str(
                (record.get("path_feature") or {}).get("feature_kind")
                or (record.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {}).get("feature_kind")
                or ""
            )

        def row(kind: str | None, effective_cl: int, record_id: str, *, parameters: dict[str, Any] | None = None) -> dict[str, Any]:
            record = require_record(record_id, "stage2_record_id")
            requested_channel = {
                CREATION_TRAINING_SPHERE_KIND: CREATION_TRAINING_SPHERE_CHANNEL,
                CREATION_TRAINING_TALENT_KIND: CREATION_TRAINING_TALENT_CHANNEL,
            }.get(kind)
            resolved_kind, channel, _authority = self._resolve_event_authority(
                record,
                project,
                requested_kind=kind,
                requested_channel=requested_channel,
                effective_cl=effective_cl,
                field="stage2_record",
            )
            return {
                "kind": resolved_kind,
                "effective_cl": effective_cl,
                "record_id": record_id,
                "acquisition_channel": channel,
                "parameters": deepcopy(parameters or {}),
            }

        scores = bounded.get("ability_scores") or bounded.get("point_buy_scores")
        if not isinstance(scores, dict):
            point_buy = locks.get("character_sheet.ability_point_buy") or {}
            fixed = point_buy.get("fixed_scores") if isinstance(point_buy, dict) else None
            auto = point_buy.get("auto_abilities") if isinstance(point_buy, dict) else None
            if isinstance(fixed, dict) and not auto and len(fixed) == 6:
                scores = fixed
        if not isinstance(scores, dict) or set(scores) != {"STR", "DEX", "CON", "INT", "WIS", "CHA"}:
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "Choose exact six ability scores before the Factory can materialize the starting-state event.",
                details={"field": "bounded_choices.ability_scores", "required_abilities": ["STR", "DEX", "CON", "INT", "WIS", "CHA"]},
                status_code=409,
            )
        if any(type(value) is not int for value in scores.values()):
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "Starting ability scores must be exact integers before advancement changes can be applied.",
                details={"field": "bounded_choices.ability_scores"},
                status_code=409,
            )
        # Keep a server-owned running score state for the deterministic event
        # order below.  The Stage 2 rows intentionally carry only deltas, so a
        # cap check against the original point-buy map would miss cumulative
        # Background, Insight, and earlier milestone changes.
        resolved_scores = {ability: scores[ability] for ability in scores}

        target_cl = frozen_owner_target_cl(project)
        path_ids = values("path_choice")
        if not path_ids:
            raise FoundryError(
                "CG1_DELEGATED_PATH_REQUIRED",
                "Choose at least one advancing Path before the Factory can materialize Stage 2.",
                status_code=409,
            )
        subpath_ids = values("subpath_choice")
        for subpath_id in subpath_ids:
            if subpath_id not in records:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The frozen project does not contain the exact authority needed to materialize this Subpath or Tradition.",
                    details={"field": "subpath_choice", "record_id": subpath_id},
                    status_code=409,
                )
        subpath_by_path: dict[str, str] = {}
        for subpath_id in subpath_ids:
            subpath_record = require_record(subpath_id, "subpath_choice")
            subpath_authority = (
                subpath_record.get("compatibility", {}).get("factory", {}).get("stage2_authority")
                or {}
            )
            owner_path = subpath_record.get("owning_path_id")
            if not isinstance(owner_path, str) or owner_path not in path_ids:
                raise FoundryError(
                    "CG1_PATH_SUBPATH_MISMATCH",
                    "The selected Subpath or Tradition is not bound to one selected Path in frozen authority.",
                    details={
                        "subpath_id": subpath_id,
                        "selected_path_ids": path_ids,
                        "owning_path_id": owner_path,
                        "stage2_parent_path_id": subpath_authority.get("parent_path_id"),
                    },
                    status_code=409,
                )
            if subpath_record.get("parent_path_id") != owner_path:
                raise FoundryError(
                    "CG1_PATH_SUBPATH_MISMATCH",
                    "The frozen Subpath parent Path does not match its explicit owning Path.",
                    details={
                        "subpath_id": subpath_id,
                        "owning_path_id": owner_path,
                        "parent_path_id": subpath_record.get("parent_path_id"),
                    },
                    status_code=409,
                )
            if subpath_authority.get("owning_path_id") not in {None, owner_path} or subpath_authority.get("parent_path_id") not in {None, owner_path}:
                raise FoundryError(
                    "CG1_PATH_SUBPATH_MISMATCH",
                    "The frozen Subpath Stage 2 ownership does not match its explicit owning Path.",
                    details={
                        "subpath_id": subpath_id,
                        "owning_path_id": owner_path,
                        "stage2_owning_path_id": subpath_authority.get("owning_path_id"),
                        "stage2_parent_path_id": subpath_authority.get("parent_path_id"),
                    },
                    status_code=409,
                )
            if owner_path in subpath_by_path:
                raise FoundryError(
                    "CG1_MULTIPLE_SUBPATHS_FOR_ONE_PATH",
                    "Each selected Path may have only one current Subpath or Tradition.",
                    details={"path_id": owner_path, "choice_ids": [subpath_by_path[owner_path], subpath_id]},
                    status_code=409,
                )
            subpath_by_path[owner_path] = subpath_id
        background_ids = values("background_choice")
        selected_background_id = background_ids[0] if len(background_ids) == 1 else None
        background_sphere_ids = values(
            "background_sphere_choice",
            background_id=selected_background_id,
        )
        background_talent_ids = values(
            "background_talent_choice",
            background_id=selected_background_id,
        )
        origin_ids = values("origin_insight_choice")
        if not background_ids or not background_sphere_ids or not background_talent_ids or not origin_ids:
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "The complete character requires the exact Background, Background Sphere, Background Talent, and Origin Insight choices.",
                details={
                    "missing_slots": [
                        slot for slot, selected in (
                            ("background_choice", background_ids),
                            ("background_sphere_choice", background_sphere_ids),
                            ("background_talent_choice", background_talent_ids),
                            ("origin_insight_choice", origin_ids),
                        ) if not selected
                    ]
                },
                status_code=409,
            )
        if len(background_ids) != 1 or len(background_sphere_ids) != 1 or len(background_talent_ids) != 1:
            raise FoundryError(
                "CG1_DELEGATED_BACKGROUND_PACKAGE_MISMATCH",
                "The complete character requires one exact sealed Background package triplet.",
                details={
                    "background_choice_ids": background_ids,
                    "background_sphere_choice_ids": background_sphere_ids,
                    "background_talent_choice_ids": background_talent_ids,
                },
                status_code=409,
            )
        self._require_frozen_background_package_triplet(
            delegated_envelope,
            background_id=background_ids[0],
            sphere_choice_id=background_sphere_ids[0],
            talent_choice_id=background_talent_ids[0],
        )

        rows = [
            {
                "kind": "starting_state",
                "effective_cl": 0,
                "record_id": "tianxia.source.canon.authority.manifest.p2a.json",
                "acquisition_channel": "source-document",
                "parameters": {"ability_scores": deepcopy(scores)},
            }
        ]

        background_record = require_record(background_ids[0], "background_choice")
        background_stage2_authority = (
            background_record.get("compatibility", {}).get("factory", {})
            .get("stage2_authority")
            or {}
        )
        adjustment = (
            background_stage2_authority.get("ability_adjustment")
            if isinstance(background_stage2_authority, dict)
            else None
        )
        has_background_adjustment = (
            isinstance(background_stage2_authority, dict)
            and "ability_adjustment" in background_stage2_authority
        )
        background_parameters: dict[str, Any] = {}
        if has_background_adjustment:
            raw_allowed_abilities = adjustment.get("allowed_abilities") if isinstance(adjustment, dict) else None
            raw_allowed_amounts = adjustment.get("allowed_amounts") if isinstance(adjustment, dict) else None
            if raw_allowed_amounts is None and isinstance(adjustment, dict):
                raw_allowed_amounts = adjustment.get("amount_choices")
            raw_allowed_amounts = [] if raw_allowed_amounts is None else raw_allowed_amounts
            source_amount = adjustment.get("amount") if isinstance(adjustment, dict) else None
            background_cap = adjustment.get("cap") if isinstance(adjustment, dict) else None
            if (
                background_stage2_authority.get("authority_complete") is not True
                or not isinstance(adjustment, dict)
                or not isinstance(raw_allowed_abilities, list)
                or not raw_allowed_abilities
                or any(
                    not isinstance(ability, str)
                    or ability not in {"STR", "DEX", "CON", "INT", "WIS", "CHA"}
                    for ability in raw_allowed_abilities
                )
                or not isinstance(raw_allowed_amounts, list)
                or any(type(value) is not int or value <= 0 for value in raw_allowed_amounts)
                or ("amount" in adjustment and (type(source_amount) is not int or source_amount <= 0))
                or type(background_cap) is not int
                or background_cap <= 0
            ):
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The Background ability adjustment has no complete positive typed authority.",
                    details={
                        "field": "bounded_choices.background_ability",
                        "allowed_abilities": raw_allowed_abilities,
                        "amount": source_amount,
                        "cap": background_cap,
                    },
                    status_code=409,
                )
            selected_ability = bounded.get("background_ability")
            allowed_amounts = [
                value
                for value in raw_allowed_amounts
            ]
            amount = (
                source_amount
                if type(source_amount) is int and not allowed_amounts
                else bounded.get("background_ability_amount", source_amount)
            )
            allowed_background_abilities = raw_allowed_abilities
            if (
                type(amount) is not int
                or amount <= 0
                or (allowed_amounts and amount not in allowed_amounts)
            ):
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The Background ability adjustment amount is outside its frozen positive typed authority.",
                    details={
                        "field": "bounded_choices.background_ability_amount",
                        "amount": amount,
                        "allowed_amounts": allowed_amounts,
                    },
                    status_code=409,
                )
            if selected_ability is None:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "Choose the exact Background ability before the Factory can materialize its typed adjustment.",
                    details={"field": "bounded_choices.background_ability", "allowed_abilities": adjustment.get("allowed_abilities")},
                    status_code=409,
                )
            if (
                selected_ability not in allowed_background_abilities
            ):
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The Background ability adjustment is outside its frozen typed authority.",
                    details={
                        "field": "bounded_choices.background_ability",
                        "ability": selected_ability,
                        "amount": amount,
                        "allowed_abilities": allowed_background_abilities,
                    },
                    status_code=409,
                )
            background_parameters = {"ability": selected_ability, "amount": amount}
            background_score = resolved_scores.get(selected_ability)
            if type(background_score) is not int:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The Background ability adjustment has no authoritative current score.",
                    details={"field": "bounded_choices.background_ability", "ability": selected_ability},
                    status_code=409,
                )
            background_result = background_score + amount
            if background_result > background_cap:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The Background ability adjustment would exceed its source-backed score cap.",
                    details={
                        "field": "bounded_choices.background_ability",
                        "ability": selected_ability,
                        "current_score": background_score,
                        "amount": amount,
                        "resulting_score": background_result,
                        "cap": background_cap,
                    },
                    status_code=409,
                )
            resolved_scores[selected_ability] = background_result
        rows.append(row("background_acquisition", 1, background_ids[0], parameters=background_parameters))
        rows.append(row("background_sphere_acquisition", 1, background_sphere_ids[0]))
        rows.append(row("background_talent_acquisition", 1, background_talent_ids[0]))
        rows.append(row("origin_insight_acquisition", 1, origin_ids[0]))
        rows.extend(row("path_acquisition", 1, path_id) for path_id in path_ids)
        method_ids = values("method_choice")
        foundation_ids = values("foundation_choice")
        for foundation_id in foundation_ids:
            if foundation_id not in records:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The frozen project does not contain the exact authority needed to materialize this Foundation.",
                    details={"field": "foundation_choice", "record_id": foundation_id},
                    status_code=409,
                )
        if method_ids:
            rows.append(row("method_acquisition", 1, method_ids[0]))
            if uses_initial_method_mechanics(run.get("request") or {}):
                rows.append(row("method_activation", 1, method_ids[0]))
        foundation_mechanics = initial_foundation_record_version(run.get("request") or {}) is not None
        if foundation_ids and not foundation_mechanics:
            rows.append(row("foundation_acquisition", 1, foundation_ids[0]))
        if foundation_mechanics:
            validate_foundation_initial_stage(run.get("request") or {}, {"foundation_choice": foundation_ids}, bounded)
            if foundation_ids and target_cl < INITIAL_FOUNDATION_MECHANICS_POLICY["acquisition_cl"]:
                raise FoundryError("CG1_FOUNDATION_ACQUIRED_TOO_EARLY", "A Foundation requires the published Realm entry at CL5.", status_code=409)

        # A server-validated canonical grant lock is automatic authority.  In
        # its absence, only the preferred semantic acquisition object may create
        # Sphere/Talent rows; planning priorities are never promoted.
        grant_plan = (
            locks.get(COMMITTED_CATALOG_CHOICE_FIELD)
            or locks.get("character_sheet.canonical_grant_plan")
        )
        acquisition = intent_doc.get("acquisition_intent") or {}
        if not isinstance(acquisition, dict):
            raise FoundryError(
                "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID",
                "The canonical intent has no semantic acquisition object.",
                status_code=422,
            )
        pair_rows = [
            value for value in acquisition.get("sphere_free_talent_pairs") or []
            if isinstance(value, dict)
        ]
        sphere_pairs = [
            (value.get("sphere_id"), value.get("talent_id"))
            for value in pair_rows
            if isinstance(value.get("sphere_id"), str) and isinstance(value.get("talent_id"), str)
        ]
        if not sphere_pairs:
            accounting = grant_plan.get("grant_accounting") if isinstance(grant_plan, dict) else {}
            sphere_pairs = [
                (value.get("sphere_id"), value.get("talent_id"))
                for value in accounting.get("free_sphere_talent_grants") or []
                if isinstance(value, dict) and isinstance(value.get("sphere_id"), str) and isinstance(value.get("talent_id"), str)
            ]
        if not sphere_pairs:
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "Choose explicit Sphere acquisitions or provide a server-validated canonical grant lock; priority order alone cannot acquire a Sphere.",
                details={"field": "acquisition_intent.free_sphere_talent_grants"},
                status_code=409,
            )
        # The semantic pair carries the acquired Sphere and its free Talent;
        # the provider never chooses the Stage 2 event route.  Resolve the
        # exact route-specific kinds from the frozen project generation lock,
        # then let each record's authenticated authority choose/verify its
        # channel.  Planning priorities remain non-acquisitive.
        pair_route = self._project_generation_route(project)
        if len(sphere_pairs) != 1:
            raise FoundryError(
                "CG1_CREATION_ROUTE_COUNT_INVALID",
                "The selected creation route must contain exactly one Sphere/free-Talent pair.",
                details={
                    "route": pair_route,
                    "expected_pair_count": 1,
                    "actual_pair_count": len(sphere_pairs),
                },
                status_code=409,
            )
        pair_sphere_kind = (
            "ai_bootstrap_sphere_acquisition"
            if pair_route == "ai_bootstrap"
            else "sect_trial_sphere_acquisition"
        )
        pair_talent_kind = (
            "ai_bootstrap_talent_acquisition"
            if pair_route == "ai_bootstrap"
            else "sect_trial_talent_acquisition"
        )
        seen_spheres: set[str] = set()
        seen_free_talents: set[str] = set()
        for sphere_id, talent_id in sphere_pairs:
            if not talent_id:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "Each acquired Sphere requires one exact free-Talent selection.",
                    details={"sphere_id": sphere_id},
                    status_code=409,
                )
            if sphere_id in seen_spheres or talent_id in seen_free_talents:
                raise FoundryError(
                    "CG1_DELEGATED_DUPLICATE_CHOICE",
                    "Each acquired Sphere and free Talent may occur only once.",
                    details={"sphere_id": sphere_id, "talent_id": talent_id},
                    status_code=409,
                )
            seen_spheres.add(sphere_id)
            seen_free_talents.add(talent_id)
            sphere_record = require_record(sphere_id, "acquisition_intent.sphere_free_talent_pairs.sphere_id")
            talent_record = require_record(talent_id, "acquisition_intent.sphere_free_talent_pairs.talent_id")
            talent_authority = talent_record.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {}
            owning_sphere = (
                talent_authority.get("owning_canonical_sphere_id")
                or talent_authority.get("sphere_id")
                or talent_record.get("owning_canonical_sphere_id")
            )
            if isinstance(owning_sphere, str) and owning_sphere != sphere_id:
                raise FoundryError(
                    "CG1_DELEGATED_FREE_TALENT_SPHERE_MISMATCH",
                    "The selected free Talent is not owned by its selected Sphere in frozen authority.",
                    details={"sphere_id": sphere_id, "talent_id": talent_id, "owning_sphere_id": owning_sphere},
                    status_code=409,
                )
            if sphere_record.get("content_type") not in {None, "sphere"} or talent_record.get("content_type") not in {None, "talent"}:
                raise FoundryError(
                    "CG1_DELEGATED_ACQUISITION_RECORD_TYPE_INVALID",
                    "A Sphere/free-Talent pair must reference frozen Sphere and Talent authority records.",
                    details={"sphere_id": sphere_id, "sphere_content_type": sphere_record.get("content_type"), "talent_id": talent_id, "talent_content_type": talent_record.get("content_type")},
                    status_code=409,
                )
            sphere_authority = (
                sphere_record.get("compatibility", {})
                .get("factory", {})
                .get("stage2_authority")
                or {}
            )
            talent_authority = (
                talent_record.get("compatibility", {})
                .get("factory", {})
                .get("stage2_authority")
                or {}
            )
            advertised_sphere_kinds = [
                value for value in sphere_authority.get("allowed_kinds") or []
                if isinstance(value, str)
            ]
            advertised_talent_kinds = [
                value for value in talent_authority.get("allowed_kinds") or []
                if isinstance(value, str)
            ]
            if (
                pair_sphere_kind not in advertised_sphere_kinds
                or pair_talent_kind not in advertised_talent_kinds
            ):
                raise FoundryError(
                    "CG1_DELEGATED_FREE_TALENT_NOT_LEGAL",
                    "The selected Sphere/free-Talent pair is not legal for the frozen generation route.",
                    details={
                        "sphere_id": sphere_id,
                        "talent_id": talent_id,
                        "route": pair_route,
                        "required_sphere_kind": pair_sphere_kind,
                        "required_talent_kind": pair_talent_kind,
                        "advertised_sphere_kinds": sorted(set(advertised_sphere_kinds)),
                        "advertised_talent_kinds": sorted(set(advertised_talent_kinds)),
                    },
                    status_code=409,
                )
            # The selected project route and each locked record's published
            # authority decide whether this is the sect-trial or AI-bootstrap
            # pair.  The response never gets to select the route by supplying a
            # convenient event kind.
            rows.append(row(pair_sphere_kind, 1, sphere_id))
            rows.append(row(pair_talent_kind, 1, talent_id))

        accounting = grant_plan.get("grant_accounting") if isinstance(grant_plan, dict) else {}
        ordinary_ids = [
            value for value in acquisition.get("ordinary_talent_ids") or []
            if isinstance(value, str)
        ]
        if not ordinary_ids:
            ordinary_ids = [value for value in accounting.get("ordinary_talent_ids") or [] if isinstance(value, str)]
        # The complete-character source inventory is the governing capacity.
        # A project may already carry an earlier/empty catalog grant lock (for
        # example, before the delegated CL20 response has supplied its
        # acquisitions); that lock must not replace the frozen source count.
        delegated_envelope = (run.get("request") or {}).get("delegated_choice_envelope") or {}
        source_count = delegated_envelope.get("ordinary_talent_count")
        authority_count = source_count if type(source_count) is int else (
            accounting.get("ordinary_talent_count") if isinstance(accounting, dict) else None
        )
        if authority_count is None:
            authority_count = target_cl
        if type(authority_count) is not int or authority_count != target_cl:
            raise FoundryError(
                "CG1_ORDINARY_TALENT_COUNT_AUTHORITY_UNRESOLVED",
                "The installed source authority does not expose the currently supported one-ordinary-Talent-per-CL creation capacity.",
                details={"target_cl": target_cl, "authority_count": authority_count},
                status_code=409,
            )
        if len(ordinary_ids) != authority_count:
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "Choose exactly one source-authorized ordinary Talent for every target CL before the Factory can materialize progression.",
                details={"field": "acquisition_intent.ordinary_talent_ids", "required_count": authority_count, "actual_count": len(ordinary_ids)},
                status_code=409,
            )
        if len(ordinary_ids) != len(set(ordinary_ids)):
            raise FoundryError("CG1_DELEGATED_DUPLICATE_CHOICE", "ordinary_talent_ids must be unique.", status_code=409)

        delegated_envelope = (run.get("request") or {}).get("delegated_choice_envelope") or {}
        ordinary_choice_ids = [
            value
            for value in (delegated_envelope.get("allowed_choice_ids_by_slot") or {}).get("advancement_skeleton", [])
            if isinstance(value, str)
        ]
        free_talent_ids = {
            value.get("talent_id")
            for value in acquisition.get("sphere_free_talent_pairs") or []
            if isinstance(value, dict) and isinstance(value.get("talent_id"), str)
        }
        try:
            canonical_background_ids = canonical_selected_background_sphere_ids(
                intent_doc.get("selected_by_slot") or {},
                delegated_envelope.get("choices_by_slot"),
                delegated_envelope.get("typed_choice_authority_by_slot"),
            )
        except SealedBackgroundSphereResolutionError as exc:
            raise FoundryError(
                "CG1_TRAINED_CHOICE_BACKGROUND_SPHERE_INVALID",
                "The selected Background Sphere cannot be resolved to one canonical sealed Sphere.",
                details={
                    "background_sphere_id": exc.background_sphere_id,
                    "reason": exc.reason,
                    "display_name": exc.display_name,
                    "candidate_ids": exc.candidate_ids,
                },
                status_code=409,
            ) from exc
        canonical_background_sphere_ids_set = set(canonical_background_ids.values())
        package_spheres, package_talents = canonical_background_package_ids(
            intent_doc.get("selected_by_slot") or {},
            delegated_envelope.get("typed_choice_authority_by_slot"),
        )
        canonical_background_sphere_ids_set.update(package_spheres)
        ordinary_sphere_ids = set(seen_spheres) | canonical_background_sphere_ids_set

        creation_training_contract = delegated_envelope.get("creation_training_contract")
        creation_training_rows_by_cl: dict[int, list[dict[str, Any]]] = {}
        if creation_training_contract is not None:
            contract_errors = validate_creation_training_contract(creation_training_contract)
            if contract_errors or creation_training_contract.get("target_cl") != target_cl:
                raise FoundryError(
                    "CG1_CREATION_TRAINING_CONTRACT_INVALID",
                    "The sealed creation-training contract does not match the target creation CL.",
                    details={
                        "fields": contract_errors,
                        "contract_target_cl": creation_training_contract.get("target_cl"),
                        "target_cl": target_cl,
                    },
                    status_code=409,
                )
            trained_rows = acquisition.get("trained_choices")
            if not isinstance(trained_rows, list):
                raise FoundryError(
                    "CG1_CREATION_TRAINING_CHOICES_REQUIRED",
                    "A sealed creation-training contract requires a trained_choices array.",
                    status_code=409,
                )
            routes = creation_training_contract.get("records") or {}
            indexed_rows = sorted(
                enumerate(trained_rows),
                key=lambda item: (
                    item[1].get("cl", 0) if isinstance(item[1], dict) else 0,
                    item[1].get("slot", 0) if isinstance(item[1], dict) else 0,
                    item[0],
                ),
            )
            if [index for index, _row in indexed_rows] != list(range(len(trained_rows))):
                raise FoundryError(
                    "CG1_TRAINED_CHOICE_ORDER_INVALID",
                    "Constructed trained choices must be ordered by CL and slot.",
                    status_code=409,
                )
            trained_ids = [
                value.get("record_id")
                for value in trained_rows
                if isinstance(value, dict) and isinstance(value.get("record_id"), str)
            ]
            if len(trained_ids) != len(set(trained_ids)):
                raise FoundryError(
                    "CG1_DELEGATED_DUPLICATE_CHOICE",
                    "Constructed training records may be acquired only once.",
                    details={"record_ids": trained_ids},
                    status_code=409,
                )
            known_spheres = set(seen_spheres) | canonical_background_sphere_ids_set
            known_talents = set(seen_free_talents) | set(background_talent_ids) | package_talents
            used_ids = (
                set(seen_spheres)
                | set(seen_free_talents)
                | set(background_sphere_ids)
                | canonical_background_sphere_ids_set
                | set(background_talent_ids)
                | package_talents
                | set(ordinary_ids)
            )
            bonus_ids: set[str] = set()
            validated_ordinary_indices: set[int] = set()

            def ordinary_route(record_id: str, record: dict[str, Any]) -> dict[str, Any]:
                """Project locked ordinary Talent legality into the route checker."""

                route = deepcopy(record)
                authority = record.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {}
                authority = authority if isinstance(authority, dict) else {}
                legality = record.get("legality") if isinstance(record.get("legality"), dict) else {}
                for key in ("access_category", "minimum_cl", "allowed_cls", "realm_rules", "prerequisites", "incompatibilities", "owning_sphere_id", "owning_canonical_sphere_id"):
                    if key in route:
                        continue
                    if key in legality:
                        route[key] = deepcopy(legality[key])
                    elif authority.get(key) is not None:
                        route[key] = deepcopy(authority[key])
                route.setdefault("record_id", record_id)
                route.setdefault("content_type", "talent")
                route.setdefault("choice_type", "known_sphere_talent")
                return route

            def validate_ordinary_before(effective_cl: int) -> None:
                """Validate ordinary Talents only after the prior CL state exists."""

                for ordinary_index in range(1, min(effective_cl, len(ordinary_ids) + 1)):
                    if ordinary_index in validated_ordinary_indices:
                        continue
                    ordinary_id = ordinary_ids[ordinary_index - 1]
                    ordinary_record = require_record(ordinary_id, f"acquisition_intent.ordinary_talent_ids.{ordinary_index - 1}")
                    route = ordinary_route(ordinary_id, ordinary_record)
                    route_errors = creation_route_temporal_legality_errors(
                        route,
                        cl=ordinary_index,
                        present_ids=(
                            creation_context_ids(
                                intent_doc.get("selected_by_slot") or {},
                                delegated_envelope.get("choices_by_slot"),
                                delegated_envelope.get("typed_choice_authority_by_slot"),
                                current_cl=ordinary_index,
                            )
                            | set(known_spheres)
                            | set(known_talents)
                        ),
                        candidate_ids=(ordinary_id,),
                    )
                    owning_sphere = route.get("owning_sphere_id") or route.get("owning_canonical_sphere_id")
                    if isinstance(owning_sphere, str) and owning_sphere not in known_spheres:
                        route_errors = [*route_errors, "owning_sphere_id"]
                    if route_errors:
                        raise FoundryError(
                            "CG1_ORDINARY_TALENT_ILLEGAL",
                            "An ordinary Talent is not legal in its prior causal state.",
                            details={
                                "ordinary_talent_index": ordinary_index - 1,
                                "record_id": ordinary_id,
                                "effective_cl": ordinary_index,
                                "fields": sorted(set(route_errors)),
                            },
                            status_code=409,
                        )
                    known_talents.add(ordinary_id)
                    validated_ordinary_indices.add(ordinary_index)

            for original_index, training_row in indexed_rows:
                row_errors = validate_trained_choice_shape(training_row)
                if row_errors:
                    raise FoundryError(
                        "CG1_PREFERRED_RESPONSE_TRAINED_CHOICE_INVALID",
                        "A trained choice does not match the constructed creation-training contract.",
                        details={"index": original_index, "fields": row_errors},
                        status_code=409,
                    )
                cl = training_row["cl"]
                validate_ordinary_before(cl)
                if cl > target_cl:
                    raise FoundryError(
                        "CG1_TRAINED_CHOICE_CL_INVALID",
                        "A trained choice must occur within the frozen target CL.",
                        details={"index": original_index, "cl": cl, "target_cl": target_cl},
                        status_code=409,
                    )
                record_id = training_row["record_id"]
                route = routes.get(record_id)
                record = require_record(record_id, f"acquisition_intent.trained_choices[{original_index}].record_id")
                if not isinstance(route, dict) or route.get("choice_type") != training_row["choice_type"]:
                    raise FoundryError(
                        "CG1_TRAINED_CHOICE_TYPE_MISMATCH",
                        "The trained choice type does not match its sealed catalog route.",
                        details={"record_id": record_id, "choice_type": training_row["choice_type"]},
                        status_code=409,
                    )
                expected_content_type = "sphere" if training_row["choice_type"] == "new_sphere" else "talent"
                if record.get("content_type") not in {None, expected_content_type} or route.get("content_type") != expected_content_type:
                    raise FoundryError(
                        "CG1_TRAINED_CHOICE_RECORD_TYPE_INVALID",
                        "A constructed training row is bound to the wrong catalog content type.",
                        details={"record_id": record_id, "expected_content_type": expected_content_type, "content_type": record.get("content_type")},
                        status_code=409,
                    )
                if training_row.get("source") != constructed_source(route, choice_type=training_row["choice_type"]):
                    raise FoundryError(
                        "CG1_TRAINED_CHOICE_SOURCE_INVALID",
                        "The constructed training source proof does not match the sealed route.",
                        details={"record_id": record_id},
                        status_code=409,
                    )
                if training_row.get("outcome") != constructed_outcome():
                    raise FoundryError(
                        "CG1_TRAINED_CHOICE_OUTCOME_INVALID",
                        "Constructed training must record a successful non-rolled outcome.",
                        details={"record_id": record_id},
                        status_code=409,
                    )
                if record_id in used_ids:
                    raise FoundryError(
                        "CG1_DELEGATED_DUPLICATE_CHOICE",
                        "A constructed training record cannot repeat another acquisition.",
                        details={"record_id": record_id},
                        status_code=409,
                    )
                present_ids = (
                    creation_context_ids(
                        intent_doc.get("selected_by_slot") or {},
                        delegated_envelope.get("choices_by_slot"),
                        delegated_envelope.get("typed_choice_authority_by_slot"),
                        current_cl=cl,
                    )
                    | set(known_spheres)
                    | set(known_talents)
                )
                route_errors = creation_route_legality_errors(
                    route,
                    cl=cl,
                    present_ids=present_ids,
                    candidate_ids=(record_id,),
                )
                if route_errors:
                    raise FoundryError(
                        "CG1_TRAINED_CHOICE_ILLEGAL",
                        "A constructed training route is not legal in the prior causal state.",
                        details={"index": original_index, "record_id": record_id, "fields": route_errors},
                        status_code=409,
                    )
                if training_row["choice_type"] == "new_sphere":
                    bonus_id = training_row.get("bonus_talent_id")
                    bonus_route = routes.get(bonus_id)
                    if (
                        not isinstance(bonus_id, str)
                        or bonus_id in used_ids
                        or bonus_id in trained_ids
                        or bonus_id in bonus_ids
                        or not isinstance(bonus_route, dict)
                        or bonus_route.get("content_type") != "talent"
                        or bonus_route.get("choice_type") != "known_sphere_talent"
                        or bonus_route.get("owning_sphere_id") != record_id
                        or bonus_route.get("bonus_talent_eligible") is not True
                    ):
                        raise FoundryError(
                            "CG1_NEW_SPHERE_BONUS_INVALID",
                            "A newly trained Sphere must name one exact unused bonus Talent from that Sphere.",
                            details={"sphere_id": record_id, "bonus_talent_id": bonus_id},
                            status_code=409,
                        )
                    bonus_errors = creation_route_legality_errors(
                        bonus_route,
                        cl=cl,
                        present_ids=present_ids,
                        candidate_ids=(record_id, bonus_id),
                        prior_choice_ids=(record_id,),
                    )
                    if bonus_errors:
                        raise FoundryError(
                            "CG1_NEW_SPHERE_BONUS_ILLEGAL",
                            "A new-Sphere bonus Talent is not legal in the constructed causal state.",
                            details={"sphere_id": record_id, "bonus_talent_id": bonus_id, "fields": bonus_errors},
                            status_code=409,
                        )
                    bonus_ids.add(bonus_id)
                    used_ids.add(bonus_id)
                    known_spheres.add(record_id)
                    ordinary_sphere_ids.add(record_id)
                    known_talents.add(bonus_id)
                else:
                    owning_sphere = route.get("owning_sphere_id")
                    if not isinstance(owning_sphere, str) or owning_sphere not in known_spheres:
                        raise FoundryError(
                            "CG1_TRAINED_TALENT_SPHERE_NOT_KNOWN",
                            "A constructed Talent requires its owning Sphere to be known earlier in the causal order.",
                            details={"record_id": record_id, "owning_sphere_id": owning_sphere, "known_spheres": sorted(known_spheres)},
                            status_code=409,
                        )
                    if creation_route_legality_errors(
                        route,
                        cl=cl,
                        present_ids=present_ids,
                        candidate_ids=(record_id,),
                    ):
                        raise FoundryError(
                            "CG1_TRAINED_CHOICE_ILLEGAL",
                            "A constructed Talent route is not legal in the prior causal state.",
                            details={
                                "index": original_index,
                                "record_id": record_id,
                                "fields": creation_route_legality_errors(
                                    route,
                                    cl=cl,
                                    present_ids=present_ids,
                                    candidate_ids=(record_id,),
                                ),
                            },
                            status_code=409,
                        )
                    known_talents.add(record_id)
                used_ids.add(record_id)
                creation_training_rows_by_cl.setdefault(cl, []).append(deepcopy(training_row))
            # With no later training group to trigger the predecessor check,
            # validate the remaining ordinary CLs after the last training CL.
            validate_ordinary_before(target_cl + 1)
            for cl, rows_for_cl in creation_training_rows_by_cl.items():
                for expected_slot, training_row in enumerate(rows_for_cl, start=1):
                    if training_row["slot"] != expected_slot:
                        raise FoundryError(
                            "CG1_TRAINED_CHOICE_SLOT_NOT_CONTIGUOUS",
                            "Constructed trained-choice slots must be contiguous within each CL.",
                            details={"cl": cl, "expected": expected_slot, "actual": training_row["slot"]},
                            status_code=409,
                        )
            if creation_training_contract.get("required_choices_per_cl") == 3:
                missing = {
                    cl: 3 - len(creation_training_rows_by_cl.get(cl, []))
                    for cl in range(1, target_cl + 1)
                    if len(creation_training_rows_by_cl.get(cl, [])) < 3
                }
                if missing:
                    raise FoundryError(
                        "CG1_TRAINED_CHOICE_REQUIRED_COUNT_UNMET",
                        "The rival/boss creation contract requires three legal trained choices at every CL.",
                        details={"missing_by_cl": missing},
                        status_code=409,
                    )
        elif "trained_choices" in acquisition:
            raise FoundryError(
                "CG1_CREATION_TRAINING_CONTRACT_REQUIRED",
                "Constructed training choices require a sealed creation-training contract.",
                status_code=409,
            )

        def ordinary_minimum_cl(record: dict[str, Any]) -> int | None:
            authority = record.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {}
            value = authority.get("minimum_cl")
            if type(value) is int:
                return value
            value = record.get("legality", {}).get("minimum_cl")
            return value if type(value) is int else None

        def legal_ordinary_ids(effective_cl: int, current_index: int) -> list[str]:
            used = set(ordinary_ids)
            if 0 <= current_index < len(ordinary_ids):
                used.discard(ordinary_ids[current_index])
            result: list[str] = []
            for candidate_id in sorted(set(ordinary_choice_ids)):
                if candidate_id in used or candidate_id in free_talent_ids:
                    continue
                candidate = records.get(candidate_id)
                if not isinstance(candidate, dict) or candidate.get("content_type") not in {None, "talent"}:
                    continue
                minimum = ordinary_minimum_cl(candidate)
                if type(minimum) is int and minimum > effective_cl:
                    continue
                candidate_authority = candidate.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {}
                owning_sphere = (
                    candidate_authority.get("owning_canonical_sphere_id")
                    or candidate_authority.get("sphere_id")
                    or candidate.get("owning_canonical_sphere_id")
                )
                if isinstance(owning_sphere, str) and owning_sphere not in ordinary_sphere_ids:
                    continue
                try:
                    self._resolve_event_authority(
                        candidate,
                        project,
                        requested_kind="level_talent_acquisition",
                        effective_cl=effective_cl,
                        field=f"acquisition_intent.ordinary_talent_ids.{current_index}",
                    )
                except FoundryError:
                    continue
                result.append(candidate_id)
            return result

        path_authority_by_id = {
            path_id: records[path_id].get("compatibility", {}).get("factory", {}).get("stage2_authority") or {}
            for path_id in path_ids
            if path_id in records
        }
        if len(path_authority_by_id) != len(path_ids):
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "The frozen Path authority is missing an executable selected Path record.",
                details={"path_ids": path_ids},
                status_code=409,
            )

        def source_backed_ability_change_rule(
            milestone: dict[str, Any],
        ) -> dict[str, Any]:
            """Return the exact ASI rule published by the selected Path feature.

            The delegated envelope carries this rule for provider context, but
            Stage 2 must independently prove it from the project-locked Path
            record.  This keeps a response from turning a non-authoritative
            delta map into an executable ability-score event.
            """
            feature_id = milestone.get("feature_record_id")
            feature = records.get(feature_id) if isinstance(feature_id, str) else None
            raw_authority = (
                feature.get("compatibility", {}).get("factory", {}).get("stage2_authority")
                if isinstance(feature, dict)
                else {}
            )
            authority = raw_authority if isinstance(raw_authority, dict) else {}
            rule = authority.get("ability_change") if isinstance(authority, dict) else None
            allowed_cls = rule.get("allowed_cls") if isinstance(rule, dict) else None
            allowed_deltas = rule.get("allowed_deltas") if isinstance(rule, dict) else None
            allowed_abilities = rule.get("allowed_abilities") if isinstance(rule, dict) else None
            source = feature.get("source") if isinstance(feature, dict) else None
            path_id = milestone.get("path_id")
            cl = milestone.get("cl")
            if (
                not isinstance(feature, dict)
                or authority.get("authority_complete") is not True
                or authority.get("feature_kind") != "advancement_choice"
                or authority.get("feature_record_id") != feature_id
                or authority.get("path_id") != path_id
                or "ability_score_change" not in (authority.get("allowed_kinds") or [])
                or not isinstance(authority.get("allowed_channels"), list)
                or "level-choice" not in authority["allowed_channels"]
                or not isinstance(rule, dict)
                or not isinstance(allowed_cls, list)
                or not allowed_cls
                or any(type(value) is not int or value < 1 for value in allowed_cls)
                or type(cl) is not int
                or cl not in allowed_cls
                or not isinstance(allowed_deltas, list)
                or not allowed_deltas
                or any(type(value) is not int or value <= 0 for value in allowed_deltas)
                or (
                    "allowed_abilities" in rule
                    and (
                        not isinstance(allowed_abilities, list)
                        or not allowed_abilities
                        or any(value not in {"STR", "DEX", "CON", "INT", "WIS", "CHA"} for value in allowed_abilities)
                    )
                )
                or type(rule.get("budget")) is not int
                or rule["budget"] <= 0
                or type(rule.get("cap")) is not int
                or rule["cap"] <= 0
                or not isinstance(source, dict)
                or not isinstance(source.get("path"), str)
                or not isinstance(source.get("source_hash"), str)
                or len(source["source_hash"]) != 64
            ):
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The selected Path advancement milestone has no complete source-backed ability-score rule.",
                    details={
                        "field": f"bounded_choices.ability_score_changes_by_milestone_id.{milestone.get('milestone_id')}",
                        "milestone_id": milestone.get("milestone_id"),
                        "path_id": path_id,
                        "feature_record_id": feature_id,
                        "effective_cl": cl,
                    },
                    status_code=409,
                )
            return deepcopy(rule)

        progression_choice = bounded.get("path_progression_by_cl") or bounded.get("path_progression_choice_by_cl") or {}
        selected_progression: dict[int, tuple[str, list[str]]] = {}
        semantic_insights = [
            value for value in acquisition.get("insight_occurrences") or []
            if isinstance(value, dict)
        ]
        insight_by_milestone = {
            value.get("milestone_id"): value
            for value in semantic_insights
            if isinstance(value.get("milestone_id"), str)
        }
        asi_by_milestone = bounded.get("ability_score_changes_by_milestone_id") or {}
        if not isinstance(asi_by_milestone, dict):
            asi_by_milestone = {}
        resolved_milestones: set[str] = set()
        expected_milestones: dict[str, dict[str, Any]] = {}
        emitted_subpath_ids: set[str] = set()
        for cl in range(1, target_cl + 1):
            requested_path = progression_choice.get(str(cl), progression_choice.get(cl)) if isinstance(progression_choice, dict) else None
            available_paths = [
                path_id
                for path_id, authority in path_authority_by_id.items()
                if str(cl) in (authority.get("progression_by_cl") or {})
            ]
            if requested_path is not None:
                if str(requested_path) not in available_paths:
                    raise FoundryError(
                        "CG1_BOUNDED_DECISION_REQUIRED",
                        "The bounded Path progression choice is not available at the requested CL.",
                        details={"cl": cl, "requested_path": requested_path, "available_path_ids": available_paths},
                        status_code=409,
                    )
                progression_path = str(requested_path)
            elif len(available_paths) == 1:
                progression_path = available_paths[0]
            elif len(available_paths) > 1:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "More than one selected Path can advance at this CL; choose one exact Path progression route.",
                    details={"cl": cl, "available_path_ids": available_paths},
                    status_code=409,
                )
            else:
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The frozen Path authority contains no progression entry for the requested CL.",
                    details={"cl": cl, "path_ids": path_ids},
                    status_code=409,
                )
            progression = (path_authority_by_id[progression_path].get("progression_by_cl") or {}).get(str(cl)) or {}
            feature_ids = [
                value for value in progression.get("feature_record_ids") or []
                if isinstance(value, str)
            ]
            if not feature_ids or any(value not in records for value in feature_ids):
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    "The selected Path progression entry is not fully represented in the frozen record snapshot.",
                    details={"cl": cl, "path_id": progression_path, "feature_record_ids": feature_ids},
                    status_code=409,
                )
            # Representative features always use authenticated source order;
            # historical rows are compared only after this derivation.
            feature_id = feature_ids[0]
            selected_progression[cl] = (progression_path, feature_ids)
            level_row = row("level_advance", cl, feature_id)
            if equal_initial_path_attainment(run.get("request") or {}):
                level_row.setdefault("parameters", {})["native_path_progressions"] = native_path_progressions([records[path_id] for path_id in path_ids], cl)
            rows.append(level_row)
            if foundation_ids and foundation_mechanics and cl == INITIAL_FOUNDATION_MECHANICS_POLICY["acquisition_cl"]:
                foundation_row = row("foundation_acquisition", cl, foundation_ids[0])
                if bounded.get("foundation_initial_stage") is not None:
                    foundation_row.setdefault("parameters", {})["stage"] = bounded["foundation_initial_stage"]
                rows.append(foundation_row)
            path_authority = path_authority_by_id[progression_path]
            milestone_specs: list[dict[str, Any]] = []
            for feature in feature_ids:
                if path_feature_kind(records[feature]) != "advancement_choice":
                    continue
                candidates = [
                    value for value in path_authority.get("required_milestones") or []
                    if isinstance(value, dict)
                    and value.get("feature_record_id") == feature
                    and value.get("cl", cl) == cl
                    and "cultivation_insight_acquisition" in (value.get("allowed_kinds") or [])
                ]
                milestone = deepcopy(candidates[0]) if candidates else {
                    "milestone_id": f"{feature}.cl{cl}",
                    "path_id": progression_path,
                    "cl": cl,
                    "feature_record_id": feature,
                    "allowed_kinds": ["ability_score_change", "cultivation_insight_acquisition"],
                }
                milestone_id = milestone.get("milestone_id")
                if not isinstance(milestone_id, str):
                    raise FoundryError(
                        "CG1_BOUNDED_DECISION_REQUIRED",
                        "The authenticated Path authority has an advancement milestone without a stable ID.",
                        details={"cl": cl, "feature_record_id": feature},
                        status_code=409,
                    )
                milestone["milestone_id"] = milestone_id
                milestone["cl"] = cl
                milestone["feature_record_id"] = feature
                milestone_specs.append(milestone)
                expected_milestones[milestone_id] = milestone
            for milestone in milestone_specs:
                milestone_id = milestone["milestone_id"]
                ability_change_rule = None
                if "ability_score_change" in (milestone.get("allowed_kinds") or []):
                    ability_change_rule = source_backed_ability_change_rule(milestone)
                insight = insight_by_milestone.get(milestone_id)
                change_entry = asi_by_milestone.get(milestone_id)
                if insight is not None and change_entry:
                    raise FoundryError(
                        "CG1_DELEGATED_AUTHORITY_CONFLICT",
                        "An Advancement Choice milestone cannot receive both an ability-score change and a Cultivation Insight.",
                        details={"milestone_id": milestone_id, "effective_cl": cl},
                        status_code=409,
                    )
                if insight is None and not change_entry:
                    raise FoundryError(
                        "CG1_BOUNDED_DECISION_REQUIRED",
                        "Resolve every source-backed advancement milestone exactly once with an ability-score change or Insight.",
                        details={
                            "field": f"bounded_choices.ability_score_changes_by_milestone_id.{milestone_id}",
                            "milestone_id": milestone_id,
                            "effective_cl": cl,
                            "allowed_resolutions": ["ability_score_change", "cultivation_insight_acquisition"],
                        },
                        status_code=409,
                    )
                if insight is not None:
                    insight_id = insight.get("insight_id")
                    if not isinstance(insight_id, str):
                        raise FoundryError(
                            "CG1_BOUNDED_DECISION_REQUIRED",
                            "An Insight milestone resolution requires an exact Insight ID.",
                            details={"milestone_id": milestone_id},
                            status_code=409,
                        )
                    insight_record = require_record(insight_id, f"acquisition_intent.insight_occurrences[{milestone_id}].insight_id")
                    insight_authority = (
                        insight_record.get("compatibility", {}).get("factory", {}).get("stage2_authority")
                        if isinstance(insight_record, dict)
                        else None
                    )
                    insight_authority = insight_authority if isinstance(insight_authority, dict) else {}
                    allowed_cls = insight_authority.get("allowed_cls") or insight_authority.get("allowed_effective_cls")
                    rule = insight_authority.get("ability_change")
                    if rule is None:
                        rule = insight_authority.get("insight_ability_change")
                    rule_abilities = rule.get("allowed_abilities") if isinstance(rule, dict) else None
                    rule_amount = rule.get("amount") if isinstance(rule, dict) else None
                    rule_cap = rule.get("cap") if isinstance(rule, dict) else None
                    if (
                        insight_authority.get("authority_complete") is not True
                        or "cultivation_insight_acquisition" not in (insight_authority.get("allowed_kinds") or [])
                        or not isinstance(insight_authority.get("allowed_channels"), list)
                        or "cultivation-insight-selection" not in insight_authority["allowed_channels"]
                        or not isinstance(allowed_cls, list)
                        or not allowed_cls
                        or any(type(value) is not int or value < 1 for value in allowed_cls)
                        or type(cl) is not int
                        or cl not in allowed_cls
                        or not isinstance(rule, dict)
                        or not isinstance(rule_abilities, list)
                        or not rule_abilities
                        or any(
                            not isinstance(ability, str)
                            or ability not in {"STR", "DEX", "CON", "INT", "WIS", "CHA"}
                            for ability in rule_abilities
                        )
                        or type(rule_amount) is not int
                        or rule_amount <= 0
                        or type(rule_cap) is not int
                        or rule_cap <= 0
                    ):
                        raise FoundryError(
                            "CG1_BOUNDED_DECISION_REQUIRED",
                            "The selected Insight has no complete positive typed authority for this milestone.",
                            details={
                                "insight_id": insight_id,
                                "milestone_id": milestone_id,
                                "effective_cl": cl,
                                "allowed_cls": allowed_cls,
                            },
                            status_code=409,
                        )
                    parameters = deepcopy(insight.get("parameters") or {})
                    if rule:
                        if not isinstance(rule, dict):
                            raise FoundryError(
                                "CG1_BOUNDED_DECISION_REQUIRED",
                                "The selected Insight has no complete typed ability-change authority.",
                                details={"milestone_id": milestone_id, "insight_id": insight_id},
                                status_code=409,
                            )
                        ability = parameters.get("ability")
                        if not isinstance(ability, str):
                            raise FoundryError(
                                "CG1_BOUNDED_DECISION_REQUIRED",
                                "Choose the exact typed ability for this Insight occurrence.",
                                details={"field": f"acquisition_intent.insight_occurrences[{milestone_id}].parameters.ability", "milestone_id": milestone_id, "allowed_abilities": rule.get("allowed_abilities") or []},
                                status_code=409,
                            )
                        if ability not in (rule.get("allowed_abilities") or []):
                            raise FoundryError(
                                "CG1_INSIGHT_PARAMETER_OUT_OF_AUTHORITY",
                                "The Insight ability is outside its frozen typed authority.",
                                details={"milestone_id": milestone_id, "ability": ability, "allowed_abilities": rule.get("allowed_abilities") or []},
                                status_code=409,
                            )
                        parameters["amount"] = rule_amount
                        previous_occurrences = [
                            value for value in rows
                            if value.get("kind") == "cultivation_insight_acquisition" and value.get("record_id") == insight_id
                        ]
                        parameters["repeat_index"] = len(previous_occurrences) + 1
                        current_score = resolved_scores.get(ability)
                        if type(current_score) is not int:
                            raise FoundryError(
                                "CG1_BOUNDED_DECISION_REQUIRED",
                                "The Insight ability change has no authoritative current score.",
                                details={"milestone_id": milestone_id, "insight_id": insight_id, "ability": ability},
                                status_code=409,
                            )
                        resulting_score = current_score + rule_amount
                        insight_cap = rule_cap
                        if resulting_score > insight_cap:
                            raise FoundryError(
                                "CG1_BOUNDED_DECISION_REQUIRED",
                                "The Insight ability change would exceed its source-backed score cap.",
                                details={
                                    "milestone_id": milestone_id,
                                    "insight_id": insight_id,
                                    "ability": ability,
                                    "current_score": current_score,
                                    "amount": rule_amount,
                                    "resulting_score": resulting_score,
                                    "cap": insight_cap,
                                },
                                status_code=409,
                            )
                        resolved_scores[ability] = resulting_score
                    else:  # The complete typed authority check above makes this unreachable.
                        raise FoundryError(
                            "CG1_BOUNDED_DECISION_REQUIRED",
                            "The selected Insight has no complete typed ability-change authority.",
                            details={"milestone_id": milestone_id, "insight_id": insight_id},
                            status_code=409,
                        )
                    rows.append(row("cultivation_insight_acquisition", cl, insight_id, parameters=parameters))
                else:
                    deltas = (
                        change_entry.get("deltas")
                        if isinstance(change_entry, dict) and "deltas" in change_entry
                        else change_entry
                    )
                    allowed_abilities = (
                        ability_change_rule.get("allowed_abilities")
                        if isinstance(ability_change_rule, dict)
                        else None
                    ) or ["STR", "DEX", "CON", "INT", "WIS", "CHA"]
                    allowed_deltas = (
                        ability_change_rule.get("allowed_deltas")
                        if isinstance(ability_change_rule, dict)
                        else []
                    )
                    budget = ability_change_rule.get("budget") if isinstance(ability_change_rule, dict) else None
                    if (
                        not isinstance(deltas, dict)
                        or not deltas
                        or any(
                            not isinstance(ability, str)
                            or ability not in allowed_abilities
                            or type(delta) is not int
                            or delta not in allowed_deltas
                            for ability, delta in deltas.items()
                        )
                        or type(budget) is not int
                        or sum(deltas.values()) != budget
                    ):
                        raise FoundryError(
                            "CG1_BOUNDED_DECISION_REQUIRED",
                            "The ability-score milestone does not match its exact source-backed rule.",
                            details={
                                "field": f"bounded_choices.ability_score_changes_by_milestone_id.{milestone_id}",
                                "milestone_id": milestone_id,
                                "effective_cl": cl,
                                "allowed_abilities": allowed_abilities,
                                "allowed_deltas": allowed_deltas,
                                "budget": budget,
                            },
                            status_code=409,
                        )
                    updated_scores = deepcopy(resolved_scores)
                    cap = ability_change_rule.get("cap") if isinstance(ability_change_rule, dict) else None
                    for ability, delta in deltas.items():
                        current_score = resolved_scores.get(ability)
                        if type(current_score) is not int or type(cap) is not int:
                            raise FoundryError(
                                "CG1_BOUNDED_DECISION_REQUIRED",
                                "The ability-score milestone has no authoritative current score or cap.",
                                details={
                                    "field": f"bounded_choices.ability_score_changes_by_milestone_id.{milestone_id}",
                                    "milestone_id": milestone_id,
                                    "ability": ability,
                                    "current_score": current_score,
                                    "cap": cap,
                                },
                                status_code=409,
                            )
                        resulting_score = current_score + delta
                        if resulting_score > cap:
                            raise FoundryError(
                                "CG1_BOUNDED_DECISION_REQUIRED",
                                "The ability-score milestone would exceed its source-backed score cap.",
                                details={
                                    "field": f"bounded_choices.ability_score_changes_by_milestone_id.{milestone_id}",
                                    "milestone_id": milestone_id,
                                    "effective_cl": cl,
                                    "ability": ability,
                                    "current_score": current_score,
                                    "delta": delta,
                                    "resulting_score": resulting_score,
                                    "cap": cap,
                                },
                                status_code=409,
                            )
                        updated_scores[ability] = resulting_score
                    resolved_scores = updated_scores
                    rows.append(row("ability_score_change", cl, milestone["feature_record_id"], parameters={"deltas": deepcopy(deltas)}))
                resolved_milestones.add(milestone_id)
            # Subpath milestones are Path-owned, not a single global CL3 row.
            # Emit every selected binding once when its owning Path publishes
            # the exact subpath-selection feature at or before the target CL.
            if cl >= 3:
                for owner_path, subpath_id in sorted(subpath_by_path.items()):
                    if subpath_id in emitted_subpath_ids:
                        continue
                    owner_authority = path_authority_by_id.get(owner_path) or {}
                    subpath_feature_cls = [
                        int(raw_cl)
                        for raw_cl, progression_row in (owner_authority.get("progression_by_cl") or {}).items()
                        if isinstance(raw_cl, str)
                        and raw_cl.isdigit()
                        and any(
                            path_feature_kind(records[feature]) == "subpath_selection"
                            for feature in (progression_row.get("feature_record_ids") or [])
                            if isinstance(feature, str) and feature in records
                        )
                    ]
                    if not subpath_feature_cls:
                        continue
                    subpath_record = require_record(subpath_id, "subpath_choice")
                    minimum = int(
                        subpath_record.get("legality", {}).get("minimum_cl")
                        or subpath_record.get("minimum_cl")
                        or 3
                    )
                    acquisition_cl = max(minimum, min(subpath_feature_cls))
                    if acquisition_cl <= cl:
                        rows.append(row("subpath_acquisition", acquisition_cl, subpath_id))
                        emitted_subpath_ids.add(subpath_id)
            # Constructed training is a causal ledger lane.  Emit each
            # selected row before the ordinary level Talent so a newly learned
            # Sphere (and its free bonus Talent) can authorize later choices
            # at the same CL.  The bonus remains a distinct acquisition event
            # and carries no trained-slot cost.
            for training_row in creation_training_rows_by_cl.get(cl, []):
                training_kind = (
                    CREATION_TRAINING_SPHERE_KIND
                    if training_row["choice_type"] == "new_sphere"
                    else CREATION_TRAINING_TALENT_KIND
                )
                training_parameters = {
                    "slot": training_row["slot"],
                    "choice_type": training_row["choice_type"],
                    "source": deepcopy(training_row["source"]),
                    "outcome": deepcopy(training_row["outcome"]),
                }
                if training_row["choice_type"] == "new_sphere":
                    training_parameters["bonus_talent_id"] = training_row["bonus_talent_id"]
                rows.append(row(training_kind, cl, training_row["record_id"], parameters=training_parameters))
                if training_row["choice_type"] == "new_sphere":
                    rows.append(row(
                        "new_sphere_bonus_talent_acquisition",
                        cl,
                        training_row["bonus_talent_id"],
                        parameters={
                            "entitlement_attempt_id": f"creation-training:{cl}:{training_row['slot']}:{training_row['record_id']}",
                        },
                    ))

            ordinary_index = cl - 1
            ordinary_id = ordinary_ids[ordinary_index]
            ordinary_record = require_record(ordinary_id, f"acquisition_intent.ordinary_talent_ids.{ordinary_index}")
            minimum = ordinary_minimum_cl(ordinary_record)
            if type(minimum) is int and minimum > cl:
                legal_ids = legal_ordinary_ids(cl, ordinary_index)
                raise FoundryError(
                    "CG1_BOUNDED_DECISION_REQUIRED",
                    f"The AI proposed {ordinary_id} for CL{cl}, but its source minimum CL is {minimum}. Choose a different source-backed ordinary Talent for CL{cl}.",
                    details={
                        "field": f"acquisition_intent.ordinary_talent_ids.{ordinary_index}",
                        "slot_id": "advancement_skeleton",
                        "operation": "set_field",
                        "effective_cl": cl,
                        "ordinary_talent_index": ordinary_index,
                        "proposed": ordinary_id,
                        "minimum_cl": minimum,
                        "allowed_choice_ids": legal_ids,
                        "allowed_count": len(legal_ids),
                    },
                    status_code=409,
                )
            rows.append(row("level_talent_acquisition", cl, ordinary_id))

        if set(subpath_ids) != emitted_subpath_ids:
            raise FoundryError(
                "CG1_SUBPATH_BINDING_UNRESOLVED",
                "Every selected Path-owned Subpath or Tradition must resolve to an authenticated Path milestone before compilation.",
                details={
                    "selected_subpath_ids": subpath_ids,
                    "materialized_subpath_ids": sorted(emitted_subpath_ids),
                    "unresolved_subpath_ids": sorted(set(subpath_ids) - emitted_subpath_ids),
                },
                status_code=409,
            )

        for item in intent_doc.get("compatibility_item_occurrences") or []:
            if not isinstance(item, dict) or not isinstance(item.get("record_id"), str):
                raise FoundryError(
                    "CG1_HISTORICAL_ITEM_UNRESOLVED",
                    "A compatibility item occurrence lacks a stable source record ID.",
                    status_code=422,
                )
            item_record = require_record(item["record_id"], "compatibility_item_occurrences.record_id")
            item_authority = item_record.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {}
            allowed_cls = item_authority.get("allowed_cls") or item_authority.get("allowed_effective_cls") or []
            if isinstance(allowed_cls, list) and len(allowed_cls) == 1 and isinstance(allowed_cls[0], int):
                item_cl = allowed_cls[0]
            else:
                item_cl = item_authority.get("minimum_cl")
            if type(item_cl) is not int:
                raise FoundryError(
                    "CG1_HISTORICAL_ITEM_UNRESOLVED",
                    "A compatibility item occurrence has no uniquely source-derived effective CL.",
                    details={"record_id": item["record_id"], "allowed_cls": allowed_cls},
                    status_code=422,
                )
            rows.append(row(None, item_cl, item["record_id"], parameters=item.get("parameters") or {}))

        advertised_milestone_ids = {
            row.get("milestone_id")
            for row in (run.get("request", {}).get("delegated_choice_envelope", {}).get("advancement_choice_milestones") or [])
            if isinstance(row, dict) and isinstance(row.get("milestone_id"), str)
        }
        # The response schema intentionally advertises the source inventory
        # for every offered Path, while the selected CL progression determines
        # which Path-owned milestones are acquired.  Keep source-backed
        # choices for a non-advancing Path as planning intent (the owner view
        # still shows them), but do not turn them into acquisitions or force a
        # full response replacement.  Anything outside the sealed inventory
        # remains a hard legality failure.
        non_acquiring_insights = set(insight_by_milestone) - set(expected_milestones)
        non_acquiring_asi = set(asi_by_milestone) - set(expected_milestones)
        for milestone_id in non_acquiring_insights:
            if milestone_id in advertised_milestone_ids:
                insight_by_milestone.pop(milestone_id, None)
        for milestone_id in non_acquiring_asi:
            if milestone_id in advertised_milestone_ids:
                asi_by_milestone.pop(milestone_id, None)
        unknown_insights = sorted(set(insight_by_milestone) - set(expected_milestones))
        unknown_asi = sorted(set(asi_by_milestone) - set(expected_milestones))
        if unknown_insights or unknown_asi:
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "A response supplied a resolution for a milestone that is not advertised by the frozen Path authority.",
                details={"unknown_insight_milestone_ids": unknown_insights, "unknown_ability_score_milestone_ids": unknown_asi},
                status_code=409,
            )
        if resolved_milestones != set(expected_milestones):
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "Every advertised advancement milestone must be resolved exactly once.",
                details={"expected_milestone_ids": sorted(expected_milestones), "resolved_milestone_ids": sorted(resolved_milestones)},
                status_code=409,
            )

        def none_parameters(target: str, reason: str) -> dict[str, Any]:
            return {
                "target": target,
                "reason_code": "not_selected_for_c1a_proof",
                "reason": reason,
            }

        if not method_ids:
            rows.append(row("typed_none", target_cl, "tianxia.c1a.none.method", parameters=none_parameters("method", "No exact Method was selected for this bounded character response.")))
        if not foundation_ids:
            rows.append(row("typed_none", target_cl, "tianxia.c1a.none.foundation", parameters=none_parameters("foundation", "No exact Foundation was selected for this bounded character response.")))
        # A lineage Manual is an actual source-access event.  Construct it
        # from the CL1 rows before resolving any child event authority, then
        # insert its source and child acquisitions at their causal CL
        # boundaries.  Synthetic/unit fixtures may have no installed published
        # source block; retain their explicit typed-none result rather than
        # inventing a quote.
        from character_creation.constructed_arts.manual import (
            MANUAL_ACCESS_MODE,
            RECORDED_ART_CONSTRUCTION_KIND,
            manual_outcome,
        )
        manual_bundles: list[dict[str, Any]] = []
        manual_records: list[dict[str, Any]] = []
        if include_manual_collection:
            try:
                manual_bundles, manual_records, manual_collection_roll = self._manual_collection_constructions(
                    run,
                    project,
                    intent_doc,
                    rows,
                    records,
                    target_cl,
                    intent_hash=intent.intent_hash,
                )
            except FoundryError as exc:
                request_doc = run.get("request") if isinstance(run, dict) else None
                strict_creation_request = (
                    isinstance(request_doc, dict)
                    and isinstance(request_doc.get("request_sha256"), str)
                    and len(request_doc["request_sha256"]) == 64
                )
                if (
                    exc.code != "CG1_MANUAL_CONSTRUCTION_AUTHORITY_MISSING"
                    or strict_creation_request
                ):
                    raise
        if manual_bundles:
            records.update({
                record["record_id"]: record
                for record in manual_records
                if isinstance(record, dict) and isinstance(record.get("record_id"), str)
            })
            scheduled_manual_rows: list[dict[str, Any]] = []
            for manual_index, manual_bundle in enumerate(manual_bundles):
                manual_id = manual_bundle["manual"]["record_id"]
                scheduled_manual_rows.append(
                    row(
                        "training_source_access",
                        1,
                        manual_id,
                        parameters={"access_mode": MANUAL_ACCESS_MODE},
                    )
                )
            # A new server-owned collection grants source access only.  The
            # historical first-bundle study lane is retained solely for an
            # identified old request with no versioned collection authority.
            request_authority = (run.get("request") or {}).get("server_owned_authority") if isinstance(run, dict) else None
            has_new_collection_policy = isinstance(request_authority, Mapping) and isinstance(request_authority.get("manual_collection"), Mapping)
            acquisition_authority = intent_doc.get("acquisition_intent") if isinstance(intent_doc, Mapping) else None
            has_explicit_collection = isinstance(acquisition_authority, Mapping) and isinstance(acquisition_authority.get("manual_collection"), Mapping)
            if not has_new_collection_policy and not has_explicit_collection:
                manual_bundle = manual_bundles[0]
                learned_count = min(3, 1 + int(target_cl) // 4)
                for ordinal in range(learned_count):
                    art = manual_bundle["recorded_arts"][ordinal]
                    scheduled_cl = min(int(target_cl), 1 + 2 * ordinal)
                    if type(art.get("minimum_cl")) is int and scheduled_cl < art["minimum_cl"]:
                        # Owning a printed higher-CL technique does not learn
                        # or execute it during creation; its later legal study
                        # event remains a separate causal choice.
                        continue
                    scheduled_manual_rows.append(
                        row(
                            RECORDED_ART_CONSTRUCTION_KIND,
                            scheduled_cl,
                            art["record_id"],
                            parameters={
                                "study_ability": art["allowed_study_abilities"][0],
                                "outcome": manual_outcome(),
                            },
                        )
                    )
            # Rows are already grouped by CL, but the tail contains historical
            # compatibility items.  Insert before the next level_advance so
            # source access precedes the child at CL1 and all existing order is
            # otherwise preserved.
            for scheduled in scheduled_manual_rows:
                scheduled_cl = int(scheduled["effective_cl"])
                boundary = next(
                    (
                        index
                        for index, existing in enumerate(rows)
                        if existing.get("kind") == "level_advance"
                        and type(existing.get("effective_cl")) is int
                        and existing["effective_cl"] > scheduled_cl
                    ),
                    len(rows),
                )
                rows.insert(boundary, scheduled)

        # Forged Techniques are constructed by the Factory from what the
        # character already knows (Core §11); a CL5+ character forges rather
        # than reporting an absence.
        constructed = self._forged_technique_constructions(
            run, project, intent_doc, rows, records, target_cl, intent_hash=intent.intent_hash,
        )
        request_authority = (run.get("request") or {}).get("server_owned_authority") if isinstance(run, Mapping) else None
        manual_marker = request_authority.get("manual_collection") if isinstance(request_authority, Mapping) else None
        creator_policy_active = (
            isinstance(manual_marker, Mapping)
            and manual_marker.get("authority_version") == "server_owned_pre_provider.v2"
        )
        creator_ability_scores: dict[str, int] = {}
        if creator_policy_active:
            # Rebuild the causal ability state used by Stage 2.  The creator
            # proof must carry this server-derived modifier; it cannot come
            # from a constructed technique or provider response.
            for entry in rows:
                if (
                    not isinstance(entry, Mapping)
                    or type(entry.get("effective_cl")) is not int
                    or entry["effective_cl"] > target_cl
                ):
                    continue
                params = entry.get("parameters") if isinstance(entry.get("parameters"), Mapping) else {}
                kind = entry.get("kind")
                if kind == "starting_state":
                    source_scores = params.get("ability_scores")
                    if isinstance(source_scores, Mapping):
                        creator_ability_scores = {
                            key: value
                            for key, value in source_scores.items()
                            if isinstance(key, str) and type(value) is int
                        }
                elif kind in {"background_acquisition", "cultivation_insight_acquisition"}:
                    ability = params.get("ability")
                    amount = params.get("amount")
                    if isinstance(ability, str) and type(amount) is int and ability in creator_ability_scores:
                        creator_ability_scores[ability] += amount
                elif kind == "ability_score_change":
                    deltas = params.get("deltas")
                    if isinstance(deltas, Mapping):
                        for ability, amount in deltas.items():
                            if isinstance(ability, str) and type(amount) is int and ability in creator_ability_scores:
                                creator_ability_scores[ability] += amount
        for index, (technique, record) in enumerate(constructed):
            records[record["record_id"]] = record
            technique_key_ability = technique.get("key_ability")
            creator_ability_modifier = None
            if creator_policy_active:
                creator_score = creator_ability_scores.get(technique_key_ability)
                if type(creator_score) is not int:
                    raise FoundryError(
                        "CG1_FORGING_CREATION_AUTHORITY_INVALID",
                        "The causal creation rows do not provide the selected Path's ability score for Forged Technique acquisition.",
                        details={"key_ability": technique_key_ability, "target_cl": target_cl},
                        status_code=409,
                    )
                creator_ability_modifier = math.floor((creator_score - 10) / 2)
            forging_parameters = self._forged_technique_creation_parameters(
                run,
                technique,
                record,
                index=index,
                intent_hash=intent.intent_hash,
                ability_modifier=creator_ability_modifier,
            )
            rows.append(
                row(
                    "forged_technique_creation",
                    target_cl,
                    record["record_id"],
                    parameters=(
                        {"forging_acquisition": forging_parameters}
                        if forging_parameters is not None
                        else None
                    ),
                )
            )
        immortal_constructed = self._stable_immortal_arts(
            run,
            project,
            intent_doc,
            rows,
            records,
            target_cl,
            intent_hash=intent.intent_hash,
        )
        for art, record, refinement_parameters in immortal_constructed:
            records[record["record_id"]] = record
            art_row = row(
                "immortal_art_creation",
                int(art["cl_created"]),
                record["record_id"],
                parameters=(
                    {"immortal_refinement": refinement_parameters}
                    if refinement_parameters is not None
                    else None
                ),
            )
            # An Art is a mechanical event at the CL where its source was
            # actually attained.  Keep every existing row in its established
            # order, place the Art after all rows at that CL, and stop before
            # the first later effective-CL row.  Appending these rows would
            # replay a CL15 Art after CL20 and make Stage 2 reject it as
            # historical backdating.
            self._insert_stage2_row_at_effective_cl(rows, art_row)
        # Immortal Arts become a required absence authority only at their
        # first legal realm boundary; low-CL compatibility streams never
        # claim a subsystem that is not yet due.
        # The controller's starting kit (printed Background kit plus the highest
        # Path's kit) is one constructed item record acquired at CL1.
        starting_kit = self._starting_kit_construction(
            intent_doc, intent.intent_hash, int(target_cl),
            owner_gear_preferences=(run.get("request") or {}).get("owner_gear_preferences") or [],
            owner_gear_requirements=(run.get("request") or {}).get("owner_gear_requirements") or [],
            run=run,
        )
        if starting_kit is not None:
            _kit, kit_record = starting_kit
            records[kit_record["record_id"]] = kit_record
            self._insert_stage2_row_at_effective_cl(rows, row("equipment_acquisition", 1, kit_record["record_id"]))
        none_targets = ("manuals", "equipment", "forged_techniques")
        if int(target_cl) >= 15:
            none_targets += ("immortal_arts",)
        for target in none_targets:
            if target == "equipment" and starting_kit is not None:
                continue
            if target == "manuals" and manual_bundles:
                continue
            if target == "forged_techniques" and constructed:
                continue
            if target == "immortal_arts" and immortal_constructed:
                continue
            rows.append(row("typed_none", target_cl, f"tianxia.c1a.none.{target}", parameters=none_parameters(target, f"No {target.replace('_', ' ')} was selected.")))
        return self._unique_rows(rows)

    @staticmethod
    def _starting_kit_construction(
        intent_doc: Any,
        intent_hash: str,
        target_cl: int,
        *,
        owner_gear_preferences: Sequence[str] = (),
        owner_gear_requirements: Sequence[Mapping[str, Any]] = (),
        run: dict[str, Any] | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any]] | None:
        """Resolve the controller's starting-kit decision into its constructed record."""
        from character_creation.constructed_arts.records import build_starting_kit_record, construct_starting_kit
        from factory_authoring.starting_kits import deterministic_kit_coin_cc, gear_catalog, has_starting_kit, highest_path, owner_gear_requirements_affordable
        from factory_authoring.treasure_weapons import CAPACITY_RULES_CURRENT as TREASURE_CAPACITY_RULES

        if not isinstance(intent_doc, Mapping):
            return None
        decision = (intent_doc.get("acquisition_intent") or {}).get("starting_kit")
        selected = intent_doc.get("selected_by_slot") or {}
        backgrounds = [value for value in selected.get("background_choice") or [] if isinstance(value, str)]
        paths = list(dict.fromkeys(value for value in selected.get("path_choice") or [] if isinstance(value, str)))
        progression = (intent_doc.get("bounded_choices") or {}).get("path_progression_by_cl")
        path_id = highest_path(paths, progression if isinstance(progression, Mapping) else None) if paths else None
        required = [dict(row) for row in owner_gear_requirements
                    if isinstance(row, Mapping) and isinstance(row.get("item_id"), str)]
        if not required:
            names = {row["item_id"]: row["name"] for row in gear_catalog()}
            required = [{"name": names.get(item_id, item_id), "item_id": item_id} for item_id in owner_gear_preferences if isinstance(item_id, str) and item_id]
        required_ids = [row["item_id"] for row in required]
        if not isinstance(decision, Mapping):
            preferences = [value for value in owner_gear_preferences if isinstance(value, str) and value]
            if len(backgrounds) == 1 and path_id and has_starting_kit(backgrounds[0], path_id) and preferences:
                affordable = any(
                    owner_gear_requirements_affordable(
                        backgrounds[0], path_id, option, required_ids,
                        remaining_coin_cc=deterministic_kit_coin_cc(backgrounds[0], path_id, option),
                    ) for option in ("option_a", "option_b")
                )
                if required and affordable:
                    required_names = ", ".join(row["name"] for row in required)
                    raise FoundryError(
                        "CG1_OWNER_NAMED_GEAR_MISSING",
                        f"The plan leaves out owner-named gear that fits the legal starting kit and its shared funds: {required_names}. Add each named item to the starting kit.",
                        details={"required_items": required}, status_code=422,
                    )
                if required and run is not None:
                    names = ", ".join(row["name"] for row in required)
                    run.setdefault("_derived_owner_gear_warnings", []).append(
                        f"{names} couldn't all be added because the legal starting-kit choices and guaranteed coin don't cover them together. These items are optional; either starting kit is allowed."
                    )
            elif preferences and run is not None:
                names = {row["item_id"]: row["name"] for row in gear_catalog()}
                run.setdefault("_derived_owner_gear_warnings", []).extend(
                    f"{names.get(item_id, item_id)} couldn't be added because the selected Background and Path have no supported starting kit."
                    for item_id in preferences
                )
            elif preferences:
                raise FoundryError(
                    "CG1_OWNER_NAMED_GEAR_MISSING",
                    "The selected Background and Path have no supported starting kit for the owner-named gear.",
                    details={"required_items": required}, status_code=422,
                )
            return None
        if len(backgrounds) != 1 or path_id is None or not has_starting_kit(backgrounds[0], path_id):
            raise FoundryError(
                "CG1_STARTING_KIT_UNRESOLVED",
                "The starting-kit decision needs one Background and a Path with a published kit.",
                details={"background_ids": backgrounds, "path_id": path_id},
                status_code=409,
            )
        kit = construct_starting_kit(
            background_id=backgrounds[0],
            path_id=path_id,
            path_option=str(decision.get("path_option")),
            picks=dict(decision.get("picks") or {}),
            seed=intent_hash,
            purchases=list(decision.get("purchases") or []),
            treasure_weapon=(
                {**decision["treasure_weapon"], "target_cl": int(target_cl), "capacity_rules": TREASURE_CAPACITY_RULES}
                if isinstance(decision.get("treasure_weapon"), Mapping) else None
            ),
            treasure_armor=(
                {**decision["treasure_armor"], "target_cl": int(target_cl), "capacity_rules": TREASURE_CAPACITY_RULES}
                if isinstance(decision.get("treasure_armor"), Mapping) else None
            ),
            treasure_purchases=(
                {**decision["treasure_purchases"], "target_cl": int(target_cl)}
                if isinstance(decision.get("treasure_purchases"), Mapping) else None
            ),
        )
        preferences = [value for value in owner_gear_preferences if isinstance(value, str) and value]
        if preferences or required:
            resolved = kit.get("resolved") or {}
            actual = {row.get("item_id") for row in resolved.get("items") or []}
            retained = {row.get("item_id") for row in resolved.get("items") or [] if row.get("source") == "purchase"}
            for treasure_key in ("treasure_weapon", "treasure_armor"):
                chassis_id = (((resolved.get(treasure_key) or {}).get("chassis") or {}).get("item_id"))
                if isinstance(chassis_id, str):
                    actual.add(chassis_id)
                    retained.add(chassis_id)
            missing = [row for row in required if row["item_id"] not in actual]
            spent = sum(int(row.get("value_cc") or 0) for row in resolved.get("items") or []
                        if row.get("source") == "purchase")
            guaranteed_coin = deterministic_kit_coin_cc(
                backgrounds[0], path_id, str(decision.get("path_option")), picks=decision.get("picks"),
            )
            affordable = owner_gear_requirements_affordable(
                backgrounds[0], path_id, str(decision.get("path_option")), required_ids,
                remaining_coin_cc=max(0, guaranteed_coin - spent),
                retained_item_ids=retained,
            )
            # Option A and Option B are both legal printed kits. If the owner
            # chose A, also check whether all owner requirements fit the
            # shared Option B funds before describing them as unavailable.
            if not affordable and str(decision.get("path_option")) == "option_a":
                affordable = owner_gear_requirements_affordable(
                    backgrounds[0], path_id, "option_b", required_ids,
                    remaining_coin_cc=deterministic_kit_coin_cc(
                        backgrounds[0], path_id, "option_b", picks=decision.get("picks"),
                    ),
                    retained_item_ids=retained,
                )
            if missing and affordable:
                required_names = ", ".join(row["name"] for row in missing)
                raise FoundryError(
                    "CG1_OWNER_NAMED_GEAR_MISSING",
                    f"The starting kit leaves out owner-named gear that fits the legal kit and its shared funds: {required_names}. Add each named item to the kit.",
                    details={"required_items": missing},
                    status_code=422,
                )
            if missing and not affordable and run is not None:
                names = ", ".join(row["name"] for row in missing)
                message = (
                    f"{names} couldn't all be added because the legal starting-kit choices and remaining guaranteed coin don't cover them together. These items are optional; either starting kit is allowed."
                    if len(missing) > 1 else
                    f"{missing[0]['name']} isn't covered by the guaranteed starting-kit coin, so it is optional and wasn't added. Either starting kit is allowed; rolled coin counts only at its minimum for required gear."
                )
                run.setdefault("_derived_owner_gear_warnings", []).extend(
                    [message]
                )
        return kit, build_starting_kit_record(kit)

    _TALENT_ROW_KINDS = frozenset({
        "sect_trial_talent_acquisition",
        "ai_bootstrap_talent_acquisition",
        "background_talent_acquisition",
        "level_talent_acquisition",
        "creation_training_talent_acquisition",
        "new_sphere_bonus_talent_acquisition",
        "talent_training_attempt",
    })
    _SPHERE_ROW_KINDS = frozenset({
        "sect_trial_sphere_acquisition",
        "ai_bootstrap_sphere_acquisition",
        "background_sphere_acquisition",
        "creation_training_sphere_acquisition",
        "sphere_training_attempt",
    })
    _PATH_DEFAULT_KEY_ABILITY = {
        "tianxia.path.body_refining": "CON",
        "tianxia.path.qi_cultivation": "INT",
        "tianxia.path.spirit_awakening": "WIS",
    }

    @staticmethod
    def _forged_technique_count(target_cl: int, pb: int) -> int:
        """Factory policy: one signature technique at Foundation, another every three CLs, never above PB."""
        if target_cl < 5:
            return 0
        return max(0, min(pb, 1 + (target_cl - 5) // 3))

    @staticmethod
    def _constructed_recipe_intent_hash(
        run: Mapping[str, Any], intent_doc: Mapping[str, Any], intent_hash: str,
    ) -> str:
        """Exclude generated Manual identities only for new seeded requests.

        The persisted nonce versions this contract. Historical requests keep
        their exact constructor seeds; project-specific provenance still goes
        into the constructors, but never into this semantic seed input.
        """
        marker = ((run.get("request") or {}).get("server_owned_authority") or {}).get("manual_collection") or {}
        if not str(marker.get("nonce", "")).startswith("cg1.autogen.v1."):
            return intent_hash
        document = {
            key: deepcopy(intent_doc.get(key))
            for key in (
                "target_cl", "selected_by_slot", "planning_preferences_by_slot",
                "acquisition_intent", "bounded_choices", "historical_stage2_rows",
                "compatibility_item_occurrences",
            )
        }
        acquisition = document.get("acquisition_intent")
        if isinstance(acquisition, dict):
            acquisition.pop("manual_collection", None)
        return sha256_json(document)

    @staticmethod
    def _autogeneration_seed(project: Mapping[str, Any]) -> str | None:
        """Read a valid user seed; this alone does not version old requests."""
        from character_creation.creative_controller import seeded_picker

        seed_value = next(
            (row.get("value") for row in (project.get("user_locks") or [])
             if isinstance(row, Mapping) and row.get("field") == seeded_picker.SEED_LOCK_FIELD),
            None,
        )
        return seeded_picker.valid_seed(seed_value)

    @staticmethod
    def _constructed_recipe_seed(
        project: Mapping[str, Any], intent_hash: str, recipe_kind: str, ordinal: int = 0,
        *, legacy_seed: str, run: Mapping[str, Any] | None = None,
    ) -> str:
        """Opt in only via persisted v1 nonce; all older seeds stay exact."""
        marker = (((run or {}).get("request") or {}).get("server_owned_authority") or {}).get("manual_collection") or {}
        if not str(marker.get("nonce", "")).startswith("cg1.autogen.v1."):
            return legacy_seed
        autogen_seed = CharacterCreationExecutionService._autogeneration_seed(project)
        if not autogen_seed:
            return legacy_seed
        return f"{autogen_seed}:{intent_hash}:{recipe_kind}:{ordinal}"

    def _manual_request_context(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        rows: list[dict[str, Any]],
        records: dict[str, dict[str, Any]],
        target_cl: int,
        *,
        intent_hash: str,
        require_known_talent: bool = True,
    ) -> tuple[dict[str, Any], list[dict[str, Any]], list[dict[str, Any]], Path, str, str, dict[str, Any]]:
        """Resolve Path/lineage context while keeping possession separate from learning."""
        from character_creation.constructed_arts.sources import installed_factory_root, published_block

        cl = max(1, int(target_cl))
        pb = 2 + (cl - 1) // 4
        initial_rows = [
            entry for entry in rows
            if isinstance(entry, dict) and type(entry.get("effective_cl")) is int and entry.get("effective_cl") <= 1
        ]
        sphere_ids: list[str] = []
        talent_ids: list[str] = []
        for entry in initial_rows:
            record_id = entry.get("record_id")
            record = records.get(record_id) if isinstance(record_id, str) else None
            if not isinstance(record, dict):
                continue
            if entry.get("kind") in self._SPHERE_ROW_KINDS and record.get("content_type") == "sphere" and record_id not in sphere_ids:
                sphere_ids.append(record_id)
            elif entry.get("kind") in self._TALENT_ROW_KINDS and record.get("content_type") == "talent" and record_id not in talent_ids:
                talent_ids.append(record_id)
        path_id = next((entry.get("record_id") for entry in rows if entry.get("kind") == "path_acquisition" and isinstance(entry.get("record_id"), str)), None)
        if not isinstance(path_id, str):
            raise FoundryError("CG1_MANUAL_CONSTRUCTION_AUTHORITY_MISSING", "A lineage Manual requires one authenticated Path source.", status_code=409)
        path_record = records.get(path_id) or {}
        path_authority = (((path_record.get("compatibility") or {}).get("factory") or {}).get("stage2_authority") or {})
        key_ability = path_authority.get("key_ability")
        if key_ability not in {"STR", "DEX", "CON", "INT", "WIS", "CHA"}:
            key_ability = self._PATH_DEFAULT_KEY_ABILITY.get(path_id, "INT")
        factory_root = installed_factory_root(self.db.settings.vendor_dir)
        spheres = [
            {"sphere_id": sphere_id, "display_name": records[sphere_id].get("display_name") or sphere_id}
            for sphere_id in sphere_ids
            if isinstance(records.get(sphere_id), dict)
        ]
        sphere_set = {row["sphere_id"] for row in spheres}
        talents: list[dict[str, Any]] = []
        for talent_id in talent_ids:
            talent_record = records.get(talent_id)
            if not isinstance(talent_record, dict):
                continue
            authority = (((talent_record.get("compatibility") or {}).get("factory") or {}).get("stage2_authority") or {})
            sphere_id = authority.get("sphere_id")
            if not isinstance(sphere_id, str) or sphere_id not in sphere_set:
                continue
            source = talent_record.get("source")
            if not isinstance(source, dict):
                continue
            quoted = published_block(factory_root, source)
            if not quoted:
                continue
            talents.append({
                "talent_id": talent_id,
                "sphere_id": sphere_id,
                "display_name": talent_record.get("display_name") or talent_id,
                "record_hash": talent_record.get("record_hash"),
                "source": deepcopy(source),
                "published_text": quoted,
                "access_category": authority.get("access_category"),
                "minimum_cl": authority.get("minimum_cl", talent_record.get("minimum_cl", 1)) or 1,
            })
        if require_known_talent and not talents:
            raise FoundryError("CG1_MANUAL_CONSTRUCTION_AUTHORITY_MISSING", "No CL1 Talent has a hash-verified published block and source-assigned access category for the lineage Manual.", status_code=409)
        lineage_source: dict[str, Any] = {}
        sect_trial = next((entry.get("record_id") for entry in initial_rows if entry.get("kind") == "sect_trial_sphere_acquisition" and isinstance(entry.get("record_id"), str)), None)
        background = next((entry.get("record_id") for entry in initial_rows if entry.get("kind") == "background_acquisition" and isinstance(entry.get("record_id"), str)), None)
        if isinstance(sect_trial, str):
            lineage_source["sect_trial_sphere_id"] = sect_trial
        if isinstance(background, str):
            lineage_source["background_id"] = background
        request_authority = (run.get("request") or {}).get("server_owned_authority") if isinstance(run, Mapping) else None
        collection_marker = request_authority.get("manual_collection") if isinstance(request_authority, Mapping) else None
        request_seed = (
            collection_marker.get("seed")
            if isinstance(collection_marker, Mapping) and isinstance(collection_marker.get("seed"), str)
            else self._constructed_recipe_seed(
                project, intent_hash, "manual",
                legacy_seed=f"{run['project_id']}:{intent_hash}:manual",
                run=run,
            )
        )
        request = {
            "schema": "TianxiaFoundry.LineageManualRequest.v1",
            "seed": request_seed,
            "project_id": run["project_id"],
            "cl": cl,
            "pb": pb,
            "path_id": path_id,
            "key_ability": key_ability,
            "known_spheres": spheres,
            "known_talents": talents,
            "lineage_source": lineage_source,
        }
        return request, initial_rows, spheres, factory_root, path_id, key_ability, lineage_source

    def _manual_constructions(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        intent_doc: dict[str, Any],
        rows: list[dict[str, Any]],
        records: dict[str, dict[str, Any]],
        target_cl: int,
        *,
        intent_hash: str,
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        """Construct one lineage Manual and its complete three-art bundle.

        The source candidates are limited to records causally available at
        CL1.  This prevents a later Talent from becoming an unearned parent
        component while allowing the Manual to retain all three fixed entries
        when the initial pool is smaller (the constructor marks repetitions).
        """
        from character_creation.constructed_arts.manual import MANUAL_ACCESS_MODE, MANUAL_CHANNEL, construct_lineage_manual
        from character_creation.constructed_arts.records import build_lineage_manual_records
        request, _initial_rows, _spheres, _factory_root, _path_id, _key_ability, _lineage_source = self._manual_request_context(
            run, project, rows, records, target_cl, intent_hash=intent_hash, require_known_talent=True
        )
        bundle = construct_lineage_manual(request)
        return bundle, build_lineage_manual_records(bundle)

    def _manual_collection_constructions(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        intent_doc: dict[str, Any],
        rows: list[dict[str, Any]],
        records: dict[str, dict[str, Any]],
        target_cl: int,
        *,
        intent_hash: str,
        dice_faces: list[int] | None = None,
        persisted_roll: Mapping[str, Any] | None = None,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any] | None]:
        """Construct owned Manuals from locked printed contents.

        A missing ``manual_collection`` field is the historical one-Manual
        contract.  The new collection path authenticates every requested
        content ID/hash/source against the project lock before the pure
        constructor ever sees it; the field never grants a learned Talent.
        """
        from character_creation.constructed_arts.manual import (
            construct_lineage_manual_collection,
            roll_manual_collection_count,
            validate_manual_collection_roll,
        )
        cl = max(1, int(target_cl))
        acquisition = intent_doc.get("acquisition_intent") if isinstance(intent_doc, Mapping) else None
        authority = acquisition.get("manual_collection") if isinstance(acquisition, Mapping) else None
        explicit_collection = isinstance(authority, Mapping)
        request_authority = (run.get("request") or {}).get("server_owned_authority") if isinstance(run, Mapping) else None
        server_marker = request_authority.get("manual_collection") if isinstance(request_authority, Mapping) else None
        if not explicit_collection and dice_faces is None and persisted_roll is None and not isinstance(server_marker, Mapping):
            # Accepted legacy plans keep their original single Manual identity.
            legacy_bundle, legacy_records = self._manual_constructions(
                run, project, intent_doc, rows, records, target_cl, intent_hash=intent_hash
            )
            return [legacy_bundle], legacy_records, None

        request, initial_rows, base_spheres, factory_root, _path_id, _key_ability, _lineage_source = self._manual_request_context(
            run, project,
            rows,
            records,
            target_cl,
            intent_hash=intent_hash,
            require_known_talent=False,
        )
        request_sha = ((run.get("request") or {}).get("request_sha256") if isinstance(run.get("request"), Mapping) else None)
        seed = (
            server_marker.get("seed")
            if isinstance(server_marker, Mapping) and isinstance(server_marker.get("seed"), str)
            else self._constructed_recipe_seed(
                project, intent_hash, "manual_collection",
                legacy_seed=f"{run['project_id']}:{request_sha or intent_hash}:manual_collection",
                run=run,
            )
        )
        if isinstance(server_marker, Mapping) and persisted_roll is None:
            persisted_roll = server_marker.get("roll")
        expected_roll = roll_manual_collection_count(cl, seed=seed, dice_faces=dice_faces)
        raw_roll = authority.get("roll") if explicit_collection else persisted_roll
        if raw_roll is not None:
            roll = validate_manual_collection_roll(raw_roll, cl=cl)
            if dice_faces is None and roll != expected_roll:
                raise FoundryError(
                    "CG1_MANUAL_COLLECTION_ROLL_MISMATCH",
                    "The persisted Manual collection roll does not rederive from the bound server policy seed.",
                    details={"expected": expected_roll, "actual": roll},
                    status_code=409,
                )
        else:
            roll = expected_roll

        requested_manuals = authority.get("manuals") if explicit_collection else None
        if requested_manuals is not None and (not isinstance(requested_manuals, list) or len(requested_manuals) != roll["total"]):
            raise FoundryError(
                "CG1_MANUAL_COLLECTION_AUTHORITY_INVALID",
                "The persisted Manual collection must contain one entry per rolled count.",
                status_code=409,
            )

        # Derive candidate printed contents only from locked, source-verifiable
        # Talent records.  The candidate may be above the character's CL; its
        # minimum CL is carried into the child record and blocks premature use.
        from character_creation.constructed_arts.sources import published_block
        candidates: dict[str, dict[str, Any]] = {}
        for record_id, record in sorted(records.items()):
            if not isinstance(record_id, str) or not isinstance(record, Mapping) or record.get("content_type") != "talent":
                continue
            stage2_authority = (((record.get("compatibility") or {}).get("factory") or {}).get("stage2_authority") or {})
            sphere_id = stage2_authority.get("sphere_id")
            source = record.get("source")
            if not isinstance(sphere_id, str) or not isinstance(source, Mapping) or not isinstance(record.get("record_hash"), str):
                continue
            sphere_record = records.get(sphere_id)
            if not isinstance(sphere_record, Mapping) or sphere_record.get("content_type") != "sphere":
                continue
            quoted = published_block(factory_root, source)
            access_category = stage2_authority.get("access_category")
            minimum_cl = stage2_authority.get("minimum_cl", record.get("minimum_cl"))
            if not quoted or not isinstance(access_category, str) or type(minimum_cl) is not int or not 1 <= minimum_cl <= 20:
                continue
            candidates[record_id] = {
                "talent_id": record_id,
                "sphere_id": sphere_id,
                "display_name": record.get("display_name") or record_id,
                "record_hash": record["record_hash"],
                "source": deepcopy(dict(source)),
                "published_text": quoted,
                "access_category": access_category,
                "minimum_cl": minimum_cl,
            }
        if len(candidates) < 3:
            raise FoundryError(
                "CG1_MANUAL_COLLECTION_CONTENTS_INSUFFICIENT",
                "The project lock has fewer than three source-verified Talent contents for a Manual.",
                details={"available_content_count": len(candidates)},
                status_code=409,
            )

        manual_contents: list[list[dict[str, Any]]] = []
        collection_ids: list[str] = []
        seen_content_tuples: set[tuple[str, ...]] = set()
        if explicit_collection:
            for index, item in enumerate(requested_manuals or []):
                if not isinstance(item, Mapping):
                    raise FoundryError("CG1_MANUAL_COLLECTION_AUTHORITY_INVALID", "Each persisted Manual collection entry must be an object.", status_code=409)
                collection_id = item.get("collection_id")
                content_ids = item.get("content_record_ids")
                bindings = item.get("content_record_bindings")
                if not isinstance(collection_id, str) or not collection_id or not isinstance(content_ids, list) or len(content_ids) != 3 or len(set(content_ids)) != 3 or not isinstance(bindings, list) or len(bindings) != 3:
                    raise FoundryError("CG1_MANUAL_COLLECTION_AUTHORITY_INVALID", "Each persisted Manual collection entry must carry three distinct content IDs and bindings.", details={"index": index}, status_code=409)
                content_tuple = tuple(sorted(content_ids))
                if content_tuple in seen_content_tuples:
                    raise FoundryError("CG1_MANUAL_COLLECTION_CONTENT_DUPLICATE", "Distinct owned Manuals must carry distinct whole printed-content tuples; individual teachings may overlap.", details={"index": index, "content_record_ids": list(content_ids)}, status_code=409)
                seen_content_tuples.add(content_tuple)
                entry_rows: list[dict[str, Any]] = []
                for content_index, content_id in enumerate(content_ids):
                    candidate = candidates.get(content_id)
                    binding = bindings[content_index] if content_index < len(bindings) else None
                    if candidate is None or not isinstance(binding, Mapping) or binding.get("record_id") != content_id or binding.get("record_hash") != candidate["record_hash"] or binding.get("source") != candidate["source"]:
                        raise FoundryError("CG1_MANUAL_COLLECTION_CONTENT_BINDING_INVALID", "A persisted Manual content binding does not match the locked source record.", details={"index": index, "content_index": content_index, "record_id": content_id}, status_code=409)
                    entry_rows.append(deepcopy(candidate))
                collection_ids.append(collection_id)
                manual_contents.append(entry_rows)
        else:
            groups: dict[str, list[dict[str, Any]]] = {}
            for candidate in candidates.values():
                groups.setdefault(candidate["sphere_id"], []).append(candidate)
            groups = {sphere_id: sorted(rows_for_sphere, key=lambda row: row["talent_id"]) for sphere_id, rows_for_sphere in groups.items() if len(rows_for_sphere) >= 3}
            if not groups:
                raise FoundryError("CG1_MANUAL_COLLECTION_COHERENT_CONTENTS_INSUFFICIENT", "The locked catalog cannot provide any whole-book content tuple.", details={"requested_count": roll["total"]}, status_code=409)
            # A realistic library: books from the Spheres the character knows,
            # interleaved with books from other traditions (two known : one
            # other), cycling so no single Sphere supplies the whole shelf.
            known_ids = {row.get("sphere_id") for row in base_spheres if isinstance(row, Mapping)}
            seeded = sorted(groups, key=lambda sphere_id: hashlib.sha256(f"{seed}:{sphere_id}".encode("utf-8")).hexdigest())
            known_order = [sphere_id for sphere_id in seeded if sphere_id in known_ids]
            other_order = [sphere_id for sphere_id in seeded if sphere_id not in known_ids]
            # No Sphere supplies more than a third of a large shelf, so a
            # character with one book-backed Sphere still owns varied books.
            per_sphere_cap = max(2, -(-roll["total"] // 3))
            shelf: list[str] = []
            known_index = other_index = 0
            while len(shelf) < roll["total"]:
                if all(shelf.count(sphere_id) >= per_sphere_cap for sphere_id in seeded):
                    per_sphere_cap += 1
                open_known = [sphere_id for sphere_id in known_order if shelf.count(sphere_id) < per_sphere_cap]
                open_other = [sphere_id for sphere_id in other_order if shelf.count(sphere_id) < per_sphere_cap]
                take_known = bool(open_known) and (len(shelf) % 3 != 2 or not open_other)
                if take_known:
                    shelf.append(open_known[known_index % len(open_known)])
                    known_index += 1
                else:
                    shelf.append(open_other[other_index % len(open_other)])
                    other_index += 1
            used_tuples: set[tuple[str, ...]] = set()
            for index, sphere_id in enumerate(shelf):
                pool = groups[sphere_id]
                options = sorted(
                    itertools.combinations(pool[: max(6, 3 + roll["total"])], 3),
                    key=lambda entry: sha256_json({"seed": seed, "index": index, "sphere_id": sphere_id, "content_record_ids": [row["talent_id"] for row in entry]}),
                )
                selected_tuple = next((entry for entry in options if tuple(row["talent_id"] for row in entry) not in used_tuples), None)
                if selected_tuple is None:
                    raise FoundryError("CG1_MANUAL_COLLECTION_COHERENT_CONTENTS_INSUFFICIENT", "The locked catalog cannot provide enough distinct whole-book content tuples for the rolled count.", details={"requested_count": roll["total"], "sphere_id": sphere_id}, status_code=409)
                used_tuples.add(tuple(row["talent_id"] for row in selected_tuple))
                manual_contents.append(deepcopy(list(selected_tuple)))
                identity = {"seed": seed, "index": index}
                if str((server_marker or {}).get("nonce", "")).startswith("cg1.autogen.v1."):
                    identity["project_id"] = run["project_id"]
                collection_ids.append(f"tianxia.manual.collection.{sha256_json(identity)[:24]}")

        # Add the source Spheres used by the books to the construction request;
        # these are source references, not learned Sphere acquisitions.
        sphere_by_id = {row["sphere_id"]: row for row in base_spheres}
        for entry_rows in manual_contents:
            for content in entry_rows:
                sphere_id = content["sphere_id"]
                if sphere_id not in sphere_by_id:
                    sphere_record = records.get(sphere_id) or {}
                    sphere_by_id[sphere_id] = {"sphere_id": sphere_id, "display_name": sphere_record.get("display_name") or sphere_id}
        request["known_spheres"] = [sphere_by_id[key] for key in sorted(sphere_by_id)]
        if not request.get("known_talents") and manual_contents:
            # Printed ownership is source authority, not learning.  The pure
            # constructor still needs one normalized source row in its request
            # shell when the selected content is above the CL1 learning pool.
            request["known_talents"] = deepcopy(manual_contents[0])
        from character_creation.constructed_arts.records import build_lineage_manual_records
        bundles = construct_lineage_manual_collection(
            request,
            roll=roll,
            manual_contents=manual_contents,
            collection_ids=collection_ids,
        )
        constructed_records = [
            record
            for bundle in bundles
            for record in build_lineage_manual_records(bundle)
        ]
        return bundles, constructed_records, roll

    def _forged_technique_constructions(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        intent_doc: dict[str, Any],
        rows: list[dict[str, Any]],
        records: dict[str, dict[str, Any]],
        target_cl: int,
        *,
        intent_hash: str,
    ) -> list[tuple[dict[str, Any], dict[str, Any]]]:
        """Construct the character's Forged Techniques from the derived rows.

        The known Spheres and talents are exactly those the Stage 2 rows will
        acquire, so Stage 2's own known-talent check and the constructor agree.
        Versioned seeded requests use their stable autogeneration seed;
        historical requests keep project-scoped seeds. Both bind to intent and technique
        ordinal so every phase re-derives the same techniques.
        """
        from character_creation.constructed_arts.forged_technique import construct_forged_technique
        from character_creation.constructed_arts.forging_authority import load_forging_authority
        from character_creation.constructed_arts.records import build_forged_technique_record
        from character_creation.constructed_arts.sources import installed_factory_root, published_block

        pb = 2 + (max(1, int(target_cl)) - 1) // 4
        acquisition = intent_doc.get("acquisition_intent") if isinstance(intent_doc, dict) else None
        concepts_in = (acquisition or {}).get("forged_technique_concepts") if isinstance(acquisition, dict) else None
        concepts = [row for row in concepts_in if isinstance(row, dict)] if isinstance(concepts_in, list) else []
        if isinstance(concepts_in, list) and len(concepts) != len(concepts_in):
            raise FoundryError("CG1_FORGED_TECHNIQUE_CONCEPT_ILLEGAL", "Every proposed Forge design must be an explicit object.")
        # Explicit Forge designs (the walk's picks) fill the first slots; the
        # rest of the Factory policy count is generated from the character's
        # own Talents, so a character without a listed design still forges.
        count = max(len(concepts), self._forged_technique_count(int(target_cl), pb))
        if count > pb:
            raise FoundryError("CG1_FORGED_TECHNIQUE_CONCEPT_ILLEGAL", "The proposed Forge designs exceed the source's PB known-technique limit.")
        if count <= 0:
            return []
        known_sphere_ids: list[str] = []
        known_talent_ids: list[str] = []
        for entry in rows:
            kind = entry.get("kind")
            record_id = entry.get("record_id")
            record = records.get(record_id) if isinstance(record_id, str) else None
            if not isinstance(record, dict):
                continue
            if kind in self._SPHERE_ROW_KINDS and record.get("content_type") == "sphere" and record_id not in known_sphere_ids:
                known_sphere_ids.append(record_id)
            elif kind in self._TALENT_ROW_KINDS and record.get("content_type") == "talent" and record_id not in known_talent_ids:
                known_talent_ids.append(record_id)
        path_ids = [entry.get("record_id") for entry in rows if entry.get("kind") == "path_acquisition"]
        path_id = next((value for value in path_ids if isinstance(value, str)), None)
        if path_id is None:
            return []
        path_record = records.get(path_id) or {}
        key_ability = (((path_record.get("compatibility") or {}).get("factory") or {}).get("stage2_authority") or {}).get("key_ability")
        if key_ability not in {"STR", "DEX", "CON", "INT", "WIS", "CHA"}:
            key_ability = self._PATH_DEFAULT_KEY_ABILITY.get(path_id, "INT")
        factory_root = installed_factory_root(self.db.settings.vendor_dir)
        spheres_by_id = {sid: records[sid] for sid in known_sphere_ids}
        talents = []
        for talent_id in known_talent_ids:
            record = records[talent_id]
            sphere_id = (((record.get("compatibility") or {}).get("factory") or {}).get("stage2_authority") or {}).get("sphere_id")
            if not isinstance(sphere_id, str) or sphere_id not in spheres_by_id:
                continue
            talents.append({
                "talent_id": talent_id,
                "sphere_id": sphere_id,
                "display_name": record.get("display_name") or talent_id,
                "record_hash": record.get("record_hash"),
                "source": record.get("source") or {},
                "published_text": published_block(factory_root, record.get("source") or {}),
            })
        # Core Rules §11 draws from both automatic Sphere base abilities and
        # learned talents. Base abilities are authenticated by typed authority
        # source hashes and the public rules-text catalog, not invented text.
        from combat.factory_compiler import TYPED_AUTHORITY
        typed = json.loads(TYPED_AUTHORITY.read_bytes())
        printed = json.loads((TYPED_AUTHORITY.parent / "typed_mechanics" / "rules_text.json").read_bytes())
        mechanics = typed.get("mechanics") or {}
        from character_creation.constructed_arts.sphere_effects import base_effect_rows
        talents.extend(base_effect_rows(known_sphere_ids, mechanics, printed))
        if not talents:
            return []
        authority = load_forging_authority(self.db.settings.root_dir)
        base_request = {
            "project_id": run["project_id"],
            "cl": int(target_cl),
            "pb": pb,
            "path_id": path_id,
            "key_ability": key_ability,
            "known_spheres": [{"sphere_id": sid, "display_name": spheres_by_id[sid].get("display_name") or sid} for sid in known_sphere_ids],
            "known_talents": talents,
        }
        constructed: list[tuple[dict[str, Any], dict[str, Any]]] = []
        for index in range(count):
            concept = deepcopy(concepts[index]) if index < len(concepts) else {}
            request = {
                **deepcopy(base_request),
                "seed": self._constructed_recipe_seed(
                    project, self._constructed_recipe_intent_hash(run, intent_doc, intent_hash), "forged_technique", index,
                    legacy_seed=f"{run['project_id']}:{intent_hash}:forged_technique:{index}",
                    run=run,
                ),
                "known_forged_technique_count": index,
                "concept": {key: concept.get(key) for key in ("name", "intent", "base_form", "primary_talent_id", "secondary_talent_ids", "augment_ids", "drawback_ids") if concept.get(key) is not None},
            }
            try:
                technique = construct_forged_technique(
                    authority, request, generator_version=concept.get("generator_version", 2)
                )
            except FoundryError as exc:
                if concept:
                    # A model concept that breaks the sealed tables is an
                    # owner-visible decision, not something to silently repair.
                    raise FoundryError(
                        "CG1_FORGED_TECHNIQUE_CONCEPT_ILLEGAL",
                        "A proposed Forged Technique concept cannot be forged under the published tables.",
                        details={"index": index, "concept": concept, "cause": exc.code, "cause_details": exc.details},
                        status_code=409,
                    ) from exc
                raise
            constructed.append((technique, build_forged_technique_record(technique)))
        return constructed

    def _stable_immortal_arts(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        intent_doc: dict[str, Any],
        rows: list[dict[str, Any]],
        records: dict[str, dict[str, Any]],
        target_cl: int,
        *,
        intent_hash: str,
        authority_db: Database | None = None,
    ) -> list[tuple[dict[str, Any], dict[str, Any], dict[str, Any] | None]]:
        """Stabilized Arts, retrying a failed refinement with the next source.

        Owner ruling 2026-09-23: a failed Refinement Check chain does not leave
        a CL15+ character without an Art; the construction moves to the next
        eligible source.  Deterministic, so every re-derivation agrees.
        """
        excluded: set[str] = set()
        kept: list[tuple[dict[str, Any], dict[str, Any], dict[str, Any] | None]] = []
        for _attempt in range(16):
            try:
                constructed = self._immortal_art_constructions(
                    run, project, intent_doc, rows, records, target_cl,
                    intent_hash=intent_hash, authority_db=authority_db,
                    excluded_source_ids=frozenset(excluded),
                )
            except FoundryError as exc:
                # No source left to try: keep what the last attempt stabilized.
                if exc.code == "CG1_IMMORTAL_ART_SOURCE_UNAVAILABLE" and excluded:
                    return kept
                raise
            kept = self._stabilized_immortal_constructions(run, constructed, intent_hash=intent_hash)
            if len(kept) == len(constructed):
                return kept
            kept_ids = {id(art) for art, _record, _proof in kept}
            failed = {
                str((((art.get("construction") or {}).get("request") or {}).get("source_record_id")))
                for art, _record in constructed
                if id(art) not in kept_ids
            }
            failed.discard("None")
            if not failed or failed <= excluded:
                return kept
            excluded |= failed
        return kept

    def _stabilized_immortal_constructions(
        self,
        run: dict[str, Any],
        constructed: list[tuple[dict[str, Any], dict[str, Any]]],
        *,
        intent_hash: str,
    ) -> list[tuple[dict[str, Any], dict[str, Any], dict[str, Any] | None]]:
        """Keep only Arts whose bounded Refinement Check chain succeeds.

        Opening rules section 5: a failed refinement leaves the Art
        unstabilized.  Such an Art is never known, never locked and never
        becomes a Stage 2 row; the character simply has no Art from that
        construction point.  Legacy requests without the server nonce keep
        every constructed Art with no proof (their sealed shape).
        """
        kept: list[tuple[dict[str, Any], dict[str, Any], dict[str, Any] | None]] = []
        for index, (art, record) in enumerate(constructed):
            try:
                proof = self._immortal_art_creation_parameters(run, art, record, index=index, intent_hash=intent_hash)
            except FoundryError as exc:
                if exc.code != "CG1_IMMORTAL_ART_REFINEMENT_EXHAUSTED":
                    raise
                continue
            kept.append((art, record, proof))
        return kept

    @staticmethod
    def _immortal_art_creation_parameters(
        run: dict[str, Any],
        art: dict[str, Any],
        record: dict[str, Any],
        *,
        index: int,
        intent_hash: str,
    ) -> dict[str, Any] | None:
        """Build one server-owned creator-history Refinement Check for an Art.

        Opening rules sections 4-6: an Immortal Art is refined only by a
        Refinement Check (d20 + Proficiency Bonus + Path ability modifier)
        against its Refinement DC, after 5 days of research per Mandate
        Complexity and 250 gp of materials per Mandate Complexity squared; a
        failed check leaves the Art unstabilized and loses half the research or
        materials.  Like Forged Technique acquisition, the d20 is derived from
        the persisted Manual-policy nonce and the immutable request/record
        identity so rebuilds reproduce the same history without a provider.
        Legacy requests without that versioned marker keep their sealed shape.
        """
        from character_creation.constructed_arts.immortal_art import (
            IMMORTAL_ART_REFINEMENT_MAX_ATTEMPTS,
            IMMORTAL_ART_REFINEMENT_SCHEMA,
            immortal_art_refinement_authority,
        )

        request = run.get("request") if isinstance(run, Mapping) else None
        server_authority = request.get("server_owned_authority") if isinstance(request, Mapping) else None
        marker = server_authority.get("manual_collection") if isinstance(server_authority, Mapping) else None
        if not isinstance(marker, Mapping) or marker.get("authority_version") != "server_owned_pre_provider.v2":
            return None
        nonce = marker.get("nonce")
        if not isinstance(nonce, str) or len(nonce) < 32 or not nonce.strip():
            raise FoundryError(
                "CG1_IMMORTAL_ART_REFINEMENT_AUTHORITY_INVALID",
                "The server-owned creator request has no valid persisted random authority for Immortal Art refinement.",
                status_code=409,
            )
        record_id = record.get("record_id")
        record_hash = record.get("record_hash")
        construction_request = ((art.get("construction") or {}).get("request") or {}) if isinstance(art, Mapping) else {}
        ability_modifier = construction_request.get("key_ability_modifier")
        pb = art.get("pb_at_creation")
        dc = art.get("refinement_dc")
        research_days = art.get("research_days")
        material_cost_gp = art.get("material_cost_gp")
        if (
            not isinstance(record_id, str) or not isinstance(record_hash, str)
            or type(ability_modifier) is not int or type(pb) is not int or type(dc) is not int
            or type(research_days) is not int or research_days < 1
            or type(material_cost_gp) is not int or material_cost_gp < 0
        ):
            raise FoundryError(
                "CG1_IMMORTAL_ART_REFINEMENT_AUTHORITY_INVALID",
                "The constructed Immortal Art has incomplete published refinement requirements.",
                details={"record_id": record_id},
                status_code=409,
            )
        seed_material = sha256_json({
            "policy_id": IMMORTAL_ART_REFINEMENT_SCHEMA,
            "nonce": nonce,
            "project_id": run.get("project_id"),
            "intent_hash": intent_hash,
            "record_id": record_id,
            "record_hash": record_hash,
            "ordinal": index,
        })
        if nonce.startswith("cg1.autogen.v1."):
            # Refinement can reject a recipe and select another source. Its
            # dice must therefore reproduce too; attempt IDs remain unique.
            seed_material = sha256_json({
                "policy_id": IMMORTAL_ART_REFINEMENT_SCHEMA,
                "recipe_seed": (art.get("construction") or {}).get("seed"),
                "ordinal": index,
            })
        rng = random.Random(seed_material)
        attempts: list[dict[str, Any]] = []
        previous_attempt_id: str | None = None
        succeeded = False
        for attempt_index in range(IMMORTAL_ART_REFINEMENT_MAX_ATTEMPTS):
            check_die = rng.randint(1, 20)
            success = check_die + pb + ability_modifier >= dc
            attempt_id = "cg1.refinement.attempt." + sha256_json({
                "project_id": run.get("project_id"),
                "intent_hash": intent_hash,
                "record_id": record_id,
                "record_hash": record_hash,
                "ordinal": index,
                "attempt_index": attempt_index,
            })[:32]
            attempts.append({
                "attempt_id": attempt_id,
                "retry_of_attempt_id": previous_attempt_id,
                "check_die_result": check_die,
                "research_time_hours": research_days * 8 if success else research_days * 4,
                "materials_paid_gp": material_cost_gp if success else material_cost_gp // 2,
            })
            previous_attempt_id = attempt_id
            if success:
                succeeded = True
                break
        if not succeeded:
            raise FoundryError(
                "CG1_IMMORTAL_ART_REFINEMENT_EXHAUSTED",
                "The bounded Immortal Art Refinement Checks all failed; the Art is not stabilized and remains unknown.",
                details={"record_id": record_id, "target_cl": art.get("cl_created"), "attempts": deepcopy(attempts)},
                status_code=409,
            )
        return {
            "schema": IMMORTAL_ART_REFINEMENT_SCHEMA,
            "authority": immortal_art_refinement_authority(),
            "mode": "creator_generated_history",
            "scope": "initial_creation",
            "observed_play": False,
            "live_currency_debit": False,
            "target_cl": art.get("cl_created"),
            "record_id": record_id,
            "record_hash": record_hash,
            "path_id": art.get("path_id"),
            "key_ability": art.get("key_ability"),
            "pb": pb,
            "ability_modifier": ability_modifier,
            "dc": dc,
            "research": {"required_days": research_days, "meaningful_training_hours": research_days * 8, "completed": True},
            "materials": {"required_gp": material_cost_gp, "paid_gp": material_cost_gp, "payment_complete": True},
            "completion": {
                "mode": "creator_generated_history",
                "scope": "initial_creation",
                "record_id": record_id,
                "record_hash": record_hash,
                "research_complete": True,
                "payment_complete": True,
            },
            "attempts": attempts,
        }

    @staticmethod
    def _forged_technique_creation_parameters(
        run: dict[str, Any],
        technique: dict[str, Any],
        record: dict[str, Any],
        *,
        index: int,
        intent_hash: str,
        ability_modifier: int | None = None,
    ) -> dict[str, Any] | None:
        """Build one server-owned creator-history forging history.

        The persisted Manual-policy nonce is the existing server random
        authority for a new request.  It is combined with the immutable
        request/record identity so rebuilds and idempotent retries reproduce
        the same d20 without exposing the nonce or asking a provider to roll.
        Legacy requests without that versioned marker retain their sealed row
        shape and are not silently migrated.
        """
        from character_creation.constructed_arts.forged_technique import forged_technique_acquisition_authority

        request = run.get("request") if isinstance(run, Mapping) else None
        server_authority = request.get("server_owned_authority") if isinstance(request, Mapping) else None
        marker = server_authority.get("manual_collection") if isinstance(server_authority, Mapping) else None
        if not isinstance(marker, Mapping) or marker.get("authority_version") != "server_owned_pre_provider.v2":
            return None
        if type(ability_modifier) is not int:
            raise FoundryError(
                "CG1_FORGING_CREATION_AUTHORITY_INVALID",
                "The server-owned creator request has no causal Path ability modifier for Forged Technique acquisition.",
                details={"record_id": record.get("record_id")},
                status_code=409,
            )
        nonce = marker.get("nonce")
        if not isinstance(nonce, str) or len(nonce) < 32 or not nonce.strip():
            raise FoundryError(
                "CG1_FORGING_CREATION_AUTHORITY_INVALID",
                "The server-owned creator request has no valid persisted random authority for Forged Technique acquisition.",
                status_code=409,
            )
        record_id = record.get("record_id")
        record_hash = record.get("record_hash")
        if not isinstance(record_id, str) or not isinstance(record_hash, str):
            raise FoundryError(
                "CG1_FORGING_CREATION_AUTHORITY_INVALID",
                "A constructed Forged Technique has no stable record identity for its acquisition attempt.",
                status_code=409,
            )
        seed_material = sha256_json({
            "policy_id": "TianxiaFoundry.ForgedTechniqueAcquisition.v1",
            "nonce": nonce,
            "project_id": run.get("project_id"),
            "intent_hash": intent_hash,
            "record_id": record_id,
            "record_hash": record_hash,
            "ordinal": index,
        })
        if nonce.startswith("cg1.autogen.v1."):
            seed_material = sha256_json({
                "policy_id": "TianxiaFoundry.ForgedTechniqueAcquisition.v1",
                "recipe_seed": (technique.get("construction") or {}).get("seed"),
                "ordinal": index,
            })
        research_days = technique.get("research_days")
        material_cost_gp = technique.get("material_cost_gp")
        pb = technique.get("pb_at_creation")
        dc = technique.get("technique_forging_dc")
        if (
            type(research_days) is not int or research_days < 1
            or type(material_cost_gp) is not int or material_cost_gp < 0
            or type(pb) is not int or pb < 0
            or type(dc) is not int
        ):
            raise FoundryError(
                "CG1_FORGING_CREATION_AUTHORITY_INVALID",
                "The constructed Forged Technique has incomplete published research or material requirements.",
                details={"record_id": record_id},
                status_code=409,
            )
        rng = random.Random(seed_material)
        attempts: list[dict[str, Any]] = []
        previous_attempt_id: str | None = None
        succeeded = False
        for attempt_index in range(8):
            check_die = rng.randint(1, 20)
            total = check_die + pb + ability_modifier
            success = total >= dc
            attempt_id = "cg1.forging.attempt." + sha256_json({
                "project_id": run.get("project_id"),
                "intent_hash": intent_hash,
                "record_id": record_id,
                "record_hash": record_hash,
                "ordinal": index,
                "attempt_index": attempt_index,
            })[:32]
            attempts.append({
                "attempt_id": attempt_id,
                "retry_of_attempt_id": previous_attempt_id,
                "check_die_result": check_die,
                "research_time_hours": research_days * 8 if success else research_days * 4,
                "materials_paid_gp": material_cost_gp if success else material_cost_gp // 2,
            })
            previous_attempt_id = attempt_id
            if success:
                succeeded = True
                break
        if not succeeded:
            raise FoundryError(
                "CG1_FORGING_ACQUISITION_EXHAUSTED",
                "The bounded Forged Technique research attempts all failed; the technique remains unknown.",
                details={
                    "record_id": record_id,
                    "target_cl": technique.get("cl_created"),
                    "attempts": deepcopy(attempts),
                },
                status_code=409,
            )
        return {
            "schema": "TianxiaFoundry.ForgedTechniqueAcquisition.v1",
            "authority": forged_technique_acquisition_authority(),
            "mode": "creator_generated_history",
            "scope": "initial_creation",
            "observed_play": False,
            "live_currency_debit": False,
            "target_cl": technique.get("cl_created"),
            "record_id": record_id,
            "record_hash": record_hash,
            "powering_path_id": technique.get("powering_path_id"),
            "key_ability": technique.get("key_ability"),
            "pb": pb,
            "ability_modifier": ability_modifier,
            "dc": dc,
            "research": {
                "required_days": research_days,
                "meaningful_training_hours": research_days * 8,
                "completed": True,
            },
            "materials": {
                "required_gp": material_cost_gp,
                "paid_gp": material_cost_gp,
                "payment_complete": True,
            },
            "training_location": {
                "mode": "creator_generated_history",
                "scope": "initial_creation",
                "suitable": True,
            },
            "completion": {
                "mode": "creator_generated_history",
                "scope": "initial_creation",
                "record_id": record_id,
                "record_hash": record_hash,
                "research_complete": True,
                "payment_complete": True,
            },
            "attempts": attempts,
        }

    def _immortal_feature_source_row(
        self,
        *,
        feature_id: str,
        feature: dict[str, Any],
        feature_record: dict[str, Any] | None,
        parent_record: dict[str, Any],
        path_id: str,
        owning_path_cl: int,
        construction_cl: int,
        factory_root: Path | None,
    ) -> dict[str, Any]:
        """Build one source snapshot from a proof-bound Subpath feature.

        The P2B feature index is the authority for identity and progression,
        while the installed factory pack is the authority for the complete
        printed action.  Keeping both commitments in this row makes the pure
        constructor useful without allowing a caller to supply mechanics or a
        child record that was not earned from the selected Subpath.
        """
        from character_creation.constructed_arts.immortal_art import immortal_art_progression_child_hash
        from character_creation.constructed_arts.sources import published_section

        adapter = _IMMORTAL_FEATURE_SOURCE_ADAPTERS.get(feature_id)
        if adapter is None:
            raise FoundryError(
                "CG1_IMMORTAL_ART_SOURCE_UNSUPPORTED",
                "The selected Path feature has no complete authenticated Immortal Art action adapter.",
                details={"feature_id": feature_id},
                status_code=409,
            )
        raw_source = feature.get("source") if isinstance(feature, dict) else None
        if not isinstance(raw_source, dict):
            raise FoundryError(
                "CG1_IMMORTAL_ART_SOURCE_AUTHORITY_INVALID",
                "The selected Path feature has no exact source-section commitment.",
                details={"feature_id": feature_id},
                status_code=409,
            )
        expected_source_fields = {
            "factory_source_path": adapter["source_id"].replace(
                "source.tianxia.subpath.", "09_RULES/Source_Text/Paths/"
            ) if False else raw_source.get("factory_source_path"),
            "source_file_sha256": adapter["source_file_sha256"],
            "line_start": adapter["line_start"],
            "line_end": adapter["line_end"],
            "section_sha256": adapter["section_sha256"],
        }
        # Source path is read from the authenticated feature row, but all
        # numeric/hash bounds are pinned to the explicit adapter.  This keeps
        # the adapter independent from the private LocalSources layout while
        # rejecting an adjacent or truncated section.
        if (
            raw_source.get("factory_source_path") != expected_source_fields["factory_source_path"]
            or raw_source.get("source_file_sha256") != adapter["source_file_sha256"]
            or raw_source.get("line_start") != adapter["line_start"]
            or raw_source.get("line_end") != adapter["line_end"]
            or raw_source.get("section_sha256") != adapter["section_sha256"]
        ):
            raise FoundryError(
                "CG1_IMMORTAL_ART_SOURCE_AUTHORITY_INVALID",
                "The selected feature's source bounds differ from its complete published action adapter.",
                details={"feature_id": feature_id, "source": raw_source},
                status_code=409,
            )
        parent_id = parent_record.get("record_id")
        parent_hash = parent_record.get("record_hash")
        if (
            parent_record.get("content_type") != "subpath"
            or not isinstance(parent_id, str)
            or not isinstance(parent_hash, str)
            or len(parent_hash) != 64
        ):
            raise FoundryError(
                "CG1_IMMORTAL_ART_SOURCE_AUTHORITY_INVALID",
                "The selected feature is not attached to one authenticated locked Subpath record.",
                details={"feature_id": feature_id, "parent_record_id": parent_id},
                status_code=409,
            )
        # P2B progression children live inside the authenticated Subpath
        # authority; they are not independent project lock records.  Bind the
        # canonical child identity to the exact parent snapshot and feature row.
        child_hash = immortal_art_progression_child_hash(parent_id, parent_hash, feature)
        if feature_record is not None:
            if (
                not isinstance(feature_record, dict)
                or feature_record.get("record_id") != feature_id
                or feature_record.get("record_hash") != child_hash
            ):
                raise FoundryError(
                    "CG1_IMMORTAL_ART_SOURCE_AUTHORITY_INVALID",
                    "An optional child snapshot does not match the parent-bound progression commitment.",
                    details={"feature_id": feature_id, "parent_record_id": parent_id},
                    status_code=409,
                )
        exact_binding = {
            "source_id": adapter["source_id"],
            "path": raw_source["factory_source_path"],
            "anchor": f"line:{adapter['line_start']}",
            "source_hash": adapter["source_file_sha256"],
        }
        exact_source = {
            **exact_binding,
            "factory_source_path": raw_source["factory_source_path"],
            "source_file_sha256": adapter["source_file_sha256"],
            "line_start": adapter["line_start"],
            "line_end": adapter["line_end"],
            "section_sha256": adapter["section_sha256"],
        }
        published_text = published_section(factory_root, exact_source)
        if not published_text:
            raise FoundryError(
                "CG1_IMMORTAL_ART_SOURCE_UNAVAILABLE",
                "The installed source section for the selected Immortal Art feature is unavailable or hash-drifted.",
                details={"feature_id": feature_id, "source": exact_source},
                status_code=409,
            )
        action, source_dependencies = _authenticated_immortal_feature_action(
            feature_id, published_text, factory_root, exact_source,
        )
        granted_at_cl = feature.get("granted_at_cl")
        if type(granted_at_cl) is not int or granted_at_cl < 1 or granted_at_cl > owning_path_cl or granted_at_cl > construction_cl:
            raise FoundryError(
                "CG1_IMMORTAL_ART_SOURCE_NOT_ATTAINED",
                "The selected source feature was not attained by the Art construction point.",
                details={"feature_id": feature_id, "granted_at_cl": granted_at_cl, "owning_path_cl": owning_path_cl, "construction_cl": construction_cl},
                status_code=409,
            )
        progression = {
            "feature_record_id": feature_id,
            "owning_path_id": path_id,
            "parent_path_id": path_id,
            "parent_record_id": parent_id,
            "parent_record_hash": parent_hash,
            "granted_at_cl": granted_at_cl,
            "minimum_realm_band": feature.get("minimum_realm_band"),
            "source_cl_basis": feature.get("source_cl_basis"),
            "source": deepcopy(exact_source),
            "components": deepcopy(feature.get("components") or []),
            "feature_snapshot": deepcopy(feature),
            "feature_record_hash_kind": "subpath_progression_commitment",
        }
        acquisition = {
            "kind": "subpath_feature",
            "parent_record_id": parent_id,
            "parent_record_hash": parent_hash,
            "feature_record_id": feature_id,
            "feature_record_hash": child_hash,
            "acquired_at_cl": granted_at_cl,
        }
        return {
            "record_id": feature_id,
            "record_hash": child_hash,
            "feature_record_hash_kind": "subpath_progression_commitment",
            "display_name": feature.get("display_name") or feature_id,
            "content_type": "path_feature",
            "known": True,
            "acquired": True,
            "acquired_at_cl": granted_at_cl,
            "path_id": path_id,
            "owning_path_id": path_id,
            "source_package_id": adapter["source_package_id"],
            "source": exact_binding,
            "source_tags": list(adapter["source_tags"]),
            "supported_factor_ids": list(adapter["supported_factor_ids"]),
            "progression": progression,
            "acquisition": acquisition,
            "action_surface": action,
            "published_text": published_text,
            "source_dependencies": source_dependencies,
            "factor_adapters": {
                factor_id: {
                    "source_record_id": feature_id,
                    "source_record_hash": child_hash,
                    "parent_record_id": parent_id,
                    "parent_record_hash": parent_hash,
                    "source_section_sha256": adapter["section_sha256"],
                }
                for factor_id in adapter["supported_factor_ids"]
            },
        }

    @staticmethod
    def _immortal_path_cl_at(
        *,
        path_id: str,
        point_cl: int,
        rows: list[dict[str, Any]],
        path_authorities: dict[str, dict[str, Any]],
        progression_choice: Mapping[str, Any] | None = None,
    ) -> int:
        """Count only the selected Path's causal level-advance events."""
        count = 0
        progression_choice = progression_choice if isinstance(progression_choice, Mapping) else {}
        for entry in rows:
            if not isinstance(entry, dict) or entry.get("kind") != "level_advance":
                continue
            cl = entry.get("effective_cl")
            if type(cl) is not int or cl > point_cl:
                continue
            native_entries = (entry.get("parameters") or {}).get("native_path_progressions")
            if isinstance(native_entries, list):
                matching = [native for native in native_entries if native.get("path_id") == path_id and native.get("cl") == cl]
                if len(matching) == 1:
                    count += 1
                continue
            authority = path_authorities.get(path_id) or {}
            progression = (authority.get("progression_by_cl") or {}).get(str(cl)) or {}
            feature_ids = progression.get("feature_record_ids") or []
            if entry.get("record_id") in feature_ids:
                count += 1
                continue
            # Historical rows can carry a representative feature from a
            # compact path projection.  The bounded intent is accepted only
            # when it names this exact selected Path for that CL.
            selected = progression_choice.get(str(cl), progression_choice.get(cl))
            if selected == path_id:
                available = (authority.get("progression_by_cl") or {}).get(str(cl))
                if isinstance(available, dict):
                    count += 1
        return count

    def _immortal_art_constructions(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        intent_doc: dict[str, Any],
        rows: list[dict[str, Any]],
        records: dict[str, dict[str, Any]],
        target_cl: int,
        *,
        intent_hash: str,
        authority_db: Database | None = None,
        excluded_source_ids: Collection[str] = (),
    ) -> list[tuple[dict[str, Any], dict[str, Any]]]:
        """Construct Arts at CL15/CL20 from actual Path/Subpath authority.

        Source candidates are proof-bound native Path or Subpath children. The
        helper never consults a raw declaration or a caller capability list;
        unsupported or unattained features simply leave the required lane
        unavailable and the caller receives a fail-closed authority error.

        GM Guide 14.6 makes Immortal Arts DM/AI-facing construction tools; the
        campaign import boundary there restricts *player* options, not this
        factory generation.  The normal run therefore constructs one Art at
        CL15 and one at CL20, each subject to the Refinement Check (opening
        rules 4-6, an unrefinable Art drops out) and to the tier count ceiling
        (Core Rules Reference §17.6 / Step 7, owner ruling 2026-09-11).
        """
        if int(target_cl) < 15:
            return []
        from character_creation.constructed_arts.immortal_art import (
            construct_immortal_art,
            immortal_art_count_ceiling,
            immortal_art_progression_child_hash,
            load_immortal_art_authority,
        )
        from character_creation.constructed_arts.records import build_immortal_art_record
        from character_creation.constructed_arts.sources import installed_factory_root
        from character_creation.constructed_arts.native_immortal_sources import (
            NATIVE_COMMITMENT_KIND, NATIVE_SOURCE_IDS, native_source_row,
        )

        selected_db = authority_db if authority_db is not None else self.db
        factory_root = installed_factory_root(selected_db.settings.vendor_dir)
        authority = load_immortal_art_authority(selected_db.settings.root_dir)
        selected_path_ids = [
            entry.get("record_id")
            for entry in rows
            if isinstance(entry, dict) and entry.get("kind") == "path_acquisition" and isinstance(entry.get("record_id"), str)
        ]
        selected_path_ids = list(dict.fromkeys(selected_path_ids))
        path_records = {
            path_id: records[path_id]
            for path_id in selected_path_ids
            if isinstance(records.get(path_id), dict)
        }
        if not path_records:
            raise FoundryError(
                "CG1_IMMORTAL_ART_AUTHORITY_MISSING",
                "Immortal Art construction requires at least one proof-bound selected Path.",
                status_code=409,
            )
        path_authorities = {
            path_id: (((record.get("compatibility") or {}).get("factory") or {}).get("stage2_authority") or {})
            for path_id, record in path_records.items()
        }
        progression_choice = (intent_doc.get("bounded_choices") or {}).get("path_progression_by_cl") if isinstance(intent_doc, dict) else {}
        if not isinstance(progression_choice, Mapping):
            progression_choice = {}
        selected_subpaths = [
            entry.get("record_id")
            for entry in rows
            if isinstance(entry, dict) and entry.get("kind") == "subpath_acquisition" and isinstance(entry.get("record_id"), str)
        ]
        selected_subpaths = list(dict.fromkeys(selected_subpaths))
        candidates: list[dict[str, Any]] = []
        for subpath_id in selected_subpaths:
            parent_record = records.get(subpath_id)
            if not isinstance(parent_record, dict):
                continue
            path_id = parent_record.get("owning_path_id") or parent_record.get("parent_path_id")
            if not isinstance(path_id, str) or path_id not in path_records:
                continue
            owning_path_cl = self._immortal_path_cl_at(
                path_id=path_id,
                point_cl=int(target_cl),
                rows=rows,
                path_authorities=path_authorities,
                progression_choice=progression_choice,
            )
            if owning_path_cl < 15:
                continue
            subpath_authority = (((parent_record.get("compatibility") or {}).get("factory") or {}).get("stage2_authority") or {})
            feature_rows = subpath_authority.get("feature_progression") or []
            if not isinstance(feature_rows, list):
                feature_rows = []
            for feature in feature_rows:
                if not isinstance(feature, dict):
                    continue
                feature_id = feature.get("canonical_id")
                if not isinstance(feature_id, str) or feature_id not in _IMMORTAL_FEATURE_SOURCE_ADAPTERS:
                    continue
                feature_record = records.get(feature_id)
                if feature_record is not None and not isinstance(feature_record, dict):
                    continue
                try:
                    source_row = self._immortal_feature_source_row(
                        feature_id=feature_id,
                        feature=feature,
                        feature_record=feature_record,
                        parent_record=parent_record,
                        path_id=path_id,
                        owning_path_cl=owning_path_cl,
                        construction_cl=int(target_cl),
                        factory_root=factory_root,
                    )
                except FoundryError:
                    # A recognized feature with drift is not converted into a
                    # generic action.  Leave the candidate unavailable so the
                    # construction boundary reports the missing authority.
                    continue
                source_row["_owning_path_cl"] = owning_path_cl
                source_row["_path_realm"] = "Immortal" if owning_path_cl >= 20 else "Nascent Soul"
                source_row["_path_name"] = path_records[path_id].get("display_name") or path_id
                source_row["_path_record_id"] = path_id
                source_row["_path_record_hash"] = path_records[path_id].get("record_hash")
                candidates.append(source_row)
        native_failures = []
        for path_id, parent_record in path_records.items():
            path_cl = self._immortal_path_cl_at(
                path_id=path_id, point_cl=int(target_cl), rows=rows,
                path_authorities=path_authorities, progression_choice=progression_choice,
            )
            if path_cl < 15:
                continue
            for feature_id in NATIVE_SOURCE_IDS:
                if not feature_id.startswith(path_id + ".feature."):
                    continue
                try:
                    source_row = native_source_row(
                        selected_db.settings.root_dir, factory_root, feature_id=feature_id,
                        parent_record=parent_record, owning_path_cl=path_cl,
                        construction_cl=int(target_cl),
                    )
                except FoundryError as exc:
                    native_failures.append({"feature_id": feature_id, "code": exc.code, "message": exc.message})
                    continue
                source_row.update({
                    "_path_record_id": path_id, "_path_record_hash": parent_record["record_hash"],
                    "_path_name": parent_record.get("display_name") or path_id,
                    "_owning_path_cl": path_cl,
                })
                candidates.append(source_row)
        # A source feature is one candidate even if a legacy projection lists
        # it in more than one representation.  Stable path/source ordering is
        # the only tie-breaker; the construction seed remains in the pure
        # constructor identity.
        unique_candidates: dict[str, dict[str, Any]] = {}
        for candidate in candidates:
            unique_candidates.setdefault(candidate["record_id"], candidate)
        candidates = sorted(
            unique_candidates.values(),
            key=lambda row: (
                row.get("feature_record_hash_kind") == NATIVE_COMMITMENT_KIND,
                row.get("owning_path_id") or "",
                row.get("source_package_id") or "",
                row["record_id"],
            ),
        )
        if not candidates:
            raise FoundryError(
                "CG1_IMMORTAL_ART_AUTHORITY_MISSING",
                "No acquired Path or Subpath has an attained complete source action for Immortal Art construction.",
                details={"target_cl": int(target_cl), "selected_subpaths": selected_subpaths,
                         "selected_paths": selected_path_ids, "native_source_failures": native_failures},
                status_code=409,
            )

        def score_state(point_cl: int) -> dict[str, int]:
            result: dict[str, int] = {}
            for entry in rows:
                if not isinstance(entry, dict) or type(entry.get("effective_cl")) is not int or entry["effective_cl"] > point_cl:
                    continue
                params = entry.get("parameters") if isinstance(entry.get("parameters"), dict) else {}
                if entry.get("kind") == "starting_state":
                    source_scores = params.get("ability_scores")
                    if isinstance(source_scores, dict):
                        result = {key: int(value) for key, value in source_scores.items() if isinstance(value, int)}
                elif entry.get("kind") in {"background_acquisition", "cultivation_insight_acquisition"}:
                    ability, amount = params.get("ability"), params.get("amount")
                    if isinstance(ability, str) and type(amount) is int and ability in result:
                        result[ability] += amount
                elif entry.get("kind") == "ability_score_change":
                    deltas = params.get("deltas")
                    if isinstance(deltas, dict):
                        for ability, amount in deltas.items():
                            if ability in result and type(amount) is int:
                                result[ability] += amount
            return result

        count_ceiling = immortal_art_count_ceiling(int(target_cl))
        previous_source_ids: set[str] = set(excluded_source_ids)
        constructed: list[tuple[dict[str, Any], dict[str, Any]]] = []
        for point_cl, ordinal in ((15, 0), (20, 1)):
            if int(target_cl) < point_cl:
                continue
            if len(constructed) >= count_ceiling:
                break
            available = []
            # Bounded diagnostics: why each authenticated source is not usable
            # at this construction point (IDs and integers only).
            excluded: dict[str, dict[str, Any]] = {}
            for row in candidates:
                if row["record_id"] in previous_source_ids:
                    excluded[row["record_id"]] = {"reason": "used_by_earlier_art"}
                    continue
                if int(row["acquired_at_cl"]) > point_cl:
                    excluded[row["record_id"]] = {"reason": "acquired_after_construction_point", "acquired_at_cl": int(row["acquired_at_cl"])}
                    continue
                point_path_cl = self._immortal_path_cl_at(
                    path_id=row["_path_record_id"],
                    point_cl=point_cl,
                    rows=rows,
                    path_authorities=path_authorities,
                    progression_choice=progression_choice,
                )
                granted_at_cl = (row.get("progression") or {}).get("granted_at_cl")
                if point_path_cl < 15 or type(granted_at_cl) is not int or granted_at_cl > point_path_cl:
                    excluded[row["record_id"]] = {
                        "reason": "path_cl_below_15" if point_path_cl < 15 else "not_granted_by_path_cl",
                        "path_id": row["_path_record_id"],
                        "path_cl_at_point": int(point_path_cl),
                        "granted_at_cl": granted_at_cl if type(granted_at_cl) is int else None,
                    }
                    continue
                if row.get("feature_record_hash_kind") == NATIVE_COMMITMENT_KIND:
                    # Scaling belongs to the Art's causal construction point,
                    # not the final character CL (e.g. Domain Pressure's cone).
                    source = native_source_row(
                        selected_db.settings.root_dir, factory_root, feature_id=row["record_id"],
                        parent_record=path_records[row["_path_record_id"]],
                        owning_path_cl=point_path_cl, construction_cl=point_cl,
                    )
                    source.update({key: value for key, value in row.items() if key.startswith("_")})
                    row = source
                available.append(row)
            if not available:
                raise FoundryError(
                    "CG1_IMMORTAL_ART_SOURCE_UNAVAILABLE",
                    "The requested Immortal Art ordinal has no distinct attained complete source action.",
                    details={
                        "construction_cl": point_cl,
                        "ordinal": ordinal,
                        "available_source_ids": [row["record_id"] for row in available],
                        "candidate_source_ids": [row["record_id"] for row in candidates],
                        "previous_source_ids": sorted(previous_source_ids),
                        "excluded": excluded,
                        "native_source_failures": native_failures,
                    },
                    status_code=409,
                )
            # ``ordinal`` identifies the construction event (and remains part
            # of the Art identity); it is not an index into the candidates
            # left after earlier Art sources have been excluded.  Select the
            # stable first remaining source so a second Art can use the next
            # authenticated source at CL20.
            selected = available[0]
            selected_path_cl = self._immortal_path_cl_at(
                path_id=selected["_path_record_id"],
                point_cl=point_cl,
                rows=rows,
                path_authorities=path_authorities,
                progression_choice=progression_choice,
            )
            selected_realm = "Immortal" if selected_path_cl >= 20 else "Nascent Soul"
            native_selected = selected.get("feature_record_hash_kind") == NATIVE_COMMITMENT_KIND
            source_path_kind = (
                selected["_path_record_id"].rsplit(".", 1)[1] if native_selected
                else _IMMORTAL_FEATURE_SOURCE_ADAPTERS[selected["record_id"]]["path_kind"]
            )
            same_path_sources = [
                row for row in available
                if row["_path_record_id"] == selected["_path_record_id"]
                and (row.get("feature_record_hash_kind") == NATIVE_COMMITMENT_KIND) == native_selected
            ]
            source_ids = {row["record_id"] for row in same_path_sources}
            scores = score_state(point_cl)
            key_ability = (((path_records[selected["_path_record_id"]].get("compatibility") or {}).get("factory") or {}).get("stage2_authority") or {}).get("key_ability")
            if key_ability not in {"STR", "DEX", "CON", "INT", "WIS", "CHA"} or type(scores.get(key_ability)) is not int:
                raise FoundryError(
                    "CG1_IMMORTAL_ART_AUTHORITY_MISSING",
                    "The selected Path has no authoritative key ability score at the Art construction point.",
                    details={"path_id": selected["_path_record_id"], "key_ability": key_ability, "construction_cl": point_cl},
                    status_code=409,
                )
            modifier = math.floor((scores[key_ability] - 10) / 2)
            request = {
                "schema": "TianxiaFoundry.ImmortalArtRequest.v1",
                "seed": self._constructed_recipe_seed(
                    project, self._constructed_recipe_intent_hash(run, intent_doc, intent_hash), "immortal_art", ordinal,
                    legacy_seed=f"{run['project_id']}:{intent_hash}:immortal_art:{ordinal}",
                    run=run,
                ),
                "project_id": run["project_id"],
                "cl": point_cl,
                "pb": 2 + (point_cl - 1) // 4,
                "path_id": selected["_path_record_id"],
                "path_kind": source_path_kind,
                "path_name": selected["_path_name"],
                "key_ability": key_ability,
                "key_ability_modifier": modifier,
                "owning_path_cl": int(selected_path_cl),
                "path_realm": selected_realm,
                "known_spheres": [
                    {
                        "sphere_id": entry["record_id"],
                        "display_name": (records.get(entry["record_id"]) or {}).get("display_name") or entry["record_id"],
                    }
                    for entry in rows
                    if isinstance(entry, dict)
                    and entry.get("kind") in self._SPHERE_ROW_KINDS
                    and type(entry.get("effective_cl")) is int
                    and entry["effective_cl"] <= point_cl
                    and isinstance(entry.get("record_id"), str)
                    and isinstance(records.get(entry["record_id"]), dict)
                    and records[entry["record_id"]].get("content_type") == "sphere"
                ],
                "known_sources": same_path_sources,
                "source_record_id": selected["record_id"],
                "art_ordinal": ordinal,
                "factor_ids": [],
                "burdens": [],
                "special_scale_cost": 0,
                "gm_review_approved": False,
            }
            art = construct_immortal_art(authority, request)
            record = build_immortal_art_record(art)
            previous_source_ids.add(selected["record_id"])
            constructed.append((art, record))
        return constructed

    def _materialize_constructed_arts(
        self,
        run: dict[str, Any],
        authority_db: Database,
        *,
        phase: str,
        plan: dict[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Lock every Factory-constructed record named by the accepted plan.

        Manual/source and Recorded Art rows are removed while re-deriving the
        ordinary base rows; the resulting identities are compared separately
        for the Manual bundle and Forged Techniques before any record is
        inserted into the authority database.
        """
        from project_store.service import ProjectStore
        from character_creation.constructed_arts.manual import (
            MANUAL_PACK_ID,
            RECORDED_ART_CONSTRUCTION_KIND,
            RECORDED_ART_PACK_ID,
        )
        from character_creation.constructed_arts.immortal_art import IMMORTAL_ART_KIND
        from character_creation.constructed_arts.records import constructed_art_contract, IMMORTAL_ART_RECORD_PACK_ID

        proposal = (plan or {}).get("stage2_proposal") if isinstance(plan, dict) else None
        choices = proposal.get("choices") if isinstance(proposal, dict) else None
        if not isinstance(choices, list):
            return None
        relevant_kinds = {
            "training_source_access",
            RECORDED_ART_CONSTRUCTION_KIND,
            "forged_technique_creation",
            "immortal_art_creation",
            "equipment_acquisition",
        }
        if not any(
            isinstance(entry, dict) and entry.get("kind") in relevant_kinds
            for entry in choices
        ):
            return None
        store = self.projects if authority_db is self.db else ProjectStore(authority_db)
        project = store.get_project(run["project_id"])["project"]

        records = self._locked_records_for_run(run, authority_db=authority_db)
        # A Path the model chose (not an owner lock) is not a project-locked
        # record; the row builder reconstructs it from the frozen authority, so
        # this re-derivation must too (a delegated multi-Path CL18 build failed
        # CG1_IMMORTAL_ART_AUTHORITY_MISSING here, 2026-09-23).
        planned_path_ids = list(dict.fromkeys(
            entry.get("record_id") for entry in choices
            if isinstance(entry, dict) and entry.get("kind") == "path_acquisition" and isinstance(entry.get("record_id"), str)
        ))
        missing_path_ids = [path_id for path_id in planned_path_ids if not isinstance(records.get(path_id), dict)]
        if missing_path_ids:
            self._add_delegated_path_records(run, records, missing_path_ids, db=authority_db if authority_db is not None else self.db, store=store)

        def is_manual_source(entry: dict[str, Any]) -> bool:
            if entry.get("kind") != "training_source_access":
                return False
            record_id = entry.get("record_id")
            if not isinstance(record_id, str):
                return False
            if record_id.startswith("tianxia.constructed.manual."):
                return True
            record = records.get(record_id)
            contract = constructed_art_contract(record) if isinstance(record, dict) else None
            return bool(
                isinstance(record, dict)
                and record.get("content_type") == "manual"
                and (record.get("content_binding") or {}).get("pack_id") == MANUAL_PACK_ID
                and isinstance(contract, dict)
                and contract.get("kind") == "manual"
            )

        def is_manual_art(entry: dict[str, Any]) -> bool:
            return entry.get("kind") == RECORDED_ART_CONSTRUCTION_KIND

        def is_forged(entry: dict[str, Any]) -> bool:
            return entry.get("kind") == "forged_technique_creation"

        def is_immortal(entry: dict[str, Any]) -> bool:
            return entry.get("kind") == "immortal_art_creation"

        def is_starting_kit(entry: dict[str, Any]) -> bool:
            return entry.get("kind") == "equipment_acquisition" and str(entry.get("record_id") or "").startswith("tianxia.constructed.starting_kit.")

        manual_source_rows = [entry for entry in choices if isinstance(entry, dict) and is_manual_source(entry)]
        manual_art_rows = [entry for entry in choices if isinstance(entry, dict) and is_manual_art(entry)]
        forged_rows = [entry for entry in choices if isinstance(entry, dict) and is_forged(entry)]
        immortal_rows = [entry for entry in choices if isinstance(entry, dict) and is_immortal(entry)]
        kit_rows = [entry for entry in choices if isinstance(entry, dict) and is_starting_kit(entry)]
        if not manual_source_rows and not manual_art_rows and not forged_rows and not immortal_rows and not kit_rows:
            return None

        intent_doc = (
            plan.get("canonical_selection_intent")
            if isinstance(plan.get("canonical_selection_intent"), dict)
            else {}
        )
        intent_hash = (
            (plan.get("materialization_receipt") or {}).get("canonical_intent_hash")
            if isinstance(plan.get("materialization_receipt"), dict)
            else None
        )
        if not isinstance(intent_hash, str):
            raise FoundryError(
                "CG1_CONSTRUCTED_ART_SEED_MISSING",
                "The accepted plan carries no canonical intent hash to seed its constructed arts.",
                details={"phase": phase},
            )
        target_cl = frozen_owner_target_cl(project)

        # Remove only constructed rows.  Ordinary training-source access
        # remains part of the immutable plan and is preserved for Stage 2.
        base_rows = [
            entry
            for entry in choices
            if isinstance(entry, dict)
            and not is_manual_source(entry)
            and not is_manual_art(entry)
            and not is_forged(entry)
            and not is_immortal(entry)
            and not is_starting_kit(entry)
        ]

        manual_bundles: list[dict[str, Any]] = []
        manual_records: list[dict[str, Any]] = []
        if manual_source_rows or manual_art_rows:
            acquisition = intent_doc.get("acquisition_intent") if isinstance(intent_doc, Mapping) else None
            has_manual_collection_authority = isinstance(acquisition, Mapping) and isinstance(acquisition.get("manual_collection"), Mapping)
            # A pre-policy accepted plan has one source row and child rows;
            # keep its exact legacy bundle identity.  New collection plans
            # rederive the whole collection from the persisted authority,
            # including the one-book roll result.
            if not has_manual_collection_authority and len(manual_source_rows) == 1 and manual_art_rows:
                manual_bundle, manual_records = self._manual_constructions(
                    run,
                    project,
                    intent_doc,
                    base_rows,
                    records,
                    target_cl,
                    intent_hash=intent_hash,
                )
                manual_bundles = [manual_bundle]
            else:
                manual_bundles, manual_records, _manual_collection_roll = self._manual_collection_constructions(
                    run,
                    project,
                    intent_doc,
                    base_rows,
                    records,
                    target_cl,
                    intent_hash=intent_hash,
                )
            records.update({
                record["record_id"]: record
                for record in manual_records
                if isinstance(record, dict) and isinstance(record.get("record_id"), str)
            })

        forged_constructed = self._forged_technique_constructions(
            run,
            project,
            intent_doc,
            base_rows,
            records,
            target_cl,
            intent_hash=intent_hash,
        ) if forged_rows else []
        immortal_constructed = [
            (art, record)
            for art, record, _refinement in self._stable_immortal_arts(
                run,
                project,
                intent_doc,
                base_rows,
                records,
                target_cl,
                intent_hash=intent_hash,
                authority_db=authority_db,
            )
        ] if immortal_rows else []

        manual_choice_rows = [
            entry
            for entry in choices
            if isinstance(entry, dict) and (is_manual_source(entry) or is_manual_art(entry))
        ]
        expected_manual_ids = [entry.get("record_id") for entry in manual_choice_rows]
        expected_art_ids = [entry.get("record_id") for entry in manual_art_rows]
        actual_manual_ids: list[str] = []
        manual_by_id = {
            bundle["manual"]["record_id"]: bundle
            for bundle in manual_bundles
        }
        art_by_id = {
            art["record_id"]: art
            for bundle in manual_bundles
            for art in bundle["recorded_arts"]
        }
        source_iter = iter(manual_bundles)
        for entry in manual_choice_rows:
            if is_manual_source(entry):
                bundle = next(source_iter, None)
                if bundle is not None:
                    actual_manual_ids.append(bundle["manual"]["record_id"])
            elif is_manual_art(entry) and entry.get("record_id") in art_by_id:
                actual_manual_ids.append(entry["record_id"])
        if expected_manual_ids != actual_manual_ids:
            raise FoundryError(
                "CG1_CONSTRUCTED_ART_MISMATCH",
                "The accepted plan's Manual and Recorded Art rows do not re-derive from the frozen authority.",
                details={
                    "phase": phase,
                    "expected_record_ids": expected_manual_ids,
                    "derived_record_ids": actual_manual_ids,
                },
                status_code=409,
            )
        expected_forged_ids = [entry.get("record_id") for entry in forged_rows]
        actual_forged_ids = [record["record_id"] for _technique, record in forged_constructed]
        if expected_forged_ids != actual_forged_ids:
            raise FoundryError(
                "CG1_CONSTRUCTED_ART_MISMATCH",
                "The accepted plan's Forged Technique rows do not re-derive from the frozen authority.",
                details={
                    "phase": phase,
                    "expected_record_ids": expected_forged_ids,
                    "derived_record_ids": actual_forged_ids,
                },
                status_code=409,
            )

        expected_immortal_ids = [entry.get("record_id") for entry in immortal_rows]
        actual_immortal_ids = [record["record_id"] for _art, record in immortal_constructed]
        if expected_immortal_ids != actual_immortal_ids:
            raise FoundryError(
                "CG1_CONSTRUCTED_ART_MISMATCH",
                "The accepted plan's Immortal Art rows do not re-derive from the frozen authority.",
                details={
                    "phase": phase,
                    "expected_record_ids": expected_immortal_ids,
                    "derived_record_ids": actual_immortal_ids,
                },
                status_code=409,
            )

        starting_kit = self._starting_kit_construction(
            intent_doc, intent_hash, int(target_cl),
            owner_gear_preferences=(run.get("request") or {}).get("owner_gear_preferences") or [],
            owner_gear_requirements=(run.get("request") or {}).get("owner_gear_requirements") or [],
            run=run,
        ) if kit_rows else None
        expected_kit_ids = [entry.get("record_id") for entry in kit_rows]
        actual_kit_ids = [starting_kit[1]["record_id"]] if starting_kit is not None else []
        if expected_kit_ids != actual_kit_ids:
            raise FoundryError(
                "CG1_CONSTRUCTED_ART_MISMATCH",
                "The accepted plan's starting-kit row does not re-derive from the frozen kit decision.",
                details={"phase": phase, "expected_record_ids": expected_kit_ids, "derived_record_ids": actual_kit_ids},
                status_code=409,
            )

        constructed_records = list(manual_records) + [
            record for _technique, record in forged_constructed
        ] + [record for _art, record in immortal_constructed] + (
            [starting_kit[1]] if starting_kit is not None else []
        )
        if not constructed_records:
            return None
        with authority_db.transaction() as conn:
            receipts = store.insert_constructed_art_records(
                conn,
                run["project_id"],
                constructed_records,
            )
        receipt_by_id = {
            record["record_id"]: receipt
            for record, receipt in zip(constructed_records, receipts)
        }
        manual_receipt_rows: list[dict[str, Any]] = []
        recorded_art_receipt_rows: list[dict[str, Any]] = []
        immortal_receipt_rows: list[dict[str, Any]] = []
        if manual_bundles:
            learned_at_cl = {
                entry["record_id"]: int(entry["effective_cl"])
                for entry in manual_art_rows
                if isinstance(entry.get("record_id"), str)
            }
            for bundle in manual_bundles:
                manual = bundle["manual"]
                manual_receipt_rows.append({
                    "record_id": manual["record_id"],
                    "name": manual["display_name"],
                    "status": receipt_by_id[manual["record_id"]]["status"],
                    **({"collection": deepcopy(manual.get("collection"))} if isinstance(manual.get("collection"), Mapping) else {}),
                })
            for art in [
                art
                for bundle in manual_bundles
                for art in bundle["recorded_arts"]
            ]:
                row = {
                    "record_id": art["record_id"],
                    "name": art["display_name"],
                    "technique_name": art["technique_name"],
                    "status": receipt_by_id[art["record_id"]]["status"],
                }
                if art["record_id"] in learned_at_cl:
                    row["learned_at_cl"] = learned_at_cl[art["record_id"]]
                recorded_art_receipt_rows.append(row)
        for art, record in immortal_constructed:
            immortal_receipt_rows.append({
                "record_id": record["record_id"],
                "art_id": art["art_id"],
                "name": art["display_name"],
                "cl_created": art["cl_created"],
                "source_record_id": art["source_record_id"],
                "status": receipt_by_id[record["record_id"]]["status"],
            })

        return {
            "schema": "TianxiaFoundry.ConstructedArtsReceipt.v1",
            "phase": phase,
            "route_origin": "factory_constructed",
            "manuals": manual_receipt_rows,
            "recorded_arts": recorded_art_receipt_rows,
            "forged_techniques": [
                {
                    "record_id": record["record_id"],
                    "technique_id": technique["technique_id"],
                    "name": technique["name"],
                    "status": receipt_by_id[record["record_id"]]["status"],
                }
                for technique, record in forged_constructed
            ],
            "immortal_arts": immortal_receipt_rows,
            "starting_kits": [
                {"record_id": starting_kit[1]["record_id"], "status": receipt_by_id[starting_kit[1]["record_id"]]["status"]}
            ] if starting_kit is not None else [],
        }

    def _historical_stage2_rows_match_derived(
        self,
        historical_rows: list[dict[str, Any]],
        derived_rows: list[dict[str, Any]],
        *,
        run: dict[str, Any],
        project: dict[str, Any],
        intent: CanonicalSelectionIntent,
    ) -> bool:
        """Compare historical rows without promoting their representation.

        Older complete-plan producers emitted one representative Path feature
        per CL and used ``level-choice`` for a CL1 ordinary Talent.  The
        current materializer resolves the exact source-authorized feature and
        channel itself, so those historical representations are compatible
        only when they identify the same frozen progression/record authority.
        Explanatory text on typed-none rows is likewise compatibility metadata,
        not a mechanical input.
        """
        if len(historical_rows) != len(derived_rows):
            return False

        def parameters(row: dict[str, Any]) -> dict[str, Any]:
            raw = row.get("parameters")
            if not isinstance(raw, dict):
                raw = {}
            if row.get("kind") == "typed_none":
                return {
                    key: deepcopy(raw[key])
                    for key in ("target", "reason_code")
                    if key in raw
                }
            return deepcopy(raw)

        selected_paths = [
            value
            for value in (intent.as_dict().get("selected_by_slot") or {}).get("path_choice") or []
            if isinstance(value, str)
        ]
        path_authority = NonSphereAuthorityService(self.db)
        path_feature_alternatives: dict[tuple[int, str], set[str]] = {}
        for path_id in selected_paths:
            path_record = path_authority.project_locked_path_catalog_record(path_id)
            authority = (
                path_record.get("compatibility", {}).get("factory", {}).get("stage2_authority") or {}
                if isinstance(path_record, dict)
                else {}
            )
            for raw_cl, progression in (authority.get("progression_by_cl") or {}).items():
                if not isinstance(progression, dict):
                    continue
                try:
                    effective_cl = int(raw_cl)
                except (TypeError, ValueError):
                    continue
                path_feature_alternatives[(effective_cl, path_id)] = {
                    value
                    for value in progression.get("feature_record_ids") or []
                    if isinstance(value, str)
                }

        records = self._locked_records_for_run(run)
        for historical, derived in zip(historical_rows, derived_rows):
            if not isinstance(historical, dict) or not isinstance(derived, dict):
                return False
            if (
                historical.get("kind") == derived.get("kind")
                and historical.get("effective_cl") == derived.get("effective_cl")
                and historical.get("record_id") == derived.get("record_id")
                and historical.get("acquisition_channel") == derived.get("acquisition_channel")
                and parameters(historical) == parameters(derived)
            ):
                continue
            if (
                historical.get("kind") != derived.get("kind")
                or historical.get("effective_cl") != derived.get("effective_cl")
                or parameters(historical) != parameters(derived)
            ):
                return False

            kind = derived.get("kind")
            if kind == "level_advance":
                try:
                    effective_cl = int(derived.get("effective_cl"))
                except (TypeError, ValueError):
                    return False
                alternatives = set()
                for path_id in selected_paths:
                    alternatives.update(path_feature_alternatives.get((effective_cl, path_id), set()))
                if (
                    derived.get("record_id") not in alternatives
                    or historical.get("record_id") not in alternatives
                    or historical.get("acquisition_channel") != derived.get("acquisition_channel")
                ):
                    return False
                continue

            if kind == "level_talent_acquisition":
                if historical.get("record_id") != derived.get("record_id"):
                    return False
                # Established plans represented the CL1 ordinary-Talent row as
                # level-choice even though the current route resolves it to the
                # explicit AI-bootstrap/sect-trial free-at-CL1 channel.
                if (
                    historical.get("acquisition_channel") != "level-choice"
                    or "cl1-talent" not in str(derived.get("acquisition_channel"))
                ):
                    return False
                record = records.get(str(historical.get("record_id")))
                if not isinstance(record, dict):
                    return False
                try:
                    self._resolve_event_authority(
                        record,
                        project,
                        requested_kind=kind,
                        requested_channel="level-choice",
                        effective_cl=int(historical.get("effective_cl")),
                        field="historical_stage2_record",
                    )
                except (FoundryError, TypeError, ValueError):
                    return False
                continue

            if kind == "origin_insight_acquisition":
                if {
                    historical.get("acquisition_channel"),
                    derived.get("acquisition_channel"),
                } == {"origin-selection", "origin-insight-selection"}:
                    continue

            return False
        return True

    def _server_materialized_stage2_proposal(
        self,
        run: dict[str, Any],
        project: dict[str, Any],
        intent: CanonicalSelectionIntent,
        plan: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Materialize explicit acquisition intent into Stage 2 request rows.

        The common production response supplies only the acquisition objects
        that are not derivable from the frozen authority.  Existing complete
        Stage 2 rows are retained solely as compatibility input; they are
        validated and compared by the Stage 2 authority rather than trusted as
        a new authority surface.
        """
        existing = plan.get("stage2_proposal")
        rows = self._derive_stage2_rows_from_frozen_authority(run, project, intent)
        result = {
            "schema_version": "TianxiaFoundry.Stage2AdvancementProposal.v2",
            "project_id": run["project_id"],
            "expected_project_revision": run["starting_revision"] + 1,
            "expected_content_lock_hash": run["request"].get("content_lock_hash"),
            "target_cl": frozen_owner_target_cl(project),
            "idempotency_key": "cg1.materialized.stage2." + intent.intent_hash[:32],
            "choices": rows,
        }
        if isinstance(existing, dict) and isinstance(existing.get("choices"), list) and existing.get("choices"):
            def semantic_rows(value: Any) -> list[dict[str, Any]]:
                return [
                    {
                        "kind": "cultivation_insight_acquisition" if row.get("kind") == "insight_acquisition" else row.get("kind"),
                        "effective_cl": row.get("effective_cl"),
                        "record_id": row.get("record_id"),
                        "acquisition_channel": row.get("acquisition_channel"),
                        "parameters": deepcopy(row.get("parameters") or {}),
                    }
                    for row in value
                    if isinstance(row, dict)
                ]

            historical_semantics = semantic_rows(existing.get("choices"))
            derived_semantics = semantic_rows(rows)
            if not self._historical_stage2_rows_match_derived(
                historical_semantics,
                derived_semantics,
                run=run,
                project=project,
                intent=intent,
            ):
                raise FoundryError(
                    "CG1_HISTORICAL_STAGE2_MISMATCH",
                    "Historical Stage 2 rows are compatibility evidence only and do not equal the server-derived proposal.",
                    details={
                        "historical": historical_semantics,
                        "derived": derived_semantics,
                    },
                    status_code=409,
                )
        return result

    def advance_agent_acquisition_correction(self, run_id: str, provider: Any) -> dict[str, Any]:
        """Consume an ANSWERED correction and apply it through the real path.

        Serialised per run: initiation/continuation share one advisory lock, so
        concurrent callers cannot both apply.  A crash after ``_apply_response``
        is recovered from the run's own attempt evidence, and the real mailbox
        row is consumed only after the corrected answer is accepted.
        """

        from character_creation import agent_acquisition_correction as correction
        from character_creation.training_authority_supplement import load_supplement

        with correction.correction_lock(self.db, run_id):
            return self._advance_correction_locked(run_id, provider, correction, load_supplement)

    def _advance_correction_locked(self, run_id, provider, correction, load_supplement) -> dict[str, Any]:
        run = self.get(run_id)
        link = correction.load_link(self.db, run_id)
        if link is None:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_NOT_OPENED",
                "No guarded acquisition correction has been opened for this run.",
                status_code=409,
            )
        latest_attempt = self._latest_attempt_id(run_id)
        attempt_request_sha256 = self._attempt_request_sha256(latest_attempt)
        attempt_response_sha256 = self._attempt_response_sha256(latest_attempt)
        # Guards run BEFORE any recovery shortcut, so a stale, terminal or
        # tampered run cannot converge into a completed state.
        request = run.get("request") if isinstance(run.get("request"), Mapping) else {}
        if isinstance(run.get("starting_revision"), int) and run.get("starting_revision") != link.get("project_revision"):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_STALE",
                "The run's revision no longer matches the recorded correction link.",
                status_code=409,
            )
        current_revision = self._revision(str(run.get("project_id")))
        if current_revision != link.get("project_revision"):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_STALE",
                "The project revision advanced after the correction was opened.",
                details={"linked_revision": link.get("project_revision"), "current_revision": current_revision},
                status_code=409,
            )
        if request.get("request_sha256") != link.get("original_request_sha256"):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_STALE",
                "The frozen request no longer matches the correction link.",
                status_code=409,
            )
        provider_id = settings_provider_id(run) or self._selected_provider_id_for_supplement()
        if provider_id != "agent":
            raise FoundryError(
                "CG1_AGENT_CORRECTION_UNAVAILABLE",
                "The guarded correction requires the agent bridge provider profile.",
                details={"provider_id": provider_id},
                status_code=409,
            )
        if run.get("status") in correction._TERMINAL_STATUSES:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_TERMINAL",
                "The run is terminal; a guarded correction cannot be applied.",
                details={"status": run.get("status")},
                status_code=409,
            )
        request = run.get("request") if isinstance(run.get("request"), Mapping) else {}
        if isinstance(run.get("starting_revision"), int) and run.get("starting_revision") != link.get("project_revision"):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_STALE",
                "The run's revision no longer matches the recorded correction link.",
                status_code=409,
            )
        current_revision = self._revision(str(run.get("project_id")))
        if current_revision != link.get("project_revision"):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_STALE",
                "The project revision advanced after the correction was opened.",
                details={"linked_revision": link.get("project_revision"), "current_revision": current_revision},
                status_code=409,
            )
        if request.get("request_sha256") != link.get("original_request_sha256"):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_STALE",
                "The frozen request no longer matches the correction link.",
                status_code=409,
            )
        response = run.get("response") if isinstance(run.get("response"), Mapping) else {}
        retained_text = response.get("exact_response_text")
        retained_sha = sha256_bytes(str(retained_text).encode("utf-8"))
        if retained_sha != link.get("original_response_sha256"):
            # The run row is only the latest projection: a completed apply
            # replaces it.  The immutable record is the original attempt in the
            # append-only ledger, so a mismatch is only an error when that
            # attempt still records the linked original response.
            ledger_response_sha = self._attempt_response_sha256(link.get("original_attempt_id"))
            already_moved = retained_sha == link.get("pending_response_sha256")
            if not already_moved and ledger_response_sha != link.get("original_response_sha256"):
                raise FoundryError(
                    "CG1_AGENT_CORRECTION_ORIGINAL_CHANGED",
                    "The retained original answer no longer matches the correction link.",
                    status_code=409,
                )
        linked_original_attempt = link.get("original_attempt_id")
        if linked_original_attempt is not None and latest_attempt != linked_original_attempt:
            # The latest attempt may legitimately be this correction's own
            # attempt (accepted, or recorded before a crash).  Anything else is
            # an unrelated attempt and must still be refused.
            if not correction.is_correction_attempt(link, latest_attempt):
                raise FoundryError(
                    "CG1_AGENT_CORRECTION_ATTEMPT_CHANGED",
                    "The run's prior attempt changed after the correction was opened.",
                    details={"linked_attempt_id": linked_original_attempt, "current_attempt_id": latest_attempt},
                    status_code=409,
                )
        provider_id = settings_provider_id(run) or self._selected_provider_id_for_supplement()
        if provider_id != "agent":
            raise FoundryError(
                "CG1_AGENT_CORRECTION_UNAVAILABLE",
                "The guarded correction requires the agent bridge provider profile.",
                details={"provider_id": provider_id},
                status_code=409,
            )
        # The declaration must exist and must still verify: a missing declaration
        # is a refusal, never a silent bypass.
        declared = (run.get("transport") or {}).get("training_authority_supplement") if isinstance(run.get("transport"), Mapping) else None
        if not isinstance(declared, Mapping) or not declared.get("digest"):
            # The projection may have been replaced by a completed apply; the
            # append-only link keeps the declaration the prompt actually carried.
            recorded = link.get("declared_supplement")
            declared = recorded if isinstance(recorded, Mapping) else declared
        digest = declared.get("digest") if isinstance(declared, Mapping) else None
        if not isinstance(digest, str) or not digest:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_SUPPLEMENT_UNDECLARED",
                "The run carries no declared training authority supplement; the correction cannot be verified.",
                status_code=409,
            )
        document_authority = load_supplement(
            self.db, run_id, digest, expected_request_sha256=str(request.get("request_sha256") or "")
        )
        if correction.already_applied(
            run, link, latest_attempt_id=latest_attempt,
            attempt_request_sha256=attempt_request_sha256,
            attempt_response_sha256=self._attempt_response_sha256(latest_attempt),
        ):
            return self._converge_completed_correction(
                run_id, run, link, provider, latest_attempt
            )
        bridge = getattr(provider, "agent_bridge", None)
        request_id = link.get("correction_request_id")
        document = bridge.get(str(request_id)) if bridge is not None and isinstance(request_id, str) else None
        if not isinstance(document, Mapping):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_REQUEST_MISSING",
                "The linked correction request is not available on the bridge.",
                status_code=409,
            )
        # (5) the linked document must match this run, this request and the link.
        if document.get("run_id") != run_id or document.get("request_sha256") != link.get("correction_request_sha256"):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_REQUEST_MISMATCH",
                "The linked correction request does not match the recorded link.",
                details={"document_run_id": document.get("run_id"), "request_id": request_id},
                status_code=409,
            )
        if document.get("schema_name") != str(request.get("required_plan_schema") or document.get("schema_name")):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_REQUEST_MISMATCH",
                "The linked correction request does not carry the run's frozen plan schema.",
                status_code=409,
            )
        if document.get("state") not in {"ANSWERED", "CONSUMED"}:
            raise FoundryError(
                "AI_AGENT_AWAITING_RESPONSE",
                "The Agent bridge has not answered the correction request yet; re-drive this step to collect it.",
                details={"request_id": request_id, "state": document.get("state")},
                status_code=409,
            )
        corrected_text = document.get("response_text")
        if not isinstance(corrected_text, str) or not corrected_text.strip():
            raise FoundryError(
                "CG1_AGENT_CORRECTION_RESPONSE_MISSING",
                "The answered correction request carries no retained answer.",
                status_code=409,
            )
        declared_payload = json.loads(str(document_authority and json.dumps({}) or "{}"))
        del declared_payload
        try:
            original_plan = json.loads(str(retained_text))
            corrected_plan = json.loads(corrected_text)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_RESPONSE_INVALID",
                "The corrected answer or the retained original is not JSON.",
                details={"reason": type(exc).__name__},
                status_code=409,
            ) from exc
        acceptable, reason = correction.correction_adds_only_missing_fields(original_plan, corrected_plan)
        if not acceptable:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_NOT_ADD_ONLY",
                "The corrected answer may only add the missing acquisition keys.",
                details={"reason": reason},
                status_code=409,
            )
        # Record the pending correction receipt before applying, so a crash after
        # application is recoverable from the link plus the run's attempt ledger.
        pending = dict(link)
        pending["pending_response_sha256"] = sha256_bytes(corrected_text.encode("utf-8"))
        pending["pending_attempt_id"] = None  # filled in after the apply records it
        pending["pending_started_at"] = utcnow()
        correction._write_link(self.db, run_id, pending)
        transport = {
            "mode": "STANDARD_API",
            "provider_called": True,
            "provider_id": "agent",
            "transport_kind": "agent_acquisition_correction",
            "submitted_request_sha256": str(request.get("request_sha256") or ""),
            "correction_request_id": request_id,
            "correction_request_sha256": document.get("request_sha256"),
            "complete_request_sha256": request.get("request_sha256"),
            "original_response_sha256": link.get("original_response_sha256"),
            "original_attempt_id": latest_attempt,
            "agent_request_id": request_id,
            "agent_model": document.get("agent_model"),
        }
        result = self._apply_response(
            run_id,
            corrected_text,
            transport,
            submitted_request_sha256=str(request.get("request_sha256") or ""),
            prior_attempt_id=latest_attempt,
            action_type="LOCAL_PROVIDER_CORRECTION",
        )
        new_attempt = self._latest_attempt_id(run_id)
        # Record which ledger row the pending marker corresponds to, so recovery
        # can tell an accepted apply from a rejected attempt with equal bytes.
        marked = correction.load_link(self.db, run_id)
        if isinstance(marked, dict):
            marked["pending_attempt_id"] = new_attempt
            correction._write_link(self.db, run_id, marked)
        settled = self.get(run_id)
        settled_quality = settled.get("quality") if isinstance(settled.get("quality"), Mapping) else {}
        accepted = str(settled_quality.get("status") or "").upper() == "CLEAN"
        if not accepted:
            # A refused corrected answer must stay visible and recoverable: keep
            # the attempt, leave the mailbox row for a further bounded answer,
            # and never report a completed or consumed correction.
            rejected = correction.load_link(self.db, run_id)
            if isinstance(rejected, dict):
                attempts = list(rejected.get("attempts") or [])
                attempts.append({
                    "request_id": request_id,
                    "state": "REJECTED",
                    "attempt_id": new_attempt,
                    "response_sha256": sha256_bytes(corrected_text.encode("utf-8")),
                })
                rejected["attempts"] = attempts
                rejected["rejected_response_sha256"] = sha256_bytes(corrected_text.encode("utf-8"))
                rejected["pending_response_sha256"] = None
                rejected["pending_attempt_id"] = None
                correction._write_link(self.db, run_id, rejected)
            return {
                "schema": correction.CORRECTION_SCHEMA,
                "run_id": run_id,
                "state": "REJECTED_RETAINED",
                "correction_request_id": request_id,
                "corrected_response_sha256": sha256_bytes(corrected_text.encode("utf-8")),
                "attempt_id": new_attempt,
                "run_status": (result or {}).get("status") if isinstance(result, Mapping) else None,
                "mailbox_state": document.get("state"),
                "applied": False,
            }
        # Consume the real mailbox row only after the corrected answer is accepted.
        consumed = None
        consume_error: str | None = None
        if isinstance(request_id, str) and bridge is not None:
            try:
                consumed = bridge.consume(request_id, run_id=run_id)
            except FoundryError as exc:
                consume_error = exc.code
                try:
                    consumed = bridge.get(request_id)
                except FoundryError:
                    consumed = None
        observed_state = consumed.get("state") if isinstance(consumed, Mapping) else None
        row_consumed = observed_state == "CONSUMED"
        updated = correction.load_link(self.db, run_id)
        if isinstance(updated, dict):
            # Only a genuinely consumed row completes the correction; an
            # accepted-but-unconsumed outcome stays distinct and recoverable.
            if row_consumed:
                updated["completed_response_sha256"] = sha256_bytes(corrected_text.encode("utf-8"))
                updated["completed_attempt_id"] = new_attempt
            updated["accepted_response_sha256"] = sha256_bytes(corrected_text.encode("utf-8"))
            updated["accepted_attempt_id"] = new_attempt
            attempts = list(updated.get("attempts") or [])
            attempts.append({
                "request_id": request_id,
                "state": observed_state or "ACCEPTED_UNCONSUMED",
                "attempt_id": new_attempt,
                "consume_error": consume_error,
                "response_sha256": sha256_bytes(corrected_text.encode("utf-8")),
            })
            updated["attempts"] = attempts
            correction._write_link(self.db, run_id, updated)
        return {
            "schema": correction.CORRECTION_SCHEMA,
            "run_id": run_id,
            "state": "APPLIED",
            "correction_request_id": request_id,
            "corrected_response_sha256": sha256_bytes(corrected_text.encode("utf-8")),
            "attempt_id": new_attempt,
            "run_status": (result or {}).get("status") if isinstance(result, Mapping) else None,
            "mailbox_state": observed_state,
            "consume_error": consume_error,
            "state": "APPLIED" if row_consumed else "ACCEPTED_UNCONSUMED",
            "applied": True,
        }

    def _attempt_response_sha256(self, attempt_id: str | None) -> str | None:
        if not isinstance(attempt_id, str) or not attempt_id:
            return None
        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT response_sha256 FROM character_creation_attempt_history WHERE attempt_id=?",
                (attempt_id,),
            ).fetchone()
        if row is None:
            return None
        try:
            value = row["response_sha256"]
        except (TypeError, IndexError, KeyError):
            return None
        return value if isinstance(value, str) else None

    def _converge_completed_correction(self, run_id, run, link, provider, latest_attempt) -> dict[str, Any]:
        """Finish a correction that already reached the ledger.

        Consume failures stay observable: the returned state reports the real
        mailbox state and whether the row was consumed, and never claims a
        completion the bridge did not accept.
        """

        from character_creation import agent_acquisition_correction as correction

        request_id = link.get("correction_request_id")
        bridge = getattr(provider, "agent_bridge", None)
        if not isinstance(request_id, str) or bridge is None:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_REQUEST_MISSING",
                "The completed correction has no resolvable mailbox request.",
                status_code=409,
            )
        document = bridge.get(request_id)
        if document.get("run_id") != run_id or document.get("request_sha256") != link.get("correction_request_sha256"):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_REQUEST_MISMATCH",
                "The linked correction request does not match the recorded link.",
                status_code=409,
            )
        consume_error: str | None = None
        state = document.get("state")
        if state == "ANSWERED":
            try:
                consumed = bridge.consume(request_id, run_id=run_id)
                state = consumed.get("state") if isinstance(consumed, Mapping) else state
            except FoundryError as exc:
                consume_error = exc.code
        row_consumed = state == "CONSUMED"
        updated = dict(link)
        # The completion marker is written only for a genuinely consumed row; an
        # accepted-but-unconsumed outcome stays distinct and recoverable.
        if row_consumed and not updated.get("completed_response_sha256"):
            updated["completed_response_sha256"] = (
                link.get("accepted_response_sha256")
                or link.get("pending_response_sha256")
                or self._attempt_response_sha256(latest_attempt) or ""
            )
            updated["completed_attempt_id"] = (
                link.get("accepted_attempt_id") or link.get("pending_attempt_id") or latest_attempt
            )
            correction._write_link(self.db, run_id, updated)
        return {
            "schema": correction.CORRECTION_SCHEMA,
            "run_id": run_id,
            "state": "COMPLETED" if row_consumed else "ACCEPTED_UNCONSUMED",
            "correction_request_id": request_id,
            "corrected_response_sha256": updated.get("completed_response_sha256"),
            "attempt_id": updated.get("completed_attempt_id") or latest_attempt,
            "run_status": run.get("status"),
            "mailbox_state": state,
            "consume_error": consume_error,
            "applied": False,
        }

    def _attempt_request_sha256(self, attempt_id: str | None) -> str | None:
        if not isinstance(attempt_id, str) or not attempt_id:
            return None
        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT request_sha256 FROM character_creation_attempt_history WHERE attempt_id=?",
                (attempt_id,),
            ).fetchone()
        if row is None:
            return None
        try:
            value = row["request_sha256"]
        except (TypeError, IndexError, KeyError):
            return None
        return value if isinstance(value, str) else None

    def open_agent_acquisition_correction(self, run_id: str, provider: Any) -> dict[str, Any]:
        """Open the guarded same-run agent correction for an acquisition refusal.

        Only a ``STANDARD_API`` run whose retained answer was refused solely for
        the missing acquisition keys is eligible.  The original request, envelope
        and retained response are never modified; a fresh authentic mailbox
        request is opened and linked append-only to them.
        """

        from character_creation import agent_acquisition_correction as correction
        from character_creation.training_authority_supplement import load_supplement, publish_supplement, supplement_digest

        with correction.correction_lock(self.db, run_id):
            return self._open_correction_locked(run_id, provider, correction, load_supplement)

    def _open_correction_locked(self, run_id, provider, correction, load_supplement) -> dict[str, Any]:
        from character_creation.training_authority_supplement import supplement_digest

        run = self.get(run_id)
        eligible, reason = correction.correction_eligibility(run)
        if not eligible:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_UNAVAILABLE",
                "This run cannot open a guarded same-run acquisition correction.",
                details={"reason": reason},
                status_code=409,
            )
        bridge = getattr(provider, "agent_bridge", None)
        if bridge is None or not callable(getattr(bridge, "enqueue", None)):
            raise FoundryError(
                "CG1_AGENT_CORRECTION_UNAVAILABLE",
                "The selected provider is not the agent bridge.",
                details={"reason": "provider_not_agent_bridge"},
                status_code=409,
            )
        settings = provider._settings() if callable(getattr(provider, "_settings", None)) else {}
        settings = settings if isinstance(settings, Mapping) else {}
        if settings.get("provider_id") != "agent":
            raise FoundryError(
                "CG1_AGENT_CORRECTION_UNAVAILABLE",
                "The guarded correction requires the selected agent bridge profile.",
                details={"reason": "provider_not_selected_agent", "provider_id": settings.get("provider_id")},
                status_code=409,
            )
        request = run.get("request") if isinstance(run.get("request"), Mapping) else {}
        response = run.get("response") if isinstance(run.get("response"), Mapping) else {}
        original_plan = json.loads(str(response.get("exact_response_text") or "{}"))
        missing = correction.missing_required_additions(original_plan)
        prompt_text = correction.build_correction_prompt(
            self._provider_prompt(run),
            original_plan=original_plan,
            missing=missing,
            link={"run_id": run_id, "project_revision": run.get("starting_revision"),
                  "original_request_sha256": request.get("request_sha256"),
                  "original_response_sha256": sha256_bytes(str(response.get("exact_response_text") or "").encode("utf-8")),
                  "original_attempt_id": self._latest_attempt_id(run_id)},
        )
        # Declared last: the declaration carries the digest of the final wire.
        prompt_text = self._declare_training_authority_supplement(run, prompt_text)
        # The declaration was produced by the supplement publisher itself; read
        # the digest back from the final wire and prove it resolves and verifies.
        declared = json.loads(prompt_text).get("training_authority_supplement") or {}
        digest = declared.get("digest")
        if not isinstance(digest, str) or not digest:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_SUPPLEMENT_MISMATCH",
                "The correction prompt declares no training authority digest.",
                status_code=409,
            )
        published = load_supplement(
            self.db, run_id, digest, expected_request_sha256=str(request.get("request_sha256") or "")
        )
        if supplement_digest(published) != digest:
            raise FoundryError(
                "CG1_AGENT_CORRECTION_SUPPLEMENT_MISMATCH",
                "The published supplement does not match its declared digest.",
                status_code=409,
            )
        binding = declared
        result = correction.initiate_correction(
            self.db,
            bridge,
            run,
            prompt_text=prompt_text,
            schema_name=str(request.get("required_plan_schema") or "TianxiaFoundry.DelegatedSelectionIntent.v1"),
            max_output_tokens=int(settings.get("max_output_tokens") or 6144),
            provider_id=str(settings.get("provider_id")),
            project_id=str(run.get("project_id")),
            declared_supplement={
                "digest": declared.get("digest"),
                "row_count": declared.get("row_count"),
                "bytes": declared.get("bytes"),
            },
        )
        return {
            "schema": correction.CORRECTION_SCHEMA,
            "run_id": run_id,
            "created": result["created"],
            "link": result["link"],
            "request": {
                key: result["request"].get(key)
                for key in ("request_id", "state", "request_sha256", "created_at", "purpose", "schema_name")
            },
            "supplement": {"digest": binding["digest"], "row_count": binding["row_count"], "bytes": binding["bytes"]},
        }

    def _persist_declared_training_authority_supplement(self, run: Mapping[str, Any], binding: Mapping[str, Any]) -> None:
        """Record the declared supplement on the run so consumption can reverify it."""

        run_id = run.get("run_id")
        if not isinstance(run_id, str) or not run_id:
            return
        with self.db.transaction() as conn:
            row = conn.execute(
                "SELECT transport_json FROM character_creation_runs WHERE run_id=?", (run_id,)
            ).fetchone()
            transport = {}
            if row is not None:
                try:
                    transport = json.loads(row["transport_json"] or "{}")
                except (TypeError, ValueError):
                    transport = {}
            transport = transport if isinstance(transport, dict) else {}
            transport["training_authority_supplement"] = {
                "digest": binding.get("digest"),
                "row_count": binding.get("row_count"),
                "bytes": binding.get("bytes"),
                "schema": binding.get("schema"),
                "run_id": (binding.get("retrieval") or {}).get("run_id") if isinstance(binding.get("retrieval"), Mapping) else None,
            }
            conn.execute(
                "UPDATE character_creation_runs SET transport_json=?, updated_at=? WHERE run_id=?",
                (canonical_json(transport), utcnow(), run_id),
            )

    def _selected_provider_id_for_supplement(self) -> str | None:
        """The configured provider profile, read from persisted selection only."""

        try:
            with self.db.connection() as conn:
                row = conn.execute(
                    "SELECT provider_id FROM ai_provider_selection WHERE singleton=1"
                ).fetchone()
        except Exception:  # pragma: no cover - selection table absent in old data
            return None
        if row is None:
            return None
        try:
            value = row["provider_id"]
        except (TypeError, IndexError, KeyError):
            value = None
        return value if isinstance(value, str) and value else None

    def _require_declared_training_authority_supplement(self, run: Mapping[str, Any]) -> None:
        """Refuse an answer whose declared bound authority is unavailable or altered.

        The provider prompt may declare a run-bound training authority
        supplement.  When it does, the same digest must still resolve for this
        run and request before the answer is consumed, so a plan can never be
        accepted against authority the client could not have read or that was
        changed after the prompt was issued.
        """

        transport = run.get("transport") if isinstance(run, Mapping) else None
        transport = transport if isinstance(transport, Mapping) else {}
        declared = transport.get("training_authority_supplement")
        if not isinstance(declared, Mapping):
            return
        digest = declared.get("digest")
        if not isinstance(digest, str) or not digest:
            raise FoundryError(
                "CG1_TRAINING_AUTHORITY_SUPPLEMENT_DECLARATION_INVALID",
                "The run declares a training authority supplement without a digest.",
                status_code=409,
            )
        request_sha256 = (run.get("request") or {}).get("request_sha256")
        from character_creation.training_authority_supplement import load_supplement

        load_supplement(
            self.db,
            str(run.get("run_id")),
            digest,
            expected_request_sha256=request_sha256 if isinstance(request_sha256, str) else None,
        )

    def _normalize_and_materialize_response(
        self, run: dict[str, Any], plan: dict[str, Any]
    ) -> tuple[dict[str, Any], CanonicalSelectionIntent | None, dict[str, Any] | None]:
        if not self._has_delegated_envelope(run):
            return deepcopy(plan), None, None
        # A declared run-bound authority supplement must still resolve before the
        # answer may be consumed by any path (agent bridge, manual, or provider).
        self._require_declared_training_authority_supplement(run)
        project = self._project(run["project_id"])
        server_output_profile = self._validated_server_owned_output_profile_target(run)
        target_cl = frozen_owner_target_cl(project)
        intent = normalize_selection_intent(
            plan,
            request_sha256=str(run["request"].get("request_sha256") or ""),
            delegated_envelope=run["request"].get("delegated_choice_envelope") or {},
            project=project,
            target_cl=target_cl,
        )
        # Normalize the historical dotted Background IDs against the same
        # frozen package linkage that Stage 2 will consume.  This happens
        # before the intent is injected/rehashed and before Stage 2 derives
        # locked records, so no raw provider alias can survive as authority.
        intent = self._canonicalize_frozen_background_intent(
            intent,
            run["request"].get("delegated_choice_envelope") or {},
        )
        intent = self._server_manual_collection_intent(
            run,
            project,
            intent,
            target_cl=target_cl,
        )
        normalized = inject_canonical_intent(plan, intent, target_cl=target_cl)
        if not isinstance(normalized.get("stage1_response"), dict):
            normalized["stage1_response"] = self._server_materialized_stage1_response(run, intent)
        normalized.setdefault("uncertainties", [])
        normalized.setdefault("fallbacks", [])
        normalized["output_profile"] = (
            {
                "combat_ready": server_output_profile["combat_ready"],
                "profile": server_output_profile["profile"],
            }
            if server_output_profile is not None
            else {"combat_ready": False, "profile": SERVER_OUTPUT_PROFILE_NAME}
        )
        stage2 = self._server_materialized_stage2_proposal(run, project, intent, normalized)
        if stage2 is not None:
            normalized["stage2_proposal"] = stage2
        normalized["materialization_receipt"] = {
            "schema": "TianxiaFoundry.DelegatedMaterializationReceipt.v1",
            "canonical_intent_hash": intent.intent_hash,
            "request_sha256": run["request"].get("request_sha256"),
            "delegated_envelope_sha256": (run["request"].get("delegated_choice_envelope") or {}).get("envelope_sha256"),
            "target_cl": target_cl,
            "stage1_server_owned": True,
            "stage2_server_owned": stage2 is not None,
            "mode": "historical_rows_compatibility_input" if isinstance(plan.get("stage2_proposal"), dict) and isinstance(plan.get("stage2_proposal", {}).get("choices"), list) and plan.get("stage2_proposal", {}).get("choices") else "server_materialized_from_selection_intent",
        }
        return normalized, intent, stage2

    def _validate_complete_response_binding(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        *,
        submitted_request_sha256: str | None = None,
    ) -> None:
        active = str(run["request"].get("request_sha256") or "")
        response_hash = plan.get("request_sha256")
        mismatches: list[str] = []
        if not isinstance(response_hash, str) or response_hash != active:
            mismatches.append("response.request_sha256")
        if submitted_request_sha256 is not None and submitted_request_sha256 != active:
            mismatches.append("submission.request_sha256")
        if mismatches:
            raise FoundryError(
                RESPONSE_BINDING_ERROR,
                RESPONSE_BINDING_MESSAGE,
                details={
                    "mismatched_fields": mismatches,
                    "active_request_sha256": active,
                    "response_request_sha256": response_hash if isinstance(response_hash, str) else None,
                    "submitted_request_sha256": submitted_request_sha256,
                },
                status_code=409,
            )

    @staticmethod
    def _ordinary_response_array_projection(response_text: Any) -> dict[str, Any] | None:
        """Return the small ordinary-array projection used by provenance checks.

        The response may legitimately gain or lose unrelated fields as a
        deterministic correction runs.  The expanded ordinary array and its
        advancement-skeleton mirror are different: every deterministic
        intermediary must preserve them byte-for-byte at the canonical array
        level.  Keep this projection deliberately small so the provenance
        verifier never retains or exposes complete response payloads.
        """
        if not isinstance(response_text, str) or not response_text.strip():
            return None
        try:
            payload = json.loads(response_text)
        except (TypeError, ValueError):
            return None
        if not isinstance(payload, dict):
            return None
        acquisition = payload.get("acquisition_intent")
        if not isinstance(acquisition, dict):
            return None
        ordinary = acquisition.get("ordinary_talent_ids")
        if (
            not isinstance(ordinary, list)
            or not ordinary
            or any(not isinstance(value, str) or not value.strip() for value in ordinary)
        ):
            return None
        selection = payload.get("selection_intent")
        by_slot = selection.get("by_slot") if isinstance(selection, dict) else None
        if not isinstance(by_slot, dict) or "advancement_skeleton" not in by_slot:
            return None
        mirror = by_slot.get("advancement_skeleton")
        if (
            not isinstance(mirror, list)
            or any(not isinstance(value, str) or not value.strip() for value in mirror)
        ):
            return None
        return {
            "ordinary": canonical_json(ordinary),
            "mirror": canonical_json(mirror),
        }

    @staticmethod
    def _ordinary_repair_advancement_choice_intermediary_valid(
        run: dict[str, Any],
        item: dict[str, Any],
        parent: dict[str, Any],
        *,
        request_sha256: str,
        item_projection: dict[str, Any],
        parent_projection: dict[str, Any],
    ) -> bool:
        """Prove one provider-backed Advancement Choice is target-only.

        A provider selector may be appended between an ordinary-repair row
        and a later Retry Local Build, but it is not a deterministic server
        repair.  Keep this exception narrow: bind the provider receipt and
        frozen target to the immediate parent, then prove that the canonical
        response changed only the selected milestone container.
        """
        if (
            not isinstance(run, dict)
            or not isinstance(item, dict)
            or not isinstance(parent, dict)
            or not isinstance(request_sha256, str)
            or not request_sha256
            or item_projection != parent_projection
        ):
            return False
        item_text = item.get("_response_text")
        parent_text = parent.get("_response_text")
        item_hash = item.get("_response_sha256")
        parent_hash = parent.get("_response_sha256")
        if (
            not isinstance(item_text, str)
            or not item_text.strip()
            or not isinstance(parent_text, str)
            or not parent_text.strip()
            or not isinstance(item_hash, str)
            or item_hash != sha256_bytes(item_text.encode("utf-8"))
            or not isinstance(parent_hash, str)
            or parent_hash != sha256_bytes(parent_text.encode("utf-8"))
            or item.get("_parent_id") != parent.get("attempt_id")
        ):
            return False

        item_transport = item.get("_transport")
        marker = item_transport.get("local_correction") if isinstance(item_transport, dict) else None
        synthetic_leaf = item.get("attempt_id") == "__current_unappended_deterministic_correction__"
        if (
            not isinstance(item_transport, dict)
            or not isinstance(marker, dict)
            or item_transport.get("provider_called") is not True
            or type(item_transport.get("automatic_retries")) is not int
            or item_transport.get("automatic_retries") != 0
            or item_transport.get("complete_request_sha256") != request_sha256
            or item_transport.get("prior_attempt_id") != parent.get("attempt_id")
            or item_transport.get("provider_id") not in _LOCAL_PROVIDER_IDS
            or "local_recovery" in item_transport
            or (not synthetic_leaf and (
                item.get("action_type") != "LOCAL_PROVIDER_CORRECTION"
                or item.get("status") not in {"BLOCKED", "READY_FOR_REVIEW"}
                or item.get("run_id") != run.get("run_id")
                or item.get("project_id") != run.get("project_id")
                or item.get("request_sha256") != request_sha256
            ))
        ):
            return False
        if "mode" in item_transport and item_transport.get("mode") != run.get("execution_mode"):
            return False
        binding = item.get("binding") if isinstance(item.get("binding"), dict) else None
        if not synthetic_leaf and (
            not isinstance(binding, dict)
            or binding.get("active_request_sha256") != request_sha256
            or binding.get("submitted_request_sha256") not in (None, request_sha256)
        ):
            return False

        diagnostic = marker.get("validator_diagnostic")
        target = CharacterCreationExecutionService._provider_target_scoped_repair_target(
            diagnostic,
            run=run,
            prior_response=parent_text,
        )
        selected_option_id = marker.get("selected_option_id")
        options = target.get("options") if isinstance(target, dict) else None
        selected = options.get(selected_option_id) if isinstance(options, dict) else None
        if (
            not isinstance(target, dict)
            or target.get("target_kind") != "advancement_choice"
            or marker.get("target_scoped_merge") is not True
            or marker.get("deterministic_server_repair") is True
            or marker.get("attempted") is not True
            or marker.get("explicit") is not True
            or marker.get("status") != "RETAINED_FOR_VALIDATION"
            or marker.get("provider_id") != item_transport.get("provider_id")
            or ("provider_called" in marker and marker.get("provider_called") is not True)
            or marker.get("request_sha256") != request_sha256
            or marker.get("prior_attempt_id") != parent.get("attempt_id")
            or marker.get("prior_response_sha256") != parent_hash
            or marker.get("applied_response_sha256") != item_hash
            or marker.get("field") != target.get("field")
            or marker.get("milestone_id") != target.get("milestone_id")
            or not isinstance(selected_option_id, str)
            or selected_option_id not in (target.get("option_ids") or [])
            or not isinstance(selected, dict)
            or marker.get("selected_kind") != selected.get("kind")
            or marker.get("validator_diagnostic") != diagnostic
        ):
            return False

        diagnostic_details = diagnostic.get("details") if isinstance(diagnostic, dict) else None
        diagnostic_cl = (
            diagnostic_details.get("effective_cl", diagnostic_details.get("cl"))
            if isinstance(diagnostic_details, dict)
            else None
        )
        if target.get("effective_cl") != diagnostic_cl:
            return False

        # The raw provider object is not trusted as a response, but its
        # receipt hashes are retained evidence for this provider-backed row.
        raw_completion = marker.get("raw_provider_completion_sha256")
        raw_response = marker.get("raw_provider_response_sha256")
        if (
            not isinstance(raw_completion, str)
            or not raw_completion.strip()
            or raw_response != raw_completion
            or item_transport.get("provider_completion_sha256") != raw_completion
        ):
            return False
        for key in ("provider_completion_sha256", "provider_response_sha256"):
            marker_value = marker.get(key)
            transport_value = item_transport.get(key)
            if marker_value is not None and not isinstance(marker_value, str):
                return False
            if transport_value is not None and not isinstance(transport_value, str):
                return False
            if marker_value != transport_value:
                return False

        def strict_object(text: str) -> dict[str, Any] | None:
            def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
                result: dict[str, Any] = {}
                for key, value in items:
                    if key in result:
                        raise ValueError("duplicate object key")
                    result[key] = value
                return result

            try:
                value = json.loads(text, object_pairs_hook=pairs)
            except (TypeError, ValueError, json.JSONDecodeError):
                return None
            return value if isinstance(value, dict) else None

        parent_payload = strict_object(parent_text)
        item_payload = strict_object(item_text)
        if parent_payload is None or item_payload is None:
            return False
        if parent_payload.get("request_sha256") != request_sha256 or item_payload.get("request_sha256") != request_sha256:
            return False
        if set(parent_payload) != set(item_payload):
            return False
        for key in set(parent_payload) - {"bounded_choices", "acquisition_intent"}:
            if parent_payload.get(key) != item_payload.get(key):
                return False
        # Explicitly bind the stale redundant echo too.  It must be retained
        # byte-for-value while only the target canonical container changes.
        missing = object()
        if parent_payload.get("advancement_skeleton", missing) != item_payload.get("advancement_skeleton", missing):
            return False

        parent_bounded = parent_payload.get("bounded_choices")
        item_bounded = item_payload.get("bounded_choices")
        parent_acquisition = parent_payload.get("acquisition_intent")
        item_acquisition = item_payload.get("acquisition_intent")
        if (
            not isinstance(parent_bounded, dict)
            or not isinstance(item_bounded, dict)
            or not isinstance(parent_acquisition, dict)
            or not isinstance(item_acquisition, dict)
            or set(parent_bounded) != set(item_bounded)
            or set(parent_acquisition) != set(item_acquisition)
        ):
            return False
        changes_key = "ability_score_changes_by_milestone_id"
        occurrences_key = "insight_occurrences"
        for key in set(parent_bounded) - {changes_key}:
            if parent_bounded.get(key) != item_bounded.get(key):
                return False
        for key in set(parent_acquisition) - {occurrences_key}:
            if parent_acquisition.get(key) != item_acquisition.get(key):
                return False
        parent_changes = parent_bounded.get(changes_key)
        item_changes = item_bounded.get(changes_key)
        parent_occurrences = parent_acquisition.get(occurrences_key)
        item_occurrences = item_acquisition.get(occurrences_key)
        milestone_id = target.get("milestone_id")
        if (
            not isinstance(parent_changes, dict)
            or not isinstance(item_changes, dict)
            or not isinstance(parent_occurrences, list)
            or not isinstance(item_occurrences, list)
            or milestone_id in parent_changes
            or any(
                isinstance(row, dict) and row.get("milestone_id") == milestone_id
                for row in parent_occurrences
            )
        ):
            return False
        selected_value = selected.get("value")
        selected_kind = selected.get("kind")
        expected_changes = deepcopy(parent_changes)
        expected_occurrences = deepcopy(parent_occurrences)
        if (
            not isinstance(selected_value, dict)
            or selected_value.get("kind") != selected_kind
            or selected_value.get("milestone_id") != milestone_id
        ):
            return False
        if selected_kind == "ability_score_change":
            deltas = selected_value.get("deltas")
            if not isinstance(deltas, dict) or not deltas:
                return False
            expected_changes[milestone_id] = {"deltas": deepcopy(deltas)}
        elif selected_kind == "cultivation_insight_acquisition":
            insight_id = selected_value.get("insight_id")
            if not isinstance(insight_id, str) or not insight_id.strip():
                return False
            occurrence = {"milestone_id": milestone_id, "insight_id": insight_id}
            if "parameters" in selected_value:
                if not isinstance(selected_value.get("parameters"), dict):
                    return False
                occurrence["parameters"] = deepcopy(selected_value["parameters"])
            expected_occurrences.append(occurrence)
        else:
            return False
        if selected_kind == "ability_score_change":
            return item_changes == expected_changes and item_occurrences == expected_occurrences
        return item_changes == expected_changes and item_occurrences == expected_occurrences

    @staticmethod
    def _ordinary_repair_historical_recovery_shadow(
        run: dict[str, Any],
        response_text: str,
    ) -> dict[str, Any] | None:
        """Follow only exact provider-free retries after a recovery leaf."""
        if not isinstance(run, dict) or not isinstance(response_text, str) or not response_text.strip():
            return None
        history = run.get("attempt_history")
        if not isinstance(history, list) or len(history) < 3:
            return None
        transport = run.get("transport") if isinstance(run.get("transport"), dict) else None
        if (
            not isinstance(transport, dict)
            or "local_recovery" in transport
            or "local_correction" in transport
            or transport.get("provider_called") is not False
            or type(transport.get("automatic_retries")) is not int
            or transport.get("automatic_retries") != 0
            or transport.get("transfer") != "retry_local_build"
            or transport.get("mode") != run.get("execution_mode")
            or transport.get("provider_id") is not None
        ):
            return None
        request = run.get("request") if isinstance(run.get("request"), dict) else None
        request_sha256 = request.get("request_sha256") if isinstance(request, dict) else None
        if (
            not isinstance(request, dict)
            or not isinstance(request_sha256, str)
            or not request_sha256
            or run.get("status") != "NEEDS_REVIEW"
            or run.get("execution_mode") not in {"STANDARD_API", "AUTO_FINALIZE_WHEN_CLEAN"}
            or request.get("project_id") != run.get("project_id")
            or request.get("project_revision") != run.get("starting_revision")
        ):
            return None
        response_sha256 = sha256_bytes(response_text.encode("utf-8"))
        response_projection = CharacterCreationExecutionService._ordinary_response_array_projection(response_text)
        if response_projection is None:
            return None
        latest = history[-1]
        current_response = run.get("response") if isinstance(run.get("response"), dict) else None
        if (
            not isinstance(latest, dict)
            or not isinstance(current_response, dict)
            or latest.get("prior_attempt_id") != transport.get("prior_attempt_id")
            or latest.get("action_type") != "RETRY_LOCAL_BUILD"
            or latest.get("status") != "BLOCKED"
            or latest.get("response_text") != response_text
            or latest.get("response_sha256") != response_sha256
            or current_response.get("exact_response_text") != response_text
            or current_response.get("response_sha256") != response_sha256
        ):
            return None
        recovery_indexes = [
            index
            for index, item in enumerate(history)
            if isinstance(item, dict)
            and isinstance(
                (item.get("binding") or {}).get("transport")
                if isinstance(item.get("binding"), dict)
                else None,
                dict,
            )
            and isinstance(
                ((item.get("binding") or {}).get("transport") or {}).get("local_recovery")
                if isinstance(item.get("binding"), dict)
                and isinstance((item.get("binding") or {}).get("transport"), dict)
                else None,
                dict,
            )
        ]
        if not recovery_indexes:
            return None
        recovery_index = recovery_indexes[-1]
        if recovery_index >= len(history) - 1:
            return None
        expected_parent_id = history[recovery_index].get("attempt_id")
        if not isinstance(expected_parent_id, str) or not expected_parent_id.strip():
            return None
        for item in history[recovery_index + 1 :]:
            if not isinstance(item, dict):
                return None
            binding = item.get("binding") if isinstance(item.get("binding"), dict) else None
            item_transport = binding.get("transport") if isinstance(binding, dict) else None
            item_text = item.get("response_text")
            item_hash = item.get("response_sha256")
            item_projection = CharacterCreationExecutionService._ordinary_response_array_projection(item_text)
            if (
                item.get("run_id") != run.get("run_id")
                or item.get("project_id") != run.get("project_id")
                or item.get("request_sha256") != request_sha256
                or item.get("action_type") != "RETRY_LOCAL_BUILD"
                or item.get("status") != "BLOCKED"
                or item.get("prior_attempt_id") != expected_parent_id
                or not isinstance(item_text, str)
                or item_text != response_text
                or item_hash != response_sha256
                or item_hash != sha256_bytes(item_text.encode("utf-8"))
                or item_projection != response_projection
                or not isinstance(binding, dict)
                or binding.get("active_request_sha256") != request_sha256
                or binding.get("submitted_request_sha256") not in (None, request_sha256)
                or not isinstance(item_transport, dict)
                or item_transport.get("provider_called") is not False
                or type(item_transport.get("automatic_retries")) is not int
                or item_transport.get("automatic_retries") != 0
                or item_transport.get("transfer") != "retry_local_build"
                or item_transport.get("mode") != run.get("execution_mode")
                or item_transport.get("prior_attempt_id") != expected_parent_id
                or item_transport.get("submitted_request_sha256") != request_sha256
                or item_transport.get("provider_id") is not None
                or "local_correction" in item_transport
                or "local_recovery" in item_transport
            ):
                return None
            expected_parent_id = item.get("attempt_id")
            if not isinstance(expected_parent_id, str) or not expected_parent_id.strip():
                return None
        recovery_node = history[recovery_index]
        recovery_binding = recovery_node.get("binding") if isinstance(recovery_node, dict) else None
        recovery_transport = recovery_binding.get("transport") if isinstance(recovery_binding, dict) else None
        if not isinstance(recovery_transport, dict):
            return None
        candidate_run = dict(run)
        candidate_run["attempt_history"] = history[: recovery_index + 1]
        candidate_run["transport"] = deepcopy(recovery_transport)
        candidate_run["response"] = {
            "exact_response_text": response_text,
            "response_sha256": response_sha256,
        }
        candidate_validation = deepcopy(recovery_node.get("validation") or {})
        if not isinstance(candidate_validation.get("last_submission_error"), dict):
            recovery_error = recovery_node.get("error")
            if isinstance(recovery_error, dict):
                candidate_validation["last_submission_error"] = deepcopy(recovery_error)
        candidate_run["validation"] = candidate_validation
        return CharacterCreationExecutionService._ordinary_repair_recovery_shadow(
            candidate_run,
            response_text,
        )

    @staticmethod
    def _ordinary_repair_recovery_shadow(
        run: dict[str, Any],
        response_text: str,
    ) -> dict[str, Any] | None:
        """Expose only the exact recovered prefix to ordinary-lineage proof.

        Retry Local Build recovery compiles a retained attempt-5 response
        while the in-memory run still contains the blocked attempt-6 schema
        correction leaf.  The normal provenance walk therefore sees the
        malformed leaf instead of the response being compiled.  Build a
        proof-only shadow ending at the immediately restored row, but only
        after binding the recovery receipt, immutable leaf, and one-hop
        parent exactly.  This never changes persisted response bytes or
        authorizes a general stale-echo exception.
        """
        if not isinstance(run, dict) or not isinstance(response_text, str) or not response_text.strip():
            return None
        history = run.get("attempt_history")
        if not isinstance(history, list) or len(history) < 2:
            return None
        transport = run.get("transport") if isinstance(run.get("transport"), dict) else None
        recovery = transport.get("local_recovery") if isinstance(transport, dict) else None
        if not isinstance(recovery, dict):
            return CharacterCreationExecutionService._ordinary_repair_historical_recovery_shadow(
                run,
                response_text,
            )
        if (
            not isinstance(transport, dict)
            or not isinstance(recovery, dict)
            or recovery.get("schema") != "TianxiaFoundry.LocalProviderRecoveryReceipt.v1"
            or set(recovery) != {
                "schema",
                "provider_called",
                "automatic_retries",
                "recovered_from_attempt_id",
                "restored_attempt_id",
                "request_sha256",
                "prior_response_sha256",
                "original_diagnostic",
            }
            or recovery.get("provider_called") is not False
            or type(recovery.get("automatic_retries")) is not int
            or recovery.get("automatic_retries") != 0
            or transport.get("provider_called") is not False
            or type(transport.get("automatic_retries")) is not int
            or transport.get("automatic_retries") != 0
            or transport.get("transfer") != "retry_local_build"
            or transport.get("mode") != run.get("execution_mode")
            or transport.get("provider_id") not in _LOCAL_PROVIDER_IDS
        ):
            return None
        request = run.get("request") if isinstance(run.get("request"), dict) else None
        request_sha256 = request.get("request_sha256") if isinstance(request, dict) else None
        if (
            not isinstance(request, dict)
            or not isinstance(request_sha256, str)
            or not request_sha256
            or run.get("status") not in {"NEEDS_REVIEW", "READY_FOR_REVIEW"}
            or run.get("execution_mode") not in {"STANDARD_API", "AUTO_FINALIZE_WHEN_CLEAN"}
            or request.get("project_id") != run.get("project_id")
            or request.get("project_revision") != run.get("starting_revision")
            or recovery.get("request_sha256") != request_sha256
            or transport.get("submitted_request_sha256") not in (None, request_sha256)
            or transport.get("complete_request_sha256") not in (None, request_sha256)
            or transport.get("prior_attempt_id") != recovery.get("recovered_from_attempt_id")
        ):
            return None
        response_sha256 = sha256_bytes(response_text.encode("utf-8"))
        if recovery.get("prior_response_sha256") != response_sha256:
            return None
        original_diagnostic = recovery.get("original_diagnostic")
        if (
            not isinstance(original_diagnostic, dict)
            or original_diagnostic.get("code") not in _LOCAL_PROVIDER_CORRECTION_CODES
        ):
            return None
        recovered_from_attempt_id = recovery.get("recovered_from_attempt_id")
        restored_attempt_id = recovery.get("restored_attempt_id")
        if (
            not isinstance(recovered_from_attempt_id, str)
            or not recovered_from_attempt_id.strip()
            or not isinstance(restored_attempt_id, str)
            or not restored_attempt_id.strip()
            or recovered_from_attempt_id == restored_attempt_id
        ):
            return None
        attempt_ids = [
            item.get("attempt_id") if isinstance(item, dict) else None
            for item in history
        ]
        if (
            any(not isinstance(attempt_id, str) or not attempt_id.strip() for attempt_id in attempt_ids)
            or len(set(attempt_ids)) != len(attempt_ids)
        ):
            return None
        latest = history[-1]
        if not isinstance(latest, dict):
            return None
        persisted_leaf = attempt_ids[-1] != recovered_from_attempt_id
        if persisted_leaf:
            if (
                len(history) < 3
                or attempt_ids[-2] != recovered_from_attempt_id
                or attempt_ids[-3] != restored_attempt_id
                or latest.get("action_type") != "RETRY_LOCAL_BUILD"
                or latest.get("status") != "BLOCKED"
                or latest.get("prior_attempt_id") != recovered_from_attempt_id
            ):
                return None
            correction = history[-2]
            restored = history[-3]
            shadow_history = history[:-2]
        else:
            if attempt_ids[-2] != restored_attempt_id:
                return None
            correction = latest
            restored = history[-2]
            shadow_history = history[:-1]
        if not isinstance(correction, dict) or not isinstance(restored, dict):
            return None
        correction_response_text = correction.get("response_text")
        correction_response_sha256 = correction.get("response_sha256")
        if (
            not isinstance(correction_response_text, str)
            or not correction_response_text.strip()
            or correction_response_sha256 != sha256_bytes(correction_response_text.encode("utf-8"))
            or correction.get("action_type") != "LOCAL_PROVIDER_CORRECTION"
            or correction.get("status") != "BLOCKED"
            or correction.get("prior_attempt_id") != restored_attempt_id
            or correction.get("run_id") != run.get("run_id")
            or correction.get("project_id") != run.get("project_id")
            or correction.get("request_sha256") != request_sha256
        ):
            return None
        current_validation = run.get("validation") if isinstance(run.get("validation"), dict) else None
        current_failure = current_validation.get("last_submission_error") if isinstance(current_validation, dict) else None
        latest_validation = correction.get("validation") if isinstance(correction.get("validation"), dict) else None
        latest_failure = latest_validation.get("last_submission_error") if isinstance(latest_validation, dict) else None
        if not isinstance(latest_failure, dict):
            latest_failure = correction.get("error")
        expected_current_failure = (
            "CG1_PREFERRED_RESPONSE_SHAPE_INVALID"
            if persisted_leaf
            else "CG1_PLAN_SCHEMA_INVALID"
        )
        if (
            not isinstance(current_failure, dict)
            or current_failure.get("code") != expected_current_failure
            or not isinstance(latest_failure, dict)
            or latest_failure.get("code") != "CG1_PLAN_SCHEMA_INVALID"
        ):
            return None
        if persisted_leaf:
            leaf_validation = latest.get("validation") if isinstance(latest.get("validation"), dict) else None
            leaf_failure = leaf_validation.get("last_submission_error") if isinstance(leaf_validation, dict) else None
            if not isinstance(leaf_failure, dict):
                leaf_failure = latest.get("error")
            if not isinstance(leaf_failure, dict) or leaf_failure.get("code") != expected_current_failure:
                return None
            if (
                latest.get("response_text") != response_text
                or latest.get("response_sha256") != response_sha256
                or latest.get("response_sha256") != sha256_bytes(
                    latest["response_text"].encode("utf-8")
                )
            ):
                return None
        current_response = run.get("response") if isinstance(run.get("response"), dict) else None
        if not isinstance(current_response, dict):
            return None
        # _apply_response preserves the latest exact text in its scratch
        # snapshot but overlays the incoming response hash for compilation;
        # accept only that exact two-value projection.
        if (
            current_response.get("exact_response_text")
            != (latest.get("response_text") if persisted_leaf else correction_response_text)
            or current_response.get("response_sha256")
            not in {
                latest.get("response_sha256") if persisted_leaf else correction_response_sha256,
                response_sha256,
            }
        ):
            return None
        restored_response_text = restored.get("response_text")
        if (
            restored.get("run_id") != run.get("run_id")
            or restored.get("project_id") != run.get("project_id")
            or restored.get("request_sha256") != request_sha256
            or restored.get("action_type") != "RETRY_LOCAL_BUILD"
            or restored.get("status") != "BLOCKED"
            or not isinstance(restored_response_text, str)
            or restored_response_text != response_text
            or restored.get("response_sha256") != response_sha256
        ):
            return None
        correction_binding = correction.get("binding") if isinstance(correction.get("binding"), dict) else None
        correction_transport = correction_binding.get("transport") if isinstance(correction_binding, dict) else None
        latest_marker = correction_transport.get("local_correction") if isinstance(correction_transport, dict) else None
        if (
            not isinstance(correction_binding, dict)
            or not isinstance(correction_transport, dict)
            or not isinstance(latest_marker, dict)
            or correction_binding.get("active_request_sha256") != request_sha256
            or correction_binding.get("submitted_request_sha256") not in (None, request_sha256)
            or correction_transport.get("provider_called") is not True
            or type(correction_transport.get("automatic_retries")) is not int
            or correction_transport.get("automatic_retries") != 0
            or correction_transport.get("complete_request_sha256") != request_sha256
            or correction_transport.get("prior_attempt_id") != restored_attempt_id
            or latest_marker.get("explicit") is not True
            or latest_marker.get("provider_called") not in (None, True)
            or latest_marker.get("prior_attempt_id") != restored_attempt_id
            or latest_marker.get("prior_response_sha256") != response_sha256
            or latest_marker.get("provider_id") != transport.get("provider_id")
            or latest_marker.get("provider_id") not in _LOCAL_PROVIDER_IDS
            or latest_marker.get("validator_diagnostic") != original_diagnostic
        ):
            return None
        if persisted_leaf:
            leaf_binding = latest.get("binding") if isinstance(latest.get("binding"), dict) else None
            leaf_transport = leaf_binding.get("transport") if isinstance(leaf_binding, dict) else None
            leaf_recovery = leaf_transport.get("local_recovery") if isinstance(leaf_transport, dict) else None
            if (
                not isinstance(leaf_binding, dict)
                or not isinstance(leaf_transport, dict)
                or leaf_recovery != recovery
                or leaf_binding.get("active_request_sha256") != request_sha256
                or leaf_binding.get("submitted_request_sha256") not in (None, request_sha256)
                or leaf_transport.get("provider_called") is not False
                or type(leaf_transport.get("automatic_retries")) is not int
                or leaf_transport.get("automatic_retries") != 0
                or leaf_transport.get("transfer") != "retry_local_build"
                or leaf_transport.get("prior_attempt_id") != recovered_from_attempt_id
            ):
                return None
        shadow = dict(run)
        shadow["attempt_history"] = shadow_history
        shadow["response"] = {
            "exact_response_text": response_text,
            "response_sha256": response_sha256,
        }
        # Prevent the recursive walk from treating the recovery receipt as a
        # new direct marker; the prefix's retained Retry Local Build row is
        # the actual current leaf for this proof.
        shadow["transport"] = {}
        return shadow

    @classmethod
    def _response_run_context(cls, run: Mapping[str, Any]) -> dict[str, Any]:
        """Validate the immutable run/request identity used by response proofs."""

        def invalid(reason: str) -> None:
            raise FoundryError(
                _RESPONSE_EVIDENCE_ERROR,
                "The exact response evidence is not bound to this creation run.",
                details={"reason": reason},
                status_code=409,
            )

        if not isinstance(run, Mapping):
            invalid("run_not_mapping")
        run_id = run.get("run_id")
        project_id = run.get("project_id")
        starting_revision = run.get("starting_revision")
        request = run.get("request")
        if (
            not isinstance(run_id, str)
            or not run_id.strip()
            or not isinstance(project_id, str)
            or not project_id.strip()
            or not isinstance(request, Mapping)
            or request.get("project_id") != project_id
            or request.get("project_revision") != starting_revision
        ):
            invalid("current_run_identity_mismatch")
        request_sha256 = request.get("request_sha256")
        if (
            not isinstance(request_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", request_sha256) is None
        ):
            invalid("request_hash_missing_or_malformed")
        try:
            recomputed_request_sha256 = cls.request_payload_sha256(dict(request))
        except Exception:
            invalid("request_hash_recompute_failed")
        if recomputed_request_sha256 != request_sha256:
            invalid("request_hash_mismatch")
        return {
            "schema": _RESPONSE_EVIDENCE_SCHEMA,
            "run_id": run_id,
            "project_id": project_id,
            "starting_revision": starting_revision,
            "request_sha256": request_sha256,
        }

    @classmethod
    def _response_evidence_context(
        cls,
        run: Mapping[str, Any],
        *,
        response_text: str,
        response_sha256: str,
    ) -> dict[str, Any]:
        """Validate a response's exact UTF-8 bytes and current-run binding."""

        def invalid(reason: str) -> None:
            raise FoundryError(
                _RESPONSE_EVIDENCE_ERROR,
                "The exact response evidence is not bound to this creation run.",
                details={"reason": reason},
                status_code=409,
            )

        base = cls._response_run_context(run)
        if (
            not isinstance(response_text, str)
            or not response_text.strip()
            or not isinstance(response_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", response_sha256) is None
        ):
            invalid("response_identity_missing_or_malformed")
        try:
            response_bytes = response_text.encode("utf-8")
        except UnicodeEncodeError:
            invalid("response_not_utf8")
        if sha256_bytes(response_bytes) != response_sha256:
            invalid("response_hash_mismatch")
        asserted_response = run.get("response")
        if not isinstance(asserted_response, Mapping):
            invalid("run_response_missing")
        asserted_sha256 = asserted_response.get("response_sha256")
        if (
            not isinstance(asserted_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", asserted_sha256) is None
            or asserted_sha256 != response_sha256
        ):
            invalid("run_response_hash_mismatch")
        asserted_text = asserted_response.get("exact_response_text")
        if asserted_text is not None and asserted_text != response_text:
            invalid("run_response_text_mismatch")
        return {
            **base,
            "response_sha256": response_sha256,
            "response_bytes": response_bytes,
        }

    @classmethod
    def _retained_response_evidence(
        cls,
        run: Mapping[str, Any],
        *,
        response_sha256: str,
    ) -> dict[str, Any]:
        """Recover one exact response only from the current run's latest leaf."""

        def invalid(reason: str, *, attempt_id: str | None = None) -> None:
            details: dict[str, Any] = {"reason": reason}
            if attempt_id is not None:
                details["attempt_id"] = attempt_id
            raise FoundryError(
                _RESPONSE_EVIDENCE_ERROR,
                "The retained response evidence cannot be authenticated.",
                details=details,
                status_code=409,
            )

        base = cls._response_run_context(run)
        history = run.get("attempt_history")
        if not isinstance(history, list) or not history:
            invalid("attempt_history_missing")
        records: set[str] = set()
        previous_id: str | None = None
        for index, item in enumerate(history):
            if not isinstance(item, Mapping):
                invalid("attempt_row_not_mapping")
            attempt_id = item.get("attempt_id")
            if not isinstance(attempt_id, str) or not attempt_id.strip() or attempt_id in records:
                invalid("attempt_identity_invalid")
            if item.get("ordinal") != index + 1:
                invalid("attempt_ordinals_invalid", attempt_id=attempt_id)
            if (
                item.get("run_id") != base["run_id"]
                or item.get("project_id") != base["project_id"]
                or item.get("request_sha256") != base["request_sha256"]
            ):
                invalid("attempt_identity_mismatch", attempt_id=attempt_id)
            parent_id = item.get("prior_attempt_id")
            parent_id = None if parent_id in (None, "") else parent_id
            if parent_id != previous_id:
                invalid("attempt_parent_mismatch", attempt_id=attempt_id)
            response_value = item.get("response_text")
            item_hash = item.get("response_sha256")
            if response_value is None:
                if item_hash not in (None, ""):
                    invalid("attempt_response_bytes_missing", attempt_id=attempt_id)
                if item.get("response_byte_count") not in (None, 0) or item.get("response_bytes_sha256") not in (None, ""):
                    invalid("response_less_metadata", attempt_id=attempt_id)
            else:
                if not isinstance(response_value, str) or not response_value.strip():
                    invalid("attempt_response_text_invalid", attempt_id=attempt_id)
                try:
                    encoded = response_value.encode("utf-8")
                except UnicodeEncodeError:
                    invalid("attempt_response_not_utf8", attempt_id=attempt_id)
                computed = sha256_bytes(encoded)
                if item_hash != computed:
                    invalid("attempt_response_hash_mismatch", attempt_id=attempt_id)
                if item.get("response_byte_count") != len(encoded) or item.get("response_bytes_sha256") != computed:
                    invalid("attempt_response_byte_receipt_mismatch", attempt_id=attempt_id)
            binding = item.get("binding")
            if binding is not None and not isinstance(binding, Mapping):
                invalid("attempt_binding_invalid", attempt_id=attempt_id)
            if isinstance(binding, Mapping):
                active = binding.get("active_request_sha256")
                submitted = binding.get("submitted_request_sha256")
                if active not in (None, base["request_sha256"]) or submitted not in (None, base["request_sha256"]):
                    invalid("attempt_binding_request_mismatch", attempt_id=attempt_id)
                transport = binding.get("transport")
                if transport is not None and not isinstance(transport, Mapping):
                    invalid("attempt_transport_invalid", attempt_id=attempt_id)
                if isinstance(transport, Mapping) and transport.get("prior_attempt_id") not in (None, parent_id):
                    invalid("attempt_transport_parent_mismatch", attempt_id=attempt_id)
            records.add(attempt_id)
            previous_id = attempt_id

        latest = history[-1]
        latest_id = latest.get("attempt_id") if isinstance(latest, Mapping) else None
        latest_text = latest.get("response_text") if isinstance(latest, Mapping) else None
        if (
            not isinstance(latest_text, str)
            or not latest_text.strip()
            or latest.get("response_sha256") != response_sha256
        ):
            invalid("latest_attempt_response_mismatch")
        latest_binding = latest.get("binding") if isinstance(latest, Mapping) else None
        latest_transport = latest_binding.get("transport") if isinstance(latest_binding, Mapping) else None
        if (
            not isinstance(latest_binding, Mapping)
            or latest_binding.get("active_request_sha256") != base["request_sha256"]
            or not isinstance(latest_transport, Mapping)
        ):
            invalid("latest_attempt_binding_missing", attempt_id=latest_id)
        context = cls._response_evidence_context(
            run,
            response_text=latest_text,
            response_sha256=response_sha256,
        )
        return {
            **context,
            "source": "attempt_history",
            "attempt_id": latest_id,
            "attempt_ordinal": latest.get("ordinal"),
            "response_text": latest_text,
        }

    @classmethod
    def _compile_response_evidence(
        cls,
        run: Mapping[str, Any],
        *,
        response_text: str,
        response_sha256: str,
        persisted_response_sha256: str | None = None,
    ) -> dict[str, Any]:
        """Authenticate a retained leaf or an explicitly marked first submit."""

        base = cls._response_evidence_context(
            run,
            response_text=response_text,
            response_sha256=response_sha256,
        )
        if persisted_response_sha256 is not None and persisted_response_sha256 != response_sha256:
            raise FoundryError(
                _RESPONSE_EVIDENCE_ERROR,
                "The persisted response digest disagrees with the compile response.",
                details={"reason": "persisted_response_hash_mismatch"},
                status_code=409,
            )
        history = run.get("attempt_history")
        if history is not None and not isinstance(history, list):
            raise FoundryError(
                _RESPONSE_EVIDENCE_ERROR,
                "The retained attempt ledger is malformed.",
                details={"reason": "attempt_history_not_list"},
                status_code=409,
            )
        if isinstance(history, list) and history:
            has_response = any(
                not isinstance(item, Mapping)
                or item.get("response_text") is not None
                or item.get("response_sha256") not in (None, "")
                for item in history
            )
            if has_response:
                evidence = cls._retained_response_evidence(
                    run,
                    response_sha256=response_sha256,
                )
                if evidence["response_text"] != response_text:
                    raise FoundryError(
                        _RESPONSE_EVIDENCE_ERROR,
                        "The retained response text disagrees with the compile response.",
                        details={"reason": "retained_response_text_mismatch"},
                        status_code=409,
                    )
                return evidence
            # A first submission may legitimately reach candidate capture
            # before its response row is durable.  The internal marker below
            # authenticates that seam, but it does not excuse a malformed
            # response-less ledger prefix.
            records: set[str] = set()
            previous_id: str | None = None
            for index, item in enumerate(history):
                if not isinstance(item, Mapping):
                    raise FoundryError(
                        _RESPONSE_EVIDENCE_ERROR,
                        "The retained attempt ledger is malformed.",
                        details={"reason": "attempt_row_not_mapping"},
                        status_code=409,
                    )
                attempt_id = item.get("attempt_id")
                if not isinstance(attempt_id, str) or not attempt_id.strip() or attempt_id in records:
                    raise FoundryError(
                        _RESPONSE_EVIDENCE_ERROR,
                        "The retained attempt ledger is malformed.",
                        details={"reason": "attempt_identity_invalid"},
                        status_code=409,
                    )
                if (
                    item.get("ordinal") != index + 1
                    or item.get("run_id") != base["run_id"]
                    or item.get("project_id") != base["project_id"]
                    or item.get("request_sha256") != base["request_sha256"]
                ):
                    raise FoundryError(
                        _RESPONSE_EVIDENCE_ERROR,
                        "The retained attempt ledger is not bound to the current run.",
                        details={"reason": "attempt_identity_mismatch", "attempt_id": attempt_id},
                        status_code=409,
                    )
                parent_id = item.get("prior_attempt_id")
                parent_id = None if parent_id in (None, "") else parent_id
                if parent_id != previous_id:
                    raise FoundryError(
                        _RESPONSE_EVIDENCE_ERROR,
                        "The retained attempt chain is not contiguous.",
                        details={"reason": "attempt_parent_mismatch", "attempt_id": attempt_id},
                        status_code=409,
                    )
                if (
                    item.get("response_text") is not None
                    or item.get("response_sha256") not in (None, "")
                    or item.get("response_byte_count") not in (None, 0)
                    or item.get("response_bytes_sha256") not in (None, "")
                    or item.get("response_bytes") not in (None, b"", bytearray())
                ):
                    raise FoundryError(
                        _RESPONSE_EVIDENCE_ERROR,
                        "The response-less attempt row contains response metadata.",
                        details={"reason": "response_less_metadata", "attempt_id": attempt_id},
                        status_code=409,
                    )
                binding = item.get("binding")
                if binding is not None and not isinstance(binding, Mapping):
                    raise FoundryError(
                        _RESPONSE_EVIDENCE_ERROR,
                        "The retained attempt binding is malformed.",
                        details={"reason": "attempt_binding_invalid", "attempt_id": attempt_id},
                        status_code=409,
                    )
                if isinstance(binding, Mapping):
                    active = binding.get("active_request_sha256")
                    submitted = binding.get("submitted_request_sha256")
                    if active not in (None, base["request_sha256"]) or submitted not in (None, base["request_sha256"]):
                        raise FoundryError(
                            _RESPONSE_EVIDENCE_ERROR,
                            "The retained attempt binding is not bound to the current request.",
                            details={"reason": "attempt_binding_request_mismatch", "attempt_id": attempt_id},
                            status_code=409,
                        )
                    transport = binding.get("transport")
                    if transport is not None and not isinstance(transport, Mapping):
                        raise FoundryError(
                            _RESPONSE_EVIDENCE_ERROR,
                            "The retained attempt transport binding is malformed.",
                            details={"reason": "attempt_transport_invalid", "attempt_id": attempt_id},
                            status_code=409,
                        )
                    if isinstance(transport, Mapping) and transport.get("prior_attempt_id") not in (None, parent_id):
                        raise FoundryError(
                            _RESPONSE_EVIDENCE_ERROR,
                            "The retained attempt transport is not bound to its parent.",
                            details={"reason": "attempt_transport_parent_mismatch", "attempt_id": attempt_id},
                            status_code=409,
                        )
                records.add(attempt_id)
                previous_id = attempt_id
        marker = run.get("_response_evidence")
        expected_marker = {
            "schema": _RESPONSE_EVIDENCE_SCHEMA,
            "kind": "PRE_PERSISTENCE",
            "run_id": base["run_id"],
            "project_id": base["project_id"],
            "request_sha256": base["request_sha256"],
            "response_sha256": base["response_sha256"],
        }
        if persisted_response_sha256 is not None or not isinstance(marker, Mapping) or dict(marker) != expected_marker:
            raise FoundryError(
                _RESPONSE_EVIDENCE_ERROR,
                "The response has no authenticated retained leaf or first-submit binding.",
                details={"reason": "response_evidence_source_missing"},
                status_code=409,
            )
        return {
            **base,
            "source": "pre_persistence",
            "attempt_id": None,
            "attempt_ordinal": None,
            "response_text": response_text,
        }

    @staticmethod
    def _legacy_retry_bypass_context(
        run: dict[str, Any],
        response_text: str,
    ) -> dict[str, Any] | None:
        """Return a proof-bound link past legacy no-op retry rows.

        Older Retry Local Build rows did not persist ``automatic_retries``.
        They are retained as immutable evidence, but cannot be traversed by
        the strict provenance verifier.  A new retry may therefore link to
        the nearest fully bound exact-response predecessor only when the
        missing field is the sole legacy defect and every skipped row is an
        exact no-op in one contiguous suffix.
        """
        if not isinstance(run, dict) or not isinstance(response_text, str) or not response_text.strip():
            return None
        history = run.get("attempt_history")
        if not isinstance(history, list) or not history:
            return None
        latest = history[-1]
        if not isinstance(latest, dict) or latest.get("action_type") != "RETRY_LOCAL_BUILD" or latest.get("status") != "BLOCKED":
            return None
        latest_binding = latest.get("binding") if isinstance(latest.get("binding"), dict) else None
        latest_transport = latest_binding.get("transport") if isinstance(latest_binding, dict) else None
        if isinstance(latest_transport, dict) and "automatic_retries" in latest_transport:
            if type(latest_transport.get("automatic_retries")) is not int or latest_transport.get("automatic_retries") != 0:
                raise FoundryError(
                    "CG1_RETRY_LOCAL_BUILD_LEGACY_PROVENANCE_INVALID",
                    "The retained Retry Local Build history has invalid retry metadata.",
                    details={"reason": "nonzero_or_malformed_automatic_retries"},
                    status_code=409,
                )
            return None

        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        request_sha256 = request.get("request_sha256")
        run_id = run.get("run_id")
        project_id = run.get("project_id")
        current_sha256 = sha256_bytes(response_text.encode("utf-8"))

        def invalid(reason: str) -> None:
            raise FoundryError(
                "CG1_RETRY_LOCAL_BUILD_LEGACY_PROVENANCE_INVALID",
                "The retained Retry Local Build history cannot be safely recovered.",
                details={"reason": reason},
                status_code=409,
            )

        if (
            not isinstance(run_id, str)
            or not run_id.strip()
            or not isinstance(project_id, str)
            or not project_id.strip()
            or not isinstance(request_sha256, str)
            or not request_sha256.strip()
        ):
            invalid("current_run_binding_missing")

        allowed_binding_keys = {"submitted_request_sha256", "active_request_sha256", "transport"}
        allowed_legacy_transport_keys = {
            "mode",
            "provider_called",
            "transfer",
            "submitted_request_sha256",
            "prior_attempt_id",
            "source_provenance",
            "uploaded_filename",
            "response_member",
            "uploaded_sha256",
        }

        def exact_response(row: Any) -> bool:
            if not isinstance(row, dict):
                return False
            if row.get("response_text") != response_text or row.get("response_sha256") != current_sha256:
                return False
            encoded = response_text.encode("utf-8")
            if "response_byte_count" in row and row.get("response_byte_count") != len(encoded):
                return False
            if "response_bytes_sha256" in row and row.get("response_bytes_sha256") != current_sha256:
                return False
            return True

        def exact_bound(row: Any) -> bool:
            if (
                not isinstance(row, dict)
                or any(key not in row for key in ("run_id", "project_id", "request_sha256"))
                or row.get("run_id") != run_id
                or row.get("project_id") != project_id
                or row.get("request_sha256") != request_sha256
                or not exact_response(row)
            ):
                return False
            binding = row.get("binding")
            if (
                not isinstance(binding, dict)
                or not set(binding).issubset(allowed_binding_keys)
                or "active_request_sha256" not in binding
                or binding.get("active_request_sha256") != request_sha256
                or "transport" not in binding
                or not isinstance(binding.get("transport"), dict)
            ):
                return False
            # Deterministic local corrections intentionally do not represent
            # a new provider submission.  Their outer submitted binding is
            # therefore explicitly null; provider and Retry Local Build rows
            # retain the strict populated submission binding.
            if row.get("action_type") == "LOCAL_PROVIDER_CORRECTION":
                return (
                    "submitted_request_sha256" in binding
                    and binding.get("submitted_request_sha256") is None
                )
            return (
                "submitted_request_sha256" in binding
                and binding.get("submitted_request_sha256") == request_sha256
            )

        def legacy_candidate(row: Any) -> bool:
            if not isinstance(row, dict) or row.get("action_type") != "RETRY_LOCAL_BUILD" or row.get("status") != "BLOCKED":
                return False
            binding = row.get("binding") if isinstance(row.get("binding"), dict) else None
            transport = binding.get("transport") if isinstance(binding, dict) else None
            return not isinstance(transport, dict) or "automatic_retries" not in transport

        def legacy_row_valid(row: Any, expected_parent_id: str) -> bool:
            if not exact_bound(row) or not legacy_candidate(row):
                return False
            if row.get("prior_attempt_id") != expected_parent_id:
                return False
            binding = row["binding"]
            transport = binding["transport"]
            if (
                not set(transport).issubset(allowed_legacy_transport_keys)
                or transport.get("provider_called") is not False
                or transport.get("transfer") != "retry_local_build"
                or transport.get("submitted_request_sha256") != request_sha256
                or transport.get("prior_attempt_id") != expected_parent_id
                or "local_correction" in transport
            ):
                return False
            if "mode" in transport and transport.get("mode") != run.get("execution_mode"):
                return False
            return True

        start = len(history) - 1
        while start >= 0 and legacy_candidate(history[start]):
            start -= 1
        bypass_rows = history[start + 1 :]
        if not bypass_rows or start < 0:
            invalid("legacy_suffix_has_no_predecessor")
        predecessor = history[start]
        if not exact_bound(predecessor):
            invalid("predecessor_binding_or_response_mismatch")
        predecessor_id = predecessor.get("attempt_id")
        if not isinstance(predecessor_id, str) or not predecessor_id.strip():
            invalid("predecessor_attempt_id_missing")
        expected_parent_id = predecessor_id
        bypassed_ids: list[str] = []
        for row in bypass_rows:
            attempt_id = row.get("attempt_id") if isinstance(row, dict) else None
            if not isinstance(attempt_id, str) or not attempt_id.strip() or attempt_id in bypassed_ids:
                invalid("legacy_attempt_id_invalid")
            if not legacy_row_valid(row, expected_parent_id):
                invalid("legacy_row_not_an_exact_noop")
            bypassed_ids.append(attempt_id)
            expected_parent_id = attempt_id

        predecessor_transport = predecessor["binding"]["transport"]
        predecessor_action = predecessor.get("action_type")
        if predecessor_action == "RETRY_LOCAL_BUILD":
            if (
                predecessor_transport.get("provider_called") is not False
                or type(predecessor_transport.get("automatic_retries")) is not int
                or predecessor_transport.get("automatic_retries") != 0
                or predecessor_transport.get("transfer") != "retry_local_build"
                or "local_correction" in predecessor_transport
            ):
                invalid("predecessor_retry_not_fully_bound")
        elif predecessor_action == "LOCAL_PROVIDER_CORRECTION":
            marker = predecessor_transport.get("local_correction")
            parent_attempt_id = predecessor.get("prior_attempt_id")
            parent_row = next(
                (
                    candidate
                    for candidate in history
                    if isinstance(candidate, dict)
                    and candidate.get("attempt_id") == parent_attempt_id
                ),
                None,
            )
            parent_response_sha256 = (
                parent_row.get("response_sha256")
                if isinstance(parent_row, dict)
                else None
            )
            if (
                predecessor_transport.get("complete_request_sha256") != request_sha256
                or predecessor_transport.get("provider_called") is not False
                or type(predecessor_transport.get("automatic_retries")) is not int
                or predecessor_transport.get("automatic_retries") != 0
                or predecessor_transport.get("prior_attempt_id") != parent_attempt_id
                or not isinstance(marker, dict)
                or marker.get("deterministic_server_repair") is not True
                or marker.get("provider_called") is not False
                or marker.get("prior_attempt_id") != parent_attempt_id
                or marker.get("prior_response_sha256") != parent_response_sha256
                or marker.get("applied_response_sha256") != predecessor.get("response_sha256")
                or marker.get("request_sha256") not in (None, request_sha256)
                or marker.get("target_kind") not in {
                    "free_talent_sphere_server_repair",
                    "ordinary_duplicate",
                    _ORDINARY_ORDER_MIRROR_TARGET_KIND,
                    "bounded_field_cleanup",
                    "bounded_path_progression_singleton",
                    "bounded_path_progression_empty_cleanup",
                }
                or any(
                    marker.get(key) is not None
                    for key in (
                        "raw_provider_completion_sha256",
                        "raw_provider_response_sha256",
                        "provider_completion_sha256",
                        "provider_response_sha256",
                    )
                )
            ):
                invalid("predecessor_correction_not_fully_bound")
        elif predecessor_action in {"IMPORT_RESPONSE", "REPLACE_RESPONSE"}:
            if predecessor_transport.get("provider_called") is not True or "local_correction" in predecessor_transport:
                invalid("predecessor_provider_binding_invalid")
        else:
            invalid("predecessor_action_invalid")

        return {
            "schema": "TianxiaFoundry.LegacyRetryBypass.v1",
            "bypassed_attempt_ids": bypassed_ids,
            "linked_prior_attempt_id": predecessor_id,
            "response_sha256": current_sha256,
            "request_sha256": request_sha256,
            "reason": "missing_automatic_retries_only",
        }

    @staticmethod
    def _ordinary_repair_provenance_chain(
        run: dict[str, Any],
        response_text: str,
        *,
        direct_marker: dict[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Resolve one exact, fail-closed ordinary-repair lineage.

        A later bounded-field cleanup or Retry Local Build can become the
        current run response, so the ordinary-repair marker cannot be read
        only from the latest transport object.  Walk the append-only attempt
        ledger by exact ``prior_attempt_id`` links and response hashes.  Only
        deterministic local corrections/retries may occur between the
        ordinary repair and the current response, and each such intermediary
        must preserve the canonical ordinary-array projection.
        """
        if not isinstance(run, dict) or not isinstance(response_text, str) or not response_text.strip():
            return None
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        request_sha256 = request.get("request_sha256")
        if not isinstance(request_sha256, str) or not request_sha256:
            return None
        current_sha256 = sha256_bytes(response_text.encode("utf-8"))
        current_projection = CharacterCreationExecutionService._ordinary_response_array_projection(response_text)
        if current_projection is None:
            return None
        history = run.get("attempt_history")
        if not isinstance(history, list) or not history:
            return None

        records: dict[str, dict[str, Any]] = {}
        ordered: list[dict[str, Any]] = []
        ordinals: list[int] = []
        for item in history:
            if not isinstance(item, dict):
                return None
            attempt_id = item.get("attempt_id")
            if not isinstance(attempt_id, str) or not attempt_id.strip() or attempt_id in records:
                return None
            if "ordinal" in item:
                if type(item.get("ordinal")) is not int or item["ordinal"] < 1:
                    return None
                ordinals.append(item["ordinal"])
            # Every retained ledger row is part of the exact run binding.  A
            # missing identity field is not equivalent to a matching field:
            # accepting it would let an unrelated/stale row satisfy the
            # provenance walk.
            if (
                "run_id" not in item
                or item.get("run_id") != run.get("run_id")
                or "project_id" not in item
                or item.get("project_id") != run.get("project_id")
                or "request_sha256" not in item
                or item.get("request_sha256") != request_sha256
            ):
                return None
            response_value = item.get("response_text")
            response_hash = item.get("response_sha256")
            if response_value is None:
                if response_hash not in (None, ""):
                    return None
            elif (
                not isinstance(response_value, str)
                or not response_value.strip()
                or not isinstance(response_hash, str)
                or response_hash != sha256_bytes(response_value.encode("utf-8"))
            ):
                return None
            if "response_byte_count" in item and response_value is not None:
                if item.get("response_byte_count") != len(response_value.encode("utf-8")):
                    return None
            if "response_bytes_sha256" in item and response_value is not None:
                if item.get("response_bytes_sha256") != sha256_bytes(response_value.encode("utf-8")):
                    return None
            parent_id = item.get("prior_attempt_id")
            if parent_id in (None, ""):
                parent_id = None
            elif not isinstance(parent_id, str) or not parent_id.strip():
                return None
            binding = item.get("binding") if isinstance(item.get("binding"), dict) else {}
            binding_transport = binding.get("transport") if isinstance(binding.get("transport"), dict) else None
            if binding_transport is not None:
                transport_parent = binding_transport.get("prior_attempt_id")
                if transport_parent not in (None, "") and transport_parent != parent_id:
                    return None
                if "complete_request_sha256" in binding_transport and binding_transport.get("complete_request_sha256") not in (None, request_sha256):
                    return None
                if "submitted_request_sha256" in binding_transport and binding_transport.get("submitted_request_sha256") not in (None, request_sha256):
                    return None
            if "submitted_request_sha256" in binding and binding.get("submitted_request_sha256") not in (None, request_sha256):
                return None
            if "active_request_sha256" in binding and binding.get("active_request_sha256") != request_sha256:
                return None
            normalized = {
                **item,
                "_parent_id": parent_id,
                "_response_text": response_value,
                "_response_sha256": response_hash,
                "_transport": binding_transport,
            }
            records[attempt_id] = normalized
            ordered.append(normalized)

        if ordinals and (
            len(ordinals) != len(ordered)
            or len(set(ordinals)) != len(ordinals)
            or ordinals != sorted(ordinals)
        ):
            return None
        # A new Retry Local Build can explicitly bypass a contiguous suffix
        # of immutable legacy retries whose only defect is a missing
        # ``automatic_retries`` field.  Validate that proof before relaxing
        # the normal single-child history rule; all other forks remain
        # fail-closed.
        bypassed_ids: set[str] = set()
        bypass_owner: str | None = None
        bypass_owner_index: int | None = None
        item_indexes = {item["attempt_id"]: index for index, item in enumerate(ordered)}
        bypass_metadata_keys = {
            "schema",
            "bypassed_attempt_ids",
            "linked_prior_attempt_id",
            "response_sha256",
            "request_sha256",
            "reason",
        }
        legacy_transport_keys = {
            "mode",
            "provider_called",
            "transfer",
            "submitted_request_sha256",
            "prior_attempt_id",
            "source_provenance",
            "uploaded_filename",
            "response_member",
            "uploaded_sha256",
        }

        def legacy_retry_candidate(item: dict[str, Any]) -> bool:
            if item.get("action_type") != "RETRY_LOCAL_BUILD" or item.get("status") != "BLOCKED":
                return False
            transport = item.get("_transport")
            return not isinstance(transport, dict) or "automatic_retries" not in transport

        def exact_item_response(item: dict[str, Any], expected_text: str, expected_hash: str) -> bool:
            if item.get("_response_text") != expected_text or item.get("_response_sha256") != expected_hash:
                return False
            encoded = expected_text.encode("utf-8")
            if "response_byte_count" in item and item.get("response_byte_count") != len(encoded):
                return False
            if "response_bytes_sha256" in item and item.get("response_bytes_sha256") != expected_hash:
                return False
            return True

        for item in ordered:
            transport = item.get("_transport")
            metadata = transport.get("legacy_retry_bypass") if isinstance(transport, dict) else None
            if metadata is None:
                continue
            if (
                bypass_owner is not None
                or item.get("action_type") != "RETRY_LOCAL_BUILD"
                or item.get("status") != "BLOCKED"
                or not isinstance(transport, dict)
                or transport.get("provider_called") is not False
                or type(transport.get("automatic_retries")) is not int
                or transport.get("automatic_retries") != 0
                or transport.get("transfer") != "retry_local_build"
                or "local_correction" in transport
                or not isinstance(metadata, dict)
                or set(metadata) != bypass_metadata_keys
                or metadata.get("schema") != "TianxiaFoundry.LegacyRetryBypass.v1"
                or metadata.get("request_sha256") != request_sha256
                or metadata.get("response_sha256") != item.get("_response_sha256")
                or metadata.get("reason") != "missing_automatic_retries_only"
            ):
                return None
            item_id = item.get("attempt_id")
            item_index = item_indexes.get(item_id)
            bypass_list = metadata.get("bypassed_attempt_ids")
            linked_id = metadata.get("linked_prior_attempt_id")
            if (
                not isinstance(item_id, str)
                or not isinstance(bypass_list, list)
                or not bypass_list
                or any(not isinstance(value, str) or not value.strip() for value in bypass_list)
                or len(set(bypass_list)) != len(bypass_list)
                or not isinstance(linked_id, str)
                or linked_id not in records
                or item.get("_parent_id") != linked_id
            ):
                return None
            bypass_indexes = [item_indexes.get(value) for value in bypass_list]
            if (
                any(value is None for value in bypass_indexes)
                or bypass_indexes != list(range(item_index - len(bypass_list), item_index))
                or item_indexes.get(linked_id) != item_index - len(bypass_list) - 1
            ):
                return None
            first_bypassed = records.get(bypass_list[0])
            bypass_response_text = (
                first_bypassed.get("_response_text")
                if isinstance(first_bypassed, dict)
                else None
            )
            bypass_response_sha256 = (
                first_bypassed.get("_response_sha256")
                if isinstance(first_bypassed, dict)
                else None
            )
            if (
                not isinstance(bypass_response_text, str)
                or not isinstance(bypass_response_sha256, str)
                or not exact_item_response(item, bypass_response_text, bypass_response_sha256)
            ):
                return None
            expected_parent_id = linked_id
            for bypass_id in bypass_list:
                bypass_row = records.get(bypass_id)
                bypass_transport = bypass_row.get("_transport") if isinstance(bypass_row, dict) else None
                if (
                    not isinstance(bypass_row, dict)
                    or not legacy_retry_candidate(bypass_row)
                    or not isinstance(bypass_transport, dict)
                    or set(bypass_transport).issubset(legacy_transport_keys) is not True
                    or bypass_transport.get("provider_called") is not False
                    or bypass_transport.get("transfer") != "retry_local_build"
                    or bypass_transport.get("submitted_request_sha256") != request_sha256
                    or bypass_transport.get("prior_attempt_id") != expected_parent_id
                    or bypass_row.get("_parent_id") != expected_parent_id
                    or "local_correction" in bypass_transport
                    or not exact_item_response(
                        bypass_row,
                        bypass_response_text,
                        bypass_response_sha256,
                    )
                ):
                    return None
                if "mode" in bypass_transport and bypass_transport.get("mode") != run.get("execution_mode"):
                    return None
                expected_parent_id = bypass_id
            predecessor = records.get(linked_id)
            predecessor_transport = predecessor.get("_transport") if isinstance(predecessor, dict) else None
            if not isinstance(predecessor, dict) or not isinstance(predecessor_transport, dict):
                return None
            bypassed_ids.update(bypass_list)
            bypass_owner = item_id
            bypass_owner_index = item_index

        # The bypass proof may be an interior node when later deterministic
        # corrections/retries have already appended descendants.  Those rows
        # must be one exact prior_attempt_id chain from the bypass owner to
        # the current retained leaf; accepting merely a single-child graph
        # would allow a disconnected or forked descendant to hide here.
        if bypass_owner is not None:
            if bypass_owner_index is None:
                return None
            expected_parent_id = bypass_owner
            for descendant in ordered[bypass_owner_index + 1 :]:
                if (
                    descendant.get("attempt_id") in bypassed_ids
                    or descendant.get("_parent_id") != expected_parent_id
                ):
                    return None
                expected_parent_id = descendant.get("attempt_id")

        # Any missing-automatic-retries legacy row must be explicitly named
        # by the one validated bypass proof; otherwise it remains an invalid
        # reachable or forked history row.
        if any(legacy_retry_candidate(item) and item.get("attempt_id") not in bypassed_ids for item in ordered):
            return None

        children: dict[str, list[str]] = {}
        for item in ordered:
            if item.get("attempt_id") in bypassed_ids:
                continue
            parent_id = item["_parent_id"]
            if parent_id is None:
                continue
            if parent_id not in records or parent_id in bypassed_ids:
                return None
            children.setdefault(parent_id, []).append(item["attempt_id"])
        if any(len(child_ids) > 1 for child_ids in children.values()):
            return None

        latest = ordered[-1]
        latest_is_current = (
            latest.get("_response_text") == response_text
            and latest.get("_response_sha256") == current_sha256
        )
        if direct_marker is None and not CharacterCreationExecutionService._historical_advancement_choice_diagnostics(run):
            recovery_shadow = CharacterCreationExecutionService._ordinary_repair_recovery_shadow(
                run,
                response_text,
            )
            if recovery_shadow is not None:
                return CharacterCreationExecutionService._ordinary_repair_provenance_chain(
                    recovery_shadow,
                    response_text,
                )
        current_node: dict[str, Any]
        if latest_is_current:
            current_node = latest
        else:
            # A direct deterministic correction is compiled before its new
            # ledger row is appended.  Expose it as a virtual leaf only when
            # its marker binds exactly to the persisted latest row.
            marker = direct_marker
            if not isinstance(marker, dict):
                return None
            parent_id = marker.get("prior_attempt_id")
            parent = records.get(parent_id) if isinstance(parent_id, str) else None
            if (
                marker.get("applied_response_sha256") != current_sha256
                or not isinstance(parent, dict)
                or parent.get("_response_sha256") != marker.get("prior_response_sha256")
            ):
                return None
            current_node = {
                "attempt_id": "__current_unappended_deterministic_correction__",
                "action_type": "LOCAL_PROVIDER_CORRECTION",
                "prior_attempt_id": parent_id,
                "_parent_id": parent_id,
                "_response_text": response_text,
                "_response_sha256": current_sha256,
                "_transport": (
                    run.get("transport") if isinstance(run.get("transport"), dict) else {}
                ),
            }
        if bypass_owner is not None and not latest_is_current:
            if current_node.get("_parent_id") != latest.get("attempt_id"):
                return None

        def row_transport(item: dict[str, Any]) -> dict[str, Any] | None:
            value = item.get("_transport")
            return value if isinstance(value, dict) else None

        def deterministic_transport_valid(transport: dict[str, Any]) -> bool:
            if transport.get("provider_called") is not False:
                return False
            if type(transport.get("automatic_retries")) is not int or transport.get("automatic_retries") != 0:
                return False
            return True

        def marker_valid(
            marker: dict[str, Any],
            *,
            item: dict[str, Any],
            parent: dict[str, Any],
        ) -> bool:
            if (
                marker.get("deterministic_server_repair") is not True
                or marker.get("provider_called") is not False
                or marker.get("prior_attempt_id") != item.get("_parent_id")
                or marker.get("prior_response_sha256") != parent.get("_response_sha256")
                or marker.get("applied_response_sha256") != item.get("_response_sha256")
            ):
                return False
            if marker.get("request_sha256") not in (None, request_sha256):
                return False
            for key in (
                "raw_provider_completion_sha256",
                "raw_provider_response_sha256",
                "provider_completion_sha256",
                "provider_response_sha256",
            ):
                if marker.get(key) is not None:
                    return False
            target_kind = marker.get("target_kind")
            if target_kind not in {
                "ordinary_duplicate",
                _ORDINARY_ORDER_MIRROR_TARGET_KIND,
                "bounded_field_cleanup",
                "free_talent_sphere_server_repair",
                "bounded_path_progression_singleton",
                "bounded_path_progression_empty_cleanup",
            }:
                return False
            return True

        visited: set[str] = set()
        node = current_node
        current_node_projection = current_projection
        ordinary_marker: dict[str, Any] | None = None
        ordinary_response_text: str | None = None
        prior_response_text: str | None = None
        advancement_choice_markers: list[dict[str, Any]] = []
        advancement_choice_intermediary_seen = False
        while True:
            node_id = node.get("attempt_id")
            if not isinstance(node_id, str) or node_id in visited:
                return None
            visited.add(node_id)
            node_text = node.get("_response_text")
            node_hash = node.get("_response_sha256")
            node_projection = CharacterCreationExecutionService._ordinary_response_array_projection(node_text)
            if node_projection is None or node_hash != sha256_bytes(node_text.encode("utf-8")):
                return None
            if node_id == current_node.get("attempt_id") and node_id == "__current_unappended_deterministic_correction__":
                node_transport = row_transport(node) or {}
            else:
                node_transport = row_transport(node)
            action_type = node.get("action_type")
            if action_type in {"IMPORT_RESPONSE", "REPLACE_RESPONSE"}:
                # The original provider response is the only permitted root
                # of this proof.  It may contain the rejected duplicate array,
                # but it cannot be a hidden deterministic intermediary.
                if (
                    ordinary_marker is None
                    or node_transport is None
                    or node_transport.get("provider_called") is not True
                    or "local_correction" in node_transport
                ):
                    return None
                return {
                    "marker": deepcopy(ordinary_marker),
                    "prior_response_text": prior_response_text,
                    "ordinary_response_text": ordinary_response_text,
                    "advancement_choice_marker": (
                        deepcopy(advancement_choice_markers[-1])
                        if advancement_choice_markers
                        else None
                    ),
                    "advancement_choice_markers": deepcopy(advancement_choice_markers),
                }
            if action_type == "LOCAL_PROVIDER_CORRECTION":
                marker = node_transport.get("local_correction") if isinstance(node_transport, dict) else None
                parent_id = node.get("_parent_id")
                parent = records.get(parent_id) if isinstance(parent_id, str) else None
                parent_text = parent.get("_response_text") if isinstance(parent, dict) else None
                parent_projection = (
                    CharacterCreationExecutionService._ordinary_response_array_projection(parent_text)
                    if isinstance(parent_text, str)
                    else None
                )
                if isinstance(marker, dict) and marker.get("target_kind") == "advancement_choice":
                    if (
                        not isinstance(parent, dict)
                        or parent_projection is None
                        or not CharacterCreationExecutionService._ordinary_repair_advancement_choice_intermediary_valid(
                            run,
                            node,
                            parent,
                            request_sha256=request_sha256,
                            item_projection=node_projection,
                            parent_projection=parent_projection,
                        )
                    ):
                        return None
                    milestone_id = marker.get("milestone_id")
                    if any(
                        existing.get("milestone_id") == milestone_id
                        for existing in advancement_choice_markers
                    ):
                        return None
                    # The walk is leaf-to-root; retain the proof in the
                    # historical root-to-leaf order for downstream checks.
                    advancement_choice_markers.insert(0, deepcopy(marker))
                    advancement_choice_intermediary_seen = True
                    node = parent
                    current_node_projection = parent_projection
                    continue
                if node_transport is None or not deterministic_transport_valid(node_transport):
                    return None
                if not isinstance(marker, dict) or not isinstance(parent, dict) or not marker_valid(marker, item=node, parent=parent):
                    return None
                parent_text = parent.get("_response_text")
                parent_hash = parent.get("_response_sha256")
                if not isinstance(parent_text, str) or not isinstance(parent_hash, str):
                    return None
                target_kind = marker.get("target_kind")
                parent_projection = CharacterCreationExecutionService._ordinary_response_array_projection(parent_text)
                if parent_projection is None:
                    return None
                if target_kind in {"ordinary_duplicate", _ORDINARY_ORDER_MIRROR_TARGET_KIND}:
                    if ordinary_marker is not None:
                        return None
                    ordinary_marker = deepcopy(marker)
                    ordinary_response_text = node_text
                    prior_response_text = parent_text
                elif parent_projection != node_projection:
                    # Bounded cleanup/free-sphere correction cannot rewrite
                    # the ordinary array after the duplicate expansion.
                    return None
                node = parent
                current_node_projection = parent_projection
                continue
            if action_type == "RETRY_LOCAL_BUILD":
                if (
                    isinstance(node_transport, dict)
                    and isinstance(node_transport.get("local_recovery"), dict)
                    and (advancement_choice_intermediary_seen or direct_marker is None)
                ):
                    node_index = item_indexes.get(node_id)
                    node_text = node.get("_response_text")
                    node_hash = node.get("_response_sha256")
                    if (
                        node_index is None
                        or not isinstance(node_text, str)
                        or not isinstance(node_hash, str)
                        or node_index >= len(history)
                    ):
                        return None
                    recovery_run = dict(run)
                    recovery_run["attempt_history"] = history[: node_index + 1]
                    recovery_run["transport"] = deepcopy(node_transport)
                    recovery_run["response"] = {
                        "exact_response_text": node_text,
                        "response_sha256": node_hash,
                    }
                    recovery_run["validation"] = deepcopy(node.get("validation") or {})
                    if not isinstance(recovery_run["validation"].get("last_submission_error"), dict):
                        node_error = node.get("error")
                        if isinstance(node_error, dict):
                            recovery_run["validation"]["last_submission_error"] = deepcopy(node_error)
                    recovery_shadow = CharacterCreationExecutionService._ordinary_repair_recovery_shadow(
                        recovery_run,
                        node_text,
                    )
                    if recovery_shadow is None:
                        return None
                    recovery_proof = CharacterCreationExecutionService._ordinary_repair_provenance_chain(
                        recovery_shadow,
                        node_text,
                    )
                    if recovery_proof is not None and advancement_choice_markers:
                        inherited_markers = recovery_proof.get("advancement_choice_markers")
                        inherited_markers = inherited_markers if isinstance(inherited_markers, list) else []
                        combined_markers = [deepcopy(marker) for marker in inherited_markers]
                        for marker in advancement_choice_markers:
                            milestone_id = marker.get("milestone_id")
                            if any(
                                existing.get("milestone_id") == milestone_id
                                for existing in combined_markers
                                if isinstance(existing, dict)
                            ):
                                return None
                            combined_markers.append(deepcopy(marker))
                        recovery_proof["advancement_choice_markers"] = combined_markers
                        recovery_proof["advancement_choice_marker"] = deepcopy(combined_markers[-1])
                    return recovery_proof
                if (
                    node_transport is None
                    or not deterministic_transport_valid(node_transport)
                    or node_transport.get("transfer") != "retry_local_build"
                    or "local_correction" in node_transport
                ):
                    return None
                parent_id = node.get("_parent_id")
                parent = records.get(parent_id) if isinstance(parent_id, str) else None
                if not isinstance(parent, dict):
                    return None
                parent_text = parent.get("_response_text")
                parent_hash = parent.get("_response_sha256")
                parent_projection = CharacterCreationExecutionService._ordinary_response_array_projection(parent_text)
                if (
                    not isinstance(parent_text, str)
                    or not isinstance(parent_hash, str)
                    or parent_hash != node_hash
                    or parent_projection is None
                    or parent_projection != node_projection
                ):
                    return None
                node = parent
                current_node_projection = parent_projection
                continue
            # REQUEST_CREATED and arbitrary owner/provider actions cannot be
            # hidden between an ordinary repair and its exact provider root.
            return None

    @staticmethod
    def _validated_repaired_ordinary_context(
        run: dict[str, Any],
        plan: dict[str, Any],
        response_text: str | None,
    ) -> dict[str, Any] | None:
        """Prove a server-expanded ordinary array before leaving the compact world.

        The model-facing ordinary shortlist is intentionally compact.  A
        deterministic duplicate repair may therefore use the full sealed
        authority, but only its exact persisted correction marker can opt into
        that projection.  Reconstructing the failed duplicate response from
        the diagnostic and re-running the frozen target builder binds the
        current array to the same authority/position proof; ordinary provider
        responses without this marker remain closed-world validated below.
        """
        if not isinstance(run, dict) or not isinstance(plan, dict):
            return None
        if not isinstance(response_text, str) or not response_text.strip():
            return None
        transport = run.get("transport") if isinstance(run.get("transport"), dict) else {}
        direct_marker = transport.get("local_correction")
        direct_marker = direct_marker if isinstance(direct_marker, dict) else None
        has_recovery_receipt = isinstance(transport.get("local_recovery"), dict)
        if direct_marker is None and not has_recovery_receipt:
            validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
            candidate = validation.get("automatic_correction")
            direct_marker = candidate if isinstance(candidate, dict) else None
        provenance = CharacterCreationExecutionService._ordinary_repair_provenance_chain(
            run,
            response_text,
            direct_marker=direct_marker,
        )
        if not isinstance(provenance, dict):
            return None
        marker = provenance.get("marker")
        prior_source_text = provenance.get("prior_response_text")
        ordinary_source_text = provenance.get("ordinary_response_text")
        if (
            not isinstance(marker, dict)
            or marker.get("target_kind") != "ordinary_duplicate"
            or not isinstance(prior_source_text, str)
            or not isinstance(ordinary_source_text, str)
            or CharacterCreationExecutionService._ordinary_response_array_projection(ordinary_source_text)
            != CharacterCreationExecutionService._ordinary_response_array_projection(response_text)
        ):
            return None
        try:
            current_payload = json.loads(response_text)
        except (TypeError, ValueError):
            return None
        if not isinstance(current_payload, dict):
            return None
        current_acquisition = current_payload.get("acquisition_intent")
        current_plan_acquisition = plan.get("acquisition_intent")
        if not isinstance(current_acquisition, dict) or not isinstance(current_plan_acquisition, dict):
            return None
        current_ordinary = current_acquisition.get("ordinary_talent_ids")
        plan_ordinary = current_plan_acquisition.get("ordinary_talent_ids")
        if (
            not isinstance(current_ordinary, list)
            or not isinstance(plan_ordinary, list)
            or current_ordinary != plan_ordinary
            or not current_ordinary
            or any(not isinstance(value, str) or not value.strip() for value in current_ordinary)
            or len(set(current_ordinary)) != len(current_ordinary)
        ):
            return None

        current_selection = current_payload.get("selection_intent")
        current_by_slot = current_selection.get("by_slot") if isinstance(current_selection, dict) else None
        plan_selection = plan.get("selection_intent")
        plan_by_slot = plan_selection.get("by_slot") if isinstance(plan_selection, dict) else None
        current_mirror = current_by_slot.get("advancement_skeleton") if isinstance(current_by_slot, dict) else None
        plan_mirror = plan_by_slot.get("advancement_skeleton") if isinstance(plan_by_slot, dict) else None
        if current_mirror != plan_mirror:
            return None
        fields = marker.get("fields")
        if (
            not isinstance(fields, list)
            or any(not isinstance(field, str) or not field.strip() for field in fields)
            or len(set(fields)) != len(fields)
            or "acquisition_intent.ordinary_talent_ids" not in fields
        ):
            return None
        has_mirror = isinstance(current_mirror, list)
        if has_mirror:
            if current_mirror != current_ordinary or "selection_intent.by_slot.advancement_skeleton" not in fields:
                return None
        elif "selection_intent.by_slot.advancement_skeleton" in fields:
            return None

        diagnostic = marker.get("validator_diagnostic")
        if (
            not isinstance(diagnostic, dict)
            or diagnostic.get("code") != "CG1_DELEGATED_DUPLICATE_CHOICE"
        ):
            return None
        details = diagnostic.get("details")
        if not isinstance(details, dict):
            return None
        reported_ids = details.get("choice_ids")
        if details.get("slot_id") != "advancement_skeleton":
            reported_ids = details.get("ordinary_talent_ids")
        if (
            not isinstance(reported_ids, list)
            or not reported_ids
            or any(not isinstance(value, str) or not value.strip() for value in reported_ids)
        ):
            return None
        # The chain resolver has already bound the exact retained provider
        # bytes to the ordinary correction marker.  Never reconstruct a
        # missing parent from the corrected response: doing so would make a
        # forged diagnostic look like durable provider evidence.
        prior_hash = marker.get("prior_response_sha256")
        if not isinstance(prior_hash, str) or sha256_bytes(prior_source_text.encode("utf-8")) != prior_hash:
            return None
        try:
            parsed_prior = json.loads(prior_source_text)
        except (TypeError, ValueError):
            parsed_prior = None
        prior_source_payload = parsed_prior if isinstance(parsed_prior, dict) else None
        if prior_source_payload is None:
            return None

        # The original diagnostic is the only retained description of the
        # rejected array.  Its bytes are rebound to the marker's prior hash
        # before the full authority target is regenerated.
        prior_payload = deepcopy(prior_source_payload or current_payload)
        prior_acquisition = prior_payload.get("acquisition_intent")
        if not isinstance(prior_acquisition, dict):
            return None
        actual_prior_ordinary = prior_acquisition.get("ordinary_talent_ids")
        if actual_prior_ordinary != reported_ids:
            return None
        if has_mirror:
            prior_selection = prior_payload.get("selection_intent")
            prior_by_slot = prior_selection.get("by_slot") if isinstance(prior_selection, dict) else None
            if not isinstance(prior_by_slot, dict) or prior_by_slot.get("advancement_skeleton") != reported_ids:
                return None
        # The exact retained provider bytes are already hash-bound and parsed
        # above.  Preserve their formatting when rebuilding the frozen target;
        # canonical reserialization would reject valid pretty-printed provider
        # evidence even though its semantic arrays are unchanged and its raw
        # hash is already verified.
        prior_response = prior_source_text
        target = CharacterCreationExecutionService._provider_ordinary_duplicate_repair_target(
            diagnostic,
            run=run,
            prior_response=prior_response,
        )
        if not isinstance(target, dict) or target.get("target_kind") != "ordinary_duplicate":
            return None
        if (
            target.get("required_count") != len(current_ordinary)
            or target.get("has_advancement_mirror") is not has_mirror
            or target.get("prior_ordinary_talent_ids") != reported_ids
        ):
            return None
        selected_option_id = marker.get("selected_option_id")
        options = target.get("options")
        if (
            not isinstance(selected_option_id, str)
            or not selected_option_id.strip()
            or not isinstance(options, dict)
            or selected_option_id not in options
        ):
            return None
        selected_option = options[selected_option_id]
        selected_ids = selected_option.get("ordinary_talent_ids") if isinstance(selected_option, dict) else None
        if selected_ids != current_ordinary:
            return None
        # The target builder has already established publication, complete
        # Stage-2 authority, sphere ownership, prerequisites, and a matching
        # assignment for every effective CL.  Return only the small proof
        # needed by the compact preflight; never copy authority into output.
        return {
            "ordinary_talent_ids": deepcopy(current_ordinary),
            "selected_option_id": selected_option_id,
        }

    @staticmethod
    def _point_buy_budget_owner_decision(
        run: dict[str, Any],
        plan: dict[str, Any],
    ) -> dict[str, Any] | None:
        """Build one bound owner choice for an over-budget point-buy map.

        The provider response remains byte-for-byte immutable.  This helper
        only derives a single legal owner value from the sealed bounded
        contract; the normal owner-resolution overlay applies that value and
        re-runs the complete validator.  In particular, it never guesses for
        an under-budget, malformed, or fixed owner-locked map.
        """
        if not isinstance(run, dict) or not isinstance(plan, dict):
            return None
        if plan.get("schema") != DELEGATED_RESPONSE_SCHEMA:
            return None
        request = run.get("request")
        if not isinstance(request, dict):
            return None
        contract = request.get("bounded_choice_contract")
        contract = contract if isinstance(contract, dict) else {}
        if contract.get("schema") != "TianxiaFoundry.BoundedChoiceContract.v1":
            return None
        fields = contract.get("fields")
        fields = fields if isinstance(fields, dict) else {}
        point_buy_contract = fields.get("ability_scores")
        if not isinstance(point_buy_contract, dict) or point_buy_contract.get("type") != "point_buy_scores":
            return None
        required_budget = point_buy_contract.get("budget")
        if type(required_budget) is not int or required_budget != 27:
            return None
        advertised_abilities = point_buy_contract.get("abilities")
        if advertised_abilities != list(_PROVIDER_POINT_BUY_ABILITIES):
            return None
        advertised_values = point_buy_contract.get("allowed_values")
        if advertised_values != list(sorted(_PROVIDER_POINT_BUY_COSTS)):
            return None

        # A complete fixed lock is owner authority, even if a malformed or
        # legacy request happens to leave the bounded field advertised.
        prompt = request.get("stage1_prompt")
        prompt = prompt if isinstance(prompt, dict) else {}
        prompt_envelope = prompt.get("envelope")
        prompt_envelope = prompt_envelope if isinstance(prompt_envelope, dict) else {}
        point_buy_lock = next(
            (
                row.get("value")
                for row in prompt_envelope.get("user_locks") or []
                if isinstance(row, dict)
                and row.get("field") == "character_sheet.ability_point_buy"
            ),
            None,
        )
        fixed_scores = point_buy_lock.get("fixed_scores") if isinstance(point_buy_lock, dict) else None
        if (
            isinstance(fixed_scores, dict)
            and set(fixed_scores) == set(_PROVIDER_POINT_BUY_ABILITIES)
            and not point_buy_lock.get("auto_abilities")
        ):
            return None

        bounded = plan.get("bounded_choices")
        bounded = bounded if isinstance(bounded, dict) else {}
        scores = bounded.get("ability_scores")
        if not isinstance(scores, dict) or set(scores) != set(_PROVIDER_POINT_BUY_ABILITIES):
            return None
        current: dict[str, int] = {}
        for ability in _PROVIDER_POINT_BUY_ABILITIES:
            score = scores.get(ability)
            if type(score) is not int or score not in _PROVIDER_POINT_BUY_COSTS:
                return None
            current[ability] = score
        computed_cost = sum(_PROVIDER_POINT_BUY_COSTS[score] for score in current.values())
        # Only over-budget maps receive a deterministic normalization.  The
        # ordinary validator remains authoritative for every other mismatch.
        if computed_cost <= required_budget:
            return None

        candidates: list[tuple[tuple[Any, ...], dict[str, int]]] = []
        allowed_scores = tuple(sorted(_PROVIDER_POINT_BUY_COSTS))
        for values in itertools.product(allowed_scores, repeat=len(_PROVIDER_POINT_BUY_ABILITIES)):
            candidate = dict(zip(_PROVIDER_POINT_BUY_ABILITIES, values))
            if sum(_PROVIDER_POINT_BUY_COSTS[value] for value in values) != required_budget:
                continue
            # Never increase a score while repairing an over-budget response.
            if any(candidate[ability] > current[ability] for ability in _PROVIDER_POINT_BUY_ABILITIES):
                continue
            # The normalization policy is deliberately independent of the
            # prompt's example presets: rank only by score deltas, then the
            # squared deltas, then canonical score order.
            decreases = tuple(
                current[ability] - candidate[ability]
                for ability in _PROVIDER_POINT_BUY_ABILITIES
            )
            rank = (
                sum(decreases),
                sum(value * value for value in decreases),
                tuple(-candidate[ability] for ability in _PROVIDER_POINT_BUY_ABILITIES),
            )
            candidates.append((rank, candidate))
        if not candidates:
            return None
        _rank, normalized = min(candidates, key=lambda item: item[0])
        return {
            "field": "ability_scores",
            "operation": "set_field",
            "current_value": deepcopy(current),
            "current_scores": deepcopy(current),
            "computed_cost": computed_cost,
            "required_budget": required_budget,
            "repaired_value": deepcopy(normalized),
            "repaired_scores": deepcopy(normalized),
            "repaired_cost": required_budget,
            "cost_by_score": {
                str(key): value for key, value in sorted(_PROVIDER_POINT_BUY_COSTS.items())
            },
            "algorithm": "bounded_point_buy_budget_normalization.v1",
            "policy": (
                "downward_only_min_total_decrease_then_squared_decrease_then_"
                "lexicographically_maximize_scores_in_STR_DEX_CON_INT_WIS_CHA_order"
            ),
            "legal_choices": [{
                "value": deepcopy(normalized),
                "label": "Factory-normalized legal 27-point-buy allocation.",
                "cost": required_budget,
            }],
        }

    @staticmethod
    def _validate_preferred_bounded_fields(
        run: dict[str, Any],
        plan: dict[str, Any],
        *,
        response_text: str | None = None,
    ) -> None:
        """Reject fields and acquisitions outside the model-facing closed world."""
        if plan.get("schema") != DELEGATED_RESPONSE_SCHEMA:
            return
        bounded = plan.get("bounded_choices")
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        request_bounded_contract = (
            request.get("bounded_choice_contract")
            if isinstance(request.get("bounded_choice_contract"), dict)
            else {}
        )
        advertised = request_bounded_contract.get("fields") or {}
        validate_foundation_initial_stage(
            request, (plan.get("selection_intent") or {}).get("by_slot") or {},
            bounded if isinstance(bounded, dict) else {},
        )
        if isinstance(bounded, dict):
            unknown = sorted(set(bounded) - set(advertised))
            if unknown:
                raise FoundryError(
                    "CG1_PREFERRED_RESPONSE_BOUNDED_FIELD_INVALID",
                    "The preferred response supplied a bounded field not advertised by the sealed request.",
                    details={"fields": unknown},
                    status_code=422,
                )

        # Starting proficiencies are a single sealed semantic contract.  Run
        # the pure validator before any provider-contract/acquisition work so
        # an omitted or forged mandatory map cannot reach Stage 2 as if it
        # were complete.  Only the three exact slot IDs are projected here;
        # unrelated by-slot choices remain owned by their existing validators.
        starting_fields = {
            field
            for field in _STARTING_PROFICIENCY_FIELD_KEYS
            if isinstance(advertised, dict) and field in advertised
        }
        if starting_fields:
            selection = plan.get("selection_intent")
            selection = selection if isinstance(selection, dict) else {}
            by_slot = selection.get("by_slot")
            by_slot = by_slot if isinstance(by_slot, dict) else {}
            selected_by_slot = {
                slot: by_slot.get(slot)
                for slot in (
                    "path_choice",
                    "background_choice",
                    "origin_insight_choice",
                )
            }
            starting_validation = validate_starting_proficiency_choices(
                contract=request_bounded_contract.get("starting_proficiency_choice_contract"),
                selected_by_slot=selected_by_slot,
                bounded_choices=bounded,
            )
            if starting_validation.get("valid") is not True:
                raise FoundryError(
                    "CG1_STARTING_PROFICIENCY_CHOICE_INVALID",
                    "The preferred response did not satisfy the sealed starting-proficiency choice contract.",
                    details={
                        "schema": starting_validation.get("schema"),
                        "contract_sha256": starting_validation.get("contract_sha256"),
                        "validation_sha256": starting_validation.get("validation_sha256"),
                        "blockers": deepcopy(starting_validation.get("blockers") or []),
                    },
                    status_code=422,
                )

        # Validate the small deterministic provider contract before materializing
        # any Stage 2 event or canonical creator grant.  The later delegated
        # validator remains authoritative; this preflight gives Local AI one
        # actionable, allowlisted diagnostic instead of a late aggregate
        # catalog failure.
        provider_payload = _provider_payload(
            run,
            cue_limit=0,
            display_limit=0,
        )
        provider_contract = provider_payload.get("response_contract") or {}
        # ``sphere_route_modules`` is the single authoritative route copy in
        # the model-facing payload.  The response contract contains an
        # explicit reference rather than a second full copy.
        route_modules = [
            row for row in provider_payload.get("sphere_route_modules") or []
            if isinstance(row, dict)
        ]
        acquisition = plan.get("acquisition_intent")
        acquisition = acquisition if isinstance(acquisition, dict) else {}
        expected = provider_contract.get("expected_acquisition_counts") or {}
        presented_pairs = [
            row for row in provider_contract.get("presented_legal_first_cycle_pairs") or []
            if isinstance(row, dict)
        ]
        pair_keys = {
            (row.get("sphere_id"), row.get("talent_id"))
            for row in presented_pairs
            if isinstance(row.get("sphere_id"), str) and isinstance(row.get("talent_id"), str)
        }
        # A deterministic-controller walk never saw the legacy prompt's
        # presented route sample. Its free pair is legal when it belongs to the
        # complete sealed legal pair set (owner decision 10: the six-Sphere
        # sample is not the legal set), and its level talents were chosen from
        # menus that mirror the delegated validator, which remains
        # authoritative below. The presented-sample and route-module bindings
        # in this preflight therefore apply to legacy full-plan responses only.
        controller_walk = request.get("controller_route") == DETERMINISTIC_CREATIVE_CONTROLLER
        if controller_walk:
            pair_keys = {
                (row.get("sphere_id"), row.get("talent_id"))
                for row in _legal_free_pairs(request, request.get("delegated_choice_envelope") or {})
                if isinstance(row, dict)
            }
        pairs = acquisition.get("sphere_free_talent_pairs")
        pairs = pairs if isinstance(pairs, list) else []
        ordinary = acquisition.get("ordinary_talent_ids")
        ordinary = ordinary if isinstance(ordinary, list) else []
        selection = plan.get("selection_intent")
        selection = selection if isinstance(selection, dict) else {}
        by_slot = selection.get("by_slot")
        by_slot = by_slot if isinstance(by_slot, dict) else {}
        skeleton = by_slot.get("advancement_skeleton")
        issues: list[dict[str, Any]] = []
        repaired_ordinary = CharacterCreationExecutionService._validated_repaired_ordinary_context(
            run,
            plan,
            response_text,
        )

        expected_pair_count = expected.get("sphere_free_talent_pairs")
        if type(expected_pair_count) is int and len(pairs) != expected_pair_count:
            issues.append({
                "field": "acquisition_intent.sphere_free_talent_pairs",
                "reason": "COUNT_MISMATCH",
                "expected_count": expected_pair_count,
                "actual_count": len(pairs),
                "allowed_values": deepcopy(presented_pairs),
            })
        for index, pair in enumerate(pairs):
            key = (
                pair.get("sphere_id") if isinstance(pair, dict) else None,
                pair.get("talent_id") if isinstance(pair, dict) else None,
            )
            if key not in pair_keys:
                issues.append({
                    "field": f"acquisition_intent.sphere_free_talent_pairs.{index}",
                    "reason": "NOT_LEGAL_FIRST_CYCLE_PAIR" if controller_walk else "NOT_PRESENTED_LEGAL_PAIR",
                    "proposed": deepcopy(pair),
                    "allowed_values": {"legal_pair_count": len(pair_keys)} if controller_walk else deepcopy(presented_pairs),
                })

        expected_ordinary_count = expected.get("ordinary_talent_ids")
        if type(expected_ordinary_count) is int and len(ordinary) != expected_ordinary_count:
            issues.append({
                "field": "acquisition_intent.ordinary_talent_ids",
                "reason": "COUNT_MISMATCH",
                "expected_count": expected_ordinary_count,
                "actual_count": len(ordinary),
            })
        ordinary_by_cl = provider_contract.get("presented_legal_ordinary_talent_ids_by_cl") or {}
        if not ordinary_by_cl and route_modules:
            derived_ordinary_by_cl: dict[str, list[str]] = {}
            for route in route_modules:
                for cl, choice_id in (route.get("ordinary_talent_ids_by_cl") or {}).items():
                    if not isinstance(cl, str) or not isinstance(choice_id, str):
                        continue
                    derived_ordinary_by_cl.setdefault(cl, []).append(choice_id)
            ordinary_by_cl = {
                cl: sorted(set(choice_ids))
                for cl, choice_ids in sorted(derived_ordinary_by_cl.items())
            }
        for index, choice_id in enumerate([] if controller_walk else ordinary):
            allowed_ids = ordinary_by_cl.get(str(index + 1))
            allowed_ids = allowed_ids if isinstance(allowed_ids, list) else []
            if choice_id not in allowed_ids and not (
                isinstance(repaired_ordinary, dict)
                and repaired_ordinary.get("ordinary_talent_ids") == ordinary
            ):
                issues.append({
                    "field": f"acquisition_intent.ordinary_talent_ids.{index}",
                    "reason": "NOT_PRESENTED_LEGAL_ORDINARY_TALENT",
                    "effective_cl": index + 1,
                    "proposed": deepcopy(choice_id),
                    "allowed_choice_ids": deepcopy(allowed_ids),
                })
        selected_routes: list[dict[str, Any]] = []
        if route_modules and pairs and not controller_walk:
            for pair in pairs:
                pair_key = (
                    pair.get("sphere_id") if isinstance(pair, dict) else None,
                    pair.get("talent_id") if isinstance(pair, dict) else None,
                )
                matching = [
                    route for route in route_modules
                    if (
                        isinstance(route.get("free_talent_pair"), dict)
                        and route["free_talent_pair"].get("sphere_id") == pair_key[0]
                        and route["free_talent_pair"].get("talent_id") == pair_key[1]
                    )
                ]
                if len(matching) != 1:
                    issues.append({
                        "field": "acquisition_intent.sphere_free_talent_pairs",
                        "reason": "NOT_PRESENTED_COMPLETE_ROUTE",
                        "proposed": deepcopy(pair),
                        "allowed_values": [
                            deepcopy(route.get("free_talent_pair")) for route in route_modules
                        ],
                    })
                    continue
                selected_routes.append(matching[0])
            if selected_routes:
                # The ordinary choices must come from the complete route(s)
                # selected by their whole free pair.  A Talent from another
                # presented route is not a legal cross-route splice.
                route_ids_by_cl: dict[str, set[str]] = {}
                for route in selected_routes:
                    for cl, choice_id in (route.get("ordinary_talent_ids_by_cl") or {}).items():
                        if isinstance(cl, str) and isinstance(choice_id, str):
                            route_ids_by_cl.setdefault(cl, set()).add(choice_id)
                for index, choice_id in enumerate(ordinary):
                    allowed_route_ids = route_ids_by_cl.get(str(index + 1), set())
                    if choice_id not in allowed_route_ids:
                        issues.append({
                            "field": f"acquisition_intent.ordinary_talent_ids.{index}",
                            "reason": "CROSS_ROUTE_MIXING",
                            "effective_cl": index + 1,
                            "proposed": deepcopy(choice_id),
                            "allowed_choice_ids": sorted(allowed_route_ids),
                        })
        # When the sealed projection proves one exact Talent for each
        # effective CL, expose that derived order in the diagnostic.  This is
        # the only mirror value a retry-only deterministic repair may use; a
        # non-unique map retains the provider's submitted array and therefore
        # cannot authorize server reordering.
        mirror_required_value = deepcopy(ordinary)
        unique_order: list[str] | None = None
        if type(expected_ordinary_count) is int and expected_ordinary_count == len(ordinary) and not controller_walk:
            candidate_order: list[str] = []
            candidate_order_valid = True
            for effective_cl in range(1, expected_ordinary_count + 1):
                values = ordinary_by_cl.get(str(effective_cl))
                if (
                    not isinstance(values, list)
                    or len(values) != 1
                    or not isinstance(values[0], str)
                    or not values[0].strip()
                ):
                    candidate_order_valid = False
                    break
                candidate_order.append(values[0])
            if candidate_order_valid and len(set(candidate_order)) == expected_ordinary_count:
                unique_order = candidate_order
        if route_modules and selected_routes and len(selected_routes) == 1:
            assignments = selected_routes[0].get("ordinary_talent_ids_by_cl")
            route_order = [
                assignments.get(str(effective_cl))
                for effective_cl in range(1, len(ordinary) + 1)
            ] if isinstance(assignments, dict) else []
            if (
                len(route_order) == len(ordinary)
                and all(isinstance(value, str) and value.strip() for value in route_order)
                and len(set(route_order)) == len(route_order)
            ):
                unique_order = route_order
        if unique_order is not None:
            mirror_required_value = unique_order
        if skeleton != ordinary:
            issues.append({
                "field": "selection_intent.by_slot.advancement_skeleton",
                "reason": "MUST_MIRROR_ORDINARY_TALENT_IDS",
                "proposed": deepcopy(skeleton),
                "required_value": mirror_required_value,
            })
        if issues:
            raise FoundryError(
                "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID",
                "The preferred response did not copy the frozen presented acquisition choices and counts.",
                details={
                    "issues": issues,
                    "expected_acquisition_counts": deepcopy(expected),
                    "presented_legal_first_cycle_pairs": deepcopy(presented_pairs),
                    "presented_legal_ordinary_talent_ids_by_cl": deepcopy(ordinary_by_cl),
                },
                status_code=422,
            )

    def _required_collaborators(self, combat_requested: bool) -> list[str]:
        if self.production_release is not None:
            # The release adapter already performs and seals the complete
            # combat cross-surface proof.  A separate combat collaborator is
            # only required on the legacy/non-production pipeline.
            return ["stage1", "stage2", "projections", "character_sheets", "factory_authoring"]
        required = ["stage1", "stage2", "projections", "character_sheets", "factory_authoring", "gm_exports", "gm_consumer", "portable_characters"]
        if combat_requested:
            required.append("combat_readiness")
        return required

    def _collaborator_blockers(self, combat_requested: bool) -> list[dict[str, Any]]:
        blockers=[]
        if self.production_release is not None:
            readiness = self.production_release.readiness()
            if not readiness.get("ready"):
                blockers.append({
                    "code": "CG1_PRODUCTION_AUTHORITY_NOT_READY",
                    "collaborator": "production_release",
                    "message": "The concrete production release authority is unavailable.",
                    "readiness": readiness,
                })
        for name in self._required_collaborators(combat_requested):
            if getattr(self, name, None) is None and self.pipeline_factory is None:
                blockers.append({"code":"CG1_REQUIRED_COLLABORATOR_MISSING","collaborator":name,"message":f"Required local service is unavailable: {name}."})
        return blockers

    def _backup_database(self, source: Path, target: Path) -> None:
        """Snapshot the live database file for a scratch compile.

        On a reflink-capable filesystem the main database file is cloned in
        one atomic ``FICLONE`` while this connection holds the write lock and
        the WAL has just been truncated, so no other writer or checkpoint can
        touch the main file during the clone and the copy is byte-identical
        to a quiescent database.  Any refusal (busy WAL, other filesystem,
        no ioctl) falls back to SQLite's page-by-page backup API.
        """

        target.parent.mkdir(parents=True, exist_ok=True)
        source_wal = Path(f"{source}-wal")
        target_wal = Path(f"{target}-wal")
        target_shm = Path(f"{target}-shm")
        with sqlite3.connect(source) as src:
            src.isolation_level = None
            cloned = False
            try:
                for stale in (target, target_wal, target_shm):
                    if stale.exists():
                        stale.unlink()
                src.execute("PRAGMA wal_checkpoint(PASSIVE)")
                # Holding the write lock: no other writer can append to the
                # WAL and no committing writer can checkpoint, so the main
                # file plus the WAL are a consistent pair; SQLite replays the
                # cloned WAL on first open of the snapshot.
                src.execute("BEGIN IMMEDIATE")
                try:
                    cloned = _reflink_file(source, target)
                    if cloned and source_wal.exists() and source_wal.stat().st_size > 0:
                        cloned = _reflink_file(source_wal, target_wal)
                finally:
                    src.execute("ROLLBACK")
            except (sqlite3.Error, OSError):
                cloned = False
            if cloned:
                return
            for stale in (target, target_wal, target_shm):
                if stale.exists():
                    stale.unlink()
            with sqlite3.connect(target) as dst:
                src.execute("PRAGMA wal_checkpoint(FULL)")
                src.backup(dst)

    def _snapshot_excluded_names(self) -> frozenset[str]:
        """Top-level data-root entries never carried into a scratch or precommit snapshot.

        ``backups/`` holds the pre-migration database copies (4.6 GB on the
        owner's machine next to a 2.1 GB live database).  Every scratch
        compile copied it into the service's tmpfs and the clean-import proof
        copied it again, so one compile could stage over 13 GB of RAM inside a
        12 GB cgroup.  Nothing in a compile reads those backups; restore and
        the post-restore tree comparison honour the same exclusion so the live
        directory is neither wiped nor flagged as diverged.
        """
        settings = self.db.settings
        try:
            relative = settings.backups_dir.resolve().relative_to(settings.data_dir.resolve())
        except ValueError:
            return frozenset()
        return frozenset({relative.parts[0]}) if len(relative.parts) == 1 else frozenset()

    def _snapshot_data(self, target: Path, *, hash_tree: bool = True) -> dict[str, str]:
        """Stage the live data root into ``target``.

        Returns the copied tree manifest.  The scratch compilers discard that
        manifest, and hashing the copied multi-gigabyte database is pure I/O,
        so they pass ``hash_tree=False``; the precommit/rollback path keeps the
        default because it compares the manifest after restore.
        """
        src = self.db.settings.data_dir
        target.mkdir(parents=True, exist_ok=True)
        db_rel = self.db.settings.db_path.relative_to(src)
        excluded = self._snapshot_excluded_names()
        for item in src.iterdir():
            if item == self.db.settings.db_path or item.name in {self.db.settings.db_path.name+"-wal", self.db.settings.db_path.name+"-shm"}:
                continue
            if item.name in excluded:
                continue
            dest=target/item.name
            if item.is_dir(): shutil.copytree(item,dest,symlinks=True,copy_function=_reflink_copy2)
            else: _reflink_copy2(item,dest)
        self._backup_database(self.db.settings.db_path, target/db_rel)
        return self._tree_hashes(target) if hash_tree else {}

    def _snapshot_external_security(self, target: Path) -> None:
        """Carry an external integrity key directory into a scratch data root.

        ``Settings.from_env`` honours ``TIANXIA_FOUNDRY_SECURITY_DIR`` (the
        Linux launcher exports it), but the scratch compile pins its
        ``security_dir`` to ``<scratch>/security``, which ``_snapshot_data``
        fills only from the live ``data/security``.  When the configured
        directory lives elsewhere the scratch compile had no key and every
        compile failed with ``INTEGRITY_KEY_MISSING``.
        """
        settings = self.db.settings
        live = settings.security_dir.resolve()
        if live == (settings.data_dir / "security").resolve() or not live.is_dir():
            return
        shutil.copytree(live, target / "security", symlinks=True, dirs_exist_ok=True)

    @staticmethod
    def _tree_hashes(root: Path, exclude: frozenset[str] | set[str] = frozenset()) -> dict[str, str]:
        return {p.relative_to(root).as_posix():sha256_file(p) for p in sorted(root.rglob("*")) if p.is_file() and not p.name.endswith(("-wal","-shm")) and p.relative_to(root).parts[0] not in exclude}

    @staticmethod
    def _remove_tree(path: Path) -> None:
        """Delete a tree even where the Factory made folders read-only."""

        def make_writable_and_retry(function: Any, target: str, _error: BaseException) -> None:
            for candidate in (os.path.dirname(target), target):
                try:
                    os.chmod(candidate, 0o700)
                except OSError:
                    pass
            function(target)

        if path.is_dir() and not path.is_symlink():
            shutil.rmtree(path, onexc=make_writable_and_retry)
        else:
            path.unlink(missing_ok=True)

    @staticmethod
    def _restore_preserved_names() -> frozenset[str]:
        """Live top-level entries a failed finalize leaves exactly as they are.

        Each name is written by match, table, or seat code and never by the finalize
        path (checked from code, see the FINALSAFE1 report).  Rolling these back to the
        precommit snapshot discarded table and match edits made while finalize ran.
        ``tabletop_auto_tokens`` is deliberately absent: ``auto_token.start`` writes it
        from finalize's own success path, so it stays part of the restored state.
        Scratch compiles and the backup exclusion do not use this list.
        """
        return frozenset({
            "Combat",
            "tabletop_buttons",
            "tabletop_presets",
            "combat_maps",
            "custom_items",
            "upload_staging",
            "opening_campaign",
            "inbox",
            "seat_meter.jsonl",
            "seat_providers.json",
            "seat_training_pairs.jsonl",
            "logs",
            "cache",
            "diagnostics",
            "tabletop_pictures",
            "tabletop_tokens",
            "team_presets",
            "owner_items",
            "seat_decisions.jsonl",
            "seat_decisions.jsonl.1",
            "seat_decisions.jsonl.lock",
        })

    def _restore_data(self, snapshot: Path) -> None:
        """Replace the live data root with ``snapshot`` without ever losing it.

        Live entries are first moved (same filesystem, atomic rename) into a
        quarantine beside the data root; only after the snapshot and database
        are restored is the quarantine deleted.  If anything fails, every
        moved entry is put back.  The previous version deleted live entries in
        place and a read-only snapshot folder stopped it halfway, destroying
        most of the data root (2026-09-24).
        """
        live=self.db.settings.data_dir
        excluded = self._snapshot_excluded_names()
        preserved = self._restore_preserved_names()
        quarantine = live.parent / f".{live.name}-restore-quarantine-{uuid.uuid4().hex}"
        quarantine.mkdir()
        moved: list[str] = []
        try:
            for child in list(live.iterdir()):
                if child == self.db.settings.db_path or child.name in {
                    self.db.settings.db_path.name+"-wal", self.db.settings.db_path.name+"-shm"
                }:
                    continue
                if child.name in excluded or child.name in preserved:
                    continue
                os.replace(child, quarantine / child.name)
                moved.append(child.name)
            for child in snapshot.iterdir():
                if child.name == self.db.settings.db_path.name or child.name in preserved:
                    continue
                dest=live/child.name
                if child.is_dir(): shutil.copytree(child,dest,symlinks=True)
                else: shutil.copy2(child,dest)
            self._restore_database_file(snapshot)
        except BaseException:
            for name in moved:
                partial = live / name
                if partial.exists() or partial.is_symlink():
                    self._remove_tree(partial)
                os.replace(quarantine / name, partial)
            raise
        try:
            self._remove_tree(quarantine)
        except OSError:
            # The restore is complete; a leftover quarantine only costs disk.
            pass

    def _keep_precommit_snapshot(self, snapshot: Path) -> Path | None:
        """Move a precommit snapshot out of its temporary directory for manual recovery."""
        target = self.db.settings.data_dir.parent / f".{self.db.settings.data_dir.name}-precommit-rescue-{uuid.uuid4().hex}"
        try:
            os.replace(snapshot, target)
        except OSError:
            try:
                shutil.copytree(snapshot, target, symlinks=True)
            except OSError:
                return None
        return target

    def _restore_database_file(self, snapshot: Path) -> None:
        source_db = snapshot / self.db.settings.db_path.name
        restore_db = self.db.settings.db_path.with_name(self.db.settings.db_path.name + ".cg1-restore")
        shutil.copy2(source_db, restore_db)
        last_error: OSError | None = None
        for _attempt in range(40):
            try:
                os.replace(restore_db, self.db.settings.db_path)
                for suffix in ("-wal", "-shm"):
                    self.db.settings.db_path.with_name(self.db.settings.db_path.name + suffix).unlink(missing_ok=True)
                return
            except OSError as exc:
                last_error = exc
                gc.collect()
                time.sleep(0.05)
        raise FoundryError(
            "CG1_ATOMIC_RESTORE_FILE_LOCKED",
            "The exact precommit database bytes could not be restored.",
            details={"path": str(self.db.settings.db_path), "cause": str(last_error)},
        )

    def _scratch_services(self, scratch_db: Database) -> dict[str, Any]:
        if self.pipeline_factory:
            return self.pipeline_factory(scratch_db)
        from stage1.service import Stage1ClipboardService
        from stage2 import Stage2AdvancementService
        from projector.service import ProjectionService
        from character_sheet import CharacterSheetService
        from factory_authoring import FactoryAuthoringWorkspaceService
        from gm_export import GMCharacterExportService
        from portable_character import PortableCharacterPackageService
        from character_creation.production_release import CharacterProductionReleaseAdapter, _COMBAT_REQUIRED_FIELDS
        return {
            "stage1": Stage1ClipboardService(scratch_db), "stage2": Stage2AdvancementService(scratch_db),
            "projections": ProjectionService(scratch_db), "character_sheets": CharacterSheetService(scratch_db),
            "factory_authoring": FactoryAuthoringWorkspaceService(scratch_db), "gm_exports": GMCharacterExportService(scratch_db),
            "portable_characters": PortableCharacterPackageService(scratch_db), "gm_consumer": self.gm_consumer,
            "combat_readiness": self.combat_readiness, "production_release": CharacterProductionReleaseAdapter(scratch_db),
        }

    def _materialize_candidate_gm_authority(
        self,
        run: Mapping[str, Any],
        scratch_db: Database,
        services: Mapping[str, Any],
        *,
        final_plan: Mapping[str, Any] | None,
        authority: Mapping[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Admit one already-approved candidate GM workspace into a scratch DB."""
        if authority is None:
            return None
        result = self.candidate_gm_authoring.materialize_approved_factory_authoring(
            run,
            scratch_db,
            final_plan=final_plan,
            factory_authoring=services.get("factory_authoring"),
            authority=authority,
        )
        if not isinstance(result, Mapping):
            raise FoundryError(
                "CG1_GM_CANDIDATE_APPROVAL_REQUIRED",
                "The approved candidate GM authority could not be materialized for compilation.",
                status_code=409,
            )
        return dict(result)

    @staticmethod
    def _invoke(obj: Any, names: tuple[str,...], *args: Any, **kwargs: Any) -> Any:
        for name in names:
            fn=getattr(obj,name,None)
            if callable(fn):
                try: return fn(*args,**kwargs)
                except TypeError:
                    try: return fn(*args)
                    except TypeError: continue
        raise FoundryError("CG1_REQUIRED_OPERATION_MISSING", f"Required operation is unavailable: {names[0]}.", details={"operations":names})

    @staticmethod
    def _build_character_creation_projection(
        projections: Any,
        stage2: Any,
        project_id: str,
        choice_snapshot: dict[str, Any],
    ) -> Any:
        private_build = getattr(projections, "_build_for_character_creation", None)
        if callable(private_build):
            return private_build(
                project_id,
                stage2_service=stage2,
                choice_snapshot=deepcopy(choice_snapshot),
            )
        return projections.build(
            project_id,
            choice_snapshot=deepcopy(choice_snapshot),
        )

    @staticmethod
    def _capture_character_creation_path_authority(
        stage2: Any,
        delegated_path_ids: Collection[str],
    ) -> Any | None:
        """Capture the private Path proof while the Stage 2 scope is active."""
        if not delegated_path_ids:
            return None
        issuer = getattr(stage2, "_issue_character_creation_path_authority_handoff", None)
        if not callable(issuer):
            raise FoundryError(
                "CG1_PATH_AUTHORITY_HANDOFF_UNAVAILABLE",
                "The private Stage 2 authority required by production clean import is unavailable.",
                status_code=409,
            )
        return issuer()

    @staticmethod
    def _canonicalize_stage2_proposal(proposal: dict[str, Any]) -> dict[str, Any]:
        """Copy the Stage 2 request and canonicalize its one legacy kind alias."""
        normalized = deepcopy(proposal)
        choices = normalized.get("choices")
        if not isinstance(choices, list):
            return normalized
        for choice in choices:
            if isinstance(choice, dict) and choice.get("kind") == "insight_acquisition":
                choice["kind"] = "cultivation_insight_acquisition"
        return normalized

    def _stage2_commit(
        self,
        svc: Any,
        proposal: dict[str, Any],
        owner: str,
        *,
        creation_run: dict[str, Any] | None = None,
        phase: str | None = None,
        delegated_path_ids: Collection[str] | None = None,
        after_commit: Callable[[], Any] | None = None,
        _timing_sink: dict[str, Any] | None = None,
    ) -> tuple[Any, ...]:
        from project_store.service import ensure_project_lock_proof_cache_scope
        from stage2.service import stage2_commit_timing_scope, stage2_compiled_validation_cache_scope

        timing_sink = _timing_sink if isinstance(_timing_sink, dict) else None

        def finish_timing(phase_name: str, started: float) -> None:
            if timing_sink is not None:
                timing_sink[f"stage2.{phase_name}"] = _elapsed_ms(
                    started,
                    time.perf_counter(),
                )

        scope = nullcontext()
        scope_factory = getattr(svc, "_trusted_character_creation_scope", None)
        if creation_run is not None and callable(scope_factory):
            snapshot = creation_run.get("request", {}).get("typed_choice_snapshot") or {}
            if delegated_path_ids is None:
                canonical_intent = creation_run.get("canonical_selection_intent")
                if not isinstance(canonical_intent, dict):
                    parsed_plan = (creation_run.get("response") or {}).get("parsed_plan")
                    canonical_intent = parsed_plan.get("canonical_selection_intent") if isinstance(parsed_plan, dict) else None
                delegated_path_ids = self._delegated_path_ids_from_canonical_intent(canonical_intent)
            scope = scope_factory(
                run_id=creation_run["run_id"],
                project_id=creation_run["project_id"],
                starting_revision=creation_run["starting_revision"],
                content_lock_hash=creation_run["request"]["content_lock_hash"],
                typed_choice_snapshot_sha256=snapshot["snapshot_sha256"],
                request_sha256=creation_run["request"].get("request_sha256"),
                authorized_delegated_path_ids=delegated_path_ids,
                phase=phase,
                candidate_identity=(creation_run.get("dry_run") or {}).get("candidate_identity") if phase == "finalization" else None,
                _server_authority=_TRUSTED_CHARACTER_CREATION_EXECUTION,
            )
        with ensure_project_lock_proof_cache_scope(), stage2_compiled_validation_cache_scope(), scope, stage2_commit_timing_scope(timing_sink):
            phase_started = time.perf_counter()
            stage2_proposal = self._canonicalize_stage2_proposal(proposal)
            # A server-materialized proposal is deliberately rebound to the
            # post-Stage-1 scratch revision here.  The response never authors
            # this value; the active Stage 2 database and frozen content lock
            # do.  Historical full-row callers retain their established
            # proposal binding semantics.
            if creation_run is not None and (
                creation_run.get("canonical_selection_intent")
                or (
                    isinstance((creation_run.get("response") or {}).get("parsed_plan"), dict)
                    and (creation_run.get("response") or {}).get("parsed_plan", {}).get("canonical_selection_intent")
                )
            ):
                with svc.db.connection() as conn:
                    project_row = conn.execute(
                        "SELECT revision,project_json FROM projects WHERE project_id=?",
                        (creation_run["project_id"],),
                    ).fetchone()
                if project_row:
                    project_doc = json.loads(project_row["project_json"] or "{}")
                    stage2_proposal["expected_project_revision"] = int(project_row["revision"])
                    stage2_proposal["expected_content_lock_hash"] = (
                        project_doc.get("content_lock") or {}
                    ).get("lock_hash") or stage2_proposal.get("expected_content_lock_hash")
                    stage2_proposal["target_cl"] = frozen_owner_target_cl(project_doc)
            created=self._invoke(svc,("create_proposal",),stage2_proposal)
            finish_timing("create", phase_started)
            pid=(created or {}).get("proposal_id") if isinstance(created,dict) else created
            phase_started = time.perf_counter()
            validation=self._invoke(svc,("validate_proposal",),pid)
            finish_timing("validate", phase_started)
            if isinstance(validation,dict) and validation.get("valid") is False:
                raise FoundryError("CG1_STAGE2_INVALID","Stage 2 validation rejected the proposed advancement.",details=validation)
            if hasattr(svc,"issue_approval_challenge"):
                phase_started = time.perf_counter()
                issued=svc.issue_approval_challenge(pid)
                finish_timing("challenge", phase_started)
                ch=issued.get("challenge", issued)
                phase_started = time.perf_counter()
                try: svc.approve_proposal(pid, challenge_id=ch.get("challenge_id"), nonce=ch.get("nonce"), approved_by=owner)
                except TypeError:
                    try: svc.approve_proposal(pid, ch.get("challenge_id"), ch.get("nonce"), owner)
                    except TypeError: svc.approve_proposal(pid, approved_by=owner)
                finish_timing("approve", phase_started)
            phase_started = time.perf_counter()
            result=self._invoke(svc,("commit_proposal",),pid)
            finish_timing("commit", phase_started)
            if after_commit is not None:
                phase_started = time.perf_counter()
                projection = after_commit()
                finish_timing("after_commit_projection", phase_started)
                return validation,result,projection
            return validation,result

    @staticmethod
    def _identity_payload(
        value: Any,
        *,
        _context: tuple[str, ...] = (),
        _surface: str | None = None,
    ) -> Any:
        if isinstance(value, dict):
            source = value.get("source")
            if isinstance(source, str) and (
                source.startswith("cg1-delegated-final-grant-plan:")
                or source.startswith("cg1-owner-descriptive:")
            ):
                # Older projects may retain a phase suffix on the same
                # server-derived lock.  The suffix is audit metadata, not
                # character mechanics.
                value = deepcopy(value)
                value["source"] = source.rsplit(":", 1)[0]
                wrapped = value.get("value")
                if isinstance(wrapped, dict) and isinstance(wrapped.get("binding"), dict):
                    wrapped["binding"].pop("phase", None)
            # Only approval/challenge envelopes and explicitly transient
            # process metadata are excluded. Mechanical manifests, package
            # digests, event/state/project hashes, sheet/GM semantics, clean
            # import proofs, and readiness receipts remain identity inputs.
            execution_envelope_fields = set(_IDENTITY_RECEIPT_PROCESS_FIELDS)
            transient_location_fields = {
                "path",
                "artifact_path",
                "package_path",
                "workspace_path",
                "created_at",
                "updated_at",
                "completed_at",
                "phase",
                 "build_manifest_path",
                "candidate_zip",
                "deep_audit_path",
                "gm_model_path",
                "gm_view_model_path",
                "seal_run",
                "harness_run",
                "consumer_root",
                "harness_package_path",
            }
            semantic_context_keys = {
                "identity",
                "mechanics",
                "content",
                "model",
                "stats",
                "cultivation",
                "paths",
                "talents",
                "insights",
                "actions",
                "features",
                "readiness",
            }
            normalized: dict[str, Any] = {}
            folded_context = tuple(str(part).casefold() for part in _context)
            receipt_context = bool(
                set(folded_context) & _IDENTITY_RECEIPT_CONTEXT_NAMES
            )
            for key, item in sorted(value.items()):
                context_keys = {str(part).casefold() for part in _context}
                semantic_context = bool(context_keys & semantic_context_keys)
                key_folded = str(key).casefold()
                root_context = not _context
                identity_path = (*tuple(str(part).casefold() for part in _context), key_folded)
                if receipt_context and (
                    key_folded in _IDENTITY_RECEIPT_PROCESS_FIELDS
                    or key_folded in _IDENTITY_RECEIPT_PROCESS_TIMESTAMP_FIELDS
                    or key_folded in _IDENTITY_RECEIPT_TRANSIENT_PATH_FIELDS
                    or (
                        key_folded in {"mac", "key_id", "domain", "algorithm", "projection_hash"}
                        and bool(set(folded_context) & {"approval_evidence", "integrity"})
                    )
                ):
                    # Stage 2 returns its terminal result as
                    # ``{"receipt": {...}, "project": ..., "replay": ...}``.
                    # These values are excluded only while inside a recognized
                    # receipt envelope.  Do not turn this into a recursive
                    # ``*_hash`` blacklist: event, state, project, source,
                    # package, and model hashes in the same receipt remain
                    # substantive candidate identity.
                    continue
                if key_folded in execution_envelope_fields and root_context and not semantic_context:
                    continue
                if key_folded in transient_location_fields and root_context and not semantic_context:
                    continue
                if identity_path in _IDENTITY_TRANSIENT_PATHS:
                    continue
                if root_context and key_folded in _IDENTITY_SURFACE_ROOT_FIELDS.get(str(_surface or "").casefold(), ()):
                    continue
                if key_folded == "id" and "package_identity" in context_keys:
                    continue
                if key_folded == "selected_id" and ({"consumer", "consumer_report"} & context_keys):
                    continue
                if key_folded in {"created_at", "updated_at", "verified_at"} and root_context:
                    continue
                if key_folded == "source" and isinstance(item, str) and (
                    item.startswith("cg1-delegated-final-grant-plan:")
                    or item.startswith("cg1-owner-descriptive:")
                ):
                    item = item.rsplit(":", 1)[0]
                normalized[key] = CharacterCreationExecutionService._identity_payload(
                    item,
                    _context=(*_context, str(key)),
                    _surface=_surface,
                )
            return normalized
        if isinstance(value, list):
            return [
                CharacterCreationExecutionService._identity_payload(v, _context=_context, _surface=_surface)
                for v in value
            ]
        return value

    @staticmethod
    def _identity_differences(left: Any, right: Any, *, _path: tuple[str, ...] = ()) -> list[dict[str, Any]]:
        if len(_path) > 8:
            return [] if left == right else [{"path": ".".join(_path), "left": left, "right": right}]
        if isinstance(left, dict) and isinstance(right, dict):
            differences: list[dict[str, Any]] = []
            for key in sorted(set(left) | set(right)):
                if key not in left or key not in right:
                    differences.append({"path": ".".join((*_path, str(key))), "left": left.get(key), "right": right.get(key)})
                else:
                    differences.extend(CharacterCreationExecutionService._identity_differences(left[key], right[key], _path=(*_path, str(key))))
                if len(differences) >= 20:
                    return differences[:20]
            return differences
        if isinstance(left, list) and isinstance(right, list):
            differences: list[dict[str, Any]] = []
            for index in range(max(len(left), len(right))):
                if index >= len(left) or index >= len(right):
                    differences.append({"path": ".".join((*_path, str(index))), "left": left[index] if index < len(left) else None, "right": right[index] if index < len(right) else None})
                else:
                    differences.extend(CharacterCreationExecutionService._identity_differences(left[index], right[index], _path=(*_path, str(index))))
                if len(differences) >= 20:
                    return differences[:20]
            return differences
        return [] if left == right else [{"path": ".".join(_path), "left": left, "right": right}]

    @staticmethod
    def _has_delegated_envelope(run: dict[str, Any]) -> bool:
        return bool((run.get("request") or {}).get("delegated_choice_envelope"))

    @staticmethod
    def _creation_training_contract_active(run: dict[str, Any]) -> bool:
        envelope = (run.get("request") or {}).get("delegated_choice_envelope") or {}
        return isinstance(envelope, dict) and isinstance(envelope.get("creation_training_contract"), dict)

    @staticmethod
    def _explicit_forging_contract_active(run: dict[str, Any]) -> bool:
        from character_creation.constructed_arts.explicit_forging import has_explicit_forging_contract
        return has_explicit_forging_contract((run.get("request") or {}).get("delegated_choice_envelope"))

    def _plan_with_accepted_final_target(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        accepted_final_plan: dict[str, Any] | None,
    ) -> dict[str, Any]:
        """Make every compilation surface consume the accepted target CL."""

        if not self._has_delegated_envelope(run) or accepted_final_plan is None:
            return plan
        target_cl = validate_accepted_final_plan_target(
            run,
            self._project(run["project_id"]),
            accepted_final_plan,
        )
        bound = deepcopy(plan)
        bound["target_cl"] = target_cl
        stage2 = bound.get("stage2_proposal")
        if isinstance(stage2, dict):
            stage2["target_cl"] = target_cl
        return bound

    def _derive_delegated_final_grant_plan(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        final_plan: dict[str, Any],
    ) -> dict[str, Any]:
        """Derive the exact canonical grant/accounting plan from accepted response rows."""
        if not self._has_delegated_envelope(run):
            return final_plan
        stage2 = catalog_stage2_selections(plan)
        resolution = final_plan.get("resolution") or {}
        selected_by_slot = resolution.get("selected_choices_by_slot") or {}

        def selected(slot_id: str) -> list[str]:
            return [value for value in selected_by_slot.get(slot_id) or [] if isinstance(value, str)]

        # Planning priorities are deliberately not compared with mechanical
        # rows.  Only the semantic acquisition object is an acquisition
        # representation; Stage 2 is the Factory's derived representation.
        canonical_intent = plan.get("canonical_selection_intent") or {}
        semantic_acquisition = canonical_intent.get("acquisition_intent") if isinstance(canonical_intent, dict) else {}
        semantic_trained_talents = [
            value
            for value in (semantic_acquisition or {}).get("trained_choices") or []
            if isinstance(value, dict)
            and value.get("choice_type") == "known_sphere_talent"
            and isinstance(value.get("record_id"), str)
        ]
        stage2_trained_talents = list(stage2.get("trained_talent_acquisitions") or [])
        if [value.get("record_id") for value in semantic_trained_talents] != [value.get("talent_id") for value in stage2_trained_talents]:
            raise FoundryError(
                "CG1_DELEGATED_CATALOG_REPRESENTATION_MISMATCH",
                "The server-derived trained Talent rows do not equal the semantic creation-training intent.",
                details={
                    "semantic_trained_talent_ids": [value.get("record_id") for value in semantic_trained_talents],
                    "stage2_trained_talent_ids": [value.get("talent_id") for value in stage2_trained_talents],
                },
                status_code=409,
            )
        for semantic_row, stage2_row in zip(semantic_trained_talents, stage2_trained_talents):
            materialized_row = {
                "cl": stage2_row.get("effective_cl"),
                "slot": stage2_row.get("slot"),
                "choice_type": stage2_row.get("choice_type"),
                "source": stage2_row.get("source"),
                "outcome": stage2_row.get("outcome"),
            }
            expected_row = {
                key: semantic_row.get(key)
                for key in ("cl", "slot", "choice_type", "source", "outcome")
            }
            if materialized_row != expected_row:
                raise FoundryError(
                    "CG1_DELEGATED_CATALOG_REPRESENTATION_MISMATCH",
                    "The server-derived trained Talent metadata does not equal the semantic creation-training intent.",
                    details={
                        "talent_id": semantic_row.get("record_id"),
                        "semantic": expected_row,
                        "stage2": materialized_row,
                    },
                    status_code=409,
                )
        envelope = run.get("request", {}).get("delegated_choice_envelope") or {}
        milestone_by_id = {
            row.get("milestone_id"): row
            for row in envelope.get("advancement_choice_milestones") or []
            if isinstance(row, dict) and isinstance(row.get("milestone_id"), str)
        }
        bounded = canonical_intent.get("bounded_choices") if isinstance(canonical_intent, dict) else {}
        bounded = bounded if isinstance(bounded, dict) else {}
        progression_by_cl = bounded.get("path_progression_by_cl") or {}

        def milestone_is_acquired(occurrence: dict[str, Any]) -> bool:
            milestone = milestone_by_id.get(occurrence.get("milestone_id"))
            if not isinstance(milestone, dict):
                # The semantic validator already rejects an unknown milestone;
                # leave this defensive case acquisitive so it produces the
                # established representation error instead of silently
                # dropping an unbound value.
                return True
            cl = milestone.get("cl")
            selected_path = (
                progression_by_cl.get(str(cl), progression_by_cl.get(cl))
                if isinstance(progression_by_cl, dict)
                else None
            )
            path_id = milestone.get("path_id")
            if isinstance(selected_path, str) and isinstance(path_id, str):
                return selected_path == path_id
            return True

        semantic_occurrences = [
            value
            for value in (semantic_acquisition or {}).get("insight_occurrences") or []
            if isinstance(value, dict) and isinstance(value.get("insight_id"), str)
        ]
        planning_only_insights = [
            deepcopy(value)
            for value in semantic_occurrences
            if not milestone_is_acquired(value)
        ]
        requested_insights = [
            value.get("insight_id")
            for value in semantic_occurrences
            if milestone_is_acquired(value)
        ]
        if requested_insights != list(stage2["insight_ids"]):
            raise FoundryError(
                "CG1_DELEGATED_CATALOG_REPRESENTATION_MISMATCH",
                "The server-derived Stage 2 Insight occurrences do not equal the semantic Insight acquisition intent.",
                details={
                    "requested_insight_ids": requested_insights,
                    "stage2_insight_ids": list(stage2["insight_ids"]),
                    "stage2_insight_occurrences": deepcopy(stage2["insight_occurrences"]),
                    "planning_only_insight_occurrences": planning_only_insights,
                },
                status_code=409,
            )
        if planning_only_insights:
            final_plan["response_reconciliation"] = {
                "schema": "TianxiaFoundry.ResponseReconciliation.v1",
                "planning_only_insight_occurrences": planning_only_insights,
                "reason": "The response proposed a source-backed Insight for a Path that was not selected for progression at that CL; it remains visible as planning intent and is not acquired.",
            }
        sphere_ids = list(stage2["sphere_ids"])
        free_talent_ids = list(stage2["free_sphere_talent_ids"])
        ordinary_talent_ids = list(stage2["ordinary_talent_ids"])
        trained_talent_ids = list(stage2.get("trained_talent_ids") or [])
        if len(sphere_ids) != len(set(sphere_ids)) or len(free_talent_ids) != len(set(free_talent_ids)) or len(ordinary_talent_ids) != len(set(ordinary_talent_ids)):
            raise FoundryError(
                "CG1_DELEGATED_DUPLICATE_CHOICE",
                "The accepted delegated catalog response repeats a canonical acquisition.",
                details={"sphere_ids": sphere_ids, "free_sphere_talent_ids": free_talent_ids, "ordinary_talent_ids": ordinary_talent_ids},
                status_code=409,
            )
        catalog = CanonicalCatalogAuthorityService(self.db.settings.root_dir)
        free_by_sphere: dict[str, str] = {}
        for talent_id in free_talent_ids:
            talent = catalog.get_talent(talent_id)
            sphere_id = talent.get("owning_canonical_sphere_id")
            if not isinstance(sphere_id, str) or sphere_id not in sphere_ids:
                raise FoundryError(
                    "CG1_DELEGATED_FREE_TALENT_SPHERE_MISMATCH",
                    "Every accepted free Sphere Talent must belong to an accepted Sphere grant.",
                    details={"talent_id": talent_id, "owning_sphere_id": sphere_id, "sphere_ids": sphere_ids},
                    status_code=409,
                )
            if sphere_id in free_by_sphere:
                raise FoundryError(
                    "CG1_DELEGATED_DUPLICATE_CHOICE",
                    "A Sphere received more than one accepted free Talent grant.",
                    details={"sphere_id": sphere_id, "talent_ids": [free_by_sphere[sphere_id], talent_id]},
                    status_code=409,
                )
            free_by_sphere[sphere_id] = talent_id
        # The generic CAT3 projection requires explicit structural authority
        # IDs because callers may be resolving a standalone acquisition.  In
        # the bound owner-creation route, derive only the source-declared
        # Sphere-scoped structural authorities carried by the selected
        # Talent records; unrelated feature/secret authorities remain
        # fail-closed and cannot be invented by the response.
        structural_authority_ids: set[str] = set()
        background_canonical_sphere_ids: list[str] = []
        background_canonical_talent_ids: list[str] = []
        package_selection = dict(selected_by_slot) if isinstance(selected_by_slot, Mapping) else {}
        package_selection["background_sphere_choice"] = list(stage2["background_sphere_ids"])
        package_selection["background_talent_choice"] = list(stage2["background_talent_ids"])
        try:
            canonical_background_ids = canonical_selected_background_sphere_ids(
                package_selection,
                envelope.get("choices_by_slot"),
                envelope.get("typed_choice_authority_by_slot"),
            )
        except SealedBackgroundSphereResolutionError as exc:
            raise FoundryError(
                "CG1_TRAINED_CHOICE_BACKGROUND_SPHERE_INVALID",
                "The selected Background Sphere cannot be resolved to one canonical sealed Sphere.",
                details={
                    "background_sphere_id": exc.background_sphere_id,
                    "reason": exc.reason,
                    "display_name": exc.display_name,
                    "candidate_ids": exc.candidate_ids,
                },
                status_code=409,
            ) from exc
        for resolved_sphere in canonical_background_ids.values():
            if resolved_sphere not in background_canonical_sphere_ids:
                background_canonical_sphere_ids.append(resolved_sphere)
        # Background Talent rows remain source aliases in Stage 2.  Add a
        # canonical held Talent only when the exact Stage 2 Background grant
        # is linked by the sealed selected-package relation.  This supplies
        # prerequisite context to CAT3 without turning the Background grant
        # into an ordinary or constructed acquisition.
        _package_spheres, package_talents = canonical_background_package_ids(
            package_selection,
            envelope.get("typed_choice_authority_by_slot"),
        )
        for resolved_talent in sorted(package_talents):
            if resolved_talent not in background_canonical_talent_ids:
                background_canonical_talent_ids.append(resolved_talent)
        acquired_spheres = set(sphere_ids) | set(background_canonical_sphere_ids)
        # Keep this legacy structural-authority derivation limited to the
        # ordinary/free routes.  A trained Talent is already validated by CAT3
        # against its source-backed acquisition context; its namespace spelling
        # must not manufacture a structural authority.
        for talent_id in [*free_talent_ids, *ordinary_talent_ids]:
            talent = catalog.get_talent(talent_id)
            owning_sphere = talent.get("owning_canonical_sphere_id")
            if not isinstance(owning_sphere, str) or owning_sphere not in acquired_spheres:
                continue
            sphere_slug = owning_sphere.rsplit(".", 1)[-1]
            for prerequisite in talent.get("typed_prerequisites") or []:
                if not isinstance(prerequisite, dict) or prerequisite.get("kind") != "structural_authority":
                    continue
                target_id = prerequisite.get("target_id")
                if (
                    isinstance(target_id, str)
                    and target_id.startswith("tianxia.structural.")
                    and f".{sphere_slug}." in target_id
                ):
                    structural_authority_ids.add(target_id)
        try:
            # Background Sphere/Talent choices remain on the separately
            # authenticated Background route.  The CAT3 grant plan is limited
            # to ordinary canonical Sphere/Talent acquisitions.
            grant_plan = catalog.validate_grant_plan_for_initial_creation(
                target_cl=final_plan["target_cl"],
                acquired_sphere_ids=sphere_ids,
                background_sphere_ids=background_canonical_sphere_ids,
                free_talent_grants=free_by_sphere,
                ordinary_talent_ids=ordinary_talent_ids,
                trained_talent_acquisitions=stage2_trained_talents,
                existing_talent_ids=background_canonical_talent_ids,
                path_ids=resolution.get("actual_advancing_path_ids") or [],
                subpath_or_tradition_ids=stage2["subpath_or_tradition_ids"] or selected("subpath_choice"),
                method_ids=[resolution["method_id"]] if resolution.get("method_id") else [],
                foundation_or_feature_ids=[resolution["foundation_id"]] if resolution.get("foundation_id") else [],
                structural_authority_ids=sorted(structural_authority_ids),
            )
        except FoundryError:
            raise
        final_plan["canonical_grant_plan"] = grant_plan
        final_plan["canonical_grant_plan_sha256"] = sha256_json(grant_plan)
        catalog_response_authority = {
            "target_cl": final_plan["target_cl"],
            "stage2_mechanical_choices": deepcopy(stage2),
            "accepted_sphere_ids": deepcopy(sphere_ids),
            "accepted_free_sphere_talent_ids": deepcopy(free_talent_ids),
            "accepted_ordinary_talent_ids": deepcopy(ordinary_talent_ids),
            "accepted_insight_ids": deepcopy(stage2["insight_ids"]),
            "accepted_insight_occurrences": deepcopy(stage2["insight_occurrences"]),
            "accepted_background_sphere_ids": deepcopy(stage2["background_sphere_ids"]),
            "accepted_background_canonical_sphere_ids": deepcopy(background_canonical_sphere_ids),
            "accepted_background_talent_ids": deepcopy(stage2["background_talent_ids"]),
            "accepted_background_canonical_talent_ids": deepcopy(background_canonical_talent_ids),
            "accepted_path_ids": deepcopy(resolution.get("actual_advancing_path_ids") or []),
            "accepted_method_id": resolution.get("method_id"),
            "accepted_foundation_id": resolution.get("foundation_id"),
            "derived_structural_authority_ids": sorted(structural_authority_ids),
            "grant_plan_provenance": deepcopy(grant_plan.get("selected_talent_dispositions") or []),
        }
        if trained_talent_ids:
            catalog_response_authority["accepted_trained_talent_ids"] = deepcopy(trained_talent_ids)
            catalog_response_authority["accepted_trained_talent_acquisitions"] = deepcopy(stage2_trained_talents)
        final_plan["catalog_response_authority"] = catalog_response_authority
        final_plan["response_representations"] = response_authority_representations(plan)
        canonical_intent = plan.get("canonical_selection_intent")
        if isinstance(canonical_intent, dict):
            final_plan["canonical_selection_intent"] = deepcopy(canonical_intent)
            final_plan["canonical_intent_hash"] = canonical_intent.get("intent_sha256")
            final_plan["submitted_plan_sha256"] = sha256_json(plan)
            final_plan["materialized_stage2_sha256"] = sha256_json(plan.get("stage2_proposal") or {})
            final_plan["materialization_receipt"] = deepcopy(plan.get("materialization_receipt") or {})
        final_plan["final_plan_sha256"] = final_plan_sha256(final_plan)
        return final_plan

    def _materialize_delegated_final_grant_plan(
        self,
        run: dict[str, Any],
        final_plan: dict[str, Any],
        authority_db: Database,
        *,
        phase: str,
    ) -> dict[str, Any] | None:
        if not self._has_delegated_envelope(run):
            return None
        from project_store.service import ProjectStore
        store = self.projects if authority_db is self.db else ProjectStore(authority_db)
        project_result = store.get_project(run["project_id"])
        project = deepcopy(project_result.get("project") or project_result)
        validate_accepted_final_plan_target(
            run,
            project,
            final_plan,
        )
        grant_plan = deepcopy(final_plan.get("canonical_grant_plan"))
        if not isinstance(grant_plan, dict) or grant_plan.get("schema") != "TianxiaFactory.CanonicalGrantPlan.v1":
            raise FoundryError(
                "CG1_CANONICAL_GRANT_PLAN_LOCK_MISSING",
                "Delegated compilation requires the server-derived canonical final grant plan.",
                status_code=409,
            )
        store.materialize_server_derived_user_lock(
            run["project_id"],
            field=DELEGATED_FINAL_CATALOG_GRANT_FIELD,
            value=grant_plan,
            # The lock is part of the reviewed mechanical snapshot.  Scratch
            # compilation and finalization must therefore persist identical
            # semantic bytes; the server phase is already bound by the caller's
            # sealed authority context and is not copied into the project lock.
            source=f"cg1-delegated-final-grant-plan:{sha256_json(grant_plan)}:server-derived",
            lock_id="lock.cg1.delegated-final-grant-plan",
        )
        return grant_plan

    def _prepare_scratch_compilation_run(
        self,
        run: dict[str, Any],
        scratch_db: Database,
        *,
        scratch_root: Path,
    ) -> None:
        """Enter compilation in the disposable copy without rewriting live history.

        Retried candidates are copied with their prior review status. Evidence
        issuance must see the new scratch compilation phase, while the live run
        retains its prior result until this compilation produces a new result.
        """
        source_path = self.db.settings.db_path.resolve()
        scratch_path = scratch_db.settings.db_path.resolve()
        root = scratch_root.resolve()
        if (
            scratch_db is self.db
            or not scratch_path.is_relative_to(root)
            or source_path.is_relative_to(root)
            or scratch_path == source_path
            or scratch_path.samefile(source_path)
        ):
            raise FoundryError(
                "CG1_SCRATCH_RUN_CONTEXT_INVALID",
                "Compilation phase transitions require an isolated disposable database.",
                status_code=409,
            )
        with scratch_db.transaction() as conn:
            row = conn.execute(
                "SELECT * FROM character_creation_runs WHERE run_id=? AND project_id=?",
                (run.get("run_id"), run.get("project_id")),
            ).fetchone()
            # Accepting the proposed name/concept, replacing a response and
            # applying a bound owner decision are steps of an active run; only
            # a terminal or unknown decision makes the copied run unusable.
            if (
                row is None
                or row["status"] not in {
                    "PREPARING_REQUEST", "WAITING_FOR_RESPONSE", "READY_FOR_REVIEW", "NEEDS_REVIEW",
                }
                or row["owner_decision"] not in _ACTIVE_RUN_OWNER_DECISIONS
                or row["completed_at"] is not None
                or row["starting_revision"] != run.get("starting_revision")
                or json.loads(row["request_json"]) != run.get("request")
            ):
                raise FoundryError(
                    "CG1_SCRATCH_RUN_CONTEXT_INVALID",
                    "Compilation requires the exact active copied creation request.",
                    status_code=409,
                )
            conn.execute(
                "UPDATE character_creation_runs SET status='PREPARING_REQUEST' WHERE run_id=? AND project_id=?",
                (run["run_id"], run["project_id"]),
            )

    def _compile_once(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        index: int,
        *,
        prior_attempt_id: str | None = None,
        accepted_final_plan: dict[str, Any] | None = None,
        final_plan: dict[str, Any] | None = None,
        candidate_gm_authority: Mapping[str, Any] | None = None,
        _timing_sink: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        compile_timings: dict[str, Any] = (
            _timing_sink if isinstance(_timing_sink, dict) else {}
        )

        def finish_timing(phase: str, started: float) -> None:
            compile_timings[phase] = _elapsed_ms(started, time.perf_counter())

        compile_plan = self._plan_with_accepted_final_target(run, plan, accepted_final_plan)
        compile_plan = self._execution_descriptive_fields(run, compile_plan)
        choice_snapshot = self._require_frozen_choice_snapshot(run)
        with tempfile.TemporaryDirectory(prefix=f"cg1-scratch-{index}-", ignore_cleanup_errors=True) as td:
            root=Path(td); data=root/"data"
            phase_started = time.perf_counter()
            self._snapshot_data(data, hash_tree=False)
            self._snapshot_external_security(data)
            finish_timing("snapshot_copy_hash", phase_started)
            s=self.db.settings
            settings=Settings(root_dir=s.root_dir,data_dir=data,db_path=data/s.db_path.name,inbox_dir=data/"inbox",exports_dir=data/"exports",packs_dir=data/"content_packs",vendor_dir=data/"vendor",logs_dir=data/"logs",backups_dir=data/"backups",security_dir=data/"security",factory_zip=s.factory_zip,fixture_path=s.fixture_path)
            phase_started = time.perf_counter()
            scratch_db=Database(settings); scratch_db.migrate()
            self._prepare_scratch_compilation_run(run, scratch_db, scratch_root=root)
            services=self._scratch_services(scratch_db)
            finish_timing("scratch_db_migrate_service_creation", phase_started)
            phase_started = time.perf_counter()
            self._materialize_descriptive_fields(run, compile_plan, scratch_db, phase="scratch_compile")
            self._materialize_delegated_final_grant_plan(
                run,
                accepted_final_plan or {},
                scratch_db,
                phase="scratch_compile",
            )
            finish_timing("descriptive_grant_materialization", phase_started)
            stage1=services["stage1"]
            s1=compile_plan["stage1_response"]; text=s1 if isinstance(s1,str) else canonical_json(s1)
            phase_started = time.perf_counter()
            attempt=stage1.validate_response(
                run["request"]["stage1_prompt"]["prompt_id"],
                text,
                prior_attempt_id=self._stage1_prior_attempt_id(
                    scratch_db,
                    run["request"]["stage1_prompt"].get("prompt_id"),
                    prior_attempt_id,
                ),
            )
            v=attempt.get("validation") or {}
            if v.get("valid") is False or v.get("errors") or v.get("blockers"):
                raise FoundryError("CG1_STAGE1_INVALID","Stage 1 validation rejected the plan.",details=v)
            stage1_commit=stage1.approve_and_commit(attempt.get("attempt_id"),self.owner_principal)
            finish_timing("stage1_validate_commit", phase_started)
            phase_started = time.perf_counter()
            method_access_receipt = self._materialize_method_hard_lock(
                run,
                scratch_db,
                phase="scratch_compile",
                plan=compile_plan,
            )
            finish_timing("method_lock", phase_started)
            phase_started = time.perf_counter()
            constructed_arts_receipt = self._materialize_constructed_arts(
                run,
                scratch_db,
                phase="scratch_compile",
                plan=compile_plan,
            )
            finish_timing("constructed_arts", phase_started)
            delegated_path_ids = self._delegated_path_ids_from_canonical_intent(
                compile_plan.get("canonical_selection_intent"),
            )
            path_authority_handoff: dict[str, Any] = {}
            def build_scratch_projection_inside_stage2_scope() -> Any:
                self._issue_initial_catalog_provenance(
                    run,
                    frozen_snapshot=choice_snapshot,
                    phase="scratch_compile",
                    authority_db=scratch_db,
                    _finalization_authority=_SERVER_SCRATCH_COMPILATION_AUTHORITY,
                    accepted_final_plan=accepted_final_plan,
                )
                projection = self._build_character_creation_projection(
                    services["projections"],
                    services["stage2"],
                    run["project_id"],
                    choice_snapshot,
                )
                if services.get("production_release") is not None:
                    path_authority_handoff["value"] = self._capture_character_creation_path_authority(
                        services["stage2"],
                        delegated_path_ids,
                    )
                return projection

            phase_started = time.perf_counter()
            stage2_validation,stage2_commit,projection=self._stage2_commit(
                services["stage2"], deepcopy(compile_plan["stage2_proposal"]), self.owner_principal,
                creation_run=run, phase="scratch_compile",
                delegated_path_ids=delegated_path_ids,
                after_commit=build_scratch_projection_inside_stage2_scope,
                _timing_sink=compile_timings,
            )
            finish_timing("stage2_commit_projection", phase_started)
            phase_started = time.perf_counter()
            sheet=self._invoke(services["character_sheets"],("build","build_sheet","sheet","current"),run["project_id"])
            finish_timing("character_sheet_build", phase_started)
            candidate_capsule = None
            if services.get("production_release") is not None:
                # Compare the approved workspace with the reproduced
                # post-Stage-2 project immediately before release admission.
                self._materialize_candidate_gm_authority(
                    run,
                    scratch_db,
                    services,
                    final_plan=final_plan,
                    authority=candidate_gm_authority,
                )

                def capture_candidate_workspace(factory_authoring: Mapping[str, Any]) -> None:
                    nonlocal candidate_capsule
                    phase_started = time.perf_counter()
                    candidate_capsule = self.candidate_gm.capture(
                        run=run,
                        root_db=self.db,
                        scratch_db=scratch_db,
                        scratch_root=root,
                        sheet=sheet,
                        projection=projection,
                        stage2_validation=stage2_validation,
                        stage2_commit=stage2_commit,
                        stage2_service=services.get("stage2"),
                        final_plan=final_plan,
                        factory_authoring=factory_authoring,
                    )
                    finish_timing("gm_candidate_context_capture", phase_started)

                release_kwargs = {
                    "output_root": root / "release",
                    "register": False,
                    "output_profile": deepcopy(compile_plan.get("output_profile") or {}),
                    "_candidate_authoring_callback": capture_candidate_workspace,
                    "_timing_sink": compile_timings,
                }
                if path_authority_handoff.get("value") is not None:
                    release_kwargs["_character_creation_path_authority"] = path_authority_handoff["value"]
                phase_started = time.perf_counter()
                try:
                    release=services["production_release"].compile(
                        run["project_id"],
                        **release_kwargs,
                    )
                except FoundryError as exc:
                    if candidate_capsule is None:
                        raise
                    if isinstance(exc.details, dict):
                        details = deepcopy(exc.details)
                    else:
                        details = {"original_details": deepcopy(exc.details)}
                    details["gm_candidate_capsule"] = deepcopy(candidate_capsule)
                    raise FoundryError(
                        exc.code,
                        exc.message,
                        details=details,
                        status_code=exc.status_code,
                    ) from exc
                finish_timing("production_release", phase_started)
                authoring=release["factory_authoring"]
                gm=release["command5"]
                gm_result=release["consumer"]
                portable={"package_sha256": release["portable_audit"].get("sha256"), "audit": release["portable_audit"], "clean_import": release["clean_import"], "release_identity": release["production_artifact_identity"]}
                stable_release=services["production_release"]._stable(release)
            else:
                authoring=self._invoke(services["factory_authoring"],("build",),run["project_id"])
                gm=self._invoke(services["gm_exports"],("export",),run["project_id"])
                gm_result=self._invoke(services["gm_consumer"],("verify","consume","import_package"),gm)
                portable=self._invoke(services["portable_characters"],("build_for_project","build_verified","export","verified_status"),run["project_id"])
            combat=None
            if bool((compile_plan.get("output_profile") or {}).get("combat_ready")):
                phase_started = time.perf_counter()
                if services.get("production_release") is not None:
                    combat = _production_release_combat_receipt(release)
                else:
                    combat=self._invoke(services["combat_readiness"],("compile","build","verify"),run["project_id"])
                finish_timing("optional_combat", phase_started)
            phase_started = time.perf_counter()
            artifacts={"stage1":stage1_commit,"stage2_validation":stage2_validation,"stage2":stage2_commit,"method_access":method_access_receipt,"constructed_arts":constructed_arts_receipt,"ledger":projection,"projection":projection,"character_sheet":sheet,"factory_authoring":authoring,"gm_model":gm,"gm_consumer":gm_result,"portable_character":portable,"combat":combat}
            identity_artifacts=artifacts
            if services.get("production_release") is not None:
                identity_artifacts={
                    **artifacts,
                    "factory_authoring":stable_release["factory_authoring"],
                    "gm_model":stable_release["command5"],
                    "gm_consumer":stable_release["consumer"],
                    "portable_character":{
                        "package_sha256":stable_release["portable_audit"].get("sha256"),
                        "audit":stable_release["portable_audit"],
                        "clean_import":stable_release["clean_import"],
                        "release_identity":release["production_artifact_identity"],
                    },
                }
            identities={k:sha256_json(self._identity_payload(v, _surface=k)) for k,v in identity_artifacts.items() if v is not None}
            preview={"identity":deepcopy(compile_plan.get("owner_descriptive_fields") or {}),"target_cl":compile_plan.get("target_cl"),"compiled":deepcopy(artifacts),"readiness":{k:{"service":k,"identity":identities.get(k),"verification_status":"VERIFIED","receipt":deepcopy(artifacts.get(k))} for k in REQUIRED_SURFACES},"uncertainties":deepcopy(compile_plan.get("uncertainties") or []),"fallbacks":deepcopy(compile_plan.get("fallbacks") or [])}
            if combat is not None: preview["readiness"]["combat"]={"service":"combat_readiness","identity":identities["combat"],"verification_status":"VERIFIED","receipt":deepcopy(combat)}
            candidate_identity=sha256_json({"plan_sha256":sha256_json(compile_plan),"typed_choice_snapshot_sha256":choice_snapshot["snapshot_sha256"],"identities":identities})
            finish_timing("identity_preview_construction", phase_started)
            return {
                "schema":"TianxiaFoundry.CompiledCharacterCandidate.v3",
                "candidate_identity":candidate_identity,
                "typed_choice_snapshot":deepcopy(choice_snapshot),
                "identities":identities,
                "preview":preview,
                "artifacts":artifacts,
                "_timings": _compile_timing_receipt(compile_timings),
            }

    def _compile_checkpoint_path(self, run: dict[str, Any]) -> Path | None:
        """Return the private diagnostic sidecar path for one creation run."""
        settings = getattr(getattr(self, "db", None), "settings", None)
        data_dir = getattr(settings, "data_dir", None)
        run_id = run.get("run_id") if isinstance(run, dict) else None
        if not isinstance(run_id, str) or not run_id:
            return None
        if isinstance(data_dir, Path):
            base = data_dir
        elif isinstance(data_dir, str) and data_dir:
            base = Path(data_dir)
        else:
            return None
        # The run id is never used as a path component.  A stable digest also
        # keeps the sidecar name bounded if a caller supplies an oversized id.
        filename = f"{sha256_bytes(run_id.encode('utf-8'))[:32]}.jsonl"
        return base / "diagnostics" / "character_creation" / filename

    def _write_compile_checkpoint(
        self,
        run: dict[str, Any],
        *,
        phase: str,
        status: str,
        compile_index: int | None = None,
        elapsed_ms: int | float | None = None,
        timing_phases_ms: Mapping[str, Any] | None = None,
        candidate_identity: str | None = None,
        error_code: str | None = None,
    ) -> None:
        """Append bounded identifier/numeric compile diagnostics best-effort.

        This sidecar is intentionally outside the candidate, receipt, and
        identity payloads.  Failure to write diagnostics must never change the
        compilation result.
        """
        path = self._compile_checkpoint_path(run)
        if path is None:
            return

        def safe_identifier(value: Any, limit: int) -> str | None:
            if not isinstance(value, str):
                return None
            safe = "".join(
                char if char.isascii() and (char.isalnum() or char in "._-") else "_"
                for char in value
            )
            return safe[:limit] or None

        run_id = run.get("run_id") if isinstance(run, dict) else None
        record: dict[str, Any] = {
            "schema": _COMPILE_CHECKPOINT_SCHEMA,
            "run_id": safe_identifier(run_id, 128),
            "phase": safe_identifier(phase, 64),
            "status": safe_identifier(status, 32),
        }
        if isinstance(compile_index, int) and not isinstance(compile_index, bool) and 1 <= compile_index <= 2:
            record["compile_index"] = compile_index
        safe_elapsed = _safe_timing_number(elapsed_ms)
        if safe_elapsed is not None:
            record["elapsed_ms"] = safe_elapsed
        safe_timing_phases: dict[str, int | float] = {}
        if isinstance(timing_phases_ms, Mapping):
            for phase_name, phase_value in timing_phases_ms.items():
                if not isinstance(phase_name, str) or phase_name not in _COMPILE_TIMING_PHASE_ALLOWLIST:
                    continue
                safe_value = _safe_timing_number(phase_value)
                if safe_value is not None:
                    safe_timing_phases[phase_name] = safe_value
        if safe_timing_phases:
            record["timing_phases_ms"] = safe_timing_phases
        safe_candidate_identity = safe_identifier(candidate_identity, 128)
        if safe_candidate_identity is not None:
            record["candidate_identity"] = safe_candidate_identity
        safe_error_code = safe_identifier(error_code, 96)
        if safe_error_code is not None:
            record["error_code"] = safe_error_code
        try:
            line = (canonical_json(record) + "\n").encode("utf-8")
            if len(line) > _COMPILE_CHECKPOINT_MAX_BYTES:
                return
            path.parent.mkdir(parents=True, exist_ok=True)
            # Binary append keeps each bounded record one write, then flushes
            # and fsyncs it so a process termination leaves a useful prefix.
            with path.open("ab") as handle:
                handle.write(line)
                handle.flush()
                os.fsync(handle.fileno())
        except OSError:
            return

    def _compile_twice(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        *,
        prior_attempt_id: str | None = None,
        accepted_final_plan: dict[str, Any] | None = None,
        final_plan: dict[str, Any] | None = None,
        candidate_gm_authority: Mapping[str, Any] | None = None,
        compilations: int = 2,
        reuse_first: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Compile the candidate in isolation twice and require equal identities.

        ``compilations=1`` (walk completion only) stops after the first build
        and marks the candidate ``independent_compilations: 1``; the second,
        independent build then runs where it is needed: in the GM retry (a
        full pair) or at finalize (``reuse_first`` = the stored first build,
        so only compile 2 runs and must reproduce its identities).  Nothing
        is finalized without two matching builds.
        """
        if compilations not in (1, 2) or (reuse_first is not None and compilations != 2):
            raise FoundryError("CG1_COMPILATION_COUNT_INVALID", "A candidate is compiled once (deferred) or proven twice.")
        with deterministic_replay(run["created_at"], run["request"]["request_sha256"]):
            return self._compile_twice_in_replay(
                run, plan, prior_attempt_id=prior_attempt_id,
                accepted_final_plan=accepted_final_plan, final_plan=final_plan,
                candidate_gm_authority=candidate_gm_authority,
                compilations=compilations, reuse_first=reuse_first,
            )

    def _compile_twice_in_replay(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        *,
        prior_attempt_id: str | None,
        accepted_final_plan: dict[str, Any] | None,
        final_plan: dict[str, Any] | None,
        candidate_gm_authority: Mapping[str, Any] | None,
        compilations: int,
        reuse_first: Mapping[str, Any] | None,
    ) -> dict[str, Any]:
        self._write_compile_checkpoint(run, phase="compile_twice", status="started")
        # Declared before the guarded block: a failure while resolving the
        # candidate authority must report its own diagnostic, not an
        # UnboundLocalError from the checkpoint writer in ``except``.
        active_compile_index: int | None = None
        active_compile_started: float | None = None
        active_compile_timings: dict[str, Any] | None = None
        # Two acceptance-app cores (2026-09-10 PID 1938122, 2026-09-11 PID
        # 2394503) segfaulted inside the cyclic collector's dict traversal
        # during these long compiles.  Reference counting still frees the
        # compile's transient objects; only automatic cycle collection is
        # paused for the duration, then restored in ``finally``.
        automatic_gc_was_enabled = gc.isenabled()
        gc.disable()
        try:
            if candidate_gm_authority is None:
                candidate_gm_authority = self.candidate_gm_authoring.candidate_compilation_authority(
                    run,
                    final_plan=final_plan,
                )
            compile_1_timings: dict[str, Any] = {}
            compile_2_timings: dict[str, Any] = {}
            compile_1_kwargs = {
                "prior_attempt_id": prior_attempt_id,
                "_timing_sink": compile_1_timings,
            }
            compile_2_kwargs = {
                "prior_attempt_id": prior_attempt_id,
                "_timing_sink": compile_2_timings,
            }
            if accepted_final_plan is not None:
                compile_1_kwargs["accepted_final_plan"] = accepted_final_plan
                compile_2_kwargs["accepted_final_plan"] = accepted_final_plan
            if final_plan is not None:
                compile_1_kwargs["final_plan"] = final_plan
                compile_2_kwargs["final_plan"] = final_plan
            if candidate_gm_authority is not None:
                compile_1_kwargs["candidate_gm_authority"] = candidate_gm_authority
                compile_2_kwargs["candidate_gm_authority"] = candidate_gm_authority
            rebound_plan = self._plan_with_accepted_final_target(
                run,
                plan,
                accepted_final_plan,
            )
            first_plan = deepcopy(rebound_plan)
            second_plan = deepcopy(rebound_plan)
            rebound_plan_sha256 = sha256_json(rebound_plan)
            first_plan_sha256 = sha256_json(first_plan)
            second_plan_sha256 = sha256_json(second_plan)
            if first_plan_sha256 != rebound_plan_sha256 or second_plan_sha256 != rebound_plan_sha256:
                raise FoundryError(
                    "CG1_NONDETERMINISTIC_COMPILATION",
                    "The central scratch-compilation plan rebind was not canonical.",
                    details={
                        "rebound_plan_sha256": rebound_plan_sha256,
                        "first_plan_sha256": first_plan_sha256,
                        "second_plan_sha256": second_plan_sha256,
                    },
                )
            if reuse_first is not None:
                # The first independent build already ran at walk completion
                # and was reviewed; only the second build runs now.
                a = deepcopy(dict(reuse_first))
                a.pop("_timings", None)
                compile_1_ms = 0
                first_candidate_identity = a["candidate_identity"]
                first_identities = deepcopy(a["identities"])
                first_timing_receipt = None
            else:
                active_compile_index = 1
                active_compile_started = time.perf_counter()
                active_compile_timings = compile_1_timings
                self._write_compile_checkpoint(run, phase="compile_1", status="started", compile_index=1)
                a=self._compile_once(run, first_plan, 1, **compile_1_kwargs)
                compile_1_ms = _elapsed_ms(active_compile_started, time.perf_counter())
                active_compile_index = None
                active_compile_started = None
                active_compile_timings = None
                first_candidate_identity = a["candidate_identity"]
                first_identities = deepcopy(a["identities"])
                first_timing_receipt = deepcopy(a.get("_timings"))
                # Release the first build's duplicate presentation graph before
                # starting the independent second build.  Canonical artifacts and
                # all identity inputs remain intact in ``a``.
                a = self._compact_candidate_for_persistence(a)
                self._write_compile_checkpoint(
                    run,
                    phase="compile_1",
                    status="complete",
                    compile_index=1,
                    elapsed_ms=compile_1_ms,
                    candidate_identity=first_candidate_identity,
                )
            if compilations == 1:
                b = None
                raise _DeferSecondCompilation
            active_compile_index = 2
            active_compile_started = time.perf_counter()
            active_compile_timings = compile_2_timings
            self._write_compile_checkpoint(run, phase="compile_2", status="started", compile_index=2)
            b=self._compile_once(run, second_plan, 2, **compile_2_kwargs)
            compile_2_ms = _elapsed_ms(active_compile_started, time.perf_counter())
            active_compile_index = None
            active_compile_started = None
            active_compile_timings = None
            self._write_compile_checkpoint(
                run,
                phase="compile_2",
                status="complete",
                compile_index=2,
                elapsed_ms=compile_2_ms,
                candidate_identity=b.get("candidate_identity") if isinstance(b, dict) else None,
            )
        except _DeferSecondCompilation:
            pass
        except Exception as exc:
            failed_elapsed_ms = (
                _elapsed_ms(active_compile_started, time.perf_counter())
                if isinstance(active_compile_started, (int, float))
                else None
            )
            self._write_compile_checkpoint(
                run,
                phase="compile_twice",
                status="failed",
                compile_index=active_compile_index,
                elapsed_ms=failed_elapsed_ms,
                timing_phases_ms=active_compile_timings,
                error_code=getattr(exc, "code", type(exc).__name__),
            )
            raise
        finally:
            if automatic_gc_was_enabled:
                gc.enable()
        if compilations == 1:
            single_phases: dict[str, Any] = {"factory_compile_1": compile_1_ms}
            phase_values = first_timing_receipt.get("phases_ms") if isinstance(first_timing_receipt, dict) else None
            if isinstance(phase_values, dict):
                for phase, value in phase_values.items():
                    single_phases[f"factory_compile_1.{phase}"] = value
            self._write_compile_checkpoint(
                run,
                phase="compile_once_deferred",
                status="complete",
                elapsed_ms=compile_1_ms,
                candidate_identity=first_candidate_identity,
            )
            return {
                **a,
                "schema": DRY_RUN_SCHEMA,
                # Not yet proven: the independent second build runs in the GM
                # retry or at finalize before any live write.
                "deterministic": None,
                "independent_compilations": 1,
                "_timings": _timing_receipt(phases_ms=single_phases),
            }
        if first_candidate_identity != b["candidate_identity"] or first_identities != b["identities"]:
            first_identity_payload = {
                key: self._identity_payload(value, _surface=key)
                for key, value in (a.get("artifacts") or {}).items()
                if value is not None
            }
            second_identity_payload = {
                key: self._identity_payload(value, _surface=key)
                for key, value in (b.get("artifacts") or {}).items()
                if value is not None
            }
            self._write_compile_checkpoint(
                run,
                phase="identity_compare",
                status="failed",
                error_code="CG1_NONDETERMINISTIC_COMPILATION",
            )
            raise FoundryError(
                "CG1_NONDETERMINISTIC_COMPILATION",
                "The two isolated Factory compilations produced different identities.",
                details={
                    "first": first_identities,
                    "second": b["identities"],
                    "differences": self._identity_differences(first_identity_payload, second_identity_payload),
                },
            )
        compile_timing_phases: dict[str, Any] = {
            "factory_compile_1": compile_1_ms,
            "factory_compile_2": compile_2_ms,
        }
        for compile_index, private_timings in ((1, first_timing_receipt), (2, b.get("_timings") if isinstance(b, dict) else None)):
            phase_values = private_timings.get("phases_ms") if isinstance(private_timings, dict) else None
            if not isinstance(phase_values, dict):
                continue
            for phase, value in phase_values.items():
                compile_timing_phases[f"factory_compile_{compile_index}.{phase}"] = value
        self._write_compile_checkpoint(
            run,
            phase="compile_twice",
            status="complete",
            elapsed_ms=compile_1_ms + compile_2_ms,
            candidate_identity=first_candidate_identity,
        )
        return {
            **a,
            "schema":DRY_RUN_SCHEMA,
            "deterministic":True,
            "independent_compilations":2,
            # This private handoff is consumed by _validate_and_compile before
            # the candidate is persisted, keeping timing out of identity data.
            "_timings": _timing_receipt(
                phases_ms=compile_timing_phases,
            ),
        }

    @staticmethod
    def _compact_candidate_for_persistence(candidate: dict[str, Any]) -> dict[str, Any]:
        """Keep one canonical artifact graph in the persisted dry-run.

        ``preview.compiled`` and readiness receipts are owner-facing copies of
        the same artifacts.  Preserve their small identity/status projections,
        but point them at the canonical top-level artifact by key so evidence
        remains complete without storing the large graph repeatedly.
        """
        if not isinstance(candidate, dict):
            return candidate
        artifacts = candidate.get("artifacts")
        preview = candidate.get("preview")
        if not isinstance(artifacts, dict) or not isinstance(preview, dict):
            return candidate
        preview.pop("compiled", None)
        readiness = preview.get("readiness")
        if isinstance(readiness, dict):
            for artifact_key, entry in readiness.items():
                if not isinstance(entry, dict):
                    continue
                entry.pop("receipt", None)
                if artifact_key in artifacts:
                    entry["artifact_key"] = artifact_key
        return candidate

    def _validate_frozen_catalog_choices(self, run: dict[str, Any], plan: dict[str, Any]) -> None:
        """Require a normal-wizard proposal to equal its exact committed choices.

        Historical explicit grant locks retain their established semantics.  A
        priority-only compatibility projection, however, cannot authorize new
        canonical acquisitions.  New normal-wizard chains use the distinct
        server-validated choice lock and must match it exactly.
        """
        project = self._project(run["project_id"])
        locks = {
            lock.get("field"): lock.get("value")
            for lock in project.get("user_locks", [])
            if isinstance(lock, dict)
        }
        committed = locks.get(COMMITTED_CATALOG_CHOICE_FIELD)
        proposal_choices = (plan.get("stage2_proposal") or {}).get("choices") or []
        sphere_kinds = {"sect_trial_sphere_acquisition", "ai_bootstrap_sphere_acquisition"}
        free_kinds = {"sect_trial_talent_acquisition", "ai_bootstrap_talent_acquisition"}
        proposal_spheres = [
            row.get("record_id") for row in proposal_choices
            if isinstance(row, dict) and row.get("kind") in sphere_kinds
        ]
        proposal_free = [
            row.get("record_id") for row in proposal_choices
            if isinstance(row, dict) and row.get("kind") in free_kinds
        ]
        proposal_free_by_sphere = {
            row.get("record_id"): proposal_choices[index + 1].get("record_id")
            for index, row in enumerate(proposal_choices[:-1])
            if isinstance(row, dict)
            and row.get("kind") in sphere_kinds
            and isinstance(proposal_choices[index + 1], dict)
            and proposal_choices[index + 1].get("kind") in free_kinds
        }
        proposal_ordinary = [
            row.get("record_id") for row in proposal_choices
            if isinstance(row, dict) and row.get("kind") == "level_talent_acquisition"
        ]
        if not isinstance(committed, dict):
            legacy = committed_catalog_grant_plan(project)
            legacy_selected = bool(
                (legacy or {}).get("acquired_canonical_sphere_ids")
                or (legacy or {}).get("grant_accounting", {}).get("ordinary_talent_ids")
                or (legacy or {}).get("grant_accounting", {}).get("free_sphere_talent_grants")
            )
            if (proposal_spheres or proposal_free or proposal_ordinary) and not legacy_selected and not (run.get("request") or {}).get("delegated_choice_envelope"):
                raise FoundryError(
                    "CG1_COMMITTED_CATALOG_CHOICE_PLAN_REQUIRED",
                    "Normal-wizard canonical acquisitions must be server-validated and frozen before scratch compilation.",
                    status_code=409,
                )
            return
        if committed.get("schema") != "TianxiaFactory.CanonicalGrantPlan.v1" or committed.get("ready") is not True:
            raise FoundryError(
                "CG1_COMMITTED_CATALOG_CHOICE_PLAN_INVALID",
                "The frozen canonical catalog choice lock is invalid.",
                status_code=409,
            )
        expected_spheres = list(committed.get("acquired_canonical_sphere_ids") or [])
        accounting = committed.get("grant_accounting") or {}
        expected_free_by_sphere = {
            row.get("sphere_id"): row.get("talent_id")
            for row in accounting.get("free_sphere_talent_grants") or []
        }
        expected_free = list(expected_free_by_sphere.values())
        expected_ordinary = list(accounting.get("ordinary_talent_ids") or [])
        mismatches = {
            "target_cl": {
                "expected": committed.get("target_cl"),
                "actual": plan.get("target_cl"),
            },
            "acquired_sphere_ids": {"expected": sorted(expected_spheres), "actual": sorted(proposal_spheres)},
            "free_talent_ids": {"expected": sorted(expected_free), "actual": sorted(proposal_free)},
            "free_talent_grants": {"expected": expected_free_by_sphere, "actual": proposal_free_by_sphere},
            "ordinary_talent_ids": {"expected": sorted(expected_ordinary), "actual": sorted(proposal_ordinary)},
        }
        failed = {
            key: value for key, value in mismatches.items()
            if value["expected"] != value["actual"]
        }
        duplicate = any(
            len(values) != len(set(values))
            for values in (proposal_spheres, proposal_free, proposal_ordinary)
        )
        if failed or duplicate:
            raise FoundryError(
                "CG1_FROZEN_CATALOG_CHOICE_MISMATCH",
                "The provider proposal does not exactly match the revision-bound canonical catalog choices.",
                details={"mismatches": failed, "duplicate_catalog_choice": duplicate},
                status_code=409,
            )

    @staticmethod
    def _apply_owner_resolutions(run: dict[str, Any], plan: dict[str, Any]) -> dict[str, Any]:
        """Apply separately bound owner choices to an in-memory plan overlay.

        The persisted response text and hash are never rewritten.  The overlay
        is revalidated by the ordinary delegated authority and deterministic
        compiler, then its binding is recorded in validation/attempt history.
        """
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        resolutions = validation.get("owner_resolutions") if isinstance(validation, dict) else []
        if not isinstance(resolutions, list) or not resolutions:
            return plan
        result = deepcopy(plan)
        selection = result.get("selection_intent")
        selection = selection if isinstance(selection, dict) else {}
        by_slot = selection.get("by_slot")
        by_slot = deepcopy(by_slot) if isinstance(by_slot, dict) else {}
        acquisition = result.get("acquisition_intent")
        acquisition = acquisition if isinstance(acquisition, dict) else {}
        acquisition = deepcopy(acquisition)
        bounded = result.get("bounded_choices")
        bounded = deepcopy(bounded) if isinstance(bounded, dict) else {}

        def selection_values(slot_id: str) -> list[Any]:
            current = by_slot.get(slot_id)
            return deepcopy(current) if isinstance(current, list) else []

        def require_scalar(value: Any, *, operation: str) -> Any:
            if value is None or isinstance(value, (dict, list, tuple, set)):
                raise FoundryError(
                    "CG1_DECISION_VALUE_INVALID",
                    "This owner operation requires one stable scalar choice value.",
                    details={"operation": operation},
                    status_code=409,
                )
            return deepcopy(value)

        def apply_selection_operation(row: dict[str, Any], slot_id: str, value: Any) -> None:
            operation = str(row.get("operation") or "replace_slot_value")
            current = selection_values(slot_id)
            if operation == "replace_slot_list":
                if not isinstance(value, list) or any(item is None for item in value):
                    raise FoundryError(
                        "CG1_DECISION_VALUE_INVALID",
                        "Replacing a selection list requires an array of legal values.",
                        details={"slot_id": slot_id},
                        status_code=409,
                    )
                by_slot[slot_id] = deepcopy(value)
                return
            if operation == "add_slot_value":
                candidate = require_scalar(value, operation=operation)
                if candidate not in current:
                    current.append(candidate)
                by_slot[slot_id] = current
                return
            if operation == "remove_slot_value":
                target = row.get("target_value")
                target = value if target is None else target
                target = require_scalar(target, operation=operation)
                by_slot[slot_id] = [item for item in current if item != target]
                return
            if operation != "replace_slot_value":
                raise FoundryError(
                    "CG1_DECISION_OPERATION_INVALID",
                    "The owner selection operation is not valid for a selection slot.",
                    details={"slot_id": slot_id, "operation": operation},
                    status_code=409,
                )
            candidate = require_scalar(value, operation=operation)
            target = row.get("target_value")
            if target is not None:
                target = require_scalar(target, operation=operation)
                if target not in current:
                    raise FoundryError(
                        "CG1_DECISION_TARGET_STALE",
                        "The owner replacement target is no longer present in the current response.",
                        details={"slot_id": slot_id, "target_value": target},
                        status_code=409,
                    )
                by_slot[slot_id] = [candidate if item == target else item for item in current]
                return
            if len(current) > 1 and candidate not in current:
                raise FoundryError(
                    "CG1_DECISION_OPERATION_REQUIRED",
                    "A multi-value selection must identify the value to replace or use an explicit list operation.",
                    details={"slot_id": slot_id, "current_count": len(current)},
                    status_code=409,
                )
            by_slot[slot_id] = [candidate]

        def apply_milestone_choice(row: dict[str, Any], value: Any) -> None:
            choice = value if isinstance(value, dict) else {}
            milestone_id = choice.get("milestone_id") or row.get("milestone_id")
            if not isinstance(milestone_id, str) or not milestone_id:
                raise FoundryError(
                    "CG1_DECISION_MILESTONE_REQUIRED",
                    "A milestone decision must identify its exact advancement milestone.",
                    status_code=409,
                )
            kind = str(choice.get("kind") or choice.get("choice_kind") or "").strip().lower()
            changes = bounded.get("ability_score_changes_by_milestone_id")
            changes = deepcopy(changes) if isinstance(changes, dict) else {}
            occurrences = acquisition.get("insight_occurrences")
            occurrences = deepcopy(occurrences) if isinstance(occurrences, list) else []
            occurrences = [
                item for item in occurrences
                if not isinstance(item, dict) or item.get("milestone_id") != milestone_id
            ]
            if kind in {"asi", "ability_score_change"}:
                deltas = choice.get("deltas")
                if not isinstance(deltas, dict) or not deltas:
                    raise FoundryError(
                        "CG1_DECISION_MILESTONE_VALUE_INVALID",
                        "An ability-score milestone decision requires a non-empty delta map.",
                        details={"milestone_id": milestone_id},
                        status_code=409,
                    )
                changes[milestone_id] = {"deltas": deepcopy(deltas)}
            elif kind in {"insight", "cultivation_insight_acquisition"}:
                insight_id = choice.get("insight_id")
                if not isinstance(insight_id, str) or not insight_id:
                    raise FoundryError(
                        "CG1_DECISION_MILESTONE_VALUE_INVALID",
                        "An Insight milestone decision requires a source-backed Insight ID.",
                        details={"milestone_id": milestone_id},
                        status_code=409,
                    )
                occurrence = {"insight_id": insight_id, "milestone_id": milestone_id}
                if isinstance(choice.get("parameters"), dict):
                    occurrence["parameters"] = deepcopy(choice["parameters"])
                occurrences.append(occurrence)
                changes.pop(milestone_id, None)
            elif kind in {"remove", "none"}:
                changes.pop(milestone_id, None)
            else:
                raise FoundryError(
                    "CG1_DECISION_MILESTONE_KIND_INVALID",
                    "Choose an ability-score improvement, a cultivation Insight, or explicit removal for this milestone.",
                    details={"milestone_id": milestone_id, "kind": kind},
                    status_code=409,
                )
            bounded["ability_score_changes_by_milestone_id"] = changes
            acquisition["insight_occurrences"] = occurrences

        for row in resolutions:
            if not isinstance(row, dict):
                continue
            slot_id = row.get("slot_id")
            field = row.get("field")
            value = row.get("value")
            operation = str(row.get("operation") or "replace_slot_value")
            if operation == "set_milestone_choice":
                apply_milestone_choice(row, value)
                continue
            if isinstance(field, str) and field.startswith("acquisition_intent.ordinary_talent_ids."):
                raw_index = field.rsplit(".", 1)[1]
                if not raw_index.isdigit() or not isinstance(value, str) or not value:
                    raise FoundryError(
                        "CG1_DECISION_VALUE_INVALID",
                        "An ordinary-Talent replacement requires one non-empty source Talent ID and a stable CL index.",
                        details={"field": field},
                        status_code=409,
                    )
                ordinary = acquisition.get("ordinary_talent_ids")
                ordinary = deepcopy(ordinary) if isinstance(ordinary, list) else []
                index = int(raw_index)
                if index < 0 or index >= len(ordinary):
                    raise FoundryError(
                        "CG1_DECISION_TARGET_STALE",
                        "The ordinary-Talent position is no longer present in the current response.",
                        details={"field": field, "index": index, "count": len(ordinary)},
                        status_code=409,
                    )
                if value in ordinary and ordinary[index] != value:
                    raise FoundryError(
                        "CG1_DELEGATED_DUPLICATE_CHOICE",
                        "An ordinary Talent can be acquired only once in the completed progression.",
                        details={"field": field, "value": value},
                        status_code=409,
                    )
                ordinary[index] = deepcopy(value)
                acquisition["ordinary_talent_ids"] = ordinary
                continue
            if isinstance(slot_id, str) and slot_id:
                apply_selection_operation(row, slot_id, value)
                continue
            if operation not in {"set_field", "replace_slot_value"}:
                raise FoundryError(
                    "CG1_DECISION_OPERATION_INVALID",
                    "This typed owner operation requires a selection slot or milestone context.",
                    details={"field": field, "operation": operation},
                    status_code=409,
                )
            if isinstance(field, str) and field in {
                "foundation_initial_stage",
                "ability_scores",
                "background_ability",
                "background_ability_amount",
                "ability_score_changes_by_milestone_id",
                "path_progression_by_cl",
            }:
                bounded[field] = deepcopy(value)
                continue
            if isinstance(field, str) and field.startswith("path_progression_by_cl."):
                progress = bounded.get("path_progression_by_cl")
                progress = deepcopy(progress) if isinstance(progress, dict) else {}
                progress[field.split(".", 1)[1]] = deepcopy(value)
                bounded["path_progression_by_cl"] = progress
        if by_slot:
            selection["by_slot"] = by_slot
            result["selection_intent"] = selection
        if bounded:
            result["bounded_choices"] = bounded
        if acquisition:
            result["acquisition_intent"] = acquisition
        return result

    def _validate_and_compile(
        self,
        run: dict[str, Any],
        response_text: str,
        *,
        submitted_request_sha256: str | None = None,
        prior_attempt_id: str | None = None,
        owner_resolution_transition_authorized: bool = False,
        compilations: int = 2,
    ) -> dict[str, Any]:
        """Validate and compile one response inside one proof-cache scope.

        Response normalization resolves the same locked rows the Stage 2
        commit resolves again; one operation scope lets both reuse the
        byte-checked memo instead of re-reading and re-verifying each row.
        """

        from project_store.service import ensure_project_lock_proof_cache_scope

        with ensure_project_lock_proof_cache_scope():
            return self._validate_and_compile_unscoped(
                run,
                response_text,
                submitted_request_sha256=submitted_request_sha256,
                prior_attempt_id=prior_attempt_id,
                owner_resolution_transition_authorized=owner_resolution_transition_authorized,
                compilations=compilations,
            )

    def _validate_and_compile_unscoped(
        self,
        run: dict[str, Any],
        response_text: str,
        *,
        submitted_request_sha256: str | None = None,
        prior_attempt_id: str | None = None,
        owner_resolution_transition_authorized: bool = False,
        compilations: int = 2,
    ) -> dict[str, Any]:
        response_schema_started = time.perf_counter()
        compatibility_receipt: dict[str, Any] = {}
        allow_stale_advancement_echo = self._proven_stale_server_repair_advancement_echo(
            run,
            response_text,
        )
        plan,raw=self._parse_plan(
            response_text,
            expected_project_id=run.get("project_id"),
            expected_project_revision=run.get("starting_revision"),
            expected_request_sha256=(run.get("request") or {}).get("request_sha256"),
            compatibility_receipt=compatibility_receipt,
            allow_proven_stale_advancement_echo=allow_stale_advancement_echo,
            creation_training_active=self._creation_training_contract_active(run),
            explicit_forging_active=self._explicit_forging_contract_active(run),
        )
        response_schema_parse_ms = _elapsed_ms(response_schema_started, time.perf_counter())
        legality_materialization_started = time.perf_counter()
        self._validate_complete_response_binding(
            run,
            plan,
            submitted_request_sha256=submitted_request_sha256,
        )
        project = self._project(run["project_id"])
        delegated_run = self._has_delegated_envelope(run)
        if delegated_run:
            correction = self._manual_ai_correction_for_response(run, plan, project)
            if correction is not None:
                raise FoundryError(
                    "CG1_MANUAL_AI_CORRECTION_REQUIRED",
                    "The Manual Chat response contains one or more invalid ordinary-Talent positions. Return a corrected response to the same chat before using Replace Response.",
                    details={
                        "ai_correction_required": correction,
                        "response_sha256": sha256_bytes(raw),
                    },
                    status_code=409,
                )
        plan = self._apply_owner_resolutions(run, plan)
        self._validate_preferred_bounded_fields(run, plan, response_text=response_text)
        point_buy_decision = self._point_buy_budget_owner_decision(run, plan)
        if point_buy_decision is not None:
            raise FoundryError(
                "CG1_BOUNDED_DECISION_REQUIRED",
                "Choose a legal 27-point-buy ability-score allocation before the Factory can materialize Stage 2.",
                details=point_buy_decision,
                status_code=409,
            )
        if plan.get("schema") in {PLAN_SCHEMA, LEGACY_PLAN_SCHEMA}:
            legacy_required = [
                "stage1_response",
                "target_cl",
                "stage2_proposal",
                "owner_descriptive_fields",
                "uncertainties",
                "fallbacks",
                "output_profile",
            ]
            legacy_missing = [field for field in legacy_required if field not in plan]
            if legacy_missing:
                raise FoundryError(
                    "CG1_PLAN_BLOCKED",
                    "The complete character plan is missing required components.",
                    details={
                        "blockers": [
                            {
                                "code": "CG1_PLAN_COMPONENT_MISSING",
                                "field": field,
                                "message": f"The complete plan is missing {field}.",
                            }
                            for field in legacy_missing
                        ]
                    },
                    status_code=409,
                )
        canonical_intent: CanonicalSelectionIntent | None = None
        if delegated_run:
            # Check compatibility copies before the server injects its frozen
            # value.  Otherwise a contradictory historical top-level target
            # could be silently replaced during normalization.
            validate_delegated_target_cl(run, project, plan)
            plan, canonical_intent, _materialized_stage2 = self._normalize_and_materialize_response(run, plan)
            if canonical_intent is not None:
                run["canonical_selection_intent"] = canonical_intent.as_dict()
        if delegated_run:
            # This is deliberately before generic component validation and
            # before final-plan derivation so omitted, stringified, or changed
            # target values all receive the one actionable authority error.
            validate_delegated_target_cl(run, project, plan)
        blockers=[]; warnings=[]
        warnings.extend(
            {"code": "CG1_OWNER_NAMED_GEAR_UNAVAILABLE", "message": message}
            for message in (run.get("request") or {}).get("owner_gear_warnings") or []
            if isinstance(message, str) and message.strip()
        )
        required_fields = (
            ("stage1_response", "owner_descriptive_fields", "uncertainties", "fallbacks", "output_profile")
            if delegated_run and canonical_intent is not None
            else ("stage1_response", "target_cl", "stage2_proposal", "owner_descriptive_fields", "uncertainties", "fallbacks", "output_profile")
        )
        for k in required_fields:
            if k not in plan: blockers.append({"code":"CG1_PLAN_COMPONENT_MISSING","field":k,"message":f"The complete plan is missing {k}."})
        target_value = plan.get("target_cl")
        if delegated_run and canonical_intent is not None:
            target_value = canonical_intent.as_dict().get("target_cl")
        if not isinstance(target_value,int) or not 1<=int(target_value or 0)<=20:
            blockers.append({"code":"CG1_TARGET_CL_INVALID","message":"Target CL must be 1 through 20."})
        if delegated_run and canonical_intent is not None and not (
            isinstance(plan.get("stage2_proposal"), dict)
            and isinstance(plan.get("stage2_proposal", {}).get("choices"), list)
            and plan.get("stage2_proposal", {}).get("choices")
        ):
            blockers.append({
                "code": "CG1_BOUNDED_DECISION_REQUIRED",
                "message": "The response supplied planning preferences but no explicit acquisition intent. Choose the exact proposed acquisitions or leave the owner decision unresolved.",
                "details": {"field": "acquisition_intent", "planning_only_slots": sorted(canonical_intent.as_dict().get("planning_preferences_by_slot") or {})},
            })
        blockers.extend(self._collaborator_blockers(bool((plan.get("output_profile") or {}).get("combat_ready"))))
        if blockers: raise FoundryError("CG1_PLAN_BLOCKED","The plan cannot enter local compilation.",details={"blockers":blockers})
        provider_required_planning_slot_ids = None
        if delegated_run:
            # The response contract is structural and identical at every cue
            # width: read it from one payload instead of the whole prompt
            # search (19 payloads, 67 s in a profiled retry).
            provider_contract = _provider_wire_compact_payload(
                _provider_payload(run, cue_limit=0, display_limit=0)
            ).get("response_contract") or {}
            required_slots = provider_contract.get("required_selection_slots") or []
            provider_required_planning_slot_ids = sorted(
                slot_id
                for slot_id in required_slots
                if slot_id in {"sphere_priorities", "insight_priorities", "item_priorities"}
            )
        final_plan = validate_delegated_choice_plan(
            run,
            project,
            plan,
            response_sha256=sha256_bytes(raw),
            provider_required_planning_slot_ids=provider_required_planning_slot_ids,
        )
        if final_plan is None:
            # Old integrations may provide a minimal Stage1 test double rather
            # than the production envelope.  Preserve their established
            # behavior while still giving every accepted run an immutable
            # server-owned final-plan record.
            final_plan = {
                "schema": "TianxiaFoundry.CharacterCreationFinalPlan.v1",
                "project_id": run["project_id"],
                "project_revision": run["starting_revision"],
                "content_lock_hash": run["request"].get("content_lock_hash"),
                "request_sha256": run["request"].get("request_sha256"),
                "response_sha256": sha256_bytes(raw),
                "idempotency_key": run.get("idempotency_key"),
                "resolution": {"schema": "TianxiaFoundry.LegacyPlanResolution.v1", "authority": "existing-local-validator"},
                "plan_sha256": sha256_json(plan),
                "immutable_after_validation": True,
            }
            final_plan["final_plan_sha256"] = final_plan_sha256(final_plan)
        if delegated_run:
            final_plan = self._derive_delegated_final_grant_plan(run, plan, final_plan)
        else:
            self._validate_frozen_catalog_choices(run, plan)
            # A legacy plan can omit every equipment row. Validate mandatory
            # gear before compilation even when no kit record will be built.
            intent_doc = plan.get("canonical_selection_intent")
            request = run.get("request") or {}
            if isinstance(intent_doc, Mapping) and (request.get("owner_gear_preferences") or request.get("owner_gear_requirements")) and not isinstance((intent_doc.get("acquisition_intent") or {}).get("starting_kit"), Mapping):
                receipt = plan.get("materialization_receipt")
                seed = receipt.get("canonical_intent_hash") if isinstance(receipt, Mapping) else None
                self._starting_kit_construction(
                    intent_doc, seed if isinstance(seed, str) else sha256_json(intent_doc), int(plan["target_cl"]),
                    owner_gear_preferences=request.get("owner_gear_preferences") or [],
                    owner_gear_requirements=request.get("owner_gear_requirements") or [], run=run,
                )
        legality_materialization_ms = _elapsed_ms(
            legality_materialization_started,
            time.perf_counter(),
        )
        candidate=self._compile_twice(
            run,
            plan,
            prior_attempt_id=prior_attempt_id,
            accepted_final_plan=final_plan if delegated_run else None,
            final_plan=final_plan,
            compilations=compilations,
        )
        candidate = self._compact_candidate_for_persistence(candidate)
        compile_timings = candidate.pop("_timings", {})
        if run["request"].get("concept_guidance"):
            from character_creation.concept_index import coverage_warnings

            acquired = catalog_stage2_selections(plan)
            acquired_ids = [value for key, values in acquired.items()
                            if isinstance(values, list)
                            for value in values if isinstance(value, str)]
            intent = canonical_intent.as_dict() if canonical_intent is not None else plan.get("canonical_selection_intent")
            equipment = None
            if isinstance(intent, dict):
                kit = self._starting_kit_construction(
                    intent, canonical_intent.intent_hash if canonical_intent is not None else sha256_json(intent),
                    int(intent.get("target_cl") or plan.get("target_cl") or final_plan.get("target_cl") or 1),
                )
                equipment = kit[0].get("resolved") if kit else None
            warnings.extend(coverage_warnings(run["request"], acquired_ids, equipment))
        warnings.extend(deepcopy(plan.get("uncertainties") or [])); warnings.extend(deepcopy(plan.get("fallbacks") or []))
        quality = _apply_owner_gear_warnings_and_quality(run, warnings, candidate)
        response_sha256 = sha256_bytes(raw)
        validation={"valid":True,"response_sha256":response_sha256,"plan_sha256":sha256_json(plan),"planner_authority_fields_used":False,"delegated_choice_authority":delegated_run,"owner_descriptive_fields":deepcopy(plan.get("owner_descriptive_fields") or {}),"proposal_projection":self._proposal_projection(plan),"response_state":{"exact_response_retained":True,"parsed_proposal_retained":True,"compiled":True}}
        if compatibility_receipt:
            validation["response_compatibility_projection"] = compatibility_receipt
        validation["timings"] = _merge_timing_receipts(
            compile_timings,
            _timing_receipt(
                phases_ms={
                    "factory_response_schema_parse": response_schema_parse_ms,
                    "factory_legality_materialization": legality_materialization_ms,
                }
            ),
        )
        source_validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        if isinstance(source_validation.get("owner_resolutions"), list):
            owner_resolutions = deepcopy(source_validation["owner_resolutions"])
            validation["owner_resolutions"] = owner_resolutions
            batch_sha256 = self._owner_resolution_batch_sha256(owner_resolutions)
            prior_batch_applied = self._owner_resolution_batch_is_applied(
                source_validation,
                owner_resolutions,
                response_sha256=response_sha256,
            )
            validation["owner_resolution_batch"] = self._owner_resolution_batch_marker(
                owner_resolutions,
                response_sha256=response_sha256,
                status="APPLIED" if owner_resolution_transition_authorized or prior_batch_applied else "PENDING",
            )
            # Keep the scalar receipt alongside the structured marker for
            # recovery clients that only need to compare the exact batch.
            validation["owner_resolution_batch_sha256"] = batch_sha256
        if canonical_intent is not None:
            validation["canonical_intent_hash"] = canonical_intent.intent_hash
            validation["materialization_receipt"] = deepcopy(plan.get("materialization_receipt") or {})
            validation["materialized_stage2_hash"] = sha256_json(plan.get("stage2_proposal") or {})
        return {"plan":plan,"final_plan":final_plan or {},"validation":validation,"candidate":candidate,"quality":quality,"warnings":warnings,"raw_sha256":sha256_bytes(raw),"canonical_intent":canonical_intent.as_dict() if canonical_intent is not None else None}

    @staticmethod
    def _diagnostic_stage(code: str) -> str:
        """Classify the first failed production boundary for owner recovery."""
        normalized = str(code or "").strip().upper()
        if normalized == "CG1_MANUAL_AI_CORRECTION_REQUIRED":
            return "AI_CORRECTION"
        # Diagnostics are an external recovery contract.  Keep this table
        # exact: substring matching misclassified unknown/compound codes (for
        # example a semantic code containing ``PATH``) as an earlier boundary.
        source_transport_codes = frozenset({
            "CG1_MANUAL_RESPONSE_FILENAME_INVALID",
            "CG1_MANUAL_RESPONSE_TOO_LARGE",
            "CG1_MANUAL_RESPONSE_ZIP_ENTRY_LIMIT",
            "CG1_MANUAL_RESPONSE_ZIP_PATH_INVALID",
            "CG1_MANUAL_RESPONSE_ZIP_MEMBER_COLLISION",
            "CG1_MANUAL_RESPONSE_ZIP_LINK_REJECTED",
            "CG1_MANUAL_RESPONSE_ZIP_SPECIAL_FILE",
            "CG1_MANUAL_RESPONSE_ZIP_ENCRYPTED",
            "CG1_MANUAL_RESPONSE_ZIP_EXPANSION_LIMIT",
            "CG1_MANUAL_RESPONSE_ZIP_CRC_INVALID",
            "CG1_MANUAL_RESPONSE_ZIP_CONTENT_INVALID",
            "CG1_MANUAL_RESPONSE_ZIP_INVALID",
            "CG1_MANUAL_RESPONSE_TYPE_INVALID",
            "CG1_MANUAL_RESPONSE_ENCODING_INVALID",
            "CG1_MANUAL_RESPONSE_EMPTY",
        })
        json_schema_codes = frozenset({
            "CG1_PLAN_JSON_INVALID",
            "CG1_PLAN_SCHEMA_INVALID",
            "CG1_PREFERRED_RESPONSE_SHAPE_INVALID",
            "CG1_PREFERRED_RESPONSE_SELECTION_INVALID",
            "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID",
            "CG1_PREFERRED_RESPONSE_BOUNDED_FIELD_INVALID",
        })
        request_binding_codes = frozenset({
            RESPONSE_BINDING_ERROR,
            "CG1_IDEMPOTENCY_CONFLICT",
            "CG1_DELEGATED_ENVELOPE_STALE",
            "CG1_DELEGATED_ONE_SHOT_BINDING_MISMATCH",
            "CG1_DELEGATED_OWNER_LOCKS_CHANGED",
            "CG1_TYPED_CHOICE_SNAPSHOT_STALE",
            "CG1_FROZEN_CATALOG_CHOICE_MISMATCH",
            "CG1_EDIT_BRIEF_BINDING_MISMATCH",
        })
        semantic_authority_codes = frozenset({
            "CG1_DELEGATED_AUTHORITY_CONFLICT",
            "CG1_DELEGATED_ENVELOPE_TAMPERED",
            "CG1_DELEGATED_METHOD_UNKNOWN",
            "CG1_DELEGATED_METHOD_REQUIRED",
            "CG1_METHOD_FOUNDATION_INCOMPATIBLE",
            "CG1_AUTHORITY_SHAPE_UNRESOLVED",
            "CG1_AUTHORITY_KIND_NOT_ALLOWED",
            "CG1_AUTHORITY_CHANNEL_NOT_ALLOWED",
            "CG1_INITIAL_PROVENANCE_CONTEXT_INVALID",
            "CG1_CANONICAL_GRANT_PLAN_LOCK_MISSING",
            "CG1_DELEGATED_FINAL_GRANT_PLAN_DIVERGED",
            "PROJECTION_NON_SPHERE_AUTHORITY_INVALID",
            "PROJECTION_UNLOCKED_CONTENT",
        })
        legality_codes = frozenset({
            "CG1_DELEGATED_NAME_REQUIRED",
            "CG1_DELEGATED_CHOICE_REQUIRED",
            "CG1_DELEGATED_CHOICE_COUNT_INVALID",
            "CG1_DELEGATED_CHOICE_OUT_OF_ENVELOPE",
            "CG1_DELEGATED_CHOICE_UNAVAILABLE",
            "CG1_DELEGATED_DUPLICATE_CHOICE",
            "CG1_PATH_SUBPATH_MISMATCH",
            "CG1_MULTIPLE_SUBPATHS_FOR_ONE_PATH",
            "CG1_METHOD_PATH_INCOMPATIBLE",
            "CG1_METHOD_ACCESS_REQUIRED",
            "CG1_FOUNDATION_PATH_INCOMPATIBLE",
            "CG1_DELEGATED_PREREQUISITE_UNSUPPORTED",
            "CG1_DELEGATED_PREREQUISITE_UNMET",
            "CG1_DELEGATED_INCOMPATIBILITY",
            "CG1_BOUNDED_DECISION_REQUIRED",
            "CG1_TARGET_CL_INVALID",
            "CG1_ORDINARY_TALENT_COUNT_AUTHORITY_UNRESOLVED",
            "CG1_SUBPATH_BINDING_UNRESOLVED",
        })
        compilation_codes = frozenset({
            "CG1_STAGE1_INVALID",
            "CG1_STAGE2_INVALID",
            "CG1_NONDETERMINISTIC_COMPILATION",
            "CG1_REQUIRED_COLLABORATOR_MISSING",
            "CG1_PRODUCTION_AUTHORITY_NOT_READY",
            "CG1_CANONICAL_PROVENANCE_BINDING_MISSING",
            "CG1_RESPONSE_SCHEMA_AUTHORITY_MISSING",
        })
        if normalized in source_transport_codes:
            return "SOURCE_TRANSPORT"
        if normalized in json_schema_codes:
            return "JSON_SCHEMA"
        if normalized in request_binding_codes:
            return "REQUEST_BINDING"
        if normalized in semantic_authority_codes:
            return "SEMANTIC_AUTHORITY"
        if normalized in legality_codes:
            return "LEGALITY"
        if normalized in compilation_codes:
            return "COMPILATION"
        return "VALIDATION"

    def _record_owner_transition_compile_failure(
        self,
        run: dict[str, Any],
        *,
        run_id: str,
        response_text: str,
        transport: dict[str, Any],
        action_type: str,
        submitted_request_sha256: str | None,
        history_prior_attempt_id: str | None,
        diagnostic: dict[str, Any],
        descriptive: dict[str, Any],
        proposal_projection: dict[str, Any],
        _owner_decision_authorization: dict[str, Any],
        incoming_response_sha256: str,
    ) -> dict[str, Any]:
        """Record an authorized build failure only against its current batch.

        Compilation is intentionally outside the durable transaction.  This
        second authority boundary prevents its stale exception handler from
        replacing a newer owner batch or appending an obsolete attempt.
        """
        owner_transition_duplicate = False
        with self.db.transaction() as conn:
            row = conn.execute(
                "SELECT project_id,request_json,response_json,validation_json,dry_run_json,blockers_json,status "
                "FROM character_creation_runs WHERE run_id=?",
                (run_id,),
            ).fetchone()
            if row is None:
                raise FoundryError("CG1_RUN_NOT_FOUND", "No character build run has that ID.", status_code=404)
            try:
                current_request = json.loads(row["request_json"] or "{}")
                current_response = json.loads(row["response_json"] or "{}")
                current_validation = json.loads(row["validation_json"] or "{}")
                current_dry_run = json.loads(row["dry_run_json"] or "{}")
                current_blockers = json.loads(row["blockers_json"] or "[]")
            except (TypeError, json.JSONDecodeError) as exc:
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted owner-transition state is not valid JSON.",
                    status_code=409,
                ) from exc
            current_run = {
                **run,
                "project_id": row["project_id"],
                "request": current_request,
                "response": current_response,
                "validation": current_validation,
                "dry_run": current_dry_run,
                "blockers": current_blockers,
                "status": row["status"],
            }
            persisted_response_text = current_response.get("exact_response_text")
            if (
                not isinstance(persisted_response_text, str)
                or sha256_bytes(persisted_response_text.encode("utf-8")) != incoming_response_sha256
                or not self._owner_decision_transition_is_authorized(
                    current_run,
                    response_text,
                    _owner_decision_authorization,
                )
            ):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The owner decision transition no longer matches the persisted exact response and resolution batch.",
                    status_code=409,
                )
            current_resolutions = current_validation.get("owner_resolutions")
            current_resolutions = (
                [deepcopy(item) for item in current_resolutions if isinstance(item, dict)]
                if isinstance(current_resolutions, list)
                else []
            )
            batch_state = self._owner_resolution_batch_state(
                current_validation,
                current_resolutions,
                response_sha256=incoming_response_sha256,
            )
            if batch_state == "APPLIED":
                owner_transition_duplicate = True
            elif batch_state != "PENDING" or row["status"] in TERMINAL_RUN_STATUSES:
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The owner decision batch is no longer the exact pending batch in the persisted run.",
                    status_code=409,
                )
            else:
                next_validation = deepcopy(current_validation)
                next_validation["last_submission_error"] = diagnostic
                next_validation["owner_descriptive_fields"] = descriptive
                next_validation["response_state"] = {
                    "exact_response_retained": True,
                    "parsed_proposal_retained": bool(proposal_projection),
                    "compiled": False,
                }
                if proposal_projection:
                    next_validation["proposal_projection"] = proposal_projection
                next_milestone_id = self._owner_transition_next_milestone_id(
                    diagnostic,
                    current_resolutions,
                    run_id=run_id,
                    request_sha256=current_request.get("request_sha256"),
                    response_sha256=incoming_response_sha256,
                    content_lock_hash=current_request.get("content_lock_hash"),
                )
                if next_milestone_id is not None:
                    # The authorized batch completed successfully even though
                    # compilation stopped at the next distinct source-backed
                    # milestone.  Keep that batch immutable and expose the
                    # next blocker for a fresh owner resolution instead of
                    # leaving the already-applied batch PENDING.
                    next_validation["owner_resolution_batch"] = self._owner_resolution_batch_marker(
                        current_resolutions,
                        response_sha256=incoming_response_sha256,
                        status="APPLIED",
                    )
                    next_validation["owner_resolution_batch_sha256"] = self._owner_resolution_batch_sha256(
                        current_resolutions
                    )
                conn.execute(
                    "UPDATE character_creation_runs SET transport_json=?,response_json=?,validation_json=?,owner_descriptive_fields_json=?,blockers_json=?,status='NEEDS_REVIEW',updated_at=? WHERE run_id=?",
                    (
                        canonical_json(transport),
                        canonical_json({
                            "exact_response_text": response_text,
                            "response_sha256": incoming_response_sha256,
                        }),
                        canonical_json(next_validation),
                        canonical_json(descriptive),
                        canonical_json([diagnostic]),
                        utcnow(),
                        run_id,
                    ),
                )
                self._append_attempt(
                    current_run,
                    action_type=action_type,
                    status="BLOCKED",
                    response_text=response_text,
                    prior_attempt_id=history_prior_attempt_id,
                    binding={
                        "submitted_request_sha256": submitted_request_sha256,
                        "active_request_sha256": current_request.get("request_sha256"),
                        "transport": transport,
                    },
                    validation=next_validation,
                    blockers=[diagnostic],
                    error=diagnostic,
                    _transaction_conn=conn,
                )
        # Both the APPLIED race and the genuine failure return the durable
        # projection.  Only the PENDING branch above wrote or appended.
        return self.get(run_id)

    @classmethod
    def _owner_transition_next_milestone_id(
        cls,
        diagnostic: Any,
        resolutions: Any,
        *,
        run_id: str,
        request_sha256: str,
        response_sha256: str,
        content_lock_hash: str,
    ) -> str | None:
        """Identify only an exact subsequent bounded milestone blocker.

        An authorized owner transition may compile far enough to expose the
        next source-backed milestone.  That is the one compile failure that
        can safely advance the current batch to APPLIED: the diagnostic has a
        typed milestone ID and no resolution in this exact batch targets it.
        Every persisted row is still rechecked with the strict restart shape so
        malformed or ambiguous batches remain PENDING.
        """
        if not isinstance(diagnostic, dict) or diagnostic.get("code") != "CG1_BOUNDED_DECISION_REQUIRED":
            return None
        details = diagnostic.get("details")
        if not isinstance(details, dict):
            return None
        milestone_id = details.get("milestone_id")
        if (
            not isinstance(milestone_id, str)
            or not milestone_id.strip()
            or milestone_id != milestone_id.strip()
            or not isinstance(resolutions, list)
            or not resolutions
            or not isinstance(run_id, str)
            or not isinstance(request_sha256, str)
            or not isinstance(response_sha256, str)
            or not isinstance(content_lock_hash, str)
        ):
            return None
        decision_ids: set[str] = set()
        milestone_ids: set[str] = set()
        for resolution in resolutions:
            if not cls._owner_resolution_is_retry_structurally_valid(
                resolution,
                run_id=run_id,
                request_sha256=request_sha256,
                response_sha256=response_sha256,
                content_lock_hash=content_lock_hash,
            ):
                return None
            decision_id = resolution.get("decision_id")
            if not isinstance(decision_id, str) or decision_id in decision_ids:
                return None
            decision_ids.add(decision_id)
            if resolution.get("operation") != "set_milestone_choice":
                continue
            value = resolution.get("value")
            if not isinstance(value, dict):
                return None
            resolution_milestone_id = value.get("milestone_id")
            if (
                not isinstance(resolution_milestone_id, str)
                or not resolution_milestone_id.strip()
                or resolution_milestone_id in milestone_ids
            ):
                return None
            milestone_ids.add(resolution_milestone_id)
            if resolution_milestone_id == milestone_id:
                return None
        return milestone_id

    def _provider_nonrequired_planning_slot_ids(self, run: dict[str, Any]) -> set[str]:
        """Return frozen unresolved planning slots omitted from the provider contract."""
        envelope = ((run.get("request") or {}).get("delegated_choice_envelope") or {})
        if not isinstance(envelope, dict) or not envelope:
            return set()
        unresolved = {
            slot_id
            for slot_id in (envelope.get("unresolved_owner_decisions") or [])
            if isinstance(slot_id, str)
        }
        planning_slots = {"sphere_priorities", "insight_priorities", "item_priorities"}
        try:
            # The response contract is structural and identical at every cue
            # width: read it from one payload instead of the whole prompt
            # search (19 payloads, 67 s in a profiled retry).
            provider_contract = _provider_wire_compact_payload(
                _provider_payload(run, cue_limit=0, display_limit=0)
            ).get("response_contract") or {}
            required = {
                slot_id
                for slot_id in (provider_contract.get("required_selection_slots") or [])
                if isinstance(slot_id, str)
            }
        except (FoundryError, TypeError, ValueError, json.JSONDecodeError):
            return set()
        return (unresolved & planning_slots) - required

    @staticmethod
    def _normalize_final_plan_nonrequired_planning_rows(
        final_plan: dict[str, Any],
        nonrequired_slots: set[str],
    ) -> dict[str, Any]:
        normalized = deepcopy(final_plan)
        normalized.pop("final_plan_sha256", None)

        def keep(row: Any) -> bool:
            return not (
                isinstance(row, dict)
                and row.get("slot_id") in nonrequired_slots
                and row.get("choice_id") is None
                and row.get("provenance") == "needs_owner"
                and row.get("status") == "unresolved"
            )

        if isinstance(normalized.get("unresolved"), list):
            normalized["unresolved"] = [row for row in normalized["unresolved"] if keep(row)]
        resolution = normalized.get("resolution")
        if isinstance(resolution, dict) and isinstance(resolution.get("provenance"), list):
            resolution["provenance"] = [row for row in resolution["provenance"] if keep(row)]
        return normalized

    def _final_plan_nonrequired_planning_compatible(
        self,
        run: dict[str, Any],
        existing: dict[str, Any],
        candidate: dict[str, Any],
    ) -> bool:
        nonrequired_slots = self._provider_nonrequired_planning_slot_ids(run)
        if not nonrequired_slots:
            return False
        return self._normalize_final_plan_nonrequired_planning_rows(
            existing, nonrequired_slots
        ) == self._normalize_final_plan_nonrequired_planning_rows(
            candidate, nonrequired_slots
        )

    def _apply_response(
        self,
        run_id: str,
        response_text: str,
        transport: dict[str, Any],
        *,
        submitted_request_sha256: str | None = None,
        prior_attempt_id: str | None = None,
        binding_error_status: bool = False,
        action_type: str = "IMPORT_RESPONSE",
        _owner_decision_authorization: dict[str, Any] | None = None,
        _suppress_auto_finalize: bool = False,
    ) -> dict[str, Any]:
        run = self.get(run_id)
        history_prior_attempt_id = prior_attempt_id or self._latest_attempt_id(run_id)
        transport = deepcopy(transport)
        if prior_attempt_id is not None:
            transport["prior_attempt_id"] = prior_attempt_id
        incoming_response_sha256 = sha256_bytes(response_text.encode("utf-8"))
        owner_resolution_transition_authorized = self._owner_decision_transition_is_authorized(
            run,
            response_text,
            _owner_decision_authorization,
        )
        if _owner_decision_authorization is not None and not owner_resolution_transition_authorized:
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The owner decision transition is not bound to the current exact response and persisted resolution batch.",
                status_code=409,
            )
        existing_final_plan = run.get("final_plan") or {}
        if existing_final_plan:
            if incoming_response_sha256 != existing_final_plan.get("response_sha256"):
                raise FoundryError(
                    "CG1_FINAL_PLAN_IMMUTABLE",
                    "The accepted server final plan is immutable and cannot be replaced by a different response.",
                    status_code=409,
                )
        try:
            # Compilation installs server-derived descriptive locks in the
            # isolated scratch database.  Bind that scratch lock to the exact
            # response bytes being compiled, even though the durable response
            # row is written only after compilation succeeds.  Finalization
            # reads the persisted response hash; using an empty scratch hash
            # would produce a different project input hash and therefore
            # different projection/provenance artifacts.
            compile_run = dict(run)
            compile_run["response"] = {
                **(run.get("response") or {}),
                "exact_response_text": response_text,
                "response_sha256": incoming_response_sha256,
            }
            source_response = run.get("response") if isinstance(run.get("response"), Mapping) else {}
            if isinstance(run.get("_response_evidence"), Mapping):
                compile_run["_response_evidence"] = deepcopy(run["_response_evidence"])
            elif not isinstance(source_response.get("exact_response_text"), str) and not source_response.get("response_sha256"):
                compile_run["_response_evidence"] = {
                    "schema": _RESPONSE_EVIDENCE_SCHEMA,
                    "kind": "PRE_PERSISTENCE",
                    "run_id": run.get("run_id"),
                    "project_id": run.get("project_id"),
                    "request_sha256": (run.get("request") or {}).get("request_sha256"),
                    "response_sha256": incoming_response_sha256,
                }
            # A deterministic correction is validated before its append-only
            # attempt row is written.  Carry the exact private transport
            # marker into that scratch snapshot so provenance validation can
            # bind the virtual leaf to the persisted prior attempt; the
            # transport is still persisted only through the normal path.
            compile_run["transport"] = deepcopy(transport)
            compiled = self._validate_and_compile(
                compile_run,
                response_text,
                submitted_request_sha256=submitted_request_sha256,
                prior_attempt_id=prior_attempt_id,
                owner_resolution_transition_authorized=owner_resolution_transition_authorized,
                # A finished DCC walk compiles once; its independent second
                # build runs in the GM retry or at finalize (owner-approved
                # 2026-09-24).  Every other path still proves the pair here.
                compilations=1 if action_type == "DCC_LINEAR_WALK" else 2,
            )
            if (
                existing_final_plan
                and existing_final_plan != compiled["final_plan"]
                and self._final_plan_nonrequired_planning_compatible(
                    run, existing_final_plan, compiled["final_plan"]
                )
            ):
                # The accepted plan remains byte-for-byte immutable.  A later
                # closed-world provider projection may prove that one of its
                # planning-only owner rows was never required; reuse the
                # persisted plan rather than replacing it.
                compiled["final_plan"] = deepcopy(existing_final_plan)
            if owner_resolution_transition_authorized:
                compiled_validation = compiled.get("validation") if isinstance(compiled, dict) else None
                persisted_resolutions = (run.get("validation") or {}).get("owner_resolutions") if isinstance(run.get("validation"), dict) else None
                if not self._owner_resolution_batch_is_applied(
                    compiled_validation,
                    persisted_resolutions,
                    response_sha256=incoming_response_sha256,
                ):
                    raise FoundryError(
                        "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                        "The compiled owner-decision batch marker does not match the persisted exact response resolution batch.",
                        status_code=409,
                    )
            status = "READY_FOR_REVIEW" if compiled["quality"]["status"] == "CLEAN" else "NEEDS_REVIEW"
            response = {
                "exact_response_text": response_text,
                "response_sha256": compiled["raw_sha256"],
                "parsed_plan": compiled["plan"],
            }
            owner_transition_duplicate = False
            persistence_started = time.perf_counter()
            with self.db.transaction() as conn:
                existing_row = conn.execute(
                    "SELECT final_plan_json,validation_json,response_json,request_json,status FROM character_creation_runs WHERE run_id=?",
                    (run_id,),
                ).fetchone()
                existing_final_plan = json.loads(existing_row["final_plan_json"] or "{}") if existing_row else {}
                if owner_resolution_transition_authorized:
                    current_request = json.loads(existing_row["request_json"] or "{}") if existing_row else {}
                    current_validation = json.loads(existing_row["validation_json"] or "{}") if existing_row else {}
                    current_response = json.loads(existing_row["response_json"] or "{}") if existing_row else {}
                    current_run = {
                        **run,
                        "request": current_request,
                        "validation": current_validation,
                        "response": current_response,
                    }
                    persisted_response_text = current_response.get("exact_response_text")
                    if (
                        not isinstance(persisted_response_text, str)
                        or sha256_bytes(persisted_response_text.encode("utf-8")) != incoming_response_sha256
                    ):
                        raise FoundryError(
                            "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                            "The persisted exact response no longer matches the owner decision transition.",
                            status_code=409,
                        )
                    if not self._owner_decision_transition_is_authorized(
                        current_run,
                        response_text,
                        _owner_decision_authorization,
                    ):
                        raise FoundryError(
                            "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                            "The owner decision transition no longer matches the persisted exact response and resolution batch.",
                            status_code=409,
                        )
                    current_resolutions = current_validation.get("owner_resolutions")
                    current_resolutions = (
                        [deepcopy(row) for row in current_resolutions if isinstance(row, dict)]
                        if isinstance(current_resolutions, list)
                        else []
                    )
                    if self._owner_resolution_batch_is_applied(
                        current_validation,
                        current_resolutions,
                        response_sha256=incoming_response_sha256,
                    ):
                        # A concurrent authorized build won the commit race.
                        # Its persisted run is already authoritative; do not
                        # rewrite its final plan/validation or append a retry.
                        owner_transition_duplicate = True
                    elif not self._owner_resolution_batch_is_pending(
                        current_validation,
                        current_resolutions,
                        response_sha256=incoming_response_sha256,
                    ):
                        raise FoundryError(
                            "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                            "The owner decision batch is no longer pending in the persisted run.",
                            status_code=409,
                        )
                    if not owner_transition_duplicate and existing_row["status"] in TERMINAL_RUN_STATUSES:
                        raise FoundryError(
                            "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                            "The owner decision run became terminal before its pending batch could be applied.",
                            status_code=409,
                        )
                if not owner_transition_duplicate and existing_final_plan and existing_final_plan != compiled["final_plan"]:
                    if not owner_resolution_transition_authorized:
                        raise FoundryError(
                            "CG1_FINAL_PLAN_IMMUTABLE",
                            "The accepted server final plan is immutable and cannot be replaced by a different response.",
                            status_code=409,
                        )
                if not owner_transition_duplicate:
                    persistence_ms = _elapsed_ms(persistence_started, time.perf_counter())
                    persistence_timing = _timing_receipt(
                        phases_ms={"factory_persistence": persistence_ms}
                    )
                    compiled["validation"]["timings"] = _merge_timing_receipts(
                        compiled["validation"].get("timings"),
                        persistence_timing,
                    )
                    transport["timings"] = _merge_timing_receipts(
                        transport.get("timings"),
                        persistence_timing,
                    )
                    conn.execute(
                        """UPDATE character_creation_runs SET transport_json=?,response_json=?,validation_json=?,dry_run_json=?,final_plan_json=?,owner_descriptive_fields_json=?,quality_json=?,blockers_json='[]',warnings_json=?,status=?,updated_at=? WHERE run_id=?""",
                        (
                            canonical_json(transport), canonical_json(response), canonical_json(compiled["validation"]),
                            canonical_json(compiled["candidate"]), canonical_json(compiled["final_plan"]), canonical_json(compiled["plan"].get("owner_descriptive_fields") or {}), canonical_json(compiled["quality"]),
                            canonical_json(compiled["warnings"]), status, utcnow(), run_id,
                        ),
                    )
            if owner_transition_duplicate:
                return self.get(run_id)
        except FoundryError as exc:
            # A failed authorized commit is a capability/state race, not a
            # new response diagnostic.  In particular, do not let this stale
            # compiler snapshot overwrite a newer APPLIED/PENDING batch.
            if _owner_decision_authorization is not None and exc.code == "CG1_OWNER_DECISION_AUTHORIZATION_INVALID":
                raise
            if exc.code in {"CG1_BOUNDED_DECISION_REQUIRED", "CG1_PLAN_BLOCKED"}:
                correction = self._manual_ai_correction_for_bounded_failure(run, response_text, exc)
                if correction is not None:
                    source_error = {
                        "code": exc.code,
                        "message": exc.message,
                        "details": deepcopy(exc.details),
                    }
                    exc = FoundryError(
                        "CG1_MANUAL_AI_CORRECTION_REQUIRED",
                        "The Manual Chat response contains a response-authored bounded mechanical decision that the same AI must correct before using Replace Response.",
                        details={
                            "ai_correction_required": correction,
                            "response_sha256": incoming_response_sha256,
                            "source_error": source_error,
                        },
                        status_code=409,
                    )
            descriptive = self._descriptive_from_response_text(response_text)
            diagnostic_category = self._diagnostic_stage(exc.code)
            diagnostic = {
                "schema": "TianxiaFoundry.CharacterCreationDiagnostic.v2",
                "code": exc.code,
                "message": exc.message,
                "details": exc.details,
                # ``stage``/``category`` remain the REC1-P1CR4 compatibility
                # fields.  ``boundary`` is the precise owner diagnostic.
                "stage": diagnostic_category,
                "category": diagnostic_category,
                "boundary": self._diagnostic_boundary(exc.code),
                "json_parsed": exc.code != "CG1_PLAN_JSON_INVALID",
                "response_retained": True,
            }
            proposal_projection = self._proposal_projection_from_response_text(response_text)
            if _owner_decision_authorization is not None:
                return self._record_owner_transition_compile_failure(
                    run,
                    run_id=run_id,
                    response_text=response_text,
                    transport=transport,
                    action_type=action_type,
                    submitted_request_sha256=submitted_request_sha256,
                    history_prior_attempt_id=history_prior_attempt_id,
                    diagnostic=diagnostic,
                    descriptive=descriptive,
                    proposal_projection=proposal_projection,
                    _owner_decision_authorization=_owner_decision_authorization,
                    incoming_response_sha256=incoming_response_sha256,
                )
            if exc.code == RESPONSE_BINDING_ERROR and binding_error_status:
                validation = deepcopy(run.get("validation") or {})
                validation["last_submission_error"] = diagnostic
                validation["owner_descriptive_fields"] = descriptive
                validation["response_state"] = {
                    "exact_response_retained": True,
                    "parsed_proposal_retained": bool(proposal_projection),
                    "compiled": False,
                }
                if proposal_projection:
                    validation["proposal_projection"] = proposal_projection
                with self.db.transaction() as conn:
                    conn.execute(
                        "UPDATE character_creation_runs SET transport_json=?,response_json=?,validation_json=?,owner_descriptive_fields_json=?,updated_at=? WHERE run_id=?",
                        (
                            canonical_json(transport),
                            canonical_json({"exact_response_text": response_text, "response_sha256": sha256_bytes(response_text.encode("utf-8"))}),
                            canonical_json(validation), canonical_json(descriptive), utcnow(), run_id,
                        ),
                    )
                self._append_attempt(
                    run,
                    action_type=action_type,
                    status="BLOCKED",
                    response_text=response_text,
                    prior_attempt_id=history_prior_attempt_id,
                    binding={
                        "submitted_request_sha256": submitted_request_sha256,
                        "active_request_sha256": run["request"].get("request_sha256"),
                        "transport": transport,
                    },
                    error=diagnostic,
                )
                raise
            blocker = diagnostic
            validation = deepcopy(run.get("validation") or {})
            if exc.code == "CG1_MANUAL_AI_CORRECTION_REQUIRED":
                # A prior response may have left owner-decision diagnostics in
                # the run.  They do not describe this response and must not
                # turn an AI-authored progression error into owner work.
                validation.pop("unresolved_owner_decisions", None)
            # Keep the latest failed production boundary on the current run as
            # well as in the append-only attempt ledger.  Owner recovery and
            # the evidence endpoint must be able to restore the exact JSON
            # schema/binding/semantic diagnostic after navigation or reload.
            validation["last_submission_error"] = diagnostic
            validation["owner_descriptive_fields"] = descriptive
            validation["response_state"] = {
                "exact_response_retained": True,
                "parsed_proposal_retained": bool(proposal_projection),
                "compiled": False,
            }
            if proposal_projection:
                validation["proposal_projection"] = proposal_projection
            with self.db.transaction() as conn:
                conn.execute(
                    "UPDATE character_creation_runs SET transport_json=?,response_json=?,validation_json=?,owner_descriptive_fields_json=?,blockers_json=?,status='NEEDS_REVIEW',updated_at=? WHERE run_id=?",
                    (
                        canonical_json(transport),
                        canonical_json({
                            "exact_response_text": response_text,
                            "response_sha256": sha256_bytes(response_text.encode("utf-8")),
                        }),
                        canonical_json(validation), canonical_json(descriptive), canonical_json([blocker]), utcnow(), run_id,
                    ),
                )
            self._append_attempt(
                run,
                action_type=action_type,
                status="BLOCKED",
                response_text=response_text,
                prior_attempt_id=history_prior_attempt_id,
                binding={
                    "submitted_request_sha256": submitted_request_sha256,
                    "active_request_sha256": run["request"].get("request_sha256"),
                    "transport": transport,
                },
                blockers=[blocker],
                error=diagnostic,
            )
            return self.get(run_id)
        self._append_attempt(
            run,
            action_type=action_type,
            status=status,
            response_text=response_text,
            canonical_intent=compiled.get("canonical_intent"),
            materialization_receipt=compiled["validation"].get("materialization_receipt"),
            validation=compiled.get("validation"),
            quality=compiled.get("quality"),
            candidate_identity=(compiled.get("candidate") or {}).get("candidate_identity"),
            materialized_plan_sha256=compiled["validation"].get("materialized_stage2_hash"),
            submitted_plan_sha256=compiled["validation"].get("plan_sha256"),
            prior_attempt_id=history_prior_attempt_id,
            binding={
                "submitted_request_sha256": submitted_request_sha256,
                "active_request_sha256": run["request"].get("request_sha256"),
                "transport": transport,
            },
        )
        result = self.get(run_id)
        if (
            not _suppress_auto_finalize
            and result["execution_mode"] == "AUTO_FINALIZE_WHEN_CLEAN"
            and result["quality"].get("status") == "CLEAN"
        ):
            receipt = self._valid_auto_finalize_opt_in(result)
            if receipt:
                return self.finalize(run_id, auto_finalize_receipt=receipt)
        return result

    def accept_descriptive_fields(
        self,
        run_id: str,
        *,
        name: str | None,
        concept: str | None,
        title: str | None = None,
    ) -> dict[str, Any]:
        run = self.get(run_id)
        if run["status"] in TERMINAL_RUN_STATUSES:
            raise FoundryError("CG1_DESCRIPTIVE_FIELDS_TERMINAL", "A finalized, cancelled, or revised run cannot accept new descriptive fields.", status_code=409)
        if getattr(self, "_finalizing_run_id", None) == run_id:
            # Finalize (or auto-finalize) already read the wording it saves the character with; a change accepted now
            # would be recorded on the run but never reach the character (owner 2026-09-27: a rename was lost).
            raise FoundryError("CG1_DESCRIPTIVE_FIELDS_FINALIZING",
                               "This character is being finalized with the wording it had when finalizing began; the wording can't change now.",
                               status_code=409)
        proposed = run.get("owner_descriptive_fields", {}).get("proposed") or {}
        delegated = (run.get("request") or {}).get("delegated_choice_envelope") or {}
        delegated_fields = delegated.get("delegated_fields")
        delegated_fields = delegated_fields if isinstance(delegated_fields, dict) else {}
        title_authority_present = "identity.title" in delegated_fields
        title_authority = delegated_fields.get("identity.title")
        title_contract = delegated.get("delegated_title_contract")
        title_contract_present = "delegated_title_contract" in delegated
        title_contract_active = _delegated_title_contract_is_complete(title_authority, title_contract)
        compiler_gate_active = isinstance(delegated.get("compiler_selection_authority"), dict)
        title_contract_applies = compiler_gate_active or title_authority_present or title_contract_present
        if title_contract_applies:
            if not title_contract_active:
                raise FoundryError(
                    "CG1_DELEGATED_TITLE_AUTHORITY_INVALID",
                    "The active delegated title contract is malformed or incomplete.",
                    details={"field": "identity.title"},
                    status_code=409,
                )
            title_state = title_authority.get("state")
            owner_title = title_authority.get("owner_value")
            if title_state not in {"delegated", "owner_locked"}:
                raise FoundryError(
                    "CG1_DELEGATED_TITLE_AUTHORITY_INVALID",
                    "The active delegated title authority has an invalid state.",
                    details={"field": "identity.title", "state": title_state},
                    status_code=409,
                )
            if (
                title_contract.get("state") != title_state
                or title_contract.get("owner_locked_value") != owner_title
            ):
                raise FoundryError(
                    "CG1_DELEGATED_TITLE_AUTHORITY_INVALID",
                    "The active delegated title contract is not bound to its title authority state.",
                    details={"field": "identity.title", "state": title_state},
                    status_code=409,
                )
            if title_state == "owner_locked" and (
                not isinstance(owner_title, str)
                or not owner_title.strip()
                or len(owner_title.strip()) > 120
            ):
                raise FoundryError(
                    "CG1_DELEGATED_TITLE_AUTHORITY_INVALID",
                    "The active owner-locked title is not a valid bounded title.",
                    details={"field": "character.identity.title", "max_length": 120},
                    status_code=409,
                )
            if title is not None and (
                not isinstance(title, str)
                or not title.strip()
            ):
                raise FoundryError(
                    "CG1_DELEGATED_TITLE_REQUIRED",
                    "An active delegated title must be nonblank.",
                    details={"field": "owner_descriptive_fields.identity.title"},
                    status_code=422,
                )
            if isinstance(title, str) and len(title.strip()) > 120:
                raise FoundryError(
                    "CG1_DELEGATED_TITLE_INVALID",
                    "A delegated title must be no longer than 120 characters.",
                    details={"field": "owner_descriptive_fields.identity.title", "max_length": 120},
                    status_code=422,
                )
        input_identity = {"name": name}
        if title is not None:
            input_identity["title"] = title
        fields = self._descriptive_fields({"identity": input_identity, "concept": concept})
        proposed_fields = self._descriptive_fields(proposed)
        if title is None and "title" in (proposed_fields.get("identity") or {}):
            fields["identity"]["title"] = (proposed_fields.get("identity") or {}).get("title")
        if title_contract_active:
            accepted_title = (fields.get("identity") or {}).get("title")
            if not isinstance(accepted_title, str) or not accepted_title.strip():
                raise FoundryError(
                    "CG1_DELEGATED_TITLE_REQUIRED",
                    "An active delegated title must remain nonblank when descriptive fields are accepted.",
                    details={"field": "owner_descriptive_fields.identity.title"},
                    status_code=422,
                )
            accepted_title = accepted_title.strip()
            if len(accepted_title) > 120:
                raise FoundryError(
                    "CG1_DELEGATED_TITLE_INVALID",
                    "A delegated title must be no longer than 120 characters.",
                    details={"field": "owner_descriptive_fields.identity.title", "max_length": 120},
                    status_code=422,
                )
            fields["identity"]["title"] = accepted_title
        for field, value in (
            ("identity.name", fields["identity"]["name"]),
            ("identity.title", (fields.get("identity") or {}).get("title")),
            ("concept", fields["concept"]),
        ):
            authority = delegated_fields.get(field) or {}
            if authority.get("state") == "owner_locked":
                expected = str(authority.get("owner_value") or "").strip() or None
                if expected is None:
                    continue
                # Owner rule 2026-10-10: owner-written wording wins; the AI may only add to it. Never block.
                from .delegated_choice_authority import _owner_wins
                resolved = _owner_wins(expected, value)
                if field == "concept":
                    fields["concept"] = resolved
                else:
                    fields.setdefault("identity", {})[field.split(".", 1)[1]] = resolved
        if not (fields["identity"]["name"] or fields["concept"] or (fields.get("identity") or {}).get("title")):
            fields = proposed_fields
        with self.db.transaction() as conn:
            conn.execute(
                "UPDATE character_creation_runs SET accepted_descriptive_fields_json=?,owner_decision='ACCEPT_DESCRIPTIVE_FIELDS',updated_at=? WHERE run_id=?",
                (canonical_json(fields), utcnow(), run_id),
            )
        return self.get(run_id)

    @staticmethod
    def _execution_descriptive_fields(run: dict[str, Any], plan: dict[str, Any]) -> dict[str, Any]:
        projection = run.get("owner_descriptive_fields") or {}
        accepted = projection.get("accepted") if isinstance(projection, dict) else None
        accepted_is_substantive = isinstance(accepted, dict) and (
            (accepted.get("identity") or {}).get("name")
            or (accepted.get("identity") or {}).get("title")
            or accepted.get("concept")
        )
        proposed_or_resolved = projection.get("resolved") if isinstance(projection, dict) else None
        resolved_is_substantive = isinstance(proposed_or_resolved, dict) and (
            (proposed_or_resolved.get("identity") or {}).get("name")
            or (proposed_or_resolved.get("identity") or {}).get("title")
            or proposed_or_resolved.get("concept")
        )
        resolved = accepted if accepted_is_substantive else proposed_or_resolved if resolved_is_substantive else None
        if not isinstance(resolved, dict):
            return deepcopy(plan)
        result = deepcopy(plan)
        result["owner_descriptive_fields"] = CharacterCreationExecutionService._descriptive_fields(resolved)
        return result

    def _materialize_descriptive_fields(self, run: dict[str, Any], plan: dict[str, Any], authority_db: Database, *, phase: str) -> None:
        fields = self._descriptive_fields(plan.get("owner_descriptive_fields") or {})
        from project_store.service import ProjectStore
        store = self.projects if authority_db is self.db else ProjectStore(authority_db)
        binding = {
            "schema": "TianxiaFoundry.ServerDerivedDescriptiveFields.v1",
            "run_id": run["run_id"],
            "project_id": run["project_id"],
            "request_sha256": run["request"].get("request_sha256"),
            "response_sha256": run.get("response", {}).get("response_sha256"),
            "phase": "server-derived",
        }
        for field, value in (
            ("character.identity.final_display_name", fields["identity"].get("name")),
            ("character.identity.final_concept", fields.get("concept")),
            ("character.identity.final_title", (fields.get("identity") or {}).get("title")),
        ):
            if not value:
                continue
            materialize = getattr(store, "materialize_server_derived_user_lock", None)
            if not callable(materialize):
                # Focused legacy test doubles intentionally model only the
                # project read/write surface.  They still exercise the
                # candidate/finalization path; production ProjectStore owns
                # the durable server-derived descriptive locks.
                continue
            materialize(
                run["project_id"],
                field=field,
                value={"value": value, "binding": binding},
                source=f"cg1-owner-descriptive:{run['run_id']}:server-derived",
                lock_id=f"lock.cg1.{field.replace('.', '-')}",
            )

        # Starting-proficiency choices are a server-derived mechanical lock,
        # not descriptive prose.  Keeping this call beside the descriptive
        # materialization means both the stage1-first scratch adapter and the
        # central compiler path install the same byte-identical lock before
        # any Stage 1/Stage 2 work begins.  Legacy requests without an
        # advertised starting contract are a deliberate no-op.
        self._materialize_starting_proficiency_choices(run, plan, authority_db)

    def _materialize_starting_proficiency_choices(
        self,
        run: dict[str, Any],
        plan: dict[str, Any],
        authority_db: Database,
    ) -> dict[str, Any] | None:
        """Persist the exact validated starting-proficiency response choices.

        The lock carries only frozen authority, response maps, selected slot
        IDs, and their immutable request binding.  It intentionally excludes
        phase/timing/path values and the raw model response.
        """
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        bounded_contract = (
            request.get("bounded_choice_contract")
            if isinstance(request.get("bounded_choice_contract"), dict)
            else {}
        )
        advertised = bounded_contract.get("fields")
        advertised = advertised if isinstance(advertised, dict) else {}
        if not any(field in advertised for field in _STARTING_PROFICIENCY_FIELD_KEYS):
            return None

        selection = plan.get("selection_intent") if isinstance(plan, dict) else {}
        selection = selection if isinstance(selection, dict) else {}
        by_slot = selection.get("by_slot")
        by_slot = by_slot if isinstance(by_slot, dict) else {}
        selected_by_slot = {
            slot: by_slot.get(slot)
            for slot in (
                "path_choice",
                "background_choice",
                "origin_insight_choice",
            )
        }
        bounded = plan.get("bounded_choices") if isinstance(plan, dict) else None
        validation = validate_starting_proficiency_choices(
            contract=bounded_contract.get("starting_proficiency_choice_contract"),
            selected_by_slot=selected_by_slot,
            bounded_choices=bounded,
        )
        validation_details = {
            "schema": validation.get("schema"),
            "contract_sha256": validation.get("contract_sha256"),
            "validation_sha256": validation.get("validation_sha256"),
            "blockers": deepcopy(validation.get("blockers") or []),
        }
        if validation.get("valid") is not True:
            raise FoundryError(
                "CG1_STARTING_PROFICIENCY_CHOICE_INVALID",
                "The starting-proficiency choices did not satisfy the sealed mechanical contract.",
                details=validation_details,
                status_code=422,
            )

        # Recompute immediately before sealing.  This guards the lock against
        # accidental mutation between validation and persistence and makes
        # the stored validation result independently reproducible.
        recomputed = validate_starting_proficiency_choices(
            contract=bounded_contract.get("starting_proficiency_choice_contract"),
            selected_by_slot=deepcopy(selected_by_slot),
            bounded_choices=deepcopy(bounded),
        )
        if recomputed != validation:
            raise FoundryError(
                "CG1_STARTING_PROFICIENCY_VALIDATION_RECOMPUTE_MISMATCH",
                "The validated starting-proficiency result changed before server lock materialization.",
                details={
                    "schema": validation.get("schema"),
                    "contract_sha256": validation.get("contract_sha256"),
                    "validation_sha256": validation.get("validation_sha256"),
                },
                status_code=409,
            )

        contract = bounded_contract.get("starting_proficiency_choice_contract")
        response_maps = {
            field: deepcopy(bounded.get(field)) if isinstance(bounded, dict) and isinstance(bounded.get(field), dict) else {}
            for field in _STARTING_PROFICIENCY_FIELD_KEYS
        }
        binding = {
            "schema": STARTING_PROFICIENCY_DERIVED_SCHEMA,
            "run_id": run.get("run_id"),
            "project_id": run.get("project_id"),
            "starting_revision": run.get("starting_revision"),
            "content_lock_hash": request.get("content_lock_hash"),
            "request_sha256": request.get("request_sha256"),
            "response_sha256": (
                (run.get("response") or {}).get("response_sha256")
                if isinstance(run.get("response"), dict)
                else None
            ),
        }
        missing_binding: list[str] = []
        for key, value in binding.items():
            if key == "starting_revision":
                if type(value) is not int:
                    missing_binding.append(key)
            elif not isinstance(value, str) or not value.strip():
                missing_binding.append(key)
        if missing_binding or not isinstance(contract, dict):
            raise FoundryError(
                "CG1_STARTING_PROFICIENCY_BINDING_INVALID",
                "The starting-proficiency lock lacks an exact request binding.",
                details={
                    "missing_fields": sorted(set(missing_binding + (["contract"] if not isinstance(contract, dict) else []))),
                },
                status_code=409,
            )

        lock_value = {
            "schema": STARTING_PROFICIENCY_DERIVED_SCHEMA,
            "contract": deepcopy(contract),
            "response_maps": response_maps,
            "selected_by_slot": deepcopy(selected_by_slot),
            "validated": deepcopy(validation),
            "binding": binding,
        }
        lock_value_sha256 = sha256_json(lock_value)
        from project_store.service import ProjectStore
        store = self.projects if authority_db is self.db else ProjectStore(authority_db)
        materialize = getattr(store, "materialize_server_derived_user_lock", None)
        if not callable(materialize):
            # Small legacy test doubles intentionally lack durable-lock APIs;
            # a real ProjectStore must never silently skip this mechanical
            # authority.
            if isinstance(store, ProjectStore):
                raise FoundryError(
                    "CG1_STARTING_PROFICIENCY_LOCK_UNAVAILABLE",
                    "The project store cannot materialize the server-derived starting-proficiency lock.",
                    status_code=500,
                )
            return {
                "schema": STARTING_PROFICIENCY_DERIVED_SCHEMA,
                "field": STARTING_PROFICIENCY_DERIVED_FIELD,
                "lock_id": "lock.cg1.character-choices-starting-proficiencies",
                "lock_value_sha256": lock_value_sha256,
                "contract_sha256": validation.get("contract_sha256"),
                "validation_sha256": validation.get("validation_sha256"),
            }
        materialize(
            run["project_id"],
            field=STARTING_PROFICIENCY_DERIVED_FIELD,
            value=lock_value,
            source=f"cg1-starting-proficiencies:{lock_value_sha256}:server-derived",
            lock_id="lock.cg1.character-choices-starting-proficiencies",
        )
        return {
            "schema": STARTING_PROFICIENCY_DERIVED_SCHEMA,
            "field": STARTING_PROFICIENCY_DERIVED_FIELD,
            "lock_id": "lock.cg1.character-choices-starting-proficiencies",
            "lock_value_sha256": lock_value_sha256,
            "contract_sha256": validation.get("contract_sha256"),
            "validation_sha256": validation.get("validation_sha256"),
        }

    def submit_manual(
        self,
        run_id: str,
        *,
        response_text: str,
        request_sha256: str,
        prior_attempt_id: str | None = None,
    ) -> dict[str, Any]:
        run = self.get(run_id)
        if run["execution_mode"] != "MANUAL_CHAT":
            raise FoundryError(
                "CG1_MANUAL_RESPONSE_MODE_MISMATCH",
                "This run is not waiting for a Manual Chat response.",
            )
        return self._apply_response(
            run_id,
            response_text,
            {
                "mode": "MANUAL_CHAT",
                "provider_called": False,
                "transfer": "pasted_response",
                "submitted_request_sha256": request_sha256,
                "source_provenance": {
                    "schema": "TianxiaFoundry.CharacterCreationResponseSourceProvenance.v1",
                    "source_kind": "paste",
                    "filename": None,
                    "member_filename": None,
                    "archive_sha256": None,
                    "member_sha256": None,
                    "raw_byte_count": len(response_text.encode("utf-8")),
                    "raw_bytes_sha256": sha256_bytes(response_text.encode("utf-8")),
                    "archive_members": [],
                    "normalization": {
                        "encoding": "utf-8",
                        "bom_removed": False,
                        "outer_whitespace_stripped": False,
                        "normalized_text_bytes": len(response_text.encode("utf-8")),
                        "normalized_text_sha256": sha256_bytes(response_text.encode("utf-8")),
                    },
                },
            },
            submitted_request_sha256=request_sha256,
            prior_attempt_id=prior_attempt_id,
            binding_error_status=True,
            action_type="IMPORT_RESPONSE",
        )

    def replace_response(
        self,
        run_id: str,
        *,
        response_text: str,
        request_sha256: str,
    ) -> dict[str, Any]:
        """Replace the response while retaining the prior attempt as history."""
        run = self.get(run_id)
        if run["status"] in TERMINAL_RUN_STATUSES:
            raise FoundryError(
                "CG1_REPLACE_RESPONSE_TERMINAL",
                "Replace Response is unavailable after a run is finalized, cancelled, or superseded.",
                status_code=409,
            )
        if run.get("execution_mode") != "MANUAL_CHAT":
            raise FoundryError(
                "CG1_REPLACE_RESPONSE_MODE_MISMATCH",
                "Replace Response is available only for a Manual Chat response run.",
                status_code=409,
            )
        prior_attempt_id = self._latest_attempt_id(run_id)
        # The prior accepted candidate remains immutable in the append-only
        # history.  This run row is only the latest-run projection and may be
        # cleared before the replacement is compiled.
        with self.db.transaction() as conn:
            conn.execute(
                """UPDATE character_creation_runs SET
                   transport_json='{}',response_json='{}',validation_json='{}',dry_run_json='{}',
                   final_plan_json='{}',owner_descriptive_fields_json='{}',accepted_descriptive_fields_json='{}',
                   quality_json='{}',owner_decision='REPLACE_RESPONSE',commit_json='{}',final_revision=NULL,
                   output_json='{}',blockers_json='[]',warnings_json='[]',status='WAITING_FOR_RESPONSE',completed_at=NULL,updated_at=?
                   WHERE run_id=?""",
                (utcnow(), run_id),
            )
        return self._apply_response(
            run_id,
            response_text,
            {
                "mode": "MANUAL_CHAT",
                "provider_called": False,
                "transfer": "replaced_response",
                "submitted_request_sha256": request_sha256,
                "prior_attempt_id": prior_attempt_id,
                "source_provenance": {
                    "schema": "TianxiaFoundry.CharacterCreationResponseSourceProvenance.v1",
                    "source_kind": "paste",
                    "filename": None,
                    "member_filename": None,
                    "archive_sha256": None,
                    "member_sha256": None,
                    "raw_byte_count": len(response_text.encode("utf-8")),
                    "raw_bytes_sha256": sha256_bytes(response_text.encode("utf-8")),
                    "archive_members": [],
                    "normalization": {
                        "encoding": "utf-8",
                        "bom_removed": False,
                        "outer_whitespace_stripped": False,
                        "normalized_text_bytes": len(response_text.encode("utf-8")),
                        "normalized_text_sha256": sha256_bytes(response_text.encode("utf-8")),
                        },
                },
            },
            submitted_request_sha256=request_sha256,
            prior_attempt_id=prior_attempt_id,
            binding_error_status=True,
            action_type="REPLACE_RESPONSE",
        )

    def replace_response_file(self, run_id: str, *, filename: str, payload: bytes) -> dict[str, Any]:
        """Replace a Manual Chat response from one bounded local file."""
        run = self.get(run_id)
        if run["status"] in TERMINAL_RUN_STATUSES:
            raise FoundryError(
                "CG1_REPLACE_RESPONSE_TERMINAL",
                "Replace Response is unavailable after a run is finalized, cancelled, or superseded.",
                status_code=409,
            )
        if run.get("execution_mode") != "MANUAL_CHAT":
            raise FoundryError(
                "CG1_REPLACE_RESPONSE_MODE_MISMATCH",
                "Replace Response is available only for a Manual Chat response run.",
                status_code=409,
            )
        prior_attempt_id = self._latest_attempt_id(run_id)
        try:
            response_text, upload = self._manual_response_text(filename, payload)
        except FoundryError as exc:
            self._record_manual_transport_failure(
                run_id,
                filename=filename,
                payload=payload,
                error=exc,
                action_type="REPLACE_RESPONSE",
                prior_attempt_id=prior_attempt_id,
            )
            raise
        with self.db.transaction() as conn:
            conn.execute(
                """UPDATE character_creation_runs SET
                   transport_json='{}',response_json='{}',validation_json='{}',dry_run_json='{}',
                   final_plan_json='{}',owner_descriptive_fields_json='{}',accepted_descriptive_fields_json='{}',
                   quality_json='{}',owner_decision='REPLACE_RESPONSE',commit_json='{}',final_revision=NULL,
                   output_json='{}',blockers_json='[]',warnings_json='[]',status='WAITING_FOR_RESPONSE',completed_at=NULL,updated_at=?
                   WHERE run_id=?""",
                (utcnow(), run_id),
            )
        return self._apply_response(
            run_id,
            response_text,
            {
                "mode": "MANUAL_CHAT",
                "provider_called": False,
                "transfer": "replaced_response_file",
                "submitted_request_sha256": run["request"].get("request_sha256"),
                "prior_attempt_id": prior_attempt_id,
                **upload,
            },
            submitted_request_sha256=run["request"].get("request_sha256"),
            prior_attempt_id=prior_attempt_id,
            binding_error_status=True,
            action_type="REPLACE_RESPONSE",
        )

    def _record_manual_transport_failure(
        self,
        run_id: str,
        *,
        filename: str,
        payload: bytes,
        error: FoundryError,
        action_type: str,
        prior_attempt_id: str | None = None,
    ) -> None:
        """Persist bounded file-transfer failures without accepting their bytes."""
        run = self.get(run_id)
        raw_filename = str(filename or "")
        suffix = Path(raw_filename).suffix.casefold()
        details = deepcopy(error.details or {})
        member_filename = details.get("member") if isinstance(details.get("member"), str) else None
        uploaded_sha256 = sha256_bytes(payload)
        provenance = {
            "schema": "TianxiaFoundry.CharacterCreationResponseSourceProvenance.v1",
            "source_kind": "zip" if suffix == ".zip" else "file",
            "filename": raw_filename,
            "uploaded_bytes": len(payload),
            "archive_sha256": uploaded_sha256 if suffix == ".zip" else None,
            "archive_bytes": len(payload) if suffix == ".zip" else None,
            "member_filename": member_filename,
            "member_sha256": None,
            "raw_byte_count": len(payload),
            "raw_bytes_sha256": uploaded_sha256,
            "archive_members": [],
            "normalization": {
                "encoding": "unknown",
                "bom_removed": None,
                "outer_whitespace_stripped": None,
                "normalized_text_bytes": None,
                "normalized_text_sha256": None,
            },
            "transfer_status": "rejected_before_response_decode",
        }
        transport = {
            "mode": "MANUAL_CHAT",
            "provider_called": False,
            "transfer": "rejected_response_file",
            "uploaded_filename": raw_filename,
            "uploaded_bytes": len(payload),
            "uploaded_sha256": uploaded_sha256,
            "submitted_request_sha256": (run.get("request") or {}).get("request_sha256"),
            "source_provenance": provenance,
        }
        diagnostic = {
            "schema": "TianxiaFoundry.CharacterCreationDiagnostic.v2",
            "code": error.code,
            "message": error.message,
            "details": details,
            "stage": self._diagnostic_stage(error.code),
            "category": self._diagnostic_stage(error.code),
            "boundary": self._diagnostic_boundary(error.code),
            "json_parsed": False,
            "response_retained": False,
        }
        validation = deepcopy(run.get("validation") or {})
        validation["last_submission_error"] = diagnostic
        with self.db.transaction() as conn:
            conn.execute(
                "UPDATE character_creation_runs SET transport_json=?,validation_json=?,updated_at=? WHERE run_id=?",
                (canonical_json(transport), canonical_json(validation), utcnow(), run_id),
            )
        self._append_attempt(
            run,
            action_type=action_type,
            status="BLOCKED",
            prior_attempt_id=prior_attempt_id or self._latest_attempt_id(run_id),
            binding={
                "submitted_request_sha256": (run.get("request") or {}).get("request_sha256"),
                "active_request_sha256": (run.get("request") or {}).get("request_sha256"),
                "transport": transport,
            },
            error=diagnostic,
        )

    def retry_local_build(
        self,
        run_id: str,
        *,
        _owner_decision_authorization: dict[str, Any] | None = None,
        _suppress_auto_finalize: bool = False,
    ) -> dict[str, Any]:
        """Recompile the exact persisted response without external I/O."""
        run = self.get(run_id)
        if run["status"] in TERMINAL_RUN_STATUSES:
            raise FoundryError(
                "CG1_RETRY_LOCAL_BUILD_TERMINAL",
                "Retry Local Build is unavailable after a terminal run state.",
                status_code=409,
            )
        response_projection = run.get("response") if isinstance(run.get("response"), Mapping) else {}
        response_text = response_projection.get("exact_response_text")
        if not isinstance(response_text, str) or not response_text:
            compact_response_sha256 = response_projection.get("response_sha256")
            if not isinstance(compact_response_sha256, str):
                raise FoundryError(
                    "CG1_RETRY_LOCAL_BUILD_RESPONSE_EVIDENCE_INVALID",
                    "Retry Local Build has no authenticated response digest to recover.",
                    status_code=409,
                )
            try:
                retained_evidence = self._retained_response_evidence(
                    run,
                    response_sha256=compact_response_sha256,
                )
            except FoundryError as exc:
                raise FoundryError(
                    "CG1_RETRY_LOCAL_BUILD_RESPONSE_EVIDENCE_INVALID",
                    "Retry Local Build could not authenticate the retained response leaf.",
                    details={"cause": exc.code, "cause_details": deepcopy(exc.details)},
                    status_code=409,
                ) from exc
            response_text = retained_evidence["response_text"]
            run["response"] = {
                **dict(response_projection),
                "exact_response_text": response_text,
                "response_sha256": compact_response_sha256,
            }
            run["_response_evidence"] = {
                "schema": _RESPONSE_EVIDENCE_SCHEMA,
                "kind": "RETAINED_ATTEMPT",
                "run_id": run.get("run_id"),
                "project_id": run.get("project_id"),
                "request_sha256": (run.get("request") or {}).get("request_sha256"),
                "response_sha256": compact_response_sha256,
                "attempt_id": retained_evidence.get("attempt_id"),
                "attempt_ordinal": retained_evidence.get("attempt_ordinal"),
            }
        request_sha256 = (run.get("request") or {}).get("request_sha256")
        submitted = (run.get("transport") or {}).get("submitted_request_sha256")
        if not isinstance(response_text, str) or not response_text:
            raise FoundryError(
                "CG1_RETRY_LOCAL_BUILD_RESPONSE_MISSING",
                "Retry Local Build requires the exact persisted response; import or replace a response first.",
                status_code=409,
            )
        if submitted not in {None, request_sha256}:
            raise FoundryError(
                RESPONSE_BINDING_ERROR,
                RESPONSE_BINDING_MESSAGE,
                details={"submitted_request_sha256": submitted, "active_request_sha256": request_sha256},
                status_code=409,
            )
        prior_transport = run.get("transport") or {}
        retained_provider_id = prior_transport.get("provider_id")
        selected_provider_id = (
            None
            if self._is_dcc_route_run(run)
            else self._provider_selected_id()
        )
        # Prefer the currently selected profile for the recovery proof.  If a
        # retained explicit correction names a different profile, the proof
        # below becomes invalid instead of silently trusting stale lineage.
        recovery_provider_id = (
            selected_provider_id
            if isinstance(selected_provider_id, str) and selected_provider_id.strip()
            else retained_provider_id
        )
        # A failed explicit local correction may have replaced the durable
        # response with a tiny malformed object.  Recover only when the
        # append-only one-hop proof identifies that exact correction and the
        # original allowlisted provider diagnostic.  The recovery itself is a
        # normal local compilation and never invokes the provider.
        recovery_candidate, recovered = self._recover_scoped_local_correction_context(
            run,
            provider_id=recovery_provider_id,
            strict_retry=True,
        )
        if recovery_candidate:
            if not isinstance(recovered, dict):
                raise FoundryError(
                    "CG1_RETRY_LOCAL_BUILD_RECOVERY_INVALID",
                    "The retained explicit local-correction lineage could not prove an exact prior response; no retry was applied.",
                    status_code=409,
                )
            recovered_response = recovered.get("response_text")
            recovered_response_sha256 = recovered.get("response_sha256")
            recovered_diagnostic = recovered.get("diagnostic")
            recovered_from_attempt_id = recovered.get("recovered_from_attempt_id")
            restored_attempt_id = recovered.get("restored_attempt_id")
            if (
                not isinstance(recovered_response, str)
                or not recovered_response.strip()
                or not isinstance(recovered_response_sha256, str)
                or recovered_response_sha256 != sha256_bytes(recovered_response.encode("utf-8"))
                or not isinstance(recovered_diagnostic, dict)
                or recovered_diagnostic.get("code") not in _LOCAL_PROVIDER_CORRECTION_CODES
                or not isinstance(recovered_from_attempt_id, str)
                or not recovered_from_attempt_id.strip()
                or not isinstance(restored_attempt_id, str)
                or not restored_attempt_id.strip()
            ):
                raise FoundryError(
                    "CG1_RETRY_LOCAL_BUILD_RECOVERY_INVALID",
                    "The retained explicit local-correction recovery evidence was malformed; no retry was applied.",
                    status_code=409,
                )
            recovery_transport = {
                "mode": run.get("execution_mode"),
                "provider_called": False,
                "automatic_retries": 0,
                "transfer": "retry_local_build",
                "submitted_request_sha256": request_sha256,
                "prior_attempt_id": recovered_from_attempt_id,
                "provider_id": recovery_provider_id,
                "local_recovery": {
                    "schema": "TianxiaFoundry.LocalProviderRecoveryReceipt.v1",
                    "provider_called": False,
                    "automatic_retries": 0,
                    "recovered_from_attempt_id": recovered_from_attempt_id,
                    "restored_attempt_id": restored_attempt_id,
                    "request_sha256": request_sha256,
                    "prior_response_sha256": recovered_response_sha256,
                    "original_diagnostic": deepcopy(recovered_diagnostic),
                },
            }
            for key in ("source_provenance", "uploaded_filename", "response_member", "uploaded_sha256"):
                if key in prior_transport:
                    recovery_transport[key] = deepcopy(prior_transport[key])
            return self._apply_response(
                run_id,
                recovered_response,
                recovery_transport,
                submitted_request_sha256=request_sha256,
                prior_attempt_id=recovered_from_attempt_id,
                binding_error_status=False,
                action_type="RETRY_LOCAL_BUILD",
                _owner_decision_authorization=_owner_decision_authorization,
                _suppress_auto_finalize=_suppress_auto_finalize,
            )
        prior_attempt_id = self._latest_attempt_id(run_id)
        legacy_retry_bypass = self._legacy_retry_bypass_context(run, response_text)
        if isinstance(legacy_retry_bypass, dict):
            prior_attempt_id = legacy_retry_bypass["linked_prior_attempt_id"]
        retry_transport = {
            "mode": run.get("execution_mode"),
            "provider_called": False,
            "automatic_retries": 0,
            "transfer": "retry_local_build",
            "submitted_request_sha256": request_sha256,
            "prior_attempt_id": prior_attempt_id,
        }
        if isinstance(legacy_retry_bypass, dict):
            retry_transport["legacy_retry_bypass"] = deepcopy(legacy_retry_bypass)
        for key in ("source_provenance", "uploaded_filename", "response_member", "uploaded_sha256"):
            if key in prior_transport:
                retry_transport[key] = deepcopy(prior_transport[key])
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        diagnostic = validation.get("last_submission_error")
        if not isinstance(diagnostic, dict):
            diagnostic = run.get("submission_error")
        repair_target = self._provider_target_scoped_repair_target(
            diagnostic,
            run=run,
            prior_response=response_text,
        ) if isinstance(diagnostic, dict) else None
        if (
            _owner_decision_authorization is None
            and isinstance(repair_target, dict)
            and repair_target.get("target_kind") in {
                "free_talent_sphere_server_repair",
                "ordinary_duplicate",
                _ORDINARY_ORDER_MIRROR_TARGET_KIND,
                "bounded_field_cleanup",
                "bounded_path_progression_singleton",
                "bounded_path_progression_empty_cleanup",
            }
        ):
            provider_id = prior_transport.get("provider_id")
            if (
                not isinstance(provider_id, str)
                or not provider_id.strip()
            ) and not self._is_dcc_route_run(run):
                provider_id = self._provider_selected_id()
            if isinstance(provider_id, str) and provider_id.strip():
                return self._apply_deterministic_server_repair(
                    run_id,
                    run=run,
                    provider_id=provider_id,
                    prior_attempt_id=prior_attempt_id,
                    prior_response=response_text,
                    diagnostic=diagnostic,
                    repair_target=repair_target,
                    explicit=False,
                )
        return self._apply_response(
            run_id,
            response_text,
            retry_transport,
            submitted_request_sha256=request_sha256,
            prior_attempt_id=prior_attempt_id,
            binding_error_status=False,
            action_type="RETRY_LOCAL_BUILD",
            _owner_decision_authorization=_owner_decision_authorization,
            _suppress_auto_finalize=_suppress_auto_finalize,
        )

    @staticmethod
    def _decision_slot_from_details(details: Any) -> str | None:
        if not isinstance(details, dict):
            return None
        explicit = details.get("slot_id")
        if isinstance(explicit, str) and explicit.strip():
            return explicit.strip()
        field = details.get("field")
        if not isinstance(field, str):
            return None
        known = (
            "background_sphere_choice", "background_talent_choice", "origin_insight_choice",
            "advancement_skeleton", "sphere_priorities", "insight_priorities", "item_priorities",
            "subpath_choice", "method_choice", "foundation_choice", "path_choice", "background_choice",
        )
        return next((slot for slot in known if field == slot or field.startswith(slot + ".")), None)

    @staticmethod
    def _owner_decision_id(
        run: dict[str, Any],
        *,
        field: str,
        slot_id: str | None,
        operation: str = "replace_slot_value",
        blocker_sha256: str | None = None,
    ) -> str:
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        response = run.get("response") if isinstance(run.get("response"), dict) else {}
        binding = {
            "run_id": run.get("run_id"),
            "field": field,
            "slot_id": slot_id,
            "operation": operation,
            "blocker_sha256": blocker_sha256,
            "request_sha256": request.get("request_sha256"),
            "response_sha256": response.get("response_sha256"),
            "content_lock_hash": request.get("content_lock_hash"),
        }
        return "cg1.decision." + sha256_json(binding)[:32]

    @staticmethod
    def _owner_resolution_batch_sha256(resolutions: Any) -> str:
        """Hash the ordered, persisted owner-resolution batch exactly."""
        rows = deepcopy(resolutions) if isinstance(resolutions, list) else []
        return sha256_json(rows)

    @classmethod
    def _owner_resolution_batch_marker(
        cls,
        resolutions: Any,
        *,
        response_sha256: str,
        status: str,
    ) -> dict[str, Any]:
        rows = deepcopy(resolutions) if isinstance(resolutions, list) else []
        return {
            "schema": _OWNER_RESOLUTION_BATCH_SCHEMA,
            "batch_sha256": cls._owner_resolution_batch_sha256(rows),
            "resolution_count": len(rows),
            "response_sha256": response_sha256,
            "status": status,
        }

    @classmethod
    def _owner_resolution_batch_is_applied(
        cls,
        validation: Any,
        resolutions: Any,
        *,
        response_sha256: str,
    ) -> bool:
        if not isinstance(validation, dict):
            return False
        marker = validation.get("owner_resolution_batch")
        if not isinstance(marker, dict):
            return False
        expected = cls._owner_resolution_batch_marker(
            resolutions,
            response_sha256=response_sha256,
            status="APPLIED",
        )
        return (
            marker.get("schema") == expected["schema"]
            and marker.get("batch_sha256") == expected["batch_sha256"]
            and marker.get("resolution_count") == expected["resolution_count"]
            and marker.get("response_sha256") == expected["response_sha256"]
            and marker.get("status") == expected["status"]
            and validation.get("owner_resolution_batch_sha256") == expected["batch_sha256"]
        )

    @classmethod
    def _owner_resolution_batch_is_pending(
        cls,
        validation: Any,
        resolutions: Any,
        *,
        response_sha256: str,
    ) -> bool:
        if not isinstance(validation, dict):
            return False
        marker = validation.get("owner_resolution_batch")
        if not isinstance(marker, dict):
            return False
        expected = cls._owner_resolution_batch_marker(
            resolutions,
            response_sha256=response_sha256,
            status="PENDING",
        )
        return (
            marker.get("schema") == expected["schema"]
            and marker.get("batch_sha256") == expected["batch_sha256"]
            and marker.get("resolution_count") == expected["resolution_count"]
            and marker.get("response_sha256") == expected["response_sha256"]
            and marker.get("status") == expected["status"]
            and validation.get("owner_resolution_batch_sha256") == expected["batch_sha256"]
        )

    @classmethod
    def _owner_resolution_batch_state(
        cls,
        validation: Any,
        resolutions: Any,
        *,
        response_sha256: str,
    ) -> str:
        """Return the durable batch state, including the pre-marker legacy state."""
        if not isinstance(validation, dict):
            return "INVALID"
        marker_present = "owner_resolution_batch" in validation
        scalar_present = "owner_resolution_batch_sha256" in validation
        if not marker_present and not scalar_present:
            return "LEGACY"
        if cls._owner_resolution_batch_is_applied(
            validation,
            resolutions,
            response_sha256=response_sha256,
        ):
            return "APPLIED"
        if cls._owner_resolution_batch_is_pending(
            validation,
            resolutions,
            response_sha256=response_sha256,
        ):
            return "PENDING"
        return "INVALID"

    @staticmethod
    def _owner_resolution_is_bound(
        resolution: Any,
        *,
        run_id: str,
        request_sha256: str,
        response_sha256: str,
        content_lock_hash: str,
    ) -> bool:
        if not isinstance(resolution, dict):
            return False
        binding = resolution.get("binding")
        return (
            resolution.get("schema") == "TianxiaFoundry.OwnerDecisionResolution.v1"
            and isinstance(resolution.get("decision_id"), str)
            and bool(resolution.get("decision_id"))
            and isinstance(resolution.get("field"), str)
            and bool(resolution.get("field"))
            and isinstance(resolution.get("operation"), str)
            and bool(resolution.get("operation"))
            and isinstance(binding, dict)
            and binding.get("run_id") == run_id
            and binding.get("request_sha256") == request_sha256
            and binding.get("response_sha256") == response_sha256
            and binding.get("content_lock_hash") == content_lock_hash
            and isinstance(binding.get("blocker_sha256"), str)
            and bool(binding.get("blocker_sha256"))
        )

    @staticmethod
    def _owner_resolution_hash(value: Any) -> bool:
        """Return whether ``value`` is a canonical hexadecimal SHA-256."""
        if not isinstance(value, str) or len(value) != 64:
            return False
        return all(character in "0123456789abcdefABCDEF" for character in value)

    @classmethod
    def _owner_resolution_is_retry_structurally_valid(
        cls,
        resolution: Any,
        *,
        run_id: str,
        request_sha256: str,
        response_sha256: str,
        content_lock_hash: str,
    ) -> bool:
        """Validate one persisted resolution before granting restart authority.

        Owner resolutions normally reach this boundary through
        ``resolve_owner_decision``.  A restart, however, has no in-memory
        capability to carry forward.  Keep the replacement capability
        deliberately narrower than the normal overlay applicator: only the
        exact persisted JSON shape and the finite set of server-owned
        operations can participate in a restart resume.
        """
        if not isinstance(resolution, dict):
            return False
        if set(resolution) != {
            "schema", "decision_id", "field", "slot_id", "operation",
            "target_value", "value", "binding",
        }:
            return False
        if (
            not isinstance(run_id, str) or not run_id.strip()
            or not cls._owner_resolution_hash(request_sha256)
            or not cls._owner_resolution_hash(response_sha256)
            or not isinstance(content_lock_hash, str) or not content_lock_hash.strip()
        ):
            return False
        if not cls._owner_resolution_is_bound(
            resolution,
            run_id=run_id,
            request_sha256=request_sha256,
            response_sha256=response_sha256,
            content_lock_hash=content_lock_hash,
        ):
            return False
        binding = resolution.get("binding")
        if not isinstance(binding, dict) or set(binding) != {
            "run_id", "request_sha256", "response_sha256",
            "content_lock_hash", "blocker_sha256",
        } or not cls._owner_resolution_hash(binding.get("blocker_sha256")):
            return False
        decision_id = resolution.get("decision_id")
        field = resolution.get("field")
        slot_id = resolution.get("slot_id")
        operation = resolution.get("operation")
        if (
            not isinstance(decision_id, str) or not decision_id.strip()
            or decision_id != decision_id.strip()
            or not isinstance(field, str) or not field.strip()
            or field != field.strip()
            or not isinstance(operation, str) or not operation.strip()
            or operation != operation.strip()
            or (slot_id is not None and (
                not isinstance(slot_id, str) or not slot_id.strip()
                or slot_id != slot_id.strip()
            ))
        ):
            return False
        allowed_operations = {
            "replace_slot_value",
            "replace_slot_list",
            "add_slot_value",
            "remove_slot_value",
            "set_field",
            "set_milestone_choice",
        }
        if operation not in allowed_operations:
            return False
        value = resolution.get("value")
        if operation == "replace_slot_list":
            if not isinstance(value, list) or any(item is None for item in value):
                return False
        elif operation == "set_milestone_choice":
            if not isinstance(value, dict):
                return False
            milestone_id = value.get("milestone_id")
            if not isinstance(milestone_id, str) or not milestone_id.strip() or milestone_id != milestone_id.strip():
                return False
            kind = value.get("kind")
            choice_kind = value.get("choice_kind")
            if kind is not None and choice_kind is not None and kind != choice_kind:
                return False
            kind = kind if kind is not None else choice_kind
            if not isinstance(kind, str) or kind.strip().lower() not in {
                "asi", "ability_score_change", "insight",
                "cultivation_insight_acquisition", "remove", "none",
            }:
                return False
            if kind.strip().lower() in {"asi", "ability_score_change"}:
                deltas = value.get("deltas")
                if (
                    not isinstance(deltas, dict) or not deltas
                    or any(
                        not isinstance(ability, str) or not ability.strip()
                        or type(delta) is not int
                        for ability, delta in deltas.items()
                    )
                ):
                    return False
            elif kind.strip().lower() in {"insight", "cultivation_insight_acquisition"}:
                insight_id = value.get("insight_id")
                if not isinstance(insight_id, str) or not insight_id.strip() or insight_id != insight_id.strip():
                    return False
                if "parameters" in value and not isinstance(value.get("parameters"), dict):
                    return False
        elif operation in {"replace_slot_value", "add_slot_value", "remove_slot_value"} and slot_id is not None:
            if value is None or isinstance(value, (dict, list, tuple, set)):
                return False
        elif operation == "set_field" and "value" not in resolution:
            return False
        if isinstance(field, str) and field.startswith("acquisition_intent.ordinary_talent_ids."):
            if not isinstance(value, str) or not value.strip() or value != value.strip():
                return False
        return True

    @classmethod
    def _owner_decision_authorization_for_pending_retry(
        cls,
        run: dict[str, Any],
        response_text: str,
    ) -> dict[str, Any] | None:
        """Rebuild the private owner capability from an exact PENDING batch.

        This is intentionally *not* called by generic Retry Local Build.  It
        is used only after either a current owner control or the explicit
        clean-finalization gate proves the persisted batch is the exact
        source-backed owner state being resumed.  Keeping this helper
        side-effect free means a malformed or stale batch simply follows the
        ordinary fail-closed owner path.
        """
        if not isinstance(run, dict) or not isinstance(response_text, str) or not response_text:
            return None
        run_id = run.get("run_id")
        request = run.get("request") if isinstance(run.get("request"), dict) else None
        response = run.get("response") if isinstance(run.get("response"), dict) else None
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else None
        if not isinstance(run_id, str) or not run_id.strip() or not isinstance(request, dict) or not isinstance(response, dict) or not isinstance(validation, dict):
            return None
        request_sha256 = request.get("request_sha256")
        content_lock_hash = request.get("content_lock_hash")
        response_sha256 = sha256_bytes(response_text.encode("utf-8"))
        persisted_response_text = response.get("exact_response_text")
        if (
            not isinstance(request_sha256, str)
            or not isinstance(content_lock_hash, str)
            or not cls._owner_resolution_hash(request_sha256)
            or not content_lock_hash.strip()
            or cls.request_payload_sha256(request) != request_sha256
            or persisted_response_text != response_text
            or response.get("response_sha256") != response_sha256
            or sha256_bytes(persisted_response_text.encode("utf-8")) != response_sha256
        ):
            return None
        resolutions = validation.get("owner_resolutions")
        if not isinstance(resolutions, list) or not resolutions:
            return None
        if not all(
            cls._owner_resolution_is_retry_structurally_valid(
                resolution,
                run_id=run_id,
                request_sha256=request_sha256,
                response_sha256=response_sha256,
                content_lock_hash=content_lock_hash,
            )
            for resolution in resolutions
        ):
            return None
        decision_ids = [resolution.get("decision_id") for resolution in resolutions]
        if len(decision_ids) != len(set(decision_ids)):
            return None
        if cls._owner_resolution_batch_state(
            validation,
            resolutions,
            response_sha256=response_sha256,
        ) != "PENDING":
            return None
        expected_marker = cls._owner_resolution_batch_marker(
            resolutions,
            response_sha256=response_sha256,
            status="PENDING",
        )
        if (
            validation.get("owner_resolution_batch") != expected_marker
            or validation.get("owner_resolution_batch_sha256") != expected_marker["batch_sha256"]
        ):
            return None
        return {
            "authority": _OWNER_DECISION_TRANSITION_AUTHORITY,
            "run_id": run_id,
            "request_sha256": request_sha256,
            "response_sha256": response_sha256,
            "content_lock_hash": content_lock_hash,
            "owner_resolution_batch_sha256": expected_marker["batch_sha256"],
            "resolution_count": len(resolutions),
        }

    def _owner_resolution_for_restart_control(
        self,
        run: dict[str, Any],
        *,
        decision_id: str,
        field: str,
        slot_id: str | None,
        operation: str,
        target_value: Any,
        value: Any,
        response_text: str,
        require_persisted_resolution: bool = True,
        require_pending_authorization: bool = True,
    ) -> dict[str, Any] | None:
        """Find the one pending resolution represented by a current control."""
        if operation != "set_milestone_choice" or not isinstance(value, dict):
            return None
        milestone_id = value.get("milestone_id")
        if not isinstance(milestone_id, str) or not milestone_id.strip():
            return None
        authorization = (
            self._owner_decision_authorization_for_pending_retry(run, response_text)
            if require_pending_authorization
            else None
        )
        if require_pending_authorization and authorization is None:
            return None
        raw_blockers: list[dict[str, Any]] = []
        for blocker in run.get("blockers") or []:
            if not isinstance(blocker, dict):
                continue
            details = blocker.get("details") if isinstance(blocker.get("details"), dict) else {}
            nested = details.get("milestone") if isinstance(details.get("milestone"), dict) else {}
            raw_milestone_id = details.get("milestone_id") or nested.get("milestone_id")
            if raw_milestone_id == milestone_id:
                raw_blockers.append(details)
        if len(raw_blockers) != 1:
            return None
        raw_details = raw_blockers[0]
        raw_field = raw_details.get("field") or raw_details.get("slot_id") or "owner decision"
        raw_field = str(raw_field) if isinstance(raw_field, str) else "owner decision"
        raw_slot = self._decision_slot_from_details(raw_details)
        raw_operation = raw_details.get("operation") or raw_details.get("decision_operation")
        if raw_operation not in {None, "set_milestone_choice"} or field != raw_field or slot_id != raw_slot:
            return None
        expected_decision_id = self._owner_decision_id(
            run,
            field=field,
            slot_id=slot_id,
            operation=operation,
            blocker_sha256=sha256_json(raw_details),
        )
        if decision_id != expected_decision_id:
            return None

        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        proposal = validation.get("proposal_projection") if isinstance(validation.get("proposal_projection"), dict) else {}
        current_overlay_plan: dict[str, Any] = {}
        try:
            parsed_response = json.loads(response_text)
            if isinstance(parsed_response, dict):
                current_overlay_plan = self._apply_owner_resolutions(run, parsed_response)
        except (FoundryError, TypeError, ValueError, json.JSONDecodeError):
            return None
        if current_overlay_plan:
            proposal = self._proposal_projection(current_overlay_plan)
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        envelope = request.get("delegated_choice_envelope") if isinstance(request.get("delegated_choice_envelope"), dict) else {}
        enriched = enrich_milestone_details(
            raw_details,
            envelope=envelope,
            proposal_bounded=proposal.get("bounded_choices") if isinstance(proposal.get("bounded_choices"), dict) else {},
            proposal_acquisition=proposal.get("acquisition_intent") if isinstance(proposal.get("acquisition_intent"), dict) else {},
            proposal_selected_by_slot=proposal.get("selected_by_slot") if isinstance(proposal.get("selected_by_slot"), dict) else {},
            authority_by_milestone=run.get("owner_decision_authority") if isinstance(run.get("owner_decision_authority"), dict) else {},
        )
        legal_choices = enriched.get("legal_choices") if isinstance(enriched.get("legal_choices"), list) else []
        if not any(
            isinstance(choice, dict) and choice.get("value") == value
            for choice in legal_choices
        ):
            return None
        resolutions = validation.get("owner_resolutions")
        matching = [
            resolution
            for resolution in resolutions
            if isinstance(resolution, dict)
            and resolution.get("operation") == operation
            and resolution.get("value") == value
            and resolution.get("target_value") == target_value
            and resolution.get("slot_id") == slot_id
            and isinstance(resolution.get("value"), dict)
            and resolution["value"].get("milestone_id") == milestone_id
            and (resolution.get("binding") or {}).get("run_id") == run.get("run_id")
            and (resolution.get("binding") or {}).get("request_sha256") == request.get("request_sha256")
            and (resolution.get("binding") or {}).get("response_sha256") == (run.get("response") or {}).get("response_sha256")
            and (resolution.get("binding") or {}).get("content_lock_hash") == request.get("content_lock_hash")
        ]
        if len(matching) != 1:
            if require_persisted_resolution or matching:
                return None
            return {
                "authorization": authorization,
                "resolution": None,
                "raw_details": deepcopy(raw_details),
                "blocker_sha256": sha256_json(raw_details),
            }
        return {
            "authorization": authorization,
            "resolution": deepcopy(matching[0]),
            "raw_details": deepcopy(raw_details),
            "blocker_sha256": sha256_json(raw_details),
        }

    def _owner_resolution_for_restart_migration_control(
        self,
        run: dict[str, Any],
        *,
        decision_id: str,
        field: str,
        slot_id: str | None,
        operation: str,
        target_value: Any,
        value: Any,
        response_text: str,
        require_pending_batch: bool = True,
    ) -> dict[str, Any] | None:
        """Prove a pre-fix pending batch may expose its next milestone."""
        if operation != "set_milestone_choice" or not isinstance(value, dict):
            return None
        milestone_id = value.get("milestone_id")
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        response = run.get("response") if isinstance(run.get("response"), dict) else {}
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        authorization = (
            self._owner_decision_authorization_for_pending_retry(run, response_text)
            if require_pending_batch
            else None
        )
        if require_pending_batch and authorization is None:
            return None
        diagnostic = validation.get("last_submission_error")
        next_milestone_id = self._owner_transition_next_milestone_id(
            diagnostic,
            validation.get("owner_resolutions"),
            run_id=run.get("run_id"),
            request_sha256=request.get("request_sha256"),
            response_sha256=response.get("response_sha256"),
            content_lock_hash=request.get("content_lock_hash"),
        )
        if not isinstance(milestone_id, str) or milestone_id != next_milestone_id:
            return None
        diagnostic_details = diagnostic.get("details") if isinstance(diagnostic, dict) else None
        if not isinstance(diagnostic_details, dict):
            return None
        raw_blockers: list[dict[str, Any]] = []
        for blocker in run.get("blockers") or []:
            if not isinstance(blocker, dict):
                continue
            details = blocker.get("details") if isinstance(blocker.get("details"), dict) else {}
            nested = details.get("milestone") if isinstance(details.get("milestone"), dict) else {}
            raw_milestone_id = details.get("milestone_id") or nested.get("milestone_id")
            if raw_milestone_id == milestone_id:
                raw_blockers.append(blocker)
        if (
            len(raw_blockers) != 1
            or raw_blockers[0].get("code") != diagnostic.get("code")
            or raw_blockers[0].get("details") != diagnostic_details
        ):
            return None
        proof = self._owner_resolution_for_restart_control(
            run,
            decision_id=decision_id,
            field=field,
            slot_id=slot_id,
            operation=operation,
            target_value=target_value,
            value=value,
            response_text=response_text,
            require_persisted_resolution=False,
            require_pending_authorization=require_pending_batch,
        )
        if proof is None or (
            require_pending_batch and proof.get("authorization") != authorization
        ):
            return None
        return {
            **proof,
            "next_milestone_id": next_milestone_id,
            "diagnostic": deepcopy(diagnostic),
        }

    def _promote_owner_resolution_batch_for_restart(
        self,
        run: dict[str, Any],
        control: dict[str, Any],
        *,
        run_id: str,
        decision_id: str,
        field: str,
        slot_id: str | None,
        operation: str,
        target_value: Any,
        value: Any,
        request_sha256: str,
        response_sha256: str,
        content_lock_hash: str,
        response_text: str,
    ) -> str:
        """Atomically promote one pre-fix batch after rechecking its proof."""
        with self.db.transaction() as conn:
            row = conn.execute(
                "SELECT project_id,request_json,response_json,validation_json,blockers_json,status "
                "FROM character_creation_runs WHERE run_id=?",
                (run_id,),
            ).fetchone()
            if row is None:
                raise FoundryError("CG1_RUN_NOT_FOUND", "No character build run has that ID.", status_code=404)
            try:
                current_request = json.loads(row["request_json"] or "{}")
                current_response = json.loads(row["response_json"] or "{}")
                current_validation = json.loads(row["validation_json"] or "{}")
                current_blockers = json.loads(row["blockers_json"] or "[]")
            except (TypeError, json.JSONDecodeError) as exc:
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted restart-migration state is not valid JSON.",
                    status_code=409,
                ) from exc
            if (
                not isinstance(current_request, dict)
                or not isinstance(current_response, dict)
                or not isinstance(current_validation, dict)
                or not isinstance(current_blockers, list)
            ):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted restart-migration state has an invalid shape.",
                    status_code=409,
                )
            current_run = {
                **run,
                "project_id": row["project_id"],
                "request": current_request,
                "response": current_response,
                "validation": current_validation,
                "blockers": current_blockers,
                "status": row["status"],
            }
            persisted_project_id = row["project_id"]
            if (
                not isinstance(persisted_project_id, str)
                or not persisted_project_id.strip()
                or run.get("project_id") != persisted_project_id
                or current_request.get("project_id") != persisted_project_id
            ):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted restart-migration run identity changed; no batch promotion was applied.",
                    status_code=409,
                )
            if row["status"] in TERMINAL_RUN_STATUSES:
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The owner-resolution batch cannot be migrated after the run became terminal.",
                    status_code=409,
                )
            persisted_request_sha256 = current_request.get("request_sha256")
            persisted_content_lock_hash = current_request.get("content_lock_hash")
            if (
                not isinstance(persisted_request_sha256, str)
                or self.request_payload_sha256(current_request) != persisted_request_sha256
                or persisted_request_sha256 != request_sha256
                or not isinstance(persisted_content_lock_hash, str)
                or not persisted_content_lock_hash.strip()
                or persisted_content_lock_hash != content_lock_hash
            ):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted restart-migration request no longer matches its bound receipt.",
                    status_code=409,
                )
            expected_binding = {
                "request_sha256": current_request.get("request_sha256"),
                "response_sha256": current_response.get("response_sha256"),
                "content_lock_hash": current_request.get("content_lock_hash"),
            }
            if expected_binding != {
                "request_sha256": request_sha256,
                "response_sha256": response_sha256,
                "content_lock_hash": content_lock_hash,
            }:
                raise FoundryError(
                    "CG1_DECISION_BINDING_MISMATCH",
                    "The persisted restart-migration binding changed; reload the current owner decision.",
                    status_code=409,
                )
            persisted_text = current_response.get("exact_response_text")
            if (
                persisted_text != response_text
                or not isinstance(persisted_text, str)
                or sha256_bytes(persisted_text.encode("utf-8")) != response_sha256
            ):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted restart-migration response changed; no batch promotion was applied.",
                    status_code=409,
                )
            current_rows = current_validation.get("owner_resolutions")
            current_rows = current_rows if isinstance(current_rows, list) else []
            state = self._owner_resolution_batch_state(
                current_validation,
                current_rows,
                response_sha256=response_sha256,
            )
            if state == "APPLIED":
                control_authorization = control.get("authorization")
                if (
                    not isinstance(control_authorization, dict)
                    or control_authorization.get("owner_resolution_batch_sha256")
                    != self._owner_resolution_batch_sha256(current_rows)
                    or control_authorization.get("resolution_count") != len(current_rows)
                ):
                    raise FoundryError(
                        "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                        "The already-applied owner-resolution batch is not the exact batch being resumed.",
                        status_code=409,
                    )
                current_control = self._owner_resolution_for_restart_migration_control(
                    current_run,
                    decision_id=decision_id,
                    field=field,
                    slot_id=slot_id,
                    operation=operation,
                    target_value=target_value,
                    value=value,
                    response_text=response_text,
                    require_pending_batch=False,
                )
                if (
                    current_control is None
                    or current_control.get("next_milestone_id") != control.get("next_milestone_id")
                    or current_control.get("blocker_sha256") != control.get("blocker_sha256")
                    or current_control.get("raw_details") != control.get("raw_details")
                    or current_control.get("diagnostic") != control.get("diagnostic")
                ):
                    raise FoundryError(
                        "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                        "The persisted restart-migration blocker or legal control changed; no batch promotion was applied.",
                        status_code=409,
                    )
                return "APPLIED"
            current_authorization = self._owner_decision_authorization_for_pending_retry(
                current_run,
                response_text,
            )
            if state != "PENDING" or current_authorization is None or current_authorization != control.get("authorization"):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted restart-migration batch is no longer the exact pending batch.",
                    status_code=409,
                )
            current_control = self._owner_resolution_for_restart_migration_control(
                current_run,
                decision_id=decision_id,
                field=field,
                slot_id=slot_id,
                operation=operation,
                target_value=target_value,
                value=value,
                response_text=response_text,
            )
            if (
                current_control is None
                or current_control.get("authorization") != current_authorization
                or current_control.get("next_milestone_id") != control.get("next_milestone_id")
                or current_control.get("blocker_sha256") != control.get("blocker_sha256")
                or current_control.get("diagnostic") != control.get("diagnostic")
            ):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The current restart-migration blocker or legal control changed; no batch promotion was applied.",
                    status_code=409,
                )
            next_validation = deepcopy(current_validation)
            next_validation["owner_resolution_batch"] = self._owner_resolution_batch_marker(
                current_rows,
                response_sha256=response_sha256,
                status="APPLIED",
            )
            next_validation["owner_resolution_batch_sha256"] = self._owner_resolution_batch_sha256(current_rows)
            conn.execute(
                "UPDATE character_creation_runs SET validation_json=?,updated_at=? WHERE run_id=?",
                (canonical_json(next_validation), utcnow(), run_id),
            )
            return "PROMOTED"

    @classmethod
    def _owner_decision_transition_is_authorized(
        cls,
        run: dict[str, Any],
        response_text: str,
        authorization: Any,
    ) -> bool:
        """Validate the non-serializable capability used only by the resolver."""
        if not isinstance(authorization, dict) or authorization.get("authority") is not _OWNER_DECISION_TRANSITION_AUTHORITY:
            return False
        response_sha256 = sha256_bytes(response_text.encode("utf-8"))
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        response = run.get("response") if isinstance(run.get("response"), dict) else {}
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        resolutions = validation.get("owner_resolutions")
        request_hash_valid = (
            isinstance(request, dict)
            and request.get("request_sha256") == cls.request_payload_sha256(request)
        )
        return (
            authorization.get("run_id") == run.get("run_id")
            and authorization.get("request_sha256") == request.get("request_sha256")
            and authorization.get("content_lock_hash") == request.get("content_lock_hash")
            and request_hash_valid
            and authorization.get("response_sha256") == response_sha256
            and response.get("response_sha256") == response_sha256
            and isinstance(resolutions, list)
            and bool(resolutions)
            and all(
                cls._owner_resolution_is_bound(
                    resolution,
                    run_id=run.get("run_id"),
                    request_sha256=request.get("request_sha256"),
                    response_sha256=response_sha256,
                    content_lock_hash=request.get("content_lock_hash"),
                )
                for resolution in resolutions
            )
            and authorization.get("owner_resolution_batch_sha256") == cls._owner_resolution_batch_sha256(resolutions)
            and authorization.get("resolution_count") == len(resolutions)
        )

    @classmethod
    def _require_applied_owner_resolution_batch(
        cls,
        run: dict[str, Any],
        *,
        response_sha256: str,
    ) -> list[dict[str, Any]] | None:
        """Validate the immutable owner overlay before finalization."""
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        if "owner_resolutions" not in validation:
            return None
        raw_resolutions = validation.get("owner_resolutions")
        if not isinstance(raw_resolutions, list) or not raw_resolutions or any(
            not isinstance(row, dict) for row in raw_resolutions
        ):
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The persisted owner-resolution collection is malformed for finalization.",
                status_code=409,
            )
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        response = run.get("response") if isinstance(run.get("response"), dict) else {}
        request_sha256 = request.get("request_sha256")
        content_lock_hash = request.get("content_lock_hash")
        if (
            not isinstance(run.get("run_id"), str)
            or not isinstance(request_sha256, str)
            or not isinstance(content_lock_hash, str)
            or not content_lock_hash
            or cls.request_payload_sha256(request) != request_sha256
            or response.get("response_sha256") != response_sha256
            or not isinstance(response.get("exact_response_text"), str)
            or sha256_bytes(response["exact_response_text"].encode("utf-8")) != response_sha256
        ):
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The owner-resolution batch is not bound to the exact persisted request and response.",
                status_code=409,
            )
        if not all(
            cls._owner_resolution_is_bound(
                row,
                run_id=run["run_id"],
                request_sha256=request_sha256,
                response_sha256=response_sha256,
                content_lock_hash=content_lock_hash,
            )
            for row in raw_resolutions
        ):
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The owner-resolution batch contains a stale or malformed binding.",
                status_code=409,
            )
        decision_ids = [row["decision_id"] for row in raw_resolutions]
        if len(decision_ids) != len(set(decision_ids)):
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The owner-resolution batch contains duplicate decision IDs.",
                status_code=409,
            )
        if not cls._owner_resolution_batch_is_applied(
            validation,
            raw_resolutions,
            response_sha256=response_sha256,
        ):
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The owner-resolution batch is not the exact applied batch reviewed for finalization.",
                status_code=409,
            )
        return deepcopy(raw_resolutions)

    def _recover_pending_owner_resolution_for_finalization(
        self,
        run: dict[str, Any],
        *,
        response_text: str,
        response_sha256: str,
        final_plan_identity_sha256: str,
    ) -> dict[str, Any]:
        """Apply an exact pending owner batch before explicit finalization.

        A provider-free retry is intentionally not allowed to reconstruct an
        owner capability.  Finalization is the one explicit owner action that
        may do so, and only after the normal clean/review gates have passed.
        This helper therefore accepts no submitted choice: it can replay only
        the exact persisted response against the exact, fully bound pending
        batch.  The retry path remains the authority boundary that compiles
        and publishes the APPLIED marker; this method never flips that marker
        directly.
        """
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        resolutions = validation.get("owner_resolutions")
        if not isinstance(resolutions, list) or not resolutions:
            return run
        state = self._owner_resolution_batch_state(
            validation,
            resolutions,
            response_sha256=response_sha256,
        )
        if state != "PENDING":
            return run

        project_id = run.get("project_id")
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        response = run.get("response") if isinstance(run.get("response"), dict) else {}
        final_plan = run.get("final_plan") if isinstance(run.get("final_plan"), dict) else {}
        request_sha256 = request.get("request_sha256")
        content_lock_hash = request.get("content_lock_hash")
        if (
            run.get("status") not in {"READY_FOR_REVIEW", "NEEDS_REVIEW"}
            or not isinstance(run.get("quality"), dict)
            or run["quality"].get("status") != "CLEAN"
            or run.get("blockers") != []
            or self._unresolved_owner_authority(run)
            or not isinstance(project_id, str)
            or not project_id.strip()
            or request.get("project_id") != project_id
            or request.get("project_revision") != run.get("starting_revision")
            or not isinstance(request_sha256, str)
            or self.request_payload_sha256(request) != request_sha256
            or not isinstance(content_lock_hash, str)
            or not content_lock_hash.strip()
            or self._revision(project_id) != run.get("starting_revision")
            or self._content_lock_hash(project_id) != content_lock_hash
            or response.get("exact_response_text") != response_text
            or response.get("response_sha256") != response_sha256
            or sha256_bytes(response_text.encode("utf-8")) != response_sha256
            or final_plan_sha256(final_plan) != final_plan.get("final_plan_sha256")
            or final_plan.get("immutable_after_validation") is not True
            or final_plan.get("request_sha256") != request_sha256
            or final_plan.get("response_sha256") != response_sha256
            or final_plan.get("plan_sha256") != validation.get("plan_sha256")
            or sha256_json(final_plan) != final_plan_identity_sha256
        ):
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The clean finalization recovery state is not bound to the exact reviewed run.",
                status_code=409,
            )

        authorization = self._owner_decision_authorization_for_pending_retry(
            run,
            response_text,
        )
        if authorization is None or not self._owner_decision_transition_is_authorized(
            run,
            response_text,
            authorization,
        ):
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The pending owner-resolution batch is not the exact bound batch reviewed for finalization.",
                status_code=409,
            )

        # Use the normal local retry/compiler path.  It rechecks the durable
        # row in its transaction and is solely responsible for publishing the
        # APPLIED batch marker and append-only retry attempt.
        self.retry_local_build(
            run["run_id"],
            _owner_decision_authorization=authorization,
            _suppress_auto_finalize=True,
        )
        refreshed = self.get(run["run_id"])
        refreshed_validation = (
            refreshed.get("validation")
            if isinstance(refreshed.get("validation"), dict)
            else {}
        )
        refreshed_rows = refreshed_validation.get("owner_resolutions")
        refreshed_final_plan = (
            refreshed.get("final_plan")
            if isinstance(refreshed.get("final_plan"), dict)
            else {}
        )
        refreshed_request = (
            refreshed.get("request")
            if isinstance(refreshed.get("request"), dict)
            else {}
        )
        refreshed_response = (
            refreshed.get("response")
            if isinstance(refreshed.get("response"), dict)
            else {}
        )
        if (
            refreshed.get("run_id") != run.get("run_id")
            or refreshed.get("project_id") != project_id
            or refreshed.get("starting_revision") != run.get("starting_revision")
            or refreshed_request != request
            or refreshed_request.get("project_id") != project_id
            or refreshed_request.get("project_revision") != refreshed.get("starting_revision")
            or refreshed_request.get("request_sha256") != request_sha256
            or refreshed_request.get("content_lock_hash") != content_lock_hash
            or self._revision(project_id) != refreshed.get("starting_revision")
            or self._content_lock_hash(project_id) != content_lock_hash
            or refreshed_response.get("exact_response_text") != response_text
            or refreshed_response.get("response_sha256") != response_sha256
            or sha256_bytes(response_text.encode("utf-8")) != response_sha256
            or refreshed_final_plan != final_plan
            or not isinstance(refreshed_rows, list)
            or self._owner_resolution_batch_state(
                refreshed_validation,
                refreshed_rows,
                response_sha256=response_sha256,
            ) != "APPLIED"
            or refreshed.get("status") not in {"READY_FOR_REVIEW", "NEEDS_REVIEW"}
            or not isinstance(refreshed.get("quality"), dict)
            or refreshed["quality"].get("status") != "CLEAN"
            or refreshed.get("blockers") != []
            or self._unresolved_owner_authority(refreshed)
        ):
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "The authorized finalization retry did not preserve the exact clean plan and applied owner batch.",
                status_code=409,
            )
        return refreshed

    def _persist_owner_resolution_pending(
        self,
        run: dict[str, Any],
        resolution: dict[str, Any],
        *,
        request_sha256: str,
        response_sha256: str,
        content_lock_hash: str,
    ) -> dict[str, Any]:
        """Merge one owner resolution against the current durable run.

        The resolver may have loaded an older public snapshot while another
        owner request was committing.  The BEGIN IMMEDIATE transaction is the
        authority boundary: it validates the current request/response binding,
        preserves all current resolutions, and only then publishes a PENDING
        marker for the merged batch.
        """
        snapshot_request = run.get("request") if isinstance(run.get("request"), dict) else {}
        snapshot_response = run.get("response") if isinstance(run.get("response"), dict) else {}
        snapshot_binding = {
            "request_sha256": snapshot_request.get("request_sha256"),
            "response_sha256": snapshot_response.get("response_sha256"),
            "content_lock_hash": snapshot_request.get("content_lock_hash"),
        }
        supplied_binding = {
            "request_sha256": request_sha256,
            "response_sha256": response_sha256,
            "content_lock_hash": content_lock_hash,
        }
        if supplied_binding != snapshot_binding:
            raise FoundryError(
                "CG1_DECISION_BINDING_MISMATCH",
                "This owner decision is stale; reload the current response and content-lock receipt before applying it.",
                details={"expected": snapshot_binding, "actual": supplied_binding},
                status_code=409,
            )

        with self.db.transaction() as conn:
            persisted_row = conn.execute(
                "SELECT request_json,response_json,validation_json,status FROM character_creation_runs WHERE run_id=?",
                (run.get("run_id"),),
            ).fetchone()
            if persisted_row is None:
                raise FoundryError("CG1_RUN_NOT_FOUND", "No character build run has that ID.", status_code=404)
            persisted_request = json.loads(persisted_row["request_json"] or "{}")
            persisted_response = json.loads(persisted_row["response_json"] or "{}")
            persisted_validation = json.loads(persisted_row["validation_json"] or "{}")
            persisted_binding = {
                "request_sha256": persisted_request.get("request_sha256"),
                "response_sha256": persisted_response.get("response_sha256"),
                "content_lock_hash": persisted_request.get("content_lock_hash"),
            }
            # Do not let a stale authority write its old validation over a
            # re-bound request or response, even when its original public
            # snapshot still carried the old binding.
            if persisted_binding != supplied_binding:
                raise FoundryError(
                    "CG1_DECISION_BINDING_MISMATCH",
                    "This owner decision is stale; reload the current response and content-lock receipt before applying it.",
                    details={"expected": persisted_binding, "actual": supplied_binding},
                    status_code=409,
                )
            if self.request_payload_sha256(persisted_request) != persisted_binding["request_sha256"]:
                raise FoundryError(
                    "CG1_DECISION_BINDING_MISMATCH",
                    "The persisted request bytes no longer match its request receipt.",
                    details={"request_sha256": persisted_binding["request_sha256"]},
                    status_code=409,
                )
            persisted_text = persisted_response.get("exact_response_text")
            if (
                not isinstance(persisted_text, str)
                or sha256_bytes(persisted_text.encode("utf-8")) != response_sha256
            ):
                raise FoundryError(
                    "CG1_DECISION_BINDING_MISMATCH",
                    "The persisted response bytes no longer match this owner decision.",
                    details={"response_sha256": response_sha256},
                    status_code=409,
                )
            if persisted_row["status"] in TERMINAL_RUN_STATUSES:
                raise FoundryError(
                    "CG1_DECISION_TERMINAL",
                    "This owner decision cannot be changed after the run is terminal.",
                    status_code=409,
                )

            raw_rows = persisted_validation.get("owner_resolutions")
            if "owner_resolutions" in persisted_validation and (
                not isinstance(raw_rows, list)
                or any(not isinstance(row, dict) for row in raw_rows)
            ):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted owner-resolution collection is malformed.",
                    status_code=409,
                )
            current_rows = [deepcopy(row) for row in raw_rows] if isinstance(raw_rows, list) else []
            if not self._owner_resolution_is_bound(
                resolution,
                run_id=run.get("run_id"),
                request_sha256=request_sha256,
                response_sha256=response_sha256,
                content_lock_hash=content_lock_hash,
            ) or not all(
                self._owner_resolution_is_bound(
                    row,
                    run_id=run.get("run_id"),
                    request_sha256=request_sha256,
                    response_sha256=response_sha256,
                    content_lock_hash=content_lock_hash,
                )
                for row in current_rows
            ):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted owner-resolution binding is malformed or stale.",
                    status_code=409,
                )
            decision_ids = [row["decision_id"] for row in current_rows]
            if len(decision_ids) != len(set(decision_ids)):
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted owner-resolution collection contains duplicate decision IDs.",
                    status_code=409,
                )
            batch_state = self._owner_resolution_batch_state(
                persisted_validation,
                current_rows,
                response_sha256=response_sha256,
            )
            if batch_state == "INVALID":
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted owner-resolution batch marker is malformed or no longer matches its resolutions.",
                    status_code=409,
                )
            same_decision = next(
                (row for row in current_rows if row.get("decision_id") == resolution.get("decision_id")),
                None,
            )
            if same_decision is not None and same_decision != resolution:
                # A decision ID is bound to one blocker and one exact value.
                # Never let a stale caller replace that already-persisted row.
                raise FoundryError(
                    "CG1_DECISION_ID_STALE",
                    "The owner decision no longer matches the persisted resolution for that blocker.",
                    status_code=409,
                )
            if same_decision is not None:
                resolutions = current_rows
                if batch_state == "APPLIED":
                    return {
                        "state": "APPLIED",
                        "resolutions": resolutions,
                        "batch_sha256": self._owner_resolution_batch_sha256(resolutions),
                    }
            else:
                # Preserve every distinct current decision.  This is the
                # stale-writer merge: a newer batch is extended, never
                # replaced by the caller's snapshot-derived list.
                resolutions = [*current_rows, deepcopy(resolution)]

            batch_sha256 = self._owner_resolution_batch_sha256(resolutions)
            next_validation = deepcopy(persisted_validation)
            next_validation["owner_resolutions"] = resolutions
            next_validation["owner_resolution_batch"] = self._owner_resolution_batch_marker(
                resolutions,
                response_sha256=response_sha256,
                status="PENDING",
            )
            next_validation["owner_resolution_batch_sha256"] = batch_sha256
            conn.execute(
                "UPDATE character_creation_runs SET validation_json=?,owner_decision='APPLY_DECISION',updated_at=? WHERE run_id=?",
                (canonical_json(next_validation), utcnow(), run.get("run_id")),
            )
            return {
                "state": "PENDING",
                "resolutions": resolutions,
                "batch_sha256": batch_sha256,
            }

    def resolve_owner_decision(
        self,
        run_id: str,
        *,
        decision_id: str,
        field: str,
        slot_id: str | None,
        operation: str = "replace_slot_value",
        target_value: Any = None,
        value: Any,
        request_sha256: str,
        response_sha256: str,
        content_lock_hash: str,
    ) -> dict[str, Any]:
        """Record one bound owner choice, then rerun normal local compilation."""
        run = self.get(run_id)
        if run.get("status") in TERMINAL_RUN_STATUSES:
            raise FoundryError("CG1_DECISION_TERMINAL", "This owner decision cannot be changed after the run is terminal.", status_code=409)
        request = run.get("request") or {}
        response = run.get("response") or {}
        expected_binding = {
            "request_sha256": request.get("request_sha256"),
            "response_sha256": response.get("response_sha256"),
            "content_lock_hash": request.get("content_lock_hash"),
        }
        supplied_binding = {
            "request_sha256": request_sha256,
            "response_sha256": response_sha256,
            "content_lock_hash": content_lock_hash,
        }
        if supplied_binding != expected_binding:
            raise FoundryError(
                "CG1_DECISION_BINDING_MISMATCH",
                "This owner decision is stale; reload the current response and content-lock receipt before applying it.",
                details={"expected": expected_binding, "actual": supplied_binding},
                status_code=409,
            )
        normalized_field = str(field or "").strip()
        normalized_slot = str(slot_id).strip() if isinstance(slot_id, str) and slot_id.strip() else None
        normalized_operation = str(operation or "replace_slot_value").strip()
        allowed_operations = {
            "replace_slot_value",
            "replace_slot_list",
            "add_slot_value",
            "remove_slot_value",
            "set_field",
            "set_milestone_choice",
        }
        if normalized_operation not in allowed_operations:
            raise FoundryError(
                "CG1_DECISION_OPERATION_INVALID",
                "The owner decision operation is not recognized by this Factory.",
                details={"operation": normalized_operation},
                status_code=409,
            )
        validation = deepcopy(run.get("validation") or {})
        response_text = response.get("exact_response_text") if isinstance(response.get("exact_response_text"), str) else ""
        # A pre-fix run can retain a valid PENDING batch for a milestone that
        # already compiled successfully while its current blocker identifies
        # the next milestone.  Prove that exact successor control first, then
        # atomically promote only the old batch and continue through the
        # ordinary current-decision path.  Generic Retry Local Build remains
        # unauthorized for PENDING batches.
        migration_control = self._owner_resolution_for_restart_migration_control(
            run,
            decision_id=decision_id,
            field=normalized_field,
            slot_id=normalized_slot,
            operation=normalized_operation,
            target_value=target_value,
            value=value,
            response_text=response_text,
        )
        if migration_control is not None:
            self._promote_owner_resolution_batch_for_restart(
                run,
                migration_control,
                run_id=run_id,
                decision_id=decision_id,
                field=normalized_field,
                slot_id=normalized_slot,
                operation=normalized_operation,
                target_value=target_value,
                value=value,
                request_sha256=request_sha256,
                response_sha256=response_sha256,
                content_lock_hash=content_lock_hash,
                response_text=response_text,
            )
            # The transaction may have observed an already-promoted race; in
            # either case all subsequent validation must use the refreshed
            # durable run, never the pre-transaction snapshot.
            run = self.get(run_id)
            request = run.get("request") or {}
            response = run.get("response") or {}
            validation = deepcopy(run.get("validation") or {})
            response_text = response.get("exact_response_text") if isinstance(response.get("exact_response_text"), str) else ""
        restart_control = None
        if migration_control is None:
            # A restarted owner panel can reconstruct a milestone control from
            # a newer raw compiler diagnostic (for example the diagnostic may
            # only retain ``milestone_id`` and ``kind``).  Its public decision
            # ID then differs from the original persisted resolution even
            # though the selected typed value is identical.  Resume only that
            # exact value through the frozen current-blocker/legal-choice
            # proof.
            restart_control = self._owner_resolution_for_restart_control(
                run,
                decision_id=decision_id,
                field=normalized_field,
                slot_id=normalized_slot,
                operation=normalized_operation,
                target_value=target_value,
                value=value,
                response_text=response_text,
            )
        # A response may have been durably accepted while the owner request
        # was still in flight.  Reconcile an exact persisted operation before
        # looking for a now-resolved blocker: pending batches must retry the
        # authorized transition, while applied batches are idempotent.
        existing_resolutions = validation.get("owner_resolutions") if isinstance(validation.get("owner_resolutions"), list) else []
        matching_persisted = next(
            (
                row
                for row in existing_resolutions
                if isinstance(row, dict)
                and row.get("decision_id") == decision_id
                and row.get("field") == normalized_field
                and row.get("slot_id") == normalized_slot
                and row.get("operation") == normalized_operation
                and row.get("value") == value
                and (target_value is None or row.get("target_value") == target_value)
                and (row.get("binding") or {}).get("run_id") == run_id
                and (row.get("binding") or {}).get("request_sha256") == request_sha256
                and (row.get("binding") or {}).get("response_sha256") == response_sha256
                and (row.get("binding") or {}).get("content_lock_hash") == content_lock_hash
            ),
            None,
        )
        if migration_control is None and matching_persisted is not None:
            # Reconcile through the durable merge boundary even for a
            # duplicate request.  This both retries a genuinely PENDING batch
            # and promotes the exact pre-marker legacy shape once; malformed
            # partial markers fail closed instead of being treated as legacy.
            persisted = self._persist_owner_resolution_pending(
                run,
                matching_persisted,
                request_sha256=request_sha256,
                response_sha256=response_sha256,
                content_lock_hash=content_lock_hash,
            )
            if persisted["state"] == "APPLIED":
                return self.get(run_id)
            persisted_resolutions = persisted["resolutions"]
            pending_batch_sha256 = persisted["batch_sha256"]
            return self.retry_local_build(
                run_id,
                _owner_decision_authorization={
                    "authority": _OWNER_DECISION_TRANSITION_AUTHORITY,
                    "run_id": run_id,
                    "request_sha256": request_sha256,
                    "response_sha256": response_sha256,
                    "content_lock_hash": content_lock_hash,
                    "owner_resolution_batch_sha256": pending_batch_sha256,
                    "resolution_count": len(persisted_resolutions),
                },
            )
        if migration_control is None and restart_control is not None:
            persisted = self._persist_owner_resolution_pending(
                run,
                restart_control["resolution"],
                request_sha256=request_sha256,
                response_sha256=response_sha256,
                content_lock_hash=content_lock_hash,
            )
            if persisted["state"] == "APPLIED":
                return self.get(run_id)
            retry_run = self.get(run_id)
            authorization = self._owner_decision_authorization_for_pending_retry(
                retry_run,
                response.get("exact_response_text") if isinstance(response.get("exact_response_text"), str) else "",
            )
            if authorization is None:
                raise FoundryError(
                    "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                    "The persisted owner-resolution batch changed before its restart resume could begin.",
                    status_code=409,
                )
            return self.retry_local_build(
                run_id,
                _owner_decision_authorization=authorization,
            )
        pending_retry_authorization = self._owner_decision_authorization_for_pending_retry(
            run,
            response.get("exact_response_text") if isinstance(response.get("exact_response_text"), str) else "",
        )
        if migration_control is None and pending_retry_authorization is not None:
            raise FoundryError(
                "CG1_OWNER_DECISION_AUTHORIZATION_INVALID",
                "A valid pending owner-resolution batch exists, but this control is not its unique current decision.",
                status_code=409,
            )
        blocker_details: dict[str, Any] | None = None
        for row in run.get("blockers") or []:
            if not isinstance(row, dict):
                continue
            details = row.get("details") if isinstance(row.get("details"), dict) else {}
            row_field = str(details.get("field") or "")
            row_slot = self._decision_slot_from_details(details)
            milestone = details.get("milestone") if isinstance(details.get("milestone"), dict) else {}
            row_milestone_id = details.get("milestone_id") or milestone.get("milestone_id")
            milestone_match = (
                normalized_operation == "set_milestone_choice"
                and isinstance(row_milestone_id, str)
                and row_milestone_id == normalized_field
            )
            if row_field == normalized_field or (normalized_slot and row_slot == normalized_slot) or milestone_match:
                blocker_details = details
                break
        if blocker_details is None:
            # A compiled resolution can retain an unresolved provenance row
            # even when the validator did not emit a duplicate blocker.  The
            # owner projection may expose that row as a direct decision, so
            # resolve against the same current row rather than rejecting the
            # control as stale.  The overlay is still revalidated below.
            final_plan = run.get("final_plan") if isinstance(run.get("final_plan"), dict) else {}
            resolution = final_plan.get("resolution") if isinstance(final_plan.get("resolution"), dict) else {}
            for row in resolution.get("provenance") or []:
                if not isinstance(row, dict) or row.get("status") != "unresolved":
                    continue
                row_field = str(row.get("field") or row.get("slot_id") or "")
                row_slot = self._decision_slot_from_details(row)
                if row_field == normalized_field or (normalized_slot and row_slot == normalized_slot):
                    blocker_details = {
                        **row,
                        "field": row.get("field") or normalized_field,
                        "slot_id": row.get("slot_id") or normalized_slot,
                    }
                    break
        if blocker_details is None:
            raise FoundryError(
                "CG1_DECISION_NOT_CURRENT",
                "That decision is no longer present in the current server review state.",
                status_code=409,
            )
        blocker_sha256 = sha256_json(blocker_details)
        expected_id = self._owner_decision_id(
            run,
            field=normalized_field,
            slot_id=normalized_slot,
            operation=normalized_operation,
            blocker_sha256=blocker_sha256,
        )
        if decision_id != expected_id:
            raise FoundryError(
                "CG1_DECISION_ID_STALE",
                "The owner decision no longer matches the current unresolved blocker.",
                details={"expected_decision_id": expected_id, "actual_decision_id": decision_id},
                status_code=409,
            )
        validation = deepcopy(run.get("validation") or {})
        # The persisted blocker is intentionally kept byte-for-byte stable for
        # decision-ID binding.  Build the legal alternatives separately from
        # the same source-backed authority used by the owner projection; this
        # closes the old split where the UI displayed Insight choices that the
        # resolver could not find on the raw blocker.
        candidate_details = blocker_details
        envelope = request.get("delegated_choice_envelope") if isinstance(request.get("delegated_choice_envelope"), dict) else {}
        current_overlay_plan: dict[str, Any] = {}
        response_text = response.get("exact_response_text")
        if isinstance(response_text, str) and response_text:
            try:
                parsed_response = json.loads(response_text)
            except (TypeError, json.JSONDecodeError):
                parsed_response = None
            if isinstance(parsed_response, dict):
                current_overlay_plan = self._apply_owner_resolutions(run, parsed_response)
        if normalized_operation == "set_milestone_choice":
            proposal = (validation.get("proposal_projection") or {}) if isinstance(validation, dict) else {}
            proposal = proposal if isinstance(proposal, dict) else {}
            # The persisted projection is intentionally the original AI
            # proposal.  Previous owner resolutions are a separate immutable
            # overlay, so rebuild this small projection before publishing the
            # next milestone's legal choices; otherwise a later milestone can
            # be offered a cap-invalid ASI that an earlier owner choice made
            # illegal.
            if current_overlay_plan:
                proposal = self._proposal_projection(current_overlay_plan)
            candidate_details = enrich_milestone_details(
                blocker_details,
                envelope=envelope,
                proposal_bounded=proposal.get("bounded_choices") if isinstance(proposal.get("bounded_choices"), dict) else {},
                proposal_acquisition=proposal.get("acquisition_intent") if isinstance(proposal.get("acquisition_intent"), dict) else {},
                proposal_selected_by_slot=proposal.get("selected_by_slot") if isinstance(proposal.get("selected_by_slot"), dict) else {},
                authority_by_milestone=run.get("owner_decision_authority") if isinstance(run.get("owner_decision_authority"), dict) else {},
            )
        candidates: list[Any] = []
        replacement_legal_ids: list[str] | None = None
        resolved_target_value = target_value
        if normalized_operation == "replace_slot_value" and normalized_slot:
            if resolved_target_value is None:
                candidate_target = blocker_details.get("target_value") or blocker_details.get("choice_id")
                if isinstance(candidate_target, str) and candidate_target:
                    resolved_target_value = candidate_target
            current_selection = (
                (current_overlay_plan.get("selection_intent") or {}).get("by_slot")
                if isinstance(current_overlay_plan, dict)
                else {}
            )
            current_selection = current_selection if isinstance(current_selection, dict) else {}
            replacement_legal_ids = legal_slot_replacement_ids(
                envelope,
                {
                    "target_cl": current_overlay_plan.get("target_cl")
                    or request.get("target_cl")
                    or (envelope.get("frozen_owner_target_cl") or {}).get("target_cl"),
                },
                current_selection,
                normalized_slot,
                target_value=resolved_target_value,
            )
        if normalized_operation == "set_milestone_choice":
            for key in ("legal_choices", "allowed_milestone_choices", "allowed_choices"):
                if isinstance(candidate_details.get(key), list):
                    candidates = candidate_details[key]
                    break
        elif normalized_operation == "set_field":
            # Bounded owner decisions publish complete typed values rather
            # than a list of opaque IDs.  Keep the candidate set bound to the
            # persisted diagnostic; the overlay is still fully revalidated.
            if isinstance(candidate_details.get("legal_choices"), list):
                candidates = candidate_details["legal_choices"]
        for key in ("allowed_choice_ids", "offered_choice_ids", "available_choice_ids", "allowed_path_ids", "available_path_ids"):
            if candidates:
                break
            if isinstance(blocker_details.get(key), list):
                candidates = blocker_details[key]
                break
        if not candidates and normalized_slot:
            envelope = request.get("delegated_choice_envelope") or {}
            allowed = envelope.get("allowed_choice_ids_by_slot") if isinstance(envelope, dict) else {}
            if isinstance(allowed, dict) and isinstance(allowed.get(normalized_slot), list):
                candidates = allowed[normalized_slot]
        if not candidates:
            for key in ("allowed_abilities", "required_abilities", "allowed_amounts"):
                if isinstance(blocker_details.get(key), list):
                    candidates = blocker_details[key]
                    break
        if replacement_legal_ids is not None:
            candidates = replacement_legal_ids
        candidate_values = [
            candidate.get("value") if isinstance(candidate, dict) and "value" in candidate else candidate
            for candidate in candidates
        ]
        decision_value = value
        if normalized_operation == "replace_slot_list":
            valid_list = bool(candidates) and isinstance(value, list) and all(item in candidate_values for item in value)
        elif normalized_operation == "remove_slot_value":
            decision_value = value if target_value is None else target_value
            valid_list = bool(candidates) and decision_value is not None and decision_value in candidate_values
        elif normalized_operation == "set_milestone_choice":
            valid_list = bool(candidates) and any(
                candidate == value
                or (isinstance(candidate, dict) and candidate.get("value") == value)
                for candidate in candidates
            )
        else:
            valid_list = bool(candidates) and value is not None and value in candidate_values
        if not valid_list:
            raise FoundryError(
                "CG1_DECISION_VALUE_ILLEGAL",
                "The selected owner value is not one of the complete legal values published for this decision.",
                details={
                    "field": normalized_field,
                    "slot_id": normalized_slot,
                    "operation": normalized_operation,
                    "value": value,
                    "target_value": target_value,
                    "allowed_count": len(candidates),
                },
                status_code=409,
            )
        resolution = {
            "schema": "TianxiaFoundry.OwnerDecisionResolution.v1",
            "decision_id": decision_id,
            "field": normalized_field,
            "slot_id": normalized_slot,
            "operation": normalized_operation,
            "target_value": deepcopy(resolved_target_value),
            "value": deepcopy(value),
            "binding": {
                "run_id": run_id,
                "request_sha256": request_sha256,
                "response_sha256": response_sha256,
                "content_lock_hash": content_lock_hash,
                "blocker_sha256": blocker_sha256,
            },
        }
        persisted = self._persist_owner_resolution_pending(
            run,
            resolution,
            request_sha256=request_sha256,
            response_sha256=response_sha256,
            content_lock_hash=content_lock_hash,
        )
        if persisted["state"] == "APPLIED":
            # The transaction observed the exact durable batch already
            # applied.  Return it without rewriting validation/final_plan or
            # creating another attempt.
            return self.get(run_id)
        resolutions = persisted["resolutions"]
        batch_sha256 = persisted["batch_sha256"]
        authorization = {
            "authority": _OWNER_DECISION_TRANSITION_AUTHORITY,
            "run_id": run_id,
            "request_sha256": request_sha256,
            "response_sha256": response_sha256,
            "content_lock_hash": content_lock_hash,
            "owner_resolution_batch_sha256": batch_sha256,
            "resolution_count": len(resolutions),
        }
        return self.retry_local_build(
            run_id,
            _owner_decision_authorization=authorization,
        )

    @staticmethod
    def _manual_response_text(filename: str, payload: bytes) -> tuple[str, dict[str, Any]]:
        name = Path(str(filename or "")).name
        if name != str(filename or "") or not name:
            raise FoundryError("CG1_MANUAL_RESPONSE_FILENAME_INVALID", "Choose one local response ZIP or JSON file.")
        if len(payload) > 16_000_000:
            raise FoundryError("CG1_MANUAL_RESPONSE_TOO_LARGE", "The complete response file is larger than the 16 MB transfer limit.")
        suffix = Path(name).suffix.casefold()
        response_name = name
        response_payload = payload
        archive_members: list[dict[str, Any]] = []
        archive_sha256: str | None = None
        if suffix == ".zip":
            try:
                with zipfile.ZipFile(io.BytesIO(payload)) as archive:
                    files = []
                    infos = archive.infolist()
                    if len(infos) > 64:
                        raise FoundryError(
                            "CG1_MANUAL_RESPONSE_ZIP_ENTRY_LIMIT",
                            "The response ZIP contains too many members.",
                            details={"entry_count": len(infos), "maximum": 64},
                        )
                    seen_names: set[str] = set()
                    folded_names: set[str] = set()
                    normalized_names: set[str] = set()
                    expanded_bytes = 0
                    compressed_bytes = 0
                    for info in infos:
                        raw_name = str(info.filename or "")
                        normalized_name = raw_name.replace("\\", "/")
                        path = PurePosixPath(normalized_name)
                        if (
                            not normalized_name
                            or path.is_absolute()
                            or ".." in path.parts
                            or len(path.parts) != 1
                            or (len(normalized_name) >= 2 and normalized_name[1] == ":")
                        ):
                            raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_PATH_INVALID", "The response ZIP must contain safe top-level member paths.", details={"member": raw_name})
                        canonical_name = unicodedata.normalize("NFC", path.as_posix())
                        folded = canonical_name.casefold()
                        if (
                            canonical_name in seen_names
                            or folded in folded_names
                            or canonical_name in normalized_names
                        ):
                            raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_MEMBER_COLLISION", "The response ZIP contains duplicate or colliding member names.", details={"member": raw_name})
                        seen_names.add(canonical_name)
                        folded_names.add(folded)
                        normalized_names.add(canonical_name)
                        mode = (info.external_attr >> 16) & 0xFFFF
                        file_type = stat.S_IFMT(mode)
                        if file_type == stat.S_IFLNK:
                            raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_LINK_REJECTED", "The response ZIP may not contain symbolic links.", details={"member": raw_name})
                        if file_type not in (0, stat.S_IFREG, stat.S_IFDIR):
                            raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_SPECIAL_FILE", "The response ZIP may contain ordinary files only.", details={"member": raw_name})
                        if info.is_dir():
                            archive_members.append({"filename": canonical_name, "directory": True, "file_size": 0, "compressed_size": int(info.compress_size)})
                            continue
                        if info.flag_bits & 0x1:
                            raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_ENCRYPTED", "Encrypted response ZIPs are not accepted.")
                        expanded_bytes += int(info.file_size)
                        compressed_bytes += int(info.compress_size)
                        if expanded_bytes > 2_000_000 or compressed_bytes > 16_000_000:
                            raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_EXPANSION_LIMIT", "The response ZIP exceeds the safe expanded-size limit.")
                        member_bytes = archive.read(info)
                        archive_members.append({
                            "filename": canonical_name,
                            "directory": False,
                            "file_size": int(info.file_size),
                            "compressed_size": int(info.compress_size),
                            "crc32": int(info.CRC),
                            "sha256": sha256_bytes(member_bytes),
                        })
                        if path.suffix.casefold() not in {".json", ".txt", ".md"}:
                            continue
                        files.append(info)
                    if archive.testzip() is not None:
                        raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_CRC_INVALID", "The response ZIP failed its integrity check.")
                    if len(files) != 1:
                        raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_CONTENT_INVALID", "The response ZIP must contain exactly one JSON, text, or Markdown response file.", details={"eligible_files": [row.filename for row in files]})
                    info = files[0]
                    if info.file_size > 2_000_000:
                        raise FoundryError("CG1_MANUAL_RESPONSE_TOO_LARGE", "The complete response inside the ZIP exceeds 2 MB.")
                    response_name = info.filename
                    response_payload = archive.read(info)
            except zipfile.BadZipFile as exc:
                code = "CG1_MANUAL_RESPONSE_ZIP_CRC_INVALID" if "crc" in str(exc).casefold() else "CG1_MANUAL_RESPONSE_ZIP_INVALID"
                raise FoundryError(code, "The response ZIP failed its integrity check." if code.endswith("CRC_INVALID") else "The selected response ZIP is not a valid ZIP archive.") from exc
            except (RuntimeError, OSError) as exc:
                raise FoundryError("CG1_MANUAL_RESPONSE_ZIP_CRC_INVALID", "The response ZIP could not be read with integrity verification.") from exc
            archive_sha256 = sha256_bytes(payload)
        elif suffix not in {".json", ".txt", ".md"}:
            raise FoundryError("CG1_MANUAL_RESPONSE_TYPE_INVALID", "Choose a .zip, .json, .txt, or .md complete response file.")
        if len(response_payload) > 2_000_000:
            raise FoundryError("CG1_MANUAL_RESPONSE_TOO_LARGE", "The complete response exceeds 2 MB.")
        had_utf8_bom = response_payload.startswith(b"\xef\xbb\xbf")
        try:
            decoded_text = response_payload.decode("utf-8-sig")
        except UnicodeDecodeError as exc:
            raise FoundryError("CG1_MANUAL_RESPONSE_ENCODING_INVALID", "The complete response must be UTF-8 text.", details={"source_filename": name, "member": response_name, "byte_offset": exc.start}) from exc
        text = decoded_text.strip()
        if not text:
            raise FoundryError("CG1_MANUAL_RESPONSE_EMPTY", "The selected complete response file is empty.")
        return text, {
            "uploaded_filename": name,
            "uploaded_bytes": len(payload),
            "response_member": response_name,
            "uploaded_sha256": sha256_bytes(payload),
            "source_provenance": {
                "schema": "TianxiaFoundry.CharacterCreationResponseSourceProvenance.v1",
                "source_kind": "zip" if suffix == ".zip" else "file",
                "filename": name,
                "archive_sha256": archive_sha256,
                "archive_bytes": len(payload) if suffix == ".zip" else None,
                "member_filename": response_name,
                "member_sha256": sha256_bytes(response_payload),
                "member_bytes": len(response_payload),
                "raw_byte_count": len(response_payload),
                "archive_members": archive_members,
                "raw_bytes_sha256": sha256_bytes(response_payload),
                "normalization": {
                    "encoding": "utf-8",
                    "bom_removed": had_utf8_bom,
                    "outer_whitespace_stripped": decoded_text != text,
                    "normalized_text_bytes": len(text.encode("utf-8")),
                    "normalized_text_sha256": sha256_bytes(text.encode("utf-8")),
                },
            },
        }

    def submit_manual_file(self, run_id: str, *, filename: str, payload: bytes) -> dict[str, Any]:
        run = self.get(run_id)
        if run["execution_mode"] != "MANUAL_CHAT":
            raise FoundryError("CG1_MANUAL_RESPONSE_MODE_MISMATCH", "This run is not waiting for a Manual Chat response.")
        try:
            response_text, upload = self._manual_response_text(filename, payload)
        except FoundryError as exc:
            self._record_manual_transport_failure(
                run_id,
                filename=filename,
                payload=payload,
                error=exc,
                action_type="IMPORT_RESPONSE",
            )
            raise
        return self._apply_response(
            run_id,
            response_text,
            {
                "mode": "MANUAL_CHAT",
                "provider_called": False,
                "transfer": "response_file",
                "submitted_request_sha256": run["request"].get("request_sha256"),
                **upload,
            },
            submitted_request_sha256=run["request"].get("request_sha256"),
            binding_error_status=True,
            action_type="IMPORT_RESPONSE",
        )

    @staticmethod
    def _is_unresolved_owner_row(row: Any) -> bool:
        """Return whether a persisted row still represents required owner work.

        ``final_plan.resolution.provenance`` is append-only evidence, so this
        deliberately accepts only the explicit unresolved states.  Historical
        accepted/rejected/deferred rows must not reopen a finalized plan.
        """
        if not isinstance(row, dict):
            return False
        status = str(row.get("status") or "").strip().lower()
        provenance = str(row.get("provenance") or "").strip().lower()
        if status in {"accepted", "resolved", "rejected", "complete", "completed"}:
            return False
        return status == "unresolved" or provenance in {"needs_owner", "owner_decision_required"}

    @staticmethod
    def _pre_subpath_deferral_is_authenticated(run: dict[str, Any]) -> bool:
        """Recognize only the generic delegated pre-Subpath deferral.

        CL1/CL2 delegated v3 responses may intentionally carry no Subpath yet;
        the authenticated compiler treats that as a future milestone rather
        than an owner choice.  This predicate is deliberately stricter than a
        target-CL check so historical, fixture, malformed, and already-selected
        representations remain finalization blockers.
        """
        request = run.get("request") if isinstance(run.get("request"), dict) else {}
        final_plan = run.get("final_plan") if isinstance(run.get("final_plan"), dict) else {}
        target_cl = final_plan.get("target_cl")
        if type(target_cl) is not int or not 0 < target_cl < FIRST_PATH_SUBPATH_SELECTION_CL:
            return False
        if request.get("schema") != "TianxiaFoundry.CharacterCreationPlanRequest.v3":
            return False
        if request.get("required_plan_schema") != "TianxiaFoundry.DelegatedSelectionIntentResponse.v1":
            return False

        resolution = final_plan.get("resolution")
        if not isinstance(resolution, dict):
            return False
        selected_by_slot = resolution.get("selected_choices_by_slot")
        if not isinstance(selected_by_slot, dict) or selected_by_slot.get("subpath_choice") != []:
            return False
        envelope = request.get("delegated_choice_envelope")
        if not isinstance(envelope, dict):
            return False

        stage1_prompt = request.get("stage1_prompt")
        stage1_envelope = stage1_prompt.get("envelope") if isinstance(stage1_prompt, dict) else None
        slots = stage1_envelope.get("decision_slots") if isinstance(stage1_envelope, dict) else None
        subpath_slots = [
            row for row in slots or []
            if isinstance(row, dict) and row.get("slot_id") == "subpath_choice"
        ]
        if len(subpath_slots) != 1 or subpath_slots[0].get("min_selections") != 0:
            return False

        parsed_plan = run.get("response", {}).get("parsed_plan") if isinstance(run.get("response"), dict) else None
        parsed_plan = parsed_plan if isinstance(parsed_plan, dict) else {}
        canonical_intent = parsed_plan.get("canonical_selection_intent")
        if not isinstance(canonical_intent, dict) or canonical_intent.get("response_form") != "preferred":
            return False
        if canonical_intent.get("historical_stage2_rows") != []:
            return False
        if request.get("fixture") is True or parsed_plan.get("fixture") is True:
            return False

        stage1_response = parsed_plan.get("stage1_response")
        stage1_response = stage1_response if isinstance(stage1_response, dict) else {}
        response_payload = stage1_response.get("response_payload")
        response_payload = response_payload if isinstance(response_payload, dict) else {}
        subpath_decisions = [
            row for row in response_payload.get("decisions") or []
            if isinstance(row, dict) and row.get("slot_id") == "subpath_choice"
        ]
        return (
            len(subpath_decisions) == 1
            and subpath_decisions[0].get("state") == "deferred_with_reason"
            and subpath_decisions[0].get("choice_ids") == []
        )

    def _unresolved_owner_authority(self, run: dict[str, Any]) -> list[dict[str, Any]]:
        """Derive one server-owned finalization guard from the persisted run.

        The UI and API projections may be stale, but the immutable final plan,
        its resolution provenance, and the current blocking rows are all
        server-owned.  Finalization must consult these same persisted sources
        immediately before any live output or canonical mutation.
        """
        unresolved: list[dict[str, Any]] = []
        seen: set[tuple[str, str, str, str]] = set()
        pre_subpath_deferral = self._pre_subpath_deferral_is_authenticated(run)
        nonrequired_planning_slots = self._provider_nonrequired_planning_slot_ids(run)

        def add(kind: str, row: Any) -> None:
            if not isinstance(row, dict):
                return
            if kind == "decision" and not self._is_unresolved_owner_row(row):
                return
            if kind == "blocker" and row.get("resolved") is True:
                return
            details = row.get("details") if isinstance(row.get("details"), dict) else {}
            slot_id = str(row.get("slot_id") or details.get("slot_id") or "")
            if (
                kind == "decision"
                and slot_id in nonrequired_planning_slots
                and row.get("choice_id") is None
                and row.get("provenance") == "needs_owner"
                and row.get("status") == "unresolved"
            ):
                return
            if pre_subpath_deferral and kind == "decision" and slot_id == "subpath_choice":
                return
            field = str(row.get("field") or details.get("field") or "")
            milestone_id = str(row.get("milestone_id") or details.get("milestone_id") or "")
            code = str(row.get("code") or details.get("code") or "")
            identity = (kind, slot_id, field or milestone_id, code)
            if identity in seen:
                return
            seen.add(identity)
            unresolved.append({
                "kind": kind,
                "slot_id": slot_id or None,
                "field": field or None,
                "milestone_id": milestone_id or None,
                "code": code or None,
                "status": row.get("status"),
                "provenance": row.get("provenance"),
                "message": row.get("message") or details.get("message") or row.get("reason"),
            })

        for blocker in run.get("blockers") or []:
            add("blocker", blocker)
        final_plan = run.get("final_plan") if isinstance(run.get("final_plan"), dict) else {}
        for row in final_plan.get("unresolved") or []:
            add("decision", row)
        resolution = final_plan.get("resolution") if isinstance(final_plan.get("resolution"), dict) else {}
        for row in resolution.get("provenance") or []:
            add("decision", row)
        validation = run.get("validation") if isinstance(run.get("validation"), dict) else {}
        for row in validation.get("unresolved_owner_decisions") or []:
            add("decision", row)
        return unresolved

    def _require_owner_decisions_resolved(self, run: dict[str, Any]) -> None:
        unresolved = self._unresolved_owner_authority(run)
        if unresolved:
            raise FoundryError(
                "CG1_OWNER_DECISIONS_REQUIRED",
                "Finalization is blocked until every required owner decision and blocking authority is resolved.",
                details={
                    "unresolved_count": len(unresolved),
                    "unresolved": unresolved,
                    "server_derived": True,
                },
                status_code=409,
            )

    def create_auto_finalize_opt_in(self, run_id: str) -> dict[str, Any]:
        run = self.get(run_id)
        self._require_owner_decisions_resolved(run)
        if run["execution_mode"] != "AUTO_FINALIZE_WHEN_CLEAN":
            raise FoundryError("CG1_AUTO_FINALIZE_MODE_REQUIRED","Explicit Auto-Finalize consent is only valid for an Auto-Finalize When Clean run.",status_code=409)
        if run["status"] not in {"READY_FOR_REVIEW", "NEEDS_REVIEW"} or run["quality"].get("status") != "CLEAN":
            raise FoundryError("CG1_AUTO_FINALIZE_OPT_IN_NOT_CLEAN","Auto-Finalize can only be enabled for a clean reviewed candidate.",status_code=409)
        plan = run["response"].get("parsed_plan") or {}
        payload = {
            "schema": "TianxiaFoundry.CharacterCreationAutoFinalizeOptIn.v1",
            "owner_principal_id": self.owner_principal,
            "owner_principal_hash": self.owner_principal_hash,
            "project_id": run["project_id"],
            "project_revision": run["starting_revision"],
            "content_lock_hash": run["request"]["content_lock_hash"],
            "request_sha256": run["request"]["request_sha256"],
            "candidate_identity": run["dry_run"]["candidate_identity"],
            "output_profile_sha256": sha256_json(plan.get("output_profile") or {}),
        }
        payload["receipt_sha256"] = sha256_json(payload)
        payload["receipt_id"] = "cg1.optin." + payload["receipt_sha256"][:24]
        with self.db.transaction() as conn:
            conn.execute(
                "INSERT OR IGNORE INTO character_creation_auto_finalize_opt_ins("
                "receipt_id,project_id,owner_principal_id,owner_principal_hash,project_revision,"
                "content_lock_hash,request_sha256,candidate_identity,output_profile_sha256,"
                "receipt_sha256,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (payload["receipt_id"], payload["project_id"], payload["owner_principal_id"],
                 payload["owner_principal_hash"], payload["project_revision"], payload["content_lock_hash"],
                 payload["request_sha256"], payload["candidate_identity"], payload["output_profile_sha256"],
                 payload["receipt_sha256"], utcnow()),
            )
        finalized = self.finalize(run_id, auto_finalize_receipt=payload)
        finalized["auto_finalize_opt_in"] = payload
        return finalized

    def _valid_auto_finalize_opt_in(self, run: dict[str, Any]) -> dict[str, Any] | None:
        plan = run["response"].get("parsed_plan") or {}
        with self.db.connection() as conn:
            row = conn.execute(
                "SELECT * FROM character_creation_auto_finalize_opt_ins WHERE "
                "project_id=? AND owner_principal_hash=? AND project_revision=? AND content_lock_hash=? "
                "AND request_sha256=? AND candidate_identity=? AND output_profile_sha256=? AND revoked_at IS NULL "
                "ORDER BY created_at DESC LIMIT 1",
                (run["project_id"], self.owner_principal_hash, run["starting_revision"],
                 run["request"]["content_lock_hash"], run["request"]["request_sha256"],
                 run["dry_run"]["candidate_identity"], sha256_json(plan.get("output_profile") or {})),
            ).fetchone()
        return dict(row) if row else None

    def _declare_training_authority_supplement(self, run: dict[str, Any], prompt_text: str) -> str:
        """Publish and declare the run-bound frozen training authority supplement.

        The prompt may only reference a supplement that is published for this run,
        bound to this run's request, so a plan cannot be authored against an
        authority the client could not have read.  Every declared field comes from
        the frozen envelope; nothing is taken from the live catalog.
        """

        request = run.get("request") if isinstance(run, dict) else None
        request = request if isinstance(request, Mapping) else {}
        envelope = request.get("delegated_choice_envelope")
        if not isinstance(envelope, Mapping):
            return prompt_text
        if not isinstance(envelope.get("creation_training_contract"), Mapping) and not isinstance(
            envelope.get("explicit_forging_contract"), Mapping
        ):
            return prompt_text
        provider_id = settings_provider_id(run) if isinstance(run, Mapping) else None
        if provider_id is None:
            provider_id = self._selected_provider_id_for_supplement()
        if str(provider_id or "") != "agent":
            # Supplement delivery is an agent-bridge concern only; local and
            # remote provider behavior is unchanged.
            return prompt_text
        run_id = run.get("run_id")
        request_sha256 = request.get("request_sha256")
        if not isinstance(run_id, str) or not run_id or not isinstance(request_sha256, str):
            return prompt_text
        payload = json.loads(prompt_text) if isinstance(prompt_text, str) else None
        if not isinstance(payload, dict):
            return prompt_text
        from character_creation.training_authority_supplement import publish_supplement

        binding = publish_supplement(self.db, run_id, envelope, request_sha256=request_sha256)
        self._persist_declared_training_authority_supplement(run, binding)
        payload["training_authority_supplement"] = {
            **binding,
            "declared_in_prompt": True,
            "delivery": {
                "mechanism": "authenticated read-only endpoint",
                "endpoint": f"/api/character-creation/runs/{run_id}/training-authority-supplement",
                "agent_bridge_export": "the agent bridge request document carries this same declaration under training_authority_supplement",
                "required": True,
                "note": "the declared digest must resolve before an answer may be submitted; the server re-verifies it at consumption time",
            },
            "usage": (
                "Fetch the declared digest through delivery.endpoint. Every frozen row is present and exact; "
                "decode by record id. Build each trained_choice row with choice_type and record_id from the row, "
                "source from constructed_source_template resolved against that row (append RAW-081 to rule_ids only "
                "for new_sphere), outcome copied verbatim from constructed_outcome_template, and bonus_talent_id only "
                "for new_sphere rows. required_choices_per_cl rows are required at every CL."
            ),
            "completeness_contract": (
                "row_count equals the frozen contract's record count; every legal frozen row is present verbatim; "
                "no row is omitted and no live-catalog value is substituted."
            ),
        }
        declared = canonical_json(payload)
        hard_cap = PROVIDER_PROMPT_HARD_CAP_BYTES
        if len(declared.encode("utf-8")) > hard_cap:
            raise FoundryError(
                "CG1_PROVIDER_PROMPT_TOO_LARGE",
                "The bounded provider choice projection exceeds the model-facing prompt byte limit; the frozen request was not changed.",
                details={"hard_cap_bytes": hard_cap},
                status_code=413,
            )
        return declared

    @staticmethod
    def _provider_prompt(run: dict[str, Any]) -> str:
        # Rebuild at progressively shorter semantic-cue widths rather than
        # slicing serialized JSON.  Every returned value is therefore a
        # complete deterministic JSON object; an unusually large legal
        # envelope fails explicitly instead of being silently truncated.
        hard_fallback: tuple[int, str] | None = None
        for cue_limit, display_limit in (
            # Exhaust optional semantic cues/flavor while retaining full
            # display names.  Name contraction is a later phase so a compact
            # profile never trades away identity context prematurely.
            (180, 180),
            (120, 180),
            (80, 180),
            (48, 180),
            (32, 180),
            (24, 180),
            (16, 180),
            (8, 180),
            (6, 180),
            (0, 180),
            (0, 160),
            (0, 128),
            (0, 96),
            (0, 72),
            (0, 64),
            (0, 48),
            (0, 32),
            (0, 24),
            (0, 0),
        ):
            payload = _provider_payload(
                run,
                cue_limit=cue_limit,
                display_limit=display_limit,
            )
            payload = _provider_wire_compact_payload(payload)
            text = canonical_json(payload)
            size = len(text.encode("utf-8"))
            if size <= PROVIDER_PROMPT_TARGET_BYTES:
                return text
            if size <= PROVIDER_PROMPT_HARD_CAP_BYTES and (
                hard_fallback is None or size < hard_fallback[0]
            ):
                # Keep searching: a later, smaller semantic projection is a
                # valid hard-cap fallback when no candidate reaches target.
                hard_fallback = (size, text)
        if hard_fallback is not None:
            return hard_fallback[1]
        raise FoundryError(
            "CG1_PROVIDER_PROMPT_TOO_LARGE",
            "The bounded provider choice projection exceeds the model-facing prompt byte limit; the frozen request was not changed.",
            details={"hard_cap_bytes": PROVIDER_PROMPT_HARD_CAP_BYTES},
            status_code=413,
        )

    @staticmethod
    def _provider_free_talent_sphere_repair_target(
        diagnostic: Any,
        *,
        run: dict[str, Any] | None = None,
        prior_response: str | None = None,
    ) -> dict[str, Any] | None:
        """Derive the sole server repair for a free-talent owning-Sphere mismatch.

        The pair is already a provider selection.  Its owning Sphere is a
        catalog relationship, not a second AI decision.  This deliberately
        proves the relationship and the repaired slot cardinality from the
        sealed delegated envelope before adding the one canonical Sphere.
        """
        if not isinstance(diagnostic, dict):
            return None
        if diagnostic.get("code") != "CG1_DELEGATED_FREE_TALENT_SPHERE_MISMATCH":
            return None
        details = diagnostic.get("details")
        if not isinstance(details, dict) or set(details) != {
            "owning_sphere_id",
            "sphere_ids",
            "talent_id",
        }:
            return None
        owning_sphere_id = details.get("owning_sphere_id")
        talent_id = details.get("talent_id")
        sphere_ids = details.get("sphere_ids")
        if (
            not isinstance(owning_sphere_id, str)
            or not owning_sphere_id.strip()
            or not isinstance(talent_id, str)
            or not talent_id.strip()
            or not isinstance(sphere_ids, list)
            or sphere_ids != []
            or not isinstance(run, dict)
            or not isinstance(prior_response, str)
        ):
            return None
        request = run.get("request")
        if not isinstance(request, dict):
            return None
        envelope = request.get("delegated_choice_envelope")
        if not isinstance(envelope, dict):
            return None
        target_cl_record = envelope.get("frozen_owner_target_cl")
        target_cl = (
            target_cl_record.get("value")
            if isinstance(target_cl_record, dict)
            else target_cl_record
        )
        if type(target_cl) is not int or target_cl < 1:
            return None

        def strict_ids(value: Any) -> list[str] | None:
            if not isinstance(value, list):
                return None
            result: list[str] = []
            for item in value:
                if not isinstance(item, str) or not item.strip() or item in result:
                    return None
                result.append(item)
            return result

        def slot_row(slot_id: str, choice_id: str) -> dict[str, Any] | None:
            choices = envelope.get("choices_by_slot")
            choices = choices if isinstance(choices, dict) else {}
            raw_rows = choices.get(slot_id)
            if isinstance(raw_rows, dict):
                row = raw_rows.get(choice_id)
                return row if isinstance(row, dict) else None
            if isinstance(raw_rows, list):
                for row in raw_rows:
                    if isinstance(row, dict) and (
                        row.get("choice_id") == choice_id or row.get("id") == choice_id
                    ):
                        return row
            return None

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError):
            return None
        if not isinstance(prior_payload, dict):
            return None
        selection_intent = prior_payload.get("selection_intent")
        by_slot = selection_intent.get("by_slot") if isinstance(selection_intent, dict) else None
        if not isinstance(by_slot, dict):
            return None
        existing_spheres = by_slot.get("sphere_priorities")
        if existing_spheres is not None and (strict_ids(existing_spheres) != []):
            return None
        # The exact diagnostic says the Stage 2 audit saw no accepted Sphere.
        # An owner/model selection elsewhere would make this repair ambiguous.
        for slot_id, selected_ids in by_slot.items():
            if slot_id == "sphere_priorities":
                continue
            values = strict_ids(selected_ids)
            if values is None or owning_sphere_id in values:
                return None

        acquisition = prior_payload.get("acquisition_intent")
        pairs = acquisition.get("sphere_free_talent_pairs") if isinstance(acquisition, dict) else None
        if not isinstance(pairs, list) or len(pairs) != 1 or not isinstance(pairs[0], dict):
            return None
        pair = pairs[0]
        if set(pair) != {"sphere_id", "talent_id"}:
            return None
        if pair.get("sphere_id") != owning_sphere_id or pair.get("talent_id") != talent_id:
            return None

        allowed_by_slot = envelope.get("allowed_choice_ids_by_slot")
        offered_by_slot = envelope.get("offered_choice_ids_by_slot")
        nonselectable_by_slot = envelope.get("nonselectable_choice_ids_by_slot")
        unavailable_by_slot = envelope.get("unavailable_or_rejected_choice_ids_by_slot")
        if not all(isinstance(value, dict) for value in (
            allowed_by_slot,
            offered_by_slot,
            nonselectable_by_slot,
            unavailable_by_slot,
        )):
            return None
        allowed_spheres = strict_ids(allowed_by_slot.get("sphere_priorities"))
        offered_spheres = strict_ids(offered_by_slot.get("sphere_priorities"))
        blocked_spheres = strict_ids(nonselectable_by_slot.get("sphere_priorities"))
        unavailable_spheres = strict_ids(unavailable_by_slot.get("sphere_priorities"))
        allowed_talents = strict_ids(allowed_by_slot.get("advancement_skeleton"))
        offered_talents = strict_ids(offered_by_slot.get("advancement_skeleton"))
        blocked_talents = strict_ids(nonselectable_by_slot.get("advancement_skeleton"))
        unavailable_talents = strict_ids(unavailable_by_slot.get("advancement_skeleton"))
        if any(value is None for value in (
            allowed_spheres,
            offered_spheres,
            blocked_spheres,
            unavailable_spheres,
            allowed_talents,
            offered_talents,
            blocked_talents,
            unavailable_talents,
        )):
            return None
        if (
            owning_sphere_id not in allowed_spheres
            or owning_sphere_id not in offered_spheres
            or owning_sphere_id in blocked_spheres
            or owning_sphere_id in unavailable_spheres
            or talent_id not in allowed_talents
            or talent_id not in offered_talents
            or talent_id in blocked_talents
            or talent_id in unavailable_talents
        ):
            return None

        limits_by_slot = envelope.get("selection_limits_by_slot")
        limits_by_slot = limits_by_slot if isinstance(limits_by_slot, dict) else {}
        limits = limits_by_slot.get("sphere_priorities")
        if not isinstance(limits, dict):
            return None
        final_min = limits.get("final_min")
        final_max = limits.get("final_max")
        owner_min = limits.get("owner_lock_min", 0)
        owner_max = limits.get("owner_lock_max")
        if (
            type(final_min) is not int
            or final_min < 0
            or final_min > 1
            or (final_max is not None and type(final_max) is not int)
            or (type(final_max) is int and (final_max < 1 or final_max < final_min))
            or type(owner_min) is not int
            or owner_min < 0
            or owner_min > 1
            or (owner_max is not None and type(owner_max) is not int)
            or (type(owner_max) is int and (owner_max < 1 or owner_max < owner_min))
        ):
            return None
        owner_locks = envelope.get("owner_locks")
        owner_locks = owner_locks if isinstance(owner_locks, dict) else {}
        owner_lock_slots = owner_locks.get("by_slot")
        owner_lock_slots = owner_lock_slots if isinstance(owner_lock_slots, dict) else owner_locks
        locked_spheres = strict_ids(owner_lock_slots.get("sphere_priorities", []))
        if locked_spheres is None or locked_spheres:
            return None
        # If the Stage 1 authority publishes a slot row, require that one
        # repaired selection is also inside its cardinality bounds.
        stage1_slots = ((request.get("stage1_prompt") or {}).get("envelope") or {}).get("decision_slots")
        if isinstance(stage1_slots, list):
            for slot in stage1_slots:
                if not isinstance(slot, dict) or slot.get("slot_id") != "sphere_priorities":
                    continue
                stage_min = slot.get("min_selections")
                stage_max = slot.get("max_selections")
                if (
                    (stage_min is not None and type(stage_min) is not int)
                    or (type(stage_min) is int and (stage_min < 0 or stage_min > 1))
                    or (stage_max is not None and type(stage_max) is not int)
                    or (type(stage_max) is int and (
                        stage_max < 1
                        or (type(stage_min) is int and stage_max < stage_min)
                    ))
                ):
                    return None
                break

        sphere_row = slot_row("sphere_priorities", owning_sphere_id)
        talent_row = slot_row("advancement_skeleton", talent_id)
        if not isinstance(sphere_row, dict) or not isinstance(talent_row, dict):
            return None
        if (
            sphere_row.get("choice_id", owning_sphere_id) != owning_sphere_id
            or sphere_row.get("content_type") != "sphere"
            or sphere_row.get("authority") != "canonical"
            or sphere_row.get("publication_state") != "published"
            or not isinstance(sphere_row.get("acquisition_channels"), list)
            or not any(isinstance(value, str) and value.strip() for value in sphere_row["acquisition_channels"])
            or talent_row.get("choice_id", talent_id) != talent_id
            or talent_row.get("content_type") != "talent"
            or talent_row.get("authority") != "canonical"
            or talent_row.get("publication_state") != "published"
            or not isinstance(talent_row.get("acquisition_channels"), list)
            or not any(isinstance(value, str) and value.strip() for value in talent_row["acquisition_channels"])
        ):
            return None
        parents = talent_row.get("parent_relationships")
        if not isinstance(parents, list) or not any(
            isinstance(parent, dict)
            and parent.get("record_id") == owning_sphere_id
            and parent.get("relation") == "dependency"
            for parent in parents
        ):
            return None

        availability = envelope.get("prerequisites_and_availability")
        availability = availability if isinstance(availability, dict) else {}
        sphere_availability = availability.get("sphere_priorities")
        sphere_availability = sphere_availability if isinstance(sphere_availability, dict) else {}
        availability_row = sphere_availability.get(owning_sphere_id)
        if not isinstance(availability_row, dict):
            return None
        source_availability = sphere_row.get("availability")
        frozen_availability = availability_row.get("availability")
        if not isinstance(source_availability, dict) or source_availability != frozen_availability:
            return None
        minimum_cl = source_availability.get("minimum_cl")
        if type(minimum_cl) is int and minimum_cl > target_cl:
            return None
        for field in ("realm_rules", "source_cl", "suppression"):
            if source_availability.get(field) not in ({}, None):
                return None
        prerequisites = sphere_row.get("prerequisites")
        incompatibilities = sphere_row.get("incompatibilities")
        frozen_prerequisites = availability_row.get("prerequisites")
        frozen_incompatibilities = availability_row.get("incompatibilities")
        if (
            not isinstance(prerequisites, list)
            or not isinstance(incompatibilities, list)
            or prerequisites != frozen_prerequisites
            or incompatibilities != frozen_incompatibilities
            or prerequisites
            or incompatibilities
        ):
            return None
        talent_availability = talent_row.get("availability")
        if not isinstance(talent_availability, dict):
            return None
        talent_minimum_cl = talent_availability.get("minimum_cl")
        if type(talent_minimum_cl) is int and talent_minimum_cl > target_cl:
            return None

        return {
            "target_kind": "free_talent_sphere_server_repair",
            "field": "selection_intent.by_slot.sphere_priorities",
            "selected_sphere_ids": [owning_sphere_id],
            "owning_sphere_id": owning_sphere_id,
            "talent_id": talent_id,
            "target_cl": target_cl,
            "required_count": 1,
            "selection_limits": {
                "final_min": final_min,
                "final_max": final_max,
                "owner_lock_min": owner_min,
                "owner_lock_max": owner_max,
            },
            "preserve_all_other_values": True,
            "deterministic_server_repair": True,
            "instruction": (
                "The free Sphere Talent pair already identifies its canonical owning Sphere; "
                "the server will add exactly that one frozen Sphere priority."
            ),
        }

    @staticmethod
    def _provider_free_talent_not_legal_repair_target(
        diagnostic: Any,
        *,
        run: dict[str, Any] | None,
        prior_response: str | None,
    ) -> dict[str, Any] | None:
        """Derive opaque legal pair options for one route-authority mismatch.

        This target is explicit-correction-only.  The retained response is
        authoritative for every field except the one failing pair occurrence;
        the provider chooses an opaque option whose Sphere and free Talent
        both advertise the frozen route-specific Stage 2 kinds.
        """

        if not isinstance(run, dict) or not isinstance(prior_response, str):
            return None
        if not isinstance(diagnostic, dict) or diagnostic.get("code") != "CG1_DELEGATED_FREE_TALENT_NOT_LEGAL":
            return None
        details = diagnostic.get("details")
        required_detail_keys = {
            "sphere_id",
            "talent_id",
            "route",
            "required_sphere_kind",
            "required_talent_kind",
            "advertised_sphere_kinds",
            "advertised_talent_kinds",
        }
        if not isinstance(details, dict) or set(details) != required_detail_keys:
            return None
        sphere_id = details.get("sphere_id")
        talent_id = details.get("talent_id")
        route = details.get("route")
        if (
            not isinstance(sphere_id, str)
            or not sphere_id.strip()
            or not isinstance(talent_id, str)
            or not talent_id.strip()
            or not isinstance(route, str)
            or not route.strip()
        ):
            return None
        expected_sphere_kind = (
            "ai_bootstrap_sphere_acquisition"
            if route == "ai_bootstrap"
            else "sect_trial_sphere_acquisition"
        )
        expected_talent_kind = (
            "ai_bootstrap_talent_acquisition"
            if route == "ai_bootstrap"
            else "sect_trial_talent_acquisition"
        )
        if (
            details.get("required_sphere_kind") != expected_sphere_kind
            or details.get("required_talent_kind") != expected_talent_kind
        ):
            return None

        def clean_ids(value: Any) -> list[str] | None:
            if not isinstance(value, list):
                return None
            result: list[str] = []
            for item in value:
                if not isinstance(item, str) or not item.strip() or item in result:
                    return None
                result.append(item)
            return result

        advertised_sphere_kinds = clean_ids(details.get("advertised_sphere_kinds"))
        advertised_talent_kinds = clean_ids(details.get("advertised_talent_kinds"))
        if advertised_sphere_kinds is None or advertised_talent_kinds is None:
            return None
        if expected_sphere_kind in advertised_sphere_kinds and expected_talent_kind in advertised_talent_kinds:
            return None

        request = run.get("request")
        if not isinstance(request, dict):
            return None
        envelope = request.get("delegated_choice_envelope")
        if not isinstance(envelope, dict):
            return None
        if _provider_free_sphere_kind(request) != expected_sphere_kind:
            return None
        target_record = envelope.get("frozen_owner_target_cl")
        target_cl = target_record.get("value") if isinstance(target_record, dict) else target_record
        if type(target_cl) is not int or target_cl < 1:
            return None

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError):
            return None
        if not isinstance(prior_payload, dict):
            return None
        acquisition = prior_payload.get("acquisition_intent")
        pairs = acquisition.get("sphere_free_talent_pairs") if isinstance(acquisition, dict) else None
        if not isinstance(pairs, list) or not pairs:
            return None
        normalized_pairs: list[dict[str, str]] = []
        matching_indexes: list[int] = []
        seen_pairs: set[tuple[str, str]] = set()
        for index, pair in enumerate(pairs):
            if not isinstance(pair, dict):
                return None
            current_sphere = pair.get("sphere_id")
            current_talent = pair.get("talent_id")
            if (
                not isinstance(current_sphere, str)
                or not current_sphere.strip()
                or not isinstance(current_talent, str)
                or not current_talent.strip()
            ):
                return None
            pair_key = (current_sphere, current_talent)
            if pair_key in seen_pairs:
                return None
            seen_pairs.add(pair_key)
            normalized_pairs.append({"sphere_id": current_sphere, "talent_id": current_talent})
            if current_sphere == sphere_id and current_talent == talent_id:
                matching_indexes.append(index)
        if len(matching_indexes) != 1:
            return None
        pair_index = matching_indexes[0]

        choices_by_slot = envelope.get("choices_by_slot")
        choices_by_slot = choices_by_slot if isinstance(choices_by_slot, dict) else {}
        sphere_rows = choices_by_slot.get("sphere_priorities")
        talent_rows = choices_by_slot.get("advancement_skeleton")
        if not isinstance(sphere_rows, dict) or not isinstance(talent_rows, dict):
            return None
        allowed_by_slot = envelope.get("allowed_choice_ids_by_slot")
        offered_by_slot = envelope.get("offered_choice_ids_by_slot")
        if not isinstance(allowed_by_slot, dict) or not isinstance(offered_by_slot, dict):
            return None
        nonselectable_by_slot = envelope.get("nonselectable_choice_ids_by_slot") or {}
        unavailable_by_slot = envelope.get("unavailable_or_rejected_choice_ids_by_slot") or {}
        if not isinstance(nonselectable_by_slot, dict) or not isinstance(unavailable_by_slot, dict):
            return None
        allowed_spheres = clean_ids(allowed_by_slot.get("sphere_priorities"))
        offered_spheres = clean_ids(offered_by_slot.get("sphere_priorities"))
        allowed_talents = clean_ids(allowed_by_slot.get("advancement_skeleton"))
        offered_talents = clean_ids(offered_by_slot.get("advancement_skeleton"))
        if None in (allowed_spheres, offered_spheres, allowed_talents, offered_talents):
            return None
        excluded_spheres = set(clean_ids(nonselectable_by_slot.get("sphere_priorities")) or []) | set(
            clean_ids(unavailable_by_slot.get("sphere_priorities")) or []
        )
        excluded_talents = set(clean_ids(nonselectable_by_slot.get("advancement_skeleton")) or []) | set(
            clean_ids(unavailable_by_slot.get("advancement_skeleton")) or []
        )
        sphere_ids = sorted(set(allowed_spheres or []) & set(offered_spheres or []) - excluded_spheres)
        talent_ids = sorted(set(allowed_talents or []) & set(offered_talents or []) - excluded_talents)
        if not sphere_ids or not talent_ids:
            return None

        def source_id(row: dict[str, Any], fallback: str) -> str:
            value = row.get("choice_id") or row.get("id")
            return value if isinstance(value, str) and value.strip() else fallback

        def minimum_cl(row: dict[str, Any], authority: dict[str, Any]) -> int | None:
            value = authority.get("minimum_cl")
            if type(value) is int:
                return value
            availability = row.get("availability")
            value = availability.get("minimum_cl") if isinstance(availability, dict) else row.get("minimum_cl")
            return value if type(value) is int else None

        def summary(row: dict[str, Any], choice_id: str, fallback: str) -> dict[str, str]:
            return {
                "id": choice_id,
                "name": _provider_short_text(
                    row.get("display_name") or row.get("name"),
                    96,
                    choice_id,
                ),
                "cue": _provider_short_text(
                    row.get("semantic_cue") or row.get("description"),
                    180,
                    fallback,
                ),
            }

        try:
            compact_model = build_compact_choice_model(request)
            free_talent_shortlist = _provider_free_talent_pair_shortlist(
                request,
                compact_model,
                target_cl=target_cl,
            )
            bounded_pairs = _provider_free_talent_pairs(
                request,
                compact_model,
                free_talent_shortlist,
            )
        except (KeyError, TypeError, ValueError):
            return None
        # Every pair has already passed the sealed route/authority checks;
        # retain only the deterministic first 256 after the balanced
        # two-per-Sphere shortlist so a large catalog cannot suppress the
        # correction target.  This is a presentation bound, not a legality
        # expansion.
        bounded_pairs = sorted(
            bounded_pairs,
            key=lambda pair: (pair.get("sphere_id", ""), pair.get("talent_id", "")),
        )[:256]
        if not bounded_pairs:
            return None
        retained_spheres = {
            pair["sphere_id"]
            for index, pair in enumerate(normalized_pairs)
            if index != pair_index
        }
        retained_talents = {
            pair["talent_id"]
            for index, pair in enumerate(normalized_pairs)
            if index != pair_index
        }

        candidate_rows: list[dict[str, Any]] = []
        for bounded_pair in bounded_pairs:
            candidate_sphere_id = bounded_pair.get("sphere_id")
            candidate_talent_id = bounded_pair.get("talent_id")
            if (
                not isinstance(candidate_sphere_id, str)
                or candidate_sphere_id not in sphere_ids
                or not isinstance(candidate_talent_id, str)
                or candidate_talent_id not in talent_ids
                or candidate_sphere_id in retained_spheres
                or candidate_talent_id in retained_talents
            ):
                continue
            sphere_row = sphere_rows.get(candidate_sphere_id)
            if not isinstance(sphere_row, dict) or source_id(sphere_row, candidate_sphere_id) != candidate_sphere_id:
                continue
            sphere_authority = choice_authority(
                envelope,
                "sphere_priorities",
                candidate_sphere_id,
                sphere_row,
            )
            sphere_allowed_kinds = _provider_stage2_allowed_kinds(sphere_authority, sphere_row)
            sphere_minimum_cl = minimum_cl(sphere_row, sphere_authority)
            if (
                not _provider_source_authority_complete(sphere_authority, sphere_row)
                or expected_sphere_kind not in sphere_allowed_kinds
                or (
                    sphere_minimum_cl is not None
                    and (sphere_minimum_cl < 0 or sphere_minimum_cl > target_cl)
                )
            ):
                continue
            talent_row = talent_rows.get(candidate_talent_id)
            if not isinstance(talent_row, dict) or source_id(talent_row, candidate_talent_id) != candidate_talent_id:
                continue
            talent_authority = choice_authority(
                envelope,
                "advancement_skeleton",
                candidate_talent_id,
                talent_row,
            )
            talent_allowed_kinds = _provider_stage2_allowed_kinds(talent_authority, talent_row)
            owner = (
                talent_authority.get("owning_canonical_sphere_id")
                or talent_authority.get("owning_sphere_id")
                or talent_authority.get("sphere_id")
                or talent_row.get("owner")
            )
            talent_minimum_cl = minimum_cl(talent_row, talent_authority)
            if (
                not _provider_source_authority_complete(talent_authority, talent_row)
                or expected_talent_kind not in talent_allowed_kinds
                or owner != candidate_sphere_id
                or (
                    talent_minimum_cl is not None
                    and (talent_minimum_cl < 0 or talent_minimum_cl > target_cl)
                )
                or talent_authority.get("free_sphere_talent_eligible") is False
                or talent_row.get("free_sphere_talent_eligible") is False
            ):
                continue
            candidate_rows.append({
                "sphere_id": candidate_sphere_id,
                "talent_id": candidate_talent_id,
                "sphere": summary(sphere_row, candidate_sphere_id, "Presented Sphere choice."),
                "talent": summary(talent_row, candidate_talent_id, "Presented free-Talent choice."),
            })
        if not candidate_rows or len(candidate_rows) > 256:
            return None
        options: dict[str, dict[str, str]] = {}
        summaries: list[dict[str, Any]] = []
        for candidate in sorted(candidate_rows, key=lambda item: (item["sphere_id"], item["talent_id"])):
            mapping = {
                "sphere_id": candidate["sphere_id"],
                "talent_id": candidate["talent_id"],
            }
            option_id = "ftp_" + sha256_json(mapping)[:20]
            if option_id in options and options[option_id] != mapping:
                return None
            options[option_id] = mapping
            summaries.append({
                "option_id": option_id,
                "sphere": candidate["sphere"],
                "talent": candidate["talent"],
            })
        option_ids = sorted(options)
        return {
            "target_kind": "free_talent_not_legal",
            "explicit_only": True,
            "field": "acquisition_intent.sphere_free_talent_pairs",
            "pair_index": pair_index,
            "expected_pair_count": len(normalized_pairs),
            "failing_pair": {"sphere_id": sphere_id, "talent_id": talent_id},
            "route": route,
            "required_sphere_kind": expected_sphere_kind,
            "required_talent_kind": expected_talent_kind,
            "candidate_summaries": summaries,
            "option_ids": option_ids,
            "options": options,
            "response_schema": {
                "type": "object",
                "additionalProperties": False,
                "required": ["option_id"],
                "properties": {"option_id": {"type": "string", "enum": option_ids}},
            },
            "preserve_all_other_values": True,
            "instruction": (
                "Choose exactly one opaque option_id for a legal frozen Sphere/free-Talent pair. "
                "The server replaces only the failing pair occurrence; every other retained response field and pair remains unchanged."
            ),
        }

    @staticmethod
    def _provider_acquisition_contract_repair_target(
        diagnostic: Any,
        *,
        run: dict[str, Any] | None,
        prior_response: str | None,
    ) -> dict[str, Any] | None:
        """Derive bounded server-owned acquisition options for one preflight failure."""
        if (
            not isinstance(diagnostic, dict)
            or diagnostic.get("code") != "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID"
            or not isinstance(run, dict)
            or not isinstance(prior_response, str)
        ):
            return None
        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError):
            return None
        if not isinstance(prior_payload, dict):
            return None
        request = run.get("request")
        if not isinstance(request, dict):
            return None
        if prior_payload.get("request_sha256") != request.get("request_sha256"):
            return None
        provider_payload = _provider_payload(run, cue_limit=0, display_limit=0)
        contract = provider_payload.get("response_contract") or {}
        expected = contract.get("expected_acquisition_counts")
        expected = expected if isinstance(expected, dict) else {}
        pair_count = expected.get("sphere_free_talent_pairs")
        ordinary_count = expected.get("ordinary_talent_ids")
        if (
            type(pair_count) is not int
            or pair_count < 0
            or type(ordinary_count) is not int
            or ordinary_count < 0
        ):
            return None
        presented_pairs: list[dict[str, str]] = []
        for row in contract.get("presented_legal_first_cycle_pairs") or []:
            if not isinstance(row, dict) or set(row) != {"sphere_id", "talent_id"}:
                return None
            sphere_id = row.get("sphere_id")
            talent_id = row.get("talent_id")
            if not isinstance(sphere_id, str) or not sphere_id or not isinstance(talent_id, str) or not talent_id:
                return None
            normalized = {"sphere_id": sphere_id, "talent_id": talent_id}
            if normalized not in presented_pairs:
                presented_pairs.append(normalized)
        if pair_count > len(presented_pairs):
            return None
        ordinary_by_cl = contract.get("presented_legal_ordinary_talent_ids_by_cl")
        ordinary_by_cl = ordinary_by_cl if isinstance(ordinary_by_cl, dict) else {}
        if not ordinary_by_cl:
            # Route-bearing prompts publish one top-level route list and an
            # explicit contract reference instead of duplicating its CL map.
            # Derive the same union for the bounded correction option; the
            # sealed envelope is still checked by the normal validator.
            derived_ordinary_by_cl: dict[str, list[str]] = {}
            for route in provider_payload.get("sphere_route_modules") or []:
                if not isinstance(route, dict):
                    continue
                for cl, value in (route.get("ordinary_talent_ids_by_cl") or {}).items():
                    if isinstance(cl, str) and isinstance(value, str):
                        derived_ordinary_by_cl.setdefault(cl, []).append(value)
            ordinary_by_cl = {
                cl: sorted(set(values))
                for cl, values in sorted(derived_ordinary_by_cl.items())
            }
        ordinary_choices: list[list[str]] = []
        for cl in range(1, ordinary_count + 1):
            values = ordinary_by_cl.get(str(cl))
            if not isinstance(values, list):
                return None
            clean: list[str] = []
            for value in values:
                if not isinstance(value, str) or not value:
                    return None
                if value not in clean:
                    clean.append(value)
            if not clean:
                return None
            ordinary_choices.append(clean)

        pair_space = math.comb(len(presented_pairs), pair_count) if pair_count else 1
        ordinary_space = math.prod(len(choice) for choice in ordinary_choices) if ordinary_choices else 1
        # Decide from the arithmetic size, never by building the product.  The
        # old code materialized ``list(itertools.product(...))`` here and only
        # discovered the space was too large after allocating it; see
        # _PROVIDER_REPAIR_ENUMERATION_CEILING.  Every space within the budget
        # is still enumerated exactly as before, so small cases are unchanged.
        if pair_space * ordinary_space > _PROVIDER_REPAIR_ENUMERATION_CEILING:
            return None
        pair_products = itertools.combinations(presented_pairs, pair_count) if pair_count else [()]
        options: dict[str, dict[str, Any]] = {}
        for pair_tuple in pair_products:
            free_ids = {row["talent_id"] for row in pair_tuple}
            ordinary_products = itertools.product(*ordinary_choices) if ordinary_choices else [()]
            for ordinary_tuple in ordinary_products:
                if len(set(ordinary_tuple)) != len(ordinary_tuple) or any(value in free_ids for value in ordinary_tuple):
                    continue
                mapping = {
                    "sphere_free_talent_pairs": [deepcopy(row) for row in pair_tuple],
                    "ordinary_talent_ids": list(ordinary_tuple),
                }
                option_id = "acq_" + sha256_json(mapping)[:20]
                if option_id in options and options[option_id] != mapping:
                    return None
                options[option_id] = mapping
                if len(options) > 256:
                    return None
        if not options:
            return None
        option_ids = sorted(options)
        return {
            "target_kind": "acquisition_contract",
            "fields": [
                "acquisition_intent.sphere_free_talent_pairs",
                "acquisition_intent.ordinary_talent_ids",
                "selection_intent.by_slot.advancement_skeleton",
            ],
            "expected_counts": {
                "sphere_free_talent_pairs": pair_count,
                "ordinary_talent_ids": ordinary_count,
            },
            "option_ids": option_ids,
            "options": options,
            "response_schema": {
                "type": "object",
                "additionalProperties": False,
                "required": ["option_id"],
                "properties": {"option_id": {"type": "string", "enum": option_ids}},
            },
            "preserve_all_other_values": True,
            "instruction": (
                "Choose one opaque server-owned acquisition option. The server replaces only the "
                "free-pair array, ordinary-Talent array, and its advancement-skeleton mirror."
            ),
        }

    @staticmethod
    def _provider_bounded_field_cleanup_repair_target(
        diagnostic: Any,
        *,
        run: dict[str, Any] | None,
        prior_response: str | None,
    ) -> dict[str, Any] | None:
        """Derive one fail-closed cleanup for an empty unadvertised field.

        A model may occasionally emit an empty alias in ``bounded_choices``.
        Removing that alias is safe only when the sealed request's complete
        bounded-field contract proves it was not advertised and the validator
        named exactly that field.  No other response value is inferred or
        rewritten here.
        """
        if (
            not isinstance(diagnostic, dict)
            or diagnostic.get("code") != "CG1_PREFERRED_RESPONSE_BOUNDED_FIELD_INVALID"
            or not isinstance(run, dict)
            or not isinstance(prior_response, str)
        ):
            return None
        details = diagnostic.get("details")
        fields = details.get("fields") if isinstance(details, dict) else None
        if (
            not isinstance(fields, list)
            or not fields
            or any(
                not isinstance(field, str)
                or not field.strip()
                or field != field.strip()
                or "." in field
                or not field.isidentifier()
                for field in fields
            )
            or len(set(fields)) != len(fields)
        ):
            return None

        request = run.get("request")
        if not isinstance(request, dict):
            return None
        if (
            request.get("project_id") != run.get("project_id")
            or request.get("project_revision") != run.get("starting_revision")
        ):
            return None
        request_sha256 = request.get("request_sha256")
        if not isinstance(request_sha256, str) or not request_sha256:
            return None
        bounded_contract = request.get("bounded_choice_contract")
        if not isinstance(bounded_contract, dict) or bounded_contract.get("schema") != "TianxiaFoundry.BoundedChoiceContract.v1":
            return None
        contract_fields = bounded_contract.get("fields")
        if not isinstance(contract_fields, dict) or not contract_fields:
            return None
        advertised = sorted(
            key
            for key in contract_fields
            if isinstance(key, str) and key.strip() and key == key.strip()
        )
        if not advertised:
            return None

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError):
            return None
        if not isinstance(prior_payload, dict) or prior_payload.get("request_sha256") != request_sha256:
            return None
        bounded_choices = prior_payload.get("bounded_choices")
        if not isinstance(bounded_choices, dict):
            return None

        normalized_fields = sorted(fields)

        def structurally_empty(value: Any) -> bool:
            # Null has no typed value and is therefore equivalent to omission
            # for an unadvertised key.  Objects/arrays must be genuinely empty;
            # scalar false/zero values are not eligible for cleanup.
            return value is None or (
                isinstance(value, (dict, list)) and not value
            )

        for field in normalized_fields:
            if field in advertised or field not in bounded_choices:
                return None
            if not structurally_empty(bounded_choices[field]):
                return None
        return {
            "target_kind": "bounded_field_cleanup",
            "fields": normalized_fields,
            "advertised_bounded_choice_keys": advertised,
            "request_sha256": request_sha256,
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "preserve_all_other_values": True,
            "empty_value_policy": "empty_object_array_or_null",
            "instruction": (
                "Remove only the diagnostically named unadvertised bounded_choices "
                "keys when their values are structurally empty; preserve every "
                "advertised and unrelated response field exactly."
            ),
        }

    @staticmethod
    def _provider_bounded_path_progression_empty_cleanup_repair_target(
        diagnostic: Any,
        *,
        run: dict[str, Any] | None,
        prior_response: str | None,
    ) -> dict[str, Any] | None:
        """Derive a provider-free removal of empty Path progression placeholders.

        A bounded compiler decision with ``requested_path == []`` means that
        the retained response supplied an empty placeholder.  Removing those
        placeholders is safe only when the exact reported CL is also empty in
        the retained response.  No Path is selected here; the normal frozen
        authority remains responsible for inferring a sole Path or surfacing a
        genuine zero/multi-Path decision after cleanup.
        """
        if (
            not isinstance(diagnostic, dict)
            or diagnostic.get("code") != "CG1_BOUNDED_DECISION_REQUIRED"
            or not isinstance(run, dict)
            or not isinstance(prior_response, str)
        ):
            return None
        details = diagnostic.get("details")
        if not isinstance(details, dict) or type(details.get("requested_path")) is not list:
            return None
        if details.get("requested_path") != []:
            return None
        reported_cl = details.get("cl")
        if type(reported_cl) is not int or reported_cl < 1:
            return None

        request = run.get("request")
        if not isinstance(request, dict):
            return None
        request_sha256 = request.get("request_sha256")
        if not isinstance(request_sha256, str) or not request_sha256:
            return None
        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError):
            return None
        if not isinstance(prior_payload, dict) or prior_payload.get("request_sha256") != request_sha256:
            return None
        bounded_choices = prior_payload.get("bounded_choices")
        if not isinstance(bounded_choices, dict):
            return None
        progression = bounded_choices.get("path_progression_by_cl")
        if not isinstance(progression, dict):
            return None

        reported_key = str(reported_cl)
        if type(progression.get(reported_key)) is not list or progression.get(reported_key) != []:
            return None

        def canonical_cl_key(value: Any) -> bool:
            if not isinstance(value, str) or not value.strip():
                return False
            try:
                parsed = int(value)
            except (TypeError, ValueError):
                return False
            return parsed >= 1 and str(parsed) == value

        removed_cl_keys: list[str] = []
        for key, value in progression.items():
            if type(value) is list and value == []:
                if not canonical_cl_key(key):
                    return None
                removed_cl_keys.append(key)
        if reported_key not in removed_cl_keys:
            return None
        removed_cl_keys.sort(key=int)
        return {
            "target_kind": "bounded_path_progression_empty_cleanup",
            "field": "bounded_choices.path_progression_by_cl",
            "reported_cl": reported_cl,
            "removed_cl_keys": removed_cl_keys,
            "request_sha256": request_sha256,
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "preserve_all_other_values": True,
            "empty_value_policy": "empty_path_progression_lists_only",
            "instruction": (
                "Remove only the empty bounded_choices.path_progression_by_cl "
                "entries recorded in removed_cl_keys; do not select or invent a "
                "Path ID and preserve every nonempty progression and other value."
            ),
        }

    @staticmethod
    def _provider_correction_requires_target(diagnostic: Any) -> bool:
        """Return whether this diagnostic may never use a generic full retry."""
        if not isinstance(diagnostic, dict):
            return False
        if diagnostic.get("code") == "CG1_DELEGATED_FREE_TALENT_NOT_LEGAL":
            return True
        if diagnostic.get("code") == "CG1_PREFERRED_RESPONSE_BOUNDED_FIELD_INVALID":
            return True
        details = diagnostic.get("details")
        if (
            diagnostic.get("code") == "CG1_BOUNDED_DECISION_REQUIRED"
            and isinstance(details, dict)
            and isinstance(details.get("milestone_id"), str)
            and details.get("field") == (
                "bounded_choices.ability_score_changes_by_milestone_id."
                + details["milestone_id"]
            )
        ):
            return True
        if (
            diagnostic.get("code") == "CG1_BOUNDED_DECISION_REQUIRED"
            and isinstance(details, dict)
            and "requested_path" in details
        ):
            return True
        if diagnostic.get("code") == "CG1_DELEGATED_DUPLICATE_CHOICE":
            return True
        return (
            diagnostic.get("code") == "CG1_DELEGATED_CHOICE_UNAVAILABLE"
            and isinstance(details, dict)
            and details.get("slot_id") == "insight_priorities"
        )

    @staticmethod
    def _provider_advancement_choice_repair_target(
        diagnostic: Any,
        *,
        run: dict[str, Any] | None,
        prior_response: str | None,
    ) -> dict[str, Any] | None:
        """Build one opaque selector for one missing Advancement Choice.

        The provider only sees display/cue projections and opaque option IDs.
        The typed owner-decision values remain server-owned in ``options`` and
        are regenerated from the same source-backed authority at merge time.
        """
        if not isinstance(run, dict) or not isinstance(prior_response, str):
            return None
        details = diagnostic.get("details") if isinstance(diagnostic, dict) else None
        if not isinstance(details, dict):
            return None
        milestone_id = details.get("milestone_id")
        field = details.get("field")
        expected_field = (
            f"bounded_choices.ability_score_changes_by_milestone_id.{milestone_id}"
            if isinstance(milestone_id, str) and milestone_id.strip()
            else None
        )
        if (
            not isinstance(milestone_id, str)
            or not milestone_id.strip()
            or milestone_id != milestone_id.strip()
            or not isinstance(field, str)
            or field != expected_field
        ):
            return None
        effective_cl = details.get("effective_cl")
        if type(effective_cl) is not int:
            effective_cl = details.get("cl")
        if type(effective_cl) is not int or effective_cl < 1:
            return None

        request = run.get("request")
        if not isinstance(request, dict):
            return None
        if (
            request.get("project_id") != run.get("project_id")
            or request.get("project_revision") != run.get("starting_revision")
        ):
            return None
        request_sha256 = request.get("request_sha256")
        if not isinstance(request_sha256, str) or len(request_sha256) != 64:
            return None
        prior_response_sha256 = sha256_bytes(prior_response.encode("utf-8"))

        def strict_object(text: str) -> dict[str, Any] | None:
            def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
                result: dict[str, Any] = {}
                for key, value in items:
                    if key in result:
                        raise ValueError("duplicate object key")
                    result[key] = value
                return result

            try:
                value = json.loads(text, object_pairs_hook=pairs)
            except (TypeError, ValueError, json.JSONDecodeError):
                return None
            return value if isinstance(value, dict) else None

        prior_payload = strict_object(prior_response)
        if prior_payload is None or prior_payload.get("request_sha256") != request_sha256:
            return None
        bounded = prior_payload.get("bounded_choices")
        if not isinstance(bounded, dict):
            return None
        changes = bounded.get("ability_score_changes_by_milestone_id")
        if not isinstance(changes, dict) or milestone_id in changes:
            return None
        acquisition = prior_payload.get("acquisition_intent")
        if not isinstance(acquisition, dict):
            return None
        occurrences = acquisition.get("insight_occurrences")
        if not isinstance(occurrences, list):
            return None
        if any(
            isinstance(row, dict) and row.get("milestone_id") == milestone_id
            for row in occurrences
        ):
            return None

        envelope = request.get("delegated_choice_envelope")
        if not isinstance(envelope, dict):
            return None
        milestone_rows: dict[str, dict[str, Any]] = {}
        for row in envelope.get("advancement_choice_milestones") or []:
            if not isinstance(row, dict) or not isinstance(row.get("milestone_id"), str):
                continue
            if row["milestone_id"] in milestone_rows:
                return None
            milestone_rows[row["milestone_id"]] = row
        milestone = milestone_rows.get(milestone_id)
        if not isinstance(milestone, dict):
            return None
        milestone_cl = milestone.get("cl", milestone.get("effective_cl"))
        if type(milestone_cl) is not int or milestone_cl != effective_cl:
            return None

        selection = prior_payload.get("selection_intent")
        selected_by_slot = selection.get("by_slot") if isinstance(selection, dict) else {}
        selected_by_slot = selected_by_slot if isinstance(selected_by_slot, dict) else {}
        authority_by_milestone = run.get("owner_decision_authority")
        authority_by_milestone = (
            authority_by_milestone
            if isinstance(authority_by_milestone, dict)
            else {}
        )
        try:
            enriched = enrich_milestone_details(
                details,
                envelope=envelope,
                proposal_bounded=bounded,
                proposal_acquisition=acquisition,
                proposal_selected_by_slot=selected_by_slot,
                authority_by_milestone=authority_by_milestone,
            )
        except (KeyError, TypeError, ValueError):
            return None
        legal_choices = enriched.get("legal_choices") if isinstance(enriched, dict) else None
        if not isinstance(legal_choices, list) or not legal_choices:
            return None
        allowed_kinds = [
            kind
            for kind in (enriched.get("allowed_kinds") or milestone.get("allowed_kinds") or [])
            if isinstance(kind, str)
        ]
        allowed_kinds = sorted(set(allowed_kinds))
        if not allowed_kinds or not set(allowed_kinds) & {
            "ability_score_change",
            "cultivation_insight_acquisition",
        }:
            return None

        def typed_value(raw_choice: Any) -> tuple[str, dict[str, Any]] | None:
            if not isinstance(raw_choice, dict) or not isinstance(raw_choice.get("value"), dict):
                return None
            value = deepcopy(raw_choice["value"])
            kind = value.get("kind")
            if kind not in {"ability_score_change", "cultivation_insight_acquisition"}:
                return None
            if value.get("milestone_id") != milestone_id:
                return None
            if kind == "ability_score_change":
                deltas = value.get("deltas")
                if (
                    not isinstance(deltas, dict)
                    or not deltas
                    or any(
                        ability not in _PROVIDER_POINT_BUY_ABILITIES
                        or type(delta) is not int
                        for ability, delta in deltas.items()
                    )
                ):
                    return None
                if set(value) != {"kind", "milestone_id", "deltas"}:
                    return None
            else:
                insight_id = value.get("insight_id")
                if not isinstance(insight_id, str) or not insight_id.strip():
                    return None
                parameters = value.get("parameters")
                if parameters is not None and not isinstance(parameters, dict):
                    return None
                if (
                    isinstance(parameters, dict)
                    and (
                        set(parameters) != {"ability"}
                        or not isinstance(parameters.get("ability"), str)
                        or not parameters.get("ability", "").strip()
                    )
                ):
                    return None
                if set(value) - {"kind", "milestone_id", "insight_id", "parameters"}:
                    return None
            if kind not in allowed_kinds:
                return None
            return kind, value

        options: dict[str, dict[str, Any]] = {}
        summaries: dict[str, dict[str, Any]] = {}
        for raw_choice in legal_choices:
            typed = typed_value(raw_choice)
            if typed is None:
                return None
            kind, value = typed
            projection = CharacterCreationExecutionService._manual_bounded_candidate(
                raw_choice,
                field=field,
                milestone_id=milestone_id,
            )
            if projection.get("milestone_id") != milestone_id:
                return None
            option_id = "adv_" + sha256_json({"kind": kind, "value": value})[:24]
            option = {
                "value": value,
                "kind": kind,
                "milestone_id": milestone_id,
            }
            existing = options.get(option_id)
            if existing is not None and existing != option:
                return None
            options[option_id] = option
            display_name = _provider_short_text(
                projection.get("display_name"),
                120,
                "Ability-score improvement" if kind == "ability_score_change" else "Cultivation Insight",
            )
            semantic_cue = _provider_short_text(
                projection.get("semantic_cue"),
                180,
                "Choose this source-backed advancement resolution.",
            )
            # Stable source IDs never need to be repeated to the model.  The
            # exact typed value remains in the server-owned option mapping.
            sensitive = {milestone_id}
            if isinstance(value.get("insight_id"), str):
                sensitive.add(value["insight_id"])
            if any(token and token in display_name for token in sensitive):
                display_name = "Ability-score improvement" if kind == "ability_score_change" else "Cultivation Insight"
            if any(token and token in semantic_cue for token in sensitive):
                semantic_cue = "Choose this source-backed advancement resolution."
            summaries[option_id] = {
                "option_id": option_id,
                "display_name": display_name,
                "semantic_cue": semantic_cue,
                "kind": kind,
            }
        if not options or len(options) > 256:
            return None
        option_ids = sorted(options)
        response_schema = {
            "type": "object",
            "additionalProperties": False,
            "required": ["option_id"],
            "properties": {
                "option_id": {"type": "string", "enum": option_ids},
            },
        }
        return {
            "target_kind": "advancement_choice",
            "field": field,
            "milestone_id": milestone_id,
            "effective_cl": effective_cl,
            "allowed_kinds": allowed_kinds,
            "request_sha256": request_sha256,
            "prior_response_sha256": prior_response_sha256,
            "option_ids": option_ids,
            "options": options,
            "option_summaries": [summaries[option_id] for option_id in option_ids],
            "response_schema": response_schema,
            "preserve_all_other_values": True,
            "instruction": (
                "Choose exactly one opaque option_id for this source-backed Advancement Choice; "
                "the server merges only that milestone resolution into the retained response."
            ),
        }

    @staticmethod
    def _provider_ordinary_order_mirror_repair_target(
        diagnostic: Any,
        *,
        run: dict[str, Any] | None,
        prior_response: str | None,
    ) -> dict[str, Any] | None:
        """Prove the only safe server repair for a CL-order permutation.

        Ordinary Talent choices remain provider-authored facts.  This target
        is deliberately narrower than the general acquisition correction:
        it activates only when the frozen per-CL projection proves a unique
        one-to-one assignment, and the retained diagnostic names exactly the
        resulting wrong positions plus the missing mirror.
        """
        target_kind = _ORDINARY_ORDER_MIRROR_TARGET_KIND
        if (
            not isinstance(diagnostic, dict)
            or diagnostic.get("code") != "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID"
            or not isinstance(run, dict)
            or not isinstance(prior_response, str)
            or not prior_response.strip()
        ):
            return None
        details = diagnostic.get("details")
        issues = details.get("issues") if isinstance(details, dict) else None
        if not isinstance(details, dict) or not isinstance(issues, list) or not issues:
            return None

        # A target is bound to the currently persisted diagnostic, not to a
        # caller-recomputed copy of it.
        validation = run.get("validation")
        persisted_diagnostic = (
            validation.get("last_submission_error")
            if isinstance(validation, dict)
            else None
        )
        if (
            not isinstance(persisted_diagnostic, dict)
            or sha256_json(persisted_diagnostic) != sha256_json(diagnostic)
        ):
            return None
        request = run.get("request")
        if not isinstance(request, dict):
            return None
        request_sha256 = request.get("request_sha256")
        if not isinstance(request_sha256, str) or len(request_sha256) != 64:
            return None
        if (
            request.get("project_id") != run.get("project_id")
            or request.get("project_revision") != run.get("starting_revision")
        ):
            return None

        def strict_load(text: str) -> dict[str, Any] | None:
            def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
                result: dict[str, Any] = {}
                for key, value in items:
                    if key in result:
                        raise ValueError("duplicate object key")
                    result[key] = value
                return result

            try:
                value = json.loads(text, object_pairs_hook=pairs)
            except (TypeError, ValueError, json.JSONDecodeError):
                return None
            return value if isinstance(value, dict) else None

        prior_payload = strict_load(prior_response)
        if not isinstance(prior_payload, dict) or prior_payload.get("request_sha256") != request_sha256:
            return None
        acquisition = prior_payload.get("acquisition_intent")
        selection = prior_payload.get("selection_intent")
        by_slot = selection.get("by_slot") if isinstance(selection, dict) else None
        if not isinstance(acquisition, dict) or not isinstance(by_slot, dict):
            return None
        prior_ordinary = acquisition.get("ordinary_talent_ids")
        prior_skeleton = by_slot.get("advancement_skeleton")
        if (
            not isinstance(prior_ordinary, list)
            or not prior_ordinary
            or any(not isinstance(value, str) or not value.strip() for value in prior_ordinary)
            or len(set(prior_ordinary)) != len(prior_ordinary)
            or not isinstance(prior_skeleton, list)
            or any(not isinstance(value, str) or not value.strip() for value in prior_skeleton)
            or prior_skeleton not in ([], prior_ordinary)
        ):
            return None

        try:
            provider_payload = _provider_payload(run, cue_limit=0, display_limit=0)
        except (FoundryError, KeyError, TypeError, ValueError, json.JSONDecodeError):
            return None
        provider_contract = provider_payload.get("response_contract")
        if not isinstance(provider_contract, dict):
            return None
        expected = provider_contract.get("expected_acquisition_counts")
        diagnostic_expected = details.get("expected_acquisition_counts")
        if not isinstance(expected, dict) or not isinstance(diagnostic_expected, dict):
            return None
        if set(expected) != set(diagnostic_expected) or any(
            diagnostic_expected.get(key) != expected.get(key) for key in expected
        ):
            return None
        pair_count = expected.get("sphere_free_talent_pairs")
        ordinary_count = expected.get("ordinary_talent_ids")
        if (
            type(pair_count) is not int
            or pair_count < 0
            or type(ordinary_count) is not int
            or ordinary_count < 1
            or len(prior_ordinary) != ordinary_count
        ):
            return None

        def normalize_pairs(value: Any, *, exact_count: int | None) -> list[dict[str, str]] | None:
            if not isinstance(value, list) or (exact_count is not None and len(value) != exact_count):
                return None
            result: list[dict[str, str]] = []
            for row in value:
                if (
                    not isinstance(row, dict)
                    or set(row) != {"sphere_id", "talent_id"}
                    or not isinstance(row.get("sphere_id"), str)
                    or not row["sphere_id"].strip()
                    or not isinstance(row.get("talent_id"), str)
                    or not row["talent_id"].strip()
                ):
                    return None
                normalized = {
                    "sphere_id": row["sphere_id"],
                    "talent_id": row["talent_id"],
                }
                if normalized in result:
                    return None
                result.append(normalized)
            return result

        prior_pairs = normalize_pairs(
            acquisition.get("sphere_free_talent_pairs"),
            exact_count=pair_count,
        )
        presented_pairs = normalize_pairs(
            provider_contract.get("presented_legal_first_cycle_pairs"),
            exact_count=None,
        )
        if prior_pairs is None or presented_pairs is None:
            return None
        diagnostic_pairs = details.get("presented_legal_first_cycle_pairs")
        if diagnostic_pairs is not None:
            diagnostic_pairs = normalize_pairs(diagnostic_pairs, exact_count=None)
            if diagnostic_pairs is None or diagnostic_pairs != presented_pairs:
                return None
        if any(row not in presented_pairs for row in prior_pairs):
            return None
        free_talent_ids = {
            row["talent_id"] for row in prior_pairs if isinstance(row.get("talent_id"), str)
        }
        if set(prior_ordinary) & free_talent_ids:
            return None

        def normalize_map(value: Any) -> dict[str, list[str]] | None:
            if not isinstance(value, dict):
                return None
            expected_keys = {str(cl) for cl in range(1, ordinary_count + 1)}
            if set(value) != expected_keys:
                return None
            result: dict[str, list[str]] = {}
            for key in sorted(value, key=int):
                values = value.get(key)
                if (
                    not isinstance(values, list)
                    or not values
                    or any(not isinstance(item, str) or not item.strip() for item in values)
                    or len(set(values)) != len(values)
                    or values != sorted(values)
                ):
                    return None
                result[key] = list(values)
            return result

        diagnostic_map = normalize_map(details.get("presented_legal_ordinary_talent_ids_by_cl"))
        if diagnostic_map is None:
            return None
        route_modules = provider_payload.get("sphere_route_modules")
        route_modules = route_modules if isinstance(route_modules, list) else []

        def route_assignment(route: Any) -> dict[str, str] | None:
            if not isinstance(route, dict):
                return None
            raw = route.get("ordinary_talent_ids_by_cl")
            if not isinstance(raw, dict):
                return None
            expected_keys = {str(cl) for cl in range(1, ordinary_count + 1)}
            if set(raw) != expected_keys:
                return None
            result: dict[str, str] = {}
            for key in sorted(raw, key=int):
                value = raw.get(key)
                if not isinstance(value, str) or not value.strip():
                    return None
                result[key] = value
            if len(set(result.values())) != ordinary_count:
                return None
            return result

        active_map: dict[str, list[str]]
        selected_assignment: dict[str, str] | None = None
        if route_modules:
            # A uniquely implied server repair cannot choose among multiple
            # acquired routes.  One selected free pair must identify one and
            # only one complete route.
            if pair_count != 1 or len(prior_pairs) != 1:
                return None
            matches = [
                route
                for route in route_modules
                if isinstance(route, dict) and route.get("free_talent_pair") == prior_pairs[0]
            ]
            if len(matches) != 1:
                return None
            selected_assignment = route_assignment(matches[0])
            if selected_assignment is None:
                return None
            union: dict[str, set[str]] = {
                str(cl): set() for cl in range(1, ordinary_count + 1)
            }
            for route in route_modules:
                assignments = route_assignment(route)
                if assignments is None:
                    return None
                for key, value in assignments.items():
                    union[key].add(value)
            active_map = {
                key: sorted(values)
                for key, values in sorted(union.items(), key=lambda item: int(item[0]))
            }
        else:
            raw_contract_map = provider_contract.get("presented_legal_ordinary_talent_ids_by_cl")
            active_map = normalize_map(raw_contract_map)
            if active_map is None:
                return None
            # The retained IDs themselves must identify exactly one CL each;
            # a matching permutation is not inferred when any ID can occupy
            # two positions or a position is left unresolved.
            positions_by_id: dict[str, list[int]] = {}
            for key, values in active_map.items():
                for value in values:
                    positions_by_id.setdefault(value, []).append(int(key))
            selected_assignment = {}
            for value in prior_ordinary:
                positions = positions_by_id.get(value)
                if not isinstance(positions, list) or len(positions) != 1:
                    return None
                key = str(positions[0])
                if key in selected_assignment:
                    return None
                selected_assignment[key] = value
            if set(selected_assignment) != set(active_map):
                return None
        if active_map != diagnostic_map or selected_assignment is None:
            return None
        derived_ordinary = [
            selected_assignment[str(cl)] for cl in range(1, ordinary_count + 1)
        ]
        if (
            len(set(derived_ordinary)) != ordinary_count
            or set(derived_ordinary) != set(prior_ordinary)
            or set(derived_ordinary) & free_talent_ids
        ):
            return None

        mismatch_indexes = {
            index
            for index, (prior, derived) in enumerate(zip(prior_ordinary, derived_ordinary))
            if prior != derived
        }
        issue_reasons_by_index: dict[int, set[str]] = {}
        mirror_issues: list[dict[str, Any]] = []
        mirror_required_value: list[str] | None = None
        for issue in issues:
            if not isinstance(issue, dict):
                return None
            field = issue.get("field")
            if isinstance(field, str) and field.startswith(
                "acquisition_intent.ordinary_talent_ids."
            ):
                suffix = field.removeprefix("acquisition_intent.ordinary_talent_ids.")
                if not suffix.isdigit() or str(int(suffix)) != suffix:
                    return None
                index = int(suffix)
                if index < 0 or index >= ordinary_count:
                    return None
                reason = issue.get("reason")
                if (
                    reason not in {
                        "CROSS_ROUTE_MIXING",
                        "NOT_PRESENTED_LEGAL_ORDINARY_TALENT",
                    }
                    or issue.get("effective_cl") != index + 1
                    or issue.get("proposed") != prior_ordinary[index]
                    or prior_ordinary[index] == derived_ordinary[index]
                ):
                    return None
                if reason == "CROSS_ROUTE_MIXING":
                    allowed = issue.get("allowed_choice_ids")
                    if allowed != [derived_ordinary[index]]:
                        return None
                else:
                    allowed = issue.get("allowed_choice_ids")
                    if allowed != diagnostic_map.get(str(index + 1)) or derived_ordinary[index] not in allowed:
                        return None
                reasons = issue_reasons_by_index.setdefault(index, set())
                if reason in reasons:
                    return None
                reasons.add(reason)
                continue
            if field == "selection_intent.by_slot.advancement_skeleton":
                # Persisted diagnostics can come from either validator
                # projection: the measured sequential run reports the
                # submitted ordinary array, while the current projection may
                # report the uniquely derived order.  Neither value grants
                # the repair; the paired per-CL rows above must already prove
                # the exact derived permutation.
                if (
                    issue.get("reason") != "MUST_MIRROR_ORDINARY_TALENT_IDS"
                    or issue.get("proposed") != prior_skeleton
                    or issue.get("required_value") not in (prior_ordinary, derived_ordinary)
                ):
                    return None
                mirror_issues.append(issue)
                mirror_required_value = deepcopy(issue.get("required_value"))
                continue
            return None
        if (
            set(issue_reasons_by_index) != mismatch_indexes
            or any(
                reasons
                != (
                    {
                        "CROSS_ROUTE_MIXING",
                        "NOT_PRESENTED_LEGAL_ORDINARY_TALENT",
                    }
                    if route_modules
                    else {"NOT_PRESENTED_LEGAL_ORDINARY_TALENT"}
                )
                for reasons in issue_reasons_by_index.values()
            )
            or len(mirror_issues) != 1
            or prior_skeleton == derived_ordinary
        ):
            return None
        return {
            "target_kind": target_kind,
            "retry_only": True,
            "request_sha256": request_sha256,
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "diagnostic_sha256": sha256_json(diagnostic),
            "expected_counts": deepcopy(expected),
            "presented_legal_ordinary_talent_ids_by_cl": deepcopy(diagnostic_map),
            "selected_route_assignment_by_cl": deepcopy(selected_assignment),
            "prior_ordinary_talent_ids": deepcopy(prior_ordinary),
            "prior_advancement_skeleton": deepcopy(prior_skeleton),
            "derived_ordinary_talent_ids": deepcopy(derived_ordinary),
            "diagnostic_mirror_required_value": deepcopy(mirror_required_value),
            "ordinary_issue_indices": sorted(mismatch_indexes),
            "fields": [
                "acquisition_intent.ordinary_talent_ids",
                "selection_intent.by_slot.advancement_skeleton",
            ],
            "preserve_all_other_values": True,
            "provider_called": False,
            "instruction": (
                "Replace only ordinary_talent_ids with the unique effective-CL order and copy that "
                "same array to selection_intent.by_slot.advancement_skeleton."
            ),
        }

    @staticmethod
    def _provider_target_scoped_repair_target(
        diagnostic: Any,
        *,
        run: dict[str, Any] | None = None,
        prior_response: str | None = None,
    ) -> dict[str, Any] | None:
        """Return the one provider-choice repair target, when diagnostics prove it."""
        if not isinstance(diagnostic, dict):
            return None
        if diagnostic.get("code") == "CG1_PREFERRED_RESPONSE_ACQUISITION_INVALID":
            ordered_target = CharacterCreationExecutionService._provider_ordinary_order_mirror_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
            if ordered_target is not None:
                return ordered_target
            return CharacterCreationExecutionService._provider_acquisition_contract_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        if diagnostic.get("code") == "CG1_PREFERRED_RESPONSE_BOUNDED_FIELD_INVALID":
            return CharacterCreationExecutionService._provider_bounded_field_cleanup_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        if diagnostic.get("code") == "CG1_DELEGATED_FREE_TALENT_SPHERE_MISMATCH":
            return CharacterCreationExecutionService._provider_free_talent_sphere_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        if diagnostic.get("code") == "CG1_DELEGATED_FREE_TALENT_NOT_LEGAL":
            return CharacterCreationExecutionService._provider_free_talent_not_legal_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        if diagnostic.get("code") == "CG1_DELEGATED_CHOICE_UNAVAILABLE":
            return CharacterCreationExecutionService._provider_insight_unavailable_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        if diagnostic.get("code") == "CG1_METHOD_PATH_INCOMPATIBLE":
            request = run.get("request") if isinstance(run, dict) else None
            envelope = request.get("delegated_choice_envelope") if isinstance(request, dict) else None
            if not isinstance(envelope, dict):
                return None
            allowed_by_slot = envelope.get("allowed_choice_ids_by_slot")
            allowed_by_slot = allowed_by_slot if isinstance(allowed_by_slot, dict) else {}

            def clean_ids(value: Any) -> list[str]:
                result: list[str] = []
                if not isinstance(value, list):
                    return result
                for item in value:
                    if isinstance(item, str) and item.strip() and item not in result:
                        result.append(item)
                return result

            allowed_method_ids = clean_ids(allowed_by_slot.get("method_choice"))
            allowed_path_ids = clean_ids(allowed_by_slot.get("path_choice"))
            path_method_authority = envelope.get("path_method_authority")
            path_method_authority = path_method_authority if isinstance(path_method_authority, dict) else {}
            raw_grants = path_method_authority.get("method_granted_path_ids")
            if not isinstance(raw_grants, dict) or not allowed_method_ids or not allowed_path_ids:
                return None
            method_granted_path_ids: dict[str, list[str]] = {}
            for method_id in allowed_method_ids:
                method_granted_path_ids[method_id] = clean_ids(raw_grants.get(method_id))

            progression_by_cl: dict[str, list[str]] = {}
            for row in envelope.get("path_progression_choices") or []:
                if not isinstance(row, dict) or type(row.get("cl")) is not int:
                    continue
                path_ids = [
                    path_id
                    for path_id in clean_ids(row.get("path_ids"))
                    if path_id in allowed_path_ids
                ]
                if not path_ids:
                    continue
                key = str(row["cl"])
                existing = progression_by_cl.setdefault(key, [])
                for path_id in path_ids:
                    if path_id not in existing:
                        existing.append(path_id)
            progression_by_cl = {
                key: sorted(value)
                for key, value in sorted(progression_by_cl.items(), key=lambda item: int(item[0]))
            }
            progression_keys: list[str] | None = None
            if isinstance(prior_response, str):
                try:
                    prior_payload = json.loads(prior_response)
                except (TypeError, ValueError):
                    prior_payload = None
                if isinstance(prior_payload, dict):
                    bounded_choices = prior_payload.get("bounded_choices")
                    existing_progression = (
                        bounded_choices.get("path_progression_by_cl")
                        if isinstance(bounded_choices, dict)
                        else None
                    )
                    if isinstance(existing_progression, dict):
                        progression_keys = sorted(
                            key for key in existing_progression if isinstance(key, str)
                        )
            if progression_keys is None:
                progression_keys = []
            if any(key not in progression_by_cl for key in progression_keys):
                return None

            selection_limits = envelope.get("selection_limits_by_slot")
            selection_limits = selection_limits if isinstance(selection_limits, dict) else {}

            def slot_limits(slot_id: str, default_min: int, default_max: int) -> tuple[int, int] | None:
                raw_limits = selection_limits.get(slot_id)
                raw_limits = raw_limits if isinstance(raw_limits, dict) else {}
                minimum = raw_limits.get("final_min", default_min)
                maximum = raw_limits.get("final_max", default_max)
                if type(minimum) is not int or type(maximum) is not int:
                    return None
                if minimum < 0 or maximum < minimum:
                    return None
                return minimum, maximum

            method_limits = slot_limits("method_choice", 1, 1)
            path_limits = slot_limits("path_choice", 1, min(3, len(allowed_path_ids)))
            # The target contract repairs an incompatible selected Method/Path
            # combination with exactly one Method plus one or more Paths.  A
            # frozen optional Method slot (0..1) still permits that repair
            # shape; never broaden it to multi-Method or unbounded authority.
            if (
                method_limits is None
                or method_limits[1] != 1
                or method_limits[0] not in {0, 1}
                or path_limits is None
                or path_limits[0] < 1
                or path_limits[1] > 3
            ):
                return None
            path_min, path_max = path_limits
            max_option_count = 256
            options_by_id: dict[str, dict[str, Any]] = {}
            for method_id in sorted(allowed_method_ids):
                granted = set(method_granted_path_ids.get(method_id) or [])
                method_paths = [path_id for path_id in sorted(allowed_path_ids) if path_id in granted]
                if len(method_paths) < path_min:
                    continue
                for count in range(path_min, min(path_max, len(method_paths)) + 1):
                    # A multi-Path correction is not self-validating without an
                    # exact retained progression key.  Do not spend the one
                    # provider correction on an option that is guaranteed to
                    # trigger a second bounded-decision blocker.  Single-Path
                    # options remain complete and provider-chosen.
                    if count > 1 and not progression_keys:
                        continue
                    for path_tuple in itertools.combinations(method_paths, count):
                        selected_paths = list(path_tuple)
                        progression_values: list[list[str]] = []
                        for key in progression_keys:
                            values = [
                                path_id
                                for path_id in progression_by_cl.get(key, [])
                                if path_id in selected_paths
                            ]
                            if not values:
                                progression_values = []
                                break
                            progression_values.append(values)
                        if progression_keys and not progression_values:
                            continue
                        progression_products = itertools.product(*progression_values) if progression_keys else [()]
                        for progression_product in progression_products:
                            progression = {
                                key: value
                                for key, value in zip(progression_keys, progression_product)
                            }
                            mapping = {
                                "method_choice": [method_id],
                                "path_choice": selected_paths,
                                "path_progression_by_cl": progression,
                            }
                            option_id = "mp_" + sha256_json(mapping)[:20]
                            if option_id in options_by_id and options_by_id[option_id] != mapping:
                                return None
                            options_by_id[option_id] = mapping
                            if len(options_by_id) > max_option_count:
                                return None
            if not options_by_id:
                return None
            option_ids = sorted(options_by_id)
            response_schema = {
                "type": "object",
                "additionalProperties": False,
                "required": ["option_id"],
                "properties": {
                    "option_id": {
                        "type": "string",
                        "enum": option_ids,
                    },
                },
            }
            return {
                "target_kind": "method_path",
                "fields": [
                    "selection_intent.by_slot.method_choice",
                    "selection_intent.by_slot.path_choice",
                    "bounded_choices.path_progression_by_cl",
                ],
                "allowed_method_ids": sorted(allowed_method_ids),
                "allowed_path_ids": sorted(allowed_path_ids),
                "method_granted_path_ids": {
                    method_id: sorted(method_granted_path_ids[method_id])
                    for method_id in sorted(method_granted_path_ids)
                },
                "path_progression_choices": [
                    {"cl": int(key), "path_ids": value}
                    for key, value in progression_by_cl.items()
                ],
                "path_progression_by_cl": progression_by_cl,
                "existing_progression_keys": progression_keys,
                "selection_limits": {
                    "method_choice": {
                        "final_min": method_limits[0],
                        "final_max": method_limits[1],
                    },
                    "path_choice": {"final_min": path_min, "final_max": path_max},
                },
                "repair_selection_count": {"method_choice": 1},
                "option_ids": option_ids,
                "options": options_by_id,
                "response_schema": response_schema,
                "preserve_all_other_values": True,
                "instruction": (
                    "Choose the opaque option_id whose server-owned Method, Paths, and Path "
                    "progression form a coherent combination for the character context; do not "
                    "mechanically preserve the incompatible combination or compose mechanics "
                    "outside the presented options."
                ),
            }
        if diagnostic.get("code") == "CG1_DELEGATED_DUPLICATE_CHOICE":
            return CharacterCreationExecutionService._provider_ordinary_duplicate_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        if diagnostic.get("code") != "CG1_BOUNDED_DECISION_REQUIRED":
            return None
        diagnostic_details = diagnostic.get("details")
        if (
            isinstance(diagnostic_details, dict)
            and isinstance(diagnostic_details.get("milestone_id"), str)
            and diagnostic_details.get("field") == (
                "bounded_choices.ability_score_changes_by_milestone_id."
                + diagnostic_details["milestone_id"]
            )
        ):
            return CharacterCreationExecutionService._provider_advancement_choice_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        if not isinstance(diagnostic_details, dict) or type(diagnostic_details.get("cl")) is not int:
            return None
        if "requested_path" in diagnostic_details:
            return CharacterCreationExecutionService._provider_bounded_path_progression_empty_cleanup_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        available_path_ids = diagnostic_details.get("available_path_ids")
        if not isinstance(available_path_ids, list):
            return None
        allowed_path_ids: list[str] = []
        for path_id in available_path_ids:
            if (
                isinstance(path_id, str)
                and path_id.strip()
                and path_id not in allowed_path_ids
            ):
                allowed_path_ids.append(path_id)
        if not allowed_path_ids:
            return None
        reported_cl = diagnostic_details["cl"]
        cl_key = str(reported_cl)

        # A diagnostic is sufficient to describe a provider-facing target, but
        # a provider-free repair must be proven by the exact delegated choice
        # envelope.  When that frozen authority is present, use only its own
        # per-CL Path sets and deliberately decline the deterministic route if
        # the reported CL cannot be bound to one exact singleton.  A missing
        # envelope remains a generic owner/provider decision; the diagnostic
        # alone never authorizes a provider-free repair.
        batch_filled_path_progression_by_cl: dict[str, str] | None = None
        batch_available_path_ids_by_cl: dict[str, list[str]] | None = None
        request = run.get("request") if isinstance(run, dict) else None
        envelope = request.get("delegated_choice_envelope") if isinstance(request, dict) else None
        if len(allowed_path_ids) == 1 and isinstance(envelope, dict):
            frozen_target = envelope.get("frozen_owner_target_cl")
            frozen_target_cl = (
                frozen_target.get("value")
                if isinstance(frozen_target, dict)
                else frozen_target
            )
            raw_rows = envelope.get("path_progression_choices")
            if type(frozen_target_cl) is int and frozen_target_cl >= reported_cl and isinstance(raw_rows, list):
                allowed_path_authority = (
                    (envelope.get("allowed_choice_ids_by_slot") or {}).get("path_choice")
                    if isinstance(envelope.get("allowed_choice_ids_by_slot"), dict)
                    else None
                )
                allowed_path_authority_set: set[str] | None = None
                allowed_path_authority_invalid = False
                if isinstance(allowed_path_authority, list):
                    cleaned_allowed_path_authority: list[str] = []
                    for path_id in allowed_path_authority:
                        if not isinstance(path_id, str) or not path_id.strip() or path_id in cleaned_allowed_path_authority:
                            allowed_path_authority_invalid = True
                            break
                        cleaned_allowed_path_authority.append(path_id)
                    else:
                        allowed_path_authority_set = set(cleaned_allowed_path_authority)
                elif allowed_path_authority is not None:
                    allowed_path_authority_invalid = True

                frozen_paths_by_cl: dict[str, set[str]] = {}
                invalid_frozen_cl: set[str] = set()
                for row in raw_rows:
                    if not isinstance(row, dict) or type(row.get("cl")) is not int:
                        continue
                    row_cl = row["cl"]
                    if row_cl < 1 or row_cl > frozen_target_cl:
                        continue
                    row_key = str(row_cl)
                    raw_path_ids = row.get("path_ids")
                    if not isinstance(raw_path_ids, list):
                        invalid_frozen_cl.add(row_key)
                        continue
                    cleaned_row_ids: list[str] = []
                    row_invalid = False
                    for path_id in raw_path_ids:
                        if not isinstance(path_id, str) or not path_id.strip():
                            row_invalid = True
                            break
                        if allowed_path_authority_set is not None and path_id not in allowed_path_authority_set:
                            row_invalid = True
                            break
                        if path_id not in cleaned_row_ids:
                            cleaned_row_ids.append(path_id)
                    if row_invalid:
                        invalid_frozen_cl.add(row_key)
                        continue
                    frozen_paths_by_cl.setdefault(row_key, set()).update(cleaned_row_ids)

                reported_frozen_ids = frozen_paths_by_cl.get(cl_key)
                if (
                    not allowed_path_authority_invalid
                    and
                    cl_key not in invalid_frozen_cl
                    and reported_frozen_ids == set(allowed_path_ids)
                    and len(reported_frozen_ids) == 1
                ):
                    try:
                        prior_payload = json.loads(prior_response) if isinstance(prior_response, str) else None
                    except (TypeError, ValueError):
                        prior_payload = None
                    prior_bounded = prior_payload.get("bounded_choices") if isinstance(prior_payload, dict) else None
                    prior_progression = (
                        prior_bounded.get("path_progression_by_cl")
                        if isinstance(prior_bounded, dict)
                        else None
                    )
                    prior_progression = prior_progression if isinstance(prior_progression, dict) else {}
                    candidate_map: dict[str, str] = {}
                    candidate_available: dict[str, list[str]] = {}
                    for candidate_key, candidate_ids in sorted(
                        frozen_paths_by_cl.items(), key=lambda item: int(item[0])
                    ):
                        if candidate_key in invalid_frozen_cl or candidate_key in prior_progression:
                            continue
                        if len(candidate_ids) != 1:
                            continue
                        candidate_map[candidate_key] = next(iter(candidate_ids))
                        candidate_available[candidate_key] = [candidate_map[candidate_key]]
                    # The reported missing decision must be one of the values
                    # selected by this same frozen proof; otherwise no
                    # provider-free repair is authorized.
                    if cl_key in candidate_map:
                        batch_filled_path_progression_by_cl = candidate_map
                        batch_available_path_ids_by_cl = candidate_available

        if batch_filled_path_progression_by_cl is not None:
            target_progression_keys = sorted(batch_filled_path_progression_by_cl, key=int)
            target_progression_schema = {
                "type": "object",
                "additionalProperties": False,
                "required": target_progression_keys,
                "properties": {
                    key: {
                        "type": "string",
                        "enum": deepcopy(batch_available_path_ids_by_cl[key]),
                    }
                    for key in target_progression_keys
                },
            }
        else:
            target_progression_schema = {
                "type": "object",
                "additionalProperties": False,
                "required": [cl_key],
                "properties": {
                    cl_key: {"type": "string", "enum": allowed_path_ids},
                },
            }
        target = {
            "field": "bounded_choices.path_progression_by_cl",
            "key": cl_key,
            "exact_selection_count": 1,
            "available_path_ids": allowed_path_ids,
            "response_schema": {
                "type": "object",
                "additionalProperties": False,
                "required": ["bounded_choices"],
                "properties": {
                    "bounded_choices": {
                        "type": "object",
                        "additionalProperties": False,
                        "required": ["path_progression_by_cl"],
                        "properties": {
                            "path_progression_by_cl": target_progression_schema,
                        },
                    },
                },
            },
            "preserve_all_other_values": True,
            "instruction": (
                f'Set bounded_choices.path_progression_by_cl["{cl_key}"] '
                "to exactly one Path ID from available_path_ids; do not leave "
                "this entry empty, select multiple IDs, or invent an ID. "
                "Preserve every other frozen/request-bound value and return "
                "one small JSON object containing this target."
            ),
        }
        # A singleton frozen choice is a complete server-owned decision.  It
        # may be applied provider-free; ambiguous choices intentionally remain
        # an explicit owner/provider decision and retain the generic target.
        if batch_filled_path_progression_by_cl is not None:
            target["target_kind"] = "bounded_path_progression_singleton"
            target["reported_cl"] = reported_cl
            target["batch_filled_path_progression_by_cl"] = deepcopy(
                batch_filled_path_progression_by_cl
            )
            target["batch_available_path_ids_by_cl"] = deepcopy(
                batch_available_path_ids_by_cl
            )
            if len(batch_filled_path_progression_by_cl) > 1:
                target["instruction"] = (
                    "Set every currently missing Path progression entry listed in "
                    "batch_filled_path_progression_by_cl to its exact frozen singleton; "
                    "preserve all existing progression entries and every other value."
                )
        return target

    @staticmethod
    def _provider_insight_unavailable_repair_target(
        diagnostic: dict[str, Any],
        *,
        run: dict[str, Any] | None,
        prior_response: str | None,
    ) -> dict[str, Any] | None:
        """Derive opaque frozen options for one unavailable Insight priority.

        This target is deliberately limited to the validator's exact
        minimum-CL/Insight-priority diagnostic.  The whole priority array is
        replaced with a same-cardinality server-owned option; no other
        response field is inferred or changed.
        """
        if not isinstance(run, dict) or not isinstance(prior_response, str):
            return None
        details = diagnostic.get("details") if isinstance(diagnostic, dict) else None
        if not isinstance(details, dict) or set(details) != {
            "choice_id",
            "minimum_cl",
            "slot_id",
            "target_cl",
        }:
            return None
        choice_id = details.get("choice_id")
        minimum_cl = details.get("minimum_cl")
        slot_id = details.get("slot_id")
        diagnostic_target_cl = details.get("target_cl")
        if (
            not isinstance(choice_id, str)
            or not choice_id.strip()
            or type(minimum_cl) is not int
            or minimum_cl < 1
            or slot_id != "insight_priorities"
            or type(diagnostic_target_cl) is not int
            or diagnostic_target_cl < 1
            or minimum_cl <= diagnostic_target_cl
        ):
            return None

        request = run.get("request")
        envelope = request.get("delegated_choice_envelope") if isinstance(request, dict) else None
        if not isinstance(envelope, dict):
            return None
        frozen_target_cl = (envelope.get("frozen_owner_target_cl") or {}).get("value")
        if type(frozen_target_cl) is not int or frozen_target_cl != diagnostic_target_cl:
            return None

        def strict_ids(value: Any) -> list[str] | None:
            if not isinstance(value, list):
                return None
            result: list[str] = []
            for item in value:
                if not isinstance(item, str) or not item.strip() or item in result:
                    return None
                result.append(item)
            return result

        selection_limits = envelope.get("selection_limits_by_slot")
        raw_limits = selection_limits.get(slot_id) if isinstance(selection_limits, dict) else None
        if not isinstance(raw_limits, dict):
            return None
        final_min = raw_limits.get("final_min")
        final_max = raw_limits.get("final_max")
        if type(final_min) is not int or type(final_max) is not int or final_min < 0 or final_max < final_min:
            return None

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError):
            return None
        if not isinstance(prior_payload, dict):
            return None
        selection = prior_payload.get("selection_intent")
        by_slot = selection.get("by_slot") if isinstance(selection, dict) else None
        if not isinstance(by_slot, dict):
            return None
        selected_ids = strict_ids(by_slot.get(slot_id))
        if (
            selected_ids is None
            or not selected_ids
            or len(selected_ids) < final_min
            or len(selected_ids) > final_max
            or choice_id not in selected_ids
        ):
            return None
        required_count = len(selected_ids)

        allowed_by_slot = envelope.get("allowed_choice_ids_by_slot")
        offered_by_slot = envelope.get("offered_choice_ids_by_slot")
        nonselectable_by_slot = envelope.get("nonselectable_choice_ids_by_slot")
        unavailable_by_slot = envelope.get("unavailable_or_rejected_choice_ids_by_slot")
        prerequisites_by_slot = envelope.get("prerequisites_and_availability")
        choices_by_slot = envelope.get("choices_by_slot")
        typed_by_slot = envelope.get("typed_choice_authority_by_slot")
        if not all(isinstance(value, dict) for value in (
            allowed_by_slot,
            offered_by_slot,
            nonselectable_by_slot,
            unavailable_by_slot,
            prerequisites_by_slot,
            choices_by_slot,
            typed_by_slot,
        )):
            return None
        allowed_ids = strict_ids(allowed_by_slot.get(slot_id))
        offered_ids = strict_ids(offered_by_slot.get(slot_id))
        nonselectable_ids = strict_ids(nonselectable_by_slot.get(slot_id))
        unavailable_ids = strict_ids(unavailable_by_slot.get(slot_id))
        if None in (allowed_ids, offered_ids, nonselectable_ids, unavailable_ids):
            return None
        allowed_set = set(allowed_ids or [])
        offered_set = set(offered_ids or [])
        excluded_ids = set(nonselectable_ids or []) | set(unavailable_ids or [])
        if any(value not in allowed_set or value not in offered_set for value in selected_ids):
            return None

        source_rows = choices_by_slot.get(slot_id)
        availability_rows = prerequisites_by_slot.get(slot_id)
        authority_slot = typed_by_slot.get(slot_id)
        stage2_authority = (
            authority_slot.get("stage2_authority_by_choice")
            if isinstance(authority_slot, dict)
            else None
        )
        if not isinstance(source_rows, dict) or not isinstance(availability_rows, dict) or not isinstance(stage2_authority, dict):
            return None
        diagnostic_source = source_rows.get(choice_id)
        diagnostic_availability = availability_rows.get(choice_id)
        diagnostic_authority = stage2_authority.get(choice_id)
        if not all(isinstance(value, dict) for value in (
            diagnostic_source,
            diagnostic_availability,
            diagnostic_authority,
        )):
            return None
        diagnostic_availability_data = diagnostic_availability.get("availability")
        if not isinstance(diagnostic_availability_data, dict):
            return None
        authority_minimum = diagnostic_authority.get("minimum_cl")
        if type(authority_minimum) is not int:
            authority_minimum = diagnostic_availability_data.get("minimum_cl")
        if authority_minimum != minimum_cl:
            return None
        source_minimum = diagnostic_availability_data.get("minimum_cl")
        if type(source_minimum) is int and source_minimum != minimum_cl:
            return None
        if (
            diagnostic_source.get("choice_id", choice_id) != choice_id
            or diagnostic_source.get("id", choice_id) != choice_id
            or diagnostic_source.get("content_type") != "cultivation_insight"
            or diagnostic_source.get("publication_state") != "published"
            or diagnostic_authority.get("authority_complete") is not True
            or "cultivation_insight_acquisition" not in (diagnostic_authority.get("allowed_kinds") or [])
            or not isinstance(diagnostic_authority.get("allowed_channels"), list)
            or not diagnostic_authority.get("allowed_channels")
        ):
            return None

        retained_ids: set[str] = set()
        selected_id_set = set(selected_ids)
        for other_slot, values in by_slot.items():
            if other_slot == slot_id or not isinstance(values, list):
                continue
            for value in values:
                if isinstance(value, str) and value not in selected_id_set:
                    retained_ids.add(value)
        acquisition = prior_payload.get("acquisition_intent")
        if isinstance(acquisition, dict):
            for pair in acquisition.get("sphere_free_talent_pairs") or []:
                if isinstance(pair, dict):
                    for key in ("sphere_id", "talent_id"):
                        value = pair.get(key)
                        if isinstance(value, str) and value not in selected_id_set:
                            retained_ids.add(value)
            for key, values in acquisition.items():
                if key == "insight_occurrences" or not isinstance(values, list):
                    continue
                for value in values:
                    if isinstance(value, str) and value not in selected_id_set:
                        retained_ids.add(value)
        bounded_choices = prior_payload.get("bounded_choices")
        if isinstance(bounded_choices, dict):
            progression = bounded_choices.get("path_progression_by_cl")
            if isinstance(progression, dict):
                for value in progression.values():
                    if isinstance(value, str) and value not in selected_id_set:
                        retained_ids.add(value)

        def relation_targets(relation: Any) -> list[str] | None:
            if isinstance(relation, str) and relation.strip():
                return [relation]
            if not isinstance(relation, dict):
                return None
            values = relation.get("target_ids") or relation.get("targets")
            if isinstance(values, str):
                return [values] if values.strip() else None
            if isinstance(values, list):
                if not values or any(not isinstance(value, str) or not value.strip() for value in values):
                    return None
                return list(dict.fromkeys(values))
            value = relation.get("target_id") or relation.get("record_id") or relation.get("canonical_id") or relation.get("id")
            return [value] if isinstance(value, str) and value.strip() else None

        def relations_are_legal(
            row: dict[str, Any],
            present_ids: set[str],
            *,
            allow_unsatisfied_prerequisites: bool = False,
        ) -> bool:
            for key in ("prerequisites", "incompatibilities"):
                relations = row.get(key)
                if not isinstance(relations, list):
                    return False
                for relation in relations:
                    targets = relation_targets(relation)
                    if not targets:
                        return False
                    operator = relation.get("operator", "requires") if isinstance(relation, dict) else "requires"
                    if operator not in {"requires", "one_of", "all_of", "not"}:
                        return False
                    if key == "prerequisites":
                        if allow_unsatisfied_prerequisites:
                            continue
                        satisfied = (
                            all(target in present_ids for target in targets)
                            if operator in {"requires", "all_of"}
                            else any(target in present_ids for target in targets)
                            if operator == "one_of"
                            else not any(target in present_ids for target in targets)
                        )
                        if not satisfied:
                            return False
                    elif any(target in present_ids for target in targets):
                        return False
            return True

        candidates: list[dict[str, Any]] = []
        relations_by_candidate: dict[str, dict[str, list[Any]]] = {}
        for candidate_id in sorted(allowed_set & offered_set):
            if candidate_id in excluded_ids:
                continue
            source_row = source_rows.get(candidate_id)
            availability = availability_rows.get(candidate_id)
            authority = stage2_authority.get(candidate_id)
            if not isinstance(source_row, dict) or not isinstance(availability, dict) or not isinstance(authority, dict):
                continue
            if (
                source_row.get("choice_id", candidate_id) != candidate_id
                or source_row.get("id", candidate_id) != candidate_id
                or source_row.get("content_type") != "cultivation_insight"
                or source_row.get("publication_state") != "published"
            ):
                continue
            availability_data = availability.get("availability")
            if not isinstance(availability_data, dict):
                continue
            if availability_data.get("suppression") or availability_data.get("realm_rules") or availability_data.get("source_cl"):
                continue
            minimum = authority.get("minimum_cl")
            if type(minimum) is not int:
                minimum = availability_data.get("minimum_cl")
            if type(minimum) is not int or minimum > diagnostic_target_cl:
                continue
            allowed_cls = authority.get("allowed_cls") or authority.get("allowed_effective_cls")
            if not isinstance(allowed_cls, list) or any(type(value) is not int for value in allowed_cls) or diagnostic_target_cl not in allowed_cls:
                continue
            if (
                authority.get("authority_complete") is not True
                or "cultivation_insight_acquisition" not in (authority.get("allowed_kinds") or [])
                or not isinstance(authority.get("allowed_channels"), list)
                or not authority.get("allowed_channels")
            ):
                continue
            candidate_relation = {
                "prerequisites": availability.get("prerequisites"),
                "incompatibilities": availability.get("incompatibilities"),
            }
            source_prerequisites = source_row.get("prerequisites")
            source_incompatibilities = source_row.get("incompatibilities")
            if (
                isinstance(source_prerequisites, list)
                and source_prerequisites != candidate_relation["prerequisites"]
            ) or (
                isinstance(source_incompatibilities, list)
                and source_incompatibilities != candidate_relation["incompatibilities"]
            ):
                continue
            if not relations_are_legal(
                candidate_relation,
                retained_ids,
                allow_unsatisfied_prerequisites=True,
            ):
                continue
            relations_by_candidate[candidate_id] = deepcopy(candidate_relation)
            ability_change = authority.get("ability_change") or authority.get("insight_ability_change") or {}
            allowed_abilities = (
                sorted({value for value in ability_change.get("allowed_abilities") or [] if isinstance(value, str)})
                if isinstance(ability_change, dict)
                else []
            )
            candidates.append({
                "id": candidate_id,
                "name": _provider_short_text(source_row.get("name") or source_row.get("display_name"), 96, candidate_id),
                "cue": _provider_short_text(source_row.get("description") or source_row.get("semantic_cue"), 180, f"Insight choice {candidate_id}."),
                "minimum_cl": minimum,
                **({"allowed_abilities": allowed_abilities} if allowed_abilities else {}),
                **({
                    "requires": sorted({
                        target
                        for relation in availability.get("prerequisites") or []
                        for target in (relation_targets(relation) or [])
                    }),
                } if availability.get("prerequisites") else {}),
            })
        if not candidates:
            return None

        candidate_ids = [row["id"] for row in candidates]
        max_option_count = 256
        options_by_id: dict[str, dict[str, Any]] = {}
        for selected_tuple in itertools.islice(
            itertools.combinations(candidate_ids, required_count),
            max_option_count,
        ):
            selected = list(selected_tuple)
            if len(selected) != required_count or len(set(selected)) != required_count:
                return None
            joint_present = retained_ids | set(selected)
            if any(
                not relations_are_legal(relations_by_candidate[candidate_id], joint_present - {candidate_id})
                for candidate_id in selected
            ):
                continue
            mapping = {"insight_priorities": selected}
            option_id = "in_" + sha256_json(mapping)[:20]
            if option_id in options_by_id and options_by_id[option_id] != mapping:
                return None
            options_by_id[option_id] = mapping
        if not options_by_id:
            return None
        selectable_candidate_ids = {
            candidate_id
            for mapping in options_by_id.values()
            for candidate_id in mapping["insight_priorities"]
        }
        candidates = [candidate for candidate in candidates if candidate["id"] in selectable_candidate_ids]
        candidate_ids = [candidate["id"] for candidate in candidates]
        option_ids = sorted(options_by_id)
        response_schema = {
            "type": "object",
            "additionalProperties": False,
            "required": ["option_id"],
            "properties": {"option_id": {"type": "string", "enum": option_ids}},
        }
        return {
            "target_kind": "insight_unavailable",
            "fields": ["selection_intent.by_slot.insight_priorities"],
            "required_count": required_count,
            "unavailable_choice_id": choice_id,
            "target_cl": diagnostic_target_cl,
            "selection_limits": {"final_min": final_min, "final_max": final_max},
            "candidate_ids": candidate_ids,
            "candidate_summaries": candidates,
            "option_ids": option_ids,
            "options": options_by_id,
            "response_schema": response_schema,
            "preserve_all_other_values": True,
            "instruction": (
                "Choose one opaque option_id whose server-owned Insight priority array "
                "is legal at the frozen target CL and has exactly the required count."
            ),
        }

    @staticmethod
    def _provider_ordinary_duplicate_repair_target(
        diagnostic: dict[str, Any],
        *,
        run: dict[str, Any] | None,
        prior_response: str | None,
    ) -> dict[str, Any] | None:
        """Derive opaque, frozen-authority options for ordinary Talent duplicates.

        This target is intentionally narrower than ordinary-talent validation:
        it activates only when the validator identifies the exact free-versus-
        ordinary duplicate shape and all authority needed to establish a legal
        replacement is present in the frozen request envelope.  The provider
        may select an opaque option, while a deterministic server policy may
        select one itself; neither path composes or supplies Talent IDs.
        """
        if not isinstance(run, dict) or not isinstance(prior_response, str):
            return None
        details = diagnostic.get("details") if isinstance(diagnostic, dict) else None
        if not isinstance(details, dict):
            return None
        def clean_ids(value: Any) -> list[str] | None:
            if not isinstance(value, list):
                return None
            result: list[str] = []
            for item in value:
                if not isinstance(item, str) or not item.strip() or item in result:
                    return None
                result.append(item)
            return result

        def string_ids(value: Any) -> list[str] | None:
            if not isinstance(value, list) or not value:
                return None
            result: list[str] = []
            for item in value:
                if not isinstance(item, str) or not item.strip():
                    return None
                result.append(item)
            return result

        reported_free_ids: list[str] | None = None
        repeated_ordinary_shape = False
        if set(details) == {"free_talent_ids", "ordinary_talent_ids"}:
            reported_free_ids = clean_ids(details.get("free_talent_ids"))
            reported_ordinary_ids = string_ids(details.get("ordinary_talent_ids"))
            if not reported_free_ids or not reported_ordinary_ids:
                return None
            if not set(reported_free_ids) & set(reported_ordinary_ids):
                return None
        elif set(details) == {"choice_ids", "slot_id"} and details.get("slot_id") == "advancement_skeleton":
            repeated_ordinary_shape = True
            reported_ordinary_ids = string_ids(details.get("choice_ids"))
            if not reported_ordinary_ids or len(set(reported_ordinary_ids)) == len(reported_ordinary_ids):
                return None
        else:
            return None
        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError):
            return None
        if not isinstance(prior_payload, dict):
            return None
        acquisition = prior_payload.get("acquisition_intent")
        if not isinstance(acquisition, dict):
            return None
        current_ordinary_ids = string_ids(acquisition.get("ordinary_talent_ids"))
        if not current_ordinary_ids or current_ordinary_ids != reported_ordinary_ids:
            return None
        selection = prior_payload.get("selection_intent")
        by_slot = selection.get("by_slot") if isinstance(selection, dict) else None
        advancement_mirror = by_slot.get("advancement_skeleton") if isinstance(by_slot, dict) else None
        if advancement_mirror is not None and advancement_mirror != current_ordinary_ids:
            return None
        has_advancement_mirror = isinstance(advancement_mirror, list)
        pair_rows = acquisition.get("sphere_free_talent_pairs")
        if not isinstance(pair_rows, list):
            return None
        current_free_ids: list[str] = []
        acquired_spheres: set[str] = set()
        for pair in pair_rows:
            if not isinstance(pair, dict):
                return None
            sphere_id = pair.get("sphere_id")
            talent_id = pair.get("talent_id")
            if not isinstance(sphere_id, str) or not sphere_id.strip() or not isinstance(talent_id, str) or not talent_id.strip():
                return None
            acquired_spheres.add(sphere_id)
            if talent_id not in current_free_ids:
                current_free_ids.append(talent_id)
        if not current_free_ids:
            return None
        if reported_free_ids is not None and set(current_free_ids) != set(reported_free_ids):
            return None

        request = run.get("request")
        if not isinstance(request, dict):
            return None
        envelope = request.get("delegated_choice_envelope")
        if not isinstance(envelope, dict):
            return None
        target_authority = envelope.get("frozen_owner_target_cl")
        target_cl = target_authority.get("value") if isinstance(target_authority, dict) else None
        if type(target_cl) is not int or target_cl < 1:
            return None
        required_count = envelope.get("ordinary_talent_count")
        if type(required_count) is not int or required_count < 1:
            return None
        # A compact model may repeat a small set of legal same-sphere anchors
        # across more positions than the frozen plan actually has.  Preserve
        # the first occurrence of each anchor, then let the proof-bound option
        # generator fill the remaining frozen capacity.  This exception is
        # deliberately limited to the duplicate-only advancement diagnostic;
        # ordinary/free overlap reports must still match the exact capacity.
        oversized_duplicate_shape = False
        if len(current_ordinary_ids) != required_count:
            if (
                not repeated_ordinary_shape
                or len(current_ordinary_ids) < required_count
                or len(set(current_ordinary_ids)) > required_count
            ):
                return None
            oversized_duplicate_shape = len(current_ordinary_ids) > required_count

        allowed_by_slot = envelope.get("allowed_choice_ids_by_slot")
        nonselectable_by_slot = envelope.get("nonselectable_choice_ids_by_slot")
        unavailable_by_slot = envelope.get("unavailable_or_rejected_choice_ids_by_slot")
        offered_by_slot = envelope.get("offered_choice_ids_by_slot")
        prerequisites_by_slot = envelope.get("prerequisites_and_availability")
        choices_by_slot = envelope.get("choices_by_slot")
        typed_by_slot = envelope.get("typed_choice_authority_by_slot")
        if not all(isinstance(value, dict) for value in (
            allowed_by_slot,
            nonselectable_by_slot,
            unavailable_by_slot,
            offered_by_slot,
            prerequisites_by_slot,
            choices_by_slot,
            typed_by_slot,
        )):
            return None
        allowed_ids = clean_ids(allowed_by_slot.get("advancement_skeleton"))
        offered_ids = clean_ids(offered_by_slot.get("advancement_skeleton"))
        nonselectable_ids = clean_ids(nonselectable_by_slot.get("advancement_skeleton"))
        unavailable_ids = clean_ids(unavailable_by_slot.get("advancement_skeleton"))
        if allowed_ids is None or offered_ids is None or nonselectable_ids is None or unavailable_ids is None:
            return None
        allowed_set = set(allowed_ids)
        offered_set = set(offered_ids)
        excluded_ids = set(nonselectable_ids) | set(unavailable_ids)
        source_rows = choices_by_slot.get("advancement_skeleton")
        availability_rows = prerequisites_by_slot.get("advancement_skeleton")
        authority_slot = typed_by_slot.get("advancement_skeleton")
        stage2_authority = authority_slot.get("stage2_authority_by_choice") if isinstance(authority_slot, dict) else None
        if not isinstance(source_rows, dict) or not isinstance(availability_rows, dict) or not isinstance(stage2_authority, dict):
            return None

        # The ordinary array is positional: its zero-based index is the
        # effective character level.  Build the same sealed slot projection
        # used by the provider contract so a server-owned correction cannot
        # move a late-eligible Talent into an earlier position merely because
        # its minimum CL is within the overall target.
        try:
            compact_model = build_compact_choice_model(request)
        except (KeyError, TypeError, ValueError):
            return None
        ordinary_slots = compact_model.get("ordinary_talent_slots")
        if not isinstance(ordinary_slots, list):
            return None
        slots_by_cl: dict[int, dict[str, Any]] = {}
        for slot in ordinary_slots:
            if not isinstance(slot, dict):
                return None
            effective_cl = slot.get("cl")
            if type(effective_cl) is not int or effective_cl < 1 or effective_cl in slots_by_cl:
                return None
            eligible_choice_ids = slot.get("eligible_choice_ids")
            if (
                not isinstance(eligible_choice_ids, list)
                or any(not isinstance(choice_id, str) or not choice_id.strip() for choice_id in eligible_choice_ids)
            ):
                return None
            slots_by_cl[effective_cl] = slot
        if required_count > target_cl:
            return None
        position_eligible_ids: list[set[str]] = []
        for effective_cl in range(1, required_count + 1):
            slot = slots_by_cl.get(effective_cl)
            if not isinstance(slot, dict) or slot.get("active_for_request") is not True:
                return None
            eligible_choice_ids = slot.get("eligible_choice_ids")
            if not isinstance(eligible_choice_ids, list):
                return None
            eligible = set(eligible_choice_ids)
            if not eligible:
                return None
            position_eligible_ids.append(eligible)

        if isinstance(by_slot, dict):
            selected_background_spheres = by_slot.get("background_sphere_choice")
            background_rows = choices_by_slot.get("background_sphere_choice")
            background_authority_slot = typed_by_slot.get("background_sphere_choice")
            background_authority = (
                background_authority_slot.get("stage2_authority_by_choice")
                if isinstance(background_authority_slot, dict)
                else None
            )
            if isinstance(selected_background_spheres, list) and isinstance(background_rows, dict):
                for background_id in selected_background_spheres:
                    if not isinstance(background_id, str):
                        return None
                    row = background_rows.get(background_id)
                    auth = background_authority.get(background_id) if isinstance(background_authority, dict) else None
                    # Some frozen Background Sphere rows intentionally carry
                    # only their source display/name; the explicit acquired
                    # Sphere/free-Talent pair above is already sufficient to
                    # establish the ordinary Talent's owning sphere.  Do not
                    # infer a canonical sphere from a display-only row.
                    if not isinstance(row, dict) or not isinstance(auth, dict):
                        continue
                    canonical_sphere = (
                        auth.get("owning_canonical_sphere_id")
                        or auth.get("sphere_id")
                        or row.get("owning_canonical_sphere_id")
                        or row.get("sphere_id")
                    )
                    if not isinstance(canonical_sphere, str) or not canonical_sphere.strip():
                        return None
                    acquired_spheres.add(canonical_sphere)

        def relation_targets(relation: Any) -> list[str] | None:
            if isinstance(relation, str) and relation.strip():
                return [relation]
            if not isinstance(relation, dict):
                return None
            values = relation.get("target_ids") or relation.get("targets")
            if isinstance(values, str):
                return [values] if values.strip() else None
            if isinstance(values, list):
                if not values or any(not isinstance(value, str) or not value.strip() for value in values):
                    return None
                return list(dict.fromkeys(values))
            value = relation.get("target_id") or relation.get("record_id") or relation.get("canonical_id") or relation.get("id")
            return [value] if isinstance(value, str) and value.strip() else None

        def relations_are_legal(
            row: dict[str, Any],
            present_ids: set[str],
            *,
            allow_unsatisfied_prerequisites: bool = False,
        ) -> bool:
            for key in ("prerequisites", "incompatibilities"):
                relations = row.get(key)
                if not isinstance(relations, list):
                    return False
                for relation in relations:
                    targets = relation_targets(relation)
                    if not targets:
                        return False
                    operator = relation.get("operator", "requires") if isinstance(relation, dict) else "requires"
                    if operator not in {"requires", "one_of", "all_of", "not"}:
                        return False
                    if key == "prerequisites":
                        if allow_unsatisfied_prerequisites:
                            # A prerequisite may be supplied by another
                            # candidate in the complete replacement option.
                            # Still parse/validate every relation above so a
                            # malformed frozen row fails closed.
                            continue
                        satisfied = (
                            all(target in present_ids for target in targets)
                            if operator in {"requires", "all_of"}
                            else any(target in present_ids for target in targets)
                            if operator == "one_of"
                            else not any(target in present_ids for target in targets)
                        )
                        if not satisfied:
                            return False
                    elif any(target in present_ids for target in targets):
                        return False
            return True

        # The replacement target is the whole ordinary array.  Outgoing
        # ordinary IDs are deliberately absent: they are not retained facts
        # unless a generated option explicitly includes them.  Free-Talent
        # pairs and acquired Spheres remain available to candidate legality.
        present_ids: set[str] = set(current_free_ids) | acquired_spheres
        candidates: list[dict[str, Any]] = []
        relations_by_candidate: dict[str, dict[str, list[Any]]] = {}
        for candidate_id in sorted(allowed_set & offered_set):
            if candidate_id in excluded_ids or candidate_id in current_free_ids:
                continue
            source_row = source_rows.get(candidate_id)
            availability = availability_rows.get(candidate_id)
            authority = stage2_authority.get(candidate_id)
            if not isinstance(source_row, dict) or not isinstance(availability, dict) or not isinstance(authority, dict):
                continue
            if (
                source_row.get("choice_id", candidate_id) != candidate_id
                or source_row.get("id", candidate_id) != candidate_id
                or source_row.get("content_type") != "talent"
                or source_row.get("publication_state") != "published"
            ):
                continue
            if authority.get("authority_complete") is not True:
                continue
            if "level_talent_acquisition" not in (authority.get("allowed_kinds") or []):
                continue
            if not isinstance(authority.get("allowed_channels"), list) or not authority.get("allowed_channels"):
                continue
            availability_data = availability.get("availability")
            if not isinstance(availability_data, dict):
                continue
            if availability_data.get("suppression") or availability_data.get("realm_rules") or availability_data.get("source_cl"):
                continue
            minimum_cl = authority.get("minimum_cl")
            if type(minimum_cl) is not int:
                minimum_cl = availability_data.get("minimum_cl")
            if type(minimum_cl) is not int or minimum_cl > target_cl:
                continue
            eligible_cls = [
                effective_cl
                for effective_cl, eligible_ids in enumerate(position_eligible_ids, start=1)
                if candidate_id in eligible_ids
            ]
            if not eligible_cls:
                continue
            sphere_id = authority.get("sphere_id") or authority.get("owning_sphere_id") or authority.get("owning_canonical_sphere_id")
            if not isinstance(sphere_id, str) or sphere_id not in acquired_spheres:
                continue
            candidate_relation = {
                "prerequisites": availability.get("prerequisites"),
                "incompatibilities": availability.get("incompatibilities"),
            }
            if not relations_are_legal(
                candidate_relation,
                present_ids - {candidate_id},
                allow_unsatisfied_prerequisites=True,
            ):
                continue
            relations_by_candidate[candidate_id] = deepcopy(candidate_relation)
            candidates.append({
                "id": candidate_id,
                "name": _provider_short_text(source_row.get("name") or source_row.get("display_name"), 96, candidate_id),
                "cue": _provider_short_text(source_row.get("description") or source_row.get("semantic_cue"), 180, f"Talent choice {candidate_id}."),
                "sphere_id": sphere_id,
                "minimum_cl": minimum_cl,
                "eligible_cls": eligible_cls,
                **({"requires": sorted({target for relation in availability.get("prerequisites") or [] for target in (relation_targets(relation) or [])})} if availability.get("prerequisites") else {}),
            })
        if not candidates:
            return None

        candidate_ids = [row["id"] for row in candidates]
        preserved_ids = (
            [
                talent_id
                for talent_id in dict.fromkeys(current_ordinary_ids)
                if talent_id not in current_free_ids
            ]
            if repeated_ordinary_shape
            else []
        )
        # Every reported anchor must resolve to an eligible frozen candidate,
        # except a known free-Talent pair, which is intentionally replaced in
        # the ordinary array rather than silently retained there.  Unknown,
        # unavailable, cross-sphere, or incomplete-authority IDs therefore
        # fail closed before any option is emitted.
        if repeated_ordinary_shape and any(
            talent_id not in candidate_ids and talent_id not in current_free_ids
            for talent_id in dict.fromkeys(current_ordinary_ids)
        ):
            return None
        if any(talent_id not in candidate_ids for talent_id in preserved_ids):
            return None
        replacement_count = required_count - len(preserved_ids)
        if replacement_count < 0:
            return None
        replacement_candidate_ids = [
            candidate_id for candidate_id in candidate_ids if candidate_id not in preserved_ids
        ]
        # A correction is one small choice, not a second character build. Keep
        # a compact, diverse menu instead of sending hundreds of full arrays
        # to the local model. The server still validates and owns every array.
        max_option_count = 24
        options_by_id: dict[str, dict[str, Any]] = {}

        candidate_positions = {
            candidate["id"]: tuple(
                effective_cl
                for effective_cl, eligible_ids in enumerate(position_eligible_ids, start=1)
                if candidate["id"] in eligible_ids
            )
            for candidate in candidates
        }

        def position_legal_array(selected_ids: list[str]) -> list[str] | None:
            """Arrange a complete selected set across its legal CL slots."""

            if len(selected_ids) != required_count or len(set(selected_ids)) != required_count:
                return None
            if any(not candidate_positions.get(candidate_id) for candidate_id in selected_ids):
                return None

            # Deterministic bipartite matching keeps restrictive/late choices
            # in their legal positions while retaining every unique anchor.
            position_to_candidate: dict[int, str] = {}

            def assign(candidate_id: str, seen_positions: set[int]) -> bool:
                for effective_cl in candidate_positions[candidate_id]:
                    if effective_cl in seen_positions:
                        continue
                    seen_positions.add(effective_cl)
                    previous = position_to_candidate.get(effective_cl)
                    if previous is None or assign(previous, seen_positions):
                        position_to_candidate[effective_cl] = candidate_id
                        return True
                return False

            anchor_order = {
                candidate_id: index
                for index, candidate_id in enumerate(preserved_ids)
            }
            ordered_ids = sorted(
                selected_ids,
                key=lambda candidate_id: (
                    len(candidate_positions[candidate_id]),
                    0 if candidate_id in anchor_order else 1,
                    anchor_order.get(candidate_id, required_count),
                    candidate_id,
                ),
            )
            for candidate_id in ordered_ids:
                if not assign(candidate_id, set()):
                    return None
            if set(position_to_candidate) != set(range(1, required_count + 1)):
                return None
            return [position_to_candidate[effective_cl] for effective_cl in range(1, required_count + 1)]

        def add_legal_option(replacement_ids: Collection[str]) -> None:
            if len(options_by_id) >= max_option_count:
                return
            selected = preserved_ids + list(replacement_ids)
            arranged = position_legal_array(selected)
            if arranged is None:
                return
            joint_present = present_ids | set(arranged)
            if any(
                not relations_are_legal(relations_by_candidate[candidate_id], joint_present - {candidate_id})
                for candidate_id in arranged
            ):
                return
            mapping = {"ordinary_talent_ids": arranged}
            option_id = "ot_" + sha256_json(mapping)[:20]
            if option_id in options_by_id and options_by_id[option_id] != mapping:
                return
            options_by_id[option_id] = mapping

        # Circular windows provide much more variety than the first N
        # lexicographic combinations when most of a long array must be filled.
        if replacement_candidate_ids:
            for offset in range(len(replacement_candidate_ids)):
                rotated = replacement_candidate_ids[offset:] + replacement_candidate_ids[:offset]
                add_legal_option(rotated[:replacement_count])
        else:
            add_legal_option([])
        # Bounded fallback covers prerequisite pairings that a circular window
        # may miss without turning prompt construction into an exhaustive scan.
        for replacement_ids in itertools.islice(
            itertools.combinations(replacement_candidate_ids, replacement_count),
            4096,
        ):
            add_legal_option(replacement_ids)
            if len(options_by_id) >= max_option_count:
                break
        if not options_by_id:
            return None
        selectable_candidate_ids = {
            candidate_id
            for mapping in options_by_id.values()
            for candidate_id in mapping["ordinary_talent_ids"]
        }
        if not selectable_candidate_ids:
            return None
        candidates = [
            candidate
            for candidate in candidates
            if candidate["id"] in selectable_candidate_ids
        ]
        candidate_ids = [candidate["id"] for candidate in candidates]
        option_ids = sorted(options_by_id)
        return {
            "target_kind": "ordinary_duplicate",
            "fields": ["acquisition_intent.ordinary_talent_ids"] + (
                ["selection_intent.by_slot.advancement_skeleton"] if has_advancement_mirror else []
            ),
            "required_count": required_count,
            "free_talent_ids": sorted(current_free_ids),
            "preserved_ordinary_talent_ids": deepcopy(preserved_ids),
            "prior_ordinary_talent_ids": deepcopy(current_ordinary_ids),
            "oversized_duplicate_shape": oversized_duplicate_shape,
            "has_advancement_mirror": has_advancement_mirror,
            "candidate_ids": candidate_ids,
            "candidate_summaries": candidates,
            "option_ids": option_ids,
            "options": options_by_id,
            "response_schema": {
                "type": "object",
                "additionalProperties": False,
                "required": ["option_id"],
                "properties": {"option_id": {"type": "string", "enum": option_ids}},
            },
            "preserve_all_other_values": True,
            "instruction": (
                "Choose one opaque option_id whose server-owned ordinary Talent array preserves each "
                "legal existing Talent once, is coherent with the character, and exactly fills the "
                "frozen ordinary-Talent count with distinct choices."
            ),
        }

    @staticmethod
    def _merge_method_path_target_response(
        prior_response: str,
        provider_response: str,
        target: dict[str, Any],
        *,
        provider_completion_sha256: str | None = None,
        provider_response_sha256: str | None = None,
    ) -> tuple[str, dict[str, Any]]:
        raw_provider_completion_sha256 = (
            sha256_bytes(provider_response.encode("utf-8"))
            if isinstance(provider_response, str)
            else None
        )
        evidence: dict[str, Any] = {
            "target_scoped_merge": True,
            "target_kind": "method_path",
            "fields": deepcopy(target.get("fields") or []),
            "allowed_method_ids": deepcopy(target.get("allowed_method_ids") or []),
            "allowed_path_ids": deepcopy(target.get("allowed_path_ids") or []),
            "method_granted_path_ids": deepcopy(target.get("method_granted_path_ids") or {}),
            "path_progression_choices": deepcopy(target.get("path_progression_choices") or []),
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": raw_provider_completion_sha256,
            "raw_provider_response_sha256": raw_provider_completion_sha256,
            "provider_completion_sha256": provider_completion_sha256,
            "provider_response_sha256": provider_response_sha256,
        }

        def reject(message: str, **details: Any) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                message,
                details=error_details,
            )

        if not isinstance(provider_response, str) or not provider_response.strip():
            reject(
                "The local Method/Path correction did not return a target-scoped JSON choice.",
                reason="provider_response_missing",
            )
        try:
            provider_payload = json.loads(provider_response)
        except (TypeError, ValueError) as exc:
            reject(
                "The local Method/Path correction target was not valid JSON.",
                reason="provider_response_json_invalid",
            )
        if not isinstance(provider_payload, dict):
            reject(
                "The local Method/Path correction target must be a JSON object.",
                reason="provider_response_not_object",
            )
        if set(provider_payload) != {"option_id"}:
            reject(
                "The local Method/Path correction must contain only the opaque option_id field.",
                reason="option_shape_invalid",
                actual_keys=sorted(provider_payload),
            )
        option_id = provider_payload.get("option_id")
        if not isinstance(option_id, str) or not option_id.strip():
            reject(
                "The local Method/Path correction must return one opaque option_id string.",
                reason="option_id_missing_or_malformed",
                actual_type=type(option_id).__name__,
            )
        options = target.get("options")
        options = options if isinstance(options, dict) else {}
        selected_option = options.get(option_id)
        if not isinstance(selected_option, dict):
            reject(
                "The local Method/Path correction selected an unknown server-owned option.",
                reason="option_id_unknown",
                option_id=option_id,
            )
        method_values = selected_option.get("method_choice")
        path_values = selected_option.get("path_choice")
        progression = selected_option.get("path_progression_by_cl")
        if (
            not isinstance(method_values, list)
            or len(method_values) != 1
            or not isinstance(method_values[0], str)
            or not isinstance(path_values, list)
            or not path_values
            or not isinstance(progression, dict)
        ):
            reject(
                "The server-owned Method/Path correction option is malformed.",
                reason="server_option_malformed",
                option_id=option_id,
            )
        selected_method_id = method_values[0]

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for a target-scoped local correction.",
                details=evidence,
            ) from exc
        if not isinstance(prior_payload, dict):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be a JSON object for a target-scoped local correction.",
                details=evidence,
            )
        merged_payload = deepcopy(prior_payload)
        merged_selection_intent = merged_payload.get("selection_intent")
        merged_selection_intent = (
            deepcopy(merged_selection_intent)
            if isinstance(merged_selection_intent, dict)
            else {}
        )
        merged_by_slot = merged_selection_intent.get("by_slot")
        merged_by_slot = deepcopy(merged_by_slot) if isinstance(merged_by_slot, dict) else {}
        merged_by_slot["method_choice"] = deepcopy(method_values)
        merged_by_slot["path_choice"] = deepcopy(path_values)
        merged_selection_intent["by_slot"] = merged_by_slot
        merged_payload["selection_intent"] = merged_selection_intent

        merged_bounded_choices = merged_payload.get("bounded_choices")
        merged_bounded_choices = (
            deepcopy(merged_bounded_choices)
            if isinstance(merged_bounded_choices, dict)
            else {}
        )
        merged_bounded_choices["path_progression_by_cl"] = deepcopy(progression)
        merged_payload["bounded_choices"] = merged_bounded_choices
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "selected_option_id": option_id,
            "selected_method_id": selected_method_id,
            "selected_path_ids": deepcopy(path_values),
            "selected_path_progression_by_cl": deepcopy(progression),
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_acquisition_contract_target_response(
        prior_response: str,
        provider_response: str,
        target: dict[str, Any],
        *,
        provider_completion_sha256: str | None = None,
        provider_response_sha256: str | None = None,
    ) -> tuple[str, dict[str, Any]]:
        """Merge only one server-owned closed-world acquisition option."""
        raw_sha = sha256_bytes(provider_response.encode("utf-8")) if isinstance(provider_response, str) else None
        evidence: dict[str, Any] = {
            "target_scoped_merge": True,
            "target_kind": "acquisition_contract",
            "fields": deepcopy(target.get("fields") or []),
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": raw_sha,
            "raw_provider_response_sha256": raw_sha,
            "provider_completion_sha256": provider_completion_sha256,
            "provider_response_sha256": provider_response_sha256,
        }

        def reject(message: str, **details: Any) -> None:
            merged_details = deepcopy(evidence)
            merged_details.update(details)
            raise FoundryError("CG1_LOCAL_CORRECTION_TARGET_INVALID", message, details=merged_details)

        try:
            provider_payload = json.loads(provider_response)
        except (TypeError, ValueError):
            reject("The local acquisition correction target was not valid JSON.", reason="provider_response_json_invalid")
        if not isinstance(provider_payload, dict) or set(provider_payload) != {"option_id"}:
            reject(
                "The local acquisition correction must contain only the opaque option_id field.",
                reason="option_shape_invalid",
                actual_keys=sorted(provider_payload) if isinstance(provider_payload, dict) else [],
            )
        option_id = provider_payload.get("option_id")
        options = target.get("options")
        selected = options.get(option_id) if isinstance(options, dict) and isinstance(option_id, str) else None
        if not isinstance(selected, dict) or set(selected) != {"sphere_free_talent_pairs", "ordinary_talent_ids"}:
            reject("The local acquisition correction selected an unknown server-owned option.", reason="option_id_unknown")
        pairs = selected.get("sphere_free_talent_pairs")
        ordinary = selected.get("ordinary_talent_ids")
        expected = target.get("expected_counts")
        expected = expected if isinstance(expected, dict) else {}
        if (
            not isinstance(pairs, list)
            or len(pairs) != expected.get("sphere_free_talent_pairs")
            or not isinstance(ordinary, list)
            or len(ordinary) != expected.get("ordinary_talent_ids")
            or len(set(ordinary)) != len(ordinary)
            or any(not isinstance(value, str) for value in ordinary)
        ):
            reject("The server-owned acquisition option is malformed.", reason="server_option_malformed")
        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for a target-scoped local correction.",
                details=evidence,
            ) from exc
        if not isinstance(prior_payload, dict):
            reject("The retained response must be a JSON object.", reason="prior_response_shape_invalid")
        prior_acquisition = prior_payload.get("acquisition_intent")
        prior_selection = prior_payload.get("selection_intent")
        prior_by_slot = prior_selection.get("by_slot") if isinstance(prior_selection, dict) else None
        if not isinstance(prior_acquisition, dict) or not isinstance(prior_by_slot, dict):
            reject("The retained response lacks the acquisition fields required for merge.", reason="prior_target_missing")
        merged_payload = deepcopy(prior_payload)
        merged_acquisition = deepcopy(merged_payload["acquisition_intent"])
        merged_acquisition["sphere_free_talent_pairs"] = deepcopy(pairs)
        merged_acquisition["ordinary_talent_ids"] = deepcopy(ordinary)
        merged_payload["acquisition_intent"] = merged_acquisition
        merged_selection = deepcopy(merged_payload["selection_intent"])
        merged_by_slot = deepcopy(merged_selection["by_slot"])
        merged_by_slot["advancement_skeleton"] = deepcopy(ordinary)
        merged_selection["by_slot"] = merged_by_slot
        merged_payload["selection_intent"] = merged_selection
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "selected_option_id": option_id,
            "selected_sphere_free_talent_pairs": deepcopy(pairs),
            "selected_ordinary_talent_ids": deepcopy(ordinary),
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_ordinary_duplicate_target_response(
        prior_response: str,
        provider_response: str,
        target: dict[str, Any],
        *,
        provider_completion_sha256: str | None = None,
        provider_response_sha256: str | None = None,
    ) -> tuple[str, dict[str, Any]]:
        """Apply only the server-owned ordinary-Talent option to retained JSON."""
        raw_provider_completion_sha256 = (
            sha256_bytes(provider_response.encode("utf-8"))
            if isinstance(provider_response, str)
            else None
        )
        evidence: dict[str, Any] = {
            "target_scoped_merge": True,
            "target_kind": "ordinary_duplicate",
            "fields": deepcopy(target.get("fields") or ["acquisition_intent.ordinary_talent_ids"]),
            "required_count": target.get("required_count"),
            "candidate_ids": deepcopy(target.get("candidate_ids") or []),
            "free_talent_ids": deepcopy(target.get("free_talent_ids") or []),
            "preserved_ordinary_talent_ids": deepcopy(target.get("preserved_ordinary_talent_ids") or []),
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": raw_provider_completion_sha256,
            "raw_provider_response_sha256": raw_provider_completion_sha256,
            "provider_completion_sha256": provider_completion_sha256,
            "provider_response_sha256": provider_response_sha256,
        }

        def reject(message: str, **details: Any) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                message,
                details=error_details,
            )

        if not isinstance(provider_response, str) or not provider_response.strip():
            reject(
                "The local ordinary-Talent correction did not return a target-scoped JSON choice.",
                reason="provider_response_missing",
            )
        try:
            provider_payload = json.loads(provider_response)
        except (TypeError, ValueError):
            reject(
                "The local ordinary-Talent correction target was not valid JSON.",
                reason="provider_response_json_invalid",
            )
        if not isinstance(provider_payload, dict) or set(provider_payload) != {"option_id"}:
            reject(
                "The local ordinary-Talent correction must contain only the opaque option_id field.",
                reason="option_shape_invalid",
                actual_keys=sorted(provider_payload) if isinstance(provider_payload, dict) else [],
            )
        option_id = provider_payload.get("option_id")
        if not isinstance(option_id, str) or not option_id.strip():
            reject(
                "The local ordinary-Talent correction must return one opaque option_id string.",
                reason="option_id_missing_or_malformed",
                actual_type=type(option_id).__name__,
            )
        options = target.get("options")
        options = options if isinstance(options, dict) else {}
        selected_option = options.get(option_id)
        if not isinstance(selected_option, dict):
            reject(
                "The local ordinary-Talent correction selected an unknown server-owned option.",
                reason="option_id_unknown",
                option_id=option_id,
            )
        selected_ids = selected_option.get("ordinary_talent_ids")
        required_count = target.get("required_count")
        candidate_ids = {
            value for value in target.get("candidate_ids") or [] if isinstance(value, str)
        }
        free_ids = {
            value for value in target.get("free_talent_ids") or [] if isinstance(value, str)
        }
        if (
            not isinstance(required_count, int)
            or required_count < 1
            or not isinstance(selected_ids, list)
            or len(selected_ids) != required_count
            or len(set(selected_ids)) != required_count
            or any(not isinstance(value, str) or value not in candidate_ids or value in free_ids for value in selected_ids)
        ):
            reject(
                "The server-owned ordinary-Talent correction option is malformed or outside frozen authority.",
                reason="server_option_malformed",
                option_id=option_id,
            )

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for a target-scoped local correction.",
                details=evidence,
            ) from exc
        if not isinstance(prior_payload, dict):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be a JSON object for a target-scoped local correction.",
                details=evidence,
            )
        prior_acquisition = prior_payload.get("acquisition_intent")
        if not isinstance(prior_acquisition, dict):
            reject(
                "The retained response has no acquisition_intent ordinary-Talent array to repair.",
                reason="prior_acquisition_missing",
            )
        prior_ordinary = prior_acquisition.get("ordinary_talent_ids")
        expected_prior_ordinary = target.get("prior_ordinary_talent_ids")
        oversized_duplicate_prior = (
            target.get("oversized_duplicate_shape") is True
            and isinstance(required_count, int)
            and isinstance(prior_ordinary, list)
            and all(isinstance(value, str) for value in prior_ordinary)
            and len(prior_ordinary) > required_count
            and len(set(prior_ordinary)) <= required_count
            and len(set(prior_ordinary)) < len(prior_ordinary)
        )
        if (
            not isinstance(prior_ordinary, list)
            or (len(prior_ordinary) != required_count and not oversized_duplicate_prior)
            or any(not isinstance(value, str) for value in prior_ordinary)
            or not isinstance(expected_prior_ordinary, list)
            or prior_ordinary != expected_prior_ordinary
        ):
            reject(
                "The retained response ordinary-Talent array does not match frozen capacity.",
                reason="prior_ordinary_count_invalid",
            )
        merged_payload = deepcopy(prior_payload)
        merged_acquisition = deepcopy(merged_payload.get("acquisition_intent"))
        merged_acquisition["ordinary_talent_ids"] = deepcopy(selected_ids)
        merged_payload["acquisition_intent"] = merged_acquisition
        if target.get("has_advancement_mirror") is True:
            prior_selection = prior_payload.get("selection_intent")
            prior_by_slot = prior_selection.get("by_slot") if isinstance(prior_selection, dict) else None
            if (
                not isinstance(prior_by_slot, dict)
                or prior_by_slot.get("advancement_skeleton") != prior_ordinary
            ):
                reject(
                    "The retained response advancement-skeleton mirror does not match the ordinary-Talent array.",
                    reason="prior_advancement_mirror_invalid",
                )
            merged_selection = deepcopy(prior_selection)
            merged_by_slot = deepcopy(prior_by_slot)
            merged_by_slot["advancement_skeleton"] = deepcopy(selected_ids)
            merged_selection["by_slot"] = merged_by_slot
            merged_payload["selection_intent"] = merged_selection
        if "advancement_skeleton" in prior_payload:
            if prior_payload.get("advancement_skeleton") != prior_ordinary:
                reject(
                    "The retained top-level advancement-skeleton echo does not match the ordinary-Talent array.",
                    reason="prior_top_level_advancement_mirror_invalid",
                )
            merged_payload["advancement_skeleton"] = deepcopy(selected_ids)
            evidence["top_level_advancement_echo_updated"] = True
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "selected_option_id": option_id,
            "selected_ordinary_talent_ids": deepcopy(selected_ids),
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_insight_unavailable_target_response(
        prior_response: str,
        provider_response: str,
        target: dict[str, Any],
        *,
        provider_completion_sha256: str | None = None,
        provider_response_sha256: str | None = None,
    ) -> tuple[str, dict[str, Any]]:
        raw_provider_completion_sha256 = (
            sha256_bytes(provider_response.encode("utf-8"))
            if isinstance(provider_response, str)
            else None
        )
        evidence: dict[str, Any] = {
            "target_scoped_merge": True,
            "target_kind": "insight_unavailable",
            "fields": deepcopy(target.get("fields") or []),
            "unavailable_choice_id": target.get("unavailable_choice_id"),
            "required_count": target.get("required_count"),
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": raw_provider_completion_sha256,
            "raw_provider_response_sha256": raw_provider_completion_sha256,
            "provider_completion_sha256": provider_completion_sha256,
            "provider_response_sha256": provider_response_sha256,
        }

        def reject(message: str, **details: Any) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                message,
                details=error_details,
            )

        if not isinstance(provider_response, str) or not provider_response.strip():
            reject(
                "The local Insight correction did not return a target-scoped JSON choice.",
                reason="provider_response_missing",
            )
        try:
            provider_payload = json.loads(provider_response)
        except (TypeError, ValueError):
            reject(
                "The local Insight correction returned invalid JSON.",
                reason="provider_response_not_json",
            )
        if not isinstance(provider_payload, dict) or set(provider_payload) != {"option_id"}:
            reject(
                "The local Insight correction must contain exactly one opaque option_id.",
                reason="provider_shape_invalid",
            )
        option_id = provider_payload.get("option_id")
        options = target.get("options")
        if not isinstance(option_id, str) or not option_id.strip() or not isinstance(options, dict):
            reject(
                "The local Insight correction option is malformed or unavailable.",
                reason="server_option_malformed",
            )
        mapping = options.get(option_id)
        if not isinstance(mapping, dict) or set(mapping) != {"insight_priorities"}:
            reject(
                "The local Insight correction option is not server-owned.",
                reason="unknown_option_id",
                option_id=option_id,
            )
        selected_ids = mapping.get("insight_priorities")
        required_count = target.get("required_count")
        candidate_ids = target.get("candidate_ids")
        if (
            type(required_count) is not int
            or required_count < 1
            or not isinstance(candidate_ids, list)
            or not isinstance(selected_ids, list)
            or len(selected_ids) != required_count
            or len(set(selected_ids)) != required_count
            or any(not isinstance(value, str) or value not in candidate_ids for value in selected_ids)
        ):
            reject(
                "The server-owned Insight correction option is malformed or outside frozen authority.",
                reason="server_option_malformed",
                option_id=option_id,
            )

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for a target-scoped local correction.",
                details=evidence,
            ) from exc
        if not isinstance(prior_payload, dict):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be a JSON object for a target-scoped local correction.",
                details=evidence,
            )
        selection = prior_payload.get("selection_intent")
        by_slot = selection.get("by_slot") if isinstance(selection, dict) else None
        prior_ids = by_slot.get("insight_priorities") if isinstance(by_slot, dict) else None
        if (
            not isinstance(by_slot, dict)
            or not isinstance(prior_ids, list)
            or len(prior_ids) != required_count
            or len(set(prior_ids)) != required_count
            or any(not isinstance(value, str) for value in prior_ids)
        ):
            reject(
                "The retained response Insight priority array does not match frozen capacity.",
                reason="prior_insight_count_invalid",
            )
        merged_payload = deepcopy(prior_payload)
        merged_selection = deepcopy(merged_payload.get("selection_intent"))
        merged_by_slot = deepcopy(merged_selection.get("by_slot"))
        merged_by_slot["insight_priorities"] = deepcopy(selected_ids)
        merged_selection["by_slot"] = merged_by_slot
        merged_payload["selection_intent"] = merged_selection
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "selected_option_id": option_id,
            "selected_insight_priority_ids": deepcopy(selected_ids),
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_free_talent_not_legal_target_response(
        prior_response: str,
        provider_response: str,
        target: dict[str, Any],
        *,
        provider_completion_sha256: str | None = None,
        provider_response_sha256: str | None = None,
    ) -> tuple[str, dict[str, Any]]:
        """Merge one opaque legal pair into only the failing pair occurrence."""

        raw_provider_completion_sha256 = (
            sha256_bytes(provider_response.encode("utf-8"))
            if isinstance(provider_response, str)
            else None
        )
        evidence = {
            "target_scoped_merge": True,
            "target_kind": "free_talent_not_legal",
            "field": "acquisition_intent.sphere_free_talent_pairs",
            "pair_index": target.get("pair_index"),
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": raw_provider_completion_sha256,
            "provider_completion_sha256": provider_completion_sha256,
            "provider_response_sha256": provider_response_sha256,
        }

        def reject(reason: str, message: str = "The local correction pair option was invalid.") -> None:
            details = deepcopy(evidence)
            details["reason"] = reason
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                message,
                details=details,
            )

        if not isinstance(provider_response, str) or not provider_response.strip():
            reject("provider_response_missing")
        try:
            provider_payload = json.loads(provider_response)
        except (TypeError, ValueError):
            reject("provider_response_json_invalid")
        if not isinstance(provider_payload, dict) or set(provider_payload) != {"option_id"}:
            reject("provider_response_shape_invalid")
        option_id = provider_payload.get("option_id")
        if not isinstance(option_id, str) or not option_id.strip():
            reject("option_id_invalid")
        options = target.get("options")
        option = options.get(option_id) if isinstance(options, dict) else None
        if (
            not isinstance(option, dict)
            or set(option) != {"sphere_id", "talent_id"}
            or not isinstance(option.get("sphere_id"), str)
            or not isinstance(option.get("talent_id"), str)
        ):
            reject("option_id_unknown")

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for the free-Talent pair correction.",
                details=evidence,
            ) from exc
        if not isinstance(prior_payload, dict):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be an object for the free-Talent pair correction.",
                details=evidence,
            )
        acquisition = prior_payload.get("acquisition_intent")
        pairs = acquisition.get("sphere_free_talent_pairs") if isinstance(acquisition, dict) else None
        pair_index = target.get("pair_index")
        expected_pair_count = target.get("expected_pair_count")
        failing_pair = target.get("failing_pair")
        if (
            not isinstance(pairs, list)
            or type(pair_index) is not int
            or pair_index < 0
            or pair_index >= len(pairs)
            or type(expected_pair_count) is not int
            or expected_pair_count != len(pairs)
            or not isinstance(failing_pair, dict)
            or pairs[pair_index] != failing_pair
        ):
            reject("prior_pair_occurrence_changed", "The retained response pair occurrence changed before merge.")
        for index, pair in enumerate(pairs):
            if not isinstance(pair, dict) or not isinstance(pair.get("sphere_id"), str) or not isinstance(pair.get("talent_id"), str):
                reject("prior_pair_shape_invalid")
            if index != pair_index:
                if pair.get("sphere_id") == option.get("sphere_id"):
                    reject("replacement_sphere_reuses_retained_pair")
                if pair.get("talent_id") == option.get("talent_id"):
                    reject("replacement_talent_reuses_retained_pair")
        merged_payload = deepcopy(prior_payload)
        merged_acquisition = deepcopy(merged_payload.get("acquisition_intent"))
        merged_pairs = deepcopy(merged_acquisition.get("sphere_free_talent_pairs"))
        merged_pairs[pair_index] = deepcopy(option)
        merged_acquisition["sphere_free_talent_pairs"] = merged_pairs
        merged_payload["acquisition_intent"] = merged_acquisition
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "selected_option_id": option_id,
            "selected_pair": deepcopy(option),
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_free_talent_sphere_server_repair_response(
        prior_response: str,
        target: dict[str, Any],
    ) -> tuple[str, dict[str, Any]]:
        """Apply the catalog-proven owning Sphere without consulting a provider."""
        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for the deterministic Sphere repair.",
                details={"prior_response_sha256": sha256_bytes(prior_response.encode("utf-8"))},
            ) from exc
        if not isinstance(prior_payload, dict):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be an object for the deterministic Sphere repair.",
            )
        selected_ids = target.get("selected_sphere_ids")
        if (
            not isinstance(selected_ids, list)
            or len(selected_ids) != 1
            or not isinstance(selected_ids[0], str)
            or not selected_ids[0].strip()
        ):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The deterministic Sphere repair did not contain exactly one server-owned Sphere.",
                details={"reason": "selected_sphere_ids_invalid"},
            )
        selection_intent = prior_payload.get("selection_intent")
        by_slot = selection_intent.get("by_slot") if isinstance(selection_intent, dict) else None
        if not isinstance(by_slot, dict):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The retained response has no selection-intent slot map for the deterministic Sphere repair.",
                details={"reason": "selection_intent_missing"},
            )
        existing = by_slot.get("sphere_priorities")
        if existing is not None and existing != []:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The retained response already contains a conflicting Sphere-priority selection.",
                details={"reason": "sphere_priorities_not_empty"},
            )
        merged_payload = deepcopy(prior_payload)
        merged_selection = merged_payload.get("selection_intent")
        merged_selection = deepcopy(merged_selection) if isinstance(merged_selection, dict) else {}
        merged_by_slot = merged_selection.get("by_slot")
        merged_by_slot = deepcopy(merged_by_slot) if isinstance(merged_by_slot, dict) else {}
        merged_by_slot["sphere_priorities"] = [selected_ids[0]]
        merged_selection["by_slot"] = merged_by_slot
        merged_payload["selection_intent"] = merged_selection
        applied_response = canonical_json(merged_payload)
        evidence = {
            "target_scoped_merge": True,
            "target_kind": "free_talent_sphere_server_repair",
            "field": "selection_intent.by_slot.sphere_priorities",
            "selected_sphere_ids": deepcopy(selected_ids),
            "deterministic_server_repair": True,
            "provider_called": False,
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": None,
            "provider_completion_sha256": None,
            "provider_response_sha256": None,
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        }
        return applied_response, evidence

    @staticmethod
    def _merge_bounded_field_cleanup_target_response(
        prior_response: str,
        target: dict[str, Any],
        *,
        diagnostic: dict[str, Any],
        run: dict[str, Any] | None,
    ) -> tuple[str, dict[str, Any]]:
        """Remove only proven empty, unadvertised bounded-choice aliases."""
        prior_response_sha256 = sha256_bytes(prior_response.encode("utf-8"))
        evidence = {
            "target_scoped_merge": True,
            "target_kind": "bounded_field_cleanup",
            "prior_response_sha256": prior_response_sha256,
            "raw_provider_completion_sha256": None,
            "provider_completion_sha256": None,
            "provider_response_sha256": None,
        }

        def reject(code: str, message: str, **details: Any) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(code, message, details=error_details)

        if not isinstance(run, dict) or not isinstance(diagnostic, dict):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The bounded-field cleanup requires the exact sealed request and diagnostic.",
                reason="sealed_context_missing",
            )
        fresh_target = CharacterCreationExecutionService._provider_bounded_field_cleanup_repair_target(
            diagnostic,
            run=run,
            prior_response=prior_response,
        )
        if not isinstance(fresh_target, dict):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The sealed request no longer proves a safe bounded-field cleanup.",
                reason="target_not_proven",
            )
        expected_metadata = {
            key: fresh_target.get(key)
            for key in (
                "target_kind",
                "fields",
                "advertised_bounded_choice_keys",
                "request_sha256",
                "prior_response_sha256",
                "preserve_all_other_values",
                "empty_value_policy",
            )
        }
        actual_metadata = {
            key: target.get(key)
            for key in expected_metadata
        }
        if actual_metadata != expected_metadata:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The bounded-field cleanup target changed or was not sealed by the request.",
                reason="target_binding_changed",
            )
        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            reject(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for bounded-field cleanup.",
                reason="prior_response_json_invalid",
            )
            raise AssertionError("unreachable") from exc
        if not isinstance(prior_payload, dict):
            reject(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be an object for bounded-field cleanup.",
                reason="prior_response_not_object",
            )
        bounded_choices = prior_payload.get("bounded_choices")
        if not isinstance(bounded_choices, dict):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The retained response has no bounded_choices object for cleanup.",
                reason="bounded_choices_not_object",
            )
        advertised = set(fresh_target["advertised_bounded_choice_keys"])
        fields = list(fresh_target["fields"])
        for field in fields:
            if field in advertised or field not in bounded_choices:
                reject(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "A bounded-field cleanup target is no longer unadvertised and present.",
                    reason="field_binding_changed",
                    field=field,
                )
            value = bounded_choices[field]
            if not (
                value is None
                or (isinstance(value, (dict, list)) and not value)
            ):
                reject(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "A bounded-field cleanup target is no longer structurally empty.",
                    reason="field_value_not_empty",
                    field=field,
                )
        merged_payload = deepcopy(prior_payload)
        merged_bounded_choices = deepcopy(merged_payload["bounded_choices"])
        for field in fields:
            del merged_bounded_choices[field]
        merged_payload["bounded_choices"] = merged_bounded_choices
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "field": "bounded_choices",
            "removed_fields": fields,
            "advertised_bounded_choice_keys": deepcopy(
                fresh_target["advertised_bounded_choice_keys"]
            ),
            "deterministic_server_repair": True,
            "provider_called": False,
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_bounded_path_progression_empty_cleanup_target_response(
        prior_response: str,
        target: dict[str, Any],
        *,
        diagnostic: dict[str, Any],
        run: dict[str, Any] | None,
    ) -> tuple[str, dict[str, Any]]:
        """Remove only the frozen response's empty Path placeholders."""
        prior_response_sha256 = sha256_bytes(prior_response.encode("utf-8"))
        evidence = {
            "target_scoped_merge": True,
            "target_kind": "bounded_path_progression_empty_cleanup",
            "prior_response_sha256": prior_response_sha256,
            "raw_provider_completion_sha256": None,
            "provider_completion_sha256": None,
            "provider_response_sha256": None,
        }

        def reject(code: str, message: str, **details: Any) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(code, message, details=error_details)

        if not isinstance(run, dict) or not isinstance(diagnostic, dict):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The empty Path progression cleanup requires the exact retained request and diagnostic.",
                reason="sealed_context_missing",
            )
        fresh_target = CharacterCreationExecutionService._provider_bounded_path_progression_empty_cleanup_repair_target(
            diagnostic,
            run=run,
            prior_response=prior_response,
        )
        if not isinstance(fresh_target, dict):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The retained response no longer proves an empty Path progression cleanup.",
                reason="target_not_proven",
            )
        expected_metadata = {
            key: fresh_target.get(key)
            for key in (
                "target_kind",
                "field",
                "reported_cl",
                "removed_cl_keys",
                "request_sha256",
                "prior_response_sha256",
                "preserve_all_other_values",
                "empty_value_policy",
            )
        }
        actual_metadata = {
            key: target.get(key)
            for key in expected_metadata
        }
        if actual_metadata != expected_metadata:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The empty Path progression cleanup target changed or was not sealed by the retained response.",
                reason="target_binding_changed",
            )

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            reject(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for empty Path progression cleanup.",
                reason="prior_response_json_invalid",
            )
            raise AssertionError("unreachable") from exc
        if not isinstance(prior_payload, dict):
            reject(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be an object for empty Path progression cleanup.",
                reason="prior_response_not_object",
            )
        request_sha256 = fresh_target["request_sha256"]
        if prior_payload.get("request_sha256") != request_sha256:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The retained response request binding changed before empty Path progression cleanup.",
                reason="request_binding_changed",
            )
        bounded_choices = prior_payload.get("bounded_choices")
        progression = (
            bounded_choices.get("path_progression_by_cl")
            if isinstance(bounded_choices, dict)
            else None
        )
        if not isinstance(progression, dict):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The retained response has no Path progression map for cleanup.",
                reason="progression_not_object",
            )
        actual_empty_keys: list[str] = []
        for key, value in progression.items():
            if type(value) is list and value == []:
                if not isinstance(key, str) or not key.isdecimal() or int(key) < 1 or str(int(key)) != key:
                    reject(
                        "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                        "The retained Path progression map contained a malformed empty CL key.",
                        reason="empty_cl_key_invalid",
                    )
                actual_empty_keys.append(key)
        actual_empty_keys.sort(key=int)
        if actual_empty_keys != fresh_target["removed_cl_keys"]:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The retained Path progression empty entries changed before cleanup.",
                reason="removed_cl_keys_changed",
            )
        reported_key = str(fresh_target["reported_cl"])
        if reported_key not in actual_empty_keys:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The reported CL no longer contains an empty Path placeholder.",
                reason="reported_cl_not_empty",
            )

        merged_payload = deepcopy(prior_payload)
        merged_bounded_choices = deepcopy(merged_payload["bounded_choices"])
        merged_progression = deepcopy(merged_bounded_choices["path_progression_by_cl"])
        for key in actual_empty_keys:
            del merged_progression[key]
        merged_bounded_choices["path_progression_by_cl"] = merged_progression
        merged_payload["bounded_choices"] = merged_bounded_choices
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "field": "bounded_choices.path_progression_by_cl",
            "request_sha256": request_sha256,
            "reported_cl": fresh_target["reported_cl"],
            "removed_cl_keys": deepcopy(actual_empty_keys),
            "deterministic_server_repair": True,
            "provider_called": False,
            "empty_value_policy": fresh_target["empty_value_policy"],
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_bounded_path_progression_target_response(
        prior_response: str,
        provider_response: str,
        target: dict[str, Any],
        *,
        provider_completion_sha256: str | None = None,
        provider_response_sha256: str | None = None,
    ) -> tuple[str, dict[str, Any]]:
        """Merge one frozen Path target, or a batch of frozen singletons.

        The batch form is still a target-scoped merge: every selected value is
        server-owned and the retained response remains authoritative for all
        other fields.  Keeping this validation here also protects callers that
        use the merge seam directly instead of going through the deterministic
        repair target validator.
        """
        target_key = target.get("key")
        available_path_ids = target.get("available_path_ids")
        batch_map = target.get("batch_filled_path_progression_by_cl")
        batch_available = target.get("batch_available_path_ids_by_cl")
        if batch_map is None:
            if (
                not isinstance(target_key, str)
                or not target_key.strip()
                or not isinstance(available_path_ids, list)
                or len(available_path_ids) != 1
                or not isinstance(available_path_ids[0], str)
                or not available_path_ids[0].strip()
            ):
                raise FoundryError(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "The deterministic singleton Path target did not contain one exact frozen choice.",
                    details={"target_kind": target.get("target_kind"), "reason": "singleton_target_invalid"},
                )
            batch_map = {target_key: available_path_ids[0]}
        if not isinstance(batch_map, dict) or not batch_map:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The deterministic Path target did not contain a complete frozen singleton map.",
                details={"target_kind": target.get("target_kind"), "reason": "batch_map_invalid"},
            )
        if not isinstance(target_key, str) or target_key not in batch_map:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The deterministic Path target did not identify its reported CL.",
                details={"target_kind": target.get("target_kind"), "reason": "reported_cl_missing"},
            )

        def canonical_cl_key(value: Any) -> bool:
            if not isinstance(value, str) or not value.strip():
                return False
            try:
                parsed = int(value)
            except (TypeError, ValueError):
                return False
            return parsed >= 1 and str(parsed) == value

        if any(not canonical_cl_key(key) for key in batch_map):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The deterministic Path target contained a malformed CL key.",
                details={"target_kind": target.get("target_kind"), "reason": "batch_key_invalid"},
            )
        if not isinstance(batch_available, dict):
            if set(batch_map) == {target_key} and isinstance(available_path_ids, list):
                batch_available = {target_key: deepcopy(available_path_ids)}
            else:
                raise FoundryError(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "The deterministic Path target omitted per-CL frozen availability.",
                    details={"target_kind": target.get("target_kind"), "reason": "batch_availability_missing"},
                )
        if set(batch_available) != set(batch_map):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The deterministic Path target availability did not bind to its singleton map.",
                details={"target_kind": target.get("target_kind"), "reason": "batch_availability_keys_mismatch"},
            )
        for key, selected in batch_map.items():
            allowed = batch_available.get(key)
            if (
                not isinstance(selected, str)
                or not selected.strip()
                or not isinstance(allowed, list)
                or not allowed
                or any(not isinstance(value, str) or not value.strip() for value in allowed)
                or len(set(allowed)) != len(allowed)
                or selected not in allowed
            ):
                raise FoundryError(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "The deterministic Path target selected an unavailable singleton.",
                    details={"target_kind": target.get("target_kind"), "reason": "batch_selection_invalid", "key": key},
                )
        if (
            not isinstance(available_path_ids, list)
            or available_path_ids != batch_available.get(target_key)
            or len(available_path_ids) != 1
            or batch_map[target_key] not in available_path_ids
        ):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The reported Path choice was not bound to its diagnostic allowlist.",
                details={"target_kind": target.get("target_kind"), "reason": "reported_choice_invalid"},
            )
        reported_cl = target.get("reported_cl", int(target_key))
        if type(reported_cl) is not int or str(reported_cl) != target_key:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The deterministic Path target reported a malformed CL.",
                details={"target_kind": target.get("target_kind"), "reason": "reported_cl_invalid"},
            )

        raw_provider_completion_sha256 = (
            sha256_bytes(provider_response.encode("utf-8"))
            if isinstance(provider_response, str)
            else None
        )
        evidence = {
            "target_scoped_merge": True,
            "field": target["field"],
            "key": target_key,
            "available_path_ids": deepcopy(available_path_ids),
            "reported_cl": reported_cl,
            "batch_filled_path_progression_by_cl": deepcopy(batch_map),
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": raw_provider_completion_sha256,
            "provider_completion_sha256": provider_completion_sha256,
            "provider_response_sha256": provider_response_sha256,
        }

        def reject(code: str, message: str, **details: Any) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(code, message, details=error_details)

        if not isinstance(provider_response, str) or not provider_response.strip():
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction did not return a target-scoped JSON choice.",
                reason="provider_response_missing",
            )
        try:
            provider_payload = json.loads(provider_response)
        except (TypeError, ValueError) as exc:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction target was not valid JSON.",
                reason="provider_response_json_invalid",
            )
        if not isinstance(provider_payload, dict):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction target must be a JSON object.",
                reason="provider_response_not_object",
            )
        bounded_choices = provider_payload.get("bounded_choices")
        progression = (
            bounded_choices.get("path_progression_by_cl")
            if isinstance(bounded_choices, dict)
            else None
        )
        if not isinstance(progression, dict) or set(progression) != set(batch_map):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction omitted or changed the exact Path progression target.",
                reason="target_missing_or_extra",
            )
        selected_map: dict[str, str] = {}
        for key in sorted(batch_map, key=int):
            selected_path_id = progression[key]
            if not isinstance(selected_path_id, str) or not selected_path_id.strip():
                reject(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "The local correction Path progression target must be exactly one string ID.",
                    reason="target_ambiguous_or_not_string",
                    key=key,
                    actual_type=type(selected_path_id).__name__,
                )
            if selected_path_id not in batch_available[key]:
                reject(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "The local correction selected a Path ID outside the frozen allowlist.",
                    reason="target_path_id_not_allowed",
                    key=key,
                    selected_path_id=selected_path_id,
                )
            if selected_path_id != batch_map[key]:
                reject(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "The local correction changed a deterministic frozen singleton.",
                    reason="deterministic_selection_changed",
                    key=key,
                    selected_path_id=selected_path_id,
                )
            selected_map[key] = selected_path_id

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for a target-scoped local correction.",
                details=evidence,
            ) from exc
        if not isinstance(prior_payload, dict):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be a JSON object for a target-scoped local correction.",
                details=evidence,
            )
        merged_payload = deepcopy(prior_payload)
        merged_bounded_choices = merged_payload.get("bounded_choices")
        merged_bounded_choices = (
            deepcopy(merged_bounded_choices)
            if isinstance(merged_bounded_choices, dict)
            else {}
        )
        merged_progression = merged_bounded_choices.get("path_progression_by_cl")
        merged_progression = (
            deepcopy(merged_progression)
            if isinstance(merged_progression, dict)
            else {}
        )
        if any(key in merged_progression for key in selected_map):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The deterministic Path target would overwrite an existing selection.",
                reason="target_overwrites_existing",
            )
        merged_progression.update(selected_map)
        merged_bounded_choices["path_progression_by_cl"] = merged_progression
        merged_payload["bounded_choices"] = merged_bounded_choices
        applied_response = canonical_json(merged_payload)
        evidence["selected_path_id"] = selected_map[target_key]
        evidence["selected_path_progression_by_cl"] = deepcopy(selected_map)
        evidence["applied_response_sha256"] = sha256_bytes(applied_response.encode("utf-8"))
        return applied_response, evidence

    @staticmethod
    def _merge_advancement_choice_target_response(
        prior_response: str,
        provider_response: str,
        target: dict[str, Any],
        *,
        run: dict[str, Any] | None = None,
        diagnostic: dict[str, Any] | None = None,
        provider_completion_sha256: str | None = None,
        provider_response_sha256: str | None = None,
    ) -> tuple[str, dict[str, Any]]:
        """Merge exactly one opaque Advancement Choice into retained JSON."""
        raw_provider_sha256 = (
            sha256_bytes(provider_response.encode("utf-8"))
            if isinstance(provider_response, str)
            else None
        )
        evidence: dict[str, Any] = {
            "target_scoped_merge": True,
            "target_kind": "advancement_choice",
            "field": target.get("field"),
            "milestone_id": target.get("milestone_id"),
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": raw_provider_sha256,
            "raw_provider_response_sha256": raw_provider_sha256,
            "provider_completion_sha256": provider_completion_sha256,
            "provider_response_sha256": provider_response_sha256,
        }

        def reject(message: str, **details: Any) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                message,
                details=error_details,
            )

        request = run.get("request") if isinstance(run, dict) else None
        request = request if isinstance(request, dict) else None
        if not isinstance(request, dict) or not isinstance(diagnostic, dict):
            reject("The Advancement Choice correction lacks its exact request diagnostic binding.", reason="binding_context_missing")
        request_sha256 = request.get("request_sha256")
        actual_prior_sha256 = sha256_bytes(prior_response.encode("utf-8"))
        if (
            not isinstance(request_sha256, str)
            or request_sha256 != target.get("request_sha256")
            or target.get("prior_response_sha256") != actual_prior_sha256
        ):
            reject(
                "The Advancement Choice correction target is stale or hash-mismatched.",
                reason="request_or_prior_response_hash_mismatch",
            )
        expected_target = CharacterCreationExecutionService._provider_advancement_choice_repair_target(
            diagnostic,
            run=run,
            prior_response=prior_response,
        )
        if not isinstance(expected_target, dict):
            reject("The frozen Advancement Choice authority is no longer available.", reason="target_unavailable")
        target_keys = (
            "target_kind", "field", "milestone_id", "effective_cl", "allowed_kinds",
            "request_sha256", "prior_response_sha256", "option_ids", "options",
            "option_summaries", "response_schema", "preserve_all_other_values",
        )
        if any(target.get(key) != expected_target.get(key) for key in target_keys):
            reject("The Advancement Choice target no longer matches frozen authority.", reason="target_lineage_mismatch")

        def strict_object(text: str) -> dict[str, Any] | None:
            def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
                result: dict[str, Any] = {}
                for key, value in items:
                    if key in result:
                        raise ValueError("duplicate object key")
                    result[key] = value
                return result

            try:
                value = json.loads(text, object_pairs_hook=pairs)
            except (TypeError, ValueError, json.JSONDecodeError):
                return None
            return value if isinstance(value, dict) else None

        provider_payload = strict_object(provider_response) if isinstance(provider_response, str) else None
        if provider_payload is None:
            reject("The local Advancement Choice correction was not one JSON object.", reason="provider_response_json_invalid")
        if set(provider_payload) != {"option_id"}:
            reject(
                "The local Advancement Choice correction must contain only option_id.",
                reason="provider_response_shape_invalid",
                actual_keys=sorted(provider_payload),
            )
        option_id = provider_payload.get("option_id")
        if not isinstance(option_id, str) or not option_id.strip() or option_id not in target["option_ids"]:
            reject("The local Advancement Choice correction selected an unknown option.", reason="option_id_unknown")
        selected = target["options"].get(option_id)
        if (
            not isinstance(selected, dict)
            or set(selected) != {"value", "kind", "milestone_id"}
            or selected.get("milestone_id") != target["milestone_id"]
            or selected.get("kind") not in {"ability_score_change", "cultivation_insight_acquisition"}
            or not isinstance(selected.get("value"), dict)
        ):
            reject("The server-owned Advancement Choice option is malformed.", reason="server_option_malformed")
        value = selected["value"]
        kind = selected["kind"]
        if value.get("kind") != kind or value.get("milestone_id") != target["milestone_id"]:
            reject("The server-owned Advancement Choice value is not typed for the target milestone.", reason="server_value_malformed")

        prior_payload = strict_object(prior_response)
        if prior_payload is None:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for an Advancement Choice correction.",
                details=evidence,
            )
        if prior_payload.get("request_sha256") != request_sha256:
            reject("The retained response is not bound to the active request.", reason="prior_request_hash_mismatch")
        bounded = prior_payload.get("bounded_choices")
        acquisition = prior_payload.get("acquisition_intent")
        if not isinstance(bounded, dict) or not isinstance(acquisition, dict):
            reject("The retained response lacks the exact Advancement Choice fields.", reason="prior_target_missing")
        changes = bounded.get("ability_score_changes_by_milestone_id")
        occurrences = acquisition.get("insight_occurrences")
        if not isinstance(changes, dict) or not isinstance(occurrences, list):
            reject("The retained response has malformed Advancement Choice containers.", reason="prior_target_malformed")
        if target["milestone_id"] in changes or any(
            isinstance(row, dict) and row.get("milestone_id") == target["milestone_id"]
            for row in occurrences
        ):
            reject("The retained response already contains the target milestone resolution.", reason="target_already_resolved")

        merged_payload = deepcopy(prior_payload)
        merged_bounded = deepcopy(merged_payload["bounded_choices"])
        merged_acquisition = deepcopy(merged_payload["acquisition_intent"])
        if kind == "ability_score_change":
            if set(value) != {"kind", "milestone_id", "deltas"} or not isinstance(value.get("deltas"), dict) or not value["deltas"]:
                reject("The ability-score Advancement Choice option is malformed.", reason="server_value_malformed")
            merged_changes = deepcopy(merged_bounded["ability_score_changes_by_milestone_id"])
            merged_changes[target["milestone_id"]] = {"deltas": deepcopy(value["deltas"])}
            merged_bounded["ability_score_changes_by_milestone_id"] = merged_changes
        else:
            if set(value) - {"kind", "milestone_id", "insight_id", "parameters"}:
                reject("The Insight Advancement Choice option is malformed.", reason="server_value_malformed")
            insight_id = value.get("insight_id")
            if not isinstance(insight_id, str) or not insight_id.strip():
                reject("The Insight Advancement Choice option lacks its source ID.", reason="server_value_malformed")
            occurrence = {
                "milestone_id": target["milestone_id"],
                "insight_id": insight_id,
            }
            if "parameters" in value:
                if not isinstance(value["parameters"], dict):
                    reject("The Insight Advancement Choice parameters are malformed.", reason="server_value_malformed")
                occurrence["parameters"] = deepcopy(value["parameters"])
            merged_occurrences = deepcopy(merged_acquisition["insight_occurrences"])
            merged_occurrences.append(occurrence)
            merged_acquisition["insight_occurrences"] = merged_occurrences
        merged_payload["bounded_choices"] = merged_bounded
        merged_payload["acquisition_intent"] = merged_acquisition
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "request_sha256": request_sha256,
            "selected_option_id": option_id,
            "selected_kind": kind,
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_ordinary_order_mirror_server_repair_response(
        prior_response: str,
        provider_response: str,
        target: dict[str, Any],
        *,
        run: dict[str, Any] | None = None,
    ) -> tuple[str, dict[str, Any]]:
        """Apply only a proven ordinary-order permutation and mirror.

        ``provider_response`` must be empty: this target is a Retry Local
        Build server repair, never a Local-AI/provider correction.  The
        retained object is copied and exactly two nested values are replaced;
        all provider evidence remains on the prior append-only attempt.
        """
        target_kind = _ORDINARY_ORDER_MIRROR_TARGET_KIND
        evidence: dict[str, Any] = {
            "target_scoped_merge": True,
            "target_kind": target_kind,
            "fields": deepcopy(target.get("fields") or []),
            "deterministic_server_repair": True,
            "provider_called": False,
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": None,
            "raw_provider_response_sha256": None,
            "provider_completion_sha256": None,
            "provider_response_sha256": None,
        }

        def reject(message: str, **details: Any) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                message,
                details=error_details,
            )

        if provider_response != "":
            reject(
                "The ordinary-order server repair accepts no provider selector or response bytes.",
                reason="provider_response_forbidden",
            )
        if (
            not isinstance(target, dict)
            or target.get("target_kind") != target_kind
            or target.get("retry_only") is not True
            or target.get("preserve_all_other_values") is not True
            or target.get("provider_called") is not False
        ):
            reject("The ordinary-order server repair target was not a complete retry-only proof.", reason="target_invalid")
        expected_prior_hash = target.get("prior_response_sha256")
        if expected_prior_hash != evidence["prior_response_sha256"]:
            reject("The retained response hash did not match the frozen repair target.", reason="prior_response_hash_mismatch")
        request = run.get("request") if isinstance(run, dict) else None
        if isinstance(request, dict) and target.get("request_sha256") != request.get("request_sha256"):
            reject("The repair target was bound to a different active request.", reason="request_binding_mismatch")
        prior_ordinary = target.get("prior_ordinary_talent_ids")
        prior_skeleton = target.get("prior_advancement_skeleton")
        derived_ordinary = target.get("derived_ordinary_talent_ids")
        if (
            not isinstance(prior_ordinary, list)
            or not prior_ordinary
            or any(not isinstance(value, str) or not value.strip() for value in prior_ordinary)
            or len(set(prior_ordinary)) != len(prior_ordinary)
            or not isinstance(prior_skeleton, list)
            or not isinstance(derived_ordinary, list)
            or len(derived_ordinary) != len(prior_ordinary)
            or any(not isinstance(value, str) or not value.strip() for value in derived_ordinary)
            or len(set(derived_ordinary)) != len(derived_ordinary)
            or set(derived_ordinary) != set(prior_ordinary)
            or prior_skeleton not in ([], prior_ordinary)
            or prior_skeleton == derived_ordinary
        ):
            reject("The ordinary-order server repair arrays were malformed or not a permutation.", reason="array_proof_invalid")
        if target.get("ordinary_issue_indices") != [
            index
            for index, (prior, derived) in enumerate(zip(prior_ordinary, derived_ordinary))
            if prior != derived
        ]:
            reject("The ordinary-order server repair did not retain its exact mismatch proof.", reason="mismatch_proof_invalid")

        def strict_load(text: str) -> dict[str, Any] | None:
            def pairs(items: list[tuple[str, Any]]) -> dict[str, Any]:
                result: dict[str, Any] = {}
                for key, value in items:
                    if key in result:
                        raise ValueError("duplicate object key")
                    result[key] = value
                return result

            try:
                value = json.loads(text, object_pairs_hook=pairs)
            except (TypeError, ValueError, json.JSONDecodeError):
                return None
            return value if isinstance(value, dict) else None

        prior_payload = strict_load(prior_response)
        if not isinstance(prior_payload, dict):
            reject("The retained response was not a strict JSON object.", reason="prior_response_invalid")
        acquisition = prior_payload.get("acquisition_intent")
        selection = prior_payload.get("selection_intent")
        by_slot = selection.get("by_slot") if isinstance(selection, dict) else None
        if (
            not isinstance(acquisition, dict)
            or not isinstance(selection, dict)
            or not isinstance(by_slot, dict)
            or acquisition.get("ordinary_talent_ids") != prior_ordinary
            or by_slot.get("advancement_skeleton") != prior_skeleton
        ):
            reject("The retained response no longer matched the exact repair proof.", reason="prior_values_mismatch")
        merged_payload = deepcopy(prior_payload)
        merged_acquisition = deepcopy(merged_payload["acquisition_intent"])
        merged_acquisition["ordinary_talent_ids"] = deepcopy(derived_ordinary)
        merged_payload["acquisition_intent"] = merged_acquisition
        merged_selection = deepcopy(merged_payload["selection_intent"])
        merged_by_slot = deepcopy(merged_selection["by_slot"])
        merged_by_slot["advancement_skeleton"] = deepcopy(derived_ordinary)
        merged_selection["by_slot"] = merged_by_slot
        merged_payload["selection_intent"] = merged_selection
        applied_response = canonical_json(merged_payload)
        evidence.update({
            "request_sha256": target.get("request_sha256"),
            "diagnostic_sha256": target.get("diagnostic_sha256"),
            "prior_ordinary_talent_ids": deepcopy(prior_ordinary),
            "derived_ordinary_talent_ids": deepcopy(derived_ordinary),
            "repaired_fields": [
                "acquisition_intent.ordinary_talent_ids",
                "selection_intent.by_slot.advancement_skeleton",
            ],
            "applied_response_sha256": sha256_bytes(applied_response.encode("utf-8")),
        })
        return applied_response, evidence

    @staticmethod
    def _merge_target_scoped_correction_response(
        prior_response: str,
        provider_response: str,
        diagnostic: dict[str, Any],
        *,
        run: dict[str, Any] | None = None,
        repair_target: dict[str, Any] | None | object = _REPAIR_TARGET_UNSET,
        provider_completion_sha256: str | None = None,
        provider_response_sha256: str | None = None,
    ) -> tuple[str, dict[str, Any]]:
        """Merge only the diagnostic-proven target into retained provider JSON."""
        if repair_target is _REPAIR_TARGET_UNSET:
            target = CharacterCreationExecutionService._provider_target_scoped_repair_target(
                diagnostic,
                run=run,
                prior_response=prior_response,
            )
        else:
            target = deepcopy(repair_target) if isinstance(repair_target, dict) else None
        if target is None:
            return provider_response, {}
        if target.get("target_kind") == "acquisition_contract":
            return CharacterCreationExecutionService._merge_acquisition_contract_target_response(
                prior_response,
                provider_response,
                target,
                provider_completion_sha256=provider_completion_sha256,
                provider_response_sha256=provider_response_sha256,
            )
        if target.get("target_kind") == "free_talent_sphere_server_repair":
            return CharacterCreationExecutionService._merge_free_talent_sphere_server_repair_response(
                prior_response,
                target,
            )
        if target.get("target_kind") == "bounded_field_cleanup":
            return CharacterCreationExecutionService._merge_bounded_field_cleanup_target_response(
                prior_response,
                target,
                diagnostic=diagnostic,
                run=run,
            )
        if target.get("target_kind") == "bounded_path_progression_empty_cleanup":
            return CharacterCreationExecutionService._merge_bounded_path_progression_empty_cleanup_target_response(
                prior_response,
                target,
                diagnostic=diagnostic,
                run=run,
            )
        if target.get("target_kind") == "free_talent_not_legal":
            return CharacterCreationExecutionService._merge_free_talent_not_legal_target_response(
                prior_response,
                provider_response,
                target,
                provider_completion_sha256=provider_completion_sha256,
                provider_response_sha256=provider_response_sha256,
            )
        if target.get("target_kind") == "method_path":
            return CharacterCreationExecutionService._merge_method_path_target_response(
                prior_response,
                provider_response,
                target,
                provider_completion_sha256=provider_completion_sha256,
                provider_response_sha256=provider_response_sha256,
            )
        if target.get("target_kind") == "ordinary_duplicate":
            return CharacterCreationExecutionService._merge_ordinary_duplicate_target_response(
                prior_response,
                provider_response,
                target,
                provider_completion_sha256=provider_completion_sha256,
                provider_response_sha256=provider_response_sha256,
            )
        if target.get("target_kind") == _ORDINARY_ORDER_MIRROR_TARGET_KIND:
            return CharacterCreationExecutionService._merge_ordinary_order_mirror_server_repair_response(
                prior_response,
                provider_response,
                target,
                run=run,
            )
        if target.get("target_kind") == "bounded_path_progression_singleton":
            return CharacterCreationExecutionService._merge_bounded_path_progression_target_response(
                prior_response,
                provider_response,
                target,
                provider_completion_sha256=provider_completion_sha256,
                provider_response_sha256=provider_response_sha256,
            )
        if target.get("target_kind") == "insight_unavailable":
            return CharacterCreationExecutionService._merge_insight_unavailable_target_response(
                prior_response,
                provider_response,
                target,
                provider_completion_sha256=provider_completion_sha256,
                provider_response_sha256=provider_response_sha256,
            )
        if target.get("target_kind") == "advancement_choice":
            return CharacterCreationExecutionService._merge_advancement_choice_target_response(
                prior_response,
                provider_response,
                target,
                run=run,
                diagnostic=diagnostic,
                provider_completion_sha256=provider_completion_sha256,
                provider_response_sha256=provider_response_sha256,
            )

        raw_provider_completion_sha256 = (
            sha256_bytes(provider_response.encode("utf-8"))
            if isinstance(provider_response, str)
            else None
        )
        evidence = {
            "target_scoped_merge": True,
            "field": target["field"],
            "key": target["key"],
            "available_path_ids": deepcopy(target["available_path_ids"]),
            "prior_response_sha256": sha256_bytes(prior_response.encode("utf-8")),
            "raw_provider_completion_sha256": raw_provider_completion_sha256,
            "provider_completion_sha256": provider_completion_sha256,
            "provider_response_sha256": provider_response_sha256,
        }

        def reject(
            code: str,
            message: str,
            **details: Any,
        ) -> None:
            error_details = deepcopy(evidence)
            error_details.update(details)
            raise FoundryError(code, message, details=error_details)

        if not isinstance(provider_response, str) or not provider_response.strip():
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction did not return a target-scoped JSON choice.",
                reason="provider_response_missing",
            )
        try:
            provider_payload = json.loads(provider_response)
        except (TypeError, ValueError) as exc:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction target was not valid JSON.",
                reason="provider_response_json_invalid",
            )
        if not isinstance(provider_payload, dict):
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction target must be a JSON object.",
                reason="provider_response_not_object",
            )
        bounded_choices = provider_payload.get("bounded_choices")
        progression = (
            bounded_choices.get("path_progression_by_cl")
            if isinstance(bounded_choices, dict)
            else None
        )
        if not isinstance(progression, dict) or target["key"] not in progression:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction omitted the exact Path progression target.",
                reason="target_missing",
            )
        selected_path_id = progression[target["key"]]
        if not isinstance(selected_path_id, str) or not selected_path_id.strip():
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction Path progression target must be exactly one string ID.",
                reason="target_ambiguous_or_not_string",
                actual_type=type(selected_path_id).__name__,
            )
        if selected_path_id not in target["available_path_ids"]:
            reject(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The local correction selected a Path ID outside the diagnostic allowlist.",
                reason="target_path_id_not_allowed",
                selected_path_id=selected_path_id,
            )

        try:
            prior_payload = json.loads(prior_response)
        except (TypeError, ValueError) as exc:
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response could not be parsed for a target-scoped local correction.",
                details=evidence,
            ) from exc
        if not isinstance(prior_payload, dict):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_PRIOR_RESPONSE_INVALID",
                "The retained response must be a JSON object for a target-scoped local correction.",
                details=evidence,
            )
        merged_payload = deepcopy(prior_payload)
        merged_bounded_choices = merged_payload.get("bounded_choices")
        merged_bounded_choices = (
            deepcopy(merged_bounded_choices)
            if isinstance(merged_bounded_choices, dict)
            else {}
        )
        merged_progression = merged_bounded_choices.get("path_progression_by_cl")
        merged_progression = (
            deepcopy(merged_progression)
            if isinstance(merged_progression, dict)
            else {}
        )
        merged_progression[target["key"]] = selected_path_id
        merged_bounded_choices["path_progression_by_cl"] = merged_progression
        merged_payload["bounded_choices"] = merged_bounded_choices
        applied_response = canonical_json(merged_payload)
        evidence["selected_path_id"] = selected_path_id
        evidence["applied_response_sha256"] = sha256_bytes(applied_response.encode("utf-8"))
        return applied_response, evidence

    @staticmethod
    def _provider_advancement_choice_correction_prompt(
        run: dict[str, Any],
        diagnostic: dict[str, Any],
        repair_target: dict[str, Any],
        *,
        prior_response_sha256: str,
    ) -> str:
        """Build a compact opaque-option prompt for one Advancement Choice."""
        request = run.get("request") if isinstance(run, dict) else None
        request = request if isinstance(request, dict) else {}
        request_sha256 = request.get("request_sha256")
        expected_prior_sha256 = repair_target.get("prior_response_sha256")
        if (
            not isinstance(request_sha256, str)
            or request_sha256 != repair_target.get("request_sha256")
            or not isinstance(prior_response_sha256, str)
            or prior_response_sha256 != expected_prior_sha256
        ):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_CONTEXT_INVALID",
                "The Advancement Choice correction is not bound to the exact request and retained response.",
                status_code=409,
            )
        envelope = request.get("delegated_choice_envelope")
        envelope = envelope if isinstance(envelope, dict) else {}
        delegated_context = _provider_descriptive_context(envelope)
        descriptive = run.get("owner_descriptive_fields") if isinstance(run, dict) else None
        descriptive = descriptive if isinstance(descriptive, dict) else {}
        resolved = descriptive.get("resolved") if isinstance(descriptive.get("resolved"), dict) else {}
        accepted = descriptive.get("accepted") if isinstance(descriptive.get("accepted"), dict) else {}
        proposed = descriptive.get("proposed") if isinstance(descriptive.get("proposed"), dict) else {}
        resolved_identity = resolved.get("identity") if isinstance(resolved.get("identity"), dict) else {}
        accepted_identity = accepted.get("identity") if isinstance(accepted.get("identity"), dict) else {}
        proposed_identity = proposed.get("identity") if isinstance(proposed.get("identity"), dict) else {}
        name_authority = delegated_context.get("identity.name") or {}
        concept_authority = delegated_context.get("concept") or {}

        def first_text(*values: Any, fallback: str) -> str:
            for value in values:
                if isinstance(value, str) and value.strip():
                    return _provider_short_text(value, 180, fallback)
            return fallback

        summaries: list[dict[str, Any]] = []
        for summary in repair_target.get("option_summaries") or []:
            if not isinstance(summary, dict) or not isinstance(summary.get("option_id"), str):
                raise FoundryError(
                    "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                    "The Advancement Choice target contains a malformed option summary.",
                    status_code=409,
                )
            summaries.append({
                "option_id": summary["option_id"],
                "display_name": _provider_short_text(summary.get("display_name"), 120, "Advancement resolution"),
                "semantic_cue": _provider_short_text(summary.get("semantic_cue"), 180, "Source-backed advancement resolution."),
                "kind": summary.get("kind"),
            })
        option_ids = repair_target.get("option_ids")
        if (
            not isinstance(option_ids, list)
            or not option_ids
            or any(not isinstance(option_id, str) or not option_id.strip() for option_id in option_ids)
            or option_ids != sorted(set(option_ids))
            or {row["option_id"] for row in summaries} != set(option_ids)
        ):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The Advancement Choice target option enum is malformed.",
                status_code=409,
            )
        field = repair_target.get("field")
        milestone_id = repair_target.get("milestone_id")
        if (
            not isinstance(field, str)
            or not isinstance(milestone_id, str)
            or field != f"bounded_choices.ability_score_changes_by_milestone_id.{milestone_id}"
        ):
            raise FoundryError(
                "CG1_LOCAL_CORRECTION_TARGET_INVALID",
                "The Advancement Choice target field is not bound to one exact milestone.",
                status_code=409,
            )
        binding = {
            "project_id": request.get("project_id"),
            "project_revision": request.get("project_revision"),
            "request_sha256": request_sha256,
            "prior_response_sha256": prior_response_sha256,
        }
        context = {
            "schema": "TianxiaFoundry.LocalProviderAdvancementChoiceCorrection.v1",
            "prompt_kind": "advancement_choice_option_selector",
            "binding": binding,
            "character_context": {
                "name": {
                    "state": name_authority.get("state") or "delegated",
                    "value": first_text(
                        resolved_identity.get("name"),
                        accepted_identity.get("name"),
                        proposed_identity.get("name"),
                        name_authority.get("owner_locked_value"),
                        fallback="delegated name",
                    ),
                },
                "concept": {
                    "state": concept_authority.get("state") or "delegated",
                    "value": first_text(
                        resolved.get("concept"),
                        accepted.get("concept"),
                        proposed.get("concept"),
                        concept_authority.get("owner_locked_value"),
                        fallback="delegated concept",
                    ),
                },
            },
            "advancement_choice": {
                "field": field,
                "milestone_id": milestone_id,
                "effective_cl": repair_target.get("effective_cl"),
                "allowed_kinds": deepcopy(repair_target.get("allowed_kinds") or []),
                "option_ids": deepcopy(option_ids),
                "choices": summaries,
            },
            "diagnostic": {
                "code": diagnostic.get("code") if isinstance(diagnostic.get("code"), str) else "",
            },
        }
        context_bytes = canonical_json(context).encode("utf-8")
        response_schema = deepcopy(repair_target.get("response_schema") or {})
        payload = {
            **context,
            "correction_contract": {
                "schema": "TianxiaFoundry.LocalProviderCorrection.v1",
                "attempt": 1,
                "request_sha256": request_sha256,
                "prior_response_sha256": prior_response_sha256,
                "return_exactly_one_json_object": True,
                "return_exactly_one_complete_response": False,
                "replace_the_prior_response_in_full": False,
                "do_not_return_a_patch_or_partial_object": False,
                "repair_target": {
                    "target_kind": "advancement_choice",
                    "field": field,
                    "milestone_id": milestone_id,
                    "effective_cl": repair_target.get("effective_cl"),
                    "allowed_kinds": deepcopy(repair_target.get("allowed_kinds") or []),
                    "option_ids": deepcopy(option_ids),
                },
                "minimal_response_shape": {"option_id": "one opaque ID from option_ids"},
                "target_scoped_merge": {
                    "server_applies_only_server_owned_option": True,
                    "retained_response_is_authoritative_for_all_other_fields": True,
                    "provider_output_may_omit_unrelated_fields": True,
                    "provider_must_return_one_small_json_object": True,
                },
            },
            "response_contract": {
                "response_format": "json_schema",
                "schema": response_schema,
                "required_fields": ["option_id"],
                "minimal_response_shape": {"option_id": "one opaque ID from option_ids"},
                "return_exactly_one_json_object": True,
                "target_scoped_merge": {
                    "server_applies_only_server_owned_option": True,
                    "retained_response_is_authoritative_for_all_other_fields": True,
                },
            },
            "instructions": [
                "Return exactly one JSON object and no markdown, commentary, or second object.",
                "Return only {\"option_id\":\"...\"} using one opaque option_id from the presented enum.",
                "Use the compact human-readable names and cues to choose the one legal source-backed resolution.",
                "Do not return the full character response, a patch, stable source IDs, or any extra field.",
                "The server merges only the selected milestone value; every other retained response field remains unchanged.",
            ],
            "authority": {
                "provider_mechanical_authority": False,
                "provider_direct_commit_allowed": False,
                "automatic_retries": 0,
            },
            "prompt_provenance": {
                "kind": "advancement_choice_option_selector",
                "context_sha256": sha256_bytes(context_bytes),
                "context_bytes": len(context_bytes),
            },
        }
        text = canonical_json(payload)
        size = len(text.encode("utf-8"))
        if size > PROVIDER_PROMPT_HARD_CAP_BYTES:
            raise FoundryError(
                "CG1_PROVIDER_CORRECTION_PROMPT_TOO_LARGE",
                "The bounded Advancement Choice correction context exceeds the local correction prompt limit.",
                details={
                    "prompt_kind": "advancement_choice_option_selector",
                    "hard_cap_bytes": PROVIDER_PROMPT_HARD_CAP_BYTES,
                    "actual_bytes": size,
                },
                status_code=413,
            )
        return text

    @staticmethod
    def _provider_method_path_correction_prompt(
        run: dict[str, Any],
        prior_response: str,
        diagnostic: dict[str, Any],
        repair_target: dict[str, Any],
        *,
        prior_response_sha256: str,
    ) -> str:
        """Build the small opaque-option prompt for a Method/Path repair.

        Method/Path correction is a bounded selector, not a request to repeat
        the character plan.  Keep the retained response out of this prompt so
        a large archived response cannot bury the five-or-fewer server-owned
        options or consume the local model's context window.
        """
        request = run.get("request") if isinstance(run, dict) else None
        request = request if isinstance(request, dict) else {}
        envelope = request.get("delegated_choice_envelope")
        envelope = envelope if isinstance(envelope, dict) else {}

        descriptive_projection = run.get("owner_descriptive_fields") if isinstance(run, dict) else None
        descriptive_projection = descriptive_projection if isinstance(descriptive_projection, dict) else {}
        delegated_context = _provider_descriptive_context(envelope)

        def first_text(*values: Any, limit: int = 512) -> str | None:
            for value in values:
                if isinstance(value, str) and value.strip():
                    return _provider_short_text(value, limit)
            return None

        resolved = descriptive_projection.get("resolved")
        resolved = resolved if isinstance(resolved, dict) else {}
        accepted = descriptive_projection.get("accepted")
        accepted = accepted if isinstance(accepted, dict) else {}
        proposed = descriptive_projection.get("proposed")
        proposed = proposed if isinstance(proposed, dict) else {}
        resolved_identity = resolved.get("identity") if isinstance(resolved.get("identity"), dict) else {}
        accepted_identity = accepted.get("identity") if isinstance(accepted.get("identity"), dict) else {}
        proposed_identity = proposed.get("identity") if isinstance(proposed.get("identity"), dict) else {}
        name_authority = delegated_context.get("identity.name") or {}
        concept_authority = delegated_context.get("concept") or {}
        character_context = {
            "name": {
                "state": name_authority.get("state") or "delegated",
                "value": first_text(
                    resolved_identity.get("name"),
                    accepted_identity.get("name"),
                    proposed_identity.get("name"),
                    name_authority.get("owner_locked_value"),
                ),
            },
            "concept": {
                "state": concept_authority.get("state") or "delegated",
                "value": first_text(
                    resolved.get("concept"),
                    accepted.get("concept"),
                    proposed.get("concept"),
                    concept_authority.get("owner_locked_value"),
                ),
            },
        }
        narrative_context: dict[str, str] = {}
        for key, value in (
            ("project_name", run.get("project_name") or request.get("working_name")),
            (
                "owner_notes",
                (request.get("revision_request") or {}).get("owner_notes")
                if isinstance(request.get("revision_request"), dict)
                else None,
            ),
        ):
            text = first_text(value, limit=512)
            if text is not None:
                narrative_context[key] = text

        choice_rows_by_slot = envelope.get("choices_by_slot")
        choice_rows_by_slot = choice_rows_by_slot if isinstance(choice_rows_by_slot, dict) else {}
        choice_summaries: dict[str, dict[str, dict[str, Any]]] = {}
        for slot_id, allowed_ids_key in (
            ("method_choice", "allowed_method_ids"),
            ("path_choice", "allowed_path_ids"),
        ):
            allowed_ids = {
                value for value in repair_target.get(allowed_ids_key) or [] if isinstance(value, str)
            }
            rows = choice_rows_by_slot.get(slot_id)
            if not allowed_ids or not isinstance(rows, list):
                continue
            summaries: dict[str, dict[str, Any]] = {}
            for row in rows:
                if not isinstance(row, dict) or row.get("id") not in allowed_ids:
                    continue
                projected = _provider_choice_projection(
                    row,
                    cue_limit=160,
                    display_limit=240,
                    include_owner=True,
                )
                choice_id = projected.get("id")
                if isinstance(choice_id, str) and choice_id not in summaries:
                    summaries[choice_id] = projected
            if summaries:
                choice_summaries[slot_id] = {
                    choice_id: summaries[choice_id]
                    for choice_id in sorted(summaries)
                }

        option_context = {
            "target_kind": "method_path",
            "selection_limits": deepcopy(repair_target.get("selection_limits") or {}),
            "repair_selection_count": deepcopy(repair_target.get("repair_selection_count") or {}),
            "existing_progression_keys": deepcopy(repair_target.get("existing_progression_keys") or []),
            "choice_summaries": choice_summaries,
            "option_ids": deepcopy(repair_target.get("option_ids") or []),
            "options": deepcopy(repair_target.get("options") or {}),
        }
        request_sha256 = request.get("request_sha256") if isinstance(request.get("request_sha256"), str) else ""
        diagnostic_context = {
            "code": diagnostic.get("code") if isinstance(diagnostic.get("code"), str) else "",
            "message": _provider_short_text(diagnostic.get("message"), 1_000),
        }
        context = {
            "schema": "TianxiaFoundry.LocalProviderMethodPathCorrection.v1",
            "prompt_kind": "method_path_option_selector",
            "binding": {
                "project_id": request.get("project_id"),
                "project_revision": request.get("project_revision"),
                "request_sha256": request_sha256,
                "prior_response_sha256": prior_response_sha256,
            },
            "character_context": character_context,
            **({"narrative_context": narrative_context} if narrative_context else {}),
            "diagnostic": diagnostic_context,
            "server_owned_option_context": option_context,
        }
        context_bytes = canonical_json(context).encode("utf-8")
        correction_contract = {
            "schema": "TianxiaFoundry.LocalProviderCorrection.v1",
            "attempt": 1,
            "request_sha256": request_sha256,
            "prior_response_sha256": prior_response_sha256,
            "validator_diagnostic": deepcopy(diagnostic),
            "return_exactly_one_json_object": True,
            "return_exactly_one_complete_response": False,
            "replace_the_prior_response_in_full": False,
            "do_not_return_a_patch_or_partial_object": False,
            "repair_target": deepcopy(repair_target),
            "minimal_response_shape": {"option_id": "one opaque ID from option_ids"},
            "target_scoped_merge": {
                "server_applies_only_server_owned_option": True,
                "retained_response_is_authoritative_for_all_other_fields": True,
                "provider_output_may_omit_unrelated_fields": True,
                "provider_must_return_one_small_json_object": True,
            },
        }
        payload = {
            **context,
            "correction_contract": correction_contract,
            "response_contract": {
                "response_format": "json_schema",
                "schema": deepcopy(repair_target.get("response_schema") or {}),
                "required_fields": ["option_id"],
                "minimal_response_shape": {"option_id": "one opaque ID from option_ids"},
                "return_exactly_one_json_object": True,
                "target_scoped_merge": {
                    "server_applies_only_server_owned_option": True,
                    "retained_response_is_authoritative_for_all_other_fields": True,
                },
            },
            "instructions": [
                "Return exactly one JSON object matching the strict response schema, with no markdown, commentary, or second object.",
                "Choose exactly one opaque option_id from the server-owned option_ids enum in server_owned_option_context based on the character context and diagnostic.",
                "Choose the coherent combination whose server-owned Method, Paths, and existing-CL progression best fit the character context.",
                "The server owns the complete Method, Path, and existing-CL progression mapping for each option; do not compose or rewrite any field yourself.",
                "The retained response is not reproduced here and remains authoritative for every field outside this target-scoped Method/Path repair.",
            ],
            "authority": {
                "provider_mechanical_authority": False,
                "provider_direct_commit_allowed": False,
                "automatic_retries": 1,
            },
            "prompt_provenance": {
                "kind": "method_path_option_selector",
                "context_sha256": sha256_bytes(context_bytes),
                "context_bytes": len(context_bytes),
            },
        }
        text = canonical_json(payload)
        size = len(text.encode("utf-8"))
        if size > PROVIDER_PROMPT_HARD_CAP_BYTES:
            raise FoundryError(
                "CG1_PROVIDER_CORRECTION_PROMPT_TOO_LARGE",
                "The bounded Method/Path correction context exceeds the local correction prompt limit.",
                details={
                    "prompt_kind": "method_path_option_selector",
                    "hard_cap_bytes": PROVIDER_PROMPT_HARD_CAP_BYTES,
                    "actual_bytes": size,
                },
                status_code=413,
            )
        return text

