    @staticmethod
    def _provider_insight_unavailable_correction_prompt(
        run: dict[str, Any],
        diagnostic: dict[str, Any],
        repair_target: dict[str, Any],
        *,
        prior_response_sha256: str,
    ) -> str:
        """Build a compact opaque-option prompt for one unavailable Insight.

        The retained response is intentionally absent.  The server-owned
        option mapping is the only allowed replacement for the exact Insight
        priority array; every other retained response field remains the
        authority during merge.
        """
        request = run.get("request") if isinstance(run, dict) else None
        request = request if isinstance(request, dict) else {}
        envelope = request.get("delegated_choice_envelope")
        envelope = envelope if isinstance(envelope, dict) else {}
