        descriptive_projection = run.get("owner_descriptive_fields") if isinstance(run, dict) else None
        descriptive_projection = descriptive_projection if isinstance(descriptive_projection, dict) else {}

        def first_text(*values: Any, limit: int = 512) -> str | None:
            for value in values:
                if isinstance(value, str) and value.strip():
                    return _provider_short_text(value, limit)
            return None

        resolved = descriptive_projection.get("resolved")
